import React, { useEffect, useState, lazy, Suspense } from 'react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { Routes, Route, Navigate, useLocation } from 'react-router-dom';
import { AppProvider } from './context/AppContext';
import { AuthProvider, useAuth } from './context/AuthContext';
import { UserProvider, useUser } from './context/UserContext';
import { PreferencesProvider, usePreferences } from './context/PreferencesContext';
import { NotificationProvider } from './context/NotificationContext';
import { useIdleTimeout } from './hooks/useIdleTimeout';
import { usePermissions } from './hooks/usePermissions';
import { MODULES } from './permissions';
import { ErrorBoundary } from './components/ErrorBoundary';
import { SkipToContent } from './components/SkipToContent';
import { LiveRegion } from './components/LiveRegion';
import Login from './components/Login';
import Layout from './components/Layout';
import { Toaster } from 'react-hot-toast';
import NotificationToast from './components/NotificationToast';

// Lazy load modules for better performance
const Dashboard = lazy(() => import('./modules/Dashboard'));
const AuditPlan = lazy(() => import('./modules/AuditPlan'));
const RiskRegister = lazy(() => import('./modules/RiskRegister'));
const AuditFindings = lazy(() => import('./modules/AuditFindings'));
const AuditEvidence = lazy(() => import('./modules/AuditEvidence'));
const UserManagement = lazy(() => import('./modules/UserManagement'));
const JobTitles = lazy(() => import('./modules/JobTitles'));
const AuditTrail = lazy(() => import('./modules/AuditTrail'));
const Notifications = lazy(() => import('./modules/Notifications'));
const Settings = lazy(() => import('./modules/Settings'));
const AuditCharter = lazy(() => import('./modules/AuditCharter'));
const AuditTasks = lazy(() => import('./modules/AuditTasks'));
const Recommendations = lazy(() => import('./modules/Recommendations'));
const DepartmentManagement = lazy(() => import('./modules/DepartmentManagement'));
const Reports = lazy(() => import('./modules/Reports'));
const IntegrityManagement = lazy(() => import('./modules/IntegrityManagement'));
const SystemLogsManagement = lazy(() => import('./modules/SystemLogsManagement'));
const ComplianceMatrix = lazy(() => import('./modules/ComplianceMatrix'));
const OrgStructure = lazy(() => import('./modules/OrgStructure'));
const CorrespondenceSystem = lazy(() => import('./modules/Correspondence/CorrespondenceSystem'));
const SystemErrorLogs = lazy(() => import('./modules/SystemErrorLogs'));
const AuditProgramLibrary = lazy(() => import('./modules/AuditProgramLibrary'));

const LoadingFallback = () => (
  <div className="flex items-center justify-center h-full min-h-[400px]">
    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[var(--color-primary)]"></div>
  </div>
);

const AppContent: React.FC = () => {
  const { user } = useUser();
  const { language } = usePreferences();
  const { isCheckingSession } = useAuth();
  const { canView } = usePermissions();
  const location = useLocation();
  const [routeAnnouncement, setRouteAnnouncement] = useState('');
  
  // Initialize idle timeout
  useIdleTimeout();

  // Announce route changes to screen readers
  useEffect(() => {
    const pageName = location.pathname.replace('/', '') || 'dashboard';
    setRouteAnnouncement(`Navigated to ${pageName}`);
  }, [location.pathname]);

  if (isCheckingSession) {
    return <LoadingFallback />;
  }

  if (!user) {
    return <Login />;
  }

  return (
    <Layout>
      <Toaster position="top-center" reverseOrder={false} />
      <NotificationToast />
      <LiveRegion message={routeAnnouncement} politeness="polite" />
      <Suspense fallback={<LoadingFallback />}>
        <Routes>
          <Route path="/" element={<Navigate to="/dashboard" replace />} />
          <Route path="/login" element={user ? <Navigate to="/dashboard" replace /> : <Login />} />
          <Route path="/dashboard" element={<Dashboard />} />
          <Route path="/charter" element={<AuditCharter />} />
          <Route path="/plan" element={<AuditPlan />} />
          <Route path="/tasks" element={<AuditTasks />} />
          <Route path="/library" element={<AuditProgramLibrary />} />
          <Route path="/findings" element={<AuditFindings />} />
          <Route path="/evidence" element={<AuditEvidence />} />
          <Route path="/recommendations" element={<Recommendations />} />
          <Route path="/risks" element={<RiskRegister />} />
          <Route path="/org-structure" element={<OrgStructure />} />
          <Route path="/cms" element={<CorrespondenceSystem language={language} />} />
          <Route path="/reports" element={<Reports />} />
          <Route path="/integrity" element={<IntegrityManagement />} />
          <Route path="/fraud" element={<Navigate to="/integrity" replace />} />
          <Route path="/coi" element={<Navigate to="/integrity" replace />} />
          <Route path="/compliance-matrix" element={<ComplianceMatrix />} />
          <Route path="/notifications" element={<Notifications />} />
          <Route path="/departments" element={<DepartmentManagement />} />
          
          {/* Permission-gated Routes */}
          <Route path="/system-logs" element={canView(MODULES.SYSTEM_LOGS) ? <SystemLogsManagement /> : <Navigate to="/dashboard" replace />} />
          <Route path="/system-errors" element={canView(MODULES.SYSTEM_LOGS) ? <Navigate to="/system-logs" replace /> : <Navigate to="/dashboard" replace />} />
          <Route path="/error-logs" element={canView(MODULES.SYSTEM_LOGS) ? <SystemErrorLogs /> : <Navigate to="/dashboard" replace />} />
          <Route path="/trail" element={canView(MODULES.SYSTEM_LOGS) ? <AuditTrail /> : <Navigate to="/dashboard" replace />} />
          <Route path="/users" element={canView(MODULES.USER_MANAGEMENT) ? <UserManagement /> : <Navigate to="/dashboard" replace />} />
          <Route path="/job-titles" element={<Navigate to="/departments" replace />} />
          
          <Route path="/settings" element={<Settings />} />
          
          {/* Fallback */}
          <Route path="*" element={<Navigate to="/dashboard" replace />} />
        </Routes>
      </Suspense>
    </Layout>
  );
};

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 5 * 60 * 1000, // 5 minutes
      retry: 1,
    },
  },
});

export default function App() {
  return (
    <ErrorBoundary>
      <SkipToContent />
      <QueryClientProvider client={queryClient}>
        {/* 
          Provider order is critical:
          UserProvider MUST wrap AuthProvider because AuthProvider calls useUser().
          Do NOT reorder these providers without updating the dependency chain.
        */}
        <UserProvider>
          <AuthProvider>
            <PreferencesProvider>
              <AppProvider>
                <NotificationProvider>
                  <AppContent />
                </NotificationProvider>
              </AppProvider>
            </PreferencesProvider>
          </AuthProvider>
        </UserProvider>
      </QueryClientProvider>
    </ErrorBoundary>
  );
}

import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useUser } from '../context/UserContext';
import { Save, Edit2 } from 'lucide-react';
import api from '../services/api';
import { UserRole } from '../constants';
import logger from '../utils/logger';

const AboutSection: React.FC = () => {
  const { user } = useUser();
  const { t } = useTranslation();
  const [settings, setSettings] = useState<any>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState<any>({});

  useEffect(() => {
    fetchSettings();
  }, []);

  const fetchSettings = async () => {
    try {
      const response = await api.get('/app-settings');
      if (response.data) {
        setSettings(response.data);
        setEditForm(response.data);
      }
    } catch (err) {
      logger.error('Operation failed', err);
    }
  };

  const handleSave = async () => {
    try {
      await api.put('/app-settings', editForm);
      setIsEditing(false);
      fetchSettings();
    } catch (err) {
      logger.error('Operation failed', err);
    }
  };

  if (!settings) return <div>{t('loadingData')}</div>;

  const fields = [
    { label: t('about.app_name'), key: 'app_name' },
    { label: t('about.app_version'), key: 'app_version' },
    { label: t('about.app_description'), key: 'app_description' },
    { label: t('about.company_name'), key: 'company_name' },
    { label: t('about.system_owner'), key: 'system_owner' },
    { label: t('about.developer_name'), key: 'developer_name' },
    { label: t('about.release_date'), key: 'release_date' },
    { label: t('about.last_update_date'), key: 'last_update_date' },
    { label: t('about.support_email'), key: 'support_email' },
    { label: t('about.support_phone'), key: 'support_phone' },
    { label: t('about.official_website'), key: 'official_website' },
    { label: t('about.copyright_notice'), key: 'copyright_notice' },
    { label: t('about.system_environment'), key: 'system_environment' },
    { label: t('about.database_type'), key: 'database_type' },
    { label: t('about.build_number'), key: 'build_number' },
    { label: t('about.app_status'), key: 'app_status' },
  ];

  return (
    <div className="glass-card p-10 space-y-8 bg-[var(--color-card)] border border-[var(--color-border-soft)]">
      <div className="flex items-center justify-between">
        <h3 className="text-xl font-bold text-[var(--color-text-main)] uppercase tracking-widest">
          {t('settings.aboutApplication')}
        </h3>
        {user?.role === UserRole.ADMIN && (
          <button 
            onClick={() => isEditing ? handleSave() : setIsEditing(true)}
            className="btn-primary flex items-center gap-2"
          >
            {isEditing ? <Save size={16} /> : <Edit2 size={16} />}
            {isEditing ? t('common.save') : t('common.edit')}
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        {fields.map((field) => (
          <div key={field.key} className="space-y-2">
            <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{field.label}</label>
            {isEditing ? (
              <input 
                className="input-field"
                value={editForm[field.key] || ''}
                onChange={e => setEditForm({...editForm, [field.key]: e.target.value})}
              />
            ) : (
              <p className="text-sm font-bold text-[var(--color-text-main)]">{settings[field.key]}</p>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default AboutSection;

// @vitest-environment jsdom
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import React from 'react';

/**
 * Component Tests - AuditPlanForm
 *
 * Tests the AuditPlanForm component rendering, form validation,
 * user interactions, and accessibility.
 */

// Mock react-hook-form
const mockRegister = vi.fn((name: string) => ({ name, onChange: vi.fn(), onBlur: vi.fn(), ref: vi.fn() }));
const mockHandleSubmit = vi.fn((fn: any) => (e: any) => { e?.preventDefault?.(); return fn({}); });
const mockReset = vi.fn();
const mockSetValue = vi.fn();
const mockWatch = vi.fn(() => '');

vi.mock('react-hook-form', () => ({
  useForm: () => ({
    register: mockRegister,
    handleSubmit: mockHandleSubmit,
    reset: mockReset,
    setValue: mockSetValue,
    watch: mockWatch,
    formState: { errors: {}, isSubmitting: false },
  }),
}));

vi.mock('@hookform/resolvers/zod', () => ({
  zodResolver: () => vi.fn(),
}));

// Mock react-i18next
vi.mock('react-i18next', () => ({
  useTranslation: () => ({
    t: (key: string) => key,
    i18n: { language: 'en', changeLanguage: vi.fn() },
  }),
}));

// Mock the api service
const mockApi = {
  get: vi.fn(),
  post: vi.fn(),
  put: vi.fn(),
};

vi.mock('../services/api', () => ({
  default: {
    get: (...args: any[]) => mockApi.get(...args),
    post: (...args: any[]) => mockApi.post(...args),
    put: (...args: any[]) => mockApi.put(...args),
  },
}));

// Mock useDepartments hook
vi.mock('../hooks/useDepartments', () => ({
  useDepartments: () => ({
    departments: [
      { id: 'dept-1', name: 'Finance' },
      { id: 'dept-2', name: 'IT' },
      { id: 'dept-3', name: 'Legal' },
    ],
  }),
}));

// Mock UI components
vi.mock('./ui/Input', () => ({
  Input: React.forwardRef((props: any, ref: any) => (
    <input {...props} ref={ref} data-testid={`input-${props.name || 'unknown'}`} />
  )),
}));

vi.mock('./ui/Select', () => ({
  Select: React.forwardRef(({ children, ...props }: any, ref: any) => (
    <select {...props} ref={ref} data-testid={`select-${props.name || 'unknown'}`}>
      {children}
    </select>
  )),
}));

vi.mock('./ui/FormField', () => ({
  FormField: ({ label, error, required, children, className }: any) => (
    <div className={className} data-testid={`field-${label}`}>
      <label>
        {label}
        {required && <span aria-hidden="true">*</span>}
      </label>
      {children}
      {error && <span role="alert">{error}</span>}
    </div>
  ),
}));

import AuditPlanForm from './AuditPlanForm';

describe('AuditPlanForm Component Tests', () => {
  const mockOnSuccess = vi.fn();
  const mockOnCancel = vi.fn();

  beforeEach(() => {
    vi.clearAllMocks();
    mockApi.get.mockResolvedValue({ data: [] });
  });

  describe('Rendering', () => {
    it('should render the form with all required fields', () => {
      render(
        <AuditPlanForm onSuccess={mockOnSuccess} onCancel={mockOnCancel} />
      );

      // Check for field labels (translation keys)
      expect(screen.getByText('plan.title')).toBeInTheDocument();
      expect(screen.getByText('plan.department')).toBeInTheDocument();
      expect(screen.getByText('plan.type')).toBeInTheDocument();
      expect(screen.getByText('plan.riskRating')).toBeInTheDocument();
      expect(screen.getByText('plan.startDate')).toBeInTheDocument();
      expect(screen.getByText('plan.endDate')).toBeInTheDocument();
      expect(screen.getByText('plan.leadAuditor')).toBeInTheDocument();
      expect(screen.getByText('plan.status')).toBeInTheDocument();
    });

    it('should render cancel and submit buttons', () => {
      render(
        <AuditPlanForm onSuccess={mockOnSuccess} onCancel={mockOnCancel} />
      );

      expect(screen.getByText('common.cancel')).toBeInTheDocument();
      expect(screen.getByText('plan.save')).toBeInTheDocument();
    });

    it('should render the program library selector for new plans', () => {
      render(
        <AuditPlanForm onSuccess={mockOnSuccess} onCancel={mockOnCancel} />
      );

      expect(screen.getByText('plan.library')).toBeInTheDocument();
    });

    it('should not render the program library selector when editing', () => {
      const initialData = {
        id: 'plan-1',
        title: 'Existing Plan',
        department: 'Finance',
        type: 'Operational',
        risk_rating: 'High',
        planned_start_date: '2025-01-01',
        planned_end_date: '2025-03-01',
        lead_auditor: 'John',
        status: 'Planned',
      };

      render(
        <AuditPlanForm
          onSuccess={mockOnSuccess}
          onCancel={mockOnCancel}
          initialData={initialData as any}
        />
      );

      expect(screen.queryByText('plan.library')).not.toBeInTheDocument();
    });
  });

  describe('User Interactions', () => {
    it('should call onCancel when cancel button is clicked', () => {
      render(
        <AuditPlanForm onSuccess={mockOnSuccess} onCancel={mockOnCancel} />
      );

      const cancelButton = screen.getByText('common.cancel');
      fireEvent.click(cancelButton);

      expect(mockOnCancel).toHaveBeenCalledTimes(1);
    });

    it('should fetch programs and auditors on mount', async () => {
      mockApi.get.mockImplementation((url: string) => {
        if (url === '/audit-programs') {
          return Promise.resolve({ data: [{ id: 'prog-1', program_title: 'Test Program', status: 'Approved', program_code: 'AP-001' }] });
        }
        if (url === '/users/list') {
          return Promise.resolve({ data: [{ id: 'user-1', name: 'Manager One', role: 'Manager' }] });
        }
        return Promise.resolve({ data: [] });
      });

      render(
        <AuditPlanForm onSuccess={mockOnSuccess} onCancel={mockOnCancel} />
      );

      await waitFor(() => {
        expect(mockApi.get).toHaveBeenCalledWith('/audit-programs');
        expect(mockApi.get).toHaveBeenCalledWith('/users/list');
      });
    });

    it('should reset form with initial data when editing', () => {
      const initialData = {
        id: 'plan-1',
        title: 'Existing Plan',
        department: 'Finance',
        type: 'Operational',
        risk_rating: 'High',
        planned_start_date: '2025-01-01',
        planned_end_date: '2025-03-01',
        lead_auditor: 'John',
        status: 'Planned',
      };

      render(
        <AuditPlanForm
          onSuccess={mockOnSuccess}
          onCancel={mockOnCancel}
          initialData={initialData as any}
        />
      );

      expect(mockReset).toHaveBeenCalled();
    });
  });

  describe('Accessibility', () => {
    it('should have required field indicators', () => {
      render(
        <AuditPlanForm onSuccess={mockOnSuccess} onCancel={mockOnCancel} />
      );

      // Required fields should have asterisk indicators
      const requiredIndicators = screen.getAllByText('*');
      expect(requiredIndicators.length).toBeGreaterThan(0);
    });

    it('should have proper form structure with labels', () => {
      const { container } = render(
        <AuditPlanForm onSuccess={mockOnSuccess} onCancel={mockOnCancel} />
      );

      // Form element should exist
      const form = container.querySelector('form');
      expect(form).toBeInTheDocument();

      // Labels should exist
      const labels = container.querySelectorAll('label');
      expect(labels.length).toBeGreaterThan(0);
    });

    it('should have submit button with disabled state during submission', () => {
      render(
        <AuditPlanForm onSuccess={mockOnSuccess} onCancel={mockOnCancel} />
      );

      const submitButton = screen.getByText('plan.save');
      expect(submitButton).toBeInTheDocument();
      // When not submitting, button should not be disabled
      expect(submitButton).not.toBeDisabled();
    });
  });
});

import React, { useState, useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { useTranslation } from 'react-i18next';
import { AuditPlan } from '../types';
import { AuditStatus, AuditType, RiskLevel, UserRole } from '../constants';
import api from '../services/api';
import { Input } from './ui/Input';
import { Select } from './ui/Select';
import { FormField } from './ui/FormField';
import { useDepartments } from '../hooks/useDepartments';
import logger from '../utils/logger';

type AuditPlanFormValues = {
  title: string;
  department: string;
  type: AuditType;
  risk_rating: RiskLevel;
  planned_start_date: string;
  planned_end_date: string;
  lead_auditor: string;
  status: AuditStatus;
  notes?: string;
  program_id?: string | number;
  year: number;
  quarter?: string;
};

interface AuditPlanFormProps {
  onSuccess: () => void;
  onCancel: () => void;
  initialData?: AuditPlan | null;
}

const AuditPlanForm: React.FC<AuditPlanFormProps> = ({ onSuccess, onCancel, initialData }) => {
  const { t } = useTranslation();
  
  const auditPlanSchema = z.object({
    title: z.string().min(1, t('plan.fieldRequired')),
    department: z.string().min(1, t('plan.fieldRequired')),
    type: z.nativeEnum(AuditType),
    risk_rating: z.nativeEnum(RiskLevel),
    planned_start_date: z.string().min(1, t('plan.fieldRequired')),
    planned_end_date: z.string().min(1, t('plan.fieldRequired')),
    lead_auditor: z.string().min(1, t('plan.fieldRequired')),
    status: z.nativeEnum(AuditStatus),
    notes: z.string().optional(),
    program_id: z.string().optional(),
    year: z.coerce.number().min(2000).max(2100),
    quarter: z.string().optional(),
  });
  
  const { departments } = useDepartments();
  const [programs, setPrograms] = useState<any[]>([]);
  const [auditors, setAuditors] = useState<any[]>([]);

  const {
    register,
    handleSubmit,
    reset,
    setValue,
    watch,
    formState: { errors, isSubmitting },
  } = useForm<AuditPlanFormValues>({
    resolver: zodResolver(auditPlanSchema) as any,
    mode: 'onBlur',
    defaultValues: {
      title: '',
      department: '',
      type: AuditType.OPERATIONAL,
      risk_rating: RiskLevel.MEDIUM,
      planned_start_date: '',
      planned_end_date: '',
      lead_auditor: '',
      status: AuditStatus.PLANNED,
      notes: '',
      year: new Date().getFullYear(),
      quarter: '',
    },
  });

  const selectedProgramId = watch('program_id');

  useEffect(() => {
    if (initialData) {
      const sanitized = { ...initialData };
      Object.keys(sanitized).forEach((key) => {
        if (sanitized[key as keyof AuditPlan] === null) {
          (sanitized as any)[key] = '';
        }
      });
      reset(sanitized as any);
    }
  }, [initialData, reset]);

  useEffect(() => {
    // Fetch programs
    api.get('/audit-programs')
      .then(res => {
        const data = Array.isArray(res.data) ? res.data : (res.data.data || []);
        setPrograms(data.filter((p: any) => p.status === 'Approved'));
      })
      .catch(() => setPrograms([]));

    // Fetch auditors (Managers)
    api.get('/users/list')
      .then(res => {
        const users = Array.isArray(res.data) ? res.data : (res.data.data || []);
        // Filter for role Manager
        setAuditors(users.filter((u: any) => u.role === UserRole.MANAGER));
      })
      .catch(() => setAuditors([]));
  }, []);

  useEffect(() => {
    if (selectedProgramId) {
      const prog = programs.find(p => String(p.id) === String(selectedProgramId));
      if (prog) {
        setValue('title', prog.program_title);
        setValue('department', prog.department);
        setValue('type', prog.audit_type as AuditType);
      }
    }
  }, [selectedProgramId, programs, setValue]);

  const onSubmit = async (data: AuditPlanFormValues) => {
    try {
      const url = initialData?.id 
        ? `/audit-plans/${initialData.id}`
        : '/audit-plans';
      
      let savedPlan;
      if (initialData?.id) {
        const res = await api.put(url, data);
        savedPlan = res.data;
      } else {
        const res = await api.post(url, data);
        savedPlan = res.data;
      }
      
      // If it's a new plan and a program was selected, import procedures
      if (!initialData?.id && data.program_id) {
        const procRes = await api.get(`/audit-procedures?program_id=${data.program_id}`);
        const procs = Array.isArray(procRes.data) ? procRes.data : (procRes.data?.data || []);
        
        if (procs.length > 0) {
          for (const proc of procs) {
            await api.post('/audit-tasks', {
              audit_id: savedPlan.id,
              procedure: `${proc.procedure_number}: ${proc.audit_step}`,
              responsible: data.lead_auditor,
              status: 'Open'
            });
          }
        }
      }
      onSuccess();
    } catch (err) {
      logger.error('Operation failed', err);
    }
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-8">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <FormField label={t('plan.title')} error={errors.title?.message} required className="md:col-span-2">
          <Input {...register('title')} />
        </FormField>

        {!initialData?.id && (
          <FormField label={t('plan.library')} error={errors.program_id?.message} className="md:col-span-2">
            <Select {...register('program_id')}>
              <option value="">{t('plan.selectProgramFromLibrary')}</option>
              {(Array.isArray(programs) ? programs : []).map(prog => (
                <option key={prog.id} value={prog.id}>{prog.program_code} - {prog.program_title}</option>
              ))}
            </Select>
            <p className="text-[10px] text-[var(--color-text-muted)] mt-2 font-bold italic">
              {t('plan.proceduresImportedAutomatically')}
            </p>
          </FormField>
        )}
        
        <FormField label={t('plan.department')} error={errors.department?.message} required>
          <Select {...register('department')}>
            <option value="">{t('plan.selectDepartment')}</option>
            {(Array.isArray(departments) ? departments : []).map(dept => (
              <option key={dept.id} value={dept.name}>{dept.name}</option>
            ))}
          </Select>
        </FormField>

        <FormField label={t('plan.type')} error={errors.type?.message} required>
          <Select {...register('type')}>
            {Object.values(AuditType).map((type) => (
              <option key={type} value={type}>{t(`plan.${type.toLowerCase()}`)}</option>
            ))}
          </Select>
        </FormField>

        <FormField label={t('plan.riskRating')} error={errors.risk_rating?.message} required>
          <Select {...register('risk_rating')}>
            {Object.values(RiskLevel).map((level) => (
              <option key={level} value={level}>{t(`plan.${level.toLowerCase()}`)}</option>
            ))}
          </Select>
        </FormField>

        <FormField label={t('plan.leadAuditor')} error={errors.lead_auditor?.message} required>
          <Select {...register('lead_auditor')}>
            <option value="">{t('plan.selectLeadAuditor')}</option>
            {auditors.map((auditor) => (
              <option key={auditor.id} value={auditor.name}>{auditor.name}</option>
            ))}
          </Select>
        </FormField>

        <FormField label={t('plan.startDate')} error={errors.planned_start_date?.message} required>
          <Input type="date" {...register('planned_start_date')} />
        </FormField>

        <FormField label={t('plan.endDate')} error={errors.planned_end_date?.message} required>
          <Input type="date" {...register('planned_end_date')} />
        </FormField>

        <FormField label={t('plan.status')} error={errors.status?.message} required>
          <Select {...register('status')}>
            {Object.values(AuditStatus).map((status) => (
              <option key={status} value={status}>{t(`plan.${status.toLowerCase()}`)}</option>
            ))}
          </Select>
        </FormField>

        <FormField label={t('plans.year')} error={errors.year?.message} required>
          <Input type="number" {...register('year')} />
        </FormField>

        <FormField label={t('plans.quarter')} error={errors.quarter?.message}>
          <Select {...register('quarter')}>
            <option value="">{t('plans.quarterOptions.Annual')}</option>
            <option value="Q1">{t('plans.quarterOptions.Q1')}</option>
            <option value="Q2">{t('plans.quarterOptions.Q2')}</option>
            <option value="Q3">{t('plans.quarterOptions.Q3')}</option>
            <option value="Q4">{t('plans.quarterOptions.Q4')}</option>
          </Select>
        </FormField>
      </div>

      <div className="flex justify-end gap-6 pt-8 border-t border-[var(--color-border-soft)] dark:border-slate-800">
        <button
          type="button"
          onClick={onCancel}
          className="px-8 py-3 text-[var(--color-text-muted)] dark:text-[var(--color-text-muted)] font-bold uppercase tracking-widest hover:bg-[var(--color-bg-main)] dark:hover:bg-slate-800 rounded-xl transition-all"
        >
          {t('common.cancel')}
        </button>
        <button
          type="submit"
          disabled={isSubmitting}
          className="btn-primary disabled:opacity-50"
        >
          {isSubmitting ? t('common.loading') : t('plan.save')}
        </button>
      </div>
    </form>
  );
};

export default AuditPlanForm;

import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { AuditTask, AuditPlan } from '../types';
import { AuditType } from '../constants';
import api from '../services/api';
import { FormField } from './ui/FormField';
import { Input } from './ui/Input';
import { Select } from './ui/Select';
import logger from '../utils/logger';
import { Users } from 'lucide-react';

interface AuditTaskFormProps {
  onSuccess: () => void;
  onCancel: () => void;
  plans: AuditPlan[];
  initialData?: AuditTask | null;
}

const AuditTaskForm: React.FC<AuditTaskFormProps> = ({ onSuccess, onCancel, plans, initialData }) => {
  const { t } = useTranslation();
  const [users, setUsers] = useState<any[]>([]);
  const [orgUnits, setOrgUnits] = useState<any[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Selected assignees (multi)
  const [selectedUsers, setSelectedUsers] = useState<string[]>([]);

  const [form, setForm] = useState({
    title: '',
    plan_id: '',
    audit_type: AuditType.OPERATIONAL,
    status: 'draft',
    audited_unit_id: '',
    planned_hours: '',
    period_from: '',
    period_to: '',
    due_date: '',
  });

  useEffect(() => {
    if (initialData) {
      setForm({
        title: initialData.title || '',
        plan_id: initialData.plan_id ? String(initialData.plan_id) : '',
        audit_type: (initialData.audit_type as AuditType) || AuditType.OPERATIONAL,
        status: initialData.status || 'draft',
        audited_unit_id: initialData.audited_unit_id || '',
        planned_hours: initialData.planned_hours ? String(initialData.planned_hours) : '',
        period_from: initialData.period_from || '',
        period_to: initialData.period_to || '',
        due_date: initialData.due_date || '',
      });
      // If initialData has assigned_to (legacy single), or assigned_users
      const assignedArr = (initialData as any).assigned_users || [];
      if (assignedArr.length > 0) {
        setSelectedUsers(assignedArr);
      } else if (initialData.assigned_to) {
        setSelectedUsers([String(initialData.assigned_to)]);
      }
    }
  }, [initialData]);

  useEffect(() => {
    api.get('/users/list')
      .then(res => setUsers(Array.isArray(res.data) ? res.data : (res.data.data || [])))
      .catch(() => setUsers([]));
    api.get('/org-entities')
      .then(res => setOrgUnits(Array.isArray(res.data) ? res.data : (res.data.data || [])))
      .catch(() => setOrgUnits([]));
  }, []);

  const toggleUser = (userId: string) => {
    setSelectedUsers(prev =>
      prev.includes(userId) ? prev.filter(id => id !== userId) : [...prev, userId]
    );
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    setForm(prev => ({ ...prev, [e.target.name]: e.target.value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    if (!form.title || !form.plan_id || !form.audit_type) {
      setError(t('plan.fieldRequired'));
      return;
    }
    setIsSubmitting(true);
    try {
      const payload: any = {
        title: form.title,
        plan_id: form.plan_id,
        audit_type: form.audit_type,
        status: form.status,
      };
      if (form.audited_unit_id) payload.audited_unit_id = form.audited_unit_id;
      if (form.planned_hours) payload.planned_hours = parseInt(form.planned_hours);
      if (form.period_from) payload.period_from = form.period_from;
      if (form.period_to) payload.period_to = form.period_to;
      if (form.due_date) payload.due_date = form.due_date;
      // Single assigned_to for backward compat (first user)
      if (selectedUsers.length > 0) payload.assigned_to = selectedUsers[0];

      const url = initialData?.id ? `/audit-tasks/${initialData.id}` : '/audit-tasks';
      let taskId: string | number | undefined;
      if (initialData?.id) {
        await api.put(url, payload);
        taskId = initialData.id;
      } else {
        const res = await api.post(url, payload);
        taskId = res.data?.id;
      }

      // Assign additional users via the assign endpoint
      if (taskId && selectedUsers.length > 1) {
        await api.post(`/audit-tasks/${taskId}/assign`, { user_ids: selectedUsers }).catch(() => {});
      }

      onSuccess();
    } catch (err: any) {
      logger.error('Operation failed', err);
      const apiError = err.response?.data?.error;
      setError(typeof apiError === 'string' ? apiError : apiError?.message || t('tasks.failedToSaveTask'));
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-8">
      {error && (
        <div className="p-4 bg-rose-50 dark:bg-rose-900/20 text-rose-600 dark:text-rose-400 rounded-xl border border-rose-100 dark:border-rose-900/30 font-bold text-sm">
          {error}
        </div>
      )}
      <div className="grid grid-cols-1 gap-8">
        {/* Title */}
        <FormField label={t('tasks.taskTitle')} required>
          <Input name="title" value={form.title} onChange={handleChange} placeholder={t('tasks.taskTitlePlaceholder')} />
        </FormField>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          {/* Plan */}
          <FormField label={t('common.auditPlan')} required>
            <Select name="plan_id" value={form.plan_id} onChange={handleChange}>
              <option value="">{t('tasks.selectAuditPlan')}</option>
              {plans.map(p => <option key={p.id} value={p.id}>{p.title}</option>)}
            </Select>
          </FormField>

          {/* Audit Type */}
          <FormField label={t('tasks.auditType')} required>
            <Select name="audit_type" value={form.audit_type} onChange={handleChange}>
              <option value={AuditType.OPERATIONAL}>{t('auditTypes.operational')}</option>
              <option value={AuditType.FINANCIAL}>{t('auditTypes.financial')}</option>
              <option value={AuditType.COMPLIANCE}>{t('auditTypes.compliance')}</option>
              <option value={AuditType.IT}>{t('auditTypes.it')}</option>
              <option value={AuditType.AML}>{t('auditTypes.aml')}</option>
              <option value={AuditType.GOVERNANCE}>{t('auditTypes.governance')}</option>
            </Select>
          </FormField>
        </div>

        {/* Multi-Assignee */}
        <FormField label={t('tasks.assignUsers') || t('tasks.assignedTo')}>
          <div className="border border-[var(--color-border-soft)] rounded-xl overflow-hidden">
            <div className="flex items-center gap-2 px-4 py-2 bg-[var(--color-bg-soft)] border-b border-[var(--color-border-soft)]">
              <Users size={16} className="text-[var(--color-primary)]" />
              <span className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">
                {selectedUsers.length > 0 ? `${selectedUsers.length} ${t('tasks.selected') || 'محدد'}` : t('tasks.selectAssignedTo')}
              </span>
            </div>
            <div className="max-h-48 overflow-y-auto custom-scrollbar">
              {users.map(u => (
                <label
                  key={u.id}
                  className={`flex items-center gap-3 px-4 py-3 cursor-pointer transition-colors hover:bg-[var(--color-primary)]/5 ${selectedUsers.includes(String(u.id)) ? 'bg-[var(--color-primary)]/10' : ''}`}
                >
                  <input
                    type="checkbox"
                    checked={selectedUsers.includes(String(u.id))}
                    onChange={() => toggleUser(String(u.id))}
                    className="w-4 h-4 accent-[var(--color-primary)]"
                  />
                  <div>
                    <p className="text-sm font-bold text-[var(--color-text-main)]">{u.name}</p>
                    <p className="text-xs text-[var(--color-text-muted)]">{u.department || u.role}</p>
                  </div>
                </label>
              ))}
            </div>
          </div>
        </FormField>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          {/* Audited Unit */}
          <FormField label={t('tasks.auditedUnit')}>
            <Select name="audited_unit_id" value={form.audited_unit_id} onChange={handleChange}>
              <option value="">{t('tasks.selectAuditedUnit')}</option>
              {orgUnits.map(u => <option key={u.id} value={u.id}>{u.name_ar || u.name_en || u.name}</option>)}
            </Select>
          </FormField>

          {/* Planned Hours */}
          <FormField label={t('tasks.plannedHours')}>
            <Input type="number" min="0" name="planned_hours" value={form.planned_hours} onChange={handleChange} placeholder="0" />
          </FormField>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          <FormField label={t('tasks.periodFrom')}>
            <Input type="date" name="period_from" value={form.period_from} onChange={handleChange} />
          </FormField>
          <FormField label={t('tasks.periodTo')}>
            <Input type="date" name="period_to" value={form.period_to} onChange={handleChange} />
          </FormField>
          <FormField label={t('tasks.dueDate')}>
            <Input type="date" name="due_date" value={form.due_date} onChange={handleChange} />
          </FormField>
        </div>

        {/* Status */}
        <FormField label={t('common.statusLabel')} required>
          <Select name="status" value={form.status} onChange={handleChange}>
            <option value="draft">{t('plan.draft')}</option>
            <option value="in_progress">{t('plan.in_progress')}</option>
            <option value="review">{t('plan.review')}</option>
            <option value="approved">{t('plan.approved')}</option>
            <option value="completed">{t('plan.completed')}</option>
          </Select>
        </FormField>
      </div>

      <div className="flex justify-end gap-6 pt-8 border-t border-[var(--color-border-soft)] dark:border-slate-800">
        <button type="button" onClick={onCancel}
          className="px-8 py-3 text-[var(--color-text-muted)] font-bold uppercase tracking-widest hover:bg-[var(--color-bg-soft)] rounded-xl transition-all">
          {t('common.cancel')}
        </button>
        <button type="submit" disabled={isSubmitting} className="btn-primary disabled:opacity-50">
          {isSubmitting ? t('common.loading') : t('common.save')}
        </button>
      </div>
    </form>
  );
};

export default AuditTaskForm;

import React from 'react';
import { useTranslation } from 'react-i18next';
import { motion } from 'motion/react';
import { CheckCircle2, Clock, AlertCircle, Edit, Trash2, Eye } from 'lucide-react';
import { AuditTask, AuditEvidence as AuditEvidenceType } from '../types';
import { useFormat } from '../services/formatService';
import { useUser } from '../context/UserContext';
import InteractiveIcon from './InteractiveIcon';
import { UserRole } from '../constants';

interface AuditTasksTableProps {
  tasks: AuditTask[];
  getPlanTitle: (planId: number | string) => string;
  getEvidence: (evidenceId?: number) => AuditEvidenceType | undefined;
  setPreviewItem: (item: AuditEvidenceType) => void;
  handleEdit: (task: AuditTask) => void;
  initiateDelete: (id: string | number) => void;
  updateStatus: (id: string | number, newStatus: string) => void;
}

const AuditTasksTable: React.FC<AuditTasksTableProps> = ({
  tasks,
  getPlanTitle,
  getEvidence,
  setPreviewItem,
  handleEdit,
  initiateDelete,
  updateStatus
}) => {
  const { t } = useTranslation();
  const { formatNumber, formatDate } = useFormat();
  const { user } = useUser();

  const userRole = user?.role as any;
  const canApprove = userRole === UserRole.MANAGER;
  const canSubmit = userRole === UserRole.INTERNAL_AUDITOR || userRole === 'Auditor';
  const canTransitionToInProgress = canSubmit || canApprove;

  return (
    <div className="overflow-x-auto custom-scrollbar">
      <table className="w-full text-start border-collapse">
        <thead>
          <tr className="bg-[var(--color-bg-soft)]/50 border-b border-[var(--color-border-soft)]">
            <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('tasks.taskNo')}</th>
            <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('common.title')}</th>
            <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('common.auditPlan')}</th>
            <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('tasks.assignedTo')}</th>
            <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('common.statusLabel')}</th>
            <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-end">{t('common.actions')}</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-[var(--color-border-soft)]/50">
          {tasks.map((task, idx) => {
            const evidence = getEvidence(task.evidence_id);
            return (
            <motion.tr 
              key={task.id}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: idx * 0.05 }}
              className="hover:bg-[var(--color-primary)]/5 transition-colors group cursor-pointer"
            >
              <td className="px-6 py-4 text-xs font-bold text-[var(--color-border-strong)] tracking-widest">{task.task_number || `#${formatNumber(task.id)}`}</td>
              <td className="px-6 py-4 max-w-xs">
                <p className="text-sm font-bold text-[var(--color-text-main)] group-hover:text-[var(--color-primary)] transition-colors line-clamp-2">{task.title || task.procedure}</p>
              </td>
              <td className="px-6 py-4 text-sm font-bold text-[var(--color-text-muted)]">{getPlanTitle(task.plan_id || task.audit_id as any)}</td>
              <td className="px-6 py-4">
                {(task as any).assigned_name ? (
                  <span className="bg-[var(--color-bg-main)] text-[var(--color-text-muted)] px-2 py-1 rounded-md text-xs font-bold whitespace-nowrap">
                    {(task as any).assigned_name}
                  </span>
                ) : task.assigned_to || task.responsible ? (
                  <span className="bg-[var(--color-bg-main)] text-[var(--color-text-muted)] px-2 py-1 rounded-md text-xs font-bold whitespace-nowrap">
                    {task.assigned_to || task.responsible}
                  </span>
                ) : (
                  <span className="text-[var(--color-text-muted)] text-xs">-</span>
                )}
              </td>
              <td className="px-6 py-4">
                <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest ${
                  task.status === 'completed' || task.status === 'approved' ? 'bg-[var(--color-success)]/10 text-[var(--color-success)]' :
                  task.status === 'in_progress' ? 'bg-[var(--color-info)]/10 text-[var(--color-info)]' : 
                  task.status === 'review' ? 'bg-[var(--color-warning)]/10 text-[var(--color-warning)]' :
                  'bg-[var(--color-bg-main)] text-[var(--color-text-muted)]'
                }`}>
                  {task.status === 'completed' || task.status === 'approved' ? <CheckCircle2 size={12} /> : 
                   task.status === 'in_progress' ? <Clock size={12} /> : <AlertCircle size={12} />}
                  {t(`plan.${task.status?.toLowerCase() || ''}`)}
                </span>
              </td>
              <td className="px-6 py-4 text-end">
                <div className="flex items-center justify-end gap-2">
                  {task.status === 'draft' && canTransitionToInProgress && (
                    <button onClick={(e) => { e.stopPropagation(); updateStatus(task.id!, 'in_progress'); }} className="text-[10px] uppercase font-bold text-blue-600 bg-[var(--color-primary-light)] px-2 py-1 rounded hover:bg-blue-100">
                      {t('tasks.startTask')}
                    </button>
                  )}
                  {task.status === 'in_progress' && canSubmit && (
                    <button onClick={(e) => { e.stopPropagation(); updateStatus(task.id!, 'review'); }} className="text-[10px] uppercase font-bold text-amber-600 bg-amber-50 px-2 py-1 rounded hover:bg-amber-100">
                      {t('tasks.submitForReview')}
                    </button>
                  )}
                  {task.status === 'review' && canApprove && (
                    <>
                      <button onClick={(e) => { e.stopPropagation(); updateStatus(task.id!, 'approved'); }} className="text-[10px] uppercase font-bold text-emerald-600 bg-emerald-50 px-2 py-1 rounded hover:bg-emerald-100">
                        {t('tasks.approve')}
                      </button>
                      <button onClick={(e) => { e.stopPropagation(); updateStatus(task.id!, 'in_progress'); }} className="text-[10px] uppercase font-bold text-rose-600 bg-rose-50 px-2 py-1 rounded hover:bg-rose-100">
                        {t('tasks.reject')}
                      </button>
                    </>
                  )}
                  {task.status === 'approved' && canApprove && (
                    <button onClick={(e) => { e.stopPropagation(); updateStatus(task.id!, 'completed'); }} className="text-[10px] uppercase font-bold text-emerald-600 bg-emerald-50 px-2 py-1 rounded hover:bg-emerald-100">
                      {t('tasks.complete')}
                    </button>
                  )}

                  <InteractiveIcon 
                    icon={Edit}
                    onClick={() => handleEdit(task)}
                    tooltip={t('common.edit')}
                    variant="ghost"
                    size={16}
                    className="!p-2"
                  />
                  <InteractiveIcon 
                    icon={Trash2}
                    onClick={() => initiateDelete(task.id!)}
                    tooltip={t('common.delete')}
                    variant="danger"
                    size={16}
                    className="!p-2"
                  />
                </div>
              </td>
            </motion.tr>
          )})}
        </tbody>
      </table>
    </div>
  );
};

export default AuditTasksTable;

import React, { useState, useRef, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { MessageSquare, X, Send, Bot, User, Loader2, Search, ExternalLink, FileText, Scale, BookOpen } from 'lucide-react';
import { motion, AnimatePresence } from 'motion/react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';
import { useFormat } from '../services/formatService';
import logger from '../utils/logger';

interface SearchResult {
  id: string | number;
  title: string;
  type: 'policy' | 'instruction' | 'law';
  path: string;
}

interface Message {
  id: string;
  text: string;
  sender: 'user' | 'bot';
  timestamp: Date;
  results?: SearchResult[];
}

const Chatbot: React.FC = () => {
  const { t, i18n } = useTranslation();
  const { formatDateTime } = useFormat();
  const navigate = useNavigate();
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isOpen && messages.length === 0) {
      setMessages([
        {
          id: 'welcome',
          text: 'chatbot.welcomeMessage', // Store key, translate at render time
          sender: 'bot',
          timestamp: new Date()
        }
      ]);
    }
  }, [isOpen]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      text: input,
      sender: 'user',
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
      // Local search in policies, instructions, and law bank
      const [policiesRes, instructionsRes, lawBankRes] = await Promise.all([
        api.get(`/compliance?source_type=internal_policy`),
        api.get(`/compliance?source_type=cbi_instruction`),
        api.get(`/compliance?source_type=law`)
      ]);

      const searchTerm = userMsg.text.toLowerCase();

      // Extract data correctly based on response format (some might be wrapped in { data: [...] })
      const allPolicies = policiesRes.data.data || (Array.isArray(policiesRes.data) ? policiesRes.data : []);
      const allInstructions = instructionsRes.data.data || (Array.isArray(instructionsRes.data) ? instructionsRes.data : []);
      const allLaws = lawBankRes.data.data || (Array.isArray(lawBankRes.data) ? lawBankRes.data : []);

      // Local filtering
      const filteredPolicies = allPolicies.filter((p: any) => 
        p.title?.toLowerCase().includes(searchTerm) || 
        p.department?.toLowerCase().includes(searchTerm)
      );
      
      const filteredInstructions = allInstructions.filter((inst: any) => 
        inst.title?.toLowerCase().includes(searchTerm) || 
        inst.description?.toLowerCase().includes(searchTerm) ||
        inst.instruction_number?.toLowerCase().includes(searchTerm)
      );

      const filteredLaws = allLaws.filter((law: any) => 
        law.title?.toLowerCase().includes(searchTerm) || 
        law.description?.toLowerCase().includes(searchTerm) ||
        law.law_number?.toLowerCase().includes(searchTerm)
      );

      const results: SearchResult[] = [
        ...filteredPolicies.map((p: any) => ({
          id: p.id,
          title: p.title,
          type: 'policy' as const,
          path: '/compliance-matrix'
        })),
        ...filteredInstructions.map((inst: any) => ({
          id: inst.id,
          title: inst.title || inst.instruction_number,
          type: 'instruction' as const,
          path: '/compliance-matrix'
        })),
        ...filteredLaws.map((law: any) => ({
          id: law.id,
          title: law.title || law.law_number,
          type: 'law' as const,
          path: '/compliance-matrix'
        }))
      ];

      let reply = '';
      if (results.length > 0) {
        reply = 'chatbot.foundResults'; // Store key for dynamic translation
      } else {
        reply = 'chatbot.noResults';
      }

      const botMsg: Message = {
        id: (Date.now() + 1).toString(),
        text: reply,
        sender: 'bot',
        timestamp: new Date(),
        results: results.slice(0, 5) // Limit to top 5 results
      };

      setMessages(prev => [...prev, botMsg]);
    } catch (error) {
      logger.error('Search error:', error);
      const errorMsg: Message = {
        id: (Date.now() + 1).toString(),
        text: 'chatbot.errorOccurred',
        sender: 'bot',
        timestamp: new Date()
      };
      setMessages(prev => [...prev, errorMsg]);
    } finally {
      setIsLoading(false);
    }
  };

  const getResultIcon = (type: string) => {
    switch (type) {
      case 'policy': return <BookOpen size={14} />;
      case 'instruction': return <FileText size={14} />;
      case 'law': return <Scale size={14} />;
      default: return <Search size={14} />;
    }
  };

  const getResultLabel = (type: string) => {
      switch (type) {
        case 'policy': return t('internalPolicies');
        case 'instruction': return t('centralBankInstructions');
        case 'law': return t('legal.law');
        default: return t('chatbot.result');
      }
  };

  return (
    <>
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 30, scale: 0.95, filter: 'blur(10px)' }}
            animate={{ opacity: 1, y: 0, scale: 1, filter: 'blur(0px)' }}
            exit={{ opacity: 0, y: 30, scale: 0.95, filter: 'blur(10px)' }}
            className="fixed bottom-24 end-6 w-80 sm:w-[400px] h-[600px] max-h-[85vh] bg-[var(--color-card)] dark:bg-slate-900 rounded-2xl shadow-2xl border border-[var(--color-border-soft)] flex flex-col z-50 overflow-hidden backdrop-blur-xl"
          >
            {/* Header */}
            <div className="p-6 bg-[var(--color-primary)] text-white flex items-center justify-between shadow-lg shadow-[var(--color-primary)]/20">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-[var(--color-card)]/20 rounded-2xl flex items-center justify-center backdrop-blur-md border border-white/30">
                  <Search size={24} className="text-white" />
                </div>
                <div>
                  <h3 className="font-bold text-lg tracking-tight">{t('searchAssistant')}</h3>
                  <p className="text-xs text-white/70 font-bold">{t('localPolicySearch')}</p>
                </div>
              </div>
              <button 
                onClick={() => setIsOpen(false)}
                className="w-10 h-10 flex items-center justify-center hover:bg-[var(--color-card)]/20 rounded-full transition-all active:scale-90"
              >
                <X size={20} />
              </button>
            </div>

            {/* Messages */}
            <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-[var(--color-bg-main)]/30 dark:bg-slate-900/50">
              {messages.map((msg) => (
                <div 
                  key={msg.id} 
                  className={`flex flex-col gap-3 ${msg.sender === 'user' ? 'items-end' : 'items-start'}`}
                >
                  <div className={`flex gap-3 ${msg.sender === 'user' ? 'flex-row-reverse' : ''}`}>
                    <div className={`w-10 h-10 rounded-2xl flex items-center justify-center shrink-0 shadow-sm ${
                      msg.sender === 'user' ? 'bg-[var(--color-card)] text-[var(--color-primary)]' : 'bg-[var(--color-primary)] text-white'
                    }`}>
                      {msg.sender === 'user' ? <User size={18} /> : <Bot size={18} />}
                    </div>
                    <div className={`max-w-[85%] p-4 rounded-xl text-sm font-medium shadow-sm ${
                      msg.sender === 'user' 
                        ? 'bg-[var(--color-primary)] text-white rounded-tr-none' 
                        : 'bg-[var(--color-card)] dark:bg-slate-800 border border-[var(--color-border-soft)] text-[var(--color-text-main)] dark:text-white rounded-tl-none'
                    }`}>
                      <p className="whitespace-pre-wrap leading-relaxed">{msg.sender === 'bot' ? t(msg.text) : msg.text}</p>
                      <span className={`text-[10px] mt-2 block font-bold uppercase tracking-widest ${msg.sender === 'user' ? 'text-white/60' : 'text-[var(--color-text-muted)] dark:text-[var(--color-text-muted)]'}`}>
                        {formatDateTime(msg.timestamp)}
                      </span>
                    </div>
                  </div>

                  {/* Structured Results */}
                  {msg.results && msg.results.length > 0 && (
                    <div className="ms-13 space-y-3 w-full max-w-[85%]">
                      {msg.results.map((result, idx) => (
                        <motion.button
                          key={`${msg.id}-res-${idx}`}
                          initial={{ opacity: 0, y: 10 }}
                          animate={{ opacity: 1, y: 0 }}
                          transition={{ delay: idx * 0.1 }}
                          onClick={() => {
                            navigate(result.path, { state: { searchTerm: input } });
