import React, { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useAppContext } from '../context/AppContext';
import { useUser } from '../context/UserContext';
import { usePreferences } from '../context/PreferencesContext';
import { useTranslation } from 'react-i18next';
import { useNavigationItems } from '../hooks/useNavigationItems';
import NotificationBell from './NotificationBell';
import StalePermissionsIndicator from './StalePermissionsIndicator';
import { motion, AnimatePresence } from 'motion/react';
import InteractiveIcon from './InteractiveIcon';
import Logo from './Logo';
import LanguageSwitcher from './LanguageSwitcher';
import Chatbot from './Chatbot';
import { useFormat } from '../services/formatService';
import { 
  LogOut,
  Globe,
  User as UserIcon,
  ChevronRight,
  ChevronLeft,
  Moon,
  Sun,
  Menu,
  X,
  PanelTopClose,
  PanelTop
} from 'lucide-react';
import { Language } from '../constants';


interface LayoutProps {
  children: React.ReactNode;
}

const Layout: React.FC<LayoutProps> = ({ children }) => {
  const { logout } = useAppContext();
  const { user } = useUser();
  const { language, setLanguage, theme, setTheme } = usePreferences();
  const { t, i18n } = useTranslation();
  const { translateName } = useFormat();
  const [isCollapsed, setIsCollapsed] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isHeaderHidden, setIsHeaderHidden] = useState(() => {
    try { return localStorage.getItem('audit_header_hidden') === 'true'; } catch { return false; }
  });
  const navigate = useNavigate();
  const location = useLocation();
  const isRTL = i18n.language === 'ar';

  const activeTab = location.pathname.substring(1) || 'dashboard';

  // Navigation items derived from ModuleRegistry with permission filtering and bilingual labels
  const menuItems = useNavigationItems();

  return (
    <div className={`flex min-h-screen bg-[var(--color-bg-main)] transition-colors duration-300 ${isRTL ? 'font-sans' : ''} ${theme === 'dark' ? 'dark' : ''}`} dir={isRTL ? 'rtl' : 'ltr'}>
      {/* Skip to main content link for keyboard users */}
      <a 
        href="#main-content" 
        className="sr-only focus:not-sr-only focus:fixed focus:top-4 focus:start-4 focus:z-[200] focus:px-6 focus:py-3 focus:bg-[var(--color-primary)] focus:text-white focus:rounded-xl focus:shadow-xl focus:font-bold focus:text-sm"
      >
        {t('common.skipToContent')}
      </a>

      {/* Sidebar Overlay for Mobile */}
      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-black/50 z-40 md:hidden" onClick={() => setIsMobileMenuOpen(false)} />
      )}

      {/* Sidebar */}
      <aside className={`${isCollapsed ? 'w-24' : 'w-72'} ${isMobileMenuOpen ? 'fixed inset-y-0 start-0 z-50' : 'hidden md:flex'} bg-[var(--color-card)] border-e border-[var(--color-border-soft)] h-screen sticky top-0 flex-col p-6 overflow-y-auto overflow-x-hidden transition-all duration-500 ease-in-out shadow-sm`} role="navigation" aria-label="Main navigation">
        <div className={`flex items-center ${isCollapsed ? 'justify-center' : 'justify-between'} mb-10 px-2`}>
          {!isCollapsed && (
            <motion.div 
              initial={{ opacity: 0, x: -10 }}
              animate={{ opacity: 1, x: 0 }}
              className="flex items-center gap-3"
            >
              <Logo size={40} className="text-[var(--color-primary)]" />
              <div className="flex flex-col gap-1">
                <h1 className="font-bold text-xl text-[var(--color-text-main)] tracking-tight leading-tight uppercase">{t('common.brandName')}</h1>
                <span className="text-[10px] font-semibold text-[var(--color-primary)] tracking-[0.15em] uppercase">{t('common.auditSystem')}</span>
              </div>
            </motion.div>
          )}
          {isCollapsed && (
            <Logo size={40} className="text-[var(--color-primary)]" />
          )}
          
          <button 
            onClick={() => setIsCollapsed(!isCollapsed)}
            className={`p-2 rounded-full hover:bg-[var(--color-bg-main)] text-[var(--color-text-muted)] transition-colors ${isCollapsed ? 'mt-4' : ''} hidden md:block`}
            aria-label={isCollapsed ? t('common.expandSidebar') : t('common.collapseSidebar')}
          >
            {isRTL ? (
              isCollapsed ? <ChevronLeft size={20} /> : <ChevronRight size={20} />
            ) : (
              isCollapsed ? <ChevronRight size={20} /> : <ChevronLeft size={20} />
            )}
          </button>
        </div>

        <nav className="flex-1 space-y-2" aria-label="Main menu">
          {menuItems.map((item) => (
            <div key={item.id} className="relative group">
              <motion.button
                whileHover={{ scale: 1.02, x: isCollapsed ? 0 : (isRTL ? -4 : 4) }}
                whileTap={{ scale: 0.98 }}
                onClick={() => {
                  navigate(item.path);
                  setIsMobileMenuOpen(false);
                }}
                aria-current={activeTab === item.id ? 'page' : undefined}
                aria-label={isCollapsed ? item.label : undefined}
                className={`w-full flex items-center ${isCollapsed ? 'justify-center' : 'gap-3 px-4'} py-3 rounded-2xl transition-all relative ${
                  activeTab === item.id 
                    ? 'bg-[var(--color-primary)] text-white shadow-md shadow-[var(--color-primary)]/20' 
                    : 'text-[var(--color-text-muted)] hover:bg-[var(--color-bg-main)] hover:text-[var(--color-primary)] font-semibold'
                }`}
              >
                <item.icon size={20} className={activeTab === item.id ? 'text-white' : ''} />
                {!isCollapsed && (
                  <motion.span 
                    initial={{ opacity: 0, width: 0 }}
                    animate={{ opacity: 1, width: 'auto' }}
                    className="font-semibold text-sm whitespace-nowrap overflow-hidden"
                  >
                    {item.label}
                  </motion.span>
                )}
                {item.badge && (
                  <span className={`absolute ${isCollapsed ? '-top-1 -end-1' : 'end-4'} w-5 h-5 bg-[var(--color-danger)] text-white text-[10px] font-bold rounded-full flex items-center justify-center border-2 border-white`}>
                    {item.badge}
                  </span>
                )}
              </motion.button>
              
              {isCollapsed && (
                <div className={`absolute start-full ms-4 top-1/2 -translate-y-1/2 px-3 py-2 bg-[var(--color-text-main)] text-[var(--color-bg-main)] text-xs font-bold rounded-lg opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity whitespace-nowrap z-50 shadow-xl`}>
                  {item.label}
                </div>
              )}
            </div>
          ))}
        </nav>

        <div className="mt-8 pt-6 border-t border-[var(--color-border-soft)]">
          <div className="relative group">
            <motion.button 
              whileHover={{ scale: 1.02, x: isCollapsed ? 0 : (isRTL ? -4 : 4) }}
              whileTap={{ scale: 0.98 }}
              onClick={logout}
              className={`w-full flex items-center ${isCollapsed ? 'justify-center' : 'gap-3 px-4'} py-3 text-[var(--color-text-muted)] hover:text-[var(--color-danger)] transition-colors font-semibold text-sm rounded-2xl hover:bg-rose-500/10`}
            >
              <LogOut size={20} />
              {!isCollapsed && <span>{t('common.logout')}</span>}
            </motion.button>
            
            {isCollapsed && (
              <div className={`absolute ${isRTL ? 'end-full me-4' : 'start-full ms-4'} top-1/2 -translate-y-1/2 px-3 py-2 bg-[var(--color-danger)] text-white text-xs font-bold rounded-lg opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity whitespace-nowrap z-50 shadow-xl`}>
                {t('common.logout')}
              </div>
            )}
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col min-w-0 h-screen">
        {/* Header */}
        <AnimatePresence>
          {!isHeaderHidden && (
            <motion.header 
              initial={{ height: 80, opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              transition={{ duration: 0.25, ease: 'easeInOut' }}
              className="h-20 bg-[var(--color-card)] border-b border-[var(--color-border-soft)] flex items-center justify-between px-4 sm:px-8 z-30 shrink-0 transition-colors duration-300 shadow-sm"
            >
              {/* Left side (Start) */}
              <div className="flex items-center gap-4">
                <button 
                  onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
                  className="md:hidden p-2 text-[var(--color-text-muted)] hover:text-[var(--color-primary)]"
                  aria-label={isMobileMenuOpen ? 'Close menu' : 'Open menu'}
                  aria-expanded={isMobileMenuOpen}
                >
                  {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
                </button>
                <h2 className="text-lg sm:text-2xl font-bold text-[var(--color-text-main)] tracking-tight">
                  {menuItems.find(m => m.id === activeTab)?.label || t('common.dashboard')}
                </h2>
              </div>

              {/* Right side (End) */}
              <div className="flex items-center gap-2 sm:gap-4">
                <StalePermissionsIndicator />
                <NotificationBell />
                
                <div className="h-8 w-px bg-[var(--color-border-soft)] mx-1 hidden sm:block"></div>
                
                <InteractiveIcon 
                  icon={Globe}
                  onClick={() => {
                    const nextLang = language === Language.EN ? Language.AR : Language.EN;
                    setLanguage(nextLang);
                    i18n.changeLanguage(nextLang);
                  }}
                  tooltip={language === 'en' ? t('common.switchToArabic') : t('common.switchToEnglish')}
                  size={20}
                  variant="ghost"
                  className="!p-2 text-[var(--color-text-muted)] hover:text-[var(--color-primary)]"
                >
                  <span className="ms-2 text-xs font-bold">{language === 'en' ? 'AR' : 'EN'}</span>
                </InteractiveIcon>

                <InteractiveIcon 
                  icon={theme === 'dark' ? Sun : Moon}
                  onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}
                  tooltip={theme === 'dark' ? t('common.lightMode') : t('common.darkMode')}
                  size={20}
                  variant="ghost"
                  className="!p-2 text-[var(--color-text-muted)] hover:text-[var(--color-primary)]"
                />

                <InteractiveIcon 
                  icon={PanelTopClose}
                  onClick={() => {
                    setIsHeaderHidden(true);
                    try { localStorage.setItem('audit_header_hidden', 'true'); } catch {}
                  }}
                  tooltip={t('common.hideHeader')}
                  size={20}
                  variant="ghost"
                  className="!p-2 text-[var(--color-text-muted)] hover:text-[var(--color-primary)]"
                />

                <div className="h-8 w-px bg-[var(--color-border-soft)] mx-1 hidden sm:block"></div>

                <div className="flex items-center gap-3 cursor-pointer hover:opacity-80 transition-opacity">
                  <div className="text-end hidden sm:block">
                    <p className="text-sm font-bold text-[var(--color-text-main)] leading-tight">{translateName(user?.name)}</p>
                    <p className="text-xs text-[var(--color-text-muted)] font-medium">{translateName(user?.job_title) || translateName(user?.role)}</p>
                  </div>
                  <div className="w-10 h-10 sm:w-11 sm:h-11 rounded-full bg-[var(--color-bg-main)] flex items-center justify-center overflow-hidden border-2 border-[var(--color-border-soft)] shadow-sm">
                    {user?.profile_picture ? (
                      <img src={user.profile_picture} alt="" className="w-full h-full object-cover" referrerPolicy="no-referrer" />
                    ) : (
                      <UserIcon size={20} className="text-[var(--color-text-muted)]" />
                    )}
                  </div>
                </div>
              </div>
            </motion.header>
          )}
        </AnimatePresence>

        {/* Show header button when hidden */}
        {isHeaderHidden && (
          <div className="flex items-center justify-between px-4 sm:px-8 py-2 bg-[var(--color-card)] border-b border-[var(--color-border-soft)] shrink-0 z-30">
            <div className="flex items-center gap-3">
              <button 
                onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
                className="md:hidden p-2 text-[var(--color-text-muted)] hover:text-[var(--color-primary)]"
              >
                <Menu size={20} />
              </button>
              <h2 className="text-sm font-bold text-[var(--color-text-main)] tracking-tight">
                {menuItems.find(m => m.id === activeTab)?.label || t('common.dashboard')}
              </h2>
            </div>
            <button
              onClick={() => {
                setIsHeaderHidden(false);
                try { localStorage.setItem('audit_header_hidden', 'false'); } catch {}
              }}
              className="p-1.5 rounded-lg text-[var(--color-text-muted)] hover:text-[var(--color-primary)] hover:bg-[var(--color-bg-soft)] transition-colors cursor-pointer"
              title={t('common.showHeader')}
            >
              <PanelTop size={18} />
            </button>
          </div>
        )}

        {/* Content Area */}
        <div id="main-content" role="main" className="flex-1 overflow-y-auto p-4 sm:p-8 custom-scrollbar bg-[var(--color-bg-main)]" tabIndex={-1}>
          <div className="max-w-7xl mx-auto w-full animate-fade-in">
            {children}
          </div>
        </div>
        {location.pathname === '/dashboard' && <Chatbot />}
      </main>
    </div>
  );

};

export default Layout;

import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import { Upload } from 'lucide-react';

interface LegalFormProps {
  onSuccess: () => void;
  onClose: () => void;
}

const LegalForm: React.FC<LegalFormProps> = ({ onSuccess, onClose }) => {
  const { token } = useAuth();
  const { t } = useTranslation();
  const [departments, setDepartments] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    title: '',
    type: '',
    authority: '',
    issue_date: '',
    description: '',
    related_risk_area: '',
    keywords: '',
    department: '',
    attachment: ''
  });

  useEffect(() => {
    if (!token) return;
    api.get('/departments')
      .then(res => {
        setDepartments(res.data);
        setLoading(false);
      })
      .catch(err => {
        setError(err.message);
        setLoading(false);
      });
  }, [token]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData({...formData, attachment: reader.result as string});
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    await api.post('/law-bank', formData);
    onSuccess();
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <input className="input-field" placeholder={t('common.title')} value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} required />
      <input className="input-field" placeholder={t('common.type')} value={formData.type} onChange={e => setFormData({...formData, type: e.target.value})} required />
      <input className="input-field" placeholder={t('legal.authority')} value={formData.authority} onChange={e => setFormData({...formData, authority: e.target.value})} required />
      <input type="date" className="input-field" value={formData.issue_date} onChange={e => setFormData({...formData, issue_date: e.target.value})} required />
      <textarea className="input-field" placeholder={t('common.description')} value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} required />
      <div className="relative">
        <input 
          type="file" 
          id="legal-file"
          className="sr-only" 
          onChange={handleFileChange} 
        />
        <label 
          htmlFor="legal-file"
          className="input-field flex items-center justify-between cursor-pointer group hover:border-[var(--color-primary)]/50 transition-all"
        >
          <span className="text-[var(--color-text-muted)] font-bold truncate flex items-center gap-2">
            <Upload size={16} className="text-[var(--color-border-strong)] group-hover:text-[var(--color-primary)] transition-colors" />
            {formData.attachment ? t('common.fileSelected') : t('common.noFileChosen')}
          </span>
          <span className="bg-[var(--color-primary)]/10 text-[var(--color-primary)] px-3 py-1 rounded-lg text-[10px] font-bold uppercase tracking-widest whitespace-nowrap">
            {t('common.chooseFile')}
          </span>
        </label>
      </div>
      {loading ? (
        <p>{t('common.loading')}</p>
      ) : error ? (
        <p className="text-red-500">{t('common.error')} {error}</p>
      ) : (
        <select className="input-field" value={formData.department} onChange={e => setFormData({...formData, department: e.target.value})} required>
          <option value="">{t('common.selectDepartment')}</option>
          {(Array.isArray(departments) ? departments : []).map(d => <option key={d.id} value={d.name}>{d.name}</option>)}
        </select>
      )}
      <input className="input-field" placeholder={t('legal.relatedRiskArea')} value={formData.related_risk_area} onChange={e => setFormData({...formData, related_risk_area: e.target.value})} required />
      <input className="input-field" placeholder={t('legal.keywords')} value={formData.keywords} onChange={e => setFormData({...formData, keywords: e.target.value})} required />
      <button type="submit" className="btn-primary w-full">{t('common.save')}</button>
    </form>
  );
};

export default LegalForm;

import React, { useState } from 'react';
import { useAppContext } from '../context/AppContext';
import { usePreferences } from '../context/PreferencesContext';
import { loginUser } from '../services/authService';
import api from '../services/api';
import { useTranslation } from 'react-i18next';
import { motion } from 'motion/react';
import { ResetStatus, Language } from '../constants';

import ChangePasswordModal from './auth/ChangePasswordModal';
import ContactAdminModal from './auth/ContactAdminModal';
import LoginIllustration from './Login/LoginIllustration';
import LoginHeader from './Login/LoginHeader';
import LoginForm from './Login/LoginForm';
import LoginFooter from './Login/LoginFooter';

const Login: React.FC = () => {
  const { login } = useAppContext();
  const { language, setLanguage } = usePreferences();
  const { t } = useTranslation();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [rememberMe, setRememberMe] = useState(false);
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [error, setError] = useState('');
  const [changeError, setChangeError] = useState('');
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);
  const [showChangeModal, setShowChangeModal] = useState(false);
  const [showContactModal, setShowContactModal] = useState(false);
  const [resetStatus, setResetStatus] = useState<ResetStatus>(ResetStatus.NONE);
  const [pendingToken, setPendingToken] = useState<string | null>(null);
  const [pendingUser, setPendingUser] = useState<any>(null);
  const [show2FA, setShow2FA] = useState(false);
  const [twoFACode, setTwoFACode] = useState('');
  const [twoFATempToken, setTwoFATempToken] = useState<string | null>(null);
  const [twoFAError, setTwoFAError] = useState('');

  React.useEffect(() => {
    try {
      const isIdleLogout = sessionStorage.getItem('idle_logout');
      if (isIdleLogout === 'true') {
        setError(t('auth.sessionExpiredIdle'));
        sessionStorage.removeItem('idle_logout');
      }
    } catch (e) {}
  }, [t]);

  const checkResetStatus = async (user: string) => {
    // Check reset status for the user
    return;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    // Don't process login if change password modal is open
    if (showChangeModal) return;
    setError('');
    setSuccess('');
    setLoading(true);

    try {
      const result = await loginUser(username, password, rememberMe);
      
      // Handle 2FA required response
      if (result && result.requires2FA) {
        setTwoFATempToken(result.tempToken);
        setShow2FA(true);
        setTwoFAError('');
        setTwoFACode('');
        setLoading(false);
        return;
      }

      if (result && result.user) {
        // Check if user needs to change password before granting access
        if (result.user.requires_password_change) {
          setError('');
          setChangeError('');
          setPendingToken(result.token);
          setPendingUser(result.user);
          setShowChangeModal(true);
          setLoading(false);
          return;
        }
        login(result.user, result.token || 'authenticated'); 
      }
    } catch (err: any) {
      const message = err.message || err.toString();
      if (message === 'Invalid credentials') {
        setError(t('auth.invalidCredentials'));
      } else if (message === 'Account suspended') {
        setError(t('auth.accountSuspended'));
      } else if (message === 'Account locked') {
        setError(t('auth.accountLocked'));
      } else {
        setError(message || t('auth.loginFailed'));
      }
    } finally {
      setLoading(false);
    }
  };

  const handle2FASubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!twoFATempToken || !twoFACode) return;
    setTwoFAError('');
    setLoading(true);

    try {
      const response = await api.post('/auth/2fa/validate', {
        tempToken: twoFATempToken,
        token: twoFACode,
      });
      const result = response.data;
      if (result && result.user) {
        login(result.user, result.token || 'authenticated');
      }
    } catch (err: any) {
      const message = err.response?.data?.error || err.message || t('auth.loginFailed');
      setTwoFAError(typeof message === 'object' ? message.message : message);
    } finally {
      setLoading(false);
    }
  };

  const handleChangeSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    e.stopPropagation();
    
    if (newPassword !== confirmPassword) {
      setChangeError(t('auth.passwordMismatch'));
      return;
    }
    if (newPassword.length < 8) {
      setChangeError(t('auth.passwordTooShort'));
      return;
    }
    if (!pendingToken) {
      setChangeError(t('auth.sessionExpired'));
      setShowChangeModal(false);
      return;
    }

    setLoading(true);
    setChangeError('');
    try {
      // Use the token from the initial login (no need to login again)
      const changeRes = await fetch('/api/auth/change-password', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${pendingToken}`
        },
        body: JSON.stringify({ newPassword })
      });
      const changeData = await changeRes.json();

      if (!changeRes.ok) {
        const errorMsg = typeof changeData.error === 'object' ? changeData.error.message : (changeData.error || '');
        throw new Error(errorMsg || 'Failed to change password');
      }

      setSuccess(t('auth.passwordChanged'));
      setShowChangeModal(false);
      login({ ...(pendingUser || {}), requires_password_change: false }, changeData.token);
    } catch (err: any) {
      const errorMessage = err.message || '';
      
      if (errorMessage.includes('same as the current password')) {
        setChangeError(t('auth.cannotUseSamePassword'));
      } else if (errorMessage.includes('used previously')) {
        setChangeError(t('auth.passwordUsedBefore'));
      } else if (errorMessage.includes('Password change required')) {
        setChangeError(t('auth.passwordChangeRequiredError'));
      } else if (errorMessage.includes('Invalid token') || errorMessage.includes('jwt expired')) {
        setChangeError(t('auth.sessionExpired'));
        // Token expired, close modal so user can login again
        setTimeout(() => setShowChangeModal(false), 2000);
      } else if (errorMessage.includes('must be at least') || errorMessage.includes('must contain')) {
        setChangeError(errorMessage);
      } else if (errorMessage && errorMessage !== 'Failed to change password') {
        setChangeError(errorMessage);
      } else {
        setChangeError(t('auth.errorChangingPassword'));
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div 
      className="min-h-screen bg-[var(--color-bg-main)] flex transition-colors duration-300 overflow-x-hidden"
      dir={language === Language.AR ? 'rtl' : 'ltr'}
    >
      {/* Left Side - Login Form (in LTR) / Right Side (in RTL) */}
      <div className="w-full lg:w-[45%] flex items-center justify-center p-6 sm:p-12 bg-[var(--color-card)] border-e border-[var(--color-border-soft)] shadow-[inset_-20px_0_50px_-15px_rgba(0,0,0,0.05)] rtl:shadow-[inset_20px_0_50px_-15px_rgba(0,0,0,0.05)]">
        <motion.div 
          initial={{ opacity: 0, x: language === Language.AR ? 20 : -20 }}
          animate={{ opacity: 1, x: 0 }}
          className="max-w-md w-full"
        >
          <LoginHeader 
            language={language} 
            setLanguage={setLanguage} 
            t={t} 
          />

          <LoginForm 
            onSubmit={handleSubmit}
            username={username}
            setUsername={setUsername}
            password={password}
            setPassword={setPassword}
            showPassword={showPassword}
            setShowPassword={setShowPassword}
            rememberMe={rememberMe}
            setRememberMe={setRememberMe}
            error={error}
            success={success}
            loading={loading}
            resetStatus={resetStatus}
            onForgotPassword={() => {}}
            onContactClick={() => setShowContactModal(true)}
            checkResetStatus={checkResetStatus}
            t={t}
          />

          <LoginFooter t={t} onContactClick={() => setShowContactModal(true)} />
        </motion.div>
      </div>

      <LoginIllustration />

      {/* 2FA Verification Modal */}
      {show2FA && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm">
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="bg-[var(--color-card)] rounded-2xl p-8 w-full max-w-sm mx-4 shadow-2xl border border-[var(--color-border-soft)]"
            dir={language === Language.AR ? 'rtl' : 'ltr'}
          >
            <h3 className="text-lg font-bold text-[var(--color-text-main)] mb-2">
              {t('auth.twoFactorTitle', 'Two-Factor Authentication')}
            </h3>
            <p className="text-sm text-[var(--color-text-muted)] mb-6">
              {t('auth.twoFactorDescription', 'Enter the 6-digit code from your authenticator app')}
            </p>
            
            {twoFAError && (
              <div className="p-3 mb-4 bg-[var(--color-danger-light)] border border-[var(--color-danger)]/20 rounded-xl text-[var(--color-danger)] text-sm" role="alert">
                {twoFAError}
              </div>
            )}

            <form onSubmit={handle2FASubmit}>
              <input
                type="text"
                inputMode="numeric"
                autoComplete="one-time-code"
                maxLength={6}
                className="w-full px-4 py-3.5 bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-xl focus:ring-2 focus:ring-[var(--color-primary)]/20 focus:border-[var(--color-primary)] outline-none transition-all font-mono text-center text-2xl tracking-[0.5em] text-[var(--color-text-main)]"
                placeholder="000000"
                value={twoFACode}
                onChange={(e) => setTwoFACode(e.target.value.replace(/\D/g, '').slice(0, 6))}
                autoFocus
              />
              <button
                type="submit"
                disabled={loading || twoFACode.length !== 6}
                className="w-full py-3.5 mt-4 bg-[var(--color-primary)] text-white rounded-xl font-bold hover:bg-[var(--color-primary-hover)] transition-all disabled:opacity-50 uppercase tracking-widest text-sm"
              >
                {loading ? '...' : t('auth.verify', 'Verify')}
              </button>
              <button
                type="button"
                onClick={() => {
                  setShow2FA(false);
                  setTwoFACode('');
                  setTwoFATempToken(null);
                  setTwoFAError('');
                }}
                className="w-full py-3 mt-2 text-[var(--color-text-muted)] hover:text-[var(--color-text-main)] font-medium transition-colors text-sm"
              >
                {t('common.cancel', 'Cancel')}
              </button>
            </form>
          </motion.div>
        </div>
      )}

      <ContactAdminModal 
        isOpen={showContactModal}
        onClose={() => setShowContactModal(false)}
        t={t}
        dir={language === Language.AR ? 'rtl' : 'ltr'}
      />

      <ChangePasswordModal
        isOpen={showChangeModal}
        onClose={() => {
          setShowChangeModal(false);
          setNewPassword('');
          setConfirmPassword('');
          setChangeError('');
        }}
        onSubmit={handleChangeSubmit}
        newPassword={newPassword}
        setNewPassword={setNewPassword}
        confirmPassword={confirmPassword}
        setConfirmPassword={setConfirmPassword}
        error={changeError}
        loading={loading}
        forced={true}
      />
    </div>
  );
};

export default Login;

