      <div className="w-16 h-px bg-[var(--color-border-soft)] mx-auto mb-4"></div>
      
      <p className="text-[10px] text-[var(--color-text-muted)] font-semibold uppercase tracking-widest">
        {t('auth.copyrightTextNew')}
      </p>
