import React from 'react';
import { motion } from 'motion/react';
import { Loader2, Check, AlertCircle } from 'lucide-react';
import { LucideIcon } from 'lucide-react';

type ButtonState = 'idle' | 'loading' | 'success' | 'error';

interface ProgressButtonProps {
  /** Current state of the button */
  state: ButtonState;
  /** Click handler */
  onClick?: () => void;
  /** Button text for idle state */
  children: React.ReactNode;
  /** Loading text (optional) */
  loadingText?: string;
  /** Success text (optional, shown briefly) */
  successText?: string;
  /** Error text (optional, shown briefly) */
  errorText?: string;
  /** Icon to show in idle state */
  icon?: LucideIcon;
  /** Button variant */
  variant?: 'primary' | 'secondary' | 'danger';
  /** Additional className */
  className?: string;
  /** Disabled state */
  disabled?: boolean;
  /** Button type */
  type?: 'button' | 'submit';
}

/**
 * Button with loading, success, and error states.
 * Provides clear feedback for async operations.
 * 
 * @example
 * const [state, setState] = useState<ButtonState>('idle');
 * 
 * const handleSave = async () => {
 *   setState('loading');
 *   try {
 *     await saveData();
 *     setState('success');
 *     setTimeout(() => setState('idle'), 2000);
 *   } catch {
 *     setState('error');
 *     setTimeout(() => setState('idle'), 3000);
 *   }
 * };
 * 
 * <ProgressButton state={state} onClick={handleSave} icon={Save}>
 *   Save Changes
 * </ProgressButton>
 */
const ProgressButton: React.FC<ProgressButtonProps> = ({
  state,
  onClick,
  children,
  loadingText,
  successText,
  errorText,
  icon: Icon,
  variant = 'primary',
  className = '',
  disabled = false,
  type = 'button',
}) => {
  const isDisabled = disabled || state === 'loading';

  const variantClasses = {
    primary: 'btn-primary',
    secondary: 'btn-secondary',
    danger: 'btn-danger',
  };

  const getContent = () => {
    switch (state) {
      case 'loading':
        return (
          <>
            <Loader2 size={18} className="animate-spin" />
            <span>{loadingText || children}</span>
          </>
        );
      case 'success':
        return (
          <>
            <motion.div
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              transition={{ type: 'spring', stiffness: 300, damping: 20 }}
            >
              <Check size={18} />
            </motion.div>
            <span>{successText || children}</span>
          </>
        );
      case 'error':
        return (
          <>
            <AlertCircle size={18} />
            <span>{errorText || children}</span>
          </>
        );
      default:
        return (
          <>
            {Icon && <Icon size={18} />}
            <span>{children}</span>
          </>
        );
    }
  };

  const stateClasses = {
    idle: '',
    loading: 'opacity-80 cursor-wait',
    success: '!bg-[var(--color-success)] !shadow-[var(--color-success)]/20',
    error: '!bg-[var(--color-danger)] !shadow-[var(--color-danger)]/20',
  };

  return (
    <button
      type={type}
      onClick={onClick}
      disabled={isDisabled}
      className={`${variantClasses[variant]} ${stateClasses[state]} ${className} disabled:opacity-50`}
    >
      {getContent()}
    </button>
  );
};

export default ProgressButton;

import React, { useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { useTranslation } from 'react-i18next';
import { Recommendation, AuditFinding } from '../types';
import { AuditStatus, RiskLevel } from '../constants';
import CommentSection from './CommentSection';
import api from '../services/api';
import { Input } from './ui/Input';
import { Select } from './ui/Select';
import { FormField } from './ui/FormField';
import logger from '../utils/logger';

const recommendationSchema = z.object({
  finding_id: z.string().min(1, 'Field is required'),
  department: z.string().min(1, 'Field is required'),
  responsible: z.string().min(1, 'Field is required'),
  due_date: z.string().min(1, 'Field is required'),
  status: z.nativeEnum(AuditStatus),
  risk_level: z.nativeEnum(RiskLevel),
});

type RecommendationFormValues = z.infer<typeof recommendationSchema>;

interface RecommendationFormProps {
  onSuccess: () => void;
  onCancel: () => void;
  findings: AuditFinding[];
  initialData?: Recommendation | null;
}

const RecommendationForm: React.FC<RecommendationFormProps> = ({ onSuccess, onCancel, findings, initialData }) => {
  const { t } = useTranslation();

  const {
    register,
    handleSubmit,
    reset,
    watch,
    formState: { errors, isSubmitting },
  } = useForm<RecommendationFormValues>({
    resolver: zodResolver(recommendationSchema) as any,
    mode: 'onBlur',
    defaultValues: {
      finding_id: findings[0]?.id ? String(findings[0].id) : '',
      department: '',
      responsible: '',
      due_date: '',
      status: AuditStatus.OPEN,
      risk_level: RiskLevel.MEDIUM,
    },
  });

  const findingId = watch('finding_id');

  useEffect(() => {
    if (initialData) {
      const sanitized = { ...initialData };
      Object.keys(sanitized).forEach((key) => {
        if (sanitized[key as keyof Recommendation] === null) {
          (sanitized as any)[key] = '';
        }
      });
      reset(sanitized as any);
    }
  }, [initialData, reset]);

  const onSubmit = async (data: RecommendationFormValues) => {
    try {
      const url = initialData?.id 
        ? `/recommendations/${initialData.id}`
        : '/recommendations';
      
      if (initialData?.id) {
        await api.put(url, data);
      } else {
        await api.post(url, data);
      }
      onSuccess();
    } catch (err) {
      logger.error('Operation failed', err);
    }
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-8">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <FormField label={t('recommendations.recommendation')} className="md:col-span-2">
          <div className="p-6 bg-emerald-50/50 dark:bg-emerald-900/10 rounded-xl border border-emerald-100 dark:border-emerald-900/30 text-sm font-bold text-emerald-900 dark:text-emerald-400 leading-relaxed shadow-sm">
            {findings.find(f => String(f.id) === String(findingId))?.recommendation || t('recommendations.noRecommendationTextFound')}
          </div>
        </FormField>

        <FormField label={t('recommendations.department')} error={errors.department?.message} required>
          <Input {...register('department')} />
        </FormField>

        <FormField label={t('recommendations.responsible')} error={errors.responsible?.message} required>
          <Input {...register('responsible')} />
        </FormField>
        
        <FormField label={t('recommendations.dueDate')} error={errors.due_date?.message} required>
          <Input type="date" {...register('due_date')} />
        </FormField>

        <FormField label={t('recommendations.status')} error={errors.status?.message} required>
          <Select {...register('status')}>
            <option value={AuditStatus.OPEN}>{t('common.open')}</option>
            <option value={AuditStatus.IN_PROGRESS}>{t('common.inProgress')}</option>
            <option value={AuditStatus.IMPLEMENTED}>{t('common.implemented')}</option>
            <option value={AuditStatus.OVERDUE}>{t('common.overdue')}</option>
          </Select>
        </FormField>

        <FormField label={t('recommendations.riskLevel')} error={errors.risk_level?.message} required>
          <Select {...register('risk_level')}>
            {Object.values(RiskLevel).map((level) => (
              <option key={level} value={level}>{t('common.' + level.toLowerCase())}</option>
            ))}
          </Select>
        </FormField>
      </div>

      {initialData?.id && (
        <CommentSection relatedType="recommendation" relatedId={initialData.id} />
      )}

      <div className="flex justify-end gap-6 pt-8 border-t border-[var(--color-border-soft)] dark:border-slate-800">
        <button
          type="button"
          onClick={onCancel}
          className="px-8 py-3 text-[var(--color-text-muted)] dark:text-[var(--color-text-muted)] font-bold uppercase tracking-widest hover:bg-[var(--color-bg-main)] dark:hover:bg-slate-800 rounded-xl transition-all"
        >
          {t('common.cancel')}
        </button>
        <button
          type="submit"
          disabled={isSubmitting}
          className="btn-primary disabled:opacity-50"
        >
          {isSubmitting ? t('common.loading') : t('recommendations.save')}
        </button>
      </div>
    </form>
  );
};

export default RecommendationForm;

import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import { Upload } from 'lucide-react';

interface RegulatoryFormProps {
  onSuccess: () => void;
  onClose: () => void;
  initialData?: any;
}

const RegulatoryForm: React.FC<RegulatoryFormProps> = ({ onSuccess, onClose, initialData }) => {
  const { token } = useAuth();
  const { t } = useTranslation();
  const [departments, setDepartments] = useState<any[]>([]);
  const [instructions, setInstructions] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    title: initialData?.title || '',
    issue_date: initialData?.issue_date || '',
    reference_number: initialData?.reference_number || '',
    category: initialData?.category || '',
    description: initialData?.description || '',
    related_department: initialData?.related_department || '',
    status: initialData?.status || 'Active',
    related_instruction_id: initialData?.related_instruction_id || '',
    attachment: initialData?.attachment || ''
  });

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData({...formData, attachment: reader.result as string});
      };
      reader.readAsDataURL(file);
    }
  };

  useEffect(() => {
    if (!token) return;
    Promise.all([
      api.get('/departments').then(res => res.data),
      api.get('/central-bank-instructions').then(res => res.data)
    ])
    .then(([depts, instrs]) => {
      setDepartments(Array.isArray(depts) ? depts : []);
      setInstructions(Array.isArray(instrs) ? instrs : []);
      setLoading(false);
    })
    .catch(err => {
      setError(err.message);
      setLoading(false);
    });
  }, [token]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const url = initialData ? `/central-bank-instructions/${initialData.id}` : '/central-bank-instructions';
    
    if (initialData) {
      await api.put(url, formData);
    } else {
      await api.post(url, formData);
    }
    onSuccess();
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <input className="input-field" placeholder={t('common.name')} value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} required />
      <input type="date" className="input-field" value={formData.issue_date} onChange={e => setFormData({...formData, issue_date: e.target.value})} required />
      <input className="input-field" placeholder={t('common.referenceNumber')} value={formData.reference_number} onChange={e => setFormData({...formData, reference_number: e.target.value})} required />
      <input className="input-field" placeholder={t('common.category')} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} required />
      <textarea className="input-field" placeholder={t('common.description')} value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} required />
      
      <select className="input-field" value={formData.status} onChange={e => setFormData({...formData, status: e.target.value})} required>
        <option value="Active">{t('common.active')}</option>
        <option value="Cancelled">{t('common.cancelled')}</option>
      </select>

      <select className="input-field" value={formData.related_instruction_id} onChange={e => setFormData({...formData, related_instruction_id: e.target.value})}>
        <option value="">{t('common.selectRelatedInstruction')}</option>
        {(Array.isArray(instructions) ? instructions : []).filter(i => i.id !== initialData?.id).map(i => (
          <option key={i.id} value={i.id}>{i.title} ({i.reference_number})</option>
        ))}
      </select>

      <div className="relative">
        <input 
          type="file" 
          id="regulatory-file"
          className="sr-only" 
          onChange={handleFileChange} 
        />
        <label 
          htmlFor="regulatory-file"
          className="input-field flex items-center justify-between cursor-pointer group hover:border-[var(--color-primary)]/50 transition-all"
        >
          <span className="text-[var(--color-text-muted)] font-bold truncate flex items-center gap-2">
            <Upload size={16} className="text-[var(--color-border-strong)] group-hover:text-[var(--color-primary)] transition-colors" />
            {formData.attachment ? t('common.fileSelected') : t('common.noFileChosen')}
          </span>
          <span className="bg-[var(--color-primary)]/10 text-[var(--color-primary)] px-3 py-1 rounded-lg text-[10px] font-bold uppercase tracking-widest whitespace-nowrap">
            {t('common.chooseFile')}
          </span>
        </label>
      </div>
      
      {loading ? (
        <p>{t('common.loading')}</p>
      ) : error ? (
        <p className="text-red-500">{t('common.error')} {error}</p>
      ) : (
        <select className="input-field" value={formData.related_department} onChange={e => setFormData({...formData, related_department: e.target.value})} required>
          <option value="">{t('common.selectDepartment')}</option>
          {(Array.isArray(departments) ? departments : []).map(d => <option key={d.id} value={d.name}>{d.name}</option>)}
        </select>
      )}
      <button type="submit" className="btn-primary w-full">{initialData ? t('common.update') : t('common.save')}</button>
    </form>
  );
};

