import React, { useId } from 'react';
import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';
import { AlertCircle } from 'lucide-react';

function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

interface FormFieldProps {
  label?: React.ReactNode;
  error?: string;
  required?: boolean;
  children: React.ReactNode;
  className?: string;
  hint?: string;
}

export const FormField: React.FC<FormFieldProps> = ({
  label,
  error,
  required,
  children,
  className,
  hint,
}) => {
  const id = useId();
  const errorId = `${id}-error`;
  const hintId = `${id}-hint`;

  return (
    <div className={cn("flex flex-col gap-2 w-full", className)}>
      {label && (
        <label className="text-sm font-semibold text-[var(--color-text-main)] px-1 flex items-center gap-1">
          {label}
          {required && <span className="text-[var(--color-danger)]" aria-hidden="true">*</span>}
        </label>
      )}
      {/* Clone children to inject aria attributes */}
      {React.Children.map(children, child => {
        if (React.isValidElement(child)) {
          return React.cloneElement(child as React.ReactElement<any>, {
            'aria-invalid': error ? true : undefined,
            'aria-describedby': error ? errorId : hint ? hintId : undefined,
            'aria-required': required || undefined,
            error: !!error,
          });
        }
        return child;
      })}
      {hint && !error && (
        <p id={hintId} className="text-xs text-[var(--color-text-muted)] px-1">
          {hint}
        </p>
      )}
      {error && (
        <p 
          id={errorId} 
          className="text-xs font-semibold text-[var(--color-danger)] px-1 flex items-center gap-1.5 animate-fade-in"
          role="alert"
        >
          <AlertCircle size={12} className="shrink-0" />
          {error}
        </p>
      )}
    </div>
  );
};

import React, { createContext, useContext, ReactNode, useEffect, useMemo, useCallback } from 'react';
import i18n from '../i18n';
import { useAuth } from './AuthContext';
import { useUser } from './UserContext';
import { usePreferences } from './PreferencesContext';
import { User } from '../types';

interface AppContextType {
  login: (user: User, token: string) => void;
  logout: () => void;
  setActiveTab: (tab: string) => void;
  fetchNotifications: () => Promise<void>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { setToken, logout: authLogout } = useAuth();
  const { setUser } = useUser();
  const { language } = usePreferences();
  
  useEffect(() => {
    i18n.changeLanguage(language);
  }, [language]);
  
  // State that remains in AppContext for orchestration
  const [, setActiveTab] = React.useState('dashboard');

  const login = useCallback((userData: User, authToken: string) => {
    setUser(userData);
    setToken(authToken);
  }, [setUser, setToken]);

  const logout = useCallback(async () => {
    authLogout();
    setUser(null);
  }, [authLogout, setUser]);

  const fetchNotifications = useCallback(async () => {}, []);

  const value = useMemo(() => ({
    login, logout, setActiveTab, fetchNotifications
  }), [login, logout, fetchNotifications]);

  // Memoize the directional wrapper to prevent re-renders of children
  // when AppProvider re-renders due to auth state changes
  const wrappedChildren = useMemo(() => (
    <div dir={language === 'ar' ? 'rtl' : 'ltr'} className={language === 'ar' ? 'font-arabic' : 'font-sans'}>
      {children}
    </div>
  ), [language, children]);

  return (
    <AppContext.Provider value={value}>
      {wrappedChildren}
    </AppContext.Provider>
  );
};

export const useAppContext = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useAppContext must be used within AppProvider');
  return context;
};

import React, { createContext, useContext, useState, useEffect, useMemo, useCallback, ReactNode } from 'react';
import api from '../services/api';
import { User } from '../types';
import { useUser } from './UserContext';
import logger from '../utils/logger';

interface AuthContextType {
  token: string | null;
  setToken: (token: string | null) => void;
  logout: () => void;
  isCheckingSession: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [token, setToken] = useState<string | null>(null);
  const [isCheckingSession, setIsCheckingSession] = useState(true);
  const { setUser } = useUser();

  const hasCheckedSession = React.useRef(false);

  useEffect(() => {
    if (!hasCheckedSession.current) {
      const checkLocalSession = async (retries = 3) => {
        if (hasCheckedSession.current && retries === 3) return;
        hasCheckedSession.current = true;
        setIsCheckingSession(true);
        try {
          const profileRes = await api.get('/profile');
          if (profileRes.data) {
            setUser(profileRes.data);
            setToken('authenticated'); 
          }
          setIsCheckingSession(false);
        } catch (err: any) {
          if (err.response?.status === 503 && retries > 0) {
            logger.warn(`Server is starting up, retrying session check in 2s... (${retries} left)`);
            setTimeout(() => checkLocalSession(retries - 1), 2000);
            return;
          }
          setUser(null);
          setToken(null);
          setIsCheckingSession(false);
        }
      };
      checkLocalSession();
    }
  }, [setUser]);

  const logout = useCallback(async () => {
    try {
      await api.post('/auth/logout');
    } catch (err) {
      logger.error('Logout failed', err);
    } finally {
      setUser(null);
      setToken(null);
    }
  }, [setUser]);

  const value = useMemo(() => ({
    token, setToken, logout, isCheckingSession
  }), [token, logout, isCheckingSession]);

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within AuthProvider');
  return context;
};

import React, { createContext, useContext, useState, useEffect, useRef, useCallback } from 'react';
import api from '../services/api';
import { Notification } from '../types';
import { useUser } from './UserContext';
import { useAuth } from './AuthContext';
import logger from '../utils/logger';

interface NotificationContextType {
  notifications: Notification[];
  unreadCount: number;
  hasMore: boolean;
  isLoading: boolean;
  fetchNotifications: (reset?: boolean) => void;
  loadMore: () => void;
  markAsRead: (id: string | number) => void;
  markAllAsRead: () => void;
  deleteNotification: (id: string | number) => void;
  /** New real-time notification that just arrived (for toast) */
  latestNotification: Notification | null;
  clearLatest: () => void;
  /** Bell should shake */
  bellShake: boolean;
}

const NotificationContext = createContext<NotificationContextType | undefined>(undefined);

export const NotificationProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { user } = useUser();
  const { isCheckingSession } = useAuth();
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [latestNotification, setLatestNotification] = useState<Notification | null>(null);
  const [bellShake, setBellShake] = useState(false);
  const wsRef = useRef<WebSocket | null>(null);
  const reconnectTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const bellShakeTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  const fetchNotifications = useCallback(async (reset = false) => {
    if (!user || isLoading) return;
    setIsLoading(true);
    try {
      const targetPage = reset ? 1 : page;
      const res = await api.get(`/notifications?page=${targetPage}&pageSize=20`);
      // API returns { data: Notification[], pagination: {...} }
      const items: Notification[] = Array.isArray(res.data) ? res.data : (res.data?.data ?? []);
      
      if (reset) {
        setNotifications(items);
        setPage(2);
      } else {
        setNotifications(prev => [...prev, ...items]);
        setPage(prev => prev + 1);
      }
      setHasMore(items.length === 20);
    } catch (err: any) {
      if (err.response?.status !== 401 && err.response?.status !== 403) {
        logger.error('Failed to fetch notifications:', err);
      }
    } finally {
      setIsLoading(false);
    }
  }, [user, page, isLoading]);

  const fetchUnreadCount = useCallback(async () => {
    if (!user) return;
    try {
      const res = await api.get('/notifications/unread-count');
      setUnreadCount(res.data?.count || 0);
    } catch { /* ignore */ }
  }, [user]);

  const loadMore = useCallback(() => {
    if (hasMore && !isLoading) {
      fetchNotifications(false);
    }
  }, [hasMore, isLoading, fetchNotifications]);

  // WebSocket connection for real-time notifications
  const connectWebSocket = useCallback(async () => {
    if (!user) return;
    try {
      // Fetch a short-lived WebSocket token from the server
      const res = await api.get('/auth/ws-token');
      const wsToken = res.data?.token;
      if (!wsToken) return;

      const protocol = window.location.protocol === 'https:' ? 'wss' : 'ws';
      const ws = new WebSocket(`${protocol}://${window.location.host}?token=${wsToken}`);

      ws.onmessage = (event) => {
        try {
          const msg = JSON.parse(event.data);
          if (msg.type === 'NEW_NOTIFICATION') {
            const newNotif: Notification = {
              ...msg.notification,
              is_read: false,
              status: 'Unread',
            };
            // Prepend to list
            setNotifications(prev => [newNotif, ...prev]);
            setUnreadCount(prev => prev + 1);
            // Trigger toast
            setLatestNotification(newNotif);
            // Trigger bell shake
            setBellShake(true);
            if (bellShakeTimeoutRef.current) clearTimeout(bellShakeTimeoutRef.current);
            bellShakeTimeoutRef.current = setTimeout(() => setBellShake(false), 1000);
            // Play sound
            playNotificationSound();
          }
        } catch { /* ignore non-JSON */ }
      };

      ws.onclose = () => {
        wsRef.current = null;
        if (user) {
          reconnectTimeoutRef.current = setTimeout(connectWebSocket, 5000);
        }
      };

      ws.onerror = () => { ws.close(); };
      wsRef.current = ws;
    } catch { /* WebSocket not available or token fetch failed */ }
  }, [user]);

  const playNotificationSound = () => {
    try {
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.frequency.setValueAtTime(880, ctx.currentTime);
      osc.frequency.setValueAtTime(660, ctx.currentTime + 0.08);
      gain.gain.setValueAtTime(0.08, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.25);
      osc.start(ctx.currentTime);
      osc.stop(ctx.currentTime + 0.25);
    } catch { /* audio not available */ }
  };

  useEffect(() => {
    if (isCheckingSession) return;
    if (user) {
      fetchNotifications(true);
      fetchUnreadCount();
      connectWebSocket();

      const handleFocus = () => { fetchUnreadCount(); };
      window.addEventListener('focus', handleFocus);
      const interval = setInterval(fetchUnreadCount, 3 * 60 * 1000);

      return () => {
        window.removeEventListener('focus', handleFocus);
        clearInterval(interval);
        if (wsRef.current) { wsRef.current.onclose = null; wsRef.current.close(); wsRef.current = null; }
        if (reconnectTimeoutRef.current) clearTimeout(reconnectTimeoutRef.current);
        if (bellShakeTimeoutRef.current) clearTimeout(bellShakeTimeoutRef.current);
      };
    } else {
      setNotifications([]);
      setUnreadCount(0);
      setPage(1);
      if (wsRef.current) { wsRef.current.onclose = null; wsRef.current.close(); wsRef.current = null; }
    }
  }, [user, isCheckingSession]);

  const markAsRead = async (id: string | number) => {
    if (!user) return;
    try {
      await api.put(`/notifications/${id}/read`);
      setNotifications(prev => prev.map(n => n.id === id ? { ...n, is_read: true, status: 'Read' } : n));
      setUnreadCount(prev => Math.max(0, prev - 1));
    } catch (err) { logger.error('Failed to mark notification as read:', err); }
  };

  const markAllAsRead = async () => {
    if (!user) return;
    try {
      await api.put('/notifications/mark-all-read');
      setNotifications(prev => prev.map(n => ({ ...n, is_read: true, status: 'Read' })));
      setUnreadCount(0);
    } catch (err) { logger.error('Failed to mark all as read:', err); }
  };

  const deleteNotification = async (id: string | number) => {
    if (!user) return;
    try {
      await api.delete(`/notifications/${id}`);
      setNotifications(prev => {
        const n = prev.find(x => x.id === id);
        if (n && !n.is_read && n.status !== 'Read') {
          setUnreadCount(c => Math.max(0, c - 1));
        }
        return prev.filter(x => x.id !== id);
      });
    } catch (err) { logger.error('Failed to dismiss notification:', err); }
  };

  const clearLatest = () => setLatestNotification(null);

  return (
    <NotificationContext.Provider value={{
      notifications, unreadCount, hasMore, isLoading,
      fetchNotifications, loadMore, markAsRead, markAllAsRead, deleteNotification,
      latestNotification, clearLatest, bellShake
    }}>
      {children}
    </NotificationContext.Provider>
  );
};

export const useNotificationContext = () => {
  const context = useContext(NotificationContext);
  if (!context) throw new Error('useNotificationContext must be used within NotificationProvider');
  return context;
};

import React, { createContext, useContext, useState, useEffect, useCallback, useMemo, useRef, ReactNode } from 'react';
import api from '../services/api';
import { Language } from '../types';
import { useTranslation } from 'react-i18next';
import logger from '../utils/logger';

interface PreferencesContextType {
  language: Language;
  theme: 'light' | 'dark';
  dashboardLayout: 'standard' | 'compact' | 'detailed';
  setLanguage: (lang: Language) => void;
  setTheme: (theme: 'light' | 'dark') => void;
  setDashboardLayout: (layout: 'standard' | 'compact' | 'detailed') => void;
}

const PreferencesContext = createContext<PreferencesContextType | undefined>(undefined);

export const PreferencesProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [language, setLanguageState] = useState<Language>(() => {
    return (localStorage.getItem('audit_lang') as Language) || Language.AR;
  });
  const [theme, setThemeState] = useState<'light' | 'dark'>(() => {
    return (localStorage.getItem('audit_theme') as 'light' | 'dark') || 'light';
  });
  const [dashboardLayout, setDashboardLayoutState] = useState<'standard' | 'compact' | 'detailed'>(() => {
    return (localStorage.getItem('audit_layout') as 'standard' | 'compact' | 'detailed') || 'standard';
  });
  const { i18n } = useTranslation();

  // Use refs for values that callbacks need for API calls.
  // This avoids subscribing to AuthContext which would couple preference
  // consumers to auth state changes.
  const languageRef = useRef(language);
  languageRef.current = language;
  const themeRef = useRef(theme);
  themeRef.current = theme;
  const dashboardLayoutRef = useRef(dashboardLayout);
  dashboardLayoutRef.current = dashboardLayout;

  useEffect(() => {
    document.documentElement.dir = language === 'ar' ? 'rtl' : 'ltr';
    document.documentElement.lang = language;
  }, [language]);

  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme]);

  const setLanguage = useCallback(async (lang: Language) => {
    setLanguageState(lang);
    i18n.changeLanguage(lang);
    try {
      localStorage.setItem('audit_lang', lang);
      localStorage.setItem('i18nextLng', lang);
    } catch (e) {}
    // Persist to server - API uses cookie-based auth, so no token check needed.
    // The request will simply fail with 401 if not authenticated (handled by api interceptor).
    try {
      await api.put('/preferences', { language: lang, theme: themeRef.current, dashboard_layout: dashboardLayoutRef.current, notifications_enabled: true });
    } catch (err) {
      // Silently fail - local state is already updated
    }
  }, [i18n]);

  const setTheme = useCallback(async (newTheme: 'light' | 'dark') => {
    setThemeState(newTheme);
    try {
      localStorage.setItem('audit_theme', newTheme);
    } catch (e) {}
    if (newTheme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    try {
      await api.put('/preferences', { language: languageRef.current, theme: newTheme, dashboard_layout: dashboardLayoutRef.current, notifications_enabled: true });
    } catch (err) {
      // Silently fail - local state is already updated
    }
  }, []);

  const setDashboardLayout = useCallback(async (layout: 'standard' | 'compact' | 'detailed') => {
    setDashboardLayoutState(layout);
    try {
      localStorage.setItem('audit_layout', layout);
    } catch (e) {}
    try {
      await api.put('/preferences', { language: languageRef.current, theme: themeRef.current, dashboard_layout: layout, notifications_enabled: true });
    } catch (err) {
      // Silently fail - local state is already updated
    }
  }, []);

  const value = useMemo(() => ({
    language, theme, dashboardLayout, setLanguage, setTheme, setDashboardLayout
  }), [language, theme, dashboardLayout, setLanguage, setTheme, setDashboardLayout]);

  return (
    <PreferencesContext.Provider value={value}>
      {children}
    </PreferencesContext.Provider>
  );
};

export const usePreferences = () => {
  const context = useContext(PreferencesContext);
  if (!context) throw new Error('usePreferences must be used within PreferencesProvider');
  return context;
};

