            <button data-testid="clear-token" onClick={() => setToken(null)}>Clear</button>
          </div>
        );
      }

      render(
        <TestWrapper>
          <NullTokenConsumer />
        </TestWrapper>
      );

      // Wait for authenticated state
      await waitFor(() => {
        expect(screen.getByTestId('token-val').textContent).toBe('authenticated');
      });

      // Clear the token
      await act(async () => {
        screen.getByTestId('clear-token').click();
      });

      expect(screen.getByTestId('token-val').textContent).toBe('null');
    });

    it('should provide stable context value references (memoized)', async () => {
      mockGet.mockRejectedValueOnce({ response: { status: 401 } });

      vi.useRealTimers();

      const renderCounts = { current: 0 };

      function RenderCounter() {
        const auth = useAuth();
        renderCounts.current += 1;
        return <span data-testid="render-count">{renderCounts.current}</span>;
      }

      render(
        <TestWrapper>
          <RenderCounter />
        </TestWrapper>
      );

      // Wait for session check to complete (token set to null, isCheckingSession set to false)
      await waitFor(() => {
        expect(screen.getByTestId('render-count')).toBeDefined();
      });

      // Allow all state updates to settle
      await act(async () => {
        await new Promise((r) => setTimeout(r, 100));
      });

      const countAfterSettle = renderCounts.current;

      // Wait again - no further renders should occur without state changes
      await act(async () => {
        await new Promise((r) => setTimeout(r, 100));
      });

      // Should not have re-rendered without state changes
      expect(renderCounts.current).toBe(countAfterSettle);
    });
  });

  describe('useAuth hook error handling', () => {
    it('should throw error when used outside AuthProvider', () => {
      function BadConsumer() {
        useAuth();
        return null;
      }

      // Suppress React error boundary console output
      const consoleSpy = vi.spyOn(console, 'error').mockImplementation(() => {});

      expect(() => {
        render(
          <UserProvider>
            <BadConsumer />
          </UserProvider>
        );
      }).toThrow('useAuth must be used within AuthProvider');

      consoleSpy.mockRestore();
    });
  });
});

// @vitest-environment jsdom
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { renderHook, act, waitFor } from '@testing-library/react';
import React from 'react';
import { createNotification } from '../../test/factories';

// ─── Mocks ───────────────────────────────────────────────────────────────────

// Mock the API module
const mockGet = vi.fn();
const mockPut = vi.fn();
const mockDelete = vi.fn();
vi.mock('../../services/api', () => ({
  default: {
    get: (...args: any[]) => mockGet(...args),
    put: (...args: any[]) => mockPut(...args),
    delete: (...args: any[]) => mockDelete(...args),
    post: vi.fn(),
    interceptors: {
      request: { use: vi.fn() },
      response: { use: vi.fn() },
    },
  },
}));

// Mock logger to suppress console output
vi.mock('../../utils/logger', () => ({
  default: {
    error: vi.fn(),
    warn: vi.fn(),
    info: vi.fn(),
  },
}));

// Track WebSocket instances for testing
let wsInstances: MockWebSocketInstance[] = [];

interface MockWebSocketInstance {
  url: string;
  readyState: number;
  onopen: ((event: any) => void) | null;
  onmessage: ((event: any) => void) | null;
  onclose: ((event: any) => void) | null;
  onerror: ((event: any) => void) | null;
  send: ReturnType<typeof vi.fn>;
  close: ReturnType<typeof vi.fn>;
}

class TestMockWebSocket implements MockWebSocketInstance {
  static CONNECTING = 0;
  static OPEN = 1;
  static CLOSING = 2;
  static CLOSED = 3;

  url: string;
  readyState: number;
  onopen: ((event: any) => void) | null = null;
  onmessage: ((event: any) => void) | null = null;
  onclose: ((event: any) => void) | null = null;
  onerror: ((event: any) => void) | null = null;
  send = vi.fn();
  close = vi.fn();

  constructor(url: string) {
    this.url = url;
    this.readyState = TestMockWebSocket.CONNECTING;
    wsInstances.push(this);
  }
}

// Override global WebSocket with our trackable version
Object.defineProperty(global, 'WebSocket', { value: TestMockWebSocket, writable: true });

// Mock UserContext
const mockUserState = { user: null as any };
vi.mock('../UserContext', () => ({
  useUser: () => mockUserState,
  UserProvider: ({ children }: { children: React.ReactNode }) => children,
}));

// Mock AuthContext
const mockAuthState = { isCheckingSession: false, token: 'test-token', setToken: vi.fn(), logout: vi.fn() };
vi.mock('../AuthContext', () => ({
  useAuth: () => mockAuthState,
  AuthProvider: ({ children }: { children: React.ReactNode }) => children,
}));

// Import after mocks are set up
import { NotificationProvider, useNotificationContext } from '../NotificationContext';

// ─── Helpers ─────────────────────────────────────────────────────────────────

function createWrapper() {
  return ({ children }: { children: React.ReactNode }) => (
    <NotificationProvider>{children}</NotificationProvider>
  );
}

// ─── Tests ───────────────────────────────────────────────────────────────────

describe('NotificationContext', () => {
  beforeEach(() => {
    wsInstances = [];
    mockUserState.user = null;
    mockAuthState.isCheckingSession = false;
    mockGet.mockReset();
    mockPut.mockReset();
