import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { useFormAutosave } from '../useFormAutosave';

describe('useFormAutosave', () => {
  // Track what's stored in our mock localStorage
  let store: Record<string, string> = {};

  beforeEach(() => {
    vi.useFakeTimers();
    store = {};

    // Override the global localStorage mock with working implementations
    (localStorage.getItem as ReturnType<typeof vi.fn>).mockImplementation(
      (key: string) => store[key] ?? null
    );
    (localStorage.setItem as ReturnType<typeof vi.fn>).mockImplementation(
      (key: string, value: string) => { store[key] = value; }
    );
    (localStorage.removeItem as ReturnType<typeof vi.fn>).mockImplementation(
      (key: string) => { delete store[key]; }
    );
    (localStorage.clear as ReturnType<typeof vi.fn>).mockImplementation(
      () => { store = {}; }
    );
  });

  afterEach(() => {
    vi.useRealTimers();
    vi.restoreAllMocks();
  });

  describe('حفظ بيانات النموذج تلقائياً في localStorage', () => {
    it('should save form data to localStorage after debounce delay', () => {
      const data = { title: 'خطة تدقيق', department: 'المالية' };

      renderHook(() =>
        useFormAutosave({ key: 'test-form', data, delay: 2000 })
      );

      // Data should not be saved immediately
      expect(store['draft_test-form']).toBeUndefined();

      // Advance past the debounce delay
      act(() => {
        vi.advanceTimersByTime(2000);
      });

      const stored = JSON.parse(store['draft_test-form']);
      expect(stored.data).toEqual(data);
      expect(stored.timestamp).toBeDefined();
    });

    it('should debounce saves when data changes rapidly', () => {
      let data = { title: 'أ' };

      const { rerender } = renderHook(
        ({ formData }) => useFormAutosave({ key: 'debounce-test', data: formData, delay: 1000 }),
        { initialProps: { formData: data } }
      );

      // Change data before debounce fires
      act(() => {
        vi.advanceTimersByTime(500);
      });

      data = { title: 'أب' };
      rerender({ formData: data });

      act(() => {
        vi.advanceTimersByTime(500);
      });

      data = { title: 'أبج' };
      rerender({ formData: data });

      // Only after the full delay from last change should it save
      act(() => {
        vi.advanceTimersByTime(1000);
      });

      const stored = JSON.parse(store['draft_debounce-test']);
      expect(stored.data).toEqual({ title: 'أبج' });
    });

    it('should not save when all values are empty', () => {
      const data = { title: '', department: null as any, notes: undefined as any };

      renderHook(() =>
        useFormAutosave({ key: 'empty-form', data, delay: 500 })
      );

      act(() => {
        vi.advanceTimersByTime(500);
      });

      expect(store['draft_empty-form']).toBeUndefined();
    });

    it('should not save when enabled is false', () => {
      const data = { title: 'بيانات مهمة' };

      renderHook(() =>
        useFormAutosave({ key: 'disabled-form', data, delay: 500, enabled: false })
      );

      act(() => {
        vi.advanceTimersByTime(500);
      });

      expect(store['draft_disabled-form']).toBeUndefined();
    });

    it('should use default delay of 2000ms when not specified', () => {
      const data = { title: 'اختبار' };

      renderHook(() =>
        useFormAutosave({ key: 'default-delay', data })
      );

      act(() => {
        vi.advanceTimersByTime(1999);
      });

      expect(store['draft_default-delay']).toBeUndefined();

      act(() => {
        vi.advanceTimersByTime(1);
      });

      expect(store['draft_default-delay']).toBeDefined();
    });

    it('should prefix storage key with "draft_"', () => {
      const data = { title: 'test' };

      renderHook(() =>
        useFormAutosave({ key: 'my-form', data, delay: 100 })
      );

      act(() => {
        vi.advanceTimersByTime(100);
      });

      expect(store['draft_my-form']).toBeDefined();
      expect(store['my-form']).toBeUndefined();
    });
  });

  describe('استعادة البيانات عند إعادة التحميل', () => {
    it('should load saved draft from localStorage', () => {
      const savedData = { title: 'مسودة محفوظة', status: 'Draft' };
      store['draft_restore-test'] = JSON.stringify({ data: savedData, timestamp: Date.now() });

      const { result } = renderHook(() =>
        useFormAutosave({ key: 'restore-test', data: { title: '', status: '' }, delay: 2000 })
      );

      const draft = result.current.loadDraft();
      expect(draft).toEqual(savedData);
    });

    it('should return null when no draft exists', () => {
      const { result } = renderHook(() =>
        useFormAutosave({ key: 'no-draft', data: { title: '' }, delay: 2000 })
      );

      const draft = result.current.loadDraft();
      expect(draft).toBeNull();
    });

    it('should return null and remove draft older than 24 hours', () => {
      const oldTimestamp = Date.now() - 25 * 60 * 60 * 1000; // 25 hours ago
      store['draft_expired-test'] = JSON.stringify({ data: { title: 'قديم' }, timestamp: oldTimestamp });

      const { result } = renderHook(() =>
        useFormAutosave({ key: 'expired-test', data: { title: '' }, delay: 2000 })
      );

      const draft = result.current.loadDraft();
      expect(draft).toBeNull();
      expect(store['draft_expired-test']).toBeUndefined();
    });

    it('should return draft that is less than 24 hours old', () => {
      const recentTimestamp = Date.now() - 23 * 60 * 60 * 1000; // 23 hours ago
      const savedData = { title: 'حديث' };
      store['draft_recent-test'] = JSON.stringify({ data: savedData, timestamp: recentTimestamp });

      const { result } = renderHook(() =>
        useFormAutosave({ key: 'recent-test', data: { title: '' }, delay: 2000 })
      );

      const draft = result.current.loadDraft();
      expect(draft).toEqual(savedData);
    });

    it('should return null for invalid JSON in localStorage', () => {
      store['draft_invalid-json'] = 'not-valid-json{{{';

      const { result } = renderHook(() =>
        useFormAutosave({ key: 'invalid-json', data: { title: '' }, delay: 2000 })
      );

      const draft = result.current.loadDraft();
      expect(draft).toBeNull();
    });

    it('hasDraft should return true when a draft exists', () => {
      store['draft_has-draft-test'] = JSON.stringify({ data: { title: 'موجود' }, timestamp: Date.now() });

      const { result } = renderHook(() =>
        useFormAutosave({ key: 'has-draft-test', data: { title: '' }, delay: 2000 })
      );

      expect(result.current.hasDraft()).toBe(true);
    });

    it('hasDraft should return false when no draft exists', () => {
      const { result } = renderHook(() =>
        useFormAutosave({ key: 'no-draft-check', data: { title: '' }, delay: 2000 })
      );

      expect(result.current.hasDraft()).toBe(false);
    });
  });

  describe('مسح البيانات بعد الإرسال الناجح', () => {
    it('should clear draft from localStorage when clearDraft is called', () => {
      store['draft_clear-test'] = JSON.stringify({ data: { title: 'مسودة' }, timestamp: Date.now() });

      const { result } = renderHook(() =>
        useFormAutosave({ key: 'clear-test', data: { title: '' }, delay: 2000 })
      );

      expect(store['draft_clear-test']).toBeDefined();

      act(() => {
        result.current.clearDraft();
      });

      expect(store['draft_clear-test']).toBeUndefined();
    });

    it('should not throw when clearing a non-existent draft', () => {
      const { result } = renderHook(() =>
        useFormAutosave({ key: 'non-existent', data: { title: '' }, delay: 2000 })
      );

      expect(() => {
        result.current.clearDraft();
      }).not.toThrow();
    });

    it('hasDraft should return false after clearDraft', () => {
      store['draft_clear-check'] = JSON.stringify({ data: { title: 'test' }, timestamp: Date.now() });

      const { result } = renderHook(() =>
        useFormAutosave({ key: 'clear-check', data: { title: '' }, delay: 2000 })
      );

      expect(result.current.hasDraft()).toBe(true);

      act(() => {
        result.current.clearDraft();
      });

      expect(result.current.hasDraft()).toBe(false);
    });

    it('loadDraft should return null after clearDraft', () => {
      store['draft_load-after-clear'] = JSON.stringify({ data: { title: 'بيانات' }, timestamp: Date.now() });

      const { result } = renderHook(() =>
        useFormAutosave({ key: 'load-after-clear', data: { title: '' }, delay: 2000 })
      );

      act(() => {
        result.current.clearDraft();
      });

      expect(result.current.loadDraft()).toBeNull();
    });
  });
});

// @vitest-environment jsdom
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { renderHook } from '@testing-library/react';
import { useIdleTimeout } from '../useIdleTimeout';

// Mock dependencies
const mockLogout = vi.fn();
const mockUser = { user: null as any };

vi.mock('../../context/UserContext', () => ({
  useUser: () => mockUser,
}));

vi.mock('../../context/AppContext', () => ({
  useAppContext: () => ({ logout: mockLogout }),
}));

vi.mock('../../services/api', () => ({
  default: {
    get: vi.fn().mockResolvedValue({ data: { session_timeout_minutes: 30 } }),
  },
}));

describe('useIdleTimeout', () => {
  beforeEach(() => {
    vi.useFakeTimers();
    mockUser.user = { id: '1', name: 'Test User', role: 'Admin' };
    mockLogout.mockClear();
    // Mock sessionStorage
    const store: Record<string, string> = {};
    vi.stubGlobal('sessionStorage', {
      getItem: (key: string) => store[key] ?? null,
      setItem: (key: string, value: string) => { store[key] = value; },
      removeItem: (key: string) => { delete store[key]; },
      clear: () => { Object.keys(store).forEach(k => delete store[k]); },
    });
  });

  afterEach(() => {
    vi.useRealTimers();
    vi.restoreAllMocks();
  });

  describe('استدعاء دالة الخمول بعد انتهاء المهلة', () => {
    it('should call logout after the default idle timeout (30 minutes)', () => {
      renderHook(() => useIdleTimeout());

      // Advance time to just before timeout - logout should not be called
      vi.advanceTimersByTime(30 * 60 * 1000 - 1);
      expect(mockLogout).not.toHaveBeenCalled();

      // Advance past the timeout
      vi.advanceTimersByTime(1);
      expect(mockLogout).toHaveBeenCalledTimes(1);
    });

    it('should set idle_logout flag in sessionStorage before logout', () => {
      renderHook(() => useIdleTimeout());

      vi.advanceTimersByTime(30 * 60 * 1000);

      expect(sessionStorage.getItem('idle_logout')).toBe('true');
      expect(mockLogout).toHaveBeenCalled();
    });

    it('should not set timeout when user is null', () => {
      mockUser.user = null;

      renderHook(() => useIdleTimeout());

      vi.advanceTimersByTime(30 * 60 * 1000);
      expect(mockLogout).not.toHaveBeenCalled();
    });

    it('should clear timeout when user becomes null', () => {
      const { rerender } = renderHook(() => useIdleTimeout());

      // Advance partially
      vi.advanceTimersByTime(10 * 60 * 1000);

      // User logs out (becomes null)
      mockUser.user = null;
      rerender();

      // Advance past original timeout
      vi.advanceTimersByTime(20 * 60 * 1000);
      expect(mockLogout).not.toHaveBeenCalled();
    });
  });

  describe('إعادة التعيين عند النشاط (mousemove, keydown)', () => {
    it('should reset the timer on mousemove event', () => {
      renderHook(() => useIdleTimeout());

      // Advance 20 minutes
      vi.advanceTimersByTime(20 * 60 * 1000);
      expect(mockLogout).not.toHaveBeenCalled();

      // Simulate mouse movement - this should reset the timer
      window.dispatchEvent(new Event('mousemove'));

      // Advance another 20 minutes (total 40 from start, but only 20 from last activity)
      vi.advanceTimersByTime(20 * 60 * 1000);
      expect(mockLogout).not.toHaveBeenCalled();

      // Advance the remaining 10 minutes to reach 30 from last activity
      vi.advanceTimersByTime(10 * 60 * 1000);
      expect(mockLogout).toHaveBeenCalledTimes(1);
    });

    it('should reset the timer on keydown event', () => {
      renderHook(() => useIdleTimeout());

      // Advance 25 minutes
      vi.advanceTimersByTime(25 * 60 * 1000);
      expect(mockLogout).not.toHaveBeenCalled();

      // Simulate keydown - this should reset the timer
      window.dispatchEvent(new Event('keydown'));

      // Advance 25 more minutes (only 25 from last activity, not yet 30)
      vi.advanceTimersByTime(25 * 60 * 1000);
      expect(mockLogout).not.toHaveBeenCalled();

      // Advance remaining 5 minutes to reach 30 from last activity
      vi.advanceTimersByTime(5 * 60 * 1000);
      expect(mockLogout).toHaveBeenCalledTimes(1);
    });

    it('should reset the timer on mousedown event', () => {
      renderHook(() => useIdleTimeout());

      // Advance 29 minutes
      vi.advanceTimersByTime(29 * 60 * 1000);
      expect(mockLogout).not.toHaveBeenCalled();

      // Simulate mousedown - resets the timer
      window.dispatchEvent(new Event('mousedown'));

      // Advance 29 minutes again (not yet 30 from last activity)
      vi.advanceTimersByTime(29 * 60 * 1000);
      expect(mockLogout).not.toHaveBeenCalled();

      // Advance 1 more minute to reach 30 from last activity
      vi.advanceTimersByTime(1 * 60 * 1000);
      expect(mockLogout).toHaveBeenCalledTimes(1);
    });

    it('should reset the timer on touchstart event', () => {
      renderHook(() => useIdleTimeout());

      // Advance 28 minutes
      vi.advanceTimersByTime(28 * 60 * 1000);
      expect(mockLogout).not.toHaveBeenCalled();

      // Simulate touchstart
      window.dispatchEvent(new Event('touchstart'));

      // Full 30 minutes from last activity
      vi.advanceTimersByTime(30 * 60 * 1000);
      expect(mockLogout).toHaveBeenCalledTimes(1);
    });

    it('should handle multiple activity events and only call logout once after final inactivity', () => {
      renderHook(() => useIdleTimeout());

      // Simulate activity every 10 minutes for 50 minutes
      for (let i = 0; i < 5; i++) {
        vi.advanceTimersByTime(10 * 60 * 1000);
        window.dispatchEvent(new Event('mousemove'));
      }

      // Should not have logged out yet
      expect(mockLogout).not.toHaveBeenCalled();

      // Now wait full 30 minutes without activity
      vi.advanceTimersByTime(30 * 60 * 1000);
      expect(mockLogout).toHaveBeenCalledTimes(1);
    });
  });

  describe('تنظيف المستمعين عند إلغاء التثبيت', () => {
    it('should remove event listeners on unmount', () => {
      const removeEventListenerSpy = vi.spyOn(window, 'removeEventListener');

      const { unmount } = renderHook(() => useIdleTimeout());
      unmount();

      // Verify that event listeners are removed for tracked events
      const removedEvents = removeEventListenerSpy.mock.calls.map(call => call[0]);
      expect(removedEvents).toContain('mousemove');
      expect(removedEvents).toContain('keydown');
      expect(removedEvents).toContain('mousedown');
      expect(removedEvents).toContain('touchstart');

      removeEventListenerSpy.mockRestore();
    });

    it('should not call logout after unmount even if timeout would have expired', () => {
      const { unmount } = renderHook(() => useIdleTimeout());

      // Advance partially
      vi.advanceTimersByTime(15 * 60 * 1000);

      // Unmount the hook
      unmount();

      // Advance past the timeout
      vi.advanceTimersByTime(20 * 60 * 1000);
      expect(mockLogout).not.toHaveBeenCalled();
    });
  });
});

// @vitest-environment jsdom
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { renderHook } from '@testing-library/react';
import { useKeyboardShortcuts } from '../useKeyboardShortcuts';

function fireKeyDown(options: KeyboardEventInit) {
  const event = new KeyboardEvent('keydown', { bubbles: true, ...options });
  document.dispatchEvent(event);
  return event;
}

describe('useKeyboardShortcuts', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('تسجيل الاختصارات واستدعاء الدوال عند الضغط', () => {
    it('should call handler when a simple key shortcut is pressed', () => {
      const handler = vi.fn();

      renderHook(() => useKeyboardShortcuts([{ key: 'escape', handler }]));

      fireKeyDown({ key: 'Escape' });

      expect(handler).toHaveBeenCalledTimes(1);
    });

    it('should call handler when ctrl+key combination is pressed', () => {
      const handler = vi.fn();

      renderHook(() => useKeyboardShortcuts([{ key: 'ctrl+n', handler }]));

      fireKeyDown({ key: 'n', ctrlKey: true });

      expect(handler).toHaveBeenCalledTimes(1);
    });

    it('should call handler when cmd+key (metaKey) combination is pressed', () => {
      const handler = vi.fn();

      renderHook(() => useKeyboardShortcuts([{ key: 'ctrl+k', handler }]));

      fireKeyDown({ key: 'k', metaKey: true });

      expect(handler).toHaveBeenCalledTimes(1);
    });

    it('should call handler when shift+key combination is pressed', () => {
      const handler = vi.fn();

      renderHook(() => useKeyboardShortcuts([{ key: 'shift+a', handler }]));

      fireKeyDown({ key: 'a', shiftKey: true });

      expect(handler).toHaveBeenCalledTimes(1);
    });

    it('should call handler when alt+key combination is pressed', () => {
      const handler = vi.fn();

      renderHook(() => useKeyboardShortcuts([{ key: 'alt+s', handler }]));

      fireKeyDown({ key: 's', altKey: true });

      expect(handler).toHaveBeenCalledTimes(1);
    });

    it('should call handler for ctrl+shift+key combination', () => {
      const handler = vi.fn();

      renderHook(() => useKeyboardShortcuts([{ key: 'ctrl+shift+p', handler }]));

      fireKeyDown({ key: 'p', ctrlKey: true, shiftKey: true });

      expect(handler).toHaveBeenCalledTimes(1);
    });

    it('should not call handler when wrong key is pressed', () => {
      const handler = vi.fn();

      renderHook(() => useKeyboardShortcuts([{ key: 'ctrl+n', handler }]));

      fireKeyDown({ key: 'k', ctrlKey: true });

      expect(handler).not.toHaveBeenCalled();
    });

    it('should not call handler when ctrl is not pressed for ctrl+key shortcut', () => {
      const handler = vi.fn();

      renderHook(() => useKeyboardShortcuts([{ key: 'ctrl+n', handler }]));

      fireKeyDown({ key: 'n' });

      expect(handler).not.toHaveBeenCalled();
    });

    it('should register multiple shortcuts and call the correct handler', () => {
      const handler1 = vi.fn();
      const handler2 = vi.fn();
      const handler3 = vi.fn();

      renderHook(() =>
        useKeyboardShortcuts([
          { key: 'ctrl+n', handler: handler1 },
          { key: 'ctrl+k', handler: handler2 },
          { key: 'escape', handler: handler3 },
        ])
      );

      fireKeyDown({ key: 'k', ctrlKey: true });

      expect(handler1).not.toHaveBeenCalled();
      expect(handler2).toHaveBeenCalledTimes(1);
      expect(handler3).not.toHaveBeenCalled();
    });

    it('should not call handler when shortcut is disabled', () => {
      const handler = vi.fn();

      renderHook(() =>
        useKeyboardShortcuts([{ key: 'ctrl+n', handler, enabled: false }])
      );

      fireKeyDown({ key: 'n', ctrlKey: true });

      expect(handler).not.toHaveBeenCalled();
    });

    it('should prevent default browser behavior by default', () => {
      const handler = vi.fn();

      renderHook(() => useKeyboardShortcuts([{ key: 'ctrl+s', handler }]));

      const event = new KeyboardEvent('keydown', {
        key: 's',
        ctrlKey: true,
        bubbles: true,
        cancelable: true,
      });
      const preventDefaultSpy = vi.spyOn(event, 'preventDefault');
      document.dispatchEvent(event);

      expect(preventDefaultSpy).toHaveBeenCalled();
    });

    it('should not prevent default when preventDefault is false', () => {
      const handler = vi.fn();

      renderHook(() =>
        useKeyboardShortcuts([{ key: 'ctrl+s', handler, preventDefault: false }])
      );

      const event = new KeyboardEvent('keydown', {
        key: 's',
        ctrlKey: true,
        bubbles: true,
        cancelable: true,
      });
      const preventDefaultSpy = vi.spyOn(event, 'preventDefault');
      document.dispatchEvent(event);

      expect(preventDefaultSpy).not.toHaveBeenCalled();
    });

    it('should not trigger shortcuts when typing in an input element (except Escape)', () => {
      const handler = vi.fn();

      renderHook(() => useKeyboardShortcuts([{ key: 'ctrl+n', handler }]));

      const input = document.createElement('input');
      document.body.appendChild(input);

      const event = new KeyboardEvent('keydown', {
        key: 'n',
        ctrlKey: true,
        bubbles: true,
      });
      Object.defineProperty(event, 'target', { value: input });
      document.dispatchEvent(event);

      expect(handler).not.toHaveBeenCalled();

      document.body.removeChild(input);
    });

    it('should allow Escape shortcut even when typing in an input element', () => {
      const handler = vi.fn();

      renderHook(() => useKeyboardShortcuts([{ key: 'escape', handler }]));

      const input = document.createElement('input');
      document.body.appendChild(input);

      const event = new KeyboardEvent('keydown', {
        key: 'Escape',
        bubbles: true,
      });
      Object.defineProperty(event, 'target', { value: input });
      document.dispatchEvent(event);

      expect(handler).toHaveBeenCalledTimes(1);

      document.body.removeChild(input);
    });

    it('should not trigger shortcuts when typing in a textarea', () => {
      const handler = vi.fn();

      renderHook(() => useKeyboardShortcuts([{ key: 'ctrl+k', handler }]));

      const textarea = document.createElement('textarea');
      document.body.appendChild(textarea);

      const event = new KeyboardEvent('keydown', {
        key: 'k',
        ctrlKey: true,
        bubbles: true,
      });
      Object.defineProperty(event, 'target', { value: textarea });
      document.dispatchEvent(event);

      expect(handler).not.toHaveBeenCalled();

      document.body.removeChild(textarea);
    });
  });

  describe('إلغاء التسجيل عند unmount', () => {
    it('should remove event listener on unmount', () => {
      const handler = vi.fn();

      const { unmount } = renderHook(() =>
        useKeyboardShortcuts([{ key: 'ctrl+n', handler }])
      );

      // Verify shortcut works before unmount
      fireKeyDown({ key: 'n', ctrlKey: true });
      expect(handler).toHaveBeenCalledTimes(1);

      // Unmount the hook
      unmount();

      // Verify shortcut no longer works after unmount
      fireKeyDown({ key: 'n', ctrlKey: true });
      expect(handler).toHaveBeenCalledTimes(1); // Still 1, not called again
    });

    it('should not interfere with other hooks after unmount', () => {
      const handler1 = vi.fn();
      const handler2 = vi.fn();

      const { unmount: unmount1 } = renderHook(() =>
        useKeyboardShortcuts([{ key: 'ctrl+a', handler: handler1 }])
      );

      renderHook(() =>
        useKeyboardShortcuts([{ key: 'ctrl+b', handler: handler2 }])
      );

      // Unmount first hook
      unmount1();

      // First shortcut should no longer work
      fireKeyDown({ key: 'a', ctrlKey: true });
      expect(handler1).not.toHaveBeenCalled();

      // Second shortcut should still work
      fireKeyDown({ key: 'b', ctrlKey: true });
      expect(handler2).toHaveBeenCalledTimes(1);
    });
  });
});

// @vitest-environment jsdom
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { useOptimisticUpdate } from '../useOptimisticUpdate';

interface TestItem {
  id: number;
  name: string;
  status: string;
}

describe('useOptimisticUpdate', () => {
  const initialItems: TestItem[] = [
    { id: 1, name: 'Item 1', status: 'draft' },
    { id: 2, name: 'Item 2', status: 'draft' },
    { id: 3, name: 'Item 3', status: 'in_progress' },
  ];

  let setItems: ReturnType<typeof vi.fn>;

  beforeEach(() => {
    setItems = vi.fn();
  });

  describe('تحديث الواجهة فوراً قبل استجابة الخادم', () => {
    it('should apply optimistic update immediately before action resolves', async () => {
      const { result } = renderHook(() => useOptimisticUpdate<TestItem>());

      let resolveAction: () => void;
      const action = new Promise<void>((resolve) => {
        resolveAction = resolve;
      });

      const optimisticUpdate = (items: TestItem[]) =>
        items.map((item) => (item.id === 1 ? { ...item, status: 'completed' } : item));

      // Start execution but don't resolve the action yet
      act(() => {
        result.current.execute(
          {
            action: () => action,
            optimisticUpdate,
            rollback: (items) => items,
          },
          initialItems,
          setItems
        );
      });

      // setItems should have been called immediately with the optimistic update
      expect(setItems).toHaveBeenCalledTimes(1);
      expect(setItems).toHaveBeenCalledWith([
        { id: 1, name: 'Item 1', status: 'completed' },
        { id: 2, name: 'Item 2', status: 'draft' },
        { id: 3, name: 'Item 3', status: 'in_progress' },
      ]);

      // isLoading should be true while action is pending
      expect(result.current.isLoading).toBe(true);

      // Now resolve the action
      await act(async () => {
        resolveAction!();
      });

      // isLoading should be false after action completes
      expect(result.current.isLoading).toBe(false);
    });

    it('should set isLoading to true during the async operation', async () => {
      const { result } = renderHook(() => useOptimisticUpdate<TestItem>());

      let resolveAction: () => void;
      const action = new Promise<void>((resolve) => {
        resolveAction = resolve;
      });

      act(() => {
        result.current.execute(
          {
            action: () => action,
            optimisticUpdate: (items) => items,
            rollback: (items) => items,
          },
          initialItems,
          setItems
        );
      });

      expect(result.current.isLoading).toBe(true);

      await act(async () => {
        resolveAction!();
      });

      expect(result.current.isLoading).toBe(false);
    });

    it('should apply the optimistic update function to the current items', async () => {
      const { result } = renderHook(() => useOptimisticUpdate<TestItem>());

      const optimisticUpdate = (items: TestItem[]) =>
        items.filter((item) => item.id !== 2);

      await act(async () => {
        await result.current.execute(
          {
            action: () => Promise.resolve(),
            optimisticUpdate,
            rollback: (items) => items,
          },
          initialItems,
          setItems
        );
      });

      // First call should be the optimistic update (removing item 2)
      expect(setItems).toHaveBeenCalledWith([
        { id: 1, name: 'Item 1', status: 'draft' },
        { id: 3, name: 'Item 3', status: 'in_progress' },
      ]);
    });
  });

  describe('التراجع (rollback) عند فشل الطلب', () => {
    it('should rollback to previous items when action fails', async () => {
      const { result } = renderHook(() => useOptimisticUpdate<TestItem>());

      const error = new Error('Server error');
      const onError = vi.fn();

      const optimisticUpdate = (items: TestItem[]) =>
        items.map((item) => (item.id === 1 ? { ...item, status: 'completed' } : item));

      await act(async () => {
        await result.current.execute(
          {
            action: () => Promise.reject(error),
            optimisticUpdate,
            rollback: (items) => items,
            onError,
          },
          initialItems,
          setItems
        );
      });

      // First call: optimistic update
      expect(setItems).toHaveBeenNthCalledWith(1, [
        { id: 1, name: 'Item 1', status: 'completed' },
        { id: 2, name: 'Item 2', status: 'draft' },
        { id: 3, name: 'Item 3', status: 'in_progress' },
      ]);

      // Second call: rollback to original items
      expect(setItems).toHaveBeenNthCalledWith(2, initialItems);
    });

    it('should call onError callback with the error when action fails', async () => {
      const { result } = renderHook(() => useOptimisticUpdate<TestItem>());

      const error = new Error('Network failure');
      const onError = vi.fn();

      await act(async () => {
        await result.current.execute(
          {
            action: () => Promise.reject(error),
            optimisticUpdate: (items) => items,
            rollback: (items) => items,
            onError,
          },
          initialItems,
          setItems
        );
      });

      expect(onError).toHaveBeenCalledTimes(1);
      expect(onError).toHaveBeenCalledWith(error);
    });

    it('should set isLoading to false after rollback', async () => {
      const { result } = renderHook(() => useOptimisticUpdate<TestItem>());

      await act(async () => {
        await result.current.execute(
          {
            action: () => Promise.reject(new Error('fail')),
            optimisticUpdate: (items) => items,
            rollback: (items) => items,
          },
          initialItems,
          setItems
        );
      });

      expect(result.current.isLoading).toBe(false);
    });

    it('should restore the exact previous state on rollback', async () => {
      const { result } = renderHook(() => useOptimisticUpdate<TestItem>());

      const complexItems: TestItem[] = [
        { id: 10, name: 'Complex A', status: 'review' },
        { id: 20, name: 'Complex B', status: 'approved' },
      ];

      await act(async () => {
        await result.current.execute(
          {
            action: () => Promise.reject(new Error('timeout')),
            optimisticUpdate: (items) =>
              items.map((item) => ({ ...item, status: 'cancelled' })),
            rollback: (items) => items,
          },
          complexItems,
          setItems
        );
      });

      // Rollback should restore the original items exactly
      expect(setItems).toHaveBeenLastCalledWith(complexItems);
    });
  });

  describe('عدم التراجع عند نجاح الطلب', () => {
    it('should not rollback when action succeeds', async () => {
      const { result } = renderHook(() => useOptimisticUpdate<TestItem>());

      const onSuccess = vi.fn();

      const optimisticUpdate = (items: TestItem[]) =>
        items.map((item) => (item.id === 2 ? { ...item, status: 'approved' } : item));

      await act(async () => {
        await result.current.execute(
          {
            action: () => Promise.resolve({ success: true }),
            optimisticUpdate,
            rollback: (items) => items,
            onSuccess,
          },
          initialItems,
          setItems
        );
      });

      // setItems should only be called once (the optimistic update), no rollback
      expect(setItems).toHaveBeenCalledTimes(1);
      expect(setItems).toHaveBeenCalledWith([
        { id: 1, name: 'Item 1', status: 'draft' },
        { id: 2, name: 'Item 2', status: 'approved' },
        { id: 3, name: 'Item 3', status: 'in_progress' },
      ]);
    });

    it('should call onSuccess callback when action succeeds', async () => {
      const { result } = renderHook(() => useOptimisticUpdate<TestItem>());

      const onSuccess = vi.fn();

      await act(async () => {
        await result.current.execute(
          {
            action: () => Promise.resolve(),
            optimisticUpdate: (items) => items,
            rollback: (items) => items,
            onSuccess,
          },
          initialItems,
          setItems
        );
      });

      expect(onSuccess).toHaveBeenCalledTimes(1);
    });

    it('should not call onError callback when action succeeds', async () => {
      const { result } = renderHook(() => useOptimisticUpdate<TestItem>());

      const onError = vi.fn();
      const onSuccess = vi.fn();

      await act(async () => {
        await result.current.execute(
          {
            action: () => Promise.resolve(),
            optimisticUpdate: (items) => items,
            rollback: (items) => items,
            onSuccess,
            onError,
          },
          initialItems,
          setItems
        );
      });

      expect(onError).not.toHaveBeenCalled();
      expect(onSuccess).toHaveBeenCalledTimes(1);
    });

    it('should set isLoading to false after successful action', async () => {
      const { result } = renderHook(() => useOptimisticUpdate<TestItem>());

      await act(async () => {
        await result.current.execute(
          {
            action: () => Promise.resolve(),
            optimisticUpdate: (items) => items,
            rollback: (items) => items,
          },
          initialItems,
          setItems
        );
      });

      expect(result.current.isLoading).toBe(false);
    });
  });
});

// @vitest-environment jsdom
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { renderHook, waitFor } from '@testing-library/react';
import fc from 'fast-check';
import { usePermissions } from '../usePermissions';
import { UserRole } from '../../constants';
import { DEFAULT_PERMISSIONS, MODULES, Module, Role } from '../../permissions';
import { PermissionAction, UserPermissionSet } from '../../permissions/types';

/**
 * Property-Based Tests for usePermissions Hook
 *
 * **Validates: Requirements 6.2, 6.5, 6.7**
 *
 * Property 11: Frontend Fallback Correctness
 * Property 12: Frontend Helper Method Equivalence
 * Property 13: Frontend Cache Validity
 */

// ─── Mocks ───────────────────────────────────────────────────────────────────

const mockUser = { user: null as any };
vi.mock('../../context/UserContext', () => ({
  useUser: () => mockUser,
}));

const mockLogout = vi.fn();
vi.mock('../../context/AppContext', () => ({
  useAppContext: () => ({ logout: mockLogout }),
}));

const mockApiGet = vi.fn();
vi.mock('../../services/api', () => ({
  default: {
    get: (...args: any[]) => mockApiGet(...args),
  },
}));

// ─── Arbitraries ─────────────────────────────────────────────────────────────

/** All non-Admin roles (Admin bypasses permission checks) */
const NON_ADMIN_ROLES = [
  UserRole.INTERNAL_AUDITOR,
  UserRole.COMPLIANCE_OFFICER,
  UserRole.RISK_OFFICER,
  UserRole.MANAGER,
  UserRole.VIEWER,
] as const;

const ALL_ROLES = [
  UserRole.ADMIN,
  UserRole.INTERNAL_AUDITOR,
  UserRole.COMPLIANCE_OFFICER,
  UserRole.RISK_OFFICER,
  UserRole.MANAGER,
  UserRole.VIEWER,
] as const;

const ALL_MODULES = Object.values(MODULES) as Module[];

const ALL_ACTIONS: PermissionAction[] = ['View', 'Create', 'Edit', 'Delete', 'Approve'];

/** Arbitrary for non-Admin roles */
const nonAdminRoleArb = fc.constantFrom(...NON_ADMIN_ROLES);

/** Arbitrary for all roles */
const allRoleArb = fc.constantFrom(...ALL_ROLES);

/** Arbitrary for module names */
const moduleArb = fc.constantFrom(...ALL_MODULES);

/** Arbitrary for permission actions */
const actionArb = fc.constantFrom(...ALL_ACTIONS);

/** Arbitrary for user IDs (numeric strings) */
const userIdArb = fc.integer({ min: 1, max: 99999 }).map(String);

// ─── Helpers ─────────────────────────────────────────────────────────────────

function buildPermissionSet(userId: string, role: string): UserPermissionSet {
  const rolePerms = DEFAULT_PERMISSIONS[role as keyof typeof DEFAULT_PERMISSIONS];
  const permissions: Record<string, PermissionAction[]> = {};
  if (rolePerms) {
    for (const [mod, actions] of Object.entries(rolePerms)) {
      permissions[mod] = [...actions] as PermissionAction[];
    }
  }
  return {
    userId,
    role,
    roleId: 'role-1',
    isCustomRole: false,
    permissions,
    overrides: [],
  };
}

// ─── Test Setup ──────────────────────────────────────────────────────────────

let store: Record<string, string> = {};

beforeEach(() => {
  mockUser.user = null;
  mockLogout.mockClear();
  mockApiGet.mockReset();
  store = {};

  (localStorage.getItem as ReturnType<typeof vi.fn>).mockImplementation(
    (key: string) => store[key] ?? null
  );
  (localStorage.setItem as ReturnType<typeof vi.fn>).mockImplementation(
    (key: string, value: string) => { store[key] = value; }
  );
  (localStorage.removeItem as ReturnType<typeof vi.fn>).mockImplementation(
    (key: string) => { delete store[key]; }
  );
  (localStorage.clear as ReturnType<typeof vi.fn>).mockImplementation(
    () => { store = {}; }
  );
  Object.defineProperty(localStorage, 'length', {
    get: () => Object.keys(store).length,
    configurable: true,
  });
  (localStorage.key as ReturnType<typeof vi.fn>).mockImplementation(
    (index: number) => Object.keys(store)[index] ?? null
  );
});

// ─── Property Tests ──────────────────────────────────────────────────────────

describe('Property 11: Frontend Fallback Correctness', () => {
  /**
   * When the API is unavailable (network error, timeout, or 5xx),
   * the hook's hasPermission results SHALL match the Static_Matrix
   * (DEFAULT_PERMISSIONS) for the user's role.
   *
   * **Validates: Requirements 6.2, 6.5**
   */

  it('when API fails with network error, permissions match Static_Matrix for any non-Admin role and module/action', async () => {
    await fc.assert(
      fc.asyncProperty(
        nonAdminRoleArb,
        moduleArb,
        actionArb,
        userIdArb,
        async (role, module, action, userId) => {
          // Reset state
          store = {};
          mockApiGet.mockReset();
          mockApiGet.mockRejectedValue({ code: 'ERR_NETWORK', message: 'Network Error' });
          mockUser.user = { id: userId, role, name: 'Test' };

          const { result } = renderHook(() => usePermissions());

          await waitFor(() => {
            expect(result.current.isLoading).toBe(false);
          });

          // Expected from static matrix
          const rolePerms = DEFAULT_PERMISSIONS[role as Role];
          const modulePerms = rolePerms?.[module as Module] ?? [];
          const expected = modulePerms.includes(action as any);

          expect(result.current.hasPermission(module, action)).toBe(expected);
        }
      ),
      { numRuns: 50 }
    );
  });

  it('when API fails with 500 error, permissions match Static_Matrix for any non-Admin role', async () => {
    await fc.assert(
      fc.asyncProperty(
        nonAdminRoleArb,
        moduleArb,
        actionArb,
        async (role, module, action) => {
          store = {};
          mockApiGet.mockReset();
          mockApiGet.mockRejectedValue({ response: { status: 500 } });
          mockUser.user = { id: '1', role, name: 'Test' };

          const { result } = renderHook(() => usePermissions());

          await waitFor(() => {
            expect(result.current.isLoading).toBe(false);
          });

          const rolePerms = DEFAULT_PERMISSIONS[role as Role];
          const modulePerms = rolePerms?.[module as Module] ?? [];
          const expected = modulePerms.includes(action as any);

          expect(result.current.hasPermission(module, action)).toBe(expected);
        }
      ),
      { numRuns: 50 }
    );
  });

  it('when API fails with timeout, permissions match Static_Matrix for any non-Admin role', async () => {
    await fc.assert(
      fc.asyncProperty(
        nonAdminRoleArb,
        moduleArb,
        actionArb,
        async (role, module, action) => {
          store = {};
          mockApiGet.mockReset();
          mockApiGet.mockRejectedValue({ code: 'ECONNABORTED', message: 'timeout' });
          mockUser.user = { id: '1', role, name: 'Test' };

          const { result } = renderHook(() => usePermissions());

          await waitFor(() => {
            expect(result.current.isLoading).toBe(false);
          });

          const rolePerms = DEFAULT_PERMISSIONS[role as Role];
          const modulePerms = rolePerms?.[module as Module] ?? [];
          const expected = modulePerms.includes(action as any);

          expect(result.current.hasPermission(module, action)).toBe(expected);
        }
      ),
      { numRuns: 50 }
    );
  });
});

describe('Property 12: Frontend Helper Method Equivalence', () => {
  /**
   * For any module M, the convenience methods SHALL be equivalent to
   * calling hasPermission with the corresponding action:
   *   canView(M) === hasPermission(M, 'View')
   *   canCreate(M) === hasPermission(M, 'Create')
   *   canEdit(M) === hasPermission(M, 'Edit')
   *   canDelete(M) === hasPermission(M, 'Delete')
   *   canApprove(M) === hasPermission(M, 'Approve')
   *
   * **Validates: Requirements 6.7**
   */

  it('canView(M) equals hasPermission(M, "View") for any role and module', async () => {
    await fc.assert(
      fc.asyncProperty(
        allRoleArb,
        moduleArb,
        async (role, module) => {
          store = {};
          mockApiGet.mockReset();
          const permSet = buildPermissionSet('1', role);
          mockApiGet.mockResolvedValue({ data: permSet });
          mockUser.user = { id: '1', role, name: 'Test' };

          const { result } = renderHook(() => usePermissions());

          await waitFor(() => {
            expect(result.current.isLoading).toBe(false);
          });

          expect(result.current.canView(module)).toBe(
            result.current.hasPermission(module, 'View')
          );
        }
      ),
      { numRuns: 50 }
    );
  });

  it('canCreate(M) equals hasPermission(M, "Create") for any role and module', async () => {
    await fc.assert(
      fc.asyncProperty(
        allRoleArb,
        moduleArb,
        async (role, module) => {
          store = {};
          mockApiGet.mockReset();
          const permSet = buildPermissionSet('1', role);
          mockApiGet.mockResolvedValue({ data: permSet });
          mockUser.user = { id: '1', role, name: 'Test' };

          const { result } = renderHook(() => usePermissions());

          await waitFor(() => {
            expect(result.current.isLoading).toBe(false);
          });

          expect(result.current.canCreate(module)).toBe(
            result.current.hasPermission(module, 'Create')
          );
        }
      ),
      { numRuns: 50 }
    );
  });

  it('canEdit(M) equals hasPermission(M, "Edit") for any role and module', async () => {
    await fc.assert(
      fc.asyncProperty(
        allRoleArb,
        moduleArb,
        async (role, module) => {
          store = {};
          mockApiGet.mockReset();
          const permSet = buildPermissionSet('1', role);
          mockApiGet.mockResolvedValue({ data: permSet });
          mockUser.user = { id: '1', role, name: 'Test' };

          const { result } = renderHook(() => usePermissions());

          await waitFor(() => {
            expect(result.current.isLoading).toBe(false);
          });

          expect(result.current.canEdit(module)).toBe(
            result.current.hasPermission(module, 'Edit')
          );
        }
      ),
      { numRuns: 50 }
    );
  });

  it('canDelete(M) equals hasPermission(M, "Delete") for any role and module', async () => {
    await fc.assert(
      fc.asyncProperty(
        allRoleArb,
        moduleArb,
        async (role, module) => {
          store = {};
          mockApiGet.mockReset();
          const permSet = buildPermissionSet('1', role);
          mockApiGet.mockResolvedValue({ data: permSet });
          mockUser.user = { id: '1', role, name: 'Test' };

          const { result } = renderHook(() => usePermissions());

          await waitFor(() => {
            expect(result.current.isLoading).toBe(false);
          });

          expect(result.current.canDelete(module)).toBe(
            result.current.hasPermission(module, 'Delete')
          );
        }
      ),
      { numRuns: 50 }
    );
  });

  it('canApprove(M) equals hasPermission(M, "Approve") for any role and module', async () => {
    await fc.assert(
      fc.asyncProperty(
        allRoleArb,
        moduleArb,
        async (role, module) => {
          store = {};
          mockApiGet.mockReset();
          const permSet = buildPermissionSet('1', role);
          mockApiGet.mockResolvedValue({ data: permSet });
          mockUser.user = { id: '1', role, name: 'Test' };

          const { result } = renderHook(() => usePermissions());

          await waitFor(() => {
            expect(result.current.isLoading).toBe(false);
          });

          expect(result.current.canApprove(module)).toBe(
            result.current.hasPermission(module, 'Approve')
          );
        }
      ),
      { numRuns: 50 }
    );
  });
});

describe('Property 13: Frontend Cache Validity', () => {
  /**
   * When a valid cache entry exists (timestamp < 5 minutes old),
   * the hook SHALL use cached permissions without making an API call.
   * When the cache is older than 5 minutes, the hook SHALL call the API.
   *
   * **Validates: Requirements 6.2**
   */

  it('cache less than 5 minutes old is used without API call for any role', async () => {
    await fc.assert(
      fc.asyncProperty(
        nonAdminRoleArb,
        userIdArb,
        // Generate a timestamp within the last 5 minutes (0 to 299999 ms ago)
        fc.integer({ min: 0, max: 299_999 }),
        async (role, userId, msAgo) => {
          store = {};
          mockApiGet.mockReset();

          const permSet = buildPermissionSet(userId, role);
          const cacheEntry = {
            data: permSet,
            timestamp: Date.now() - msAgo,
            userId,
          };
          store[`user_permissions_${userId}`] = JSON.stringify(cacheEntry);

          mockUser.user = { id: userId, role, name: 'Test' };

          const { result } = renderHook(() => usePermissions());

          await waitFor(() => {
            expect(result.current.isLoading).toBe(false);
          });

          // API should NOT have been called since cache is valid
          expect(mockApiGet).not.toHaveBeenCalled();
          // Permissions should be available from cache
          expect(result.current.permissions).not.toBeNull();
        }
      ),
      { numRuns: 50 }
    );
  });

  it('cache older than 5 minutes triggers API call for any role', async () => {
    await fc.assert(
      fc.asyncProperty(
        nonAdminRoleArb,
        userIdArb,
        // Generate a timestamp older than 5 minutes (300000 to 600000 ms ago)
        fc.integer({ min: 300_000, max: 600_000 }),
        async (role, userId, msAgo) => {
          store = {};
          mockApiGet.mockReset();

          const permSet = buildPermissionSet(userId, role);
          const cacheEntry = {
            data: permSet,
            timestamp: Date.now() - msAgo,
            userId,
          };
          store[`user_permissions_${userId}`] = JSON.stringify(cacheEntry);

          // API returns fresh data
          mockApiGet.mockResolvedValue({ data: permSet });
          mockUser.user = { id: userId, role, name: 'Test' };

          const { result } = renderHook(() => usePermissions());

          await waitFor(() => {
            expect(result.current.isLoading).toBe(false);
          });

          // API SHOULD have been called since cache is expired
          expect(mockApiGet).toHaveBeenCalled();
        }
      ),
      { numRuns: 50 }
    );
  });
});

// @vitest-environment jsdom
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { renderHook, waitFor, act } from '@testing-library/react';
import { usePermissions } from '../usePermissions';
import { UserRole } from '../../constants';
import { MODULES, PERMISSIONS, DEFAULT_PERMISSIONS, Module, Permission } from '../../permissions';
import { UserPermissionSet } from '../../permissions/types';

// Mock the UserContext
const mockUser = { user: null as any };
vi.mock('../../context/UserContext', () => ({
  useUser: () => mockUser,
}));

// Mock the AppContext (logout for re-auth flow)
const mockLogout = vi.fn();
vi.mock('../../context/AppContext', () => ({
  useAppContext: () => ({ logout: mockLogout }),
}));

// Mock the API service
const mockApiGet = vi.fn();
vi.mock('../../services/api', () => ({
  default: {
    get: (...args: any[]) => mockApiGet(...args),
  },
}));

// Helper: build a mock UserPermissionSet from the static matrix for a given role
function buildPermissionSet(userId: string, role: string): UserPermissionSet {
  const rolePerms = DEFAULT_PERMISSIONS[role as keyof typeof DEFAULT_PERMISSIONS];
  const permissions: Record<string, string[]> = {};
  if (rolePerms) {
    for (const [mod, actions] of Object.entries(rolePerms)) {
      permissions[mod] = [...actions];
    }
  }
  return {
    userId,
    role,
    roleId: 'role-1',
    isCustomRole: false,
    permissions,
    overrides: [],
  };
}

describe('usePermissions', () => {
  let store: Record<string, string> = {};

  beforeEach(() => {
    mockUser.user = null;
    mockLogout.mockClear();
    mockApiGet.mockReset();
    store = {};

    // Override the global localStorage mock from setup.ts to actually store values
    (localStorage.getItem as ReturnType<typeof vi.fn>).mockImplementation(
      (key: string) => store[key] ?? null
    );
    (localStorage.setItem as ReturnType<typeof vi.fn>).mockImplementation(
      (key: string, value: string) => { store[key] = value; }
    );
    (localStorage.removeItem as ReturnType<typeof vi.fn>).mockImplementation(
      (key: string) => { delete store[key]; }
    );
    (localStorage.clear as ReturnType<typeof vi.fn>).mockImplementation(
      () => { store = {}; }
    );
    Object.defineProperty(localStorage, 'length', {
      get: () => Object.keys(store).length,
      configurable: true,
    });
    (localStorage.key as ReturnType<typeof vi.fn>).mockImplementation(
      (index: number) => Object.keys(store)[index] ?? null
    );
  });

  describe('API fetch on mount', () => {
    it('should fetch from /v1/permissions/me on mount when no cache exists', async () => {
      const permSet = buildPermissionSet('1', UserRole.INTERNAL_AUDITOR);
      mockApiGet.mockResolvedValue({ data: permSet });
      mockUser.user = { id: '1', role: UserRole.INTERNAL_AUDITOR, name: 'Test' };

      const { result } = renderHook(() => usePermissions());

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(mockApiGet).toHaveBeenCalledWith('/v1/permissions/me', expect.objectContaining({
        timeout: 10000,
      }));
    });

    it('should expose isLoading=true during initial fetch', () => {
      mockApiGet.mockReturnValue(new Promise(() => {})); // never resolves
      mockUser.user = { id: '1', role: UserRole.INTERNAL_AUDITOR, name: 'Test' };

      const { result } = renderHook(() => usePermissions());

      expect(result.current.isLoading).toBe(true);
    });

    it('should set isLoading=false once fetch resolves', async () => {
      const permSet = buildPermissionSet('1', UserRole.INTERNAL_AUDITOR);
      mockApiGet.mockResolvedValue({ data: permSet });
      mockUser.user = { id: '1', role: UserRole.INTERNAL_AUDITOR, name: 'Test' };

      const { result } = renderHook(() => usePermissions());

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });
    });
  });

  describe('localStorage cache with 5-minute TTL', () => {
    it('should use cached permissions without API call when cache is valid', async () => {
      const permSet = buildPermissionSet('1', UserRole.INTERNAL_AUDITOR);
      const cacheEntry = {
        data: permSet,
        timestamp: Date.now(),
        userId: '1',
      };
      localStorage.setItem('user_permissions_1', JSON.stringify(cacheEntry));
      mockUser.user = { id: '1', role: UserRole.INTERNAL_AUDITOR, name: 'Test' };

      const { result } = renderHook(() => usePermissions());

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      // Should NOT have called the API
      expect(mockApiGet).not.toHaveBeenCalled();
      expect(result.current.hasPermission('AuditPlans', 'View')).toBe(true);
    });

    it('should fetch from API when cache is expired (> 5 min)', async () => {
      const permSet = buildPermissionSet('1', UserRole.INTERNAL_AUDITOR);
      const cacheEntry = {
        data: permSet,
        timestamp: Date.now() - 6 * 60 * 1000, // 6 minutes ago
        userId: '1',
      };
      localStorage.setItem('user_permissions_1', JSON.stringify(cacheEntry));
      mockApiGet.mockResolvedValue({ data: permSet });
      mockUser.user = { id: '1', role: UserRole.INTERNAL_AUDITOR, name: 'Test' };

      const { result } = renderHook(() => usePermissions());

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(mockApiGet).toHaveBeenCalled();
    });

    it('should store permissions in localStorage on successful API fetch', async () => {
      const permSet = buildPermissionSet('1', UserRole.INTERNAL_AUDITOR);
      mockApiGet.mockResolvedValue({ data: permSet });
      mockUser.user = { id: '1', role: UserRole.INTERNAL_AUDITOR, name: 'Test' };

      renderHook(() => usePermissions());

      await waitFor(() => {
        const stored = localStorage.getItem('user_permissions_1');
        expect(stored).not.toBeNull();
      });

      const stored = JSON.parse(localStorage.getItem('user_permissions_1')!);
      expect(stored.data.userId).toBe('1');
      expect(stored.userId).toBe('1');
      expect(stored.timestamp).toBeGreaterThan(0);
    });

    it('should discard cached permissions if user ID does not match', async () => {
      // Cache for user 2
      const permSet2 = buildPermissionSet('2', UserRole.VIEWER);
      const cacheEntry = {
        data: permSet2,
        timestamp: Date.now(),
        userId: '2',
      };
      localStorage.setItem('user_permissions_2', JSON.stringify(cacheEntry));

      // Current user is user 1
      const permSet1 = buildPermissionSet('1', UserRole.INTERNAL_AUDITOR);
      mockApiGet.mockResolvedValue({ data: permSet1 });
      mockUser.user = { id: '1', role: UserRole.INTERNAL_AUDITOR, name: 'Test' };

      renderHook(() => usePermissions());

      await waitFor(() => {
        // Old user's cache should be removed
        expect(localStorage.getItem('user_permissions_2')).toBeNull();
      });
    });
  });

  describe('fallback to DEFAULT_PERMISSIONS on network error or 5xx', () => {
    it('should fall back to static matrix on network error', async () => {
      mockApiGet.mockRejectedValue({ code: 'ERR_NETWORK', message: 'Network Error' });
      mockUser.user = { id: '1', role: UserRole.INTERNAL_AUDITOR, name: 'Test' };

      const { result } = renderHook(() => usePermissions());

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      // Should use static matrix fallback
      expect(result.current.hasPermission('AuditPlans', 'View')).toBe(true);
      expect(result.current.hasPermission('AuditPlans', 'Delete')).toBe(false);
    });

    it('should fall back to static matrix on 500 error', async () => {
      mockApiGet.mockRejectedValue({ response: { status: 500 } });
      mockUser.user = { id: '1', role: UserRole.INTERNAL_AUDITOR, name: 'Test' };

      const { result } = renderHook(() => usePermissions());

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(result.current.hasPermission('AuditPlans', 'View')).toBe(true);
    });

    it('should fall back to static matrix on timeout (ECONNABORTED)', async () => {
      mockApiGet.mockRejectedValue({ code: 'ECONNABORTED', message: 'timeout' });
      mockUser.user = { id: '1', role: UserRole.INTERNAL_AUDITOR, name: 'Test' };

      const { result } = renderHook(() => usePermissions());

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(result.current.hasPermission('AuditPlans', 'View')).toBe(true);
    });
  });

  describe('re-authentication on 401/403', () => {
    it('should trigger logout on 401 response (NOT fall back to static)', async () => {
      mockApiGet.mockRejectedValue({ response: { status: 401 } });
      mockUser.user = { id: '1', role: UserRole.INTERNAL_AUDITOR, name: 'Test' };

      renderHook(() => usePermissions());

      await waitFor(() => {
        expect(mockLogout).toHaveBeenCalled();
      });
    });

    it('should trigger logout on 403 response (NOT fall back to static)', async () => {
      mockApiGet.mockRejectedValue({ response: { status: 403 } });
      mockUser.user = { id: '1', role: UserRole.INTERNAL_AUDITOR, name: 'Test' };

      renderHook(() => usePermissions());

      await waitFor(() => {
        expect(mockLogout).toHaveBeenCalled();
      });
    });
  });

  describe('Admin bypass - always returns true', () => {
    it('should return true for all modules and all permissions when user is Admin', async () => {
      // Admin doesn't need API data to return true
      mockApiGet.mockReturnValue(new Promise(() => {})); // never resolves
      mockUser.user = { id: '1', role: UserRole.ADMIN, name: 'Admin' };

      const { result } = renderHook(() => usePermissions());

      const allModules = Object.values(MODULES) as Module[];
      const allPermissions = Object.values(PERMISSIONS) as Permission[];

      for (const mod of allModules) {
        for (const perm of allPermissions) {
          expect(result.current.hasPermission(mod, perm)).toBe(true);
        }
      }
    });

    it('should return true for all convenience methods when user is Admin', async () => {
      mockApiGet.mockReturnValue(new Promise(() => {}));
      mockUser.user = { id: '1', role: UserRole.ADMIN, name: 'Admin' };

      const { result } = renderHook(() => usePermissions());

      expect(result.current.canView('AuditPlans')).toBe(true);
      expect(result.current.canCreate('AuditPlans')).toBe(true);
      expect(result.current.canEdit('AuditPlans')).toBe(true);
      expect(result.current.canDelete('AuditPlans')).toBe(true);
      expect(result.current.canApprove('AuditPlans')).toBe(true);
    });
  });

  describe('refetch() method', () => {
    it('should force a fresh API call ignoring cache', async () => {
      const permSet = buildPermissionSet('1', UserRole.INTERNAL_AUDITOR);
      // Set valid cache
      const cacheEntry = {
        data: permSet,
        timestamp: Date.now(),
        userId: '1',
      };
      localStorage.setItem('user_permissions_1', JSON.stringify(cacheEntry));
      mockApiGet.mockResolvedValue({ data: permSet });
      mockUser.user = { id: '1', role: UserRole.INTERNAL_AUDITOR, name: 'Test' };

      const { result } = renderHook(() => usePermissions());

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      // Initial load used cache, no API call
      expect(mockApiGet).not.toHaveBeenCalled();

      // Now force refetch
      await act(async () => {
        await result.current.refetch();
      });

      expect(mockApiGet).toHaveBeenCalledTimes(1);
    });
  });

  describe('hasPermission with fetched data', () => {
    it('should return true for permissions the role has from API', async () => {
      const permSet = buildPermissionSet('1', UserRole.INTERNAL_AUDITOR);
      mockApiGet.mockResolvedValue({ data: permSet });
      mockUser.user = { id: '1', role: UserRole.INTERNAL_AUDITOR, name: 'Test' };

      const { result } = renderHook(() => usePermissions());

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(result.current.hasPermission('AuditPlans', 'View')).toBe(true);
      expect(result.current.hasPermission('AuditProgramLibrary', 'Create')).toBe(true);
      expect(result.current.hasPermission('AuditProgramLibrary', 'Edit')).toBe(true);
    });

    it('should return false for permissions the role does not have', async () => {
      const permSet = buildPermissionSet('1', UserRole.INTERNAL_AUDITOR);
      mockApiGet.mockResolvedValue({ data: permSet });
      mockUser.user = { id: '1', role: UserRole.INTERNAL_AUDITOR, name: 'Test' };

      const { result } = renderHook(() => usePermissions());

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(result.current.hasPermission('AuditPlans', 'Delete')).toBe(false);
      expect(result.current.hasPermission('AuditPlans', 'Approve')).toBe(false);
    });

    it('should return false for all permissions when user is null', () => {
      mockUser.user = null;

      const { result } = renderHook(() => usePermissions());

      expect(result.current.hasPermission('AuditPlans', 'View')).toBe(false);
      expect(result.current.canView('AuditPlans')).toBe(false);
    });

    it('should expose isCustomRole from API response', async () => {
      const permSet = buildPermissionSet('1', UserRole.INTERNAL_AUDITOR);
      permSet.isCustomRole = true;
      mockApiGet.mockResolvedValue({ data: permSet });
      mockUser.user = { id: '1', role: UserRole.INTERNAL_AUDITOR, name: 'Test' };

      const { result } = renderHook(() => usePermissions());

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(result.current.isCustomRole).toBe(true);
    });
  });

  describe('convenience methods', () => {
    it('canView should check View permission', async () => {
      const permSet = buildPermissionSet('1', UserRole.INTERNAL_AUDITOR);
