import { useQuery, useQueryClient } from '@tanstack/react-query';
import { auditService } from '../services/auditService';

export const useAuditFindings = (initialParams: any = {}) => {
  const queryClient = useQueryClient();

  const findingsQuery = useQuery({
    queryKey: ['audit-findings', initialParams],
    queryFn: () => auditService.getFindings(initialParams),
    staleTime: 5 * 60 * 1000,
  });

  const data = findingsQuery.data || {};
  const findings = (data.data || (Array.isArray(data) ? data : [])) as any[];

  const fetchFindings = () => {
    queryClient.invalidateQueries({ queryKey: ['audit-findings'] });
  };

  return { 
    findings, 
    loading: findingsQuery.isLoading || findingsQuery.isFetching, 
    error: findingsQuery.error ? (findingsQuery.error as any).message : null, 
    fetchFindings 
  };
};

import { useQuery, useQueryClient } from '@tanstack/react-query';
import { auditService } from '../services/auditService';

export const useAuditPlans = (initialParams: any = {}) => {
  const queryClient = useQueryClient();

  const plansQuery = useQuery({
    queryKey: ['audit-plans', initialParams],
    queryFn: () => auditService.getPlans(initialParams),
    staleTime: 5 * 60 * 1000, // 5 minutes cache
  });

  const data = plansQuery.data || {};
  const plans = (data.data || (Array.isArray(data) ? data : [])) as any[];
  const pagination = {
    total: data.pagination?.total || 0,
    totalPages: data.pagination?.totalPages || 0,
    page: data.pagination?.page || 1,
    limit: data.pagination?.pageSize || 15
  };

  const fetchPlans = (_params?: any) => {
    queryClient.invalidateQueries({ queryKey: ['audit-plans'] });
  };

  return { 
    plans, 
    loading: plansQuery.isLoading || plansQuery.isFetching, 
    error: plansQuery.error ? (plansQuery.error as any).message : null, 
    pagination, 
    fetchPlans 
  };
};

import { useCallback } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { correspondenceService } from '../services/correspondenceService';

export const useCorrespondence = (initialParams: any = {}) => {
  const queryClient = useQueryClient();

  const statsQuery = useQuery({
    queryKey: ['correspondence-stats'],
    queryFn: () => correspondenceService.getStats(),
    staleTime: 2 * 60 * 1000,
  });

  const incomingQuery = useQuery({
    queryKey: ['correspondence-incoming', initialParams],
    queryFn: () => correspondenceService.getIncoming(initialParams),
    staleTime: 1 * 60 * 1000,
  });

  const outgoingQuery = useQuery({
    queryKey: ['correspondence-outgoing', initialParams],
    queryFn: () => correspondenceService.getOutgoing(initialParams),
    staleTime: 1 * 60 * 1000,
  });

  const archiveQuery = useQuery({
    queryKey: ['correspondence-archive', initialParams],
    queryFn: () => correspondenceService.getArchive(initialParams),
    staleTime: 5 * 60 * 1000,
  });

  const refreshAll = useCallback(() => {
    queryClient.invalidateQueries({ queryKey: ['correspondence-stats'] });
    queryClient.invalidateQueries({ queryKey: ['correspondence-incoming'] });
    queryClient.invalidateQueries({ queryKey: ['correspondence-outgoing'] });
    queryClient.invalidateQueries({ queryKey: ['correspondence-archive'] });
  }, [queryClient]);

  return {
    stats: statsQuery.data || null,
    incoming: incomingQuery.data || [],
    outgoing: outgoingQuery.data || [],
    archive: archiveQuery.data || [],
    loading: statsQuery.isLoading || incomingQuery.isLoading || outgoingQuery.isLoading,
    error: (statsQuery.error || incomingQuery.error || outgoingQuery.error) ? 'Failed to fetch correspondence data' : null,
    fetchStats: () => queryClient.refetchQueries({ queryKey: ['correspondence-stats'] }),
    fetchIncoming: (params: any) => queryClient.prefetchQuery({ queryKey: ['correspondence-incoming', params], queryFn: () => correspondenceService.getIncoming(params) }),
    fetchOutgoing: (params: any) => queryClient.prefetchQuery({ queryKey: ['correspondence-outgoing', params], queryFn: () => correspondenceService.getOutgoing(params) }),
    fetchArchive: (params: any) => queryClient.prefetchQuery({ queryKey: ['correspondence-archive', params], queryFn: () => correspondenceService.getArchive(params) }),
    refreshAll
  };
};

import { useQuery } from '@tanstack/react-query';
import { dashboardService } from '../services/dashboardService';

export const useDashboardStats = (department?: string) => {
  const statsQuery = useQuery({
    queryKey: ['dashboard-stats', department],
    queryFn: () => dashboardService.getStats(department),
    staleTime: 5 * 60 * 1000, // 5 minutes cache
  });

  // Ensure stats has the expected structure with safe defaults
  const rawStats = statsQuery.data;
  const stats = rawStats ? {
    audits: {
      total: rawStats.audits?.total ?? 0,
      completed: rawStats.audits?.completed ?? 0,
      in_progress: rawStats.audits?.in_progress ?? 0,
      delayed: rawStats.audits?.delayed ?? 0,
      progress_by_type: rawStats.audits?.progress_by_type ?? []
    },
    findings: {
      summary: {
        total: rawStats.findings?.summary?.total ?? 0,
        open: rawStats.findings?.summary?.open ?? 0,
        high_risk_open: rawStats.findings?.summary?.high_risk_open ?? 0
      },
      byRisk: rawStats.findings?.byRisk ?? []
    },
    recommendations: {
      total: rawStats.recommendations?.total ?? 0,
      open: rawStats.recommendations?.open ?? 0,
      overdue: rawStats.recommendations?.overdue ?? 0
    },
    risks: {
      summary: {
        total: rawStats.risks?.summary?.total ?? 0,
        high: rawStats.risks?.summary?.high ?? 0
      },
      byLevel: rawStats.risks?.byLevel ?? []
    },
    correspondence: {
      incoming_total: rawStats.correspondence?.incoming_total ?? 0,
      outgoing_total: rawStats.correspondence?.outgoing_total ?? 0,
      pending_responses: rawStats.correspondence?.pending_responses ?? 0
    },
    compliance: {
      total: rawStats.compliance?.total ?? 0
    },
    activity: rawStats.activity ?? []
  } : null;

  return { 
    stats, 
    loading: statsQuery.isLoading, 
    error: statsQuery.error ? (statsQuery.error as any).message : null, 
    refresh: () => statsQuery.refetch() 
  };
};

import { useCallback, useRef, useEffect } from 'react';

/**
 * Hook that returns a debounced version of a callback.
 * Useful for search inputs, resize handlers, and other high-frequency events.
 * 
 * Unlike useDebounce (which debounces a value), this debounces the function itself.
 * 
 * @example
 * const debouncedSearch = useDebouncedCallback((query: string) => {
 *   fetchResults(query);
 * }, 300);
 * 
 * <input onChange={(e) => debouncedSearch(e.target.value)} />
 */
export function useDebouncedCallback<T extends (...args: any[]) => any>(
  callback: T,
  delay: number
): T {
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);
  const callbackRef = useRef(callback);

  // Keep callback ref up to date
  useEffect(() => {
    callbackRef.current = callback;
  }, [callback]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, []);

  const debouncedFn = useCallback((...args: Parameters<T>) => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }

    timeoutRef.current = setTimeout(() => {
      callbackRef.current(...args);
    }, delay);
  }, [delay]);

  return debouncedFn as T;
}

/**
 * Hook that returns a throttled version of a callback.
 * Ensures the function is called at most once per interval.
 * 
 * @example
 * const throttledScroll = useThrottledCallback(() => {
 *   updateScrollPosition();
 * }, 100);
 * 
 * window.addEventListener('scroll', throttledScroll);
 */
export function useThrottledCallback<T extends (...args: any[]) => any>(
  callback: T,
  interval: number
): T {
  const lastCallRef = useRef<number>(0);
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);
  const callbackRef = useRef(callback);

  useEffect(() => {
    callbackRef.current = callback;
  }, [callback]);

  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, []);

  const throttledFn = useCallback((...args: Parameters<T>) => {
    const now = Date.now();
    const timeSinceLastCall = now - lastCallRef.current;

    if (timeSinceLastCall >= interval) {
      lastCallRef.current = now;
      callbackRef.current(...args);
    } else {
      // Schedule a trailing call
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
      timeoutRef.current = setTimeout(() => {
        lastCallRef.current = Date.now();
        callbackRef.current(...args);
      }, interval - timeSinceLastCall);
    }
  }, [interval]);

  return throttledFn as T;
}

