    queryFn: () => userService.getJobTitles(),
  });

  // Mutations
  const updateUserMutation = useMutation({
    mutationFn: ({ id, data }: { id: string; data: any }) => userService.updateUser(id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['users'] });
      toast.success('User updated successfully');
    },
    onError: (err: any) => {
      toast.error(`Failed to update user: ${err.message}`);
    }
  });

  const refreshAll = useCallback(() => {
    queryClient.invalidateQueries({ queryKey: ['users'] });
    queryClient.invalidateQueries({ queryKey: ['users-summary'] });
    queryClient.invalidateQueries({ queryKey: ['sessions'] });
    queryClient.invalidateQueries({ queryKey: ['password-reset-requests'] });
  }, [queryClient]);

  return {
    users: usersQuery.data?.data || [],
    summary: summaryQuery.data || null,
    roles: Array.isArray(rolesQuery.data) ? rolesQuery.data : (rolesQuery.data as any)?.data || [],
    permissions: Array.isArray(permissionsQuery.data) ? permissionsQuery.data : (permissionsQuery.data as any)?.data || [],
    sessions: Array.isArray(sessionsQuery.data) ? sessionsQuery.data : (sessionsQuery.data as any)?.data || [],
    settings: settingsQuery.data || null,
    loginHistory: loginHistoryQuery.data?.data || [],
    auditTrail: auditTrailQuery.data?.data || [],
    resetRequests: Array.isArray(resetRequestsQuery.data) ? resetRequestsQuery.data : (resetRequestsQuery.data as any)?.requests || [],
    departments: Array.isArray(departmentsQuery.data) ? departmentsQuery.data : (departmentsQuery.data as any)?.departments || [],
    jobTitles: Array.isArray(jobTitlesQuery.data) ? jobTitlesQuery.data : (jobTitlesQuery.data as any)?.jobTitles || [],
    loading: usersQuery.isLoading || summaryQuery.isLoading,
    error: usersQuery.error ? (usersQuery.error as any).message : null,
    pagination: usersQuery.data?.pagination || { total: 0, page: 1, pageSize: 10, totalPages: 0 },
    historyPagination: loginHistoryQuery.data?.pagination || { total: 0, page: 1, pageSize: 50, totalPages: 0 },
    activityPagination: auditTrailQuery.data?.pagination || { total: 0, page: 1, pageSize: 50, totalPages: 0 },
    fetchUsers: (params: any) => queryClient.prefetchQuery({ queryKey: ['users', params], queryFn: () => userService.getUsers(params) }),
    fetchLoginHistory: (params: any) => queryClient.prefetchQuery({ queryKey: ['login-history', params], queryFn: () => userService.getLoginHistory(params) }),
    fetchAuditTrail: (params: any) => queryClient.prefetchQuery({ queryKey: ['audit-trail', params], queryFn: () => userService.getAuditTrail(params) }),
    refreshAll,
    updateUser: updateUserMutation.mutateAsync
  };
};

import {StrictMode, Suspense} from 'react';
import {createRoot} from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';
import App from './App.tsx';
import api from './services/api';
import './index.css';
import './i18n'; // Import i18n
import { securityLogger } from './utils/SecurityLogger';
import { initNoiseFilter } from './utils/NoiseFilter';
import { SecurityProvider } from './utils/SecurityProvider';

// Initialize noise filter for dev environment noise
initNoiseFilter();

// Global Error Listener for Frontend
window.addEventListener('error', (event) => {
  const msg = (event.message || '').toLowerCase();
  const isAuthError = (event.error as any)?.response?.status === 401;
  const isViteNoise = (msg.includes('vite') || msg.includes('hmr')) && 
                     (msg.includes('websocket') || msg.includes('connection failed') || msg.includes('closed without opened'));

  if (
    isViteNoise ||
    isAuthError ||
    msg.includes('network error')
  ) return;

  api.post('/system-errors', {
    message: msg,
    stack: event.error?.stack || null,
    module: 'Frontend'
  }).catch(err => console.error('Failed to log frontend error:', err));
});

window.addEventListener('unhandledrejection', (event) => {
  const msg = (event.reason?.message || String(event.reason) || '').toLowerCase();
  const isAuthError = event.reason?.response?.status === 401;
  const isViteNoise = (msg.includes('vite') || msg.includes('hmr')) && 
                     (msg.includes('websocket') || msg.includes('connection failed') || msg.includes('closed without opened'));

  if (
    isViteNoise ||
    isAuthError ||
    msg.includes('network error')
  ) return;

  api.post('/system-errors', {
    message: msg,
    stack: event.reason?.stack || null,
    module: 'Frontend (Promise)'
  }).catch(err => console.error('Failed to log frontend promise error:', err));
});

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <SecurityProvider>
      <BrowserRouter>
        <Suspense fallback={<div className="min-h-screen flex items-center justify-center bg-[var(--color-bg-soft)]"><div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div></div>}>
          <App />
        </Suspense>
      </BrowserRouter>
    </SecurityProvider>
  </StrictMode>,
);

import { describe, it, expect } from 'vitest';
import {
  validateFilename,
  validateChecksum,
  validateFileSize,
  validateFileRecord,
  MAX_FILENAME_LENGTH,
  CHECKSUM_LENGTH,
} from './file-record.model';

describe('FileRecord Validation', () => {
  describe('validateFilename', () => {
    it('accepts a valid filename', () => {
      expect(validateFilename('report.pdf')).toBeNull();
    });

    it('accepts a filename at max length', () => {
      const name = 'a'.repeat(MAX_FILENAME_LENGTH);
      expect(validateFilename(name)).toBeNull();
    });

    it('rejects an empty filename', () => {
      const error = validateFilename('');
      expect(error).not.toBeNull();
      expect(error!.field).toBe('originalName');
    });

    it('rejects a filename exceeding 255 characters', () => {
      const name = 'a'.repeat(256);
      const error = validateFilename(name);
      expect(error).not.toBeNull();
      expect(error!.field).toBe('originalName');
      expect(error!.message).toContain('256');
    });

    it('rejects a filename with path traversal (..)', () => {
      const error = validateFilename('../etc/passwd');
      expect(error).not.toBeNull();
      expect(error!.message).toContain('path traversal');
    });

    it('rejects a filename with forward slash', () => {
      const error = validateFilename('path/to/file.txt');
      expect(error).not.toBeNull();
      expect(error!.message).toContain('path traversal');
    });

    it('rejects a filename with backslash', () => {
      const error = validateFilename('path\\to\\file.txt');
      expect(error).not.toBeNull();
      expect(error!.message).toContain('path traversal');
    });

    it('rejects a filename with null byte', () => {
      const error = validateFilename('file\0.txt');
      expect(error).not.toBeNull();
      expect(error!.message).toContain('path traversal');
    });
  });

  describe('validateChecksum', () => {
    it('accepts a valid SHA-256 checksum', () => {
      const validChecksum = 'a'.repeat(CHECKSUM_LENGTH);
      expect(validateChecksum(validChecksum)).toBeNull();
    });

    it('accepts a realistic SHA-256 checksum', () => {
      const checksum = 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855';
      expect(validateChecksum(checksum)).toBeNull();
    });

    it('rejects an empty checksum', () => {
      const error = validateChecksum('');
      expect(error).not.toBeNull();
      expect(error!.field).toBe('checksum');
    });

    it('rejects a checksum that is too short', () => {
      const error = validateChecksum('abc123');
      expect(error).not.toBeNull();
      expect(error!.message).toContain('SHA-256');
    });

    it('rejects a checksum with uppercase letters', () => {
      const error = validateChecksum('A'.repeat(64));
      expect(error).not.toBeNull();
      expect(error!.message).toContain('lowercase');
    });

    it('rejects a checksum with non-hex characters', () => {
      const error = validateChecksum('g'.repeat(64));
      expect(error).not.toBeNull();
    });
  });

  describe('validateFileSize', () => {
    it('accepts a valid positive size', () => {
      expect(validateFileSize(1024)).toBeNull();
    });

    it('accepts size of 1 byte', () => {
      expect(validateFileSize(1)).toBeNull();
    });

    it('rejects zero size', () => {
      const error = validateFileSize(0);
      expect(error).not.toBeNull();
      expect(error!.field).toBe('size');
      expect(error!.message).toContain('positive');
    });

    it('rejects negative size', () => {
      const error = validateFileSize(-100);
      expect(error).not.toBeNull();
      expect(error!.message).toContain('positive');
    });

    it('rejects NaN', () => {
      const error = validateFileSize(NaN);
      expect(error).not.toBeNull();
      expect(error!.message).toContain('finite');
    });

    it('rejects Infinity', () => {
      const error = validateFileSize(Infinity);
      expect(error).not.toBeNull();
      expect(error!.message).toContain('finite');
    });

    it('rejects fractional bytes', () => {
      const error = validateFileSize(1.5);
      expect(error).not.toBeNull();
      expect(error!.message).toContain('integer');
    });
  });

  describe('validateFileRecord', () => {
    const validRecord = {
      originalName: 'document.pdf',
      checksum: 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855',
      size: 1024,
    };

    it('returns no errors for a valid record', () => {
      expect(validateFileRecord(validRecord)).toEqual([]);
    });

    it('returns multiple errors for an invalid record', () => {
      const errors = validateFileRecord({
        originalName: '',
        checksum: 'invalid',
        size: -1,
      });
      expect(errors.length).toBe(3);
    });

    it('returns only relevant errors', () => {
      const errors = validateFileRecord({
        ...validRecord,
        originalName: 'a'.repeat(256),
      });
      expect(errors.length).toBe(1);
      expect(errors[0].field).toBe('originalName');
    });
  });
});

import { describe, it, expect } from 'vitest';
import {
  validateJobType,
  validateJobStatus,
