        items: t('charter.definitions_items', { returnObjects: true }) as { term: string; def: string }[]
      },
      {
        id: "organization",
        title: t('charter.organization_title'),
        icon: Building,
        content: t('charter.organization_content', { returnObjects: true }) as string[]
      },
      {
        id: "purpose",
        title: t('charter.purpose_title'),
        icon: Target,
        content: t('charter.purpose_content', { returnObjects: true }) as string[]
      },
      {
        id: "reports",
        title: t('charter.reports_title'),
        icon: FileText,
        content: t('charter.reports_content', { returnObjects: true }) as string[],
        table: t('charter.reports_table', { returnObjects: true }) as { name: string; freq: string; recipient: string; notes: string }[]
      },
      {
        id: "org_chart",
        title: t('charter.org_chart_title'),
        icon: Users,
        content: t('charter.org_chart_content', { returnObjects: true }) as string[]
      },
      {
        id: "independence",
        title: t('charter.independence_title'),
        icon: Scale,
        content: t('charter.independence_content', { returnObjects: true }) as string[]
      },
      {
        id: "scope",
        title: t('charter.scope_title'),
        icon: Shield,
        content: t('charter.scope_content', { returnObjects: true }) as string[]
      },
      {
        id: "authorities",
        title: t('charter.authorities_title'),
        icon: Briefcase,
        content: t('charter.authorities_content', { returnObjects: true }) as string[]
      },
      {
        id: "responsibilities",
        title: t('charter.responsibilities_title'),
        icon: Users,
        content: t('charter.responsibilities_content', { returnObjects: true }) as string[]
      },
      {
        id: "manager_responsibilities",
        title: t('charter.manager_responsibilities_title'),
        icon: Target,
        content: t('charter.manager_responsibilities_content', { returnObjects: true }) as string[]
      },
      {
        id: "external_relations",
        title: t('charter.external_relations_title'),
        icon: Building,
        content: t('charter.external_relations_content', { returnObjects: true }) as string[]
      },
      {
        id: "references",
        title: t('charter.references_title'),
        icon: BookOpen,
        content: t('charter.references_content', { returnObjects: true }) as string[]
      },
      {
        id: "approval",
        title: t('charter.approval_title'),
        icon: CheckCircle,
        content: t('charter.approval_content', { returnObjects: true }) as string[]
      }
    ]
  };

  return (
    <div className="space-y-10">
      <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-8">
        <div className="flex items-center gap-6">
          <div className="w-12 h-12 sm:w-16 sm:h-16 bg-[var(--color-primary)] rounded-2xl flex items-center justify-center text-white shadow-lg shadow-[var(--color-primary)]/20">
            <BookOpen size={32} />
          </div>
          <div>
            <h2 className="text-2xl sm:text-4xl font-bold text-[var(--color-text-main)] tracking-tight">{t('common.auditCharter')}</h2>
            <p className="text-sm text-[var(--color-text-muted)] font-bold mt-2">{charterData.company}</p>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <div className="bg-[var(--color-bg-main)] px-4 py-2 rounded-xl text-sm font-bold text-[var(--color-text-muted)]">
            {t('common.version')}: {charterData.version}
          </div>
          <div className="bg-[var(--color-bg-main)] px-4 py-2 rounded-xl text-sm font-bold text-[var(--color-text-muted)]">
            {t('common.date')}: {charterData.date}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-8">
        {charterData.sections.map((section, idx) => {
          const Icon = section.icon;
          return (
            <motion.div 
              key={section.id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: idx * 0.05 }}
              className="glass-card p-8"
            >
              <div className="flex items-center gap-4 mb-6">
                <div className="w-12 h-12 rounded-2xl bg-[var(--color-primary)]/10 flex items-center justify-center text-[var(--color-primary)]">
                  <Icon size={24} />
                </div>
                <h3 className="text-2xl font-bold text-[var(--color-text-main)]">{section.title}</h3>
              </div>
              
              <div className="space-y-4 text-[var(--color-text-muted)] leading-relaxed">
                {section.id === 'org_chart' && (
                  <div className="py-8 overflow-x-auto">
                    <div className="min-w-[800px] flex flex-col items-center">
                      <div className="relative flex flex-col items-center w-full">
                        <div className="bg-[var(--color-primary)] text-white font-bold py-4 px-8 rounded-xl shadow-lg relative z-10 w-64 text-center">
                          {t('auditCharter.deptManager')}
                        </div>
                        <div className="w-0.5 h-8 bg-slate-300"></div>
                        <div className="bg-slate-700 text-white font-bold py-3 px-6 rounded-lg relative z-10 w-56 text-center">
                          {t('auditCharter.deputyManager')}
                        </div>
                        <div className="w-0.5 h-8 bg-slate-300"></div>
                        <div className="w-[75%] h-0.5 bg-slate-300"></div>
                        
                        <div className="flex w-full justify-around mt-0">
                          <div className="flex flex-col items-center flex-1 px-2">
                            <div className="w-0.5 h-8 bg-slate-300"></div>
                            <div className="bg-sky-500 w-full text-white font-bold py-3 px-2 rounded-lg shadow-md text-center text-sm h-full flex items-center justify-center leading-snug">
                              {t('auditCharter.financialAuditDept')}
                            </div>
                          </div>
                          <div className="flex flex-col items-center flex-1 px-2">
                            <div className="w-0.5 h-8 bg-slate-300"></div>
                            <div className="bg-emerald-500 w-full text-white font-bold py-3 px-2 rounded-lg shadow-md text-center text-sm h-full flex items-center justify-center leading-snug">
                              {t('auditCharter.auditDivision')}
                            </div>
                          </div>
                          <div className="flex flex-col items-center flex-1 px-2">
                            <div className="w-0.5 h-8 bg-slate-300"></div>
                            <div className="bg-amber-500 w-full text-white font-bold py-3 px-2 rounded-lg shadow-md text-center text-sm h-full flex items-center justify-center leading-snug">
                              {t('auditCharter.auditReconciliationDiv')}
                            </div>
                          </div>
                          <div className="flex flex-col items-center flex-1 px-2">
                            <div className="w-0.5 h-8 bg-slate-300"></div>
                            <div className="bg-rose-500 w-full text-white font-bold py-3 px-2 rounded-lg shadow-md text-center text-sm h-full flex items-center justify-center leading-snug">
                              {t('auditCharter.itAuditDiv')}
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                )}
                {section.content && Array.isArray(section.content) && section.content.map((p, i) => (
                  <p key={i} className={p && p.match && p.match(/^\d+\./) ? (isRTL ? "pe-4" : "ps-4") : ""}>
                    {p}
                  </p>
                ))}
                
                {section.items && (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-6">
                    {section.items.map((item, i) => (
                      <div key={i} className="bg-[var(--color-bg-soft)] p-4 rounded-xl border border-[var(--color-border-soft)]">
                        <h4 className="font-bold text-[var(--color-text-main)] mb-2">{item.term}</h4>
                        <p className="text-sm text-[var(--color-text-muted)]">{item.def}</p>
                      </div>
                    ))}
                  </div>
                )}

                {section.table && (
                  <div className="overflow-x-auto mt-6">
                    <table className="w-full text-start border-collapse">
                      <thead>
                        <tr className="bg-[var(--color-bg-soft)] border-b border-[var(--color-border-soft)]">
                          <th className="px-6 py-4 text-xs font-bold text-[var(--color-text-muted)] uppercase">{t('common.reportName')}</th>
                          <th className="px-6 py-4 text-xs font-bold text-[var(--color-text-muted)] uppercase">{t('common.frequency')}</th>
                          <th className="px-6 py-4 text-xs font-bold text-[var(--color-text-muted)] uppercase">{t('common.recipients')}</th>
                          <th className="px-6 py-4 text-xs font-bold text-[var(--color-text-muted)] uppercase">{t('common.notes')}</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-[var(--color-border-soft)]/50">
                        {section.table.map((row, i) => (
                          <tr key={i} className="hover:bg-[var(--color-bg-soft)]/50">
                            <td className="px-6 py-4 text-sm font-bold text-[var(--color-text-main)]">{row.name}</td>
                            <td className="px-6 py-4 text-sm text-[var(--color-text-muted)]">{row.freq}</td>
                            <td className="px-6 py-4 text-sm text-[var(--color-text-muted)]">{row.recipient}</td>
                            <td className="px-6 py-4 text-sm text-[var(--color-text-muted)]">{row.notes}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            </motion.div>
          );
        })}
      </div>
    </div>
  );
};

export default AuditCharter;

import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { useUser } from '../context/UserContext';
import { usePreferences } from '../context/PreferencesContext';
import api from '../services/api';
import { useTranslation } from 'react-i18next';
import { AuditEvidence as AuditEvidenceType, AuditPlan, AuditFinding } from '../types';
import { 
  FileText, Search, Plus, Download, Trash2, 
  Image as ImageIcon, Mail, FileCode, FileSignature, AlertCircle, Eye, Edit, FolderOpen
} from 'lucide-react';
import { motion } from 'motion/react';
import { UserRole } from '../constants';
import Modal from '../components/Modal';
import PdfViewer from '../components/PdfViewer';
import { useFormat } from '../services/formatService';
import logger from '../utils/logger';

const AuditEvidence: React.FC = () => {
  const { token } = useAuth();
  const { language } = usePreferences();
  const { user } = useUser();
  const { t } = useTranslation();
  const { formatDate, formatNumber } = useFormat();
  const [evidence, setEvidence] = useState<AuditEvidenceType[]>([]);
  const [audits, setAudits] = useState<AuditPlan[]>([]);
  const [findings, setFindings] = useState<AuditFinding[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedAudit, setSelectedAudit] = useState<string>('all');
  const [showForm, setShowForm] = useState(false);
  
  // Edit State
  const [editingId, setEditingId] = useState<string | number | null>(null);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<string | number | null>(null);

  // Preview State
  const [previewItem, setPreviewItem] = useState<AuditEvidenceType | null>(null);

  // Form State
  const [formData, setFormData] = useState<Partial<AuditEvidenceType>>({
    type: 'Document'
  });
  const [file, setFile] = useState<File | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [evRes, audRes, findRes] = await Promise.all([
        api.get('/audit-evidence'),
        api.get('/audit-plans'),
        api.get('/audit-findings')
      ]);
      
      setEvidence(evRes.data.data || (Array.isArray(evRes.data) ? evRes.data : []));
      setAudits(audRes.data.data || (Array.isArray(audRes.data) ? audRes.data : []));
      setFindings(findRes.data.data || (Array.isArray(findRes.data) ? findRes.data : []));
    } catch (err) {
      logger.error('Operation failed', err);
    } finally {
      setLoading(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    if (!file && !editingId) {
      setError(t('evidence.pleaseSelectFile'));
      return;
    }

    const submitData = async (base64Data?: string) => {
      const payload: any = {
        audit_id: formData.audit_id,
        finding_id: formData.finding_id,
        type: formData.type,
        description: formData.description || '',
        uploaded_by: user?.name || 'Unknown',
        upload_date: new Date().toISOString().split('T')[0],
      };

      if (base64Data && file) {
        payload.file_name = file.name;
        payload.file_data = base64Data;
      }

      try {
        const url = editingId ? `/audit-evidence/${editingId}` : '/audit-evidence';
        
        if (editingId) {
          await api.put(url, payload);
        } else {
          await api.post(url, payload);
        }

        fetchData();
        setShowForm(false);
        setFormData({ type: 'Document' });
        setFile(null);
        setEditingId(null);
      } catch (err: any) {
        logger.error('Operation failed', err);
        const apiError = err.response?.data?.error;
        if (typeof apiError === 'string') {
          setError(apiError);
        } else if (apiError && typeof apiError === 'object') {
          setError(apiError.message || t('evidence.operationFailed'));
        } else {
          setError(t('evidence.operationFailed'));
        }
      }
    };

    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => submitData(reader.result as string);
      reader.readAsDataURL(file);
    } else {
      submitData();
    }
  };

  const handleEdit = (ev: AuditEvidenceType) => {
    setFormData({
      audit_id: ev.audit_id,
      finding_id: ev.finding_id,
      type: ev.type,
      description: ev.description
    });
    setEditingId(ev.id || null);
    setShowForm(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDelete = async (id: string | number) => {
    setItemToDelete(id);
    setIsDeleteModalOpen(true);
  };

  const confirmDelete = async () => {
    if (itemToDelete === null) return;
    try {
      await api.delete(`/audit-evidence/${itemToDelete}`);
      fetchData();
      setIsDeleteModalOpen(false);
      setItemToDelete(null);
    } catch (err) {
      logger.error('Operation failed', err);
    }
  };

  const handleDownload = (ev: AuditEvidenceType) => {
    if (!ev.file_data) {
      setError(t('evidence.noFileDataAvailable'));
      return;
    }
    const a = document.createElement('a');
    a.href = ev.file_data;
    a.download = ev.file_name;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  const filteredEvidence = evidence.filter(e => {
    const matchesSearch = (e.description?.toLowerCase() || '').includes(searchTerm.toLowerCase()) || 
                          (e.file_name?.toLowerCase() || '').includes(searchTerm.toLowerCase());
    const matchesAudit = selectedAudit === 'all' || (e.audit_id && e.audit_id.toString() === selectedAudit);
    return matchesSearch && matchesAudit;
  });

  const getIcon = (type: string) => {
    switch (type) {
      case 'Document': return <FileText size={24} />;
      case 'Email': return <Mail size={24} />;
      case 'Screenshot': return <ImageIcon size={24} />;
      case 'System Log': return <FileCode size={24} />;
      case 'Contract': return <FileSignature size={24} />;
      default: return <FileText size={24} />;
    }
  };

  const canEdit = user?.role === UserRole.ADMIN || user?.role === UserRole.INTERNAL_AUDITOR;

  return (
    <div className="space-y-10">
      <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-6">
        <div className="flex items-center gap-6">
          <div className="w-12 h-12 sm:w-16 sm:h-16 bg-[var(--color-primary)] rounded-2xl flex items-center justify-center text-white shadow-lg shadow-[var(--color-primary)]/20">
            <FolderOpen size={32} />
          </div>
          <div>
            <h2 className="text-2xl sm:text-4xl font-bold text-[var(--color-text-main)] tracking-tight">{t('evidence.title')}</h2>
            <p className="text-sm text-[var(--color-text-muted)] font-bold mt-2">{t('evidence.secureDocumentRepository')}</p>
          </div>
        </div>
        
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-4">
          <select 
            className="input-field min-w-[200px]"
            value={selectedAudit}
            onChange={(e) => setSelectedAudit(e.target.value)}
          >
            <option value="all">{t('evidence.allAudits')}</option>
            {audits.map(a => (
              <option key={a.id} value={a.id}>{a.title}</option>
            ))}
          </select>
          <div className="relative flex-1 min-w-[250px]">
            <Search className="absolute start-5 top-1/2 -translate-y-1/2 text-[var(--color-text-muted)]" size={20} />
            <input 
              type="text"
              placeholder={t('common.search')}
              className="input-field !ps-14"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          {canEdit && (
            <button 
              onClick={() => {
                setEditingId(null);
                setFormData({ type: 'Document' });
                setFile(null);
                setError(null);
                setShowForm(true);
              }} 
              className="btn-primary flex items-center justify-center gap-3 whitespace-nowrap"
            >
              <Plus size={24} />
              <span>{t('evidence.uploadEvidence')}</span>
            </button>
          )}
        </div>
      </div>

      {error && !showForm && (
        <div className="p-4 bg-rose-50 text-rose-600 rounded-xl border border-rose-100 font-bold text-sm">
          {error}
        </div>
      )}

      {showForm && canEdit && (
        <motion.div 
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          className="glass-card p-10 border-[var(--color-primary)]/20"
        >
          <h3 className="text-xl font-bold text-[var(--color-text-main)] mb-8">
            {editingId ? (t('evidence.editEvidence')) : (t('evidence.uploadNewEvidence'))}
          </h3>
          <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-3">
              <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('evidence.auditEngagement')}</label>
              <select 
                required
                className="input-field"
                value={formData.audit_id || ''}
                onChange={e => setFormData({...formData, audit_id: e.target.value})}
              >
                <option value="">{t('evidence.selectAudit')}</option>
                {audits.map(a => (
                  <option key={a.id} value={a.id}>{a.title}</option>
                ))}
              </select>
            </div>
            
            <div className="space-y-3">
              <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('evidence.relatedFindingOptional')}</label>
              <select 
                className="input-field"
                value={formData.finding_id || ''}
                onChange={e => setFormData({...formData, finding_id: e.target.value})}
              >
                <option value="">{t('evidence.none')}</option>
                {findings.filter(f => !formData.audit_id || String(f.audit_id) === String(formData.audit_id)).map(f => (
                  <option key={f.id} value={f.id}>{(f.condition || '').substring(0, 50)}...</option>
                ))}
              </select>
            </div>

            <div className="space-y-3">
              <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('evidence.evidenceType')}</label>
              <select 
                required
                className="input-field"
                value={formData.type || ''}
                onChange={e => setFormData({...formData, type: e.target.value as any})}
              >
                <option value="Document">{t('evidence.document')}</option>
                <option value="Email">{t('evidence.emailType')}</option>
                <option value="Screenshot">{t('evidence.screenshot')}</option>
                <option value="System Log">{t('evidence.systemLog')}</option>
                <option value="Contract">{t('evidence.contract')}</option>
              </select>
            </div>

            <div className="space-y-3">
              <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">
                {t('evidence.fileAttachment')} {editingId && (t('evidence.optional'))}
              </label>
              <input 
                type="file" 
                required={!editingId}
                onChange={handleFileChange}
                className="input-field file:me-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-xs file:font-bold file:bg-[var(--color-primary)]/10 file:text-[var(--color-primary)] hover:file:bg-[var(--color-primary)]/20"
              />
            </div>

            <div className="md:col-span-2 space-y-3">
              <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('evidence.description')}</label>
              <textarea 
                required
                className="input-field min-h-[100px]"
                value={formData.description || ''}
                onChange={e => setFormData({...formData, description: e.target.value})}
                placeholder={t('evidence.describeEvidence')}
              />
            </div>

            <div className="md:col-span-2 flex justify-end gap-4 mt-4">
              <button 
                type="button" 
                onClick={() => {
                  setShowForm(false);
                  setEditingId(null);
                  setFormData({ type: 'Document' });
                  setFile(null);
                }} 
                className="px-8 py-4 rounded-xl font-bold text-[var(--color-text-muted)] hover:bg-[var(--color-bg-main)] transition-all uppercase tracking-widest text-xs"
              >
                {t('common.cancel')}
              </button>
              <button type="submit" className="btn-primary">
                {editingId ? t('common.save') : (t('evidence.upload'))}
              </button>
            </div>
          </form>
        </motion.div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
        {filteredEvidence.map((ev, idx) => {
          const audit = audits.find(a => String(a.id) === String(ev.audit_id));
          return (
            <motion.div 
              key={ev.id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: idx * 0.05 }}
              className="glass-card p-8 group hover:border-[var(--color-primary)]/30 transition-all flex flex-col"
            >
              <div className="flex items-start justify-between mb-6">
                <div className="w-14 h-14 rounded-2xl bg-[var(--color-bg-soft)] flex items-center justify-center text-[var(--color-primary)] shadow-inner overflow-hidden">
                  {ev.file_data && (ev.file_data.startsWith('data:image') || /\.(jpg|jpeg|png|gif|webp)$/i.test(ev.file_name)) ? (
                    <img 
                      src={ev.file_data} 
                      alt={ev.file_name} 
                      className="w-full h-full object-cover" 
                      referrerPolicy="no-referrer"
                    />
                  ) : (
                    getIcon(ev.type)
                  )}
                </div>
                <div className="flex gap-2">
                  <button 
                    onClick={() => setPreviewItem(ev)}
                    className="w-10 h-10 rounded-xl bg-[var(--color-bg-soft)] text-[var(--color-text-muted)] hover:text-blue-600 hover:bg-[var(--color-primary-light)] flex items-center justify-center transition-all"
                    title={t('evidence.preview')}
                  >
                    <Eye size={18} />
                  </button>
                  <button onClick={() => handleDownload(ev)} className="w-10 h-10 rounded-xl bg-[var(--color-bg-soft)] text-[var(--color-text-muted)] hover:text-[var(--color-primary)] hover:bg-[var(--color-primary)]/10 flex items-center justify-center transition-all" title={t('evidence.download')}>
                    <Download size={18} />
                  </button>
                  {canEdit && (
                    <>
                      <button 
                        onClick={() => handleEdit(ev)}
                        className="w-10 h-10 rounded-xl bg-[var(--color-bg-soft)] text-[var(--color-text-muted)] hover:text-amber-600 hover:bg-amber-50 flex items-center justify-center transition-all"
                        title={t('common.edit')}
                      >
                        <Edit size={18} />
                      </button>
                      <button onClick={() => ev.id && handleDelete(ev.id)} className="w-10 h-10 rounded-xl bg-[var(--color-bg-soft)] text-[var(--color-text-muted)] hover:text-rose-600 hover:bg-rose-50 flex items-center justify-center transition-all" title={t('common.delete')}>
                        <Trash2 size={18} />
                      </button>
                    </>
                  )}
                </div>
              </div>

              <h3 className="text-lg font-bold text-[var(--color-text-main)] mb-2 line-clamp-2" title={ev.file_name}>
                {ev.file_name}
              </h3>
              <p className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-6">
                {ev.type} • {formatDate(ev.upload_date)}
              </p>

              <div className="flex-1">
                <p className="text-sm text-[var(--color-text-muted)] font-medium line-clamp-3 mb-6">
                  {ev.description}
                </p>
              </div>

              <div className="space-y-3 pt-6 border-t border-[var(--color-border-soft)]">
                <div className="flex items-center gap-3">
                  <div className="w-2 h-2 rounded-full bg-[var(--color-primary)] shrink-0" />
                  <p className="text-xs font-bold text-[var(--color-text-muted)] truncate">
                    {t('common.auditPlan')}: {audit?.title || (t('evidence.unknown'))}
                  </p>
                </div>
                <div className="flex items-center gap-3">
                  <div className="w-2 h-2 rounded-full bg-slate-300 shrink-0" />
                  <p className="text-xs font-bold text-[var(--color-text-muted)] truncate">
                    {t('evidence.uploadedBy')}{ev.uploaded_by}
                  </p>
                </div>
                {ev.finding_id && (
                  <div className="flex items-center gap-3">
                    <div className="w-2 h-2 rounded-full bg-rose-400 shrink-0" />
                    <p className="text-xs font-bold text-rose-500 truncate">
                      {t('evidence.linkedToFinding')}{formatNumber(ev.finding_id)}
                    </p>
                  </div>
                )}
              </div>
            </motion.div>
          );
        })}
        
        {filteredEvidence.length === 0 && !loading && (
          <div className="col-span-full glass-card p-20 text-center">
            <div className="w-24 h-24 bg-[var(--color-bg-soft)] rounded-2xl flex items-center justify-center mx-auto mb-8 text-[var(--color-border-strong)] shadow-inner">
              <AlertCircle size={48} />
            </div>
            <h3 className="text-2xl font-bold text-[var(--color-text-main)] mb-3 tracking-tight">{t('evidence.noEvidenceFound')}</h3>
            <p className="text-[var(--color-text-muted)] font-bold uppercase tracking-widest text-xs">{t('evidence.uploadDocumentsToBuildTrail')}</p>
          </div>
        )}
      </div>

      <Modal
        isOpen={isDeleteModalOpen}
        onClose={() => {
          setIsDeleteModalOpen(false);
          setItemToDelete(null);
        }}
        title={t('plan.deleteConfirm')}
      >
        <div className="space-y-6">
          <p className="text-[var(--color-text-muted)] font-medium">
            {t('plan.deleteMessage')}
          </p>
          <div className="flex justify-end gap-4">
            <button
              onClick={() => {
                setIsDeleteModalOpen(false);
                setItemToDelete(null);
              }}
              className="px-6 py-3 rounded-xl bg-[var(--color-bg-main)] text-[var(--color-text-muted)] font-bold hover:bg-[var(--color-bg-main)] transition-colors"
            >
              {t('common.cancel')}
            </button>
            <button
              onClick={confirmDelete}
              className="px-6 py-3 rounded-xl bg-rose-500 text-white font-bold hover:bg-rose-600 transition-colors shadow-lg shadow-rose-200"
            >
              {t('common.delete')}
            </button>
          </div>
        </div>
      </Modal>

      <Modal
        isOpen={!!previewItem}
        onClose={() => setPreviewItem(null)}
        title={previewItem?.file_name || (t('evidence.preview'))}
        size="full"
      >
        <div className="w-full h-full bg-[var(--color-bg-soft)] rounded-xl overflow-hidden">
          {previewItem?.file_data ? (
            previewItem.file_data.startsWith('data:image') || /\.(jpg|jpeg|png|gif|webp)$/i.test(previewItem.file_name) ? (
              <img 
                src={previewItem.file_data} 
                alt={previewItem.file_name} 
                className="max-w-full max-h-full object-contain mx-auto" 
                referrerPolicy="no-referrer"
              />
            ) : previewItem.file_data.startsWith('data:application/pdf') || /\.pdf$/i.test(previewItem.file_name) || (previewItem.file_data && !previewItem.file_data.startsWith('data:') && !previewItem.file_data.startsWith('http') && !previewItem.file_data.startsWith('/') && previewItem.file_data.length > 100) ? (
              <div className="w-full h-full">
                <PdfViewer url={previewItem.file_data} />
              </div>
            ) : (
              <div className="text-center p-10">
                <FileText size={48} className="mx-auto text-[var(--color-border-strong)] mb-4" />
                <p className="text-[var(--color-text-muted)] font-bold">{t('evidence.previewNotAvailableForThisFile')}</p>
                <button 
                  onClick={() => previewItem && handleDownload(previewItem)}
                  className="mt-4 btn-primary"
                >
                  {t('tasks.downloadFile')}
                </button>
              </div>
            )
          ) : (
            <p className="text-[var(--color-text-muted)]">{t('evidence.noFileDataAvailable')}</p>
          )}
        </div>
      </Modal>
    </div>
  );
};

export default AuditEvidence;

import React, { useState, useEffect } from 'react';
import { useAppContext } from '../context/AppContext';
import { useAuth } from '../context/AuthContext';
import { useTranslation } from 'react-i18next';
import { AuditFinding, AuditPlan } from '../types';
import { Plus, AlertTriangle, FolderOpen, ChevronDown, ChevronLeft } from 'lucide-react';
import { motion, AnimatePresence } from 'motion/react';
import { useAuditFindings } from '../hooks/useAuditFindings';
import { RiskLevel } from '../constants';
import toast from 'react-hot-toast';
import api from '../services/api';
import logger from '../utils/logger';

import Modal from '../components/Modal';
import FindingForm from '../components/FindingForm';
import Badge from '../components/Badge';
import LoadingSpinner from '../components/LoadingSpinner';
import FindingCard from '../components/FindingCard';

const AuditFindings: React.FC = () => {
  const { setActiveTab } = useAppContext();
  const { token } = useAuth();
  const { t, i18n } = useTranslation();
  const isRTL = i18n.language === 'ar';

  const { findings, loading, fetchFindings } = useAuditFindings();
  const [plans, setPlans] = useState<AuditPlan[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingFinding, setEditingFinding] = useState<AuditFinding | null>(null);
  const [expandedPlans, setExpandedPlans] = useState<Set<string>>(new Set());

  useEffect(() => {
    api.get('/audit-plans')
      .then(res => setPlans(Array.isArray(res.data) ? res.data : (res.data.data || [])))
      .catch(() => setPlans([]));
  }, []);

  const handleAddSuccess = () => {
    toast.success(t(editingFinding ? 'updateSuccess' : 'createSuccess'));
    setIsModalOpen(false);
    setEditingFinding(null);
    fetchFindings();
  };

  const handleEdit = (finding: AuditFinding) => {
    setEditingFinding(finding);
    setIsModalOpen(true);
  };

  const togglePlan = (planId: string) => {
    setExpandedPlans(prev => {
      const next = new Set(prev);
      next.has(planId) ? next.delete(planId) : next.add(planId);
      return next;
    });
  };

  // Group findings by plan (audit_id)
  const findingsByPlan: Record<string, AuditFinding[]> = {};
  (Array.isArray(findings) ? findings : []).forEach(f => {
    const planId = String(f.audit_id);
    if (!findingsByPlan[planId]) findingsByPlan[planId] = [];
    findingsByPlan[planId].push(f);
  });

  const getPlanInfo = (planId: string) => plans.find(p => String(p.id) === planId);

  return (
    <div className="space-y-10">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div className="flex items-center gap-6">
          <div className="w-12 h-12 sm:w-16 sm:h-16 bg-[var(--color-primary)] rounded-2xl flex items-center justify-center text-white shadow-lg shadow-[var(--color-primary)]/20">
            <AlertTriangle size={32} />
          </div>
          <div>
            <h2 className="text-2xl sm:text-4xl font-bold text-[var(--color-text-main)] tracking-tight">{t('findings.title')}</h2>
            <p className="text-sm text-[var(--color-text-muted)] font-bold mt-2">{t('findings.professionalFramework')}</p>
          </div>
        </div>
        <motion.button
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          onClick={() => setIsModalOpen(true)}
          className="btn-primary flex items-center justify-center gap-3"
        >
          <Plus size={24} />
          <span>{t('plan.add')}</span>
        </motion.button>
      </div>

      {/* Add/Edit Modal */}
      <Modal
        isOpen={isModalOpen}
        onClose={() => { setIsModalOpen(false); setEditingFinding(null); }}
        title={(editingFinding ? t('common.edit') : t('plan.add')) + ' ' + t('findings.title')}
      >
        <FindingForm
          onSuccess={handleAddSuccess}
          onCancel={() => { setIsModalOpen(false); setEditingFinding(null); }}
          initialData={editingFinding}
        />
      </Modal>

      {/* Content */}
      {loading ? (
        <div className="glass-card p-20">
          <LoadingSpinner size="lg" />
          <p className="text-center text-[var(--color-text-muted)] font-bold mt-4 uppercase tracking-widest text-xs">{t('findings.loadingFindings')}</p>
        </div>
      ) : Object.keys(findingsByPlan).length === 0 ? (
        <div className="glass-card p-20 text-center">
          <AlertTriangle size={48} className="mx-auto text-[var(--color-border-strong)] mb-4" />
          <p className="text-[var(--color-text-muted)] font-bold">{t('common.noFindings') || 'لا توجد ملاحظات'}</p>
        </div>
      ) : (
        <div className="space-y-6">
          {Object.entries(findingsByPlan).map(([planId, planFindings]) => {
            const plan = getPlanInfo(planId);
            const isExpanded = expandedPlans.has(planId);
            return (
              <div key={planId} className="glass-card overflow-hidden">
                {/* Folder Header */}
                <button
                  onClick={() => togglePlan(planId)}
                  className="w-full flex items-center justify-between p-6 hover:bg-[var(--color-primary)]/5 transition-colors cursor-pointer"
                >
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-[var(--color-primary)]/10 rounded-xl flex items-center justify-center">
                      <FolderOpen size={24} className="text-[var(--color-primary)]" />
                    </div>
                    <div className="text-start">
                      <h3 className="text-lg font-bold text-[var(--color-text-main)]">
                        {plan?.title || `${t('common.auditPlan')} #${planId.slice(0, 8)}`}
                      </h3>
                      <p className="text-xs text-[var(--color-text-muted)] font-bold mt-0.5">
                        {plan?.plan_code || ''} • {planFindings.length} {t('findings.title')}
                      </p>
                    </div>
                  </div>
                  <div className="flex items-center gap-3">
                    <Badge type="status" value={plan?.status || 'Planned'} />
                    {isExpanded
                      ? <ChevronDown size={20} className="text-[var(--color-text-muted)]" />
                      : <ChevronLeft size={20} className="text-[var(--color-text-muted)]" />
                    }
                  </div>
                </button>

                {/* Findings inside folder */}
                <AnimatePresence>
                  {isExpanded && (
                    <motion.div
                      initial={{ height: 0, opacity: 0 }}
                      animate={{ height: 'auto', opacity: 1 }}
                      exit={{ height: 0, opacity: 0 }}
                      transition={{ duration: 0.3 }}
                      className="border-t border-[var(--color-border-soft)] overflow-hidden"
                    >
                      <div className="p-6 space-y-6">
                        {planFindings.map((finding, idx) => (
                          <FindingCard
                            key={finding.id}
                            finding={finding}
                            idx={idx}
                            isRTL={isRTL}
                            t={t}
                            handleEdit={handleEdit}
                            setActiveTab={setActiveTab}
                            onStatusChanged={fetchFindings}
                          />
                        ))}
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default AuditFindings;

import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useAuditPlans } from '../hooks/useAuditPlans';
import { auditService } from '../services/auditService';
import { AuditPlan } from '../types';
import { Plus, Search, Calendar, Edit, Trash2, Archive } from 'lucide-react';
import { motion } from 'motion/react';
import { useFormat } from '../services/formatService';
import { useDebounce } from '../hooks/useDebounce';
import { AuditStatus } from '../constants';
import api from '../services/api';
import toast from 'react-hot-toast';
import logger from '../utils/logger';

import Modal from '../components/Modal';
import InteractiveIcon from '../components/InteractiveIcon';
import AuditPlanForm from '../components/AuditPlanForm';
import Badge from '../components/Badge';
import LoadingSpinner from '../components/LoadingSpinner';
import Pagination from '../components/Pagination';

const AuditPlanModule: React.FC = () => {
  const { t } = useTranslation();
  const { formatDate, formatNumber } = useFormat();
  const [searchTerm, setSearchTerm] = useState('');
  const debouncedSearchTerm = useDebounce(searchTerm, 500);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(15);
  const { plans, loading, pagination, fetchPlans } = useAuditPlans({ page, pageSize, search: debouncedSearchTerm || undefined });

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedPlan, setSelectedPlan] = useState<AuditPlan | null>(null);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [planToDelete, setPlanToDelete] = useState<string | number | null>(null);
  const [isArchiveModalOpen, setIsArchiveModalOpen] = useState(false);
  const [planToArchive, setPlanToArchive] = useState<any | null>(null);
  const [archiving, setArchiving] = useState(false);

  const handleAddSuccess = () => {
    toast.success(t(selectedPlan ? 'updateSuccess' : 'createSuccess'));
    setIsModalOpen(false);
    setSelectedPlan(null);
    fetchPlans({ page, pageSize, search: searchTerm });
  };

  const confirmDelete = async () => {
    if (!planToDelete) return;
    try {
      await auditService.deletePlan(planToDelete);
      toast.success(t('deleteSuccess'));
      fetchPlans({ page, pageSize, search: searchTerm });
      setIsDeleteModalOpen(false);
      setPlanToDelete(null);
    } catch (err: any) {
      logger.error('delete failed', err);
      toast.error(t('errorOccurred'));
    }
  };

  const confirmArchive = async () => {
    if (!planToArchive?.id) return;
    setArchiving(true);
    try {
      await api.post(`/audit-plans/${planToArchive.id}/archive`);
      toast.success(t('archive.success'));
      fetchPlans({ page, pageSize, search: searchTerm });
      setIsArchiveModalOpen(false);
      setPlanToArchive(null);
    } catch (err: any) {
      const msg = err.response?.data?.error?.message || err.response?.data?.error || t('errorOccurred');
      toast.error(typeof msg === 'string' ? msg : t('errorOccurred'));
    } finally {
      setArchiving(false);
    }
  };

  const getQuarterLabel = (q: string) => {
    if (!q || q === 'Annual') return t('plans.quarterOptions.Annual');
    return t(`plans.quarterOptions.${q}`);
  };

  return (
    <div className="space-y-10">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div className="flex items-center gap-6">
          <div className="w-12 h-12 sm:w-16 sm:h-16 bg-[var(--color-primary)] rounded-2xl flex items-center justify-center text-white shadow-lg shadow-[var(--color-primary)]/20">
            <Calendar size={32} />
          </div>
          <div>
            <h2 className="text-2xl sm:text-4xl font-bold text-[var(--color-text-main)] tracking-tight">{t('common.auditPlan')}</h2>
            <p className="text-sm text-[var(--color-text-muted)] font-bold mt-2">{t('plan.strategicInternalAuditRoadmap')}</p>
          </div>
        </div>
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-4">
          <div className="relative flex-1 min-w-[300px]">
            <Search className="absolute start-5 top-1/2 -translate-y-1/2 text-[var(--color-text-muted)]" size={20} />
            <input type="text" placeholder={t('plan.search')} className="input-field !ps-14" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
          </div>
          <motion.button whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }}
            onClick={() => { setSelectedPlan(null); setIsModalOpen(true); }}
            className="btn-primary flex items-center justify-center gap-3 whitespace-nowrap">
            <Plus size={24} /><span>{t('plan.add')}</span>
          </motion.button>
        </div>
      </div>

      {/* Modals */}
      <Modal isOpen={isModalOpen} onClose={() => { setIsModalOpen(false); setSelectedPlan(null); }} title={selectedPlan ? t('plan.editPlan') : t('plan.addPlan')}>
        <AuditPlanForm onSuccess={handleAddSuccess} onCancel={() => { setIsModalOpen(false); setSelectedPlan(null); }} initialData={selectedPlan} />
      </Modal>

      <Modal isOpen={isDeleteModalOpen} onClose={() => { setIsDeleteModalOpen(false); setPlanToDelete(null); }} title={t('plan.deleteConfirm')}>
        <div className="space-y-6">
          <p className="text-[var(--color-text-main)] font-medium">{t('plan.deleteMessage')}</p>
          <div className="flex justify-end gap-4">
            <button onClick={() => { setIsDeleteModalOpen(false); setPlanToDelete(null); }} className="px-6 py-3 rounded-2xl bg-[var(--color-bg-main)] text-[var(--color-text-main)] font-bold hover:bg-[var(--color-border-soft)] transition-colors border border-[var(--color-border-soft)]">{t('common.cancel')}</button>
            <button onClick={confirmDelete} className="px-6 py-3 rounded-2xl bg-[var(--color-danger)] text-white font-bold hover:bg-[var(--color-danger)]/90 transition-colors">{t('plan.delete')}</button>
          </div>
        </div>
      </Modal>

      <Modal isOpen={isArchiveModalOpen} onClose={() => { setIsArchiveModalOpen(false); setPlanToArchive(null); }} title={t('archive.confirmTitle')}>
        <div className="space-y-6">
          <p className="text-[var(--color-text-main)] font-medium">{t('archive.action')}: <span className="font-bold text-[var(--color-primary)]">{planToArchive?.title}</span></p>
          <p className="text-sm text-[var(--color-text-muted)]">{t('archive.openItemsError', { count: 0 })}</p>
          <div className="flex justify-end gap-4">
            <button onClick={() => { setIsArchiveModalOpen(false); setPlanToArchive(null); }} className="px-6 py-3 rounded-2xl bg-[var(--color-bg-main)] text-[var(--color-text-main)] font-bold hover:bg-[var(--color-border-soft)] transition-colors border border-[var(--color-border-soft)]">{t('common.cancel')}</button>
            <button onClick={confirmArchive} disabled={archiving} className="px-6 py-3 rounded-2xl bg-amber-500 text-white font-bold hover:bg-amber-600 transition-colors disabled:opacity-50 flex items-center gap-2">
              <Archive size={16} />{archiving ? t('common.loading') : t('archive.action')}
            </button>
          </div>
        </div>
      </Modal>

      {/* Table */}
      {loading ? (
        <div className="glass-card p-20"><LoadingSpinner size="lg" /><p className="text-center text-[var(--color-text-muted)] font-bold mt-4 uppercase tracking-widest text-xs">{t('plan.loadingAuditPlans')}</p></div>
      ) : (
        <div className="glass-card overflow-hidden">
          <div className="overflow-x-auto custom-scrollbar">
            <table className="w-full text-start border-collapse">
              <thead>
                <tr className="bg-[var(--color-bg-main)] border-b border-[var(--color-border-soft)]">
                  {['plan.code','plan.title','plans.year','plans.quarter','plan.department','plan.type','plan.riskRating','plan.startDate','plan.status',''].map((k,i) => (
                    <th key={i} className="px-6 py-5 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em]">{k ? t(k) : ''}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-[var(--color-border-soft)]">
                {(Array.isArray(plans) ? plans : []).map((plan: any, idx: number) => (
                  <motion.tr key={plan.id} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: idx * 0.04 }}
                    className={`hover:bg-[var(--color-primary)]/5 transition-colors group cursor-pointer ${plan.is_archived ? 'opacity-60' : ''}`}>
                    <td className="px-6 py-4 text-xs font-bold text-[var(--color-text-muted)] tracking-widest">{plan.plan_code || `#${formatNumber(plan.id)}`}</td>
                    <td className="px-6 py-4">
                      <p className="text-sm font-bold text-[var(--color-text-main)] group-hover:text-[var(--color-primary)]">{plan.title}</p>
                      <p className="text-[10px] text-[var(--color-text-muted)] font-bold mt-0.5 uppercase tracking-wider">{plan.lead_auditor}</p>
                    </td>
                    <td className="px-6 py-4 text-sm font-bold text-[var(--color-text-main)]">{plan.year || '—'}</td>
                    <td className="px-6 py-4 text-sm text-[var(--color-text-muted)]">{plan.quarter ? getQuarterLabel(plan.quarter) : '—'}</td>
                    <td className="px-6 py-4 text-sm font-bold text-[var(--color-text-main)]">{plan.department}</td>
                    <td className="px-6 py-4"><span className="inline-flex items-center px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest bg-[var(--color-bg-main)] text-[var(--color-text-muted)] border border-[var(--color-border-soft)]">{t(`plan.${plan.type?.toLowerCase() || ''}`)}</span></td>
                    <td className="px-6 py-4"><Badge type="risk" value={plan.risk_rating} /></td>
                    <td className="px-6 py-4 text-sm text-[var(--color-text-muted)]">{formatDate(plan.planned_start_date)}</td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2">
                        <span className={`w-2 h-2 rounded-full shrink-0 ${plan.status === AuditStatus.CLOSED ? 'bg-[var(--color-success)]' : plan.status === AuditStatus.FIELDWORK ? 'bg-[var(--color-primary)]' : 'bg-[var(--color-border-soft)]'}`} />
                        <Badge type="status" value={plan.status} />
                      </div>
                    </td>
                    <td className="px-6 py-4 text-end">
                      <div className="flex items-center justify-end gap-1">
                        {!plan.is_archived && <InteractiveIcon icon={Archive} onClick={() => { setPlanToArchive(plan); setIsArchiveModalOpen(true); }} tooltip={t('archive.action')} variant="ghost" size={14} className="!p-2 !text-amber-500" />}
                        <InteractiveIcon icon={Edit} onClick={() => { setSelectedPlan(plan); setIsModalOpen(true); }} tooltip={t('plan.edit')} variant="ghost" size={14} className="!p-2" />
                        <InteractiveIcon icon={Trash2} onClick={() => { setPlanToDelete(plan.id!); setIsDeleteModalOpen(true); }} tooltip={t('plan.delete')} variant="danger" size={14} className="!p-2" />
                      </div>
                    </td>
                  </motion.tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      <Pagination currentPage={page} totalPages={pagination.totalPages} onPageChange={(p) => setPage(p)} pageSize={pageSize} onPageSizeChange={(ps) => { setPageSize(ps); setPage(1); }} totalItems={pagination.total} />
    </div>
  );
};

export default AuditPlanModule;

import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { useUser } from '../context/UserContext';
import { useTranslation } from 'react-i18next';
import { AuditProgram, AuditProcedure } from '../types';
import { motion } from 'motion/react';
import { useFormat } from '../services/formatService';
import api from '../services/api';
import { AuditStatus, AuditType, ControlTestType } from '../constants';
import toast from 'react-hot-toast';
import logger from '../utils/logger';

// Sub-components
import AuditProgramHeader from './AuditProgram/AuditProgramHeader';
import AuditProgramGrid from './AuditProgram/AuditProgramGrid';
import AuditProgramEditor from './AuditProgram/AuditProgramEditor';
import AuditProgramProceduresModal from './AuditProgram/AuditProgramProceduresModal';
import Modal from '../components/Modal';
import { useDepartments } from '../hooks/useDepartments';

const AuditProgramLibrary: React.FC = () => {
  const { token } = useAuth();
  const { user } = useUser();
  const { t, i18n } = useTranslation();
  const isRTL = i18n.language === 'ar';
  const { formatDate } = useFormat();
  
  const [programs, setPrograms] = useState<AuditProgram[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState('All');
  const [filterStatus, setFilterStatus] = useState('All');
  
  const [isEditing, setIsEditing] = useState(false);
  const [currentProgram, setCurrentProgram] = useState<Partial<AuditProgram> | null>(null);
  const [procedures, setProcedures] = useState<AuditProcedure[]>([]);
  const [isViewingProcedures, setIsViewingProcedures] = useState(false);
  const { departments } = useDepartments();
  const [instructions, setInstructions] = useState<any[]>([]);
  const [laws, setLaws] = useState<any[]>([]);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const [showDeleteConfirm, setShowDeleteConfirm] = useState<{id: string | number | null, type: 'program' | 'procedure'}>({id: null, type: 'program'});

  useEffect(() => {
    fetchPrograms();
    
    if (token) {
      api.get('/compliance?source_type=cbi_instruction', { headers: { 'Authorization': `Bearer ${token}` } })
        .then(res => setInstructions(Array.isArray(res.data) ? res.data : (res.data.data || [])))
        .catch(() => setInstructions([]));

      api.get('/compliance?source_type=law', { headers: { 'Authorization': `Bearer ${token}` } })
        .then(res => setLaws(Array.isArray(res.data) ? res.data : (res.data.data || [])))
        .catch(() => setLaws([]));
    }
  }, [token]);

  const fetchPrograms = async () => {
    try {
      const res = await api.get('/audit-programs', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      setPrograms(Array.isArray(res.data) ? res.data : (res.data.data || []));
    } catch (err) {
      logger.error('Operation failed', err);
      setPrograms([]);
    } finally {
      setLoading(false);
    }
  };

  const fetchProcedures = async (programId: string | number) => {
    try {
      const res = await api.get(`/audit-procedures`, {
        params: { program_id: programId, pageSize: 500 }
      });
      const data = res.data.data || (Array.isArray(res.data) ? res.data : []);
      setProcedures(data);
    } catch (err) {
      logger.error('Operation failed', err);
    }
  };

  const handleSaveProgram = async () => {
    if (!currentProgram?.program_title || !currentProgram?.program_code || isSaving) return;
    
    setIsSaving(true);
    try {
      const data = {
        ...currentProgram,
        created_by: currentProgram.id ? currentProgram.created_by : user?.username,
        version_number: currentProgram.id ? currentProgram.version_number : 1,
        status: currentProgram.id ? currentProgram.status : AuditStatus.DRAFT
      };

      if (currentProgram.id) {
        try {
          await api.put(`/audit-programs/${currentProgram.id}`, data, {
            headers: { 'Authorization': `Bearer ${token}` }
          });
          toast.success(t('updateSuccess'));
        } catch (err: any) {
          if (err.response?.status === 404) {
            toast.error(t('program.programNotFound'));
            setIsEditing(false);
            fetchPrograms();
            return;
          }
          throw err;
        }
      } else {
        const res = await api.post('/audit-programs', data, {
          headers: { 'Authorization': `Bearer ${token}` }
        });
        setCurrentProgram(res.data);
        toast.success(t('createSuccess'));
      }
      
      fetchPrograms();
      setIsEditing(false);
    } catch (err) {
      logger.error('Operation failed', err);
      toast.error(t('errorOccurred'));
    } finally {
      setIsSaving(false);
    }
  };

  const confirmDelete = async () => {
    if (!showDeleteConfirm.id || isDeleting) return;
    
    const idToDelete = showDeleteConfirm.id;
    const deleteType = showDeleteConfirm.type;

    setIsDeleting(true);
    try {
      if (deleteType === 'program') {
        await api.delete(`/audit-programs/${idToDelete}`, {
          headers: { 'Authorization': `Bearer ${token}` }
        });
        fetchPrograms();
      } else {
        await api.delete(`/audit-procedures/${idToDelete}`, {
          headers: { 'Authorization': `Bearer ${token}` }
        });
        setProcedures(prev => prev.filter(p => p.id !== idToDelete));
      }
      toast.success(t('deleteSuccess'));
      setShowDeleteConfirm({id: null, type: 'program'});
    } catch (err: any) {
      logger.error('Operation failed', err);
      // If it's 404, it might be already deleted, so we can treat it as success in UI
      if (err.response?.status === 404) {
        if (deleteType === 'procedure') {
          setProcedures(prev => prev.filter(p => p.id !== idToDelete));
        } else {
          fetchPrograms();
        }
        toast.success(t('deleteSuccess'));
        setShowDeleteConfirm({id: null, type: 'program'});
      } else {
        toast.error(t('errorOccurred'));
      }
    } finally {
      setIsDeleting(false);
    }
  };

  const handleDuplicate = async (id: string | number) => {
    if (isSaving) return;
    setIsSaving(true);
    try {
      await api.post(`/audit-programs/${id}/duplicate`, {}, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      toast.success(t('createSuccess'));
      fetchPrograms();
    } catch (err: any) {
      logger.error('Operation failed', err);
      if (err.response?.status === 404) {
        toast.error(t('program.programNotFound'));
        fetchPrograms();
      } else {
        toast.error(t('errorOccurred'));
      }
    } finally {
      setIsSaving(false);
    }
  };

  const handleApprove = async (id: string | number) => {
    if (isSaving) return;
    setIsSaving(true);
    try {
      await api.post(`/audit-programs/${id}/approve`, {}, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      toast.success(t('updateSuccess'));
      fetchPrograms();
      setIsEditing(false);
    } catch (err: any) {
      logger.error('Operation failed', err);
      if (err.response?.status === 404) {
        toast.error(t('program.programNotFound'));
        setIsEditing(false);
        fetchPrograms();
      } else {
        toast.error(t('errorOccurred'));
      }
    } finally {
      setIsSaving(false);
    }
  };

  const handleAddProcedure = async () => {
    if (!currentProgram?.id) return;
    
    const newProc: Partial<AuditProcedure> = {
      program_id: currentProgram.id,
      procedure_number: `${procedures.length + 1}`,
      audit_step: '',
      audit_test_description: '',
      risk_addressed: '',
      control_test_type: ControlTestType.WALKTHROUGH,
      expected_evidence: '',
      sampling_method: '',
      responsible_auditor: user?.username || ''
    };

    try {
      const res = await api.post('/audit-procedures', newProc, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      toast.success(t('createSuccess'));
      setProcedures([...procedures, res.data]);
    } catch (err) {
      logger.error('Operation failed', err);
      toast.error(t('errorOccurred'));
    }
  };

  const handleUpdateProcedure = async (id: string | number, data: Partial<AuditProcedure>) => {
    try {
      await api.put(`/audit-procedures/${id}`, data, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      setProcedures(prev => prev.map(p => String(p.id) === String(id) ? { ...p, ...data } : p));
    } catch (err: any) {
      logger.error('Operation failed', err);
      if (err.response?.status === 404) {
        toast.error(t('program.programNotFound'));
        setProcedures(prev => prev.filter(p => String(p.id) !== String(id)));
      }
    }
  };

  const filteredPrograms = Array.isArray(programs) ? programs.filter(p => {
    const matchesSearch = (p.program_title?.toLowerCase() || '').includes(searchTerm.toLowerCase()) || 
                         (p.program_code?.toLowerCase() || '').includes(searchTerm.toLowerCase()) ||
                         (p.department?.toLowerCase() || '').includes(searchTerm.toLowerCase());
    const matchesType = filterType === 'All' || p.audit_type === filterType;
    const matchesStatus = filterStatus === 'All' || p.status === filterStatus;
    return matchesSearch && matchesType && matchesStatus;
  }) : [];

  const auditTypes = Object.values(AuditType);
  const testTypes = Object.values(ControlTestType);

  return (
    <div className="space-y-10" dir={isRTL ? 'rtl' : 'ltr'}>
      {isEditing && currentProgram ? (
        <AuditProgramEditor
          program={currentProgram}
          procedures={procedures}
          auditTypes={auditTypes}
          testTypes={testTypes}
          instructions={instructions}
          laws={laws}
          user={user}
          onCancel={() => setIsEditing(false)}
          onSave={handleSaveProgram}
          onUpdateProgram={(data) => setCurrentProgram({ ...currentProgram, ...data })}
          onAddProcedure={handleAddProcedure}
          onUpdateProcedure={handleUpdateProcedure}
          onDeleteProcedure={(id) => setShowDeleteConfirm({ id, type: 'procedure' })}
          onApprove={handleApprove}
          isDeleting={isDeleting}
        />
      ) : (
        <>
          <AuditProgramHeader
            searchTerm={searchTerm}
            setSearchTerm={setSearchTerm}
            filterType={filterType}
            setFilterType={setFilterType}
            auditTypes={auditTypes}
            onAdd={() => {
              setCurrentProgram({});
              setProcedures([]);
              setIsEditing(true);
            }}
          />

          <AuditProgramGrid
            programs={filteredPrograms}
            formatDate={formatDate}
            onEdit={(program) => {
              setCurrentProgram(program);
              fetchProcedures(program.id!);
              setIsEditing(true);
            }}
            onDuplicate={handleDuplicate}
            onDelete={(id) => setShowDeleteConfirm({ id, type: 'program' })}
            onViewProcedures={(program) => {
              setCurrentProgram(program);
              fetchProcedures(program.id!);
              setIsViewingProcedures(true);
            }}
          />
        </>
      )}

      <Modal
        isOpen={!!showDeleteConfirm.id}
        onClose={() => setShowDeleteConfirm({ id: null, type: 'program' })}
        title={t(showDeleteConfirm.type === 'program' ? 'program.deleteConfirm' : 'program.deleteProcedureConfirm')}
        size="sm"
      >
        <div className="space-y-6">
          <p className="text-[var(--color-text-muted)]">{t(showDeleteConfirm.type === 'program' ? 'program.deleteMessage' : 'program.deleteProcedureMessage')}</p>
          <div className="flex justify-end gap-3">
            <button 
              onClick={() => setShowDeleteConfirm({ id: null, type: 'program' })}
              className="px-4 py-2 rounded-xl text-[var(--color-text-muted)] font-bold hover:bg-[var(--color-bg-main)] transition-colors"
            >
              {t('common.cancel')}
            </button>
            <button 
              onClick={confirmDelete}
              disabled={isDeleting}
              className={`px-6 py-2 rounded-xl bg-rose-500 text-white font-bold hover:bg-rose-600 shadow-lg shadow-rose-200 transition-all active:scale-95 ${isDeleting ? 'opacity-50 cursor-not-allowed' : ''}`}
            >
              {isDeleting ? t('common.loading') : t('common.delete')}
            </button>
          </div>
        </div>
      </Modal>

      <AuditProgramProceduresModal
        isOpen={isViewingProcedures}
        program={currentProgram as AuditProgram}
        procedures={procedures}
        onClose={() => setIsViewingProcedures(false)}
      />
    </div>
  );
};

export default AuditProgramLibrary;

import React, { useEffect, useState } from 'react';
import { X, Save, FileText, List, Plus, Trash2, Shield, Target, CheckCircle } from 'lucide-react';
import { AuditProgram, AuditProcedure } from '../../types';
import { useTranslation } from 'react-i18next';
import { useFormat } from '../../services/formatService';
import { AuditStatus, AuditType, ControlTestType, UserRole } from '../../constants';
import { useDepartments } from '../../hooks/useDepartments';
import api from '../../services/api';

interface AuditProgramEditorProps {
  program: Partial<AuditProgram>;
  procedures: AuditProcedure[];
  auditTypes: string[];
  testTypes: string[];
  instructions: any[];
  laws: any[];
  user: any;
  onCancel: () => void;
  onSave: () => void;
  onUpdateProgram: (data: Partial<AuditProgram>) => void;
  onAddProcedure: () => void;
  onUpdateProcedure: (id: string | number, data: Partial<AuditProcedure>) => void;
  onDeleteProcedure: (id: string | number) => void;
  onApprove: (id: string | number) => void;
  isDeleting?: boolean;
}

const AuditProgramEditor: React.FC<AuditProgramEditorProps> = ({
  program,
  procedures,
  auditTypes,
  testTypes,
  instructions,
  laws,
  user,
  onCancel,
  onSave,
  onUpdateProgram,
  onAddProcedure,
  onUpdateProcedure,
  onDeleteProcedure,
  onApprove,
  isDeleting
}) => {
  const { t, i18n } = useTranslation();
  const isRTL = i18n.language === 'ar';
  const { formatNumber } = useFormat();
  const { departments } = useDepartments();

  // Risk register entries for linking
  const [risks, setRisks] = useState<any[]>([]);
  // Compliance items for reference standard
  const [complianceItems, setComplianceItems] = useState<any[]>([]);

  useEffect(() => {
    api.get('/risk-register', { params: { pageSize: 200 } })
      .then(res => setRisks(Array.isArray(res.data) ? res.data : (res.data.data || [])))
      .catch(() => setRisks([]));
    api.get('/compliance-items', { params: { pageSize: 200 } })
      .then(res => setComplianceItems(Array.isArray(res.data) ? res.data : (res.data.data || [])))
      .catch(() => setComplianceItems([]));
  }, []);

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500" dir={isRTL ? 'rtl' : 'ltr'}>
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button onClick={onCancel} className="p-2 hover:bg-[var(--color-bg-main)] rounded-full transition-colors">
            <X size={24} className="text-[var(--color-text-muted)]" />
          </button>
          <h2 className="text-3xl font-bold text-[var(--color-text-main)] tracking-tight">
            {program.id ? t('program.edit') : t('program.add')} {t('program.library')}
          </h2>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={onSave} className="btn-primary flex items-center gap-2">
            <Save size={18} />
            {t('program.save')}
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-8">
          <div className="glass-card p-8 space-y-6">
            <h3 className="text-xl font-bold text-[var(--color-text-main)] flex items-center gap-2">
              <FileText size={20} className="text-[var(--color-primary)]" />
              {t('program.basicProgramInformation')}
            </h3>
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('program.programCode')}</label>
                <input 
                  type="text" 
                  className="input-field" 
                  value={program.program_code || ''} 
                  onChange={e => onUpdateProgram({ program_code: e.target.value })}
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('program.programTitle')}</label>
                <input 
                  type="text" 
                  className="input-field" 
                  value={program.program_title || ''} 
                  onChange={e => onUpdateProgram({ program_title: e.target.value })}
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('program.department')}</label>
                <select 
                  className="input-field" 
                  value={program.department || ''} 
                  onChange={e => onUpdateProgram({ department: e.target.value })}
                >
                  <option value="">{t('plan.selectDepartment')}</option>
                  {Array.isArray(departments) && departments.map(d => <option key={d.id} value={d.name}>{d.name}</option>)}
                </select>
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('program.auditType')}</label>
                <select 
                  className="input-field" 
                  value={program.audit_type || ''} 
                  onChange={e => onUpdateProgram({ audit_type: e.target.value as AuditType })}
                >
                  <option value="">{t('program.selectType')}</option>
                  {auditTypes.map(type => <option key={type} value={type}>{t(`plan.${type.toLowerCase()}`)}</option>)}
                </select>
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('program.auditObjective')}</label>
              <textarea 
                className="input-field min-h-[100px]" 
                value={program.audit_objective || ''} 
                onChange={e => onUpdateProgram({ audit_objective: e.target.value })}
              />
            </div>

            <div className="space-y-2">
              <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('program.auditScope')}</label>
              <textarea 
                className="input-field min-h-[100px]" 
                value={program.audit_scope || ''} 
                onChange={e => onUpdateProgram({ audit_scope: e.target.value })}
              />
            </div>
          </div>

          {program.id && (
            <div className="glass-card p-8 space-y-6">
              <div className="flex items-center justify-between">
                <h3 className="text-xl font-bold text-[var(--color-text-main)] flex items-center gap-2">
                  <List size={20} className="text-[var(--color-primary)]" />
                  {t('program.auditProcedures')}
                </h3>
                <button onClick={onAddProcedure} className="btn-primary py-2 px-4 text-xs flex items-center gap-2">
                  <Plus size={14} />
                  {t('program.addProcedure')}
                </button>
              </div>

              <div className="space-y-4">
                {Array.isArray(procedures) && procedures.map((proc, idx) => (
                  <div key={proc.id} className="p-6 bg-[var(--color-bg-soft)] rounded-2xl border border-[var(--color-border-soft)] space-y-4">
                    <div className="flex items-center justify-between">
                      <span className="text-xs font-bold text-[var(--color-primary)] bg-[var(--color-primary)]/10 px-3 py-1 rounded-full">
                        {t('program.procedure')} #{formatNumber(proc.procedure_number)}
                      </span>
                      <button 
                        onClick={() => onDeleteProcedure(proc.id!)} 
                        disabled={isDeleting}
                        className={`text-rose-500 hover:text-rose-700 p-1 transition-all ${isDeleting ? 'opacity-30 cursor-not-allowed' : 'active:scale-90'}`}
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                    
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div className="space-y-1">
                        <label className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('program.auditStep')}</label>
                        <input 
                          type="text" 
                          className="input-field py-2 text-sm" 
                          value={proc.audit_step || ''} 
                          onChange={e => onUpdateProcedure(proc.id!, { audit_step: e.target.value })}
                        />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('program.testType')}</label>
                        <select 
                          className="input-field py-2 text-sm" 
                          value={proc.control_test_type || ''} 
                          onChange={e => onUpdateProcedure(proc.id!, { control_test_type: e.target.value as ControlTestType })}
                        >
                          {testTypes.map(type => <option key={type} value={type}>{t(`program.${type.toLowerCase()}`)}</option>)}
                        </select>
                      </div>
                    </div>

                    <div className="space-y-1">
                      <label className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('program.testDescription')}</label>
                      <textarea 
                        className="input-field py-2 text-sm min-h-[60px]" 
                        value={proc.audit_test_description || ''} 
                        onChange={e => onUpdateProcedure(proc.id!, { audit_test_description: e.target.value })}
                      />
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div className="space-y-1">
                        <label className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('program.riskAddressed')}</label>
                        <input 
                          type="text" 
                          className="input-field py-2 text-sm" 
                          value={proc.risk_addressed || ''} 
                          onChange={e => onUpdateProcedure(proc.id!, { risk_addressed: e.target.value })}
                        />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('program.expectedEvidence')}</label>
                        <input 
                          type="text" 
                          className="input-field py-2 text-sm" 
                          value={proc.expected_evidence || ''} 
                          onChange={e => onUpdateProcedure(proc.id!, { expected_evidence: e.target.value })}
                        />
                      </div>
                    </div>
                  </div>
                ))}
                {procedures.length === 0 && (
                  <div className="py-12 text-center border-2 border-dashed border-[var(--color-border-soft)] rounded-3xl">
                    <p className="text-[var(--color-text-muted)] font-bold">{t('program.noProceduresAddedYet')}</p>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>

        <div className="space-y-8">
          <div className="glass-card p-8 space-y-6">
            <h3 className="text-xl font-bold text-[var(--color-text-main)] flex items-center gap-2">
              <Shield size={20} className="text-[var(--color-primary)]" />
              {t('program.risksAndControls')}
            </h3>
            
            <div className="space-y-4">
              {/* Key Risks — pulled from Risk Register */}
              <div className="space-y-2">
                <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('program.keyRisks')}</label>
                {/* Show selected risks as tags */}
                <div className="flex flex-wrap gap-2 mb-2 min-h-[32px]">
                  {(program.key_risks ? program.key_risks.split('||').filter(Boolean) : []).map((r, i) => (
                    <span key={i} className="bg-rose-50 text-rose-600 border border-rose-200 px-2 py-1 rounded-lg text-xs font-bold flex items-center gap-1">
                      {r}
                      <button onClick={() => {
                        const arr = (program.key_risks || '').split('||').filter(Boolean);
                        onUpdateProgram({ key_risks: arr.filter((_, idx) => idx !== i).join('||') });
                      }} className="hover:text-rose-800"><X size={11} /></button>
                    </span>
                  ))}
                </div>
                <select className="input-field" value=""
                  onChange={e => {
                    if (!e.target.value) return;
                    const arr = (program.key_risks || '').split('||').filter(Boolean);
                    if (!arr.includes(e.target.value)) {
                      onUpdateProgram({ key_risks: [...arr, e.target.value].join('||') });
                    }
                  }}>
                  <option value="">{t('programs.linkRisks') || 'اختر خطراً من السجل'}</option>
                  {risks.map(r => (
                    <option key={r.id} value={r.risk_id ? `${r.risk_id}: ${r.description}` : r.description}>
                      {r.risk_id ? `${r.risk_id} — ` : ''}{r.description}
                    </option>
                  ))}
                </select>
              </div>

              {/* Reference Standard — pulled from Compliance Matrix */}
              <div className="space-y-2">
                <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('program.referenceStandard')}</label>
                <div className="flex flex-wrap gap-2 mb-2 min-h-[32px]">
                  {(program.reference_standard ? program.reference_standard.split(',').filter(Boolean) : []).map((standard, index) => (
                    <span key={index} className="bg-[var(--color-primary)]/10 text-[var(--color-primary)] px-2 py-1 rounded-lg text-xs font-bold flex items-center gap-1">
                      {standard}
                      <button onClick={() => {
                        const standards = (program.reference_standard || '').split(',').filter(Boolean);
                        onUpdateProgram({ reference_standard: standards.filter((_, i) => i !== index).join(',') });
                      }} className="hover:text-[var(--color-primary)]/70"><X size={12} /></button>
                    </span>
                  ))}
                </div>
                <select className="input-field" value=""
                  onChange={e => {
                    const val = e.target.value;
                    if (!val) return;
                    const arr = (program.reference_standard || '').split(',').filter(Boolean);
                    if (!arr.includes(val)) {
                      onUpdateProgram({ reference_standard: [...arr, val].join(',') });
                    }
                  }}>
                  <option value="">{t('programs.linkStandards') || 'اختر معياراً من مصفوفة الامتثال'}</option>
                  {complianceItems.map(c => (
                    <option key={c.id} value={c.ref_number ? `${c.ref_number}: ${c.title}` : c.title}>
                      {c.ref_number ? `${c.ref_number} — ` : ''}{c.title}
                    </option>
                  ))}
                </select>
              </div>
            </div>
          </div>

          <div className="glass-card p-8 space-y-6">
            <h3 className="text-xl font-bold text-[var(--color-text-main)] flex items-center gap-2">
              <Target size={20} className="text-[var(--color-primary)]" />
              {t('program.programStatus')}
            </h3>
            
            <div className="space-y-4">
              <div className="flex items-center justify-between p-4 bg-[var(--color-bg-soft)] rounded-2xl">
                <span className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('program.status')}</span>
                <span className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest ${
                  program.status === AuditStatus.APPROVED ? 'bg-emerald-100 text-emerald-600' :
                  program.status === AuditStatus.DRAFT ? 'bg-slate-200 text-[var(--color-text-muted)]' : 'bg-[var(--color-primary)]/10 text-[var(--color-primary)]'
                }`}>
                  {t(`plan.${program.status?.toLowerCase() || 'draft'}`)}
                </span>
              </div>
              <div className="flex items-center justify-between p-4 bg-[var(--color-bg-soft)] rounded-2xl">
                <span className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('program.version')}</span>
                <span className="text-sm font-bold text-[var(--color-text-main)]">v{formatNumber(program.version_number || 1)}.0</span>
              </div>
              {program.id && (user?.role === UserRole.ADMIN || user?.role === UserRole.MANAGER) && program.status !== AuditStatus.APPROVED && (
                <button onClick={() => onApprove(program.id!)} className="w-full btn-primary bg-emerald-600 hover:bg-emerald-700 shadow-emerald-100 flex items-center justify-center gap-2">
                  <CheckCircle size={18} />
                  {t('program.approve')}
                </button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

