export default AuditProgramProceduresModal;

import React, { useState } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import api from '../services/api';
import { useTranslation } from 'react-i18next';
import { AuditTask, AuditPlan, AuditEvidence as AuditEvidenceType } from '../types';
import { Plus, Search, MoreVertical, CheckCircle2, Clock, AlertCircle, Edit, Trash2, FileText, Eye } from 'lucide-react';
import { motion } from 'motion/react';
import toast from 'react-hot-toast';
import { useFormat } from '../services/formatService';
import { useDebounce } from '../hooks/useDebounce';
import { AuditStatus } from '../constants';
import logger from '../utils/logger';

import Modal from '../components/Modal';
import AuditTaskForm from '../components/AuditTaskForm';
import PdfViewer from '../components/PdfViewer';
import Pagination from '../components/Pagination';
import AuditTasksTable from '../components/AuditTasksTable';

const AuditTasksModule: React.FC = () => {
  const { t, i18n } = useTranslation();
  const { formatDate, formatNumber } = useFormat();
  const queryClient = useQueryClient();

  const [searchTerm, setSearchTerm] = useState('');
  const debouncedSearchTerm = useDebounce(searchTerm, 500);
  const [pagination, setPagination] = useState({ page: 1, pageSize: 15 });
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<AuditTask | null>(null);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [taskToDelete, setTaskToDelete] = useState<string | number | null>(null);
  const [previewItem, setPreviewItem] = useState<AuditEvidenceType | null>(null);

  const { data: tasksData, isLoading: loadingTasks } = useQuery({
    queryKey: ['audit-tasks', pagination.page, pagination.pageSize, debouncedSearchTerm],
    queryFn: async () => {
      const res = await api.get('/audit-tasks', {
        params: {
          page: pagination.page,
          pageSize: pagination.pageSize,
          search: debouncedSearchTerm || undefined
        }
      });
      return res.data;
    }
  });

  const tasks = Array.isArray(tasksData?.data) ? tasksData.data : (Array.isArray(tasksData) ? tasksData : []);
  const totalItems = tasksData?.pagination?.total || 0;
  const totalPages = tasksData?.pagination?.totalPages || 0;

  const { data: plans = [] } = useQuery({
    queryKey: ['audit-plans'],
    queryFn: async () => {
      const res = await api.get('/audit-plans');
      return Array.isArray(res.data) ? res.data : (res.data.data || []);
    }
  });

  const { data: evidenceList = [] } = useQuery({
    queryKey: ['audit-evidence'],
    queryFn: async () => {
      const res = await api.get('/audit-evidence');
      return Array.isArray(res.data) ? res.data : (res.data.data || []);
    }
  });

  const loading = loadingTasks;

  const handleAddSuccess = () => {
    setIsModalOpen(false);
    setEditingTask(null);
    toast.success(editingTask ? t('updateSuccess') : t('createSuccess'));
    queryClient.invalidateQueries({ queryKey: ['audit-tasks'] });
  };

  const handleEdit = (task: AuditTask) => {
    setEditingTask(task);
    setIsModalOpen(true);
  };

  const initiateDelete = (id: string | number) => {
    setTaskToDelete(id);
    setIsDeleteModalOpen(true);
  };

  const confirmDelete = async () => {
    if (!taskToDelete) return;
    try {
      await api.delete(`/audit-tasks/${taskToDelete}`);
      toast.success(t('deleteSuccess'));
      queryClient.invalidateQueries({ queryKey: ['audit-tasks'] });
      setIsDeleteModalOpen(false);
      setTaskToDelete(null);
    } catch (err) {
      logger.error('Operation failed', err);
      toast.error(t('errorOccurred'));
    }
  };

  const updateStatus = async (id: string | number, newStatus: string) => {
    try {
      await api.patch(`/audit-tasks/${id}/status`, { status: newStatus });
      toast.success(t('tasks.statusUpdateSuccess'));
      queryClient.invalidateQueries({ queryKey: ['audit-tasks'] });
    } catch (err: any) {
      logger.error('Operation failed', err);
      const apiError = err.response?.data?.error;
      const errorMsg = typeof apiError === 'string' ? apiError : (apiError?.message || t('errorOccurred'));
      toast.error(errorMsg);
    }
  };

  const getPlanTitle = (id: string | number) => {
    return plans.find(p => String(p.id) === String(id))?.title || `${t('common.auditPlan')} #${formatNumber(id)}`;
  };

  const getEvidence = (id?: string | number) => {
    if (!id) return null;
    return evidenceList.find(e => String(e.id) === String(id));
  };

  const filteredTasks = tasks;

  return (
    <div className="space-y-10">
      <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-6">
        <div className="flex items-center gap-6">
          <div className="w-12 h-12 sm:w-16 sm:h-16 bg-[var(--color-primary)] rounded-2xl flex items-center justify-center text-white shadow-lg shadow-[var(--color-primary)]/20">
            <CheckCircle2 size={32} />
          </div>
          <div>
            <h2 className="text-2xl sm:text-4xl font-bold text-[var(--color-text-main)] tracking-tight">{t('tasks.title')}</h2>
            <p className="text-sm text-[var(--color-text-muted)] font-bold mt-2">{t('tasks.detailedAuditProcedures')}</p>
          </div>
        </div>
        
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-4">
          <div className="relative flex-1 min-w-[300px]">
            <Search className="absolute start-5 top-1/2 -translate-y-1/2 text-[var(--color-text-muted)]" size={20} />
            <input 
              type="text"
              placeholder={t('common.search')}
              className="input-field !ps-14"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="flex items-center gap-4">
            <motion.button 
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={() => {
                setEditingTask(null);
                setIsModalOpen(true);
              }}
              className="btn-primary flex items-center justify-center gap-3 whitespace-nowrap"
            >
              <Plus size={24} />
              <span>{t('plan.add')}</span>
            </motion.button>
          </div>
        </div>
      </div>

      <Modal 
        isOpen={isModalOpen} 
        onClose={() => {
          setIsModalOpen(false);
          setEditingTask(null);
        }} 
        title={editingTask ? t('tasks.editTask') : t('tasks.addTask')}
      >
        <AuditTaskForm 
          onSuccess={handleAddSuccess} 
          onCancel={() => {
            setIsModalOpen(false);
            setEditingTask(null);
          }} 
          plans={plans}
          initialData={editingTask}
        />
      </Modal>

      <Modal 
        isOpen={isDeleteModalOpen} 
        onClose={() => {
          setIsDeleteModalOpen(false);
          setTaskToDelete(null);
        }} 
        title={t('plan.deleteConfirm')}
      >
        <div className="space-y-6">
          <p className="text-[var(--color-text-muted)] font-medium">
            {t('plan.deleteMessage')}
          </p>
          <div className="flex justify-end gap-4">
            <button 
              onClick={() => {
                setIsDeleteModalOpen(false);
                setTaskToDelete(null);
              }}
              className="px-6 py-3 rounded-2xl bg-[var(--color-bg-main)] text-[var(--color-text-muted)] font-bold hover:bg-[var(--color-bg-main)] transition-colors"
            >
              {t('common.cancel')}
            </button>
            <button 
              onClick={confirmDelete}
              className="px-6 py-3 rounded-2xl bg-rose-500 text-white font-bold hover:bg-rose-600 transition-colors shadow-lg shadow-rose-200"
            >
              {t('common.delete')}
            </button>
          </div>
        </div>
      </Modal>

      {previewItem && (
        <Modal
          isOpen={!!previewItem}
          onClose={() => setPreviewItem(null)}
          title={previewItem.file_name}
          size="xl"
        >
          <div className="h-[70vh] flex flex-col bg-[var(--color-bg-main)] rounded-2xl overflow-hidden">
            {previewItem.file_data?.startsWith('data:application/pdf') || /\.(pdf)$/i.test(previewItem.file_data || '') || (previewItem.file_data && !previewItem.file_data.startsWith('data:') && !previewItem.file_data.startsWith('http') && !previewItem.file_data.startsWith('/') && previewItem.file_data.length > 100) ? (
              <PdfViewer url={previewItem.file_data} />
            ) : previewItem.file_data?.startsWith('data:image/') || /\.(jpg|jpeg|png|gif|webp)$/i.test(previewItem.file_data || '') ? (
              <div className="flex-1 overflow-auto p-4 flex items-center justify-center">
                <img src={previewItem.file_data} alt={previewItem.file_name} className="max-w-full max-h-full object-contain shadow-xl rounded-xl" />
              </div>
            ) : (
              <div className="flex-1 flex flex-col items-center justify-center p-8 text-center">
                <div className="w-24 h-24 bg-[var(--color-card)] rounded-full flex items-center justify-center shadow-lg mb-6">
                  <FileText size={48} className="text-[var(--color-text-muted)]" />
                </div>
                <h3 className="text-xl font-bold text-[var(--color-text-main)] mb-2">{t('tasks.previewNotAvailable')}</h3>
                <p className="text-[var(--color-text-muted)] mb-8 max-w-md">{t('tasks.previewNotAvailableDesc')}</p>
                <a 
                  href={previewItem.file_data} 
                  download={previewItem.file_name}
                  className="btn-primary"
                >
                  {t('tasks.downloadFile')}
                </a>
              </div>
            )}
          </div>
        </Modal>
      )}

      <div className="glass-card overflow-hidden">
        <AuditTasksTable 
          tasks={filteredTasks}
          getPlanTitle={getPlanTitle}
          getEvidence={getEvidence}
          setPreviewItem={setPreviewItem}
          handleEdit={handleEdit}
          initiateDelete={initiateDelete}
          updateStatus={updateStatus}
        />
      </div>

      <Pagination 
        currentPage={pagination.page}
        totalPages={totalPages}
        onPageChange={(page) => setPagination(prev => ({ ...prev, page }))}
        pageSize={pagination.pageSize}
        onPageSizeChange={(pageSize) => setPagination(prev => ({ ...prev, pageSize, page: 1 }))}
        totalItems={totalItems}
      />
    </div>
  );
};

export default AuditTasksModule;

import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../context/AuthContext';
import { AuditTrail } from '../types';
import { History, Search, Filter, Clock, User, Activity, ArrowRight } from 'lucide-react';
import { motion } from 'motion/react';
import api from '../services/api';
import toast from 'react-hot-toast';
import { useFormat } from '../services/formatService';
import Pagination from '../components/Pagination';
import logger from '../utils/logger';

const AuditTrailModule: React.FC = () => {
  const { token } = useAuth();
  const { t, i18n } = useTranslation();
  const { formatDateTime, translateName, translateAction, translateModule } = useFormat();
  const [logs, setLogs] = useState<AuditTrail[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterModule, setFilterModule] = useState('all');
  const [filterAction, setFilterAction] = useState('all');
  
  const modules = ['auth', 'users', 'audit', 'compliance', 'risk', 'correspondence', 'settings', 'system'];
  const actions = ['login', 'logout', 'created', 'updated', 'deleted', 'failed', 'approved', 'rejected'];

  const [pagination, setPagination] = useState({
    page: 1,
    pageSize: 20,
    total: 0,
    totalPages: 0
  });

  useEffect(() => {
    const controller = new AbortController();
    fetchLogs(controller.signal);
    return () => controller.abort();
  }, [pagination.page, pagination.pageSize, filterModule, filterAction, searchTerm]);

  const fetchLogs = async (signal?: AbortSignal) => {
    setLoading(true);
    try {
      const res = await api.get('/audit-trail', {
        params: {
          page: pagination.page,
          pageSize: pagination.pageSize,
          module: filterModule !== 'all' ? filterModule : undefined,
          action: filterAction !== 'all' ? filterAction : undefined,
          username: searchTerm || undefined
        },
        signal
      });
      
      const data = Array.isArray(res.data) ? res.data : (res.data.data || []);
      const pagin = res.data.pagination || { total: data.length, totalPages: 1 };
      
      setLogs(data);
      setPagination(prev => ({
        ...prev,
        total: pagin.total,
        totalPages: pagin.totalPages
      }));
    } catch (err: any) {
      if (err?.name !== 'CanceledError') {
        logger.error('Operation failed', err);
        toast.error(t('errorOccurred'));
      }
    } finally {
      setLoading(false);
    }
  };

  const handlePageChange = (page: number) => {
    setPagination(prev => ({ ...prev, page }));
  };

  const handlePageSizeChange = (pageSize: number) => {
    setPagination(prev => ({ ...prev, pageSize, page: 1 }));
  };

  const filteredLogs = logs;

  return (
    <div className="space-y-10" dir={i18n.language === 'ar' ? 'rtl' : 'ltr'}>
      <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-8">
        <div className="flex items-center gap-6">
          <div className="w-12 h-12 sm:w-16 sm:h-16 bg-[var(--color-primary)] rounded-2xl flex items-center justify-center text-white shadow-lg shadow-[var(--color-primary)]/20">
            <History size={32} />
          </div>
          <div>
            <h2 className="text-2xl sm:text-4xl font-bold text-[var(--color-text-main)] tracking-tight">{t('common.trail')}</h2>
            <p className="text-sm text-[var(--color-text-muted)] font-bold mt-2">{t('common.trailSubtitle')}</p>
          </div>
        </div>
        
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-4">
          <div className="relative flex-1 min-w-[200px]">
            <Search className="absolute start-5 top-1/2 -translate-y-1/2 text-[var(--color-text-muted)]" size={20} />
            <input 
              type="text"
              placeholder={t('common.search')}
              className="input-field !ps-14"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>

          <div className="flex items-center gap-2">
            <Filter size={18} className="text-[var(--color-text-muted)]" />
            <select 
              className="input-field py-2 text-sm min-w-[150px]"
              value={filterModule}
              onChange={(e) => setFilterModule(e.target.value)}
            >
              <option value="all">{t('common.allModules')}</option>
              {modules.map(m => (
                <option key={m} value={m}>{t(`common.modules.${m}`)}</option>
              ))}
            </select>

            <select 
              className="input-field py-2 text-sm min-w-[150px]"
              value={filterAction}
              onChange={(e) => setFilterAction(e.target.value)}
            >
              <option value="all">{t('common.allActions')}</option>
              {actions.map(a => (
                <option key={a} value={a}>
                  {t(`common.${a}`)}
                </option>
              ))}
            </select>
          </div>
        </div>
      </div>

      <div className="glass-card overflow-hidden">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-start border-collapse">
            <thead>
              <tr className="bg-[var(--color-bg-soft)]/50 border-b border-[var(--color-border-soft)]">
                <th className="px-10 py-6 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('common.timestamp_label')}</th>
                <th className="px-10 py-6 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('common.user_label')}</th>
                <th className="px-10 py-6 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('common.action_label')}</th>
                <th className="px-10 py-6 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('common.module')}</th>
                <th className="px-10 py-6 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('common.details')}</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[var(--color-border-soft)]/50">
              {(Array.isArray(filteredLogs) ? filteredLogs : []).map((log, idx) => (
                <motion.tr 
                  key={log.id}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: idx * 0.02 }}
                  className="hover:bg-[var(--color-primary)]/5 transition-colors group"
                >
                  <td className="px-10 py-6 text-xs font-bold text-[var(--color-text-muted)] whitespace-nowrap">
                    {formatDateTime(log.timestamp)}
                  </td>
                  <td className="px-10 py-6">
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 rounded-xl bg-[var(--color-card)] border border-[var(--color-border-soft)] flex items-center justify-center text-[10px] font-bold text-[var(--color-primary)] shadow-sm">
                        {log.user.charAt(0).toUpperCase()}
                      </div>
                      <span className="text-sm font-bold text-[var(--color-text-main)]">{translateName(log.user)}</span>
                    </div>
                  </td>
                  <td className="px-10 py-6">
                    <span className={`inline-flex items-center px-4 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest ${
                      (log.action || '').toLowerCase().includes('delete') ? 'bg-rose-100 text-rose-600' :
                      (log.action || '').toLowerCase().includes('created') ? 'bg-emerald-100 text-emerald-600' :
                      (log.action || '').toLowerCase().includes('failed') ? 'bg-rose-100 text-rose-600' : 'bg-[var(--color-primary)]/10 text-[var(--color-primary)]'
                    }`}>
                      {translateAction(log.action)}
                    </span>
                  </td>
                  <td className="px-10 py-6 text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">
                    {translateModule(log.module)}
                  </td>
                  <td className="px-10 py-6 text-sm font-bold text-[var(--color-text-muted)] max-w-xs truncate" title={log.details}>
                    {log.details}
                  </td>
                </motion.tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <Pagination 
        currentPage={pagination.page}
        totalPages={pagination.totalPages}
        onPageChange={handlePageChange}
        pageSize={pagination.pageSize}
        onPageSizeChange={handlePageSizeChange}
        totalItems={pagination.total}
      />
    </div>
  );
};

export default AuditTrailModule;

import React, { useState, useEffect } from 'react';
import { useUser } from '../context/UserContext';
import { useTranslation } from 'react-i18next';
import { motion, AnimatePresence } from 'motion/react';
import { 
  ClipboardList, 
  AlertTriangle, 
  FileText, 
  ShieldCheck, 
  Plus, 
  ArrowRight, 
  Upload, 
  CheckCircle2,
  Clock,
  User,
  ChevronRight,
  Search,
  MessageSquare,
  Link as LinkIcon
} from 'lucide-react';
import api from '../services/api';
import { extractErrorMessage } from '../services/errorService';
import { useFormat } from '../services/formatService';
import toast from 'react-hot-toast';
import LoadingSpinner from '../components/LoadingSpinner';
import Badge from '../components/Badge';
import Modal from '../components/Modal';
import FindingForm from '../components/FindingForm';
import { AuditStatus, RiskLevel } from '../constants';
import logger from '../utils/logger';

interface AuditWorkspaceProps {
  planId: string | number;
  onClose: () => void;
}

const AuditWorkspace: React.FC<AuditWorkspaceProps> = ({ planId, onClose }) => {
  const { t, i18n } = useTranslation();
  const { formatNumber } = useFormat();
  const { user } = useUser();
  const [loading, setLoading] = useState(true);
  const [plan, setPlan] = useState<any>(null);
  const [tasks, setTasks] = useState<any[]>([]);
  const [findings, setFindings] = useState<any[]>([]);
  const [evidence, setEvidence] = useState<any[]>([]);
  const [activeTask, setActiveTask] = useState<any>(null);
  const [isFindingModalOpen, setIsFindingModalOpen] = useState(false);
  const [selectedFinding, setSelectedFinding] = useState<any>(null);
  const [currentFindingIndex, setCurrentFindingIndex] = useState(0);

  const [isUpdatingStatus, setIsUpdatingStatus] = useState(false);

  const nextFinding = () => {
    if (findings.length === 0) return;
    setCurrentFindingIndex((prev) => (prev + 1) % findings.length);
  };

  const prevFinding = () => {
    if (findings.length === 0) return;
    setCurrentFindingIndex((prev) => (prev - 1 + findings.length) % findings.length);
  };

  const fetchData = async () => {
    setLoading(true);
    try {
      const [planRes, tasksRes, findingsRes, evidenceRes] = await Promise.all([
        api.get(`/audit-plans/${planId}`),
        api.get(`/audit-tasks?plan_id=${planId}`),
        api.get(`/audit-findings?audit_id=${planId}`),
        api.get(`/audit-evidence?audit_id=${planId}`)
      ]);

      const planData = planRes?.data?.data || planRes?.data;
      const tasksData = tasksRes?.data?.data || tasksRes?.data;
      const findingsData = findingsRes?.data?.data || findingsRes?.data;
      const evidenceData = evidenceRes?.data?.data || evidenceRes?.data;

      setPlan(planData);
      const tasksArray = Array.isArray(tasksData) ? tasksData : [];
      setTasks(tasksArray);
      setFindings(Array.isArray(findingsData) ? findingsData : []);
      setEvidence(Array.isArray(evidenceData) ? evidenceData : []);
      
      if (tasksArray.length > 0 && !activeTask) {
        setActiveTask(tasksArray[0]);
      }
    } catch (error) {
      logger.error('Error fetching audit data:', error);
      toast.error(t('errorOccurred'));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [planId]);

  const handleUpdateTaskStatus = async (taskId: string, newStatus: string) => {
    setIsUpdatingStatus(true);
    try {
      await api.patch(`/audit-tasks/${taskId}/status`, { status: newStatus });
      toast.success(t('statusUpdated'));
      await fetchData();
    } catch (error: any) {
      toast.error(extractErrorMessage(error, t('errorOccurred')));
    } finally {
      setIsUpdatingStatus(false);
    }
  };

  const isRTL = i18n.language === 'ar';

  if (loading && !plan) {
    return (
      <div className="fixed inset-0 bg-[var(--color-card)] z-[60] flex items-center justify-center">
        <LoadingSpinner size="lg" />
      </div>
    );
  }

  return (
    <div className="fixed inset-0 bg-[var(--color-bg-main)] z-[60] flex flex-col">
      {/* Header */}
      <div className="h-20 bg-[var(--color-card)] border-b border-[var(--color-border-soft)] px-8 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button 
            onClick={onClose}
            className="w-10 h-10 rounded-full hover:bg-[var(--color-bg-main)] flex items-center justify-center transition-colors"
          >
            <ArrowRight size={20} className={isRTL ? '' : 'rotate-180'} />
          </button>
          <div>
            <h2 className="text-xl font-bold text-[var(--color-text-main)]">{plan?.title}</h2>
            <p className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{plan?.plan_code} • {plan?.department}</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <Badge type="status" value={plan?.status} />
          <div className="w-px h-6 bg-slate-200 mx-2" />
          <button className="btn-primary !py-2 !px-4 text-xs">
            {t('common.completeAudit')}
          </button>
        </div>
      </div>

      <div className="flex-1 flex overflow-hidden">
        {/* Left Sidebar: Tasks */}
        <div className="w-80 bg-[var(--color-card)] border-e border-[var(--color-border-soft)] flex flex-col">
          <div className="p-6 border-b border-[var(--color-border-soft)]">
            <h3 className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] mb-4">{t('planTasks')}</h3>
            <div className="relative">
              <Search className="absolute start-3 top-1/2 -translate-y-1/2 text-[var(--color-text-muted)]" size={14} />
              <input 
                type="text" 
                placeholder={t('common.search')}
                className="w-full bg-[var(--color-bg-soft)] border-none rounded-xl py-2 ps-10 text-xs font-bold focus:ring-1 focus:ring-[var(--color-primary)]"
              />
            </div>
          </div>
          <div className="flex-1 overflow-y-auto custom-scrollbar p-3 space-y-2">
            {tasks.map((task) => (
              <button
                key={task.id}
                onClick={() => setActiveTask(task)}
                className={`w-full text-start p-4 rounded-2xl transition-all group ${
                  activeTask?.id === task.id 
                    ? 'bg-[var(--color-primary)] text-white shadow-lg shadow-[var(--color-primary)]/20' 
                    : 'hover:bg-[var(--color-bg-soft)] text-[var(--color-text-muted)]'
                }`}
              >
                <div className="flex justify-between items-start mb-1">
                  <span className={`text-[9px] font-bold uppercase tracking-widest ${activeTask?.id === task.id ? 'text-white/70' : 'text-[var(--color-text-muted)]'}`}>
                    {task.task_number}
                  </span>
                  <div className={`w-2 h-2 rounded-full ${
                    task.status === 'completed' ? 'bg-emerald-400' : 
                    task.status === 'in_progress' ? 'bg-blue-400' : 'bg-slate-300'
                  }`} />
                </div>
                <p className="text-xs font-bold leading-tight line-clamp-2">{task.title}</p>
                <div className="mt-3 flex items-center justify-between">
                  <div className="flex items-center gap-1">
                    <User size={10} className={activeTask?.id === task.id ? 'text-white/70' : 'text-[var(--color-text-muted)]'} />
                    <span className="text-[9px] font-bold opacity-70">{task.assigned_name || t('common.unassigned')}</span>
                  </div>
                  <ChevronRight size={14} className={`transition-transform ${isRTL ? 'rotate-180' : ''} ${activeTask?.id === task.id ? (isRTL ? '-translate-x-1' : 'translate-x-1') : 'opacity-0 group-hover:opacity-100'}`} />
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Main Content: Middle (Execution) & Right (Findings/Evidence) */}
        <div className="flex-1 flex bg-[var(--color-bg-soft)] overflow-hidden">
          {/* Execution Area */}
          <div className="flex-1 p-8 overflow-y-auto custom-scrollbar space-y-8">
            {activeTask ? (
              <>
                <div className="bg-[var(--color-card)] rounded-2xl p-8 shadow-sm border border-[var(--color-border-soft)]">
                  <div className="flex justify-between items-start mb-6">
                    <div>
                      <h3 className="text-2xl font-bold text-[var(--color-text-main)] mb-2">{activeTask.title}</h3>
                      <div className="flex items-center gap-4">
                        <span className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{activeTask.audit_type}</span>
                        <div className="w-1 h-1 rounded-full bg-slate-300" />
                        <span className="text-xs font-bold text-[var(--color-text-muted)]">{t('common.assignedTo')}: {activeTask.assigned_name}</span>
                      </div>
                    </div>
                    <div className="flex gap-2">
                       {activeTask?.status === 'draft' && (
                         <button 
                           onClick={() => handleUpdateTaskStatus(activeTask.id, 'in_progress')}
                           disabled={isUpdatingStatus}
                           className="btn-primary !py-2 !px-6 text-xs flex items-center gap-2 disabled:opacity-50"
                         >
                           {isUpdatingStatus ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Clock size={16} />} 
                           {t('common.startTask')}
                         </button>
                       )}
                       {activeTask?.status === 'in_progress' && (
                         <button 
                           onClick={() => handleUpdateTaskStatus(activeTask.id, 'review')}
                           disabled={isUpdatingStatus}
                           className="btn-warning !py-2 !px-6 text-xs flex items-center gap-2 disabled:opacity-50"
                         >
                           {isUpdatingStatus ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <ShieldCheck size={16} />} 
                           {t('common.moveToReview')}
                         </button>
                       )}
                    </div>
                  </div>

                  <div className="grid grid-cols-2 gap-8 text-sm">
                    <div className="space-y-4">
                      <h4 className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest border-b border-slate-50 pb-2">{t('common.details')}</h4>
                      <div className="grid grid-cols-2 gap-4">
                        <div>
                          <p className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-1">{t('common.startDate')}</p>
                          <p className="font-bold text-[var(--color-text-main)]">{activeTask?.period_from || '—'}</p>
                        </div>
                        <div>
                          <p className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-1">{t('common.endDate')}</p>
                          <p className="font-bold text-[var(--color-text-main)]">{activeTask?.period_to || '—'}</p>
                        </div>
                      </div>
                    </div>
                    <div className="space-y-4">
                      <h4 className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest border-b border-slate-50 pb-2">{t('common.progress')}</h4>
                      <div className="flex items-center gap-4">
                        <div className="flex-1 h-2 bg-[var(--color-bg-main)] rounded-full overflow-hidden">
                           <div className={`h-full rounded-full ${activeTask?.status === 'completed' ? 'bg-emerald-500 w-full' : 'bg-[var(--color-primary-light)]0 w-1/2'}`} />
                        </div>
                        <span className="text-xs font-bold text-[var(--color-text-main)]">{activeTask?.status === 'completed' ? formatNumber(100) + '%' : formatNumber(50) + '%'}</span>
                      </div>
                    </div>
                  </div>
                </div>

                {/* Observations & Work Done */}
                <div className="grid grid-cols-1 gap-8">
                  <div className="bg-[var(--color-card)] rounded-2xl p-8 shadow-sm border border-[var(--color-border-soft)]">
                    <div className="flex justify-between items-center mb-6">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 bg-amber-50 rounded-xl flex items-center justify-center text-amber-500">
                          <AlertTriangle size={20} />
                        </div>
                        <h4 className="text-lg font-bold text-[var(--color-text-main)]">{t('common.findingsAndObservations')}</h4>
                      </div>
                      <button 
                         onClick={() => {
                           setSelectedFinding(null);
                           setIsFindingModalOpen(true);
                         }}
                         className="flex items-center gap-2 text-[var(--color-primary)] font-bold text-xs hover:bg-[var(--color-primary)]/5 px-4 py-2 rounded-xl transition-colors"
                      >
                        <Plus size={16} /> {t('common.addObservation')}
                      </button>
                    </div>

                    <div className="relative mt-4">
                      {findings.length === 0 ? (
                        <div className="py-12 flex flex-col items-center justify-center text-[var(--color-border-strong)] border-2 border-dashed border-slate-50 rounded-3xl">
                          <MessageSquare size={48} className="mb-4 opacity-20" />
                          <p className="text-sm font-bold">{t('common.noFindingsYet')}</p>
                        </div>
                      ) : (
                        <div className="relative overflow-hidden w-full bg-[var(--color-bg-soft)] border border-[var(--color-border-soft)] rounded-2xl p-6 h-[200px]">
                          <AnimatePresence mode="wait">
                            {findings.length > 0 && (
                              <motion.div
                                key={currentFindingIndex}
                                initial={{ opacity: 0, x: isRTL ? -20 : 20 }}
                                animate={{ opacity: 1, x: 0 }}
                                exit={{ opacity: 0, x: isRTL ? 20 : -20 }}
                                transition={{ duration: 0.3 }}
                                className="absolute inset-0 p-6 flex flex-col h-full"
                              >
                                <div className="flex justify-between items-start mb-4">
                                  <h5 className="font-bold text-[var(--color-text-main)] text-lg line-clamp-1">{findings[currentFindingIndex].title}</h5>
                                  <Badge type="risk" value={findings[currentFindingIndex].risk_level} />
                                </div>
                                <p className="text-sm text-[var(--color-text-muted)] line-clamp-3 mb-auto leading-relaxed">{findings[currentFindingIndex].description}</p>
                                <div className="flex flex-row items-center justify-between mt-4 border-t border-[var(--color-border-soft)]/50 pt-4">
                                  <span className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest bg-[var(--color-card)] px-3 py-1 rounded-full shadow-sm">
                                    {findings[currentFindingIndex].status}
                                  </span>
                                  <button 
                                    onClick={() => {
                                      setSelectedFinding(findings[currentFindingIndex]);
                                      setIsFindingModalOpen(true);
                                    }}
                                    className="text-[var(--color-primary)] text-xs font-bold uppercase tracking-widest hover:underline"
                                  >
                                    {t('common.edit')}
                                  </button>
                                </div>
                              </motion.div>
                            )}
                          </AnimatePresence>
                          
                          {/* Navigation Controls */}
                          {findings.length > 1 && (
                            <div className="absolute top-1/2 -translate-y-1/2 left-0 right-0 flex justify-between px-2 w-full pointer-events-none">
                              <button 
                                onClick={isRTL ? nextFinding : prevFinding}
                                className="w-8 h-8 rounded-full bg-[var(--color-card)] shadow-md flex items-center justify-center text-[var(--color-text-muted)] hover:bg-[var(--color-bg-soft)] transition-colors pointer-events-auto"
                              >
                                <ChevronRight size={18} className="rotate-180" />
                              </button>
                              <button 
                                onClick={isRTL ? prevFinding : nextFinding}
                                className="w-8 h-8 rounded-full bg-[var(--color-card)] shadow-md flex items-center justify-center text-[var(--color-text-muted)] hover:bg-[var(--color-bg-soft)] transition-colors pointer-events-auto"
                              >
                                <ChevronRight size={18} />
                              </button>
                            </div>
                          )}

                          {/* Pagination Indicators */}
                          {findings.length > 1 && (
                            <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex items-center gap-1.5 z-10">
                              {findings.map((_, idx) => (
                                <button
                                  key={idx}
                                  onClick={() => setCurrentFindingIndex(idx)}
                                  className={`h-1.5 rounded-full transition-all ${idx === currentFindingIndex ? 'w-4 bg-[var(--color-primary)]' : 'w-1.5 bg-slate-300'}`}
                                />
                              ))}
                            </div>
                          )}
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </>
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-[var(--color-text-muted)] space-y-4">
                <ClipboardList size={64} className="opacity-20" />
                <p className="text-lg font-bold uppercase tracking-widest">{t('common.selectTaskToExecute')}</p>
              </div>
            )}
          </div>

          {/* Right Sidebar: Evidence & Links */}
          <div className="w-96 bg-[var(--color-card)] border-s border-[var(--color-border-soft)] flex flex-col p-6">
            <h3 className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] mb-6">{t('common.evidenceAndAttachments')}</h3>
            
            <div className="mb-8">
              <div className="p-8 border-2 border-dashed border-[var(--color-border-soft)] rounded-2xl flex flex-col items-center justify-center text-center group hover:border-[var(--color-primary)]/50 hover:bg-[var(--color-primary)]/5 transition-all cursor-pointer">
                <div className="w-12 h-12 bg-[var(--color-bg-soft)] rounded-2xl flex items-center justify-center text-[var(--color-text-muted)] mb-4 group-hover:bg-[var(--color-primary)] group-hover:text-white transition-all">
                  <Upload size={24} />
                </div>
                <p className="text-xs font-bold text-[var(--color-text-main)] mb-1">{t('common.uploadEvidence')}</p>
                <p className="text-[10px] font-medium text-[var(--color-text-muted)]">{t('common.dragAndDropFile')}</p>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar space-y-4">
              <h4 className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest border-b border-slate-50 pb-2">{t('common.recentEvidence')}</h4>
              {evidence.length === 0 ? (
                <p className="text-[10px] font-bold text-[var(--color-border-strong)] text-center py-8 italic">{t('common.noEvidenceUploaded')}</p>
              ) : (
                evidence.map((item) => (
                  <div key={item.id} className="p-3 rounded-2xl bg-[var(--color-bg-soft)] flex items-center gap-3 group">
                    <div className="w-10 h-10 bg-[var(--color-card)] rounded-xl flex items-center justify-center text-blue-500 shadow-sm">
                      <FileText size={20} />
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-xs font-bold text-[var(--color-text-main)] truncate">{item.file_name}</p>
                      <p className="text-[9px] font-medium text-[var(--color-text-muted)] underline">{item.type || 'General'}</p>
                    </div>
                    <button className="w-8 h-8 rounded-lg hover:bg-[var(--color-bg-main)] flex items-center justify-center text-[var(--color-text-muted)] opacity-0 group-hover:opacity-100 transition-opacity">
                      <Plus size={14} />
                    </button>
                  </div>
                ))
              )}

              <h4 className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest border-b border-slate-50 pb-2 mt-8">{t('common.linkedRecommendations')}</h4>
              {findings.map(f => (
                <div key={`rec-${f.id}`} className="space-y-2">
                  <div className="flex items-center gap-2 p-3 rounded-2xl bg-emerald-50/50 border border-emerald-100/50">
                    <CheckCircle2 size={14} className="text-emerald-500" />
                    <p className="text-[10px] font-bold text-emerald-800 line-clamp-1">{t('common.recommendationFor')}: {f.title}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      <Modal 
        isOpen={isFindingModalOpen}
        onClose={() => setIsFindingModalOpen(false)}
        title={selectedFinding ? t('findings.editFinding') : t('findings.addFinding')}
      >
        <FindingForm 
          onSuccess={() => {
            setIsFindingModalOpen(false);
            fetchData();
          }}
          onCancel={() => setIsFindingModalOpen(false)}
          initialData={selectedFinding ? { ...selectedFinding, audit_id: planId } : { audit_id: planId }}
        />
      </Modal>
    </div>
  );
};

export default AuditWorkspace;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { 
  ShieldCheck, Search, Filter, Plus, Edit2, Trash2, Eye, 
  Download, FileText, CheckCircle, AlertTriangle, XCircle, AlertCircle,
  LayoutGrid, List, BarChart3, ArrowRight, Calendar, User, Building,
  Tag, Info, MoreHorizontal, ChevronRight, FileDown, Layers, Upload
} from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { motion, AnimatePresence } from 'motion/react';
import api from '../../services/api';
import Modal from '../../components/Modal';
import { useDepartments } from '../../hooks/useDepartments';
import { useFormat } from '../../services/formatService';
import toast from 'react-hot-toast';
import logger from '../../utils/logger';

// --- Types ---
type ComplianceStatus = 'compliant' | 'partial' | 'non_compliant' | 'under_review';
type SourceType = 'cbi_instruction' | 'law' | 'internal_policy' | 'admin_decision';

interface ComplianceItem {
  id: string;
  ref_number: string;
  title: string;
  source_type: SourceType;
  issuing_authority?: string | null;
  category?: string | null;
  issue_date?: string | null;
  effective_date?: string | null;
  review_date?: string | null;
  compliance_status: ComplianceStatus;
  maturity_score?: number | null;
  gap_notes?: string | null;
  responsible_person_id?: string | null;
  responsible_person_name?: string | null;
  department_id?: string | null;
  department_name?: string | null;
  description?: string | null;
  keywords?: string | null;
  version?: string | null;
  attachment_path?: string | null;
  open_findings_count?: number;
}

export default function ComplianceMatrix() {
  const { t } = useTranslation();
  const { formatNumber } = useFormat();

  const statusConfig: Record<ComplianceStatus, { color: string, icon: any, label: string }> = {
    compliant: { color: 'emerald', icon: CheckCircle, label: t('complianceMatrix.compliant') },
    partial: { color: 'amber', icon: AlertTriangle, label: t('complianceMatrix.partial') },
    non_compliant: { color: 'rose', icon: XCircle, label: t('complianceMatrix.nonCompliant') },
    under_review: { color: 'slate', icon: AlertCircle, label: t('complianceMatrix.underReview') },
  };

  const sourceLabels: Record<SourceType, string> = {
    cbi_instruction: t('complianceMatrix.cbiInstruction'),
    law: t('complianceMatrix.law'),
    internal_policy: t('complianceMatrix.internalPolicy'),
    admin_decision: t('complianceMatrix.adminDecision'),
  };

  const sourceColors: Record<SourceType, string> = {
    cbi_instruction: 'primary',
    law: 'purple',
    internal_policy: 'emerald',
    admin_decision: 'orange',
  };

  const [activeTab, setActiveTab] = useState<'registry'|'matrix'|'dashboard'>('registry');
  const [items, setItems] = useState<ComplianceItem[]>([]);
  const [summary, setSummary] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  
  // Modals
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);

  // Stable close handler to prevent unnecessary re-renders cascading through Modal → FocusTrap
  const handleModalClose = useCallback(() => { setIsModalOpen(false); }, []);
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<ComplianceItem | null>(null);
  const [formData, setFormData] = useState<Partial<ComplianceItem>>({ compliance_status: 'under_review' });
  const [file, setFile] = useState<File | null>(null);

  // Filters
  const [search, setSearch] = useState('');
  const [filterSource, setFilterSource] = useState('');
  const [filterStatus, setFilterStatus] = useState('');

  // Dropdown data
  const [users, setUsers] = useState<any[]>([]);
  const { departments } = useDepartments();

  useEffect(() => {
    fetchItems();
    fetchSummary();
  }, [filterSource, filterStatus, search]);

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchItems = async () => {
    setLoading(true);
    try {
      const q = new URLSearchParams();
      if (search) q.append('search', search);
      if (filterSource) q.append('source_type', filterSource);
      if (filterStatus) q.append('compliance_status', filterStatus);
      const res = await api.get('/compliance?' + q.toString());
      if (res.data.success) setItems(res.data.data);
    } catch (e) {
      logger.error('Operation failed', e);
      toast.error(t('complianceMatrix.loadError'));
    } finally {
      setLoading(false);
    }
  };

  const fetchSummary = async () => {
    try {
      const res = await api.get('/compliance/summary');
      if (res.data.success) setSummary(res.data.data);
    } catch (e) {
      logger.error('Operation failed', e);
    }
  };

  const fetchUsers = async () => {
    try {
      const uRes = await api.get('/users/summary');
      if (uRes.data?.success) setUsers(uRes.data.data);
      else {
        const uResFallback = await api.get('/users');
        if (uResFallback.data?.success) setUsers(uResFallback.data.data);
      }
    } catch (e) {}
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const data = new FormData();
      Object.entries(formData).forEach(([key, value]) => {
        if (value !== undefined && value !== null) {
          data.append(key, value.toString());
        }
      });
      if (file) {
        data.append('attachment', file);
      }

      const config = {
        headers: { 'Content-Type': 'multipart/form-data' }
      };

      if (selectedItem?.id) {
        await api.put('/compliance/' + selectedItem.id, data, config);
        toast.success(t('complianceMatrix.updateSuccess'));
      } else {
        await api.post('/compliance', data, config);
        toast.success(t('complianceMatrix.addSuccess'));
      }
      setIsModalOpen(false);
      setFile(null);
      fetchItems();
      fetchSummary();
    } catch (err) {
      logger.error('Operation failed', err);
      toast.error(t('complianceMatrix.saveError'));
    }
  };

  const confirmDelete = async () => {
    if (!itemToDelete) return;
    try {
      await api.delete('/compliance/' + itemToDelete);
      toast.success(t('complianceMatrix.deleteSuccess'));
      fetchItems();
      fetchSummary();
      setIsDeleteModalOpen(false);
      setItemToDelete(null);
    } catch (e) {
      logger.error('Operation failed', e);
      toast.error(t('complianceMatrix.deleteError'));
    }
  };

  const handleDelete = (id: string) => {
    setItemToDelete(id);
    setIsDeleteModalOpen(true);
  };

  const updateStatus = async (id: string, status: string) => {
    try {
      await api.patch('/compliance/' + id + '/status', { compliance_status: status });
      toast.success(t('complianceMatrix.statusUpdateSuccess'));
      fetchItems();
      fetchSummary();
    } catch (e) {
      logger.error('Operation failed', e);
      toast.error(t('complianceMatrix.statusUpdateError'));
    }
  };

  const getStatusBadge = (status: ComplianceStatus) => {
    const config = statusConfig[status];
    const Icon = config.icon;
    return (
      <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider border shadow-sm
        ${status === 'compliant' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 
          status === 'non_compliant' ? 'bg-rose-50 text-rose-700 border-rose-100' : 
          status === 'partial' ? 'bg-amber-50 text-amber-700 border-amber-100' : 
          'bg-[var(--color-bg-soft)] text-[var(--color-text-main)] border-[var(--color-border-soft)]'}`}>
        <Icon size={12} strokeWidth={3} />
        {config.label}
      </span>
    );
  };

  const getSourceBadge = (type: SourceType) => {
    const label = sourceLabels[type] || type;
    const color = sourceColors[type] || 'slate';
    return (
      <span className={`px-2 py-0.5 rounded text-[9px] font-bold uppercase tracking-tighter border
        ${color === 'primary' ? 'bg-[var(--color-primary)]/10 text-[var(--color-primary)] border-[var(--color-primary)]/20' :
          color === 'purple' ? 'bg-purple-50 text-purple-600 border-purple-100' :
          color === 'emerald' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' :
          'bg-orange-50 text-orange-600 border-orange-100'}`}>
        {label}
      </span>
    );
  };

  // --- RENDERS ---
  const renderRegistry = () => (
    <div className="space-y-6">
      <div className="flex flex-col lg:flex-row justify-between gap-4 bg-[var(--color-bg-soft)]/50 p-4 rounded-2xl border border-[var(--color-border-soft)]">
        <div className="relative group flex-1 max-w-md">
          <Search className="absolute end-4 top-1/2 -translate-y-1/2 text-[var(--color-text-muted)] group-focus-within:text-[var(--color-primary)] transition-colors" size={18} />
          <input 
            type="text" placeholder={t('complianceMatrix.searchPlaceholder')} 
            className="w-full bg-[var(--color-card)] pe-12 ps-4 py-2.5 rounded-xl border border-[var(--color-border-soft)] text-sm focus:ring-2 focus:ring-[var(--color-primary)]/20 focus:border-[var(--color-primary)] outline-none transition-all shadow-sm"
            value={search} onChange={e => setSearch(e.target.value)}
          />
        </div>
        
        <div className="flex flex-wrap items-center gap-3 lg:pb-0">
          <div className="flex items-center gap-2 px-3 py-1.5 bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-xl shadow-sm cursor-pointer">
            <Filter size={14} className="text-[var(--color-text-muted)]" />
            <select className="bg-transparent text-xs font-medium outline-none border-none p-0 cursor-pointer min-w-[120px]" value={filterSource} onChange={e => setFilterSource(e.target.value)}>
              <option value="">{t('complianceMatrix.allSources')}</option>
              {Object.entries(sourceLabels).map(([k,v]) => <option key={k} value={k}>{v}</option>)}
            </select>
          </div>
          <div className="flex items-center gap-2 px-3 py-1.5 bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-xl shadow-sm">
            <ShieldCheck size={14} className="text-[var(--color-text-muted)]" />
            <select className="bg-transparent text-xs font-medium outline-none border-none p-0 cursor-pointer min-w-[120px]" value={filterStatus} onChange={e => setFilterStatus(e.target.value)}>
              <option value="">{t('complianceMatrix.allStatuses')}</option>
              {Object.entries(statusConfig).map(([k,v]) => <option key={k} value={k}>{v.label}</option>)}
            </select>
          </div>
          <motion.button 
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.98 }}
            className="flex items-center gap-2 px-5 py-2.5 bg-[var(--color-primary)] text-white rounded-xl shadow-md shadow-[var(--color-primary)]/20 text-sm font-bold whitespace-nowrap" 
            onClick={() => { setSelectedItem(null); setFormData({ compliance_status: 'under_review' }); setIsModalOpen(true); }}
          >
            <Plus size={18} /> {t('complianceMatrix.addRecord')}
          </motion.button>
        </div>
      </div>

      <div className="glass-card">
        <div className="overflow-x-visible lg:overflow-x-auto">
          <table className="w-full text-start">
            <thead>
              <tr className="border-b border-[var(--color-border-soft)] bg-[var(--color-bg-soft)]/50">
                <th className="px-6 py-4 text-[11px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('complianceMatrix.ref')}</th>
                <th className="px-6 py-4 text-[11px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('complianceMatrix.titleData')}</th>
                <th className="px-6 py-4 text-[11px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('complianceMatrix.source')}</th>
                <th className="px-6 py-4 text-[11px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('complianceMatrix.complianceStatus')}</th>
                <th className="px-6 py-4 text-[11px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('complianceMatrix.responsible', t('complianceMatrix.personResp'))}</th>
                <th className="px-6 py-4 text-[11px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('complianceMatrix.review')}</th>
                <th className="px-6 py-4 text-center text-[11px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('complianceMatrix.actions')}</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[var(--color-border-soft)]">
              <AnimatePresence mode="popLayout">
                {items.map((item, idx) => (
                  <motion.tr 
                    layout
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: idx * 0.03 }}
                    key={item.id} 
                    className="hover:bg-[var(--color-primary)]/5 transition-colors group"
                  >
                    <td className="px-6 py-5 whitespace-nowrap">
                      <span className="text-[10px] font-bold font-mono text-[var(--color-text-muted)] group-hover:text-[var(--color-primary)] transition-colors bg-[var(--color-bg-main)] px-2 py-1 rounded border border-[var(--color-border-soft)] uppercase">
                        {item.ref_number}
                      </span>
                    </td>
                    <td className="px-6 py-5 min-w-[200px]">
                      <div className="font-bold text-[var(--color-text-main)] leading-tight mb-1 truncate max-w-sm" title={item.title}>{item.title}</div>
                      <div className="flex items-center gap-3">
                        <span className="text-[9px] text-[var(--color-text-muted)] flex items-center gap-1 font-medium">
                          <Tag size={10} /> {item.category || t('complianceMatrix.noCategory')}
                        </span>
                        {item.open_findings_count ? (
                          <span className="flex items-center gap-1 text-[9px] font-bold text-rose-500 bg-rose-50 px-1.5 py-0.5 rounded border border-rose-100">
                            <AlertTriangle size={10} /> {formatNumber(item.open_findings_count)} {t('complianceMatrix.remarks')}
                          </span>
                        ) : null}
                      </div>
                    </td>
                    <td className="px-6 py-5 whitespace-nowrap">{getSourceBadge(item.source_type)}</td>
                    <td className="px-6 py-5 whitespace-nowrap">{getStatusBadge(item.compliance_status)}</td>
                    <td className="px-6 py-5 whitespace-nowrap">
                      <div className="flex items-center gap-2">
                         <div className="w-7 h-7 rounded-full bg-[var(--color-bg-main)] flex items-center justify-center border border-[var(--color-border-soft)]">
                            <User size={12} className="text-[var(--color-text-muted)]" />
                         </div>
                         <div className="text-xs font-bold text-[var(--color-text-main)]">{item.responsible_person_name || t('complianceMatrix.notSpecified')}</div>
                      </div>
                    </td>
                    <td className="px-6 py-5 whitespace-nowrap">
                      <div className="flex flex-col gap-0.5">
                        <span className={`text-[10px] font-bold flex items-center gap-1 ${item.review_date && new Date(item.review_date) < new Date() ? 'text-rose-500' : 'text-[var(--color-text-muted)]'}`}>
                          <Calendar size={10} /> {item.review_date || '-- / -- / --'}
                        </span>
                        {item.review_date && new Date(item.review_date) < new Date() && (
                          <span className="text-[8px] font-bold text-rose-400 uppercase tracking-tighter">{t('complianceMatrix.overdue')}</span>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-5 whitespace-nowrap">
                      <div className="flex items-center justify-center gap-1">
                        <button onClick={() => { setSelectedItem(item); setFormData(item); setIsViewModalOpen(true); }} className="p-2 text-[var(--color-text-muted)] hover:text-[var(--color-primary)] hover:bg-[var(--color-primary)]/10 rounded-lg transition-all" title={t('common.view')}><Eye size={18} /></button>
                        <button onClick={() => { setSelectedItem(item); setFormData(item); setIsModalOpen(true); }} className="p-2 text-[var(--color-text-muted)] hover:text-emerald-500 hover:bg-emerald-50 rounded-lg transition-all" title={t('common.edit')}><Edit2 size={18} /></button>
                        
                        <div className="relative group/actions">
                          <button className="p-2 text-[var(--color-text-muted)] hover:text-[var(--color-text-muted)] hover:bg-[var(--color-bg-soft)] rounded-lg transition-all">
                            <MoreHorizontal size={18} />
                          </button>
                          <div className="absolute start-0 bottom-full mb-1 hidden group-hover/actions:flex flex-col bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-xl shadow-xl z-[100] min-w-[140px] animate-in fade-in slide-in-from-bottom-2 duration-200">
                             <div className="px-3 py-2 text-[10px] font-bold text-[var(--color-text-muted)] bg-[var(--color-bg-soft)] border-b border-[var(--color-border-soft)] uppercase tracking-widest text-center">{t('complianceMatrix.changeStatus')}</div>
                             {Object.entries(statusConfig).map(([k,v]) => (
                               <button 
                                 key={k}
                                 onClick={() => updateStatus(item.id, k as ComplianceStatus)}
                                 className="px-4 py-2 text-[11px] font-bold text-[var(--color-text-muted)] hover:bg-[var(--color-bg-soft)] text-end flex items-center gap-2 transition-colors"
                               >
                                 <v.icon size={12} className={`text-${v.color}-500`} />
                                 {v.label}
                               </button>
                             ))}
                             <div className="border-t border-[var(--color-border-soft)] mt-1">
                                <button onClick={() => handleDelete(item.id)} className="w-full px-4 py-2 text-[11px] font-bold text-rose-500 hover:bg-rose-50 text-end flex items-center gap-2 transition-colors">
                                  <Trash2 size={12} /> {t('common.delete')}
                                </button>
                             </div>
                          </div>
                        </div>
                      </div>
                    </td>
                  </motion.tr>
                ))}
              </AnimatePresence>
            </tbody>
          </table>
          {(loading || items.length === 0) && (
            <div className="flex flex-col items-center justify-center py-20 bg-[var(--color-card)]/20">
               {loading ? (
                 <div className="animate-spin rounded-full h-10 w-10 border-4 border-[var(--color-primary)] border-t-transparent shadow-lg shadow-[var(--color-primary)]/20"></div>
               ) : (
                 <>
                  <div className="bg-[var(--color-bg-main)] p-6 rounded-full border-2 border-dashed border-[var(--color-border-strong)] mb-4 animate-pulse">
                    <ShieldCheck size={48} className="text-[var(--color-border-strong)]" />
                  </div>
                  <p className="text-[var(--color-text-muted)] font-bold">{t('complianceMatrix.noRecords')}</p>
                  <p className="text-[var(--color-text-muted)] text-sm mt-1">{t('complianceMatrix.tryAdjustFilters')}</p>
                 </>
               )}
            </div>
          )}
        </div>
      </div>
    </div>
  );

  const renderMatrix = () => {
    const statuses: ComplianceStatus[] = ['compliant', 'partial', 'non_compliant', 'under_review'];
    
    return (
      <div className="space-y-6">
        <div className="flex justify-between items-center bg-[var(--color-bg-soft)]/50 p-4 rounded-2xl border border-[var(--color-border-soft)]">
           <div>
              <h3 className="font-bold text-[var(--color-text-main)] uppercase tracking-tighter flex items-center gap-2">
                <Layers size={18} className="text-[var(--color-primary)]" /> {t('complianceMatrix.gapMatrix')}
              </h3>
              <p className="text-[10px] text-[var(--color-text-muted)] font-bold">{t('complianceMatrix.gapMatrixDesc')}</p>
           </div>
           <div className="flex gap-2">
              <button className="flex items-center gap-2 px-4 py-2 bg-[var(--color-card)] border border-[var(--color-border-soft)] hover:border-[var(--color-border-strong)] text-[var(--color-text-muted)] rounded-xl text-xs font-bold transition-all shadow-sm group">
                <FileDown size={14} className="group-hover:translate-y-0.5 transition-transform" /> {t('complianceMatrix.exportPdf')}
              </button>
              <button className="flex items-center gap-2 px-4 py-2 bg-[var(--color-card)] border border-[var(--color-border-soft)] hover:border-[var(--color-border-strong)] text-[var(--color-text-muted)] rounded-xl text-xs font-bold transition-all shadow-sm group">
                <BarChart3 size={14} className="group-hover:scale-110 transition-transform" /> {t('complianceMatrix.detailedStats')}
              </button>
           </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-6">
          {statuses.map((status, sIdx) => {
            const stItems = items.filter(i => i.compliance_status === status);
            const config = statusConfig[status];
            const Icon = config.icon;
            
            return (
              <motion.div 
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={{ delay: sIdx * 0.1 }}
                key={status} 
                className="flex flex-col h-[600px] bg-[var(--color-bg-soft)]/50 rounded-3xl border border-[var(--color-border-soft)]/50 overflow-hidden shadow-inner"
              >
                <div className={`p-4 border-b-2 flex justify-between items-center bg-[var(--color-card)] border-${config.color}-500/30`}>
                  <div className="flex items-center gap-2.5">
                    <div className={`p-2 bg-${config.color}-50 rounded-lg text-${config.color}-600 border border-${config.color}-100`}>
                      <Icon size={16} strokeWidth={3} />
                    </div>
                    <span className="font-bold text-[var(--color-text-main)] text-[11px] uppercase tracking-wider">{config.label}</span>
                  </div>
                  <span className={`bg-${config.color}-100 text-${config.color}-700 px-2.5 py-0.5 rounded-full text-[10px] font-bold font-mono border border-${config.color}-200`}>
                    {formatNumber(stItems.length)}
                  </span>
                </div>

                <div className="flex-1 p-3 space-y-3 overflow-y-auto scrollbar-hide">
                  {stItems.map((item, iIdx) => (
                    <motion.div 
                      key={item.id}
                      whileHover={{ scale: 1.02 }}
                      onClick={() => { setSelectedItem(item); setFormData(item); setIsViewModalOpen(true); }}
                      className="group p-4 bg-[var(--color-card)] rounded-2xl border border-[var(--color-border-soft)] shadow-sm hover:shadow-md hover:border-[var(--color-primary)]/30 transition-all cursor-pointer relative overflow-hidden"
                    >
                      <div className={`absolute top-0 end-0 w-1 h-full bg-${config.color}-400/50 group-hover:bg-${config.color}-500 transition-colors`}></div>
                      <div className="text-[9px] font-bold font-mono text-[var(--color-text-muted)] group-hover:text-[var(--color-primary)] mb-1 leading-none">{item.ref_number}</div>
                      <div className="font-bold text-[var(--color-text-main)] text-xs mb-2 leading-snug truncate-2-lines">{item.title}</div>
                      
                      <div className="flex items-center justify-between mt-auto pt-2 border-t border-[var(--color-border-soft)]/50">
                        {getSourceBadge(item.source_type)}
                        <div className="flex -space-x-1 space-x-reverse">
                           <div className="w-5 h-5 rounded-full bg-[var(--color-primary)]/10 border-2 border-white flex items-center justify-center text-[8px] font-bold text-[var(--color-primary)]" title={item.responsible_person_name || ''}>
                             {(item.responsible_person_name || t('complianceMatrix.notSpecified'))[0]}
                           </div>
                        </div>
                      </div>
                    </motion.div>
                  ))}
                  {stItems.length === 0 && (
                    <div className="flex flex-col items-center justify-center h-40 text-[var(--color-border-strong)] opacity-50 space-y-2">
                       <ShieldCheck size={32} />
                       <span className="text-[10px] font-bold uppercase tracking-widest italic">{t('complianceMatrix.noData')}</span>
                    </div>
                  )}
                </div>
              </motion.div>
            );
          })}
        </div>
      </div>
    );
  };

  const renderDashboard = () => {
    const total = summary?.total || items.length;
    const getCount = (st: ComplianceStatus) => items.filter(i => i.compliance_status === st).length;
    
    const overdueItems = items.filter(i => i.review_date && new Date(i.review_date) < new Date()).sort((a,b) => new Date(a.review_date!).getTime() - new Date(b.review_date!).getTime());

    const stats = [
      { label: t('complianceMatrix.totalRecords'), value: total, color: 'primary', icon: BarChart3, highlight: 'primary/10', class: 'text-[var(--color-primary)]' },
      { label: t('complianceMatrix.fullyCompliant'), value: getCount('compliant'), color: 'emerald', icon: CheckCircle, highlight: 'emerald-500/10' },
      { label: t('complianceMatrix.nonCompliantGaps'), value: getCount('non_compliant'), color: 'rose', icon: XCircle, highlight: 'rose-500/10' },
      { label: t('complianceMatrix.overdueReviews'), value: overdueItems.length, color: 'amber', icon: AlertTriangle, highlight: 'amber-500/10' },
      { label: t('complianceMatrix.pendingVerification'), value: getCount('under_review'), color: 'slate', icon: AlertCircle, highlight: 'slate-500/10' },
    ];

    return (
      <div className="space-y-8 pb-10">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-5">
           {stats.map((stat, idx) => (
             <motion.div 
              key={idx}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: idx * 0.1 }}
              className={`glass-card p-5 border-b-4 border-b-${stat.color}-500 shadow-xl shadow-${stat.color}-500/5 hover:shadow-${stat.color}-500/10 transition-all group`}
             >
                <div className="flex justify-between items-start mb-3">
                   <div className={`p-2 rounded-xl bg-${stat.color}-50 text-${stat.color}-600 group-hover:scale-110 transition-transform`}>
                      <stat.icon size={20} />
                   </div>
                   <span className="text-[10px] font-bold text-[var(--color-text-muted)] group-hover:text-[var(--color-text-muted)] uppercase tracking-widest">{stat.label}</span>
                </div>
                <div className={`text-3xl font-bold text-[var(--color-text-main)] group-hover:text-${stat.color}-600 transition-colors`}>{formatNumber(stat.value)}</div>
             </motion.div>
           ))}
        </div>

        <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
           <div className="xl:col-span-2 glass-card p-8">
              <div className="flex items-center justify-between mb-8">
                 <div>
                    <h3 className="text-xl font-bold text-[var(--color-text-main)] tracking-tight flex items-center gap-3">
                       <AlertTriangle className="text-amber-500" /> {t('complianceMatrix.overdueReviews')}
                    </h3>
                    <p className="text-xs text-[var(--color-text-muted)] font-bold mt-1">{t('complianceMatrix.overdueReviewsDesc')}</p>
                 </div>
                 <button className="text-[10px] font-bold text-[var(--color-primary)] hover:text-[var(--color-primary-hover)] flex items-center gap-1 uppercase tracking-widest p-2 bg-[var(--color-primary)]/10 rounded-lg transition-colors">
                    {t('complianceMatrix.viewAll')} <ChevronRight size={12} className="rotate-180" />
                 </button>
              </div>

              <div className="space-y-4 max-h-[450px] overflow-y-auto pe-2 custom-scrollbar">
                {overdueItems.map((item, idx) => (
                  <motion.div 
                    initial={{ opacity: 0, x: 20 }}
                    whileInView={{ opacity: 1, x: 0 }}
                    transition={{ delay: idx * 0.05 }}
                    key={item.id} 
                    className="group flex flex-col sm:flex-row justify-between items-start sm:items-center p-5 bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-2xl hover:border-amber-200 hover:bg-amber-50/20 transition-all shadow-sm"
                  >
                    <div className="flex items-start gap-4">
                       <div className="w-12 h-12 rounded-2xl bg-amber-50 border border-amber-100 flex items-center justify-center text-amber-500 font-bold text-sm shadow-inner group-hover:scale-110 transition-transform">
                          {formatNumber(idx + 1)}
                       </div>
                       <div className="min-w-0">
                          <div className="flex items-center gap-2 mb-1">
                            <span className="text-[10px] font-bold font-mono text-[var(--color-text-muted)] bg-[var(--color-bg-main)] px-2 py-0.5 rounded uppercase tracking-tighter">{item.ref_number}</span>
                            <div className="text-sm font-bold text-[var(--color-text-main)] truncate max-w-[200px] lg:max-w-md">{item.title}</div>
                          </div>
                          <div className="flex items-center gap-3 text-[10px] text-[var(--color-text-muted)] font-bold">
                            <span className="flex items-center gap-1"><Building size={10} /> {item.department_name || t('complianceMatrix.unspecifiedDept')}</span>
                            <span className="flex items-center gap-1"><User size={10} /> {item.responsible_person_name || t('complianceMatrix.notSpecified')}</span>
                          </div>
                       </div>
                    </div>
                    <div className="flex flex-col items-end gap-2 mt-4 sm:mt-0">
                       <div className="flex items-center gap-2 px-3 py-1.5 bg-rose-100 text-rose-700 rounded-xl text-[10px] font-bold border border-rose-200 shadow-sm animate-pulse">
                           {t('complianceMatrix.overdue')} {formatNumber(Math.ceil((new Date().getTime() - new Date(item.review_date!).getTime()) / (1000 * 3600 * 24)))} {t('complianceMatrix.overdueDays')}
                       </div>
                       <div className="text-[10px] font-bold px-2 py-1 bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-lg shadow-sm text-[var(--color-text-muted)] font-mono tracking-tighter">
                          {item.review_date}
                       </div>
                    </div>
                  </motion.div>
                ))}
                {overdueItems.length === 0 && (
                  <div className="flex flex-col items-center justify-center py-20 text-[var(--color-border-strong)] italic">
                    <CheckCircle size={48} className="mb-4 opacity-20" />
                    <p className="font-bold uppercase tracking-widest text-xs">{t('complianceMatrix.noOverdue')}</p>
                  </div>
                )}
              </div>
           </div>
           
           <div className="glass-card p-8">
              <h3 className="text-xl font-bold text-[var(--color-text-main)] tracking-tight mb-8 flex items-center gap-3">
                 <Layers size={22} className="text-[var(--color-primary)]" /> {t('complianceMatrix.complianceDist')}
              </h3>
              <div className="space-y-6">
                {(Object.entries(sourceLabels) as [SourceType, string][]).map(([type, label], idx) => {
                  const count = items.filter(i => i.source_type === type).length;
                  const pct = total === 0 ? 0 : Math.round((count / total) * 100);
                  const color = sourceColors[type];
                  
                  return (
                    <motion.div 
                      key={type}
                      initial={{ opacity: 0, x: -20 }}
                      whileInView={{ opacity: 1, x: 0 }}
                      transition={{ delay: idx * 0.1 }}
                    >
                      <div className="flex justify-between items-end mb-2">
                        <div>
                          <span className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest block mb-1">{label}</span>
                          <span className={`text-xs font-bold text-${color}-600`}>{formatNumber(pct)}% {t('complianceMatrix.ofTotal')}</span>
                        </div>
                        <div className="text-end">
                          <span className="text-xl font-bold text-[var(--color-text-main)] leading-none">{formatNumber(count)}</span>
                          <span className="text-[9px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest block">{t('complianceMatrix.activeRecord')}</span>
                        </div>
                      </div>
                      <div className="h-3 w-full bg-[var(--color-bg-main)] rounded-full overflow-hidden shadow-inner p-0.5 border border-[var(--color-border-soft)]">
                        <motion.div 
                          initial={{ width: 0 }}
                          whileInView={{ width: `${pct}%` }}
                          transition={{ duration: 1, ease: 'easeOut' }}
                          className={`h-full rounded-full bg-gradient-to-r from-${color}-500 to-${color}-600 shadow-sm`}
                        ></motion.div>
                      </div>
                    </motion.div>
                  );
                })}
              </div>

              <div className="mt-12 p-6 rounded-3xl bg-[var(--color-primary)]/5 border border-[var(--color-primary)]/10 shadow-inner relative overflow-hidden group">
                 <div className="absolute top-0 end-0 w-32 h-32 bg-[var(--color-primary)]/5 rounded-full -mr-16 -mt-16 blur-2xl group-hover:scale-150 transition-transform duration-1000"></div>
                 <div className="relative z-10">
                    <h4 className="text-sm font-bold text-[var(--color-primary)] mb-2">{t('complianceMatrix.maturityLevel')}</h4>
                    <div className="flex items-end gap-3 mb-4">
                       <span className="text-4xl font-bold text-[var(--color-primary)] leading-none">
                         {formatNumber(Math.round(items.reduce((acc, i) => acc + (i.maturity_score || 0), 0) / (items.length || 1)))}%
                       </span>
                       <span className="text-[10px] font-bold text-[var(--color-primary)] opacity-40 uppercase tracking-widest pb-1 italic leading-none">{t('complianceMatrix.overallRating')}</span>
                    </div>
                    <p className="text-[10px] text-[var(--color-primary)] font-bold leading-relaxed opacity-60">{t('complianceMatrix.maturityDesc')}</p>
                 </div>
              </div>
           </div>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-10">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div className="flex items-center gap-6">
          <div className="w-12 h-12 sm:w-16 sm:h-16 bg-[var(--color-primary)] rounded-2xl flex items-center justify-center text-white shadow-lg shadow-[var(--color-primary)]/20">
            <ShieldCheck size={32} />
          </div>
          <div>
            <h2 className="text-2xl sm:text-4xl font-bold text-[var(--color-text-main)] tracking-tight">{t('common.complianceMatrix')}</h2>
            <p className="text-sm text-[var(--color-text-muted)] font-bold mt-2">{t('complianceMatrix.subTitle')}</p>
          </div>
        </div>
      </div>

      {/* Tabs — matches system-wide tab pattern */}
      <div className="flex gap-2 p-1 bg-[var(--color-bg-main)] rounded-2xl w-fit">
        {[
          { id: 'registry', label: t('complianceMatrix.generalRegistry'), icon: List },
          { id: 'matrix', label: t('complianceMatrix.gapMatrixTab'), icon: Layers },
          { id: 'dashboard', label: t('complianceMatrix.dashboard'), icon: LayoutGrid }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex items-center gap-2 px-6 py-3 rounded-xl text-sm font-bold transition-all cursor-pointer
              ${activeTab === tab.id ? 'bg-[var(--color-card)] text-[var(--color-primary)] shadow-sm' : 'text-[var(--color-text-muted)] hover:text-[var(--color-text-main)]'}`}
          >
            <tab.icon size={18} /> {tab.label}
          </button>
        ))}
      </div>

      <motion.div
        key={activeTab}
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.3 }}
      >
        {activeTab === 'registry' && renderRegistry()}
        {activeTab === 'matrix' && renderMatrix()}
        {activeTab === 'dashboard' && renderDashboard()}
      </motion.div>

      {/* Write/Edit Modal */}
      <Modal isOpen={isModalOpen} onClose={handleModalClose} title={selectedItem ? t('complianceMatrix.editRecord') : t('complianceMatrix.addRecord')}>
        <form onSubmit={handleSave} className="space-y-8 p-1">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-6">
               <div className="p-6 bg-[var(--color-bg-soft)]/50 rounded-3xl border border-[var(--color-border-soft)] shadow-inner">
                  <h4 className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-6 flex items-center gap-2 border-b border-[var(--color-border-soft)] pb-2">
                     <Info size={14} /> {t('complianceMatrix.basicData')}
                  </h4>
                  <div className="space-y-5">
                    <div>
                      <label className="block text-[11px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-2 px-1">{t('complianceMatrix.refSymbolic')} *</label>
                      <input type="text" required className="w-full bg-[var(--color-card)] px-4 py-3 rounded-2xl border border-[var(--color-border-soft)] text-sm font-bold focus:ring-2 focus:ring-[var(--color-primary)]/20 focus:border-[var(--color-primary)] outline-none transition-all" value={formData.ref_number || ''} onChange={e => setFormData({...formData, ref_number: e.target.value})} placeholder={t('complianceMatrix.refPlaceholder')} />
                    </div>
                    <div>
                      <label className="block text-[11px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-2 px-1">{t('complianceMatrix.titleLabel')}</label>
                      <input type="text" required className="w-full bg-[var(--color-card)] px-4 py-3 rounded-2xl border border-[var(--color-border-soft)] text-sm font-bold focus:ring-2 focus:ring-[var(--color-primary)]/20 focus:border-[var(--color-primary)] outline-none transition-all" value={formData.title || ''} onChange={e => setFormData({...formData, title: e.target.value})} placeholder={t('complianceMatrix.titlePlaceholder')} />
                    </div>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                       <div>
                          <label className="block text-[11px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-2 px-1">{t('complianceMatrix.source')} *</label>
                          <select required className="w-full bg-[var(--color-card)] px-4 py-3 rounded-2xl border border-[var(--color-border-soft)] text-sm font-bold focus:ring-2 focus:ring-[var(--color-primary)]/20 focus:border-[var(--color-primary)] outline-none transition-all appearance-none" value={formData.source_type || ''} onChange={e => setFormData({...formData, source_type: e.target.value as SourceType})}>
                            <option value="">{t('complianceMatrix.selectSource')}</option>
                            {Object.entries(sourceLabels).map(([k,v]) => <option key={k} value={k}>{v}</option>)}
                          </select>
                       </div>
                       <div>
                          <label className="block text-[11px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-2 px-1">{t('complianceMatrix.issuingAuthority')}</label>
                          <input type="text" className="w-full bg-[var(--color-card)] px-4 py-3 rounded-2xl border border-[var(--color-border-soft)] text-sm font-bold focus:ring-2 focus:ring-[var(--color-primary)]/20 focus:border-[var(--color-primary)] outline-none transition-all" value={formData.issuing_authority || ''} onChange={e => setFormData({...formData, issuing_authority: e.target.value})} />
                       </div>
                    </div>
                  </div>
               </div>

               <div className="p-6 bg-[var(--color-bg-soft)]/50 rounded-3xl border border-[var(--color-border-soft)] shadow-inner">
                  <h4 className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-6 flex items-center gap-2 border-b border-[var(--color-border-soft)] pb-2">
                     <Building size={14} /> {t('complianceMatrix.responsibilities')}
                  </h4>
                  <div className="space-y-5">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                       <div>
                          <label className="block text-[11px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-2 px-1">{t('complianceMatrix.personResp')}</label>
                          <select className="w-full bg-[var(--color-card)] px-4 py-3 rounded-2xl border border-[var(--color-border-soft)] text-sm font-bold focus:ring-2 focus:ring-[var(--color-primary)]/20 focus:border-[var(--color-primary)] outline-none transition-all" value={formData.responsible_person_id || ''} onChange={e => setFormData({...formData, responsible_person_id: e.target.value})}>
                            <option value="">{t('complianceMatrix.selectPerson')}</option>
                            {users.map(u => <option key={u.id} value={u.id}>{u.name || u.full_name || u.username}</option>)}
                          </select>
                       </div>
                       <div>
                          <label className="block text-[11px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-2 px-1">{t('complianceMatrix.deptResp')}</label>
                          <select className="w-full bg-[var(--color-card)] px-4 py-3 rounded-2xl border border-[var(--color-border-soft)] text-sm font-bold focus:ring-2 focus:ring-[var(--color-primary)]/20 focus:border-[var(--color-primary)] outline-none transition-all" value={formData.department_id || ''} onChange={e => setFormData({...formData, department_id: e.target.value})}>
                            <option value="">{t('complianceMatrix.selectDept')}</option>
                            {departments.map(d => <option key={d.id} value={d.id}>{d.name_ar || d.name_en || d.name}</option>)}
                          </select>
                       </div>
                    </div>
                  </div>
               </div>
            </div>

            <div className="space-y-6">
               <div className="p-6 bg-[var(--color-bg-soft)]/50 rounded-3xl border border-[var(--color-border-soft)] shadow-inner">
                  <h4 className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-6 flex items-center gap-2 border-b border-[var(--color-border-soft)] pb-2">
                     <ShieldCheck size={14} /> {t('complianceMatrix.evalMatch')}
                  </h4>
                  <div className="space-y-5">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                       <div>
                          <label className="block text-[11px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-2 px-1">{t('complianceMatrix.statusLabel')}</label>
                          <select className="w-full bg-[var(--color-card)] px-4 py-3 rounded-2xl border border-[var(--color-border-soft)] text-sm font-bold focus:ring-2 focus:ring-[var(--color-primary)]/20 focus:border-[var(--color-primary)] outline-none transition-all" value={formData.compliance_status || 'under_review'} onChange={e => setFormData({...formData, compliance_status: e.target.value as ComplianceStatus})}>
                            {Object.entries(statusConfig).map(([k,v]) => <option key={k} value={k}>{v.label}</option>)}
                          </select>
                       </div>
                       <div>
                          <label className="block text-[11px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-2 px-1">{t('complianceMatrix.maturityScoreLabel')}</label>
                          <input type="number" min="0" max="100" className="w-full bg-[var(--color-card)] px-4 py-3 rounded-2xl border border-[var(--color-border-soft)] text-sm font-bold focus:ring-2 focus:ring-[var(--color-primary)]/20 focus:border-[var(--color-primary)] outline-none transition-all" value={formData.maturity_score || ''} onChange={e => setFormData({...formData, maturity_score: parseInt(e.target.value)})} />
                       </div>
                    </div>
                    <div>
                      <label className="block text-[11px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-2 px-1">{t('complianceMatrix.requiredActions')}</label>
                      <textarea className="w-full bg-[var(--color-card)] px-4 py-3 rounded-2xl border border-[var(--color-border-soft)] text-sm font-bold focus:ring-2 focus:ring-[var(--color-primary)]/20 focus:border-[var(--color-primary)] outline-none transition-all" rows={3} value={formData.gap_notes || ''} onChange={e => setFormData({...formData, gap_notes: e.target.value})} placeholder={t('complianceMatrix.gapNotesPlaceholder')}></textarea>
                    </div>
                  </div>
               </div>

               <div className="p-6 bg-[var(--color-bg-soft)]/50 rounded-3xl border border-[var(--color-border-soft)] shadow-inner">
                  <h4 className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-6 flex items-center gap-2 border-b border-[var(--color-border-soft)] pb-2">
                     <Calendar size={14} /> {t('complianceMatrix.importantDates')}
                  </h4>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                     <div>
                        <label className="block text-[11px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-2 px-1">{t('complianceMatrix.effectiveDate')}</label>
                        <input type="date" className="w-full bg-[var(--color-card)] px-4 py-3 rounded-2xl border border-[var(--color-border-soft)] text-sm font-bold focus:ring-2 focus:ring-[var(--color-primary)]/20 focus:border-[var(--color-primary)] outline-none transition-all" value={formData.effective_date || ''} onChange={e => setFormData({...formData, effective_date: e.target.value})} />
                     </div>
                     <div>
                        <label className="block text-[11px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-2 px-1">{t('complianceMatrix.nextReviewDate')}</label>
                        <input type="date" className="w-full bg-[var(--color-card)] px-4 py-3 rounded-2xl border border-[var(--color-border-soft)] text-sm font-bold focus:ring-2 focus:ring-[var(--color-primary)]/20 focus:border-[var(--color-primary)] outline-none transition-all" value={formData.review_date || ''} onChange={e => setFormData({...formData, review_date: e.target.value})} />
                     </div>
                  </div>
               </div>

               <div className="p-6 bg-[var(--color-bg-soft)]/50 rounded-3xl border border-[var(--color-border-soft)] shadow-inner">
                  <h4 className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-6 flex items-center gap-2 border-b border-[var(--color-border-soft)] pb-2">
                     <FileText size={14} /> {t('complianceMatrix.docsAttachments')}
                  </h4>
                  <div>
                    <label className="block text-[11px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-2 px-1">{t('complianceMatrix.uploadPdf')}</label>
                    <div className="relative group/file">
                      <input 
                        type="file" 
                        accept=".pdf" 
                        className="absolute inset-0 opacity-0 cursor-pointer z-10" 
                        onChange={e => {
                          if (e.target.files?.[0]) {
                            setFile(e.target.files[0]);
                          }
                        }}
                      />
                      <div className={`w-full px-4 py-3 rounded-2xl border-2 border-dashed transition-all flex items-center justify-between
                        ${file ? 'border-[var(--color-primary)] bg-[var(--color-primary)]/5' : 'border-[var(--color-border-soft)] bg-[var(--color-card)] group-hover/file:border-[var(--color-primary)]/50'}`}>
                        <div className="flex items-center gap-3">
                          <FileText size={18} className={file ? 'text-[var(--color-primary)]' : 'text-[var(--color-text-muted)]'} />
                          <span className={`text-xs font-bold truncate max-w-[200px] ${file ? 'text-[var(--color-primary)]' : 'text-[var(--color-text-muted)]'}`}>
                            {file ? file.name : (formData.attachment_path ? t('complianceMatrix.fileUploaded') : t('complianceMatrix.dragFile'))}
                          </span>
                        </div>
                        <Upload size={16} className={file ? 'text-[var(--color-primary)]' : 'text-[var(--color-text-muted)]'} />
                      </div>
                    </div>
                  </div>
               </div>
            </div>
          </div>
          
          <div className="flex justify-end items-center gap-4 mt-12 bg-[var(--color-card)]/50 backdrop-blur-md p-6 -mx-6 -mb-6 border-t border-[var(--color-border-soft)]">
            <button type="button" onClick={() => setIsModalOpen(false)} className="px-8 py-3 text-[var(--color-text-muted)] font-bold text-xs uppercase tracking-widest hover:text-[var(--color-text-main)] transition-colors">{t('complianceMatrix.cancel')}</button>
            <motion.button 
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
              type="submit" 
              className="px-10 py-3 bg-[var(--color-primary)] text-white rounded-2xl text-xs font-bold shadow-xl shadow-[var(--color-primary)]/20 uppercase tracking-widest hover:bg-[var(--color-primary-hover)] transition-all"
            >
              {t('complianceMatrix.saveChanges')}
            </motion.button>
          </div>
        </form>
      </Modal>

      {/* Delete Confirmation Modal */}
      <Modal 
        isOpen={isDeleteModalOpen} 
        onClose={() => {
          setIsDeleteModalOpen(false);
          setItemToDelete(null);
        }} 
        title={t('deleteConfirm')}
      >
        <div className="space-y-6 pt-2">
          <div className="flex items-center gap-4 p-4 bg-[var(--color-danger-light)] rounded-2xl border border-[var(--color-danger)]/20">
            <div className="w-12 h-12 rounded-xl bg-[var(--color-danger)] flex items-center justify-center text-white shadow-lg shadow-[var(--color-danger)]/20">
              <Trash2 size={24} />
            </div>
            <div>
              <h4 className="font-bold text-[var(--color-danger)] text-sm">{t('deleteConfirm')}</h4>
              <p className="text-[var(--color-text-muted)] text-[10px] font-bold">{t('deleteMessage')}</p>
            </div>
          </div>
          
          <div className="flex justify-end gap-3 pt-2">
            <button 
              onClick={() => {
                setIsDeleteModalOpen(false);
                setItemToDelete(null);
              }}
              className="btn-secondary"
            >
              {t('common.cancel')}
            </button>
            <button 
              onClick={confirmDelete}
              className="btn-danger"
            >
              {t('common.delete')}
            </button>
          </div>
        </div>
      </Modal>

      {/* View Modal */}
      <Modal isOpen={isViewModalOpen} onClose={() => setIsViewModalOpen(false)} title={t('complianceMatrix.viewDetails')}>
        {selectedItem && (
          <div className="space-y-8 p-1">
            <div className="flex flex-col sm:flex-row justify-between items-start gap-4">
              <div className="flex-1">
                <div className="flex items-center gap-3 mb-2">
                   <span className="text-[10px] font-bold font-mono text-[var(--color-primary)] bg-[var(--color-primary)]/10 px-2 py-1 rounded border border-[var(--color-primary)]/20 uppercase tracking-tighter">
                      {selectedItem.ref_number}
                   </span>
                   {getSourceBadge(selectedItem.source_type)}
                </div>
                <h2 className="text-2xl font-bold text-[var(--color-text-main)] tracking-tight leading-tight">{selectedItem.title}</h2>
              </div>
              <div className="shrink-0">{getStatusBadge(selectedItem.compliance_status)}</div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
              {[
                { label: t('complianceMatrix.deptResp'), value: selectedItem.department_name || '-', icon: Building, color: 'primary' },
                { label: t('complianceMatrix.personResp'), value: selectedItem.responsible_person_name || '-', icon: User, color: 'emerald' },
                { label: t('complianceMatrix.issueDate'), value: selectedItem.issue_date || '-', icon: Calendar, color: 'slate' },
                { label: t('complianceMatrix.nextReview'), value: selectedItem.review_date || '-', icon: Calendar, color: 'warning' }
              ].map((info, idx) => (
                <div key={idx} className="bg-[var(--color-bg-soft)]/50 p-4 rounded-2xl border border-[var(--color-border-soft)] shadow-sm relative overflow-hidden group">
                   <div className={`absolute top-0 end-0 w-1 h-full bg-${info.color === 'primary' ? '[var(--color-primary)]' : 
                                                                     info.color === 'warning' ? 'amber-500' :
                                                                     info.color === 'emerald' ? 'emerald-500' : 'slate-500'} group-hover:w-2 transition-all`}></div>
                   <div className="text-[9px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-1 flex items-center gap-1.5 leading-none">
                      <info.icon size={10} /> {info.label}
                   </div>
                   <div className="text-xs font-bold text-[var(--color-text-main)] truncate">{info.value}</div>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
               <div className="md:col-span-2 space-y-8">
                  {selectedItem.description && (
                    <section>
                      <h3 className="text-[11px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-3 flex items-center gap-2">
                         <Info size={14} className="text-[var(--color-primary)]" /> {t('complianceMatrix.reqDesc')}
                      </h3>
                      <div className="p-6 bg-[var(--color-card)] rounded-3xl border border-[var(--color-border-soft)] shadow-sm text-sm text-[var(--color-text-muted)] font-bold leading-relaxed">
                         {selectedItem.description}
                      </div>
                    </section>
                  )}

                  {selectedItem.gap_notes && (
                    <section>
                      <h3 className="text-[11px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-3 flex items-center gap-2">
                         <AlertTriangle size={14} className="text-amber-500" /> {t('complianceMatrix.gapsAndCorrectiveActions')}
                      </h3>
                      <div className="p-6 bg-amber-50/50 rounded-3xl border border-amber-100 text-sm text-amber-900 font-bold leading-relaxed shadow-inner">
                         {selectedItem.gap_notes}
                      </div>
                    </section>
                  )}
               </div>

               <div className="space-y-6">
                  <div className="p-6 bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-2xl shadow-sm relative overflow-hidden group">
                    <div className="absolute -bottom-8 -end-8 w-32 h-32 bg-[var(--color-primary)]/5 rounded-full blur-3xl group-hover:scale-150 transition-transform duration-1000 pointer-events-none"></div>
                    <div className="relative z-10">
                       <h3 className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-6 border-b border-[var(--color-border-soft)] pb-2">{t('complianceMatrix.maturityEvaluation')}</h3>
                       <div className="flex items-center justify-between mb-4">
                          <span className="text-xs font-bold text-[var(--color-text-muted)]">{t('complianceMatrix.percentage')}</span>
                          <span className="text-3xl font-bold text-[var(--color-text-main)]">{formatNumber(selectedItem.maturity_score || 0)}%</span>
                       </div>
                       <div className="h-2 w-full bg-[var(--color-bg-main)] rounded-full overflow-hidden shadow-inner flex p-0.5">
                          <motion.div 
                            initial={{ width: 0 }}
                            animate={{ width: `${selectedItem.maturity_score || 0}%` }}
                            transition={{ duration: 1.5, ease: 'backOut' }}
                            className="h-full rounded-full bg-gradient-to-r from-[var(--color-primary)] to-[var(--color-primary-hover)] shadow-sm shadow-[var(--color-primary)]/50"
                          ></motion.div>
                       </div>
                       <div className="mt-8 pt-6 border-t border-[var(--color-border-soft)]">
                          <button className="w-full py-3 bg-[var(--color-bg-soft)] hover:bg-[var(--color-bg-main)] border border-[var(--color-border-soft)] hover:border-[var(--color-border-soft)] text-[var(--color-text-muted)] hover:text-[var(--color-text-main)] rounded-2xl text-[10px] font-bold uppercase tracking-widest transition-all">{t('complianceMatrix.updateEvaluation')}</button>
                       </div>
                    </div>
                  </div>

                  <div className="glass-card p-6 border-[var(--color-border-soft)]">
                    <h3 className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-4">{t('complianceMatrix.attachmentsDocs')}</h3>
                    {selectedItem.attachment_path ? (
                      <a href={selectedItem.attachment_path} target="_blank" rel="noreferrer" className="flex items-center gap-3 p-4 bg-[var(--color-primary)]/10 rounded-2xl border border-[var(--color-primary)]/20 text-[var(--color-primary)] hover:bg-[var(--color-primary)]/20 transition-colors group">
                         <div className="p-2 bg-[var(--color-card)] rounded-lg shadow-sm group-hover:scale-110 transition-transform">
                            <FileText size={18} />
                         </div>
                         <div className="min-w-0">
                            <div className="text-xs font-bold truncate">{t('complianceMatrix.originalDoc')}</div>
                            <div className="text-[9px] font-bold opacity-60">{t('complianceMatrix.viewAttachedFile')}</div>
                         </div>
                         <Download size={14} className="ms-auto" />
                      </a>
                    ) : (
                      <div className="p-4 bg-[var(--color-bg-soft)] rounded-2xl border border-[var(--color-border-soft)] text-[var(--color-text-muted)] text-[10px] font-bold text-center italic">
                        {t('complianceMatrix.noFilesAttached')}
                      </div>
                    )}
                  </div>
               </div>
            </div>

            <div className="flex justify-end border-t border-[var(--color-border-soft)] pt-6">
              <button onClick={() => setIsViewModalOpen(false)} className="px-8 py-3 bg-[var(--color-bg-main)] text-[var(--color-text-muted)] rounded-2xl text-xs font-bold shadow-inner shadow-[var(--color-border-soft)] uppercase tracking-widest hover:bg-[var(--color-bg-main)] transition-all">{t('complianceMatrix.closeWindow')}</button>
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { useUser } from '../context/UserContext';
import { useTranslation } from 'react-i18next';
import { ShieldAlert, Plus, Edit, CheckCircle2, AlertCircle } from 'lucide-react';
import { motion } from 'motion/react';
import Modal from '../components/Modal';
import api from '../services/api';
import toast from 'react-hot-toast';
import { useFormat } from '../services/formatService';
import { UserRole } from '../constants';
import logger from '../utils/logger';

interface COI {
  id: number;
  user_id: number;
  user_name: string;
  declaration_date: string;
  description: string;
  related_party: string;
  status: string;
  reviewer_notes: string;
}

const ConflictOfInterest: React.FC = () => {
  const { token } = useAuth();
  const { user } = useUser();
  const { t } = useTranslation();
  const { formatDate } = useFormat();
  const [declarations, setDeclarations] = useState<COI[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isReviewModalOpen, setIsReviewModalOpen] = useState(false);
  const [selectedCOI, setSelectedCOI] = useState<COI | null>(null);
  
  const [formData, setFormData] = useState({
    description: '',
    related_party: ''
  });

  const [reviewData, setReviewData] = useState({
    status: 'Reviewed',
    reviewer_notes: ''
  });

  useEffect(() => {
    fetchDeclarations();
  }, []);

  const fetchDeclarations = async () => {
    try {
      const res = await api.get('/coi');
      if (res.data && res.data.data) {
        setDeclarations(res.data.data);
      } else {
        setDeclarations(Array.isArray(res.data) ? res.data : []);
      }
    } catch (err) {
      logger.error('Operation failed', err);
      setDeclarations([]);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await api.post('/coi', formData);
      setIsModalOpen(false);
      setFormData({ description: '', related_party: '' });
      fetchDeclarations();
    } catch (err) {
      logger.error('Operation failed', err);
      toast.error(t('errorOccurred'));
    }
  };

  const handleReviewSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCOI) return;
    try {
      await api.put(`/coi/${selectedCOI.id}`, reviewData);
      setIsReviewModalOpen(false);
      setSelectedCOI(null);
      fetchDeclarations();
    } catch (err) {
      logger.error('Operation failed', err);
      toast.error(t('errorOccurred'));
    }
  };

  const isAdminOrCompliance = user?.role === UserRole.ADMIN || user?.role === UserRole.COMPLIANCE_OFFICER;

  return (
    <div className="space-y-10">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl sm:text-4xl font-bold text-[var(--color-text-main)] tracking-tight">{t('integrity.conflicts')}</h2>
          <p className="text-sm text-[var(--color-text-muted)] font-bold mt-2">{t('integrity.coiSubtitle')}</p>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="btn-primary flex items-center gap-2"
        >
          <Plus size={20} />
          {t('integrity.declareConflict')}
        </button>
      </div>

      <div className="glass-card overflow-hidden">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-start border-collapse">
            <thead>
              <tr className="bg-[var(--color-bg-soft)]/50 border-b border-[var(--color-border-soft)]">
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('common.id')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('common.user')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('integrity.declarationDate')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('integrity.relatedParty')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('common.statusLabel')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[var(--color-border-soft)]/50">
              {(Array.isArray(declarations) ? declarations : []).map((coi, idx) => (
                <motion.tr 
                  key={coi.id}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: idx * 0.05 }}
                  className="hover:bg-[var(--color-primary)]/5 transition-colors group"
                >
                  <td className="px-6 py-4 text-xs font-bold text-[var(--color-border-strong)]">#{coi.id}</td>
                  <td className="px-6 py-4 text-sm font-bold text-[var(--color-text-muted)]">{coi.user_name}</td>
                  <td className="px-6 py-4 text-sm font-bold text-[var(--color-text-muted)]">{formatDate(coi.declaration_date)}</td>
                  <td className="px-6 py-4 text-sm font-bold text-[var(--color-text-muted)]">{coi.related_party}</td>
                  <td className="px-6 py-4">
                    <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-[10px] font-bold uppercase tracking-widest ${
                      coi.status === 'Resolved' ? 'bg-[var(--color-success)]/10 text-[var(--color-success)]' :
                      coi.status === 'Reviewed' ? 'bg-[var(--color-info)]/10 text-[var(--color-info)]' :
                      'bg-[var(--color-warning)]/10 text-[var(--color-warning)]'
                    }`}>
                      {coi.status === 'Resolved' ? <CheckCircle2 size={12} /> : <AlertCircle size={12} />}
                      {coi.status === 'Resolved' ? t('integrity.resolved') : coi.status === 'Reviewed' ? t('integrity.reviewed') : t('integrity.pending')}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-end">
                    {isAdminOrCompliance && (
                      <button 
                        onClick={() => {
                          setSelectedCOI(coi);
                          setReviewData({ status: coi.status, reviewer_notes: coi.reviewer_notes || '' });
                          setIsReviewModalOpen(true);
                        }}
                        className="p-2 text-[var(--color-text-muted)] hover:text-[var(--color-primary)] hover:bg-[var(--color-primary)]/10 rounded-xl transition-colors"
                      >
                        <Edit size={18} />
                      </button>
                    )}
                  </td>
                </motion.tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Declare Modal */}
      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={t('integrity.declareConflict')}>
        <form onSubmit={handleSubmit} className="space-y-6">
          <div>
            <label className="block text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] mb-3">{t('common.description')}</label>
            <textarea
              required
              rows={4}
              className="input-field py-4"
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
            />
          </div>
          <div>
            <label className="block text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] mb-3">{t('integrity.relatedParty')}</label>
            <input
              type="text"
              required
              className="input-field"
              value={formData.related_party}
              onChange={(e) => setFormData({ ...formData, related_party: e.target.value })}
            />
          </div>
          <div className="flex justify-end gap-4 pt-4 border-t border-[var(--color-border-soft)]">
            <button type="button" onClick={() => setIsModalOpen(false)} className="px-6 py-3 rounded-xl bg-[var(--color-bg-main)] text-[var(--color-text-muted)] font-bold hover:bg-[var(--color-bg-main)] transition-colors">
              {t('common.cancel')}
            </button>
            <button type="submit" className="btn-primary">
              {t('common.save')}
            </button>
          </div>
        </form>
      </Modal>

      {/* Review Modal */}
      <Modal isOpen={isReviewModalOpen} onClose={() => setIsReviewModalOpen(false)} title={t('common.edit')}>
        <form onSubmit={handleReviewSubmit} className="space-y-6">
          <div>
            <label className="block text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] mb-3">{t('common.statusLabel')}</label>
            <select
              className="input-field"
              value={reviewData.status}
              onChange={(e) => setReviewData({ ...reviewData, status: e.target.value })}
            >
              <option value="Pending">{t('integrity.pending')}</option>
              <option value="Reviewed">{t('integrity.reviewed')}</option>
              <option value="Resolved">{t('integrity.resolved')}</option>
            </select>
          </div>
          <div>
            <label className="block text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] mb-3">{t('integrity.reviewerNotes')}</label>
            <textarea
              rows={4}
              className="input-field py-4"
              value={reviewData.reviewer_notes}
              onChange={(e) => setReviewData({ ...reviewData, reviewer_notes: e.target.value })}
            />
          </div>
          <div className="flex justify-end gap-4 pt-4 border-t border-[var(--color-border-soft)]">
            <button type="button" onClick={() => setIsReviewModalOpen(false)} className="px-6 py-3 rounded-xl bg-[var(--color-bg-main)] text-[var(--color-text-muted)] font-bold hover:bg-[var(--color-bg-main)] transition-colors">
              {t('common.cancel')}
            </button>
            <button type="submit" className="btn-primary">
              {t('common.save')}
            </button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default ConflictOfInterest;

import React, { useState, useEffect } from 'react';
import { 
  Search, 
  Archive, 
  Eye, 
  Download, 
  Mail, 
  Send,
  Calendar,
  Building,
  Filter
} from 'lucide-react';
import { useTranslation } from 'react-i18next';
import api from '../../services/api';
import toast from 'react-hot-toast';
import logger from '../../utils/logger';
import Pagination from '../../components/Pagination';
import { useFormat } from '../../services/formatService';
import { useDebounce } from '../../hooks/useDebounce';

interface CorrespondenceArchiveProps {
  language: 'ar' | 'en';
  onViewDetails: (type: 'Incoming' | 'Outgoing', id: number) => void;
}

const CorrespondenceArchive: React.FC<CorrespondenceArchiveProps> = ({ language, onViewDetails }) => {
  const { t } = useTranslation();
  const { formatNumber, formatDate } = useFormat();
  const [items, setItems] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const debouncedSearch = useDebounce(search, 500);
  const [typeFilter, setTypeFilter] = useState<'All' | 'Incoming' | 'Outgoing'>('All');
  const [pagination, setPagination] = useState({ page: 1, pageSize: 15, total: 0, totalPages: 0 });

  useEffect(() => {
    fetchArchived();
  }, [debouncedSearch, typeFilter, pagination.page, pagination.pageSize]);

  const fetchArchived = async () => {
    try {
      setLoading(true);
      const response = await api.get('/correspondence/archive', {
        params: {
          page: pagination.page,
          pageSize: pagination.pageSize,
          type: typeFilter !== 'All' ? typeFilter : undefined,
          search: debouncedSearch || undefined
        }
      });
      
      if (response.data.data) {
        setItems(response.data.data);
        setPagination(prev => ({
          ...prev,
          total: response.data.pagination?.total ?? response.data.data.length,
          totalPages: response.data.pagination?.totalPages ?? 1
        }));
      }
    } catch (error) {
      logger.error("Failed to fetch archived correspondence", error);
      toast.error(t('errorOccurred'));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-4">
      <div className="bg-[var(--color-bg-soft)]/50 p-4 rounded-2xl border border-[var(--color-border-soft)] flex flex-wrap items-center gap-4">
        <div className="relative flex-1 min-w-[250px]">
          <Search className="absolute start-4 top-1/2 -translate-y-1/2 text-[var(--color-text-muted)]" size={18} />
          <input 
            type="text"
            placeholder={t('correspondence.searchArchivePlaceholder')}
            className="w-full p-2.5 ps-11 bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-xl text-sm font-bold outline-none focus:border-[var(--color-primary)] transition-colors shadow-sm"
            value={search}
            onChange={(e) => {
              setSearch(e.target.value);
              setPagination(prev => ({ ...prev, page: 1 }));
            }}
          />
        </div>
        
        <div className="flex bg-[var(--color-bg-main)] p-1 rounded-xl border border-[var(--color-border-soft)]">
          <button 
            onClick={() => {
              setTypeFilter('All');
              setPagination(prev => ({ ...prev, page: 1 }));
            }}
            className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${typeFilter === 'All' ? 'bg-[var(--color-card)] text-[var(--color-primary)] shadow-sm' : 'text-[var(--color-text-muted)] hover:text-[var(--color-text-main)]'}`}
          >
            {t('correspondence.all')}
          </button>
          <button 
            onClick={() => {
              setTypeFilter('Incoming');
              setPagination(prev => ({ ...prev, page: 1 }));
            }}
            className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${typeFilter === 'Incoming' ? 'bg-[var(--color-card)] text-[var(--color-primary)] shadow-sm' : 'text-[var(--color-text-muted)] hover:text-[var(--color-text-main)]'}`}
          >
            {t('correspondence.incoming')}
          </button>
          <button 
            onClick={() => {
              setTypeFilter('Outgoing');
              setPagination(prev => ({ ...prev, page: 1 }));
            }}
            className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${typeFilter === 'Outgoing' ? 'bg-[var(--color-card)] text-[var(--color-primary)] shadow-sm' : 'text-[var(--color-text-muted)] hover:text-[var(--color-text-main)]'}`}
          >
            {t('correspondence.outgoing')}
          </button>
        </div>
      </div>

      <div className="bg-[var(--color-card)] rounded-2xl border border-[var(--color-border-soft)] overflow-hidden shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full text-start border-collapse">
            <thead>
              <tr className="bg-[var(--color-bg-soft)]/50 border-b border-[var(--color-border-soft)]">
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('correspondence.type')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('correspondence.seqNumber')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('correspondence.subject')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('correspondence.entity')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('correspondence.archiveDate')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-end">{t('common.actions')}</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[var(--color-border-soft)]/50">
              {loading ? (
                <tr>
                  <td colSpan={6} className="px-6 py-10 text-center text-[var(--color-text-muted)] font-bold text-sm">
                    {t('common.loading')}
                  </td>
                </tr>
              ) : items.length === 0 ? (
                <tr>
                  <td colSpan={6} className="px-6 py-10 text-center text-[var(--color-text-muted)] font-bold text-sm">
                    {t('correspondence.archiveIsEmpty')}
                  </td>
                </tr>
              ) : (Array.isArray(items) ? items : []).map((item, idx) => (
                <tr key={idx} className="hover:bg-[var(--color-primary)]/5 transition-colors group">
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-2">
                      {item.type === 'Incoming' ? (
                        <Mail size={16} className="text-[var(--color-primary)]" />
                      ) : (
                        <Send size={16} className="text-teal-500" />
                      )}
                      <span className="text-[10px] font-bold uppercase tracking-wider text-[var(--color-text-muted)]">{t(`correspondence.${item.type.toLowerCase()}`)}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-xs font-bold text-[var(--color-border-strong)] tracking-widest">{formatNumber(item.sequence_number)}</td>
                  <td className="px-6 py-4 text-sm font-bold text-[var(--color-text-main)] max-w-xs truncate">{item.subject}</td>
                  <td className="px-6 py-4 text-sm font-bold text-[var(--color-text-main)]">{item.entity}</td>
                  <td className="px-6 py-4 text-sm font-bold text-[var(--color-text-main)]">
                    <div className="flex items-center gap-2">
                      <Calendar size={14} className="text-[var(--color-text-muted)]" />
                      {formatDate(item.updated_at) || '-'}
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center justify-end gap-2 md:opacity-0 md:group-hover:opacity-100 transition-opacity">
                      <button 
                        onClick={() => onViewDetails(item.type, item.id)}
                        className="p-2 bg-[var(--color-card)] text-[var(--color-primary)] border border-[var(--color-border-soft)] hover:border-[var(--color-primary)]/30 rounded-xl shadow-sm transition-all"
                        title={t('correspondence.viewDetails')}
                      >
                        <Eye size={16} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <Pagination 
        currentPage={pagination.page}
        totalPages={pagination.totalPages}
        onPageChange={(page) => setPagination(prev => ({ ...prev, page }))}
        pageSize={pagination.pageSize}
        onPageSizeChange={(pageSize) => setPagination(prev => ({ ...prev, pageSize, page: 1 }))}
        totalItems={pagination.total}
      />
    </div>
  );
};

export default CorrespondenceArchive;

import React, { useState, useEffect } from 'react';
import { 
  ArrowLeft, 
  Mail, 
  Send, 
  Clock, 
  CheckCircle, 
  Archive, 
  AlertCircle,
  FileText,
  Link as LinkIcon,
  Paperclip,
  Share2,
  History,
  User,
  Building,
  Calendar,
  Tag,
  Download,
  Plus,
  X,
  ChevronRight,
  ChevronDown,
  Search
} from 'lucide-react';
import { useTranslation } from 'react-i18next';
import api from '../../services/api';
import { motion, AnimatePresence } from 'motion/react';
import { useFormat } from '../../services/formatService';
import logger from '../../utils/logger';

interface CorrespondenceDetailsProps {
  type: 'Incoming' | 'Outgoing';
  id: number;
  language: 'ar' | 'en';
  onBack: () => void;
}

const CorrespondenceDetails: React.FC<CorrespondenceDetailsProps> = ({ type, id, language, onBack }) => {
  const { t } = useTranslation();
  const { formatNumber, formatDate, formatDateTime } = useFormat();
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<'info' | 'history' | 'referrals' | 'attachments'>('info');
  const [showStatusModal, setShowStatusModal] = useState(false);
  const [showReferModal, setShowReferModal] = useState(false);
  const [showUploadModal, setShowUploadModal] = useState(false);
  const [showArchiveModal, setShowArchiveModal] = useState(false);

  useEffect(() => {
    fetchDetails();
  }, [type, id]);

  const fetchDetails = async () => {
    try {
      setLoading(true);
      const endpoint = type === 'Incoming' 
        ? `/correspondence/details/incoming/${id}` 
        : `/correspondence/details/outgoing/${id}`;
      const response = await api.get(endpoint);
      setData(response.data);
    } catch (error) {
      logger.error("Failed to fetch details", error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center p-20">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[var(--color-primary)]"></div>
      </div>
    );
  }

  if (!data) {
    return (
      <div className="p-10 text-center">
        <p className="text-[var(--color-text-muted)]">{t('correspondence.dataNotFound')}</p>
        <button onClick={onBack} className="mt-4 text-[var(--color-primary)] hover:underline">{t('correspondence.goBack')}</button>
      </div>
    );
  }

  const mainData = data.main;

  return (
    <div className="space-y-6 max-w-6xl mx-auto">
      {/* Breadcrumb */}
      <nav aria-label="Breadcrumb" className="flex items-center gap-1.5 text-xs">
        <ol className="flex items-center gap-1.5 list-none p-0 m-0">
          <li className="flex items-center gap-1.5">
            <button onClick={onBack} className="font-medium text-[var(--color-text-muted)] hover:text-[var(--color-primary)] transition-colors cursor-pointer">
              {t('common.cms')}
            </button>
          </li>
          <li className="flex items-center gap-1.5">
            <ChevronRight size={12} className="text-[var(--color-border-strong)] rtl:rotate-180" />
            <button onClick={onBack} className="font-medium text-[var(--color-text-muted)] hover:text-[var(--color-primary)] transition-colors cursor-pointer">
              {t(`correspondence.${type.toLowerCase()}`)}
            </button>
          </li>
          <li className="flex items-center gap-1.5">
            <ChevronRight size={12} className="text-[var(--color-border-strong)] rtl:rotate-180" />
            <span className="font-semibold text-[var(--color-text-main)]" aria-current="page">
              #{formatNumber(mainData.sequence_number)}
            </span>
          </li>
        </ol>
      </nav>

      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          <button 
            onClick={onBack}
            className="p-2 hover:bg-[var(--color-bg-main)] rounded-full transition-colors text-[var(--color-text-main)]"
            aria-label={t('common.goBack') || 'Go back'}
          >
            <ArrowLeft size={24} className="rtl:rotate-180" />
          </button>
          <div>
            <div className="flex items-center gap-2">
              <span className={`px-2 py-0.5 rounded text-xs font-bold uppercase ${type === 'Incoming' ? 'bg-[var(--color-primary)]/10 text-[var(--color-primary)]' : 'bg-[var(--color-info)]/10 text-[var(--color-info)]'}`}>
                {t('correspondence.' + type.toLowerCase())}
              </span>
              <h1 className="text-2xl font-bold text-[var(--color-text-main)]">{formatNumber(mainData.sequence_number)}</h1>
            </div>
            <p className="text-[var(--color-text-muted)] flex items-center gap-2">
              <FileText size={16} />
              {mainData.subject}
            </p>
          </div>
        </div>
        <div className="flex flex-wrap gap-2">
          {type !== 'Outgoing' && (
            <>
              <button 
                onClick={() => setShowStatusModal(true)}
                className="btn-secondary flex items-center gap-2"
              >
                <Clock size={18} />
                {t('correspondence.updateStatus')}
              </button>
              <button 
                onClick={() => setShowReferModal(true)}
                className="btn-secondary flex items-center gap-2"
              >
                <Share2 size={18} />
                {t('correspondence.refer')}
              </button>
            </>
          )}
          <button 
            onClick={() => setShowArchiveModal(true)}
            className="px-4 py-2 bg-[var(--color-text-muted)] text-white rounded-lg hover:bg-[var(--color-text-main)] flex items-center gap-2 transition-colors font-bold"
          >
            <Archive size={18} />
            {t('correspondence.archive')}
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Column: Main Info */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-[var(--color-card)] rounded-2xl border border-[var(--color-border-soft)] shadow-sm overflow-hidden">
            <div className="flex border-b border-[var(--color-border-soft)] overflow-x-auto">
              <DetailTab active={activeTab === 'info'} onClick={() => setActiveTab('info')} label={t('correspondence.basicInfo')} icon={<FileText size={18} />} />
              <DetailTab active={activeTab === 'history'} onClick={() => setActiveTab('history')} label={t('correspondence.statusHistory')} icon={<History size={18} />} />
              {type !== 'Outgoing' && (
                <DetailTab active={activeTab === 'referrals'} onClick={() => setActiveTab('referrals')} label={t('correspondence.referrals')} icon={<Share2 size={18} />} />
              )}
              <DetailTab active={activeTab === 'attachments'} onClick={() => setActiveTab('attachments')} label={t('correspondence.attachments')} icon={<Paperclip size={18} />} />
            </div>

            <div className="p-6">
              {activeTab === 'info' && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-y-6 gap-x-12">
                  <InfoItem label={t('correspondence.letterNo')} value={formatNumber(mainData.letter_number || mainData.official_number || mainData.sequence_number)} />
                  <InfoItem label={t('correspondence.date')} value={formatDate(mainData.letter_date)} />
                  <InfoItem label={type === 'Outgoing' ? t('correspondence.recipient') : t('correspondence.sender')} value={mainData.sender_entity || mainData.recipient_entity} />
                  {type !== 'Outgoing' && <InfoItem label={t('correspondence.entityType')} value={t('correspondence.' + mainData.sender_entity_type?.toLowerCase().replace(/\s+/g, '_')) || mainData.sender_entity_type} />}
                  <InfoItem label={t('correspondence.classification')} value={t('correspondence.' + mainData.classification?.toLowerCase().replace(/\s+/g, '_')) || mainData.classification} />
                  {type !== 'Outgoing' && <InfoItem label={t('correspondence.priority')} value={t('correspondence.' + mainData.priority?.toLowerCase().replace(/\s+/g, '_')) || mainData.priority} />}
                  <InfoItem label={t('correspondence.method')} value={t('correspondence.' + (mainData.method || mainData.sending_method)?.toLowerCase().replace(/\s+/g, '_')) || mainData.method || mainData.sending_method} />
                  <InfoItem label={t('correspondence.currentStatus')} value={t('correspondence.' + mainData.status?.toLowerCase().replace(/\s+/g, '_')) || mainData.status || t('correspondence.pending')} isStatus />
                  <div className="md:col-span-2">
                    <InfoItem label={t('correspondence.notes')} value={mainData.notes || t('correspondence.noNotes')} />
                  </div>
                </div>
              )}

              {activeTab === 'history' && (
                <div className="space-y-4">
                  {data.history.length === 0 ? (
                    <p className="text-center text-[var(--color-text-muted)] py-8">{t('correspondence.noStatusHistory')}</p>
                  ) : (
                    <div className="relative border-s-2 border-[var(--color-border-soft)] ms-3 space-y-8 py-2">
                      {(Array.isArray(data.history) ? data.history : []).map((h: any, idx: number) => (
                        <div key={idx} className="relative ps-8">
                          <div className="absolute -start-[9px] top-0 w-4 h-4 rounded-full bg-[var(--color-primary)] border-2 border-white"></div>
                          <div className="flex flex-col">
                            <span className="text-sm font-bold text-[var(--color-text-main)]">{t('correspondence.' + h.status.toLowerCase().replace(/\s+/g, '_')) || h.status}</span>
                            <span className="text-xs text-[var(--color-text-muted)]">{formatDateTime(h.changed_at)}</span>
                            <p className="text-sm text-[var(--color-text-main)] mt-1 opacity-80">{h.notes}</p>
                            <span className="text-xs text-[var(--color-primary)] mt-1 flex items-center gap-1">
                              <User size={12} />
                              {h.changed_by_name}
                            </span>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}

              {activeTab === 'referrals' && (
                <div className="space-y-4">
                  {data.referrals.length === 0 ? (
                    <p className="text-center text-[var(--color-text-muted)] py-8">{t('correspondence.noReferrals')}</p>
                  ) : (
                    <div className="space-y-4">
                      {(Array.isArray(data.referrals) ? data.referrals : []).map((r: any, idx: number) => (
                        <div key={idx} className="p-4 bg-[var(--color-bg-main)] rounded-xl border border-[var(--color-border-soft)] flex justify-between items-start">
                          <div>
                            <div className="flex items-center gap-2 mb-1">
                              <Building size={16} className="text-[var(--color-text-muted)]" />
                              <span className="font-semibold text-[var(--color-text-main)]">{language === 'ar' ? r.to_dept_name_ar : r.to_dept_name_en}</span>
                            </div>
                            {r.to_user_name && (
                              <div className="flex items-center gap-2 mb-2">
                                <User size={14} className="text-[var(--color-text-muted)]" />
                                <span className="text-sm text-[var(--color-text-main)] opacity-80">{r.to_user_name}</span>
                              </div>
                            )}
                            <p className="text-sm text-[var(--color-text-main)] opacity-80 italic">"{r.instructions}"</p>
                          </div>
                          <div className="text-end">
                            <span className="text-xs text-[var(--color-text-muted)] block">{formatDate(r.referral_date)}</span>
                            <span className="text-xs text-[var(--color-primary)] font-medium">{t('correspondence.by')}{r.from_user_name}</span>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}

              {activeTab === 'attachments' && (
                <div className="space-y-4">
                  <div className="flex justify-between items-center mb-4">
                    <h3 className="font-semibold text-[var(--color-text-main)]">{t('correspondence.attachedFiles')}</h3>
                    <button 
                      onClick={() => setShowUploadModal(true)}
                      className="text-[var(--color-primary)] text-sm font-medium flex items-center gap-1 hover:underline"
                    >
                      <Plus size={16} />
                      {t('correspondence.addAttachment')}
                    </button>
                  </div>
                  {data.attachments.length === 0 ? (
                    <p className="text-center text-[var(--color-text-muted)] py-8">{t('correspondence.noAttachments')}</p>
                  ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      {(Array.isArray(data.attachments) ? data.attachments : []).map((a: any, idx: number) => (
                        <div key={idx} className="p-4 bg-[var(--color-bg-main)] rounded-xl border border-[var(--color-border-soft)] flex items-center justify-between">
                          <div className="flex items-center gap-3">
                            <div className="p-2 bg-[var(--color-card)] rounded-lg border border-[var(--color-border-soft)]">
                              <FileText size={20} className="text-[var(--color-primary)]" />
                            </div>
                            <div>
                              <p className="text-sm font-medium text-[var(--color-text-main)] truncate max-w-[150px]">{a.file_name}</p>
                              <p className="text-xs text-[var(--color-text-muted)]">{a.file_type} • {formatDate(a.uploaded_at)}</p>
                            </div>
                          </div>
                          <button className="p-2 text-[var(--color-text-muted)] hover:text-[var(--color-primary)] transition-colors">
                            <Download size={18} />
                          </button>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Right Column: Tracking & Summary */}
        <div className="space-y-6">
          {type !== 'Outgoing' && (
            <div className="bg-[var(--color-card)] rounded-2xl border border-[var(--color-border-soft)] shadow-sm p-6">
              <h3 className="font-bold text-[var(--color-text-main)] mb-4 flex items-center gap-2">
                <Clock size={18} className="text-[var(--color-primary)]" />
                {t('correspondence.followUpTracking')}
              </h3>
              <div className="space-y-4">
                <div className="flex justify-between items-center">
                  <span className="text-sm text-[var(--color-text-muted)]">{t('correspondence.followUpRequired')}</span>
                  <span className={`px-2 py-0.5 rounded text-xs font-bold ${mainData.follow_up_required ? 'bg-[var(--color-warning)]/10 text-[var(--color-warning)]' : 'bg-[var(--color-bg-main)] text-[var(--color-text-muted)]'}`}>
                    {mainData.follow_up_required ? t('correspondence.yes') : t('correspondence.no')}
                  </span>
                </div>
                {mainData.follow_up_required && (
                  <div className="flex justify-between items-center">
                    <span className="text-sm text-[var(--color-text-muted)]">{t('correspondence.followUpDate')}</span>
                    <span className="text-sm font-medium text-[var(--color-text-main)]">{formatDate(mainData.follow_up_date)}</span>
                  </div>
                )}
                <div className="border-t border-[var(--color-border-soft)] pt-4">
                  <div className="flex justify-between items-center">
                    <span className="text-sm text-[var(--color-text-muted)]">{t('correspondence.responseRequired')}</span>
                    <span className={`px-2 py-0.5 rounded text-xs font-bold ${mainData.response_required ? 'bg-[var(--color-primary)]/10 text-[var(--color-primary)]' : 'bg-[var(--color-bg-main)] text-[var(--color-text-muted)]'}`}>
                      {mainData.response_required ? t('correspondence.yes') : t('correspondence.no')}
                    </span>
                  </div>
                  {mainData.response_required && (
                    <div className="mt-2 flex justify-between items-center">
                       <span className="text-sm text-[var(--color-text-muted)]">{t('correspondence.dueDate')}</span>
                       <span className="text-sm font-medium text-[var(--color-danger)]">{formatDate(mainData.response_due_date)}</span>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          {type !== 'Outgoing' && (
            <div className="bg-[var(--color-card)] rounded-2xl border border-[var(--color-border-soft)] shadow-sm p-6">
              <h3 className="font-bold text-[var(--color-text-main)] mb-4 flex items-center gap-2">
                <User size={18} className="text-[var(--color-primary)]" />
                {t('correspondence.responsibility')}
              </h3>
              <div className="space-y-4">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-[var(--color-primary)]/10 flex items-center justify-center text-[var(--color-primary)]">
                    <Building size={20} />
                  </div>
                  <div>
                    <p className="text-xs text-[var(--color-text-muted)]">{t('correspondence.responsibleDept')}</p>
                    <p className="text-sm font-bold text-[var(--color-text-main)]">{language === 'ar' ? mainData.assigned_dept_name_ar : mainData.assigned_dept_name_en || '-'}</p>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-[var(--color-success)]/10 flex items-center justify-center text-[var(--color-success)]">
                    <User size={20} />
                  </div>
                  <div>
                    <p className="text-xs text-[var(--color-text-muted)]">{t('correspondence.assignedUser')}</p>
                    <p className="text-sm font-bold text-[var(--color-text-main)]">{mainData.assigned_user_name || '-'}</p>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Modals */}
      <AnimatePresence>
        {showStatusModal && (
          <StatusUpdateModal 
            language={language} 
            id={id} 
            type={type}
            currentStatus={mainData.status}
            onClose={() => setShowStatusModal(false)}
            onSuccess={() => {
              setShowStatusModal(false);
              fetchDetails();
            }}
          />
        )}
        {showReferModal && (
          <ReferralModal 
            language={language} 
            id={id} 
            onClose={() => setShowReferModal(false)}
            onSuccess={() => {
              setShowReferModal(false);
              fetchDetails();
            }}
          />
        )}
        {showArchiveModal && (
          <ArchiveModal 
            language={language} 
            id={id} 
            type={type}
            onClose={() => setShowArchiveModal(false)}
            onSuccess={() => {
              setShowArchiveModal(false);
              fetchDetails();
            }}
          />
        )}
      </AnimatePresence>
    </div>
  );
};

// Helper Components
const DetailTab = ({ active, onClick, label, icon }: any) => (
  <button
    onClick={onClick}
    className={`flex items-center gap-2 px-6 py-4.5 text-sm transition-all whitespace-nowrap ${
      active 
        ? 'border-b-2 border-[var(--color-primary)] text-[var(--color-primary)] font-bold bg-[var(--color-primary)]/5' 
        : 'border-b-2 border-transparent text-[var(--color-text-muted)] hover:text-[var(--color-text-main)] hover:bg-[var(--color-bg-soft)] font-bold'
    }`}
  >
    {icon}
    {label}
  </button>
);

const InfoItem = ({ label, value, isStatus }: any) => (
  <div>
    <p className="text-xs text-[var(--color-text-muted)] mb-1 font-medium">{label}</p>
    {isStatus ? (
      <span className="px-2 py-1 bg-[var(--color-primary)]/10 text-[var(--color-primary)] rounded-full text-xs font-bold">
        {value}
      </span>
    ) : (
      <p className="text-sm font-bold text-[var(--color-text-main)]">{value}</p>
    )}
  </div>
);

// Modal Components
const ArchiveModal = ({ language, id, type, onClose, onSuccess }: any) => {
  const { t } = useTranslation();
  const [submitting, setSubmitting] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setSubmitting(true);
      await api.put(`/correspondence/archive/${type}/${id}`);
      onSuccess();
    } catch (error) {
      logger.error("Failed to archive", error);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
      <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} className="bg-[var(--color-card)] rounded-2xl border border-[var(--color-border-soft)] shadow-xl overflow-hidden w-full max-w-md">
        <div className="p-6 border-b border-[var(--color-border-soft)] flex justify-between items-center bg-[var(--color-bg-main)]">
          <h2 className="text-lg font-bold text-[var(--color-text-main)]">{t('correspondence.confirmArchive')}</h2>
          <button onClick={onClose} className="p-1 hover:bg-[var(--color-border-soft)] rounded-full text-[var(--color-text-main)]"><X size={20} /></button>
        </div>
        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <p className="text-[var(--color-text-main)]">
            {t('correspondence.confirmArchiveMessage')}
          </p>
          <div className="flex gap-3 pt-4">
            <button type="button" onClick={onClose} className="btn-secondary flex-1">{t('common.cancel')}</button>
            <button type="submit" disabled={submitting} className="btn-primary flex-1 disabled:opacity-50">{submitting ? '...' : t('correspondence.archive')}</button>
          </div>
        </form>
      </motion.div>
    </div>
  );
};

const StatusUpdateModal = ({ language, id, type, currentStatus, onClose, onSuccess }: any) => {
  const { t } = useTranslation();
  const [status, setStatus] = useState(currentStatus);
  const [notes, setNotes] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const statuses = ['Received', 'Registered', 'Under Review', 'Referred', 'Action Taken', 'Closed', 'Cancelled'];

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setSubmitting(true);
      await api.put(`/correspondence/status/${type}/${id}`, { new_status: status, notes });
      onSuccess();
    } catch (error) {
      logger.error("Failed to update status", error);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
      <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} className="bg-[var(--color-card)] rounded-2xl border border-[var(--color-border-soft)] shadow-xl overflow-hidden w-full max-w-md">
        <div className="p-6 border-b border-[var(--color-border-soft)] flex justify-between items-center bg-[var(--color-bg-main)]">
          <h2 className="text-lg font-bold text-[var(--color-text-main)]">{t('correspondence.updateCorrespondenceStatus')}</h2>
          <button onClick={onClose} className="p-1 hover:bg-[var(--color-border-soft)] rounded-full text-[var(--color-text-main)]"><X size={20} /></button>
        </div>
        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div className="space-y-2">
            <label className="text-sm font-semibold text-[var(--color-text-main)]">{t('correspondence.newStatus')}</label>
            <select 
              className="input-field"
              value={status}
              onChange={(e) => setStatus(e.target.value)}
            >
              {statuses.map(s => <option key={s} value={s}>{t('correspondence.' + s.toLowerCase().replace(/\s+/g, '_')) || s}</option>)}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-sm font-semibold text-[var(--color-text-main)]">{t('correspondence.updateNotes')}</label>
            <textarea 
              rows={3}
              className="input-field"
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              placeholder={t('correspondence.updateNotesPlaceholder')}
            />
          </div>
          <div className="flex gap-3 pt-4">
            <button type="button" onClick={onClose} className="btn-secondary flex-1">{t('common.cancel')}</button>
            <button type="submit" disabled={submitting} className="btn-primary flex-1 disabled:opacity-50">{submitting ? '...' : t('common.update')}</button>
          </div>
        </form>
      </motion.div>
    </div>
  );
};

const ReferralModal = ({ language, id, onClose, onSuccess }: any) => {
  const { t } = useTranslation();
  const [deptId, setDeptId] = useState('');
  const [userId, setUserId] = useState('');
  const [instructions, setInstructions] = useState('');
  const [departments, setDepartments] = useState<any[]>([]);
  const [users, setUsers] = useState<any[]>([]);
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    const fetchMeta = async () => {
      const [d, u] = await Promise.all([api.get('/org-entities'), api.get('/users')]);
      setDepartments(d.data);
      setUsers(u.data);
    };
    fetchMeta();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setSubmitting(true);
      await api.post('/correspondence/refer', { incoming_id: id, to_dept_id: deptId, to_user_id: userId, instructions });
      onSuccess();
    } catch (error) {
      logger.error("Failed to refer", error);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
      <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} className="bg-[var(--color-card)] rounded-2xl border border-[var(--color-border-soft)] shadow-xl overflow-hidden w-full max-w-md">
        <div className="p-6 border-b border-[var(--color-border-soft)] flex justify-between items-center bg-[var(--color-bg-main)]">
          <h2 className="text-lg font-bold text-[var(--color-text-main)]">{t('correspondence.referCorrespondence')}</h2>
          <button onClick={onClose} className="p-1 hover:bg-[var(--color-border-soft)] rounded-full text-[var(--color-text-main)]"><X size={20} /></button>
        </div>
        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div className="space-y-2">
            <label className="text-sm font-semibold text-[var(--color-text-main)]">{t('correspondence.targetDeptRequired')}</label>
            <select required className="input-field" value={deptId} onChange={(e) => setDeptId(e.target.value)}>
              <option value="">{t('correspondence.selectDept')}</option>
              {(Array.isArray(departments) ? departments : []).map(d => <option key={d.id} value={d.id}>{language === 'ar' ? d.name_ar : d.name_en}</option>)}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-sm font-semibold text-[var(--color-text-main)]">{t('correspondence.userOptional')}</label>
            <select className="input-field" value={userId} onChange={(e) => setUserId(e.target.value)}>
              <option value="">{t('correspondence.selectUser')}</option>
              {(Array.isArray(users) ? users : []).map(u => <option key={u.id} value={u.id}>{u.name}</option>)}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-sm font-semibold text-[var(--color-text-main)]">{t('correspondence.instructions')}</label>
            <textarea rows={3} className="input-field" value={instructions} onChange={(e) => setInstructions(e.target.value)} />
          </div>
          <div className="flex gap-3 pt-4">
            <button type="button" onClick={onClose} className="btn-secondary flex-1">{t('common.cancel')}</button>
            <button type="submit" disabled={submitting} className="btn-primary flex-1 disabled:opacity-50">{submitting ? '...' : t('correspondence.refer')}</button>
          </div>
        </form>
      </motion.div>
    </div>
  );
};

export default CorrespondenceDetails;

import React, { useState, useEffect } from 'react';
import { 
  Mail, 
  Send, 
  Clock, 
  CheckCircle, 
  Archive, 
  AlertCircle,
  FileText,
  Link as LinkIcon,
  Search,
  Plus,
  Filter,
  Download,
  Eye,
  ArrowRight,
  User,
  Building
} from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { motion } from 'motion/react';
import { useCorrespondence } from '../../hooks/useCorrespondence';
import { correspondenceService } from '../../services/correspondenceService';
import toast from 'react-hot-toast';
import IncomingRegister from './IncomingRegister';
import CorrespondenceDetails from './CorrespondenceDetails';
import CorrespondenceArchive from './CorrespondenceArchive';
import OutgoingRegister from './OutgoingRegister';
import { Language, CorrespondenceType } from '../../constants';
import { useFormat } from '../../services/formatService';

interface CorrespondenceSystemProps {
  language: Language;
  userRole?: string;
}

const CorrespondenceSystem: React.FC<CorrespondenceSystemProps> = ({ language, userRole }) => {
  const { t } = useTranslation();
  const { formatNumber } = useFormat();
  const [activeSubTab, setActiveSubTab] = useState<'dashboard' | 'incoming' | 'outgoing' | 'archive'>('dashboard');
  const [selectedRecord, setSelectedRecord] = useState<{ type: CorrespondenceType, id: number } | null>(null);
  
  const { stats, incoming: recentIncoming, loading, error, fetchStats } = useCorrespondence({ limit: 5 });

  if (loading && activeSubTab === 'dashboard' && !stats) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[var(--color-primary)]"></div>
      </div>
    );
  }

  const renderDashboard = () => (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-5">
        {[
          { title: t('correspondence.totalIncoming'), value: formatNumber(stats?.total_incoming || 0), icon: <Mail size={22} />, color: 'bg-[var(--color-primary)]/10 text-[var(--color-primary)]', onClick: () => setActiveSubTab('incoming') },
          { title: t('correspondence.totalOutgoing'), value: formatNumber(stats?.total_outgoing || 0), icon: <Send size={22} />, color: 'bg-[var(--color-info)]/10 text-[var(--color-info)]', onClick: () => setActiveSubTab('outgoing') },
          { title: t('correspondence.pendingResponses'), value: formatNumber(stats?.pending_response || 0), icon: <Clock size={22} />, color: 'bg-[var(--color-warning)]/10 text-[var(--color-warning)]', onClick: undefined },
          { title: t('correspondence.archive'), value: formatNumber(stats?.archived || 0), icon: <Archive size={22} />, color: 'bg-[var(--color-bg-soft)] text-[var(--color-text-muted)]', onClick: () => setActiveSubTab('archive') },
        ].map((card, idx) => (
          <motion.div
            key={idx}
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: idx * 0.05, duration: 0.3, ease: 'easeOut' }}
            onClick={card.onClick}
            className="interactive-card p-5 group hover:border-[var(--color-primary)]/20"
          >
            <div className="flex items-start justify-between mb-3">
              <div className={`w-11 h-11 rounded-xl ${card.color} flex items-center justify-center group-hover:scale-105 transition-transform duration-200`}>
                {card.icon}
              </div>
            </div>
            <div>
              <p className="text-[11px] font-medium text-[var(--color-text-muted)] uppercase tracking-wider mb-1">{card.title}</p>
              <p className="text-2xl font-bold text-[var(--color-text-main)]">{card.value}</p>
            </div>
          </motion.div>
        ))}
      </div>

      <div className="grid grid-cols-1 gap-6">
        <div className="glass-card p-6">
          <h3 className="text-lg font-semibold mb-4 flex items-center gap-2 text-[var(--color-text-main)]">
            <Mail size={20} className="text-[var(--color-primary)]" />
            {t('correspondence.recentIncomingLetters')}
          </h3>
          <div className="space-y-3">
            {(!Array.isArray(recentIncoming) || recentIncoming.length === 0) ? (
              <p className="text-sm text-[var(--color-text-muted)] italic">
                {t('correspondence.noIncomingCorrespondence')}
              </p>
            ) : (
              recentIncoming.map((item) => (
                <div 
                  key={item.id} 
                  onClick={() => setSelectedRecord({ type: CorrespondenceType.INCOMING, id: item.id })}
                  className="p-3 border border-[var(--color-border-soft)] rounded-xl hover:bg-[var(--color-bg-main)] cursor-pointer transition-colors flex justify-between items-center"
                >
                  <div className="flex flex-col">
                    <span className="text-sm font-bold text-[var(--color-text-main)]">{formatNumber(item.sequence_number)}</span>
                    <span className="text-xs text-[var(--color-text-muted)] truncate max-w-[200px]">{item.subject}</span>
                  </div>
                  <span className="text-xs text-[var(--color-text-muted)]/70">{item.receipt_date}</span>
                </div>
              ))
            )}
          </div>
          <button 
            onClick={() => setActiveSubTab('incoming')}
            className="mt-4 text-[var(--color-primary)] text-sm font-medium hover:underline flex items-center gap-1"
          >
            {t('correspondence.viewAll')}
            <ArrowRight size={14} className={language === Language.AR ? 'rotate-180' : ''} />
          </button>
        </div>
      </div>
    </div>
  );

  if (selectedRecord) {
    return (
      <CorrespondenceDetails 
        type={selectedRecord.type} 
        id={selectedRecord.id} 
        language={language} 
        onBack={() => {
          setSelectedRecord(null);
          fetchStats();
        }} 
      />
    );
  }

  return (
    <div className="space-y-6" dir={language === Language.AR ? 'rtl' : 'ltr'}>
      <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-6">
        <div className="flex items-center gap-5">
          <div className="w-14 h-14 bg-[var(--color-primary)] rounded-2xl flex items-center justify-center text-white shadow-lg shadow-[var(--color-primary)]/20">
            <Mail size={28} />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-[var(--color-text-main)] tracking-tight">
              {t('correspondence.systemTitle')}
            </h1>
            <p className="text-sm text-[var(--color-text-muted)] mt-0.5">
              {t('correspondence.systemDesc')}
            </p>
          </div>
        </div>
        <div className="flex flex-wrap gap-3">
          <button 
            onClick={() => setActiveSubTab('incoming')}
            className="btn-primary flex items-center justify-center gap-2 whitespace-nowrap"
          >
            <Plus size={18} />
            {t('correspondence.registerIncoming')}
          </button>
          <button 
            onClick={() => setActiveSubTab('outgoing')}
            className="btn-secondary flex items-center justify-center gap-2 whitespace-nowrap"
          >
            <Plus size={18} />
            {t('correspondence.registerOutgoing')}
          </button>
        </div>
      </div>

      <div className="flex gap-2 p-1.5 bg-[var(--color-card)] rounded-2xl w-fit overflow-x-auto border border-[var(--color-border-soft)]">
        <TabButton 
          active={activeSubTab === 'dashboard'} 
          onClick={() => setActiveSubTab('dashboard')}
          label={t('common.dashboard')}
          icon={<FileText size={18} />}
        />
        <TabButton 
          active={activeSubTab === 'incoming'} 
          onClick={() => setActiveSubTab('incoming')}
          label={t('correspondence.incomingRegister')}
          icon={<Mail size={18} />}
        />
        <TabButton 
          active={activeSubTab === 'outgoing'} 
          onClick={() => setActiveSubTab('outgoing')}
          label={t('correspondence.outgoingRegister')}
          icon={<Send size={18} />}
        />
        <TabButton 
          active={activeSubTab === 'archive'} 
          onClick={() => setActiveSubTab('archive')}
          label={t('correspondence.archive')}
          icon={<Archive size={18} />}
        />
      </div>

      {activeSubTab === 'dashboard' && renderDashboard()}
      {activeSubTab === 'incoming' && (
        <IncomingRegister 
          language={language} 
          onViewDetails={(id) => setSelectedRecord({ type: CorrespondenceType.INCOMING, id })} 
        />
      )}
      {activeSubTab === 'outgoing' && (
        <OutgoingRegister 
          language={language} 
          userRole={userRole} 
          onViewDetails={(type, id) => setSelectedRecord({ type: type as CorrespondenceType, id })}
        />
      )}
      {activeSubTab === 'archive' && (
        <CorrespondenceArchive 
          language={language} 
          onViewDetails={(type, id) => setSelectedRecord({ type: type as CorrespondenceType, id })} 
        />
      )}
    </div>
  );
};

interface TabButtonProps {
  active: boolean;
  onClick: () => void;
  label: string;
  icon: React.ReactNode;
}

const TabButton: React.FC<TabButtonProps> = ({ active, onClick, label, icon }) => (
  <button
    onClick={onClick}
    className={`flex items-center gap-2.5 px-6 py-3 rounded-xl text-sm font-semibold transition-all whitespace-nowrap ${
