    {label}
  </button>
);

export default CorrespondenceSystem;

import React from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { useTranslation } from 'react-i18next';
import { 
  CorrespondencePriority, 
  CorrespondenceClassification, 
  SendingMethod, 
  EntityType 
} from '../../constants';
import api from '../../services/api';
import toast from 'react-hot-toast';
import { Input } from '../../components/ui/Input';
import { Select } from '../../components/ui/Select';
import logger from '../../utils/logger';
import { Textarea } from '../../components/ui/Textarea';
import { FormField } from '../../components/ui/FormField';

const incomingSchema = z.object({
  letter_number: z.string().optional(),
  sender_entity: z.string().min(1, 'Field is required'),
  sender_entity_type: z.nativeEnum(EntityType),
  subject: z.string().min(1, 'Field is required'),
  letter_date: z.string().min(1, 'Field is required'),
  receipt_date: z.string().min(1, 'Field is required'),
  classification: z.nativeEnum(CorrespondenceClassification),
  priority: z.nativeEnum(CorrespondencePriority),
  method: z.nativeEnum(SendingMethod),
  receiving_dept_id: z.string().optional().transform(val => val ? Number(val) : undefined),
  assigned_dept_id: z.string().optional().transform(val => val ? Number(val) : undefined),
  assigned_user_id: z.string().optional().transform(val => val ? Number(val) : undefined),
  follow_up_required: z.boolean().optional(),
  follow_up_date: z.string().optional(),
  response_required: z.boolean().optional(),
  response_due_date: z.string().optional(),
  notes: z.string().optional(),
});

type IncomingFormValues = z.infer<typeof incomingSchema>;

interface IncomingFormProps {
  language: 'ar' | 'en';
  departments: any[];
  users: any[];
  onSuccess: () => void;
  onCancel: () => void;
}

const IncomingForm: React.FC<IncomingFormProps> = ({ language, departments, users, onSuccess, onCancel }) => {
  const { t } = useTranslation();
  
  const {
    register,
    handleSubmit,
    watch,
    formState: { errors, isSubmitting },
  } = useForm<IncomingFormValues>({
    resolver: zodResolver(incomingSchema) as any,
    mode: 'onBlur',
    defaultValues: {
      sender_entity_type: EntityType.PRIVATE,
      classification: CorrespondenceClassification.GENERAL,
      priority: CorrespondencePriority.NORMAL,
      method: SendingMethod.OFFICIAL_MAIL,
      letter_date: new Date().toISOString().split('T')[0],
      receipt_date: new Date().toISOString().split('T')[0],
      follow_up_required: false,
      response_required: false,
    },
  });

  const followUpRequired = watch('follow_up_required');
  const responseRequired = watch('response_required');

  const onSubmit = async (data: IncomingFormValues) => {
    try {
      await api.post('/correspondence/incoming', data);
      onSuccess();
    } catch (error) {
      logger.error("Failed to save incoming correspondence", error);
      toast.error(t('errorOccurred'));
    }
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        <FormField label={t('correspondence.originalLetterNo')} error={errors.letter_number?.message}>
          <Input {...register('letter_number')} defaultValue="" placeholder={t('correspondence.originalLetterNoPlaceholder')} />
        </FormField>

        <FormField label={t('correspondence.senderEntity')} error={errors.sender_entity?.message} required>
          <Input {...register('sender_entity')} defaultValue="" placeholder={t('correspondence.senderEntityPlaceholder')} />
        </FormField>

        <FormField label={t('correspondence.entityType')} error={errors.sender_entity_type?.message}>
          <Select {...register('sender_entity_type')}>
            {Object.values(EntityType).map(type => (
              <option key={type} value={type}>{t(`correspondence.${type.toLowerCase().replace(/\s+/g, '_')}`)}</option>
            ))}
          </Select>
        </FormField>

        <FormField label={t('correspondence.letterSubject')} error={errors.subject?.message} required className="md:col-span-2 lg:col-span-3">
          <Input {...register('subject')} defaultValue="" placeholder={t('correspondence.letterSubjectPlaceholder')} />
        </FormField>

        <FormField label={t('correspondence.letterDate')} error={errors.letter_date?.message} required>
          <Input type="date" {...register('letter_date')} />
        </FormField>

        <FormField label={t('correspondence.receiptDate')} error={errors.receipt_date?.message} required>
          <Input type="date" {...register('receipt_date')} />
        </FormField>

        <FormField label={t('correspondence.receivedMethod')} error={errors.method?.message}>
          <Select {...register('method')}>
            {Object.values(SendingMethod).map(method => (
              <option key={method} value={method}>{t(`correspondence.${method.toLowerCase().replace(/\s+/g, '_')}`)}</option>
            ))}
          </Select>
        </FormField>

        <FormField label={t('correspondence.classification')} error={errors.classification?.message}>
          <Select {...register('classification')}>
            {Object.values(CorrespondenceClassification).map(cls => (
              <option key={cls} value={cls}>{t(`correspondence.${cls.toLowerCase().replace(/\s+/g, '_')}`)}</option>
            ))}
          </Select>
        </FormField>

        <FormField label={t('correspondence.priority')} error={errors.priority?.message}>
          <Select {...register('priority')}>
            {Object.values(CorrespondencePriority).map(prio => (
              <option key={prio} value={prio}>{t(`correspondence.${prio.toLowerCase().replace(/\s+/g, '_')}`)}</option>
            ))}
          </Select>
        </FormField>

        <FormField label={t('correspondence.receivingDept')} error={errors.receiving_dept_id?.message}>
          <Select {...register('receiving_dept_id')}>
            <option value="">{t('correspondence.selectDepartment')}</option>
            {(Array.isArray(departments) ? departments : []).map(d => (
              <option key={d.id} value={d.id}>{language === 'ar' ? d.name_ar : d.name_en}</option>
            ))}
          </Select>
        </FormField>

        <FormField label={t('correspondence.assignedDept')} error={errors.assigned_dept_id?.message}>
          <Select {...register('assigned_dept_id')}>
            <option value="">{t('correspondence.selectDepartment')}</option>
            {(Array.isArray(departments) ? departments : []).map(d => (
              <option key={d.id} value={d.id}>{language === 'ar' ? d.name_ar : d.name_en}</option>
            ))}
          </Select>
        </FormField>

        <FormField label={t('correspondence.assignedUser')} error={errors.assigned_user_id?.message}>
          <Select {...register('assigned_user_id')}>
            <option value="">{t('correspondence.selectUser')}</option>
            {(Array.isArray(users) ? users : []).map(u => (
              <option key={u.id} value={u.id}>{u.name}</option>
            ))}
          </Select>
        </FormField>

        {/* Tracking Section */}
        <div className="p-6 bg-[var(--color-bg-soft)] dark:bg-slate-900/50 rounded-2xl border border-[var(--color-border-soft)] dark:border-slate-800 lg:col-span-3 space-y-6">
          <div className="flex flex-wrap items-center gap-8">
            <div className="flex items-center gap-3">
              <input 
                type="checkbox"
                id="follow_up_required"
                className="w-5 h-5 text-[var(--color-primary)] rounded border-[var(--color-border-strong)] dark:border-slate-700 focus:ring-[var(--color-primary)] bg-[var(--color-card)] dark:bg-slate-800"
                {...register('follow_up_required')}
              />
              <label htmlFor="follow_up_required" className="text-sm font-bold text-[var(--color-text-main)] dark:text-[var(--color-border-strong)]">
                {t('correspondence.followUpRequired')}
              </label>
            </div>

            {followUpRequired && (
              <div className="flex-1 min-w-[200px]">
                <Input type="date" {...register('follow_up_date')} />
              </div>
            )}
          </div>

          <div className="flex flex-wrap items-center gap-8">
            <div className="flex items-center gap-3">
              <input 
                type="checkbox"
                id="response_required"
                className="w-5 h-5 text-[var(--color-primary)] rounded border-[var(--color-border-strong)] dark:border-slate-700 focus:ring-[var(--color-primary)] bg-[var(--color-card)] dark:bg-slate-800"
                {...register('response_required')}
              />
              <label htmlFor="response_required" className="text-sm font-bold text-[var(--color-text-main)] dark:text-[var(--color-border-strong)]">
                {t('correspondence.responseRequired')}
              </label>
            </div>

            {responseRequired && (
              <div className="flex-1 min-w-[200px]">
                <Input type="date" {...register('response_due_date')} />
              </div>
            )}
          </div>
        </div>

        <FormField label={t('correspondence.notes')} error={errors.notes?.message} className="lg:col-span-3">
          <Textarea rows={3} {...register('notes')} placeholder={t('correspondence.notesPlaceholder')} />
        </FormField>
      </div>

      <div className="flex justify-end gap-6 pt-8 border-t border-[var(--color-border-soft)] dark:border-slate-800">
        <button 
          type="button"
          onClick={onCancel}
          className="px-8 py-3 text-[var(--color-text-muted)] dark:text-[var(--color-text-muted)] font-bold uppercase tracking-widest hover:bg-[var(--color-bg-main)] dark:hover:bg-slate-800 rounded-xl transition-all"
        >
          {t('common.cancel')}
        </button>
        <button 
          type="submit"
          disabled={isSubmitting}
          className="btn-primary disabled:opacity-50 flex items-center justify-center gap-2"
        >
          {isSubmitting ? t('correspondence.saving') : t('correspondence.registerLetter')}
        </button>
      </div>
    </form>
  );
};

export default IncomingForm;

import React, { useState, useEffect } from 'react';
import { 
  Search, 
  Filter, 
  Plus, 
  Eye, 
  Download, 
  MoreVertical,
  Calendar,
  User,
  Building,
  Tag,
  AlertCircle,
  CheckCircle,
  Clock,
  FileText,
  X,
  Mail
} from 'lucide-react';
import { useTranslation } from 'react-i18next';
import api from '../../services/api';
import { motion, AnimatePresence } from 'motion/react';
import Pagination from '../../components/Pagination';
import { useFormat } from '../../services/formatService';
import { useDebounce } from '../../hooks/useDebounce';
import logger from '../../utils/logger';

import IncomingForm from './IncomingForm';

interface IncomingRegisterProps {
  language: 'ar' | 'en';
  onViewDetails: (id: number) => void;
}

const IncomingRegister: React.FC<IncomingRegisterProps> = ({ language, onViewDetails }) => {
  const { t } = useTranslation();
  const { formatNumber, formatDate } = useFormat();
  const [items, setItems] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [showAddModal, setShowAddModal] = useState(false);
  const [pagination, setPagination] = useState({ page: 1, pageSize: 15, total: 0, totalPages: 0 });
  const [filters, setFilters] = useState({
    search: '',
    status: '',
    priority: '',
    dept_id: '',
    start_date: '',
    end_date: ''
  });
  const debouncedSearch = useDebounce(filters.search, 500);
  const [departments, setDepartments] = useState<any[]>([]);
  const [users, setUsers] = useState<any[]>([]);

  useEffect(() => {
    fetchData();
  }, [debouncedSearch, filters.status, filters.priority, filters.dept_id, filters.start_date, filters.end_date, pagination.page, pagination.pageSize]);

  useEffect(() => {
    fetchMetadata();
  }, []);

  const fetchData = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      params.append('page', pagination.page.toString());
      params.append('pageSize', pagination.pageSize.toString());
      if (debouncedSearch) params.append('search', debouncedSearch);
      if (filters.status) params.append('status', filters.status);
      if (filters.priority) params.append('priority', filters.priority);
      if (filters.dept_id) params.append('dept_id', filters.dept_id);
      if (filters.start_date) params.append('start_date', filters.start_date);
      if (filters.end_date) params.append('end_date', filters.end_date);

      const response = await api.get(`/correspondence/incoming?${params.toString()}`);
      if (response.data.data) {
        setItems(response.data.data);
        setPagination(prev => ({
          ...prev,
          total: response.data.pagination?.total ?? response.data.data.length,
          totalPages: response.data.pagination?.totalPages ?? 1
        }));
      } else {
        setItems(response.data);
      }
    } catch (error) {
      logger.error("Failed to fetch incoming correspondence", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchMetadata = async () => {
    try {
      const [deptsRes, usersRes] = await Promise.all([
        api.get('/org-entities'),
        api.get('/users')
      ]);
      setDepartments(deptsRes.data);
      setUsers(usersRes.data);
    } catch (error) {
      logger.error("Failed to fetch metadata", error);
    }
  };

  const handleExport = () => {
    const headers = [
      t('correspondence.seqNumber'),
      t('correspondence.letterNo'),
      t('correspondence.sender'),
      t('correspondence.subject'),
      t('correspondence.date'),
      t('correspondence.status'),
      t('correspondence.priority')
    ];

    const csvData = items.map(item => [
      item.sequence_number,
      item.letter_number || '',
      item.sender_entity,
      item.subject,
      item.letter_date,
      item.status,
      item.priority
    ]);

    const csvContent = [
      headers.join(','),
      ...csvData.map(row => row.map(cell => `"${cell}"`).join(','))
    ].join('\n');

    const blob = new Blob(['\ufeff' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `incoming_correspondence_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Received': return 'bg-[var(--color-primary)]/10 text-[var(--color-primary)]';
      case 'Registered': return 'bg-[var(--color-info)]/10 text-[var(--color-info)]';
      case 'Under Review': return 'bg-[var(--color-warning)]/10 text-[var(--color-warning)]';
      case 'Referred': return 'bg-purple-500/10 text-purple-500';
      case 'Action Taken': return 'bg-teal-500/10 text-teal-500';
      case 'Closed': return 'bg-[var(--color-success)]/10 text-[var(--color-success)]';
      case 'Archived': return 'bg-[var(--color-text-muted)]/10 text-[var(--color-text-muted)]';
      case 'Cancelled': return 'bg-[var(--color-danger)]/10 text-[var(--color-danger)]';
      default: return 'bg-[var(--color-text-muted)]/10 text-[var(--color-text-muted)]';
    }
  };

  const getStatusLabel = (status: string) => {
    if (!status) return '';
    return t(`correspondence.${status.toLowerCase().replace(/\s+/g, '_')}`);
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'Normal': return 'text-[var(--color-text-muted)]';
      case 'Urgent': return 'text-[var(--color-warning)] font-semibold';
      case 'Very Urgent': return 'text-[var(--color-danger)] font-semibold';
      case 'Confidential': return 'text-purple-500 font-semibold';
      case 'Restricted': return 'text-[var(--color-primary)] font-semibold';
      default: return 'text-[var(--color-text-muted)]';
    }
  };

  const getPriorityLabel = (priority: string) => {
    if (!priority) return '';
    return t(`correspondence.${priority.toLowerCase().replace(/\s+/g, '_')}`);
  };

  return (
    <div className="space-y-4">
      {/* Filters Bar */}
      <div className="bg-[var(--color-bg-soft)]/50 p-4 rounded-2xl border border-[var(--color-border-soft)] flex flex-wrap items-center gap-4">
        <div className="relative flex-1 min-w-[250px]">
          <Search className="absolute start-4 top-1/2 -translate-y-1/2 text-[var(--color-text-muted)]" size={18} />
          <input 
            type="text"
            placeholder={t('correspondence.searchIncomingPlaceholder')}
            className="w-full p-2.5 ps-11 bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-xl text-sm font-bold outline-none focus:border-[var(--color-primary)] transition-colors shadow-sm"
            value={filters.search}
            onChange={(e) => setFilters({...filters, search: e.target.value})}
          />
        </div>
        
        <select 
          className="p-2.5 bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-xl text-sm font-bold outline-none focus:border-[var(--color-primary)] transition-colors shadow-sm w-auto"
          value={filters.status}
          onChange={(e) => setFilters({...filters, status: e.target.value})}
        >
          <option value="">{t('correspondence.allStatuses')}</option>
          <option value="Received">{t('correspondence.received')}</option>
          <option value="Registered">{t('correspondence.registered')}</option>
          <option value="Under Review">{t('correspondence.under_review')}</option>
          <option value="Referred">{t('correspondence.referred')}</option>
          <option value="Action Taken">{t('correspondence.action_taken')}</option>
          <option value="Closed">{t('correspondence.closed')}</option>
        </select>

        <select 
          className="p-2.5 bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-xl text-sm font-bold outline-none focus:border-[var(--color-primary)] transition-colors shadow-sm w-auto"
          value={filters.priority}
          onChange={(e) => setFilters({...filters, priority: e.target.value})}
        >
          <option value="">{t('correspondence.allPriorities')}</option>
          <option value="Normal">{t('correspondence.normal')}</option>
          <option value="Urgent">{t('correspondence.urgent')}</option>
          <option value="Very Urgent">{t('correspondence.very_urgent')}</option>
          <option value="Confidential">{t('correspondence.confidential')}</option>
          <option value="Restricted">{t('correspondence.restricted')}</option>
        </select>

        <button 
          onClick={handleExport}
          className="btn-secondary !py-2.5 flex items-center justify-center gap-2 whitespace-nowrap text-sm bg-[var(--color-card)]"
          title={t('correspondence.exportToCSV')}
        >
          <Download size={18} />
          {t('correspondence.export')}
        </button>

        <button 
          onClick={() => setShowAddModal(true)}
          className="btn-primary !py-2.5 flex items-center justify-center gap-2 whitespace-nowrap text-sm"
        >
          <Plus size={18} />
          {t('correspondence.addNew')}
        </button>
      </div>

      {/* Table */}
      <div className="bg-[var(--color-card)] rounded-2xl border border-[var(--color-border-soft)] overflow-hidden shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full text-start border-collapse">
            <thead>
              <tr className="bg-[var(--color-bg-soft)]/50 border-b border-[var(--color-border-soft)]">
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">
                  {t('correspondence.seqNumber')}
                </th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('correspondence.letterNo')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('correspondence.sender')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('correspondence.subject')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('correspondence.date')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('correspondence.status')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('correspondence.priority')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-end">{t('common.actions')}</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[var(--color-border-soft)]/50">
              {loading ? (
                <tr>
                  <td colSpan={8} className="px-6 py-10 text-center text-[var(--color-text-muted)] font-bold text-sm">
                    {t('common.loading')}
                  </td>
                </tr>
              ) : items.length === 0 ? (
                <tr>
                  <td colSpan={8} className="px-6 py-10 text-center text-[var(--color-text-muted)] font-bold text-sm">
                    {t('correspondence.noMatchingResults')}
                  </td>
                </tr>
              ) : (Array.isArray(items) ? items : []).map((item) => (
                <tr key={item.id} className="hover:bg-[var(--color-primary)]/5 transition-colors group">
                  <td className="px-6 py-4 text-xs font-bold text-[var(--color-border-strong)] tracking-widest">{formatNumber(item.sequence_number)}</td>
                  <td className="px-6 py-4 text-sm font-bold text-[var(--color-text-main)]">{formatNumber(item.letter_number) || '-'}</td>
                  <td className="px-6 py-4 text-sm font-bold text-[var(--color-text-main)]">
                    <div className="flex items-center gap-2">
                      <Building size={14} className="text-[var(--color-text-muted)]" />
                      {item.sender_entity}
                    </div>
                  </td>
                  <td className="px-6 py-4 text-sm font-bold text-[var(--color-text-main)] max-w-xs truncate">{item.subject}</td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="flex flex-col">
                      <span className="text-sm font-bold text-[var(--color-text-main)]">{formatDate(item.letter_date)}</span>
                      <span className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('correspondence.recPrefix')}{formatDate(item.receipt_date)}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <span className={`px-2.5 py-1 rounded-lg text-[10px] font-bold uppercase tracking-wider ${getStatusColor(item.status)}`}>
                      {getStatusLabel(item.status)}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <span className={`flex items-center gap-1.5 text-xs ${getPriorityColor(item.priority)}`}>
                      <Tag size={12} />
                      {getPriorityLabel(item.priority)}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center justify-end gap-2 md:opacity-0 md:group-hover:opacity-100 transition-opacity">
                      <button 
                        onClick={() => onViewDetails(item.id)}
                        className="p-2 bg-[var(--color-card)] text-[var(--color-primary)] border border-[var(--color-border-soft)] hover:border-[var(--color-primary)]/30 rounded-xl shadow-sm transition-all"
                        title={t('correspondence.viewDetails')}
                      >
                        <Eye size={16} />
                      </button>
                      <button 
                        className="p-2 bg-[var(--color-card)] text-[var(--color-text-muted)] border border-[var(--color-border-soft)] hover:text-[var(--color-text-muted)] rounded-xl shadow-sm transition-all"
                      >
                        <MoreVertical size={16} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <Pagination 
        currentPage={pagination.page}
        totalPages={pagination.totalPages}
        onPageChange={(page) => setPagination(prev => ({ ...prev, page }))}
        pageSize={pagination.pageSize}
        onPageSizeChange={(pageSize) => setPagination(prev => ({ ...prev, pageSize, page: 1 }))}
        totalItems={pagination.total}
      />

      {/* Add Modal */}
      <AnimatePresence>
        {showAddModal && (
          <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
            <motion.div 
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.95 }}
              className="bg-[var(--color-card)] rounded-3xl border border-[var(--color-border-soft)] shadow-2xl w-full max-w-4xl max-h-[90vh] overflow-hidden flex flex-col"
            >
              <div className="p-6 border-b border-[var(--color-border-soft)] flex items-center justify-between bg-[var(--color-bg-main)]">
                <h2 className="text-xl font-bold text-[var(--color-text-main)] flex items-center gap-2">
                  <Mail className="text-[var(--color-primary)]" />
                  {t('correspondence.registerIncomingTitle')}
                </h2>
                <button 
                  onClick={() => setShowAddModal(false)}
                  className="p-2 text-[var(--color-text-muted)] hover:text-[var(--color-text-main)] rounded-full hover:bg-[var(--color-border-soft)] transition-colors"
                >
                  <X size={20} />
                </button>
              </div>
              
              <div className="p-6 overflow-y-auto flex-1">
                <IncomingForm 
                  language={language} 
                  departments={departments}
                  users={users}
                  onSuccess={() => {
                    setShowAddModal(false);
                    fetchData();
                  }}
                  onCancel={() => setShowAddModal(false)}
                />
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default IncomingRegister;

import React from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { useTranslation } from 'react-i18next';
import { 
  CorrespondenceClassification, 
  SendingMethod 
} from '../../constants';
import api from '../../services/api';
import toast from 'react-hot-toast';
import { Input } from '../../components/ui/Input';
import { Select } from '../../components/ui/Select';
import { FormField } from '../../components/ui/FormField';
import logger from '../../utils/logger';

const outgoingSchema = z.object({
  letter_date: z.string().min(1, 'Field is required'),
  recipient_entity: z.string().min(1, 'Field is required'),
  subject: z.string().min(1, 'Field is required'),
  classification: z.nativeEnum(CorrespondenceClassification),
  sending_method: z.nativeEnum(SendingMethod),
  attachment_file: z.any().optional(),
});

type OutgoingFormValues = z.infer<typeof outgoingSchema>;

interface OutgoingFormProps {
  language: 'ar' | 'en';
  onSuccess: () => void;
  onCancel: () => void;
}

const OutgoingForm: React.FC<OutgoingFormProps> = ({ language, onSuccess, onCancel }) => {
  const { t } = useTranslation();
  
  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting },
  } = useForm<OutgoingFormValues>({
    resolver: zodResolver(outgoingSchema),
    mode: 'onBlur',
    defaultValues: {
      letter_date: new Date().toISOString().split('T')[0],
      classification: CorrespondenceClassification.GENERAL,
      sending_method: SendingMethod.OFFICIAL_MAIL,
    },
  });

  const onSubmit = async (data: OutgoingFormValues) => {
    try {
      const formData = new FormData();
      formData.append('letter_date', data.letter_date);
      formData.append('recipient_entity', data.recipient_entity);
      formData.append('subject', data.subject);
      formData.append('classification', data.classification);
      formData.append('sending_method', data.sending_method);
      
      if (data.attachment_file && data.attachment_file[0]) {
        formData.append('attachment_file', data.attachment_file[0]);
      }
      
      await api.post('/correspondence/outgoing', formData);
      onSuccess();
    } catch (error) {
      logger.error("Failed to save outgoing correspondence", error);
      toast.error(t('errorOccurred'));
    }
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <FormField label={t('correspondence.sequenceNumber')} error={errors.letter_date?.message} className="opacity-60 cursor-not-allowed">
          <Input defaultValue={t('correspondence.autoGenerated')} disabled className="bg-[var(--color-bg-soft)] dark:bg-slate-900 border-dashed" />
        </FormField>

        <FormField label={t('correspondence.letterDate')} error={errors.letter_date?.message} required>
          <Input type="date" {...register('letter_date')} />
        </FormField>

        <FormField label={t('correspondence.recipientEntity')} error={errors.recipient_entity?.message} required className="md:col-span-2">
          <Input {...register('recipient_entity')} defaultValue="" placeholder={t('correspondence.recipientEntityPlaceholder')} />
        </FormField>

        <FormField label={t('correspondence.subject')} error={errors.subject?.message} required className="md:col-span-2">
          <Input {...register('subject')} defaultValue="" placeholder={t('correspondence.letterSubjectPlaceholder')} />
        </FormField>

        <FormField label={t('correspondence.classification')} error={errors.classification?.message}>
          <Select {...register('classification')}>
            {Object.values(CorrespondenceClassification).map(cls => (
              <option key={cls} value={cls}>{t(`correspondence.${cls.toLowerCase().replace(/\s+/g, '_')}`)}</option>
            ))}
          </Select>
        </FormField>

        <FormField label={t('correspondence.sendingMethod')} error={errors.sending_method?.message}>
          <Select {...register('sending_method')}>
            {Object.values(SendingMethod).map(method => (
              <option key={method} value={method}>{t(`correspondence.${method.toLowerCase().replace(/\s+/g, '_')}`)}</option>
            ))}
          </Select>
        </FormField>

        <FormField label={t('correspondence.attachmentPdf')} error={errors.attachment_file?.message as string} className="md:col-span-2">
          <Input type="file" accept="application/pdf" {...register('attachment_file')} />
        </FormField>
      </div>

      <div className="flex justify-end gap-6 pt-8 border-t border-[var(--color-border-soft)] dark:border-slate-800">
        <button 
          type="button"
          onClick={onCancel}
          className="px-8 py-3 text-[var(--color-text-muted)] dark:text-[var(--color-text-muted)] font-bold uppercase tracking-widest hover:bg-[var(--color-bg-main)] dark:hover:bg-slate-800 rounded-xl transition-all"
        >
          {t('common.cancel')}
        </button>
        <button 
          type="submit"
          disabled={isSubmitting}
          className="btn-primary disabled:opacity-50 flex items-center justify-center gap-2"
        >
          {isSubmitting ? t('correspondence.saving') : t('correspondence.registerLetter')}
        </button>
      </div>
    </form>
  );
};

export default OutgoingForm;

import React, { useState, useEffect } from 'react';
import { 
  Search, 
  Plus, 
  Eye, 
  Download, 
  MoreVertical,
  Calendar,
  Building,
  Tag,
  FileText,
  X,
  Send,
  Trash2,
  Edit2
} from 'lucide-react';
import { useTranslation } from 'react-i18next';
import api from '../../services/api';
import toast from 'react-hot-toast';
import { motion, AnimatePresence } from 'motion/react';
import { useFormat } from '../../services/formatService';
import { useDebounce } from '../../hooks/useDebounce';
import Modal from '../../components/Modal';
import PdfViewer from '../../components/PdfViewer';
import Pagination from '../../components/Pagination';
import { UserRole } from '../../constants';
import logger from '../../utils/logger';

import OutgoingForm from './OutgoingForm';

interface OutgoingRegisterProps {
  language: 'ar' | 'en';
  userRole?: string;
  onViewDetails: (type: 'Outgoing', id: number) => void;
}

const OutgoingRegister: React.FC<OutgoingRegisterProps> = ({ language, userRole, onViewDetails }) => {
  const { t } = useTranslation();
  const [items, setItems] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [showAddModal, setShowAddModal] = useState(false);
  const [search, setSearch] = useState('');
  const debouncedSearch = useDebounce(search, 500);
  const [pagination, setPagination] = useState({ page: 1, pageSize: 15, total: 0, totalPages: 0 });
  const { formatDate, formatNumber } = useFormat();
  
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<number | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);

  useEffect(() => {
    fetchData();
  }, [pagination.page, pagination.pageSize, debouncedSearch]);

  const fetchData = async () => {
    try {
      setLoading(true);
      const response = await api.get('/correspondence/outgoing', {
        params: {
          page: pagination.page,
          pageSize: pagination.pageSize,
          search: debouncedSearch || undefined
        }
      });
      if (response.data.data) {
        setItems(response.data.data);
        setPagination(prev => ({
          ...prev,
          total: response.data.pagination?.total ?? response.data.data.length,
          totalPages: response.data.pagination?.totalPages ?? 1
        }));
      } else {
        setItems(response.data);
      }
    } catch (error) {
      logger.error("Failed to fetch outgoing correspondence", error);
      toast.error(t('errorOccurred'));
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: number) => {
    setItemToDelete(id);
    setIsDeleteModalOpen(true);
  };

  const confirmDelete = async () => {
    if (itemToDelete === null) return;
    try {
      await api.delete(`/correspondence/outgoing/${itemToDelete}`);
      fetchData();
      setIsDeleteModalOpen(false);
      setItemToDelete(null);
    } catch (error) {
      logger.error('Error deleting letter:', error);
      toast.error(t('errorOccurred'));
    }
  };

  const handlePreview = (fileUrl: string) => {
    setPreviewUrl(fileUrl);
  };

  const filteredItems = items;

  return (
    <div className="space-y-4">
      <Modal
        isOpen={!!previewUrl}
        onClose={() => setPreviewUrl(null)}
        title={t('correspondence.previewFile')}
        size="full"
      >
        <div className="w-full h-full bg-[var(--color-bg-main)] rounded-xl overflow-hidden">
          {previewUrl && (
            previewUrl.startsWith('data:image') || /\.(jpg|jpeg|png|gif|webp)$/i.test(previewUrl) ? (
              <img 
                src={previewUrl} 
                alt="Attachment" 
                className="max-w-full max-h-full object-contain mx-auto" 
                referrerPolicy="no-referrer"
              />
            ) : previewUrl.startsWith('data:application/pdf') || /\.pdf$/i.test(previewUrl) || (previewUrl && !previewUrl.startsWith('data:') && !previewUrl.startsWith('http') && !previewUrl.startsWith('/') && previewUrl.length > 100) ? (
              <div className="w-full h-full">
                <PdfViewer url={previewUrl} />
              </div>
            ) : (
              <div className="text-center p-10">
                <FileText size={48} className="mx-auto text-[var(--color-text-muted)] mb-4" />
                <p className="text-[var(--color-text-main)] font-bold">
                  {t('correspondence.previewNotAvailable')}
                </p>
                <a 
                  href={previewUrl} 
                  download="attachment"
                  className="mt-4 btn-primary inline-block"
                >
                  {t('correspondence.downloadFile')}
                </a>
              </div>
            )
          )}
        </div>
      </Modal>

      {isDeleteModalOpen && (
        <div className="fixed inset-0 z-[9999] bg-black/50 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-[var(--color-bg-main)] p-8 rounded-2xl shadow-2xl w-full max-w-md border border-[var(--color-border-soft)]">
            <h3 className="text-xl font-bold text-[var(--color-text-main)] mb-4">
              {t('correspondence.confirmDelete')}
            </h3>
            <p className="text-[var(--color-text-muted)] mb-8">
              {t('correspondence.deleteLetterConfirm')}
            </p>
            <div className="flex justify-end gap-3">
              <button 
                onClick={() => {
                  setIsDeleteModalOpen(false);
                  setItemToDelete(null);
                }}
                className="btn-secondary"
              >
                {t('common.cancel')}
              </button>
              <button 
                onClick={confirmDelete}
                className="px-6 py-2.5 bg-[var(--color-danger)] text-white rounded-xl hover:bg-red-700 transition-colors shadow-md shadow-red-900/20"
              >
                {t('common.delete')}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Filters Bar */}
      <div className="bg-[var(--color-bg-soft)]/50 p-4 rounded-2xl border border-[var(--color-border-soft)] flex flex-wrap items-center gap-4">
        <div className="relative flex-1 min-w-[250px]">
          <Search className="absolute start-4 top-1/2 -translate-y-1/2 text-[var(--color-text-muted)]" size={18} />
          <input 
            type="text"
            placeholder={t('correspondence.searchOutgoingPlaceholder')}
            className="w-full p-2.5 ps-11 bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-xl text-sm font-bold outline-none focus:border-[var(--color-primary)] transition-colors shadow-sm"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>

        {userRole !== UserRole.VIEWER && (
          <button 
            onClick={() => setShowAddModal(true)}
            className="btn-primary !py-2.5 flex items-center justify-center gap-2 whitespace-nowrap text-sm"
          >
            <Plus size={18} />
            {t('correspondence.addNew')}
          </button>
        )}
      </div>

      {/* Table */}
      <div className="bg-[var(--color-card)] rounded-2xl border border-[var(--color-border-soft)] overflow-hidden shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full text-start border-collapse">
            <thead>
              <tr className="bg-[var(--color-bg-soft)]/50 border-b border-[var(--color-border-soft)]">
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">
                  {t('correspondence.seqNumber')}
                </th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('correspondence.date')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('correspondence.recipient')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('correspondence.subject')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('correspondence.classification')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('correspondence.sendingMethod')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-center">{t('correspondence.attachment')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-center">{t('common.actions')}</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[var(--color-border-soft)]/50">
              {loading ? (
                <tr>
                  <td colSpan={8} className="px-6 py-10 text-center text-[var(--color-text-muted)] font-bold text-sm">
                    {t('common.loading')}
                  </td>
                </tr>
              ) : filteredItems.length === 0 ? (
                <tr>
                  <td colSpan={8} className="px-6 py-10 text-center text-[var(--color-text-muted)] font-bold text-sm">
                    {t('correspondence.noMatchingResults')}
                  </td>
                </tr>
              ) : (Array.isArray(filteredItems) ? filteredItems : []).map((item) => (
                <tr key={item.id} className="hover:bg-[var(--color-primary)]/5 transition-colors group cursor-pointer" onClick={() => onViewDetails('Outgoing', item.id)}>
                  <td className="px-6 py-4 text-xs font-bold text-[var(--color-border-strong)] tracking-widest">{formatNumber(item.sequence_number)}</td>
                  <td className="px-6 py-4 text-sm font-bold text-[var(--color-text-main)]">{formatDate(item.letter_date)}</td>
                  <td className="px-6 py-4 text-sm font-bold text-[var(--color-text-main)]">
                    <div className="flex items-center gap-2">
                      <Building size={14} className="text-[var(--color-text-muted)]" />
                      {item.recipient_entity}
                    </div>
                  </td>
                  <td className="px-6 py-4 text-sm font-bold text-[var(--color-text-main)] max-w-xs truncate">{item.subject}</td>
                  <td className="px-6 py-4">
                    <span className="px-2.5 py-1 bg-[var(--color-bg-main)] rounded-lg text-[10px] font-bold uppercase tracking-wider text-[var(--color-text-muted)] border border-[var(--color-border-soft)]">
                      {t(`correspondence.${(item.classification || '').toLowerCase().replace(/\s+/g, '_')}`) || item.classification}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-sm font-bold text-[var(--color-text-main)]">
                    {t(`correspondence.${(item.sending_method || '').toLowerCase().replace(/\s+/g, '_')}`) || item.sending_method}
                  </td>
                  <td className="px-6 py-4 text-center" onClick={(e) => e.stopPropagation()}>
                    {item.attachment_file && (
                      <button 
                        onClick={() => handlePreview(item.attachment_file!)} 
                        className="p-2 text-[var(--color-primary)] hover:bg-[var(--color-primary)]/10 rounded-xl transition-colors inline-flex"
                        title={t('correspondence.previewAttachment')}
                      >
                        <FileText size={18} />
                      </button>
                    )}
                  </td>
                  <td className="px-6 py-4" onClick={(e) => e.stopPropagation()}>
                    <div className="flex items-center justify-center gap-2 md:opacity-0 md:group-hover:opacity-100 transition-opacity">
                      <button className="p-2 bg-[var(--color-card)] text-[var(--color-text-muted)] border border-[var(--color-border-soft)] hover:text-[var(--color-primary)] rounded-xl shadow-sm transition-all" title={t('common.download')}>
                        <Download size={16} />
                      </button>
                      {userRole === UserRole.ADMIN && (
                        <>
                          <button className="p-2 bg-[var(--color-card)] text-[var(--color-text-muted)] border border-[var(--color-border-soft)] hover:text-amber-500 rounded-xl shadow-sm transition-all" title={t('common.edit')}>
                            <Edit2 size={16} />
                          </button>
                          <button 
                            className="p-2 bg-[var(--color-card)] text-[var(--color-text-muted)] border border-[var(--color-border-soft)] hover:text-red-500 rounded-xl shadow-sm transition-all" 
                            onClick={() => handleDelete(item.id)}
                            title={t('common.delete')}
                          >
                            <Trash2 size={16} />
                          </button>
                        </>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <Pagination 
        currentPage={pagination.page}
        totalPages={pagination.totalPages}
        onPageChange={(page) => setPagination(prev => ({ ...prev, page }))}
        pageSize={pagination.pageSize}
        onPageSizeChange={(pageSize) => setPagination(prev => ({ ...prev, pageSize, page: 1 }))}
        totalItems={pagination.total}
      />

      {/* Add Modal */}
      <AnimatePresence>
        {showAddModal && (
          <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
            <motion.div 
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.95 }}
              className="bg-[var(--color-card)] rounded-3xl border border-[var(--color-border-soft)] shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden flex flex-col"
            >
              <div className="p-6 border-b border-[var(--color-border-soft)] flex items-center justify-between bg-[var(--color-bg-main)]">
                <h2 className="text-xl font-bold text-[var(--color-text-main)] flex items-center gap-2">
                  <Send className="text-[var(--color-primary)]" />
                  {t('correspondence.registerOutgoingTitle')}
                </h2>
                <button 
                  onClick={() => setShowAddModal(false)}
                  className="p-2 text-[var(--color-text-muted)] hover:text-[var(--color-text-main)] rounded-full hover:bg-[var(--color-border-soft)] transition-colors"
                >
                  <X size={20} />
                </button>
              </div>
              
              <div className="p-6 overflow-y-auto flex-1">
                <OutgoingForm 
                  language={language} 
                  onSuccess={() => {
                    setShowAddModal(false);
                    fetchData();
                  }}
                  onCancel={() => setShowAddModal(false)}
                />
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default OutgoingRegister;

import React from 'react';
import { History, Briefcase, FileSearch, ShieldAlert } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useFormat } from '../../services/formatService';
import { useScrollReveal } from '../../hooks/useScrollReveal';

interface DashboardActivityFeedProps {
  t: any;
  activity: any[];
}

const DashboardActivityFeed: React.FC<DashboardActivityFeedProps> = React.memo(({ t, activity }) => {
  const navigate = useNavigate();
  const { formatDateTime, translateName, translateAction, translateModule } = useFormat();
  const { ref, isVisible } = useScrollReveal<HTMLDivElement>();

  return (
    <div ref={ref} className={`lg:col-span-2 glass-card p-8 transition-all duration-500 ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>
      <div className="flex items-center justify-between mb-8">
        <h3 className="text-xl font-bold text-[var(--color-text-main)] flex items-center gap-3">
          <History className="text-[var(--color-primary)]" />
          {t('dashboard.recentActivity')}
        </h3>
        <button 
          onClick={() => navigate('/trail')}
          className="text-xs font-bold text-[var(--color-primary)] uppercase tracking-widest hover:underline"
        >
          {t('dashboard.viewAll')}
        </button>
      </div>
      <div className="space-y-4">
        {(Array.isArray(activity) ? activity : []).map((item, idx) => (
          <div key={idx} className="flex items-start gap-4 p-4 rounded-2xl bg-[var(--color-bg-main)] border border-[var(--color-border-soft)] hover:border-[var(--color-primary)]/30 transition-all">
            <div className={`w-12 h-12 rounded-[1rem] flex items-center justify-center shrink-0 shadow-sm ${
              item.module === 'Audit' ? 'bg-[var(--color-info)]/10 text-[var(--color-info)]' : 
              item.module === 'Finding' ? 'bg-[var(--color-warning)]/10 text-[var(--color-warning)]' : 'bg-[var(--color-danger)]/10 text-[var(--color-danger)]'
            }`}>
              {item.module === 'Audit' ? <Briefcase size={22} /> : 
               item.module === 'Finding' ? <FileSearch size={22} /> : <ShieldAlert size={22} />}
            </div>
            <div className="flex-1 min-w-0">
              <div className="flex items-center justify-between mb-1">
