import React, { useState, useMemo } from 'react';
import { 
  Activity, AlertCircle, CheckCircle2, Clock, FileText, ShieldAlert, 
  Inbox, Send, Briefcase, AlertTriangle, TrendingUp, FileSearch, History,
  Plus, Scale
} from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { usePreferences } from '../../context/PreferencesContext';
import { useDashboardStats } from '../../hooks/useDashboardStats';
import { Language } from '../../constants';

// Sub-components
import DashboardHeader from './DashboardHeader';
import DashboardKpiGrid from './DashboardKpiGrid';
import DashboardAuditProgress from './DashboardAuditProgress';
import DashboardRiskOverview from './DashboardRiskOverview';
import DashboardActivityFeed from './DashboardActivityFeed';
import DashboardQuickActions from './DashboardQuickActions';

const Dashboard: React.FC = () => {
  const { language } = usePreferences();
  const { t } = useTranslation();
  const isRtl = language === Language.AR;
  
  const [activeFilter, setActiveFilter] = useState('all');
  const { stats, loading, error } = useDashboardStats(activeFilter);

  const COLORS = useMemo(() => ['#10b981', '#f59e0b', '#ef4444', '#6366f1', '#8b5cf6'], []);

  const kpiCards = useMemo(() => {
    if (!stats) return [];
    
    // Real calculation for completion trend instead of hardcoded '85%'
    const completionRate = stats.audits.total > 0 
      ? Math.round((stats.audits.completed / stats.audits.total) * 100) 
      : 0;

    return [
      { id: 'audits', title: t('dashboard.totalAudits'), value: stats.audits.total, icon: Briefcase, color: 'text-[var(--color-primary)]', bg: 'bg-[var(--color-primary)]/10', link: '/plan' },
      { id: 'completed', title: t('dashboard.completedAudits'), value: stats.audits.completed, icon: CheckCircle2, color: 'text-[var(--color-success)]', bg: 'bg-[var(--color-success)]/10', trend: `${completionRate}%`, trendUp: true, link: '/plan' },
      { id: 'findings', title: t('dashboard.openFindings'), value: stats.findings.summary.open, icon: FileText, color: 'text-[var(--color-warning)]', bg: 'bg-[var(--color-warning)]/10', link: '/findings' },
      { id: 'high-risk', title: t('dashboard.highRiskFindings'), value: stats.findings.summary.high_risk_open, icon: AlertCircle, color: 'text-[var(--color-danger)]', bg: 'bg-[var(--color-danger)]/10', trend: t('dashboard.critical'), trendUp: false, link: '/findings' },
      { id: 'recommendations', title: t('dashboard.openRecommendations'), value: stats.recommendations.open, icon: TrendingUp, color: 'text-[var(--color-info)]', bg: 'bg-[var(--color-info)]/10', trend: t('dashboard.active'), trendUp: true, link: '/recommendations' },
      { id: 'overdue', title: t('dashboard.overdueRecommendations'), value: stats.recommendations.overdue, icon: Clock, color: 'text-[var(--color-danger)]', bg: 'bg-[var(--color-danger)]/10', trend: t('dashboard.urgent'), trendUp: false, link: '/recommendations' },
      { id: 'risks', title: t('dashboard.totalRisks'), value: stats.risks.summary.total, icon: ShieldAlert, color: 'text-[var(--color-text-main)]', bg: 'bg-[var(--color-bg-main)]', trend: t('dashboard.monitored'), trendUp: true, link: '/risks' },
      { id: 'high-risks', title: t('dashboard.highRisks'), value: stats.risks.summary.high, icon: AlertTriangle, color: 'text-[var(--color-danger)]', bg: 'bg-[var(--color-danger)]/10', trend: t('dashboard.highPriority'), trendUp: false, link: '/risks' },
      { id: 'incoming', title: t('dashboard.incomingCorrespondence'), value: stats.correspondence.incoming_total, icon: Inbox, color: 'text-[var(--color-success)]', bg: 'bg-[var(--color-success)]/10', trend: t('dashboard.official'), trendUp: true, link: '/cms' },
      { id: 'outgoing', title: t('dashboard.outgoingCorrespondence'), value: stats.correspondence.outgoing_total, icon: Send, color: 'text-[var(--color-primary)]', bg: 'bg-[var(--color-primary)]/10', trend: t('dashboard.official'), trendUp: true, link: '/cms' },
      { id: 'pending-resp', title: t('dashboard.pendingResponses'), value: stats.correspondence.pending_responses, icon: Clock, color: 'text-[var(--color-warning)]', bg: 'bg-[var(--color-warning)]/10', trend: t('dashboard.actionRequired'), trendUp: false, link: '/cms' },
      { id: 'compliance', title: t('dashboard.activeInstructions'), value: stats.compliance.total, icon: Scale, color: 'text-[var(--color-primary)]', bg: 'bg-[var(--color-primary)]/10', trend: t('dashboard.regulatory'), trendUp: true, link: '/regulatory' },
    ];
  }, [stats, t]);

  const quickActions = useMemo(() => [
    { label: t('dashboard.addAuditEngagement'), icon: Plus, link: 'plan', color: 'bg-[var(--color-primary)]' },
    { label: t('dashboard.addAuditFinding'), icon: FileSearch, link: 'findings', color: 'bg-[var(--color-warning)]' },
    { label: t('dashboard.addRisk'), icon: ShieldAlert, link: 'risks', color: 'bg-[var(--color-danger)]' },
    { label: t('dashboard.addIncomingLetter'), icon: Inbox, link: 'cms', color: 'bg-[var(--color-success)]' },
  ], [t]);

  const auditProgressData = useMemo(() => {
    if (!stats?.audits?.progress_by_type) {
      return [
        { name: t('dashboard.operationalAudit'), planned: 0, completed: 0 },
        { name: t('dashboard.financialAudit'), planned: 0, completed: 0 },
        { name: t('dashboard.complianceAudit'), planned: 0, completed: 0 },
        { name: t('dashboard.itAudit'), planned: 0, completed: 0 },
        { name: t('dashboard.amlAudit'), planned: 0, completed: 0 },
      ];
    }
    
    const typeMapping: Record<string, string> = {
      'Operational': t('dashboard.operationalAudit'),
      'Financial': t('dashboard.financialAudit'),
      'Compliance': t('dashboard.complianceAudit'),
      'IT': t('dashboard.itAudit'),
      'AML': t('dashboard.amlAudit')
    };

    // Initialize with zeros for known categories to ensure they always show up
    const trackedData: Record<string, {name: string, planned: number, completed: number}> = {
      'Operational': { name: typeMapping['Operational'], planned: 0, completed: 0 },
      'Financial': { name: typeMapping['Financial'], planned: 0, completed: 0 },
      'Compliance': { name: typeMapping['Compliance'], planned: 0, completed: 0 },
      'IT': { name: typeMapping['IT'], planned: 0, completed: 0 },
      'AML': { name: typeMapping['AML'], planned: 0, completed: 0 }
    };

    stats.audits.progress_by_type.forEach((item: any) => {
      const dbType = item.type || 'Other';
      if (trackedData[dbType]) {
        trackedData[dbType].planned += Number(item.planned || 0);
        trackedData[dbType].completed += Number(item.completed || 0);
      } else {
        trackedData[dbType] = {
          name: dbType,
          planned: Number(item.planned || 0),
          completed: Number(item.completed || 0)
        };
      }
    });

    return Object.values(trackedData);
  }, [stats, t]);

  if (loading || !stats) {
    return (
      <div className="flex items-center justify-center h-screen bg-[var(--color-bg-main)]">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-[var(--color-primary)] border-t-transparent rounded-full animate-spin"></div>
          <p className="text-[var(--color-text-muted)] font-bold uppercase tracking-widest text-xs">{t('common.loading')}</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center h-screen bg-[var(--color-bg-main)]">
        <div className="glass-card p-8 text-center max-w-md">
          <AlertCircle size={48} className="text-[var(--color-danger)] mx-auto mb-4" />
          <h2 className="text-xl font-bold mb-2">{t('common.error')}</h2>
          <p className="text-[var(--color-text-muted)] mb-6">{error}</p>
          <button 
            onClick={() => window.location.reload()}
            className="btn-primary w-full"
          >
            {t('dashboard.retry')}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-8 max-w-[1600px] mx-auto min-h-screen pb-12">
      <DashboardHeader 
        language={language} 
        activeFilter={activeFilter} 
        setActiveFilter={setActiveFilter} 
      />

      <DashboardKpiGrid cards={kpiCards} />

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <DashboardAuditProgress 
          t={t} 
          isRtl={isRtl} 
          data={auditProgressData} 
          totalPlanned={stats.audits.total}
          totalCompleted={stats.audits.completed}
        />
        <DashboardRiskOverview t={t} stats={stats} colors={COLORS} />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <DashboardActivityFeed t={t} activity={stats.activity} />
        <DashboardQuickActions t={t} quickActions={quickActions} stats={stats} />
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Plus, Trash2, Edit2, Building, Briefcase } from 'lucide-react';
import { motion, AnimatePresence } from 'motion/react';
import api from '../services/api';
import { extractErrorMessage } from '../services/errorService';
import toast from 'react-hot-toast';
import { useDepartments } from '../hooks/useDepartments';
import JobTitles from './JobTitles';
import logger from '../utils/logger';

const DepartmentManagement: React.FC = () => {
  const { t } = useTranslation();
  const { departments, refresh } = useDepartments();
  const [activeTab, setActiveTab ] = useState<'departments' | 'jobTitles'>('departments');
  const [newDept, setNewDept] = useState('');
  const [editingDept, setEditingDept] = useState<any>(null);

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const addDept = async () => {
    if (!newDept.trim()) return;
    setLoading(true);
    setError(null);
    try {
      await api.post('/departments', { name: newDept.trim() });
      setNewDept('');
      toast.success(t('createSuccess'));
      refresh();
    } catch (error: any) {
      logger.error("Error adding department:", error);
      const msg = extractErrorMessage(error, t('failedToAddDepartment'));
      setError(msg);
      toast.error(msg);
    } finally {
      setLoading(false);
    }
  };

  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [deptToDelete, setDeptToDelete] = useState<string | number | null>(null);

  const handleDeleteClick = (id: string | number) => {
    setDeptToDelete(id);
    setShowDeleteConfirm(true);
  };

  const confirmDelete = async () => {
    if (!deptToDelete) return;
    setError(null);
    try {
      await api.delete(`/departments/${deptToDelete}`);
      toast.success(t('deleteSuccess'));
      refresh();
      setShowDeleteConfirm(false);
      setDeptToDelete(null);
    } catch (error: any) {
      logger.error("Error deleting department:", error);
      const msg = extractErrorMessage(error, t('failedToDeleteDepartment'));
      setError(msg);
      toast.error(msg);
    }
  };

  const editDept = async (id: string | number, name: string) => {
    setError(null);
    try {
      await api.put(`/departments/${id}`, { name });
      toast.success(t('updateSuccess'));
      setEditingDept(null);
      refresh();
    } catch (error: any) {
      logger.error("Error updating department:", error);
      const msg = extractErrorMessage(error, t('failedToUpdateDepartment'));
      setError(msg);
      toast.error(msg);
    }
  };

  const [searchTerm, setSearchTerm] = useState('');

  const filteredDepartments = departments.filter(dept => 
    (dept.name?.toLowerCase() || '').includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-10">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div className="flex items-center gap-6">
          <div className="w-12 h-12 sm:w-16 sm:h-16 bg-[var(--color-primary)] rounded-2xl flex items-center justify-center text-white shadow-lg shadow-[var(--color-primary)]/20">
            <Building size={32} />
          </div>
          <div>
            <h2 className="text-2xl sm:text-4xl font-bold text-[var(--color-text-main)] tracking-tight">{t('modules.OrgStructure')}</h2>
            <p className="text-sm text-[var(--color-text-muted)] font-bold mt-2">{t('manageSystemDepartments')}</p>
          </div>
        </div>
      </div>

      {/* Tabs Header */}
      <div className="flex gap-2 p-1 bg-[var(--color-bg-main)] rounded-2xl w-fit">
        <button 
          onClick={() => setActiveTab('departments')}
          className={`flex items-center gap-2 px-6 py-3 rounded-xl text-sm font-bold transition-all cursor-pointer ${
            activeTab === 'departments' 
              ? 'bg-[var(--color-card)] text-[var(--color-primary)] shadow-sm' 
              : 'text-[var(--color-text-muted)] hover:text-[var(--color-text-main)]'
          }`}
        >
          <Building size={18} />
          {t('common.departments')}
        </button>
        <button 
          onClick={() => setActiveTab('jobTitles')}
          className={`flex items-center gap-2 px-6 py-3 rounded-xl text-sm font-bold transition-all cursor-pointer ${
            activeTab === 'jobTitles' 
              ? 'bg-[var(--color-card)] text-[var(--color-primary)] shadow-sm' 
              : 'text-[var(--color-text-muted)] hover:text-[var(--color-text-main)]'
          }`}
        >
          <Briefcase size={18} />
          {t('common.jobTitles')}
        </button>
      </div>

      <AnimatePresence mode="wait">
        {activeTab === 'departments' ? (
          <motion.div 
            key="depts"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            className="glass-card p-10"
          >
            {error && (
              <div className="mb-6 p-4 bg-rose-50 text-rose-600 rounded-xl border border-rose-100 font-bold text-sm">
                {error}
              </div>
            )}
            
            <div className="mb-8 p-6 bg-[var(--color-bg-soft)] rounded-2xl border border-[var(--color-border-soft)]">
              <h3 className="text-lg font-bold text-[var(--color-text-main)] mb-4">{t('addNew')}</h3>
              <div className="flex gap-4">
                <input 
                  className="input-field" 
                  placeholder={t('newDepartmentName')} 
                  value={newDept} 
                  onChange={e => setNewDept(e.target.value)} 
                  onKeyDown={e => e.key === 'Enter' && addDept()}
                />
                <button 
                  onClick={addDept} 
                  disabled={loading}
                  className="btn-primary flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed whitespace-nowrap"
                >
                  <Plus size={20} />
                  {loading ? "..." : t('common.add')}
                </button>
              </div>
            </div>

            <div className="mb-6">
              <input 
                className="input-field" 
                placeholder={t('common.search')} 
                value={searchTerm} 
                onChange={e => setSearchTerm(e.target.value)} 
              />
            </div>

            <div className="space-y-4">
              {filteredDepartments.length === 0 ? (
                <div className="text-center py-8 text-[var(--color-text-muted)]">{t('noDepartmentsFound')}</div>
              ) : (
                (Array.isArray(filteredDepartments) ? filteredDepartments : []).map(dept => (
                  <div key={dept.id} className="flex items-center justify-between p-4 bg-[var(--color-card)] rounded-2xl border border-[var(--color-border-soft)] shadow-sm hover:shadow-md transition-shadow">
                    {editingDept?.id === dept.id ? (
                      <input className="input-field" value={editingDept.name || ''} onChange={e => setEditingDept({...editingDept, name: e.target.value})} />
                    ) : (
                      <span className="font-bold text-[var(--color-text-main)]">{dept.name}</span>
                    )}
                    <div className="flex gap-2">
                      {editingDept?.id === dept.id ? (
                        <button onClick={() => editDept(dept.id, editingDept.name)} className="btn-primary text-xs">{t('common.save')}</button>
                      ) : (
                        <button onClick={() => setEditingDept(dept)} className="p-2 text-[var(--color-text-muted)] hover:text-[var(--color-primary)]"><Edit2 size={18} /></button>
                      )}
                      <button onClick={() => handleDeleteClick(dept.id)} className="p-2 text-[var(--color-text-muted)] hover:text-rose-500"><Trash2 size={18} /></button>
                    </div>
                  </div>
                ))
              )}
            </div>
          </motion.div>
        ) : (
          <motion.div
            key="jobs"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
          >
            <JobTitles />
          </motion.div>
        )}
      </AnimatePresence>

      {/* Delete Confirmation Modal */}
      {showDeleteConfirm && (
        <div className="fixed inset-0 z-[9999] bg-black/50 flex items-center justify-center">
          <motion.div 
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="bg-[var(--color-card)] rounded-2xl p-6 w-full max-w-md shadow-2xl"
          >
            <h3 className="text-xl font-bold text-[var(--color-text-main)] mb-2">{t('deleteConfirm')}</h3>
            <p className="text-[var(--color-text-muted)] mb-6">{t('deleteMessage')}</p>
            <div className="flex justify-end gap-3">
              <button 
                onClick={() => setShowDeleteConfirm(false)}
                className="px-4 py-2 text-[var(--color-text-muted)] font-medium hover:bg-[var(--color-bg-main)] rounded-lg transition-colors"
              >
                {t('common.cancel')}
              </button>
              <button 
                onClick={confirmDelete}
                className="px-4 py-2 bg-rose-500 text-white font-medium rounded-lg hover:bg-rose-600 transition-colors shadow-lg shadow-rose-500/20"
              >
                {t('common.delete')}
              </button>
            </div>
          </motion.div>
        </div>
      )}
    </div>
  );
};

export default DepartmentManagement;

import React, { useState } from 'react';
import { ShieldAlert, Lock, AlertCircle, EyeOff, Clock, XCircle, CheckCircle, X, Plus, Save, FileText } from 'lucide-react';
import { motion, AnimatePresence } from 'motion/react';
import { useTranslation } from 'react-i18next';
import Modal from '../../../components/Modal';
import { AccessRequest, AccessStatus } from '../types';

interface AccessGateProps {
  isManager: boolean;
  accessStatus: AccessStatus;
  myRequest: AccessRequest | null;
  requests: AccessRequest[];
  isRequestModalOpen: boolean;
  setIsRequestModalOpen: (open: boolean) => void;
  requestReason: string;
  setRequestReason: (reason: string) => void;
  requestError: string | null;
  submitAccessRequest: (e: React.FormEvent) => Promise<boolean>;
  approveRequest: (id: string, duration: string) => Promise<boolean>;
  rejectRequest: (id: string, reason: string) => Promise<boolean>;
  policyContent: string;
  setPolicyContent: (content: string) => void;
  savePolicy: (content: string) => Promise<boolean>;
  fetchPolicy: () => Promise<void>;
}

export const AccessGate: React.FC<AccessGateProps> = ({
  isManager,
  accessStatus,
  myRequest,
  requests,
  isRequestModalOpen,
  setIsRequestModalOpen,
  requestReason,
  setRequestReason,
  requestError,
  submitAccessRequest,
  approveRequest,
  rejectRequest,
  policyContent,
  setPolicyContent,
  savePolicy,
  fetchPolicy
}) => {
  const { t, i18n } = useTranslation();
  const [isPolicyOpen, setIsPolicyOpen] = useState(false);
  const [isEditingPolicy, setIsEditingPolicy] = useState(false);
  const [isRejectModalOpen, setIsRejectModalOpen] = useState(false);
  const [isApproveModalOpen, setIsApproveModalOpen] = useState(false);
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);
  const [rejectionReason, setRejectionReason] = useState('');
  const [selectedApprovalDuration, setSelectedApprovalDuration] = useState('1');
  const [requestToApprove, setRequestToApprove] = useState<AccessRequest | null>(null);

  const handleApproveClick = (req: AccessRequest) => {
    setRequestToApprove(req);
    setSelectedApprovalDuration('1');
    setIsApproveModalOpen(true);
  };

  const handleRejectClick = (reqId: string) => {
    setSelectedRequestId(reqId);
    setRejectionReason('');
    setIsRejectModalOpen(true);
  };

  const handlePolicySave = async () => {
    const success = await savePolicy(policyContent);
    if (success) setIsEditingPolicy(false);
  };

  const hasAccess = isManager || accessStatus === 'Approved';

  if (!hasAccess) {
    return (
      <motion.div 
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        className="space-y-10"
      >
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-6">
            <div className="w-16 h-16 bg-[var(--color-danger)] rounded-2xl flex items-center justify-center text-white shadow-lg shadow-[var(--color-danger)]/20">
              <ShieldAlert size={32} />
            </div>
            <div>
              <h2 className="text-2xl sm:text-4xl font-bold text-[var(--color-text-main)] tracking-tight">{t('integrity.fraud')}</h2>
              <p className="text-sm text-[var(--color-danger)] font-semibold uppercase tracking-[0.2em] mt-2 flex items-center gap-2">
                <Lock size={14} />
                {t('integrity.confidentialAccess')}
              </p>
            </div>
          </div>
        </div>

        <div className="glass-card p-20 border-rose-100 bg-rose-50/10 relative overflow-hidden group">
          <div className="absolute top-0 end-0 p-10 opacity-5 group-hover:opacity-10 transition-opacity">
            <EyeOff size={200} className="text-rose-900" />
          </div>
          
          <div className="relative z-10 text-center max-w-2xl mx-auto">
            <div className="w-24 h-24 bg-rose-100 rounded-2xl flex items-center justify-center mx-auto mb-10 text-rose-600 shadow-xl">
              <AlertCircle size={48} />
            </div>
            <h3 className="text-3xl font-bold text-[var(--color-text-main)] mb-6 tracking-tight">{t('integrity.accessRestricted')}</h3>
            <p className="text-[var(--color-text-muted)] font-medium leading-relaxed mb-10">
              {t('integrity.accessRestrictedDesc')}
            </p>
            
            {accessStatus === 'Pending' ? (
              <div className="bg-amber-50 border border-amber-200 rounded-xl p-6 mb-8 max-w-md mx-auto">
                <div className="flex items-center gap-3 text-amber-600 font-bold mb-2 justify-center">
                  <Clock size={20} />
                  <span>{t('integrity.accessRequestPending')}</span>
                </div>
                <p className="text-sm text-[var(--color-text-muted)]">
                  {t('integrity.requestSentToManager')}
                </p>
              </div>
            ) : accessStatus === 'Rejected' ? (
              <div className="bg-rose-50 border border-rose-200 rounded-xl p-6 mb-8 max-w-md mx-auto">
                <div className="flex items-center gap-3 text-rose-600 font-bold mb-2 justify-center">
                  <XCircle size={20} />
                  <span>{t('integrity.accessDenied')}</span>
                </div>
                <p className="text-sm text-[var(--color-text-muted)] mb-4">
                  {t('integrity.reason')}: {myRequest?.rejection_reason}
                </p>
                <button 
                  onClick={() => setIsRequestModalOpen(true)}
                  className="text-xs font-bold text-rose-600 hover:text-rose-700 underline"
                >
                  {t('integrity.submitNewRequest')}
                </button>
              </div>
            ) : (
              <div className="flex flex-col sm:flex-row items-center justify-center gap-6">
                <button 
                  onClick={() => setIsRequestModalOpen(true)}
                  className="px-10 py-4 bg-rose-600 text-white font-bold rounded-xl shadow-2xl shadow-rose-200 hover:bg-rose-700 transition-all uppercase tracking-widest text-xs"
                >
                  {t('integrity.requestAccess')}
                </button>
                <button 
                  onClick={() => setIsPolicyOpen(true)}
                  className="px-10 py-4 bg-[var(--color-card)] text-[var(--color-text-muted)] font-bold rounded-xl border border-[var(--color-border-soft)] hover:bg-[var(--color-bg-soft)] transition-all uppercase tracking-widest text-xs"
                >
                  {t('integrity.viewPolicy')}
                </button>
              </div>
            )}
          </div>
        </div>

        {/* Request Access Modal */}
        <Modal
          isOpen={isRequestModalOpen}
          onClose={() => setIsRequestModalOpen(false)}
          title={t('integrity.requestAccessTitle')}
        >
          <form onSubmit={(e) => { e.preventDefault(); submitAccessRequest(e); }} className="space-y-6">
            <div className="bg-[var(--color-primary-light)] p-4 rounded-lg flex items-start gap-3">
              <AlertCircle className="text-[var(--color-primary)] shrink-0 mt-0.5" size={20} />
              <p className="text-sm text-[var(--color-primary)]">
                {t('integrity.accessMonitoredDesc')}
              </p>
            </div>
            {requestError && <div className="text-rose-500 text-sm font-bold">{requestError}</div>}
            <div className="space-y-2">
              <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-wider">{t('integrity.reasonForAccess')}</label>
              <textarea 
                required
                rows={4}
                className="input-field"
                placeholder={t('integrity.explainAccessReason')}
                value={requestReason}
                onChange={e => setRequestReason(e.target.value)}
              />
            </div>
            <div className="flex justify-end gap-4 pt-4 border-t border-[var(--color-border-soft)]">
              <button 
                type="button"
                onClick={() => setIsRequestModalOpen(false)}
                className="btn-secondary"
              >
                {t('common.cancel')}
              </button>
              <button 
                type="submit"
                className="btn-primary bg-rose-600 hover:bg-rose-700"
              >
                {t('common.confirm')}
              </button>
            </div>
          </form>
        </Modal>

        <PolicyModal 
          isOpen={isPolicyOpen}
          onClose={() => setIsPolicyOpen(false)}
          isEditing={isEditingPolicy}
          setIsEditing={setIsEditingPolicy}
          content={policyContent}
          setContent={setPolicyContent}
          onSave={handlePolicySave}
          onCancelEdit={() => { setIsEditingPolicy(false); fetchPolicy(); }}
          isManager={isManager}
        />
      </motion.div>
    );
  }

  return (
    <>
      {/* Access Requests Section for Managers */}
      {isManager && requests.filter(r => r.status === 'Pending').length > 0 && (
        <div className="bg-[var(--color-card)] rounded-2xl shadow-sm border border-[var(--color-border-soft)] p-6 mb-8">
          <h3 className="text-lg font-bold text-[var(--color-text-main)] mb-4 flex items-center gap-2">
            <ShieldAlert className="text-amber-500" size={20} />
            {t('integrity.pendingAccessRequests')}
          </h3>
          <div className="space-y-4">
            {requests.filter(r => r.status === 'Pending').map(req => (
              <div key={req.id} className="flex items-start justify-between p-4 bg-[var(--color-bg-soft)] rounded-xl border border-[var(--color-border-soft)]">
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <span className="font-bold text-[var(--color-text-main)]">{req.user_name}</span>
                    <span className="text-xs text-[var(--color-text-muted)]">({req.user_id})</span>
                  </div>
                  <p className="text-sm text-[var(--color-text-muted)] italic">"{req.reason}"</p>
                </div>
                <div className="flex items-center gap-2">
                  <button 
                    onClick={() => handleRejectClick(req.id.toString())}
                    className="p-2 text-rose-600 hover:bg-rose-50 rounded-lg transition-colors text-sm font-bold flex items-center gap-1"
                  >
                    <XCircle size={16} />
                    {t('common.reject')}
                  </button>
                  <button 
                    onClick={() => handleApproveClick(req)}
                    className="p-2 text-emerald-600 hover:bg-emerald-50 rounded-lg transition-colors text-sm font-bold flex items-center gap-1"
                  >
                    <CheckCircle size={16} />
                    {t('common.approve')}
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Reject Modal */}
      <Modal
        isOpen={isRejectModalOpen}
        onClose={() => setIsRejectModalOpen(false)}
        title={t('integrity.rejectAccessRequest')}
      >
        <div className="space-y-4">
          <textarea 
            className="input-field"
            placeholder={t('integrity.rejectionReason')}
            value={rejectionReason}
            onChange={e => setRejectionReason(e.target.value)}
          />
          <div className="flex justify-end gap-3">
            <button className="btn-secondary" onClick={() => setIsRejectModalOpen(false)}>{t('common.cancel')}</button>
            <button 
              className="btn-primary bg-rose-600" 
              onClick={async () => {
                if (selectedRequestId) {
                  await rejectRequest(selectedRequestId, rejectionReason);
                  setIsRejectModalOpen(false);
                }
              }}
            >
              {t('integrity.confirmReject')}
            </button>
          </div>
        </div>
      </Modal>

      {/* Approve Modal */}
      <Modal
        isOpen={isApproveModalOpen}
        onClose={() => setIsApproveModalOpen(false)}
        title={t('integrity.approveAccessRequest')}
      >
        <div className="space-y-4">
          <p className="text-sm text-[var(--color-text-muted)]">{t('integrity.grantAccessFor')}:</p>
          <select 
            className="input-field"
            value={selectedApprovalDuration}
            onChange={e => setSelectedApprovalDuration(e.target.value)}
          >
            <option value="1">1 {t('integrity.day')}</option>
            <option value="3">3 {t('integrity.days')}</option>
            <option value="7">7 {t('integrity.days')}</option>
            <option value="30">30 {t('integrity.days')}</option>
          </select>
          <div className="flex justify-end gap-3">
            <button className="btn-secondary" onClick={() => setIsApproveModalOpen(false)}>{t('common.cancel')}</button>
            <button 
              className="btn-primary bg-emerald-600"
              onClick={async () => {
                if (requestToApprove) {
                  await approveRequest(requestToApprove.id.toString(), selectedApprovalDuration);
                  setIsApproveModalOpen(false);
                }
              }}
            >
              {t('integrity.confirmApprove')}
            </button>
          </div>
        </div>
      </Modal>

      <PolicyModal 
        isOpen={isPolicyOpen}
        onClose={() => setIsPolicyOpen(false)}
        isEditing={isEditingPolicy}
        setIsEditing={setIsEditingPolicy}
        content={policyContent}
        setContent={setPolicyContent}
        onSave={handlePolicySave}
        onCancelEdit={() => { setIsEditingPolicy(false); fetchPolicy(); }}
        isManager={isManager}
      />
    </>
  );
};

interface PolicyModalProps {
  isOpen: boolean;
  onClose: () => void;
  isEditing: boolean;
  setIsEditing: (editing: boolean) => void;
  content: string;
  setContent: (content: string) => void;
  onSave: () => void;
  onCancelEdit: () => void;
  isManager: boolean;
}

const PolicyModal: React.FC<PolicyModalProps> = ({
  isOpen,
  onClose,
  isEditing,
  setIsEditing,
  content,
  setContent,
  onSave,
  onCancelEdit,
  isManager
}) => {
  const { t, i18n } = useTranslation();
  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 0.95 }}
            className="bg-[var(--color-card)] rounded-2xl shadow-xl w-full max-w-4xl max-h-[90vh] overflow-hidden flex flex-col"
          >
            <div className="flex items-center justify-between p-6 border-b border-[var(--color-border-soft)]">
              <div className="flex items-center gap-4">
