import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { Briefcase, Search, Plus, Edit2, Trash2, Archive } from 'lucide-react';
import { motion } from 'motion/react';
import api from '../services/api';
import { useDepartments } from '../hooks/useDepartments';
import logger from '../utils/logger';

import Modal from '../components/Modal';

const JobTitles: React.FC = () => {
  const { t } = useTranslation();
  const [jobTitles, setJobTitles] = useState<any[]>([]);
  const { departments } = useDepartments();
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | number | null>(null);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [titleToDelete, setTitleToDelete] = useState<string | number | null>(null);
  const [isStatusModalOpen, setIsStatusModalOpen] = useState(false);
  const [titleToChangeStatus, setTitleToChangeStatus] = useState<any | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    name: '',
    department: '',
    job_level: 'Staff',
    description: '',
    reporting_to: '',
    status: 'Active'
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const res = await api.get('/job-titles');
      setJobTitles(Array.isArray(res.data) ? res.data : []);
    } catch (err) {
      logger.error('Operation failed', err);
    } finally {
      setLoading(false);
    }
  };

  const filteredTitles = jobTitles.filter(j => 
    (j.name?.toLowerCase() || '').includes(searchTerm.toLowerCase()) ||
    j.department?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    try {
      const url = editingId ? `/job-titles/${editingId}` : '/job-titles';
      
      const payload = {
        ...formData,
        reporting_to: formData.reporting_to || null
      };

      if (editingId) {
        await api.put(url, payload);
      } else {
        await api.post(url, payload);
      }

      fetchData();
      setShowForm(false);
      setEditingId(null);
      setFormData({ name: '', department: '', job_level: 'Staff', description: '', reporting_to: '', status: 'Active' });
    } catch (err: any) {
      logger.error('Operation failed', err);
      const apiError = err.response?.data?.error;
      if (typeof apiError === 'string') {
        setError(apiError);
      } else if (apiError && typeof apiError === 'object') {
        setError(apiError.message || t('jobTitles.failedToSaveJobTitle'));
      } else {
        setError(t('jobTitles.failedToSaveJobTitle'));
      }
    }
  };

  const editTitle = (title: any) => {
    setEditingId(title.id);
    setFormData({
      name: title.name || '',
      department: title.department || '',
      job_level: title.job_level || 'Staff',
      description: title.description || '',
      reporting_to: title.reporting_to ? title.reporting_to.toString() : '',
      status: title.status || 'Active'
    });
    setShowForm(true);
  };

  const deleteTitle = async () => {
    if (!titleToDelete) return;
    setError(null);
    try {
      await api.delete(`/job-titles/${titleToDelete}`);
      fetchData();
      setIsDeleteModalOpen(false);
      setTitleToDelete(null);
    } catch (err: any) {
      logger.error('Operation failed', err);
      const apiError = err.response?.data?.error;
      if (typeof apiError === 'string') {
        setError(apiError);
      } else if (apiError && typeof apiError === 'object') {
        setError(apiError.message || t('jobTitles.failedToDeleteJobTitle'));
      } else {
        setError(t('jobTitles.failedToDeleteJobTitle'));
      }
    }
  };

  const archiveTitle = async () => {
    if (!titleToChangeStatus) return;
    try {
      await api.put(`/job-titles/${titleToChangeStatus.id}`, { 
        ...titleToChangeStatus, 
        status: titleToChangeStatus.status === 'Active' ? 'Inactive' : 'Active' 
      });
      fetchData();
      setIsStatusModalOpen(false);
      setTitleToChangeStatus(null);
    } catch (err) {
      logger.error('Operation failed', err);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 bg-[var(--color-bg-soft)]/50 p-6 rounded-2xl border border-[var(--color-border-soft)]">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-[var(--color-card)] rounded-xl flex items-center justify-center text-[var(--color-primary)] shadow-sm border border-[var(--color-border-soft)]">
            <Briefcase size={24} />
          </div>
          <div>
            <h3 className="text-xl font-bold text-[var(--color-text-main)] tracking-tight">{t('common.jobTitles')}</h3>
            <p className="text-xs text-[var(--color-text-muted)] font-bold">{t('manageOrgRoles')}</p>
          </div>
        </div>
        
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-4">
          <div className="relative flex-1 min-w-[250px]">
            <Search className="absolute start-4 top-1/2 -translate-y-1/2 text-[var(--color-text-muted)]" size={18} />
            <input 
              type="text"
              placeholder={t('common.search')}
              className="w-full p-2.5 ps-11 bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-xl text-sm font-bold outline-none focus:border-[var(--color-primary)] transition-colors shadow-sm"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <button onClick={() => {
            setEditingId(null);
            setFormData({ name: '', department: '', job_level: 'Staff', description: '', reporting_to: '', status: 'Active' });
            setError(null);
            setShowForm(true);
          }} className="btn-primary !py-2.5 flex items-center justify-center gap-2 whitespace-nowrap text-sm">
            <Plus size={20} />
            <span>{t('addJobTitle')}</span>
          </button>
        </div>
      </div>

      {error && !showForm && (
        <div className="p-4 bg-rose-50 text-rose-600 rounded-xl border border-rose-100 font-bold text-sm">
          {error}
        </div>
      )}

      {showForm && (
        <motion.div 
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          className="glass-card p-10 border-[var(--color-primary)]/20"
        >
          <h3 className="text-xl font-bold text-[var(--color-text-main)] mb-8">{editingId ? t('editJobTitle') : t('addNewJobTitle')}</h3>
          <form onSubmit={handleSubmit}>
            {error && (
              <div className="mb-6 p-4 bg-rose-50 text-rose-600 rounded-xl border border-rose-100 font-bold text-sm">
                {error}
              </div>
            )}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div>
                <label className="block text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-2">{t('jobTitleName')}</label>
                <input required className="input-field" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
              </div>
              <div>
                <label className="block text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-2">{t('common.departments')}</label>
                <select className="input-field" value={formData.department || ''} onChange={e => setFormData({...formData, department: e.target.value})}>
                  <option value="">{t('plan.selectDepartment')}</option>
                  {(Array.isArray(departments) ? departments : []).map(dept => (
                    <option key={dept.id} value={dept.name}>{dept.name}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-2">{t('jobLevel')}</label>
                <select className="input-field" value={formData.job_level || 'Staff'} onChange={e => setFormData({...formData, job_level: e.target.value})}>
                  <option value="Executive">{t('jobTitles.executive')}</option>
                  <option value="Manager">{t('jobTitles.manager')}</option>
                  <option value="Officer">{t('jobTitles.officer')}</option>
                  <option value="Staff">{t('jobTitles.staff')}</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-2">{t('reportsTo')}</label>
                <select className="input-field" value={formData.reporting_to || ''} onChange={e => setFormData({...formData, reporting_to: e.target.value})}>
                  <option value="">{t('common.none')}</option>
                  {(Array.isArray(jobTitles) ? jobTitles : []).filter(j => String(j.id) !== String(editingId)).map(title => (
                    <option key={title.id} value={title.id}>{title.name} ({title.department})</option>
                  ))}
                </select>
              </div>
              <div className="md:col-span-2">
                <label className="block text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-2">{t('common.description')}</label>
                <textarea className="input-field min-h-[100px]" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} />
              </div>
              <div>
                <label className="block text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-2">{t('common.statusLabel')}</label>
                <select className="input-field" value={formData.status || 'Active'} onChange={e => setFormData({...formData, status: e.target.value})}>
                  <option value="Active">{t('common.active')}</option>
                  <option value="Inactive">{t('common.inactive')}</option>
                </select>
              </div>
            </div>
            <div className="flex justify-end gap-4 mt-8">
              <button type="button" onClick={() => setShowForm(false)} className="btn-secondary">{t('common.cancel')}</button>
              <button type="submit" className="btn-primary">{editingId ? t('common.save') : t('addJobTitle')}</button>
            </div>
          </form>
        </motion.div>
      )}

      <div className="glass-card overflow-hidden">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-start border-collapse">
            <thead>
              <tr className="bg-[var(--color-bg-soft)]/50 border-b border-[var(--color-border-soft)]">
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('common.id')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('common.jobTitles')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('common.departments')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('jobLevel')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('common.statusLabel')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-start">{t('created')}</th>
                <th className="px-6 py-4 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em] text-end">{t('common.actions')}</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[var(--color-border-soft)]/50">
              {(Array.isArray(filteredTitles) ? filteredTitles : []).map((title, idx) => (
                <motion.tr 
                  key={title.id}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: idx * 0.02 }}
                  className="hover:bg-[var(--color-primary)]/5 transition-colors group"
                >
                  <td className="px-6 py-4 text-xs font-bold text-[var(--color-text-muted)]">#{title.id}</td>
                  <td className="px-6 py-4">
                    <div className="font-bold text-[var(--color-text-main)]">{title.name}</div>
                    {title.description && <div className="text-xs text-[var(--color-text-muted)] truncate max-w-[200px] mt-1">{title.description}</div>}
                  </td>
                  <td className="px-6 py-4 text-sm font-bold text-[var(--color-text-muted)]">{title.department || '-'}</td>
                  <td className="px-6 py-4">
                    <span className="px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest bg-[var(--color-bg-main)] text-[var(--color-text-muted)]">
                      {t(`jobTitles.${title.job_level?.toLowerCase()}`)}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest ${
                      title.status === 'Active' ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'
                    }`}>
                      <div className={`w-1.5 h-1.5 rounded-full ${title.status === 'Active' ? 'bg-emerald-500' : 'bg-rose-500'}`} />
                      {t(`jobTitles.${title.status?.toLowerCase()}`)}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-xs font-bold text-[var(--color-text-muted)]">
                    {new Date(title.created_at).toLocaleDateString()}
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center justify-end gap-2 md:opacity-0 md:group-hover:opacity-100 transition-opacity">
                      <button onClick={() => editTitle(title)} className="p-2 text-[var(--color-text-muted)] hover:text-[var(--color-primary)] hover:bg-[var(--color-primary)]/10 rounded-lg transition-colors" title={t('common.edit')}>
                        <Edit2 size={16} />
                      </button>
                      <button onClick={() => {
                        setTitleToChangeStatus(title);
                        setIsStatusModalOpen(true);
                      }} className={`p-2 rounded-lg transition-colors ${title.status === 'Active' ? 'text-[var(--color-text-muted)] hover:text-amber-600 hover:bg-amber-50' : 'text-[var(--color-text-muted)] hover:text-emerald-600 hover:bg-emerald-50'}`} title={title.status === 'Active' ? t('markInactive') : t('markActive')}>
                        <Archive size={16} />
                      </button>
                      <button onClick={() => {
                        setTitleToDelete(title.id);
                        setIsDeleteModalOpen(true);
                      }} className="p-2 text-[var(--color-text-muted)] hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-colors" title={t('common.delete')}>
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </td>
                </motion.tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <Modal
        isOpen={isDeleteModalOpen}
        onClose={() => setIsDeleteModalOpen(false)}
        title={t('deleteJobTitle')}
      >
        <div className="space-y-6">
          <p className="text-sm text-[var(--color-text-muted)] font-bold">
            {t('deleteJobTitleConfirm')}
          </p>
          <div className="flex justify-end gap-4 pt-4 border-t border-[var(--color-border-soft)]">
            <button 
              onClick={() => setIsDeleteModalOpen(false)}
              className="px-6 py-3 rounded-2xl bg-[var(--color-bg-main)] text-[var(--color-text-muted)] font-bold hover:bg-[var(--color-bg-main)] transition-colors"
            >
              {t('common.cancel')}
            </button>
            <button 
              onClick={deleteTitle}
              className="px-6 py-3 rounded-2xl bg-rose-500 text-white font-bold hover:bg-rose-600 transition-colors shadow-lg shadow-rose-500/30"
            >
              {t('common.delete')}
            </button>
          </div>
        </div>
      </Modal>

      <Modal
        isOpen={isStatusModalOpen}
        onClose={() => setIsStatusModalOpen(false)}
        title={t('common.statusLabel')}
      >
        <div className="space-y-6">
          <p className="text-sm text-[var(--color-text-muted)] font-bold">
            {titleToChangeStatus?.status === 'Active' 
              ? t('statusConfirmInactive') 
              : t('statusConfirmActive')}
          </p>
          <div className="flex justify-end gap-4 pt-4 border-t border-[var(--color-border-soft)]">
            <button 
              onClick={() => setIsStatusModalOpen(false)}
              className="px-6 py-3 rounded-2xl bg-[var(--color-bg-main)] text-[var(--color-text-muted)] font-bold hover:bg-[var(--color-bg-main)] transition-colors"
            >
              {t('common.cancel')}
            </button>
            <button 
              onClick={archiveTitle}
              className="px-6 py-3 rounded-2xl bg-[var(--color-primary)] text-white font-bold hover:bg-[var(--color-primary)]/90 transition-colors shadow-lg shadow-[var(--color-primary)]/30"
            >
              {t('common.save')}
            </button>
          </div>
        </div>
      </Modal>
    </div>
  );
};

export default JobTitles;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { usePreferences } from '../context/PreferencesContext';
import { useNotificationContext } from '../context/NotificationContext';
import { useTranslation } from 'react-i18next';
import { Bell, Check, Trash2, Filter, Search, Calendar, FileText, Info, AlertTriangle, UserPlus, Shield } from 'lucide-react';
import { motion, AnimatePresence } from 'motion/react';
import Modal from '../components/Modal';
import { getTranslatedNotificationMessage, getTranslatedNotificationModule } from '../utils/notificationHelpers';

const Notifications: React.FC = () => {
  const { t, i18n } = useTranslation();
  const { language } = usePreferences();
  const { notifications, markAsRead, markAllAsRead, deleteNotification, loadMore, hasMore, isLoading } = useNotificationContext();
  const navigate = useNavigate();
  const [filter, setFilter] = useState<'all' | 'unread' | 'read'>('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [notificationToDelete, setNotificationToDelete] = useState<number | null>(null);

  const handleNotificationClick = (notification: any) => {
    if (!notification.is_read && notification.status !== 'Read') {
      markAsRead(notification.id);
    }
    if (notification.link) {
      const link = notification.link.replace('/', '');
      let tab = 'dashboard';
      if (link.includes('audit-plans')) tab = 'plan';
      else if (link.includes('audit-tasks')) tab = 'tasks';
      else if (link.includes('audit-programs')) tab = 'library';
      else if (link.includes('audit-findings')) tab = 'findings';
      else if (link.includes('audit-evidence')) tab = 'evidence';
      else if (link.includes('recommendations')) tab = 'recommendations';
      else if (link.includes('risk-register')) tab = 'risks';
      else if (link.includes('central-bank')) tab = 'compliance-matrix';
      else if (link.includes('law-bank')) tab = 'compliance-matrix';
      else if (link.includes('policies')) tab = 'compliance-matrix';
      else if (link.includes('fraud-log')) tab = 'fraud';
      else if (link.includes('departments')) tab = 'departments';
      else if (link.includes('audit-trail')) tab = 'trail';
      else if (link.includes('users')) tab = 'users';
      
      navigate(`/${tab}`);
    }
  };

  const isUnread = (n: any) => !n.is_read && n.status !== 'Read';

  const filteredNotifications = (Array.isArray(notifications) ? notifications : []).filter(n => {
    const matchesFilter = filter === 'all' ? true : 
                          filter === 'unread' ? isUnread(n) : 
                          !isUnread(n);
    const matchesSearch = (n.description?.toLowerCase() || '').includes(searchTerm.toLowerCase()) || 
                          (n.related_module?.toLowerCase() || '').includes(searchTerm.toLowerCase()) ||
                          (n.title?.toLowerCase() || '').includes(searchTerm.toLowerCase());
    return matchesFilter && matchesSearch;
  });

  const getIcon = (type: string) => {
    switch (type) {
      case 'Created': return <FileText size={20} className="text-emerald-500" />;
      case 'Updated': return <Info size={20} className="text-blue-500" />;
      case 'Alert': return <AlertTriangle size={20} className="text-amber-500" />;
      case 'User': return <UserPlus size={20} className="text-purple-500" />;
      case 'Security': return <Shield size={20} className="text-rose-500" />;
      default: return <Bell size={20} className="text-[var(--color-text-muted)]" />;
    }
  };

  return (
    <div className="space-y-8" dir={i18n.language === 'ar' ? 'rtl' : 'ltr'}>
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div className="flex items-center gap-6">
          <div className="w-12 h-12 sm:w-16 sm:h-16 bg-[var(--color-primary)] rounded-2xl flex items-center justify-center text-white shadow-lg shadow-[var(--color-primary)]/20">
            <Bell size={32} />
          </div>
          <div>
            <h2 className="text-2xl sm:text-4xl font-bold text-[var(--color-text-main)] tracking-tight mb-2">{t('common.notifications')}</h2>
            <p className="text-sm text-[var(--color-text-muted)] font-bold">{t('common.stayUpdated')}</p>
          </div>
        </div>
        <div className="flex gap-3">
          <button 
            onClick={() => markAllAsRead()}
            className="btn-secondary flex items-center gap-2"
          >
            <Check size={18} />
            <span>{t('common.markAllRead')}</span>
          </button>
        </div>
      </div>

      <div className="glass-card p-6">
        <div className="flex flex-col md:flex-row gap-4 mb-6">
          <div className="flex gap-2 p-1.5 bg-[var(--color-card)] rounded-2xl w-fit border border-[var(--color-border-soft)]">
            <button 
              onClick={() => setFilter('all')}
              className={`px-4 py-2 rounded-xl text-xs font-semibold uppercase tracking-wider transition-all cursor-pointer ${filter === 'all' ? 'bg-[var(--color-primary)] text-white shadow-md shadow-[var(--color-primary)]/20' : 'text-[var(--color-text-muted)] hover:text-[var(--color-text-main)] hover:bg-[var(--color-bg-soft)]'}`}
            >
              {t('common.all')}
            </button>
            <button 
              onClick={() => setFilter('unread')}
              className={`px-4 py-2 rounded-xl text-xs font-semibold uppercase tracking-wider transition-all cursor-pointer ${filter === 'unread' ? 'bg-[var(--color-primary)] text-white shadow-md shadow-[var(--color-primary)]/20' : 'text-[var(--color-text-muted)] hover:text-[var(--color-text-main)] hover:bg-[var(--color-bg-soft)]'}`}
            >
              {t('common.unread')}
            </button>
            <button 
              onClick={() => setFilter('read')}
              className={`px-4 py-2 rounded-xl text-xs font-semibold uppercase tracking-wider transition-all cursor-pointer ${filter === 'read' ? 'bg-[var(--color-primary)] text-white shadow-md shadow-[var(--color-primary)]/20' : 'text-[var(--color-text-muted)] hover:text-[var(--color-text-main)] hover:bg-[var(--color-bg-soft)]'}`}
            >
              {t('common.read')}
            </button>
          </div>
          <div className="relative flex-1">
            <Search className="absolute start-4 top-1/2 -translate-y-1/2 text-[var(--color-text-muted)]" size={18} />
            <input 
              type="text" 
              placeholder={t('common.searchNotifications')} 
              className="input-field !ps-12"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>

        <div className="space-y-4">
          <AnimatePresence>
            {filteredNotifications.length === 0 ? (
              <motion.div 
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                className="text-center py-20"
              >
                <div className="w-20 h-20 bg-[var(--color-bg-soft)] rounded-full flex items-center justify-center mx-auto mb-4 text-[var(--color-border-strong)]">
                  <Bell size={40} />
                </div>
                <h3 className="text-xl font-bold text-[var(--color-text-main)] mb-2">{t('common.noNotificationsFound')}</h3>
                <p className="text-[var(--color-text-muted)] text-sm font-bold">{t('common.tryAdjustingFilters')}</p>
              </motion.div>
            ) : (
              (Array.isArray(filteredNotifications) ? filteredNotifications : []).map((notification) => (
                <motion.div
                  key={notification.id}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, height: 0 }}
                  onClick={() => handleNotificationClick(notification)}
                  className={`relative group p-6 rounded-2xl border transition-all cursor-pointer ${isUnread(notification) ? 'bg-[var(--color-card)] border-[var(--color-primary)]/20 shadow-lg shadow-[var(--color-primary)]/5' : 'bg-[var(--color-bg-soft)]/50 border-[var(--color-border-soft)]'}`}
                >
                  <div className="flex items-start gap-4">
                    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 ${isUnread(notification) ? 'bg-[var(--color-primary)]/10 shadow-inner' : 'bg-[var(--color-card)] border border-[var(--color-border-soft)]'}`}>
                      {getIcon(notification.event_type)}
                    </div>
                    
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center justify-between mb-1 pe-12">
                        <span className={`text-xs font-bold uppercase tracking-widest ${isUnread(notification) ? 'text-[var(--color-primary)]' : 'text-[var(--color-text-muted)]'}`}>
                          {getTranslatedNotificationModule(notification.related_module, t)}
                        </span>
                        <span className="text-xs font-bold text-[var(--color-text-muted)] flex items-center gap-1">
                          <Calendar size={12} />
                          {new Date(notification.date).toLocaleString(i18n.language)}
                        </span>
                      </div>
                      
                      {notification.title && (
                        <p className={`text-sm font-bold mb-1 ${isUnread(notification) ? 'text-[var(--color-primary)]' : 'text-[var(--color-text-muted)]'}`}>
                          {notification.title}
                        </p>
                      )}
                      
                      <h3 className={`text-lg font-bold mb-2 pe-12 ${isUnread(notification) ? 'text-[var(--color-text-main)]' : 'text-[var(--color-text-muted)]'}`}>
                        {getTranslatedNotificationMessage(notification.description, t, language)}
                      </h3>
                      
                      <div className="flex items-center gap-4 mt-4">
                        {isUnread(notification) && (
                          <button 
                            onClick={(e) => {
                              e.stopPropagation();
                              notification.id && markAsRead(notification.id);
                            }}
                            className="text-xs font-bold text-[var(--color-primary)] hover:text-[var(--color-primary)]/80 uppercase tracking-wider flex items-center gap-1"
                          >
                            <Check size={14} /> {t('common.markAsRead')}
                          </button>
                        )}
                        <button 
                          onClick={(e) => {
                            e.stopPropagation();
                            if (notification.id) {
                              setNotificationToDelete(notification.id);
                              setIsDeleteModalOpen(true);
                            }
                          }}
                          className="text-xs font-bold text-[var(--color-text-muted)] hover:text-rose-500 uppercase tracking-wider flex items-center gap-1 md:opacity-0 md:group-hover:opacity-100 transition-opacity"
                        >
                          <Trash2 size={14} /> {t('common.delete')}
                        </button>
                      </div>
                    </div>
                  </div>
                  
                  {isUnread(notification) && (
                    <div className="absolute top-1/2 -translate-y-1/2 end-6 w-3 h-3 bg-[var(--color-primary)] rounded-full shadow-lg shadow-[var(--color-primary)]/20 animate-pulse" />
                  )}
                </motion.div>
              ))
            )}
          </AnimatePresence>
          
          {/* Load More Button */}
          {hasMore && !isLoading && (
            <div className="text-center pt-6">
              <button 
                onClick={loadMore}
                className="btn-secondary px-8"
              >
                {t('common.loadMore')}
              </button>
            </div>
          )}
          {isLoading && (
            <div className="text-center py-6">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-[var(--color-primary)] mx-auto"></div>
            </div>
          )}
        </div>
      </div>

      <Modal
        isOpen={isDeleteModalOpen}
        onClose={() => {
          setIsDeleteModalOpen(false);
          setNotificationToDelete(null);
        }}
        title={t('deleteConfirm')}
      >
        <div className="space-y-6">
          <p className="text-[var(--color-text-muted)] font-medium">
            {t('deleteMessage')}
          </p>
          <div className="flex justify-end gap-4">
            <button
              onClick={() => {
                setIsDeleteModalOpen(false);
                setNotificationToDelete(null);
              }}
              className="btn-secondary"
            >
              {t('common.cancel')}
            </button>
            <button
              onClick={() => {
                if (notificationToDelete) {
                  deleteNotification(notificationToDelete);
                  setIsDeleteModalOpen(false);
                  setNotificationToDelete(null);
                }
              }}
              className="btn-danger"
            >
              {t('common.delete')}
            </button>
          </div>
        </div>
      </Modal>
    </div>
  );
};

export default Notifications;

import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { 
  Users, Search, Plus, Edit2, Archive, ChevronRight, ChevronDown, 
  MapPin, User, Hash, Info, Building2, LayoutGrid, BarChart3, List,
  Filter, AlertCircle, Network
} from 'lucide-react';
import { useTranslation } from 'react-i18next';
import api from '../../services/api';
import { extractErrorMessage } from '../../services/errorService';
import { useDepartments, Department } from '../../hooks/useDepartments';
import { useFormat } from '../../services/formatService';
import Modal from '../../components/Modal';
import toast from 'react-hot-toast';
import { useUser } from '../../context/UserContext';
import { UserRole } from '../../constants';
import logger from '../../utils/logger';

// --- Components ---

interface TreeNodeProps {
  node: Department;
  level: number;
  onEdit: (node: Department) => void;
  onAddChild: (parentId: string) => void;
  onArchive: (node: Department) => void;
}

const TreeNode: React.FC<TreeNodeProps> = ({ node, level, onEdit, onAddChild, onArchive }) => {
  const [isExpanded, setIsExpanded] = useState(level < 1);
  const { i18n, t } = useTranslation();
  const isRTL = i18n.language === 'ar';

  const getTypeBadgeColor = (type: string) => {
    switch (type) {
      case 'Top Management': return 'bg-blue-900 text-white';
      case 'Department':      return 'bg-blue-100 text-blue-700 border-blue-200';
      case 'Division':        return 'bg-teal-100 text-teal-700 border-teal-200';
      case 'Unit':            return 'bg-green-100 text-green-700 border-green-200';
      case 'Branch':          return 'bg-orange-100 text-orange-700 border-orange-200';
      case 'Office':          return 'bg-purple-100 text-purple-700 border-purple-200';
      case 'Committee':       return 'bg-[var(--color-bg-main)] text-[var(--color-text-main)] border-[var(--color-border-soft)]';
      default:                return 'bg-[var(--color-bg-soft)] text-[var(--color-text-muted)] border-[var(--color-border-soft)]';
    }
  };

  const hasChildren = node.children && node.children.length > 0;

  return (
    <div className="mb-2">
      <div 
        className={`group flex items-center p-3 rounded-xl border transition-all duration-200 ${
          isExpanded ? 'bg-[var(--color-card)] shadow-sm border-[var(--color-border-soft)]' : 'bg-[var(--color-card)]/50 border-transparent hover:bg-[var(--color-card)] hover:border-[var(--color-border-soft)]'
        }`}
        style={{ [isRTL ? 'marginRight' : 'marginLeft']: `${level * 24}px` }}
      >
        <div className="flex items-center gap-3 flex-1 min-w-0">
          <button 
            onClick={() => setIsExpanded(!isExpanded)}
            className={`p-1 rounded-lg hover:bg-[var(--color-bg-main)] transition-colors ${!hasChildren && 'opacity-0 cursor-default'}`}
            disabled={!hasChildren}
          >
            {isExpanded ? <ChevronDown size={16} /> : (isRTL ? <ChevronRight size={16} className="rotate-180" /> : <ChevronRight size={16} />)}
          </button>
          
          <div className="flex flex-col gap-1 min-w-0">
            <div className="flex items-center gap-2 flex-wrap">
              <span className="px-1.5 py-0.5 bg-[var(--color-bg-main)] text-[var(--color-text-muted)] text-[10px] font-mono rounded border border-[var(--color-border-soft)] uppercase tracking-tighter shrink-0">
                {node.entity_code}
              </span>
              <h4 className="font-bold text-[var(--color-text-main)] truncate">{node.name_ar}</h4>
              <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full border uppercase tracking-wider shrink-0 ${getTypeBadgeColor(node.entity_type)}`}>
                {t(`orgTypes.${node.entity_type}`, node.entity_type)}
              </span>
              <span className={`w-2 h-2 rounded-full shrink-0 ${node.status === 'Active' ? 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.4)]' : 'bg-slate-300'}`} />
            </div>
            
            <div className="flex items-center gap-4 text-xs text-[var(--color-text-muted)]">
              {node.manager_name && (
                <div className="flex items-center gap-1.5 min-w-0">
                  <User size={12} className="shrink-0" />
                  <span className="truncate">{node.manager_name}</span>
                </div>
              )}
              {node.name_en && (
                <div className="flex items-center gap-1.5 min-w-0 italic opacity-60">
                  <span className="truncate">{node.name_en}</span>
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="flex items-center gap-1 md:opacity-0 md:group-hover:opacity-100 transition-opacity">
          <button 
            onClick={() => onAddChild(node.id)}
            className="p-2 text-[var(--color-primary)] hover:bg-[var(--color-primary-light)] rounded-lg transition-colors"
            title={t('addChildUnit')}
          >
            <Plus size={16} />
          </button>
          <button 
            onClick={() => onEdit(node)}
            className="p-2 text-[var(--color-text-muted)] hover:bg-[var(--color-bg-main)] rounded-lg transition-colors"
            title={t('editUnit')}
          >
            <Edit2 size={16} />
          </button>
          <button 
            onClick={() => onArchive(node)}
            className="p-2 text-rose-600 hover:bg-rose-50 rounded-lg transition-colors"
            title={t('archiveUnit')}
          >
            <Archive size={16} />
          </button>
        </div>
      </div>

      <AnimatePresence>
        {isExpanded && hasChildren && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            className="overflow-hidden"
          >
            {node.children!.map(child => (
              <TreeNode 
                key={child.id} 
                node={child} 
                level={level + 1} 
                onEdit={onEdit}
                onAddChild={onAddChild}
                onArchive={onArchive}
              />
            ))}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

// --- Main Component ---

const OrgStructure: React.FC = () => {
  const { t, i18n } = useTranslation();
  const { formatNumber } = useFormat();
  const isRTL = i18n.language === 'ar';
  const { user } = useUser();
  const isAdmin = [UserRole.ADMIN, UserRole.MANAGER].includes(user?.role as any || '');

  const [activeTab, setActiveTab] = useState<'tree' | 'table' | 'stats'>('tree');
  const { departments, refresh, loading: flatLoading, error } = useDepartments();
  const [treeData, setTreeData] = useState<Department[]>([]);
  const [treeLoading, setTreeLoading] = useState(false);

  // Search & Filter state
  const [search, setSearch] = useState('');
  const [filterType, setFilterType] = useState('All');
  const [filterStatus, setFilterStatus] = useState('All');

  // Modal state
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingNode, setEditingNode] = useState<Partial<Department> | null>(null);

  const fetchTree = async () => {
    setTreeLoading(true);
    try {
      const res = await api.get('/departments/tree');
      setTreeData(res.data);
    } catch (e) {
      logger.error('Operation failed', e);
      toast.error(t('errorLoadingTree'));
    } finally {
      setTreeLoading(false);
    }
  };

  useEffect(() => {
    if (activeTab === 'tree') fetchTree();
  }, [activeTab]);

  useEffect(() => {
    if (error) {
      toast.error(error);
    }
  }, [error]);

  const filteredList = useMemo(() => {
    return departments.filter(d => {
      const searchLower = search.toLowerCase();
      const matchesSearch = 
        (d.name_ar || '').toLowerCase().includes(searchLower) || 
        (d.name_en || '').toLowerCase().includes(searchLower) || 
        (d.entity_code || '').toLowerCase().includes(searchLower);
      const matchesType = filterType === 'All' || d.entity_type === filterType;
      const matchesStatus = filterStatus === 'All' || d.status === filterStatus;
      return matchesSearch && matchesType && matchesStatus;
    });
  }, [departments, search, filterType, filterStatus]);

  const stats = useMemo(() => {
    const activeUnits = departments.filter(d => d.status === 'Active').length;
    const inactiveUnits = departments.filter(d => d.status === 'Inactive').length;
    const noManager = departments.filter(d => d.status === 'Active' && !d.manager_name).length;
    const byType = departments.reduce((acc, d) => {
      acc[d.entity_type] = (acc[d.entity_type] || 0) + (d.status === 'Active' ? 1 : 0);
      return acc;
    }, {} as Record<string, number>);

    return { activeUnits, inactiveUnits, noManager, byType };
  }, [departments]);

  const handleEdit = (node: Department) => {
    setEditingNode(node);
    setIsModalOpen(true);
  };

  const handleAddChild = (parentId: string) => {
    setEditingNode({ parent_id: parentId });
    setIsModalOpen(true);
  };

  const handleArchive = async (node: Department) => {
    if (node.children && node.children.length > 0) {
      toast.error(t('cannotDeleteParent'));
      return;
    }

    if (!window.confirm(t('confirmArchiveUnit'))) return;

    try {
      await api.delete(`/departments/${node.id}`);
      toast.success(t('archiveSuccess'));
      refresh();
      if (activeTab === 'tree') fetchTree();
    } catch (error: any) {
      toast.error(extractErrorMessage(error, t('archiveFailed')));
    }
  };

  const entityTypes = [
    'Top Management', 'Department', 'Division', 'Unit', 'Branch', 'Office', 'Committee', 'Other'
  ];

  return (
    <div className="p-6 max-w-7xl mx-auto space-y-6">
      <header className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div className="flex items-center gap-6">
          <div className="w-12 h-12 sm:w-16 sm:h-16 bg-[var(--color-primary)] rounded-2xl flex items-center justify-center text-white shadow-lg shadow-[var(--color-primary)]/20">
            <Network size={32} />
          </div>
          <div>
            <h1 className="text-2xl sm:text-4xl font-bold text-[var(--color-text-main)] tracking-tight">
              {t('organizationalStructure')}
            </h1>
            <p className="text-sm text-[var(--color-text-muted)] font-bold mt-2">{t('orgStructureDesc')}</p>
          </div>
        </div>
        
        {isAdmin && (
          <button 
            onClick={() => { setEditingNode({}); setIsModalOpen(true); }}
            className="btn-primary"
          >
            <Plus size={20} className={isRTL ? 'ml-2' : 'mr-2'} />
            {t('addUnit')}
          </button>
        )}
      </header>

      {/* Tabs */}
      <div className="flex items-center gap-1 p-1 bg-[var(--color-bg-main)] rounded-2xl w-fit">
        {[
          { id: 'tree', icon: LayoutGrid, label: t('treeView') },
          { id: 'table', icon: List, label: t('listView') },
          { id: 'stats', icon: BarChart3, label: t('statistics') },
        ].map((tab) => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-bold transition-all cursor-pointer duration-200 ${
              activeTab === tab.id 
                ? 'bg-[var(--color-card)] text-[var(--color-primary)] shadow-sm' 
                : 'text-[var(--color-text-muted)] hover:bg-[var(--color-card)]/50'
            }`}
          >
            <tab.icon size={18} />
            {tab.label}
          </button>
        ))}
      </div>

      {/* Content */}
      <div className="min-h-[400px]">
        {activeTab === 'tree' && (
          <div className="glass-card p-6 min-h-[500px]">
            {treeLoading ? (
              <div className="flex flex-col items-center justify-center py-20 gap-4">
                <div className="w-10 h-10 border-4 border-blue-600 border-t-transparent rounded-full animate-spin" />
                <p className="text-[var(--color-text-muted)] font-bold">{t('loadingTree')}</p>
              </div>
            ) : treeData.length > 0 ? (
              <div className="space-y-1">
                {treeData.map(node => (
                  <TreeNode 
                    key={node.id} 
                    node={node} 
                    level={0} 
                    onEdit={handleEdit}
                    onAddChild={handleAddChild}
                    onArchive={handleArchive}
                  />
                ))}
              </div>
            ) : (
              <div className="flex flex-col items-center justify-center py-20 text-center uppercase tracking-widest gap-4">
                <div className="w-20 h-20 bg-[var(--color-bg-soft)] rounded-full flex items-center justify-center text-slate-200 border border-[var(--color-border-soft)]">
                  <LayoutGrid size={40} />
                </div>
                <p className="text-[var(--color-text-muted)] font-bold text-sm">{t('noStructureDefined')}</p>
              </div>
            )}
          </div>
        )}

        {activeTab === 'table' && (
          <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2">
            <div className="glass-card p-4 flex flex-col md:flex-row gap-4 items-center">
              <div className="relative flex-1">
                <Search className="absolute start-3 top-1/2 -translate-y-1/2 text-[var(--color-text-muted)]" size={18} />
                <input 
                  type="text"
                  placeholder={t('searchUnits')}
                  className="input-field ps-10"
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                />
              </div>
              <div className="flex items-center gap-2 w-full md:w-auto">
                <select 
                  className="input-field w-full md:w-40"
                  value={filterType}
                  onChange={(e) => setFilterType(e.target.value)}
                >
                  <option value="All">{t('allTypes')}</option>
                  {entityTypes.map(type => <option key={type} value={type}>{t(`orgTypes.${type}`, type)}</option>)}
                </select>
                <select 
                  className="input-field w-full md:w-32"
                  value={filterStatus}
                  onChange={(e) => setFilterStatus(e.target.value)}
                >
                  <option value="All">{t('allStatuses')}</option>
                  <option value="Active">{t('common.active')}</option>
                  <option value="Inactive">{t('common.inactive')}</option>
                </select>
              </div>
            </div>

            <div className="glass-card overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-sm text-start">
                  <thead className="bg-[var(--color-bg-soft)] border-b border-[var(--color-border-soft)]">
                    <tr className="text-[var(--color-text-muted)] font-bold uppercase tracking-wider text-[10px]">
                      <th className="px-6 py-4">{t('code')}</th>
                      <th className="px-6 py-4">{t('unitName')}</th>
                      <th className="px-6 py-4">{t('entityType')}</th>
                      <th className="px-6 py-4">{t('parent')}</th>
                      <th className="px-6 py-4">{t('manager')}</th>
                      <th className="px-6 py-4">{t('status')}</th>
                      <th className="px-6 py-4 text-center">{t('actions')}</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[var(--color-border-soft)]">
                    {filteredList.map(item => (
                      <tr key={item.id} className="hover:bg-[var(--color-bg-soft)]/50 transition-colors">
                        <td className="px-6 py-4 font-mono text-[10px] text-[var(--color-text-muted)] uppercase">{item.entity_code}</td>
                        <td className="px-6 py-4">
                          <div className="font-bold text-[var(--color-text-main)]">{item.name_ar}</div>
                          <div className="text-[10px] text-[var(--color-text-muted)]">{item.name_en}</div>
                        </td>
                        <td className="px-6 py-4">
                          <span className="text-[10px] font-bold px-2 py-0.5 rounded-full border border-[var(--color-border-soft)] bg-[var(--color-card)] text-[var(--color-text-muted)]">
                            {item.entity_type}
                          </span>
                        </td>
                        <td className="px-6 py-4 text-[var(--color-text-muted)]">
                          {departments.find(d => d.id === item.parent_id)?.name_ar || '-'}
                        </td>
                        <td className="px-6 py-4 text-[var(--color-text-muted)] font-medium">
                          {item.manager_name || <span className="text-rose-400 italic text-[10px] font-bold">{t('notAssigned')}</span>}
                        </td>
                        <td className="px-6 py-4">
                          <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold ${
                            item.status === 'Active' ? 'bg-green-100 text-green-700' : 'bg-[var(--color-bg-main)] text-[var(--color-text-muted)]'
                          }`}>
                            {t(`common.status.${(item.status || '').toLowerCase()}`)}
                          </span>
                        </td>
                        <td className="px-6 py-4 flex items-center justify-center gap-2">
                          <button onClick={() => handleEdit(item)} className="p-2 text-[var(--color-text-muted)] hover:text-[var(--color-primary)] hover:bg-[var(--color-primary-light)] rounded-lg transition-colors">
                            <Edit2 size={16} />
                          </button>
                          <button onClick={() => handleArchive(item)} className="p-2 text-[var(--color-text-muted)] hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-colors">
                            <Archive size={16} />
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'stats' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 animate-in fade-in slide-in-from-bottom-2">
            <div className="glass-card p-6 space-y-2">
              <div className="flex items-center justify-between">
                <div className="p-2 bg-green-100 text-green-700 rounded-xl">
                  <LayoutGrid size={24} />
                </div>
                <span className="text-[10px] font-bold text-green-600 bg-green-50 px-2 py-1 rounded-full">{t('activeUnits')}</span>
              </div>
              <h3 className="text-3xl font-bold text-[var(--color-text-main)]">{formatNumber(stats.activeUnits)}</h3>
              <p className="text-sm text-[var(--color-text-muted)] font-bold">{t('totalActiveUnits')}</p>
            </div>
            
            <div className="glass-card p-6 space-y-2">
              <div className="flex items-center justify-between">
                <div className="p-2 bg-amber-100 text-amber-700 rounded-xl">
                  <User size={24} />
                </div>
                <span className="text-[10px] font-bold text-amber-600 bg-amber-50 px-2 py-1 rounded-full">{t('missingManager')}</span>
              </div>
              <h3 className="text-3xl font-bold text-[var(--color-text-main)]">{formatNumber(stats.noManager)}</h3>
              <p className="text-sm text-[var(--color-text-muted)] font-bold">{t('unitsWithoutManager')}</p>
            </div>

            <div className="glass-card p-6 space-y-2">
              <div className="flex items-center justify-between">
                <div className="p-2 bg-[var(--color-bg-main)] text-[var(--color-text-main)] rounded-xl">
                  <AlertCircle size={24} />
                </div>
                <span className="text-[10px] font-bold text-[var(--color-text-muted)] bg-[var(--color-bg-soft)] px-2 py-1 rounded-full">{t('inactiveLabel')}</span>
              </div>
              <h3 className="text-3xl font-bold text-[var(--color-text-main)]">{formatNumber(stats.inactiveUnits)}</h3>
              <p className="text-sm text-[var(--color-text-muted)] font-bold">{t('suspendedUnits')}</p>
            </div>

            <div className="glass-card p-6 flex flex-col justify-center">
              <h4 className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-4">{t('distributionByType')}</h4>
              <div className="space-y-3">
                {Object.entries(stats.byType).map(([type, count]) => (
                  <div key={type} className="space-y-1">
                    <div className="flex justify-between text-[10px] font-bold">
                      <span className="text-[var(--color-text-muted)]">{type}</span>
                      <span className="text-[var(--color-text-muted)]">{formatNumber(count as number)}</span>
                    </div>
                    <div className="h-1.5 bg-[var(--color-bg-main)] rounded-full overflow-hidden">
                      <div 
                        className="h-full bg-[var(--color-primary-light)]0 transition-all duration-500" 
                        style={{ width: `${(count / stats.activeUnits) * 100}%` }}
                      />
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>

      <OrgUnitModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        editingNode={editingNode}
        departments={departments}
        onSave={() => {
          refresh();
          if (activeTab === 'tree') fetchTree();
        }}
      />
    </div>
  );
};

interface OrgUnitModalProps {
  isOpen: boolean;
  onClose: () => void;
  editingNode: Partial<Department> | null;
  departments: Department[];
  onSave: () => void;
}

const OrgUnitModal: React.FC<OrgUnitModalProps> = ({ isOpen, onClose, editingNode, departments, onSave }) => {
  const { t } = useTranslation();
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState<any>({});

  useEffect(() => {
    if (editingNode) {
      setFormData({
        entity_code: (editingNode as any).entity_code || (editingNode as any).code || '',
        name_ar: editingNode.name_ar || '',
        name_en: editingNode.name_en || '',
        entity_type: editingNode.entity_type || 'Department',
        parent_id: editingNode.parent_id || null,
        manager_name: editingNode.manager_name || '',
        description: editingNode.description || '',
        location: editingNode.location || '',
        cost_center_code: editingNode.cost_center_code || '',
        status: editingNode.status || 'Active'
      });
    }
  }, [editingNode, isOpen]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      if (editingNode?.id) {
        await api.put(`/departments/${editingNode.id}`, formData);
        toast.success(t('updateSuccess'));
      } else {
        await api.post('/departments', formData);
        toast.success(t('createSuccess'));
      }
      onSave();
      onClose();
    } catch (error: any) {
      toast.error(extractErrorMessage(error, t('saveFailed')));
    } finally {
      setLoading(false);
    }
  };

  const handleEntityCodeBlur = () => {
    if (!formData.entity_code) {
      const typePrefix = formData.entity_type?.substring(0, 4).toUpperCase() || 'DEPT';
      setFormData({ ...formData, entity_code: `${typePrefix}-${Date.now().toString().slice(-6)}` });
    }
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title={editingNode?.id ? t('editUnit') : t('newUnit')} size="lg">
      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="space-y-1">
            <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest flex items-center gap-1.5">
              <Hash size={12} />
              {t('unitCode')} *
            </label>
            <input 
              type="text"
              required
              className="input-field"
              placeholder={t('placeholders.entityCode')}
              value={formData.entity_code}
              onChange={(e) => setFormData({ ...formData, entity_code: e.target.value })}
              onBlur={handleEntityCodeBlur}
            />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest flex items-center gap-1.5">
              <LayoutGrid size={12} />
              {t('entityType')} *
            </label>
            <select 
              required
              className="input-field"
              value={formData.entity_type}
              onChange={(e) => setFormData({ ...formData, entity_type: e.target.value })}
            >
              {['Top Management', 'Department', 'Division', 'Unit', 'Branch', 'Office', 'Committee', 'Other'].map(type => (
                <option key={type} value={type}>{t(`orgTypes.${type}`, type)}</option>
              ))}
            </select>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest flex items-center gap-1.5">
              <Info size={12} />
              {t('nameAr')} *
            </label>
            <input 
              type="text"
              required
              className="input-field"
              value={formData.name_ar}
              onChange={(e) => setFormData({ ...formData, name_ar: e.target.value })}
            />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest flex items-center gap-1.5">
              <Info size={12} />
              {t('nameEn')}
            </label>
            <input 
              type="text"
              className="input-field"
              value={formData.name_en}
              onChange={(e) => setFormData({ ...formData, name_en: e.target.value })}
            />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest flex items-center gap-1.5">
              <Building2 size={12} />
              {t('parentUnit')}
            </label>
            <select 
              className="input-field"
              value={formData.parent_id || ''}
              onChange={(e) => setFormData({ ...formData, parent_id: e.target.value || null })}
            >
              <option value="">{t('rootLevel')}</option>
              {departments
                .filter(d => d.id !== editingNode?.id)
                .map(d => (
                  <option key={d.id} value={d.id}>{d.name_ar} ({d.entity_type})</option>
                ))}
            </select>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest flex items-center gap-1.5">
              <User size={12} />
              {t('managerName')}
            </label>
            <input 
              type="text"
              className="input-field"
              value={formData.manager_name}
              onChange={(e) => setFormData({ ...formData, manager_name: e.target.value })}
            />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest flex items-center gap-1.5">
              <MapPin size={12} />
              {t('location')}
            </label>
            <input 
              type="text"
              className="input-field"
              value={formData.location}
              onChange={(e) => setFormData({ ...formData, location: e.target.value })}
            />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest flex items-center gap-1.5">
              <Hash size={12} />
              {t('costCenter')}
            </label>
            <input 
              type="text"
              className="input-field"
              value={formData.cost_center_code}
              onChange={(e) => setFormData({ ...formData, cost_center_code: e.target.value })}
            />
          </div>

          <div className="col-span-1 md:col-span-2 space-y-1">
            <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest flex items-center gap-1.5">
              <Plus size={12} />
              {t('description')}
            </label>
            <textarea 
              className="input-field min-h-[80px]"
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
            />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest flex items-center gap-1.5">
              {t('status')}
            </label>
            <div className="flex items-center gap-4 mt-2">
              <label className="flex items-center gap-2 cursor-pointer">
                <input 
                  type="radio" 
                  name="status" 
                  value="Active" 
                  checked={formData.status === 'Active'}
                  onChange={() => setFormData({ ...formData, status: 'Active' })}
                />
                <span className="text-sm font-bold text-[var(--color-text-main)]">{t('common.active')}</span>
              </label>
              <label className="flex items-center gap-2 cursor-pointer">
                <input 
                  type="radio" 
                  name="status" 
                  value="Inactive" 
                  checked={formData.status === 'Inactive'}
                  onChange={() => setFormData({ ...formData, status: 'Inactive' })}
                />
                <span className="text-sm font-bold text-[var(--color-text-main)]">{t('common.inactive')}</span>
              </label>
            </div>
          </div>
        </div>

        <div className="flex justify-end gap-3 pt-6 border-t">
          <button type="button" onClick={onClose} className="btn-secondary">{t('common.cancel')}</button>
          <button type="submit" disabled={loading} className="btn-primary min-w-[120px]">
            {loading ? <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin mx-auto" /> : (editingNode?.id ? t('update') : t('create'))}
          </button>
        </div>
      </form>
    </Modal>
  );
};

export default OrgStructure;

import React, { useState, useEffect } from 'react';
import api from '../services/api';
import { useTranslation } from 'react-i18next';
import { Recommendation, AuditFinding, AuditPlan } from '../types';
import { Search, TrendingUp, Filter } from 'lucide-react';
import { motion } from 'motion/react';
import { useFormat } from '../services/formatService';
import logger from '../utils/logger';

import Modal from '../components/Modal';
import Badge from '../components/Badge';
import LoadingSpinner from '../components/LoadingSpinner';

const RecommendationsModule: React.FC = () => {
  const { t } = useTranslation();
  const { formatDate, formatNumber } = useFormat();
  const [recommendations, setRecommendations] = useState<Recommendation[]>([]);
  const [findings, setFindings] = useState<AuditFinding[]>([]);
  const [plans, setPlans] = useState<AuditPlan[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  // Filters
  const [filterDepartment, setFilterDepartment] = useState('');
  const [filterPlanId, setFilterPlanId] = useState('');
  const [filterStatus, setFilterStatus] = useState('');
  const [editingRec, setEditingRec] = useState<Recommendation | null>(null);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [recToDelete, setRecToDelete] = useState<string | number | null>(null);

  useEffect(() => {
    fetchAll();
  }, []);

  const fetchAll = async () => {
    try {
      const [recRes, findRes, planRes] = await Promise.all([
        api.get('/recommendations', { params: { pageSize: 200 } }),
        api.get('/audit-findings', { params: { pageSize: 200 } }),
        api.get('/audit-plans'),
      ]);
      setRecommendations(recRes.data?.data || (Array.isArray(recRes.data) ? recRes.data : []));
      setFindings(findRes.data?.data || (Array.isArray(findRes.data) ? findRes.data : []));
      setPlans(planRes.data?.data || (Array.isArray(planRes.data) ? planRes.data : []));
    } catch (err) {
      logger.error('Operation failed', err);
    } finally {
      setLoading(false);
    }
  };

  const initiateDelete = (id: string | number) => {
    setRecToDelete(id);
    setIsDeleteModalOpen(true);
  };

  const confirmDelete = async () => {
    if (!recToDelete) return;
    try {
      await api.delete(`/recommendations/${recToDelete}`);
      fetchAll();
      setIsDeleteModalOpen(false);
      setRecToDelete(null);
    } catch (err) {
      logger.error('Operation failed', err);
    }
  };

  const getFinding = (id: string | number) => findings.find(f => String(f.id) === String(id));
  const getPlan = (id: string | number | undefined) => plans.find(p => String(p.id) === String(id));

  // unique departments from recommendations
  const departments = [...new Set(recommendations.map(r => r.department).filter(Boolean))];
  const statuses = ['Open', 'In Progress', 'Implemented', 'Overdue', 'Closed'];

  const filteredRecs = (recommendations || []).filter(r => {
    const finding = getFinding(r.finding_id);
    const matchSearch = (r.department?.toLowerCase() || '').includes(searchTerm.toLowerCase()) ||
                        (r.responsible?.toLowerCase() || '').includes(searchTerm.toLowerCase()) ||
                        (finding?.title?.toLowerCase() || '').includes(searchTerm.toLowerCase());
    const matchDept = !filterDepartment || r.department === filterDepartment;
    const matchStatus = !filterStatus || r.status === filterStatus;
    const matchPlan = !filterPlanId || String(r.plan_id) === String(filterPlanId) ||
                      String(finding?.audit_id) === String(filterPlanId);
    return matchSearch && matchDept && matchStatus && matchPlan;
  });

  return (
    <div className="space-y-10">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div className="flex items-center gap-6">
          <div className="w-12 h-12 sm:w-16 sm:h-16 bg-[var(--color-primary)] rounded-2xl flex items-center justify-center text-white shadow-lg shadow-[var(--color-primary)]/20">
            <TrendingUp size={32} />
          </div>
          <div>
            <h2 className="text-2xl sm:text-4xl font-bold text-[var(--color-text-main)] tracking-tight">{t('recommendations.title')}</h2>
            <p className="text-sm text-[var(--color-text-muted)] font-bold mt-2">{t('recommendations.trackingManagementActionPlans')}</p>
          </div>
        </div>
        <div className="relative flex-1 min-w-[300px] max-w-md">
          <Search className="absolute start-5 top-1/2 -translate-y-1/2 text-[var(--color-text-muted)]" size={20} />
          <input
            type="text"
            placeholder={t('recommendations.search')}
            className="input-field !ps-14"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      {/* Filters */}
      <div className="glass-card p-6">
        <div className="flex items-center gap-3 mb-4">
          <Filter size={18} className="text-[var(--color-primary)]" />
          <span className="text-sm font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('filters.filters') || 'تصفية'}</span>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          {/* Filter by Plan */}
          <div>
            <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-2 block">{t('filters.byPlan')}</label>
            <select className="input-field" value={filterPlanId} onChange={e => setFilterPlanId(e.target.value)}>
              <option value="">{t('common.all') || 'الكل'}</option>
              {plans.map(p => <option key={p.id} value={p.id}>{p.title}</option>)}
            </select>
          </div>
          {/* Filter by Department */}
          <div>
            <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-2 block">{t('filters.byDepartment')}</label>
            <select className="input-field" value={filterDepartment} onChange={e => setFilterDepartment(e.target.value)}>
              <option value="">{t('common.all') || 'الكل'}</option>
              {departments.map(d => <option key={d} value={d}>{d}</option>)}
            </select>
          </div>
          {/* Filter by Status */}
          <div>
            <label className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-2 block">{t('filters.byStatus')}</label>
            <select className="input-field" value={filterStatus} onChange={e => setFilterStatus(e.target.value)}>
              <option value="">{t('common.all') || 'الكل'}</option>
              {statuses.map(s => {
                const tKey = s === 'In Progress' ? 'common.inProgress'
                           : s === 'Implemented' ? 'common.implemented'
                           : s === 'Overdue' ? 'common.overdue'
                           : s === 'Closed' ? 'common.closed'
                           : 'common.open';
                return <option key={s} value={s}>{t(tKey)}</option>;
              })}
            </select>
          </div>
        </div>
      </div>

      {/* Delete Modal */}
      <Modal
        isOpen={isDeleteModalOpen}
        onClose={() => { setIsDeleteModalOpen(false); setRecToDelete(null); }}
        title={t('recommendations.deleteConfirm')}
      >
        <div className="space-y-6">
          <p className="text-[var(--color-text-main)] font-medium">{t('recommendations.deleteMessage')}</p>
          <div className="flex justify-end gap-4">
            <button onClick={() => { setIsDeleteModalOpen(false); setRecToDelete(null); }}
              className="px-6 py-3 rounded-2xl bg-[var(--color-bg-main)] text-[var(--color-text-main)] font-bold hover:bg-[var(--color-border-soft)] transition-colors border border-[var(--color-border-soft)]">
              {t('common.cancel')}
            </button>
            <button onClick={confirmDelete}
              className="px-6 py-3 rounded-2xl bg-[var(--color-danger)] text-white font-bold hover:bg-[var(--color-danger)]/90 transition-colors shadow-lg shadow-[var(--color-danger)]/20">
              {t('recommendations.delete')}
            </button>
          </div>
        </div>
      </Modal>

      {/* Table */}
      {loading ? (
        <div className="glass-card p-20">
          <LoadingSpinner size="lg" />
          <p className="text-center text-[var(--color-text-muted)] font-bold mt-4 uppercase tracking-widest text-xs">{t('recommendations.loadingRecommendations')}</p>
        </div>
      ) : (
        <div className="glass-card overflow-hidden">
          <div className="overflow-x-auto custom-scrollbar">
            <table className="w-full text-start border-collapse">
              <thead>
                <tr className="bg-[var(--color-bg-main)] border-b border-[var(--color-border-soft)]">
                  <th className="px-8 py-6 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em]">{t('recommendations.id')}</th>
                  <th className="px-8 py-6 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em]">{t('findings.findingTitle')}</th>
                  <th className="px-8 py-6 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em]">{t('recommendations.recommendation')}</th>
                  <th className="px-8 py-6 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em]">{t('common.auditPlan')}</th>
                  <th className="px-8 py-6 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em]">{t('recommendations.department')}</th>
                  <th className="px-8 py-6 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em]">{t('recommendations.responsible')}</th>
                  <th className="px-8 py-6 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em]">{t('recommendations.dueDate')}</th>
                  <th className="px-8 py-6 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em]">{t('recommendations.riskLevel')}</th>
                  <th className="px-8 py-6 text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-[0.2em]">{t('recommendations.status')}</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[var(--color-border-soft)]">
                {filteredRecs.map((rec, idx) => {
                  const finding = getFinding(rec.finding_id);
                  const plan = getPlan(rec.plan_id || finding?.audit_id);
                  return (
                    <motion.tr
                      key={rec.id}
                      initial={{ opacity: 0, y: 10 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ delay: idx * 0.03 }}
                      className="hover:bg-[var(--color-primary)]/5 transition-colors"
                    >
                      <td className="px-8 py-5 text-xs font-bold text-[var(--color-text-muted)] tracking-widest">{rec.rec_number || `#${formatNumber(rec.id)}`}</td>
                      <td className="px-8 py-5 max-w-[180px]">
                        <p className="text-xs font-bold text-[var(--color-text-main)] line-clamp-2">{finding?.title || `#${formatNumber(rec.finding_id)}`}</p>
                      </td>
                      <td className="px-8 py-5 max-w-xs">
                        <p className="text-sm text-[var(--color-text-muted)] line-clamp-2">{finding?.recommendation || '—'}</p>
                      </td>
                      <td className="px-8 py-5 text-xs font-bold text-[var(--color-text-muted)]">{plan?.title || '—'}</td>
                      <td className="px-8 py-5 text-sm font-bold text-[var(--color-text-main)]">{rec.department}</td>
                      <td className="px-8 py-5 text-sm text-[var(--color-text-muted)]">{rec.responsible}</td>
                      <td className="px-8 py-5 text-sm text-[var(--color-text-muted)]">{formatDate(rec.due_date)}</td>
                      <td className="px-8 py-5"><Badge type="risk" value={rec.risk_level} /></td>
                      <td className="px-8 py-5"><Badge type="status" value={rec.status} /></td>
                    </motion.tr>
                  );
                })}
                {filteredRecs.length === 0 && (
                  <tr>
                    <td colSpan={9} className="px-8 py-20 text-center text-[var(--color-text-muted)] font-bold text-sm">
                      {t('recommendations.noRecommendations') || 'لا توجد توصيات'}
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

export default RecommendationsModule;

import React from 'react';
import { FileText, Download, Trash2 } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { AuditReport, ReportType } from '../types';
import { useFormat } from '../../../services/formatService';

interface AuditReportCardProps {
  report: AuditReport;
  reportTypes: ReportType[];
  onDownload: (report: AuditReport) => void;
  onDelete: (id: string | number) => void;
}

const AuditReportCard: React.FC<AuditReportCardProps> = ({
  report,
  reportTypes,
  onDownload,
  onDelete
}) => {
  const { t } = useTranslation();
  const { formatDate } = useFormat();

  return (
    <div className="glass-card p-6 flex flex-col justify-between group hover:border-[var(--color-primary)]/30 transition-all">
      <div>
        <div className="flex items-start justify-between mb-4">
          <div className="w-12 h-12 bg-[var(--color-primary)]/10 rounded-xl flex items-center justify-center text-[var(--color-primary)]">
            <FileText size={24} />
          </div>
          <div className="flex flex-col items-end gap-1">
            <span className="px-3 py-1 bg-[var(--color-bg-main)] rounded-full text-[10px] font-bold uppercase tracking-widest text-[var(--color-text-muted)] border border-[var(--color-border-soft)]">
              {report.status}
            </span>
            {report.report_type && report.report_type !== 'auditReport' && (
              <span className="px-2 py-0.5 bg-[var(--color-primary)]/10 rounded-full text-[8px] font-bold text-[var(--color-primary)] uppercase tracking-tighter">
                {reportTypes.find(rt => rt.id === report.report_type)?.label}
              </span>
            )}
          </div>
        </div>
        <h3 className="text-lg font-bold text-[var(--color-text-main)] mb-2 line-clamp-2">{report.title}</h3>
        <p className="text-xs text-[var(--color-text-muted)] font-bold uppercase tracking-wider mb-4">
          {formatDate(report.date_generated)} • {report.generated_by}
        </p>
      </div>
      
      <div className="flex items-center gap-2 mt-4 pt-4 border-t border-[var(--color-border-soft)]">
        <button 
          onClick={() => onDownload(report)}
          className="flex-1 py-2 bg-[var(--color-bg-main)] hover:bg-[var(--color-border-soft)] rounded-xl text-[var(--color-text-main)] text-xs font-bold uppercase tracking-wider flex items-center justify-center gap-2 transition-colors border border-[var(--color-border-soft)]"
        >
          <Download size={16} />
          {t('common.download')}
        </button>
        <button 
          onClick={() => onDelete(report.id!)}
          className="p-2 text-[var(--color-danger)] hover:bg-[var(--color-danger)]/10 rounded-xl transition-colors"
        >
          <Trash2 size={18} />
        </button>
      </div>
    </div>
  );
};

