import React from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend } from 'recharts';
import { useTranslation } from 'react-i18next';
import ChartContainer from '../../components/ChartContainer';
import { BarChart as BarChartIcon, Activity } from 'lucide-react';

interface AnalyticsData {
  severity: string;
  count: number;
  date: string;
}

interface Props {
  data: AnalyticsData[];
}

const SystemErrorAnalytics: React.FC<Props> = ({ data }) => {
  const { t } = useTranslation();

  const chartData = data.reduce((acc: any, curr) => {
    const existing = acc.find((item: any) => item.date === curr.date);
    if (existing) {
      existing[curr.severity] = curr.count;
    } else {
      acc.push({ date: curr.date, [curr.severity]: curr.count });
    }
    return acc;
  }, []);

  return (
    <div className="bg-[var(--color-card)] p-8 rounded-2xl border border-[var(--color-border-soft)] shadow-sm flex flex-col group transition-all hover:shadow-xl hover:shadow-[var(--color-border-soft)]/50">
      <div className="flex items-center gap-3 mb-8">
        <div className="w-10 h-10 rounded-xl bg-[var(--color-bg-soft)] flex items-center justify-center text-[var(--color-text-muted)] group-hover:text-[var(--color-primary)] transition-colors">
          <BarChartIcon size={20} />
        </div>
        <h2 className="text-xl font-bold text-[var(--color-text-main)] tracking-tight">{t('systemErrorLogs.errorTrends')}</h2>
      </div>
      
      {data.length > 0 ? (
        <div className="flex-1 min-h-[250px] w-full">
          <ChartContainer debugName="SystemErrorAnalyticsChart" minHeight={250}>
            {(width, height) => (
              <BarChart width={width} height={height} data={chartData} margin={{ top: 0, right: 0, left: -20, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis 
                  dataKey="date" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fill: '#94a3b8', fontSize: 10, fontWeight: 700 }}
                />
                <YAxis 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fill: '#94a3b8', fontSize: 10, fontWeight: 700 }}
                />
                <Tooltip 
                  contentStyle={{ borderRadius: '1rem', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontWeight: 'bold' }}
                />
                <Legend iconType="circle" wrapperStyle={{ paddingTop: '20px', fontWeight: 'bold', fontSize: '12px' }} />
                <Bar radius={[4, 4, 0, 0]} dataKey="error" fill="#ef4444" name={t('systemErrorLogs.error')} />
                <Bar radius={[4, 4, 0, 0]} dataKey="warning" fill="#f59e0b" name={t('systemErrorLogs.warning')} />
                <Bar radius={[4, 4, 0, 0]} dataKey="info" fill="#3b82f6" name={t('systemErrorLogs.info')} />
              </BarChart>
            )}
          </ChartContainer>
        </div>
      ) : (
        <div className="flex flex-col items-center justify-center py-20 text-[var(--color-border-strong)] font-bold border-2 border-dashed border-slate-50 rounded-3xl">
          <Activity size={48} className="mb-4 opacity-20" />
          {t('systemErrorLogs.noAnalyticsData')}
        </div>
      )}
    </div>
  );
};

export default SystemErrorAnalytics;

import React, { useState, useEffect } from 'react';
import api from '../../services/api';
import { AlertCircle, RefreshCw, Trash2, Download, ChevronDown, ChevronUp, ShieldAlert } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { useFormat } from '../../services/formatService';
import Pagination from '../../components/Pagination';
import Modal from '../../components/Modal';
import SystemErrorAnalytics from './SystemErrorAnalytics';
import logger from '../../utils/logger';

interface SystemError {
  id: number;
  message: string;
  stack: string;
  module: string;
  timestamp: string;
  severity?: 'error' | 'warning' | 'info';
}

const SystemErrorLogs: React.FC = () => {
  const { t, i18n } = useTranslation();
  const { formatDate } = useFormat();
  const [logs, setLogs] = useState<SystemError[]>([]);
  const [analytics, setAnalytics] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [isClearModalOpen, setIsClearModalOpen] = useState(false);
  const [isClearing, setIsClearing] = useState(false);
  const [moduleFilter, setModuleFilter] = useState('');
  const [userIdFilter, setUserIdFilter] = useState('');
  const [severityFilter, setSeverityFilter] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [pagination, setPagination] = useState({ page: 1, pageSize: 20, total: 0, totalPages: 0 });
  const [expandedRows, setExpandedRows] = useState<number[]>([]);

  const toggleRow = (id: number) => {
    setExpandedRows(prev => prev.includes(id) ? prev.filter(rowId => rowId !== id) : [...prev, id]);
  };

  const fetchLogs = async () => {
    try {
      setLoading(true);
      const response = await api.get('/system-errors', {
        params: {
          page: pagination.page,
          pageSize: pagination.pageSize,
          module: moduleFilter || undefined,
          user_id: userIdFilter || undefined,
          severity: severityFilter || undefined,
          start_date: startDate || undefined,
          end_date: endDate || undefined
        }
      });
      if (response.data.data) {
        setLogs(response.data.data);
        setPagination(prev => ({
          ...prev,
          total: response.data.pagination?.total ?? response.data.data.length,
          totalPages: response.data.pagination?.totalPages ?? 1
        }));
      } else {
        setLogs(response.data);
      }
    } catch (error) {
      logger.error('Error fetching logs:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchAnalytics = async () => {
    try {
      const response = await api.get('/system-errors/analytics');
      setAnalytics(response.data);
    } catch (error) {
      logger.error('Error fetching analytics:', error);
    }
  };

  const handleClearLogs = async () => {
    try {
      setIsClearing(true);
      await api.delete('/system-errors');
      await Promise.all([fetchLogs(), fetchAnalytics()]);
      setIsClearModalOpen(false);
    } catch (error) {
      logger.error('Error clearing logs:', error);
    } finally {
      setIsClearing(false);
    }
  };

  const exportLogs = async () => {
    try {
      const response = await api.get('/system-errors/export', { responseType: 'blob' });
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `system-errors-${new Date().toISOString().slice(0, 10)}.csv`);
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      logger.error('Error exporting logs:', error);
    }
  };

  const fetchLogsRef = React.useRef(fetchLogs);
  const fetchAnalyticsRef = React.useRef(fetchAnalytics);

  useEffect(() => {
    fetchLogsRef.current = fetchLogs;
    fetchAnalyticsRef.current = fetchAnalytics;
  });

  useEffect(() => {
    fetchLogs();
    fetchAnalytics();
  }, [pagination.page, pagination.pageSize, moduleFilter, userIdFilter, severityFilter, startDate, endDate]);

  useEffect(() => {
    let ws: WebSocket;
    let reconnectTimeout: NodeJS.Timeout;
    let reconnectAttempts = 0;
    let isComponentMounted = true;

    const connect = async () => {
      if (!isComponentMounted) return;
      
      try {
        // Fetch a short-lived WebSocket token from the server
        const res = await api.get('/auth/ws-token');
        const wsToken = res.data?.token;
        if (!wsToken) return;

        const protocol = window.location.protocol === 'https:' ? 'wss' : 'ws';
        ws = new WebSocket(`${protocol}://${window.location.host}?token=${wsToken}`);
        
        ws.onopen = () => {
          reconnectAttempts = 0;
        };

        ws.onmessage = (event) => {
          try {
            const data = JSON.parse(event.data);
            if (data.type === 'NEW_SYSTEM_ERROR') {
              fetchLogsRef.current();
              fetchAnalyticsRef.current();
            }
          } catch (e) {
            // Ignore parse errors
          }
        };

        ws.onclose = () => {
          if (isComponentMounted) {
            const delay = Math.min(5000 * Math.pow(2, reconnectAttempts), 30000);
            reconnectTimeout = setTimeout(connect, delay);
            reconnectAttempts++;
          }
        };

        ws.onerror = () => {
          // Error handled by onclose
        };
      } catch (e) {
        // Token fetch failed - retry with backoff
        if (isComponentMounted) {
          const delay = Math.min(5000 * Math.pow(2, reconnectAttempts), 30000);
          reconnectTimeout = setTimeout(connect, delay);
          reconnectAttempts++;
        }
      }
    };

    connect();

    return () => {
      isComponentMounted = false;
      clearTimeout(reconnectTimeout);
      if (ws) {
        ws.onclose = null; // Prevent reconnect on unmount
        try {
          if (ws.readyState === WebSocket.OPEN || ws.readyState === WebSocket.CONNECTING) {
            ws.close();
          }
        } catch (e) {
          // Ignore close errors
        }
      }
    };
  }, []); // Empty dependencies!

  const getSeverityColor = (severity?: string) => {
    switch (severity) {
      case 'warning': return 'text-yellow-600 bg-yellow-100';
      case 'info': return 'text-blue-600 bg-blue-100';
      default: return 'text-red-600 bg-red-100';
    }
  };

  return (
    <div className="min-h-screen bg-[var(--color-bg-soft)]/50 p-6 space-y-10" dir={i18n.language === 'ar' ? 'rtl' : 'ltr'}>
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div className="flex items-center gap-6">
          <div className="w-12 h-12 sm:w-16 sm:h-16 bg-[var(--color-primary)] rounded-2xl flex items-center justify-center text-white shadow-lg shadow-[var(--color-primary)]/20">
            <AlertCircle size={32} />
          </div>
          <div>
            <h1 className="text-2xl sm:text-4xl font-bold text-[var(--color-text-main)] tracking-tight">{t('systemErrorLogs.title')}</h1>
            <p className="text-sm text-[var(--color-text-muted)] font-bold mt-2">{t('common.stayUpdated')}</p>
          </div>
        </div>
        <div className="flex gap-2">
          <button onClick={fetchLogs} title={t('common.refresh')} className="p-3 bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-2xl hover:bg-[var(--color-bg-main)] transition-colors shadow-sm">
            <RefreshCw size={20} className="text-[var(--color-text-muted)]" />
          </button>
          <button onClick={exportLogs} title={t('common.export')} className="p-3 bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-2xl hover:bg-[var(--color-bg-main)] transition-colors shadow-sm">
            <Download size={20} className="text-[var(--color-text-muted)]" />
          </button>
          <button onClick={() => setIsClearModalOpen(true)} title={t('common.clear')} className="p-3 bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-2xl hover:bg-[var(--color-bg-main)] transition-colors text-rose-500 shadow-sm">
            <Trash2 size={20} />
          </button>
        </div>
      </div>

      {/* Confirmation Modal */}
      <Modal 
        isOpen={isClearModalOpen} 
        onClose={() => !isClearing && setIsClearModalOpen(false)}
        title={t('systemErrorLogs.confirmClearLogs')}
      >
        <div className="p-6 text-center">
          <div className="w-16 h-16 bg-rose-50 text-rose-500 rounded-full flex items-center justify-center mx-auto mb-4">
            <ShieldAlert size={32} />
          </div>
          <h3 className="text-xl font-bold text-[var(--color-text-main)] mb-2">{t('systemErrorLogs.importantAlert')}</h3>
          <p className="text-[var(--color-text-muted)] font-bold mb-8 leading-relaxed">
            {t('systemErrorLogs.clearLogsWarning')}
          </p>
          <div className="grid grid-cols-2 gap-3">
            <button
              onClick={() => setIsClearModalOpen(false)}
