              className="px-6 py-3 rounded-xl font-bold text-[var(--color-text-muted)] hover:bg-[var(--color-bg-soft)] transition-colors border border-[var(--color-border-soft)]"
            >
              {t('common.cancel')}
            </button>
            <button
              onClick={handleClearLogs}
              disabled={isClearing}
              className="px-6 py-3 rounded-xl font-bold bg-rose-500 text-white hover:bg-rose-600 transition-colors shadow-lg shadow-rose-500/20 disabled:opacity-50 flex items-center justify-center gap-2"
            >
              {isClearing ? (
                <>
                  <RefreshCw size={18} className="animate-spin" />
                  {t('systemErrorLogs.clearing')}
                </>
              ) : (
                t('systemErrorLogs.confirmDelete')
              )}
            </button>
          </div>
        </div>
      </Modal>

      {/* Search & Filters Section */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4 p-6 bg-[var(--color-bg-main)]/50 rounded-2xl border border-[var(--color-border-soft)]/50 shadow-inner">
        <div className="relative group">
          <input 
            type="text" 
            placeholder={t('systemErrorLogs.filterByModule')} 
            value={moduleFilter} 
            onChange={(e) => setModuleFilter(e.target.value)} 
            className="w-full p-3.5 bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-2xl text-sm font-bold text-[var(--color-text-main)] focus:ring-2 focus:ring-[var(--color-primary)]/20 focus:border-[var(--color-primary)] transition-all outline-none" 
          />
        </div>
        
        <input 
          type="text" 
          placeholder={t('systemErrorLogs.filterByUserId')} 
          value={userIdFilter} 
          onChange={(e) => setUserIdFilter(e.target.value)} 
          className="w-full p-3.5 bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-2xl text-sm font-bold text-[var(--color-text-main)] focus:ring-2 focus:ring-[var(--color-primary)]/20 focus:border-[var(--color-primary)] transition-all outline-none" 
        />
        
        <select 
          value={severityFilter} 
          onChange={(e) => setSeverityFilter(e.target.value)} 
          className="w-full p-3.5 bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-2xl text-sm font-bold text-[var(--color-text-main)] focus:ring-2 focus:ring-[var(--color-primary)]/20 outline-none cursor-pointer"
        >
          <option value="">{t('systemErrorLogs.allSeverities')}</option>
          <option value="error">{t('systemErrorLogs.error')}</option>
          <option value="warning">{t('systemErrorLogs.warning')}</option>
          <option value="info">{t('systemErrorLogs.info')}</option>
        </select>

        <div className="relative">
          <input 
            type="date" 
            value={startDate} 
            onChange={(e) => setStartDate(e.target.value)} 
            className="w-full p-3.5 bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-2xl text-sm font-bold text-[var(--color-text-main)] outline-none" 
          />
        </div>

        <div className="relative">
          <input 
            type="date" 
            value={endDate} 
            onChange={(e) => setEndDate(e.target.value)} 
            className="w-full p-3.5 bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-2xl text-sm font-bold text-[var(--color-text-main)] outline-none" 
          />
        </div>
      </div>
      
      <SystemErrorAnalytics data={analytics} />
      
      <div className="bg-[var(--color-card)] border border-[var(--color-border-soft)] shadow-sm rounded-2xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full border-collapse">
            <thead>
              <tr className="border-b border-slate-50">
                <th className="px-8 py-6 text-start text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('common.time')}</th>
                <th className="px-8 py-6 text-start text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('common.module')}</th>
                <th className="px-8 py-6 text-start text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('systemErrorLogs.severity')}</th>
                <th className="px-8 py-6 text-start text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('common.message')}</th>
                <th className="px-8 py-6 text-start"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[var(--color-border-soft)]/50">
              {loading ? (
                <tr>
                  <td colSpan={5} className="px-8 py-20 text-center">
                    <RefreshCw className="animate-spin text-[var(--color-primary)] mx-auto mb-4" size={32} />
                    <p className="text-[var(--color-text-muted)] font-bold">{t('common.loading')}</p>
                  </td>
                </tr>
              ) : (Array.isArray(logs) ? logs : []).length === 0 ? (
                <tr>
                  <td colSpan={5} className="px-8 py-20 text-center">
                    <AlertCircle className="text-slate-200 mx-auto mb-4" size={48} />
                    <p className="text-[var(--color-text-muted)] font-bold">{t('systemErrorLogs.noErrorsLogged')}</p>
                  </td>
                </tr>
              ) : (Array.isArray(logs) ? logs : []).map(log => (
                <React.Fragment key={log.id}>
                  <tr 
                    className="hover:bg-[var(--color-bg-soft)]/50 cursor-pointer transition-all duration-200 group" 
                    onClick={() => toggleRow(log.id)}
                  >
                    <td className="px-8 py-5 text-sm font-bold text-[var(--color-text-muted)] font-mono">{formatDate(log.timestamp)}</td>
                    <td className="px-8 py-5">
                      <span className="px-3 py-1 bg-[var(--color-bg-main)] text-[var(--color-text-muted)] rounded-lg text-[10px] font-bold uppercase tracking-wider">
                        {log.module}
                      </span>
                    </td>
                    <td className="px-8 py-5">
                      <span className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider ${getSeverityColor(log.severity)}`}>
                        {t(`systemErrorLogs.${log.severity || 'error'}`)}
                      </span>
                    </td>
                    <td className="px-8 py-5">
                      <span className="text-sm font-bold text-[var(--color-text-main)] line-clamp-1 group-hover:text-rose-600 transition-colors">{log.message}</span>
                    </td>
                    <td className="px-8 py-5 text-[var(--color-text-muted)] group-hover:text-[var(--color-text-muted)]">
                      {expandedRows.includes(log.id) ? <ChevronUp size={18} /> : <ChevronDown size={18} />}
                    </td>
                  </tr>
                  {expandedRows.includes(log.id) && (
                    <tr className="bg-[var(--color-bg-soft)]/30">
                      <td colSpan={5} className="px-8 py-6">
                        <div className="bg-[var(--color-card)] p-6 rounded-2xl border border-[var(--color-border-soft)] shadow-sm space-y-6">
                          {log.stack && (
                            <div className="flex flex-col gap-2">
                              <h4 className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('systemErrorLogs.stackTrace')}</h4>
                              <div className="relative group">
                                <pre className="text-xs font-mono text-[var(--color-text-muted)] bg-slate-900/95 p-6 rounded-2xl overflow-x-auto leading-relaxed border-l-4 border-rose-500">
                                  {log.stack}
                                </pre>
                              </div>
                            </div>
                          )}
                          {!log.stack && (
                            <p className="text-sm text-[var(--color-text-muted)] italic">{t('systemErrorLogs.noStackTrace')}</p>
                          )}
                        </div>
                      </td>
                    </tr>
                  )}
                </React.Fragment>
              ))}
            </tbody>
          </table>
        </div>

        <div className="p-8 border-t border-slate-50 bg-[var(--color-bg-soft)]/20">
          <Pagination 
            currentPage={pagination.page}
            totalPages={pagination.totalPages}
            onPageChange={(page) => setPagination(prev => ({ ...prev, page }))}
            pageSize={pagination.pageSize}
            onPageSizeChange={(pageSize) => setPagination(prev => ({ ...prev, pageSize, page: 1 }))}
            totalItems={pagination.total}
          />
        </div>
      </div>
    </div>
  );
};

export default SystemErrorLogs;

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, screen, waitFor, act } from '@testing-library/react';
import fc from 'fast-check';
import React from 'react';
import SystemLogsManagement from './SystemLogsManagement';

/**
 * Bug Condition Exploration Test - Hardcoded Health Percentage
 * 
 * **Validates: Requirements 1.1, 1.2, 1.3, 1.4**
 * 
 * This test encodes the EXPECTED (correct) behavior:
 * - Health percentage should be dynamically calculated as (totalAudit / (totalAudit + totalErrors)) * 100
 * - Color should change based on thresholds: emerald-500 (>=90%), amber-500 (>=70%), rose-500 (<70%)
 * - Status should change based on thresholds: "stable" (>=90%), "degraded" (>=70%), "critical" (<70%)
 * - Error count should use pagination.total, not array length
 * 
 * EXPECTED OUTCOME: Test FAILS on unfixed code (proves the bug exists)
 */

// Mock the API module
vi.mock('../services/api', () => ({
  default: {
    get: vi.fn(),
  },
}));

import api from '../services/api';
const mockedApi = vi.mocked(api);

// Helper to create mock API responses
function createMockAuditResponse(totalItems: number, paginationTotal?: number) {
  const today = new Date().toISOString().split('T')[0];
  const data = Array.from({ length: Math.min(totalItems, 50) }, (_, i) => ({
    id: i + 1,
    action: `action_${i}`,
    timestamp: `${today}T10:00:00Z`,
    user: 'test-user',
  }));

  return {
    data: {
      data,
      pagination: {
        page: 1,
        pageSize: 50,
        total: paginationTotal ?? totalItems,
        totalPages: Math.ceil((paginationTotal ?? totalItems) / 50),
      },
    },
  };
}

function createMockErrorsResponse(itemsInPage: number, paginationTotal?: number) {
  const data = Array.from({ length: itemsInPage }, (_, i) => ({
    id: i + 1,
    message: `Error ${i}`,
    timestamp: new Date().toISOString(),
    severity: 'error',
  }));

  return {
    data: {
      data,
      pagination: {
        page: 1,
        pageSize: 50,
        total: paginationTotal ?? itemsInPage,
        totalPages: Math.ceil((paginationTotal ?? itemsInPage) / 50),
      },
    },
  };
}

// Helper to determine expected color based on health percentage
function getExpectedColor(health: number): string {
  if (health >= 90) return 'text-emerald-500';
  if (health >= 70) return 'text-amber-500';
  return 'text-rose-500';
}

// Helper to determine expected status based on health percentage
function getExpectedStatus(health: number): string {
  if (health >= 90) return 'systemLogsManagement.stable';
  if (health >= 70) return 'systemLogsManagement.degraded';
  return 'systemLogsManagement.critical';
}

describe('Bug Condition Exploration: Hardcoded Health Percentage', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('Test Case 1: 50 audit actions and 50 errors → health 50.0% with rose-500 and "critical"', async () => {
    // Mock API: 50 audit actions, 50 errors → health = 50/(50+50)*100 = 50%
    mockedApi.get.mockImplementation((url: string) => {
      if (url === '/audit-trail') {
        return Promise.resolve(createMockAuditResponse(50, 50));
      }
      if (url === '/system-errors') {
        return Promise.resolve(createMockErrorsResponse(50, 50));
      }
      return Promise.reject(new Error('Unknown URL'));
    });

    render(<SystemLogsManagement />);

    await waitFor(() => {
      expect(mockedApi.get).toHaveBeenCalledWith('/audit-trail');
      expect(mockedApi.get).toHaveBeenCalledWith('/system-errors');
    });

    // Wait for state update after API calls resolve
    await waitFor(() => {
      // Expected: health = 50.0% with rose-500 color and "critical" status
      const healthElement = screen.getByText('50.0%');
      expect(healthElement).toBeInTheDocument();
      expect(healthElement).toHaveClass('text-rose-500');
    });

    // Verify status text shows "critical"
    expect(screen.getByText('systemLogsManagement.critical')).toBeInTheDocument();
  });

  it('Test Case 2: 80 audit actions and 20 errors → health 80.0% with amber-500 and "degraded"', async () => {
    // Mock API: 80 audit actions, 20 errors → health = 80/(80+20)*100 = 80%
    mockedApi.get.mockImplementation((url: string) => {
      if (url === '/audit-trail') {
        return Promise.resolve(createMockAuditResponse(50, 80));
      }
      if (url === '/system-errors') {
        return Promise.resolve(createMockErrorsResponse(20, 20));
      }
      return Promise.reject(new Error('Unknown URL'));
    });

    render(<SystemLogsManagement />);

    await waitFor(() => {
      expect(mockedApi.get).toHaveBeenCalledWith('/audit-trail');
      expect(mockedApi.get).toHaveBeenCalledWith('/system-errors');
    });

    await waitFor(() => {
      // Expected: health = 80.0% with amber-500 color and "degraded" status
      const healthElement = screen.getByText('80.0%');
      expect(healthElement).toBeInTheDocument();
      expect(healthElement).toHaveClass('text-amber-500');
    });

    expect(screen.getByText('systemLogsManagement.degraded')).toBeInTheDocument();
  });

  it('Test Case 3: 50 items in data array but pagination.total = 200 → errorsCount displays 200', async () => {
    // Mock API: 50 items in page but total is 200
    mockedApi.get.mockImplementation((url: string) => {
      if (url === '/audit-trail') {
        return Promise.resolve(createMockAuditResponse(50, 100));
      }
      if (url === '/system-errors') {
        // 50 items in the data array, but pagination.total = 200
        return Promise.resolve(createMockErrorsResponse(50, 200));
      }
      return Promise.reject(new Error('Unknown URL'));
    });

    render(<SystemLogsManagement />);

    await waitFor(() => {
      expect(mockedApi.get).toHaveBeenCalledWith('/audit-trail');
      expect(mockedApi.get).toHaveBeenCalledWith('/system-errors');
    });

    await waitFor(() => {
      // Expected: errorsCount should display 200 (pagination.total), not 50 (array length)
      const errorCountElement = screen.getByText(/200/);
      expect(errorCountElement).toBeInTheDocument();
    });
  });

  it('Test Case 4: 0 audit actions and 0 errors → health defaults to 100% with emerald-500 and "stable"', async () => {
    // Mock API: 0 audit actions, 0 errors → health should default to 100%
    mockedApi.get.mockImplementation((url: string) => {
      if (url === '/audit-trail') {
        return Promise.resolve(createMockAuditResponse(0, 0));
      }
      if (url === '/system-errors') {
        return Promise.resolve(createMockErrorsResponse(0, 0));
      }
      return Promise.reject(new Error('Unknown URL'));
    });

    render(<SystemLogsManagement />);

    await waitFor(() => {
      expect(mockedApi.get).toHaveBeenCalledWith('/audit-trail');
      expect(mockedApi.get).toHaveBeenCalledWith('/system-errors');
    });

    await waitFor(() => {
      // Expected: health = 100.0% with emerald-500 color and "stable" status
      const healthElement = screen.getByText('100.0%');
      expect(healthElement).toBeInTheDocument();
      expect(healthElement).toHaveClass('text-emerald-500');
    });

    expect(screen.getByText('systemLogsManagement.stable')).toBeInTheDocument();
  });

  it('Property: for all (totalAudit, totalErrors) pairs, health = (totalAudit / (totalAudit + totalErrors)) * 100 with correct color and status', async () => {
    /**
     * **Validates: Requirements 1.1, 1.2, 1.3, 1.4**
     * 
     * Property-based test: for any valid pair of (totalAudit, totalErrors),
     * the component should display the dynamically calculated health percentage
     * with the correct color and status text based on thresholds.
     */
    await fc.assert(
      fc.asyncProperty(
        fc.integer({ min: 0, max: 1000 }),
        fc.integer({ min: 0, max: 1000 }),
        async (totalAudit, totalErrors) => {
          // Skip the case where both are 0 (handled separately in test case 4)
          fc.pre(totalAudit + totalErrors > 0);

          vi.clearAllMocks();

          mockedApi.get.mockImplementation((url: string) => {
            if (url === '/audit-trail') {
              return Promise.resolve(createMockAuditResponse(Math.min(totalAudit, 50), totalAudit));
            }
            if (url === '/system-errors') {
              return Promise.resolve(createMockErrorsResponse(Math.min(totalErrors, 50), totalErrors));
            }
            return Promise.reject(new Error('Unknown URL'));
          });

          const { unmount } = render(<SystemLogsManagement />);

          const expectedHealth = (totalAudit / (totalAudit + totalErrors)) * 100;
          const expectedHealthStr = `${expectedHealth.toFixed(1)}%`;
          const expectedColor = getExpectedColor(expectedHealth);

          await waitFor(() => {
            const healthElement = screen.getByText(expectedHealthStr);
            expect(healthElement).toBeInTheDocument();
            expect(healthElement).toHaveClass(expectedColor);
          });

          unmount();
        }
      ),
      { numRuns: 20 } // Limited runs for exploration
    );
  });
});


/**
 * Preservation Property Tests - Non-Health Display Behavior
 * 
 * **Validates: Requirements 3.1, 3.2, 3.3, 3.4, 3.5**
 * 
 * These tests verify behaviors that MUST remain unchanged after the fix:
 * - Today's audit count calculation (filtering by today's date)
 * - Loading state transitions (true during fetch, false after)
 * - Error handling (API failures logged, no crash)
 * - Concurrent fetching (both endpoints called via Promise.all)
 * - Zero errors with audit actions → health displays green/stable
 * 
 * EXPECTED OUTCOME: Tests PASS on unfixed code (confirms baseline behavior to preserve)
 */
describe('Preservation Property: Non-Health Display Behavior', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  /**
   * **Validates: Requirements 3.1**
   * 
   * Property: For all non-buggy inputs (zero errors with some audit actions),
   * the unfixed code shows health as "99.9%" with emerald-500 and "stable".
   * After the fix, this should show ~100% with emerald-500 and "stable".
   * On unfixed code, we verify the hardcoded "99.9%" still renders correctly
   * with green color and stable status when zero errors exist.
   */
  it('Property: for all non-buggy inputs (zero errors with some audit actions), health displays emerald-500 and "stable"', async () => {
    await fc.assert(
      fc.asyncProperty(
        fc.integer({ min: 1, max: 500 }), // at least 1 audit action
        async (totalAudit) => {
          vi.clearAllMocks();

          const today = new Date().toISOString().split('T')[0];
          const auditData = Array.from({ length: Math.min(totalAudit, 50) }, (_, i) => ({
            id: i + 1,
            action: `action_${i}`,
            timestamp: `${today}T10:00:00Z`,
            user: 'test-user',
          }));

          mockedApi.get.mockImplementation((url: string) => {
            if (url === '/audit-trail') {
              return Promise.resolve({
                data: {
                  data: auditData,
                  pagination: { page: 1, pageSize: 50, total: totalAudit, totalPages: Math.ceil(totalAudit / 50) },
                },
              });
            }
            if (url === '/system-errors') {
              // Zero errors
              return Promise.resolve({
                data: {
                  data: [],
                  pagination: { page: 1, pageSize: 50, total: 0, totalPages: 0 },
                },
              });
            }
            return Promise.reject(new Error('Unknown URL'));
          });

          const { unmount } = render(<SystemLogsManagement />);

          await waitFor(() => {
            expect(mockedApi.get).toHaveBeenCalledWith('/audit-trail');
            expect(mockedApi.get).toHaveBeenCalledWith('/system-errors');
          });

          // On unfixed code: hardcoded "99.9%" with emerald-500 and "stable"
          // On fixed code: should show ~100% with emerald-500 and "stable"
          // Both cases: emerald-500 color and "stable" status when zero errors
          await waitFor(() => {
            // The health element should have emerald-500 class
            const healthSpan = screen.getByText(/99\.9%|100\.0%/);
            expect(healthSpan).toBeInTheDocument();
            expect(healthSpan).toHaveClass('text-emerald-500');
          });

          // Status should be "stable"
          expect(screen.getByText('systemLogsManagement.stable')).toBeInTheDocument();

          unmount();
        }
      ),
      { numRuns: 15 }
    );
  });

  /**
   * **Validates: Requirements 3.5**
   * 
   * Property: For all API responses, today's audit count equals the count
   * of audit entries with today's date in the data array.
   */
  it('Property: for all API responses, today\'s audit count equals count of audit entries with today\'s date', async () => {
    await fc.assert(
      fc.asyncProperty(
        fc.integer({ min: 0, max: 30 }), // items with today's date
        fc.integer({ min: 0, max: 20 }), // items with yesterday's date
        async (todayCount, yesterdayCount) => {
          vi.clearAllMocks();

          const today = new Date().toISOString().split('T')[0];
          const yesterday = new Date(Date.now() - 86400000).toISOString().split('T')[0];

          const auditData = [
            ...Array.from({ length: todayCount }, (_, i) => ({
              id: i + 1,
              action: `today_action_${i}`,
              timestamp: `${today}T${String(10 + (i % 12)).padStart(2, '0')}:00:00Z`,
              user: 'test-user',
            })),
            ...Array.from({ length: yesterdayCount }, (_, i) => ({
              id: todayCount + i + 1,
              action: `yesterday_action_${i}`,
              timestamp: `${yesterday}T10:00:00Z`,
              user: 'test-user',
            })),
          ];

          mockedApi.get.mockImplementation((url: string) => {
            if (url === '/audit-trail') {
              return Promise.resolve({
                data: {
                  data: auditData,
                  pagination: { page: 1, pageSize: 50, total: auditData.length, totalPages: 1 },
                },
              });
            }
            if (url === '/system-errors') {
              return Promise.resolve({
                data: {
                  data: [],
                  pagination: { page: 1, pageSize: 50, total: 0, totalPages: 0 },
                },
              });
            }
            return Promise.reject(new Error('Unknown URL'));
          });

          const { unmount } = render(<SystemLogsManagement />);

          await waitFor(() => {
            expect(mockedApi.get).toHaveBeenCalledWith('/audit-trail');
          });

          // Today's audit count should equal the number of items with today's date
          await waitFor(() => {
            const expectedText = `${todayCount} systemLogsManagement.actions`;
            expect(screen.getByText(expectedText)).toBeInTheDocument();
          });

          unmount();
        }
      ),
      { numRuns: 20 }
    );
  });

  /**
   * **Validates: Requirements 3.3**
   * 
   * Property: For all API call states, loading flag transitions correctly
   * (true during fetch, false after completion).
   */
  it('Property: for all API call states, loading flag transitions correctly (true during fetch, false after)', async () => {
    await fc.assert(
      fc.asyncProperty(
        fc.integer({ min: 0, max: 100 }),
        fc.integer({ min: 0, max: 100 }),
        async (auditCount, errorsCount) => {
          vi.clearAllMocks();

          let resolveAudit: (value: any) => void;
          let resolveErrors: (value: any) => void;

          const auditPromise = new Promise((resolve) => { resolveAudit = resolve; });
          const errorsPromise = new Promise((resolve) => { resolveErrors = resolve; });

          mockedApi.get.mockImplementation((url: string) => {
            if (url === '/audit-trail') return auditPromise;
            if (url === '/system-errors') return errorsPromise;
            return Promise.reject(new Error('Unknown URL'));
          });

          const { unmount } = render(<SystemLogsManagement />);

          // API calls should have been initiated
          await waitFor(() => {
            expect(mockedApi.get).toHaveBeenCalledWith('/audit-trail');
            expect(mockedApi.get).toHaveBeenCalledWith('/system-errors');
          });

          // Now resolve both promises
          const today = new Date().toISOString().split('T')[0];
          await act(async () => {
            resolveAudit!({
              data: {
                data: Array.from({ length: Math.min(auditCount, 50) }, (_, i) => ({
                  id: i + 1, action: `a_${i}`, timestamp: `${today}T10:00:00Z`, user: 'u',
                })),
                pagination: { page: 1, pageSize: 50, total: auditCount, totalPages: 1 },
              },
            });
            resolveErrors!({
              data: {
                data: Array.from({ length: Math.min(errorsCount, 50) }, (_, i) => ({
                  id: i + 1, message: `e_${i}`, timestamp: new Date().toISOString(), severity: 'error',
                })),
                pagination: { page: 1, pageSize: 50, total: errorsCount, totalPages: 1 },
              },
            });
          });

          // After resolution, component should render stats (loading is false)
          await waitFor(() => {
            // The stats section renders audit count - this proves loading completed
            expect(screen.getByText(/systemLogsManagement.actions/)).toBeInTheDocument();
          });

          unmount();
        }
      ),
      { numRuns: 10 }
    );
  });

  /**
   * **Validates: Requirements 3.4**
   * 
   * Property: For all API failure scenarios, error is logged to console
   * and component does not crash.
   */
  it('Property: for all API failure scenarios, error is logged and component does not crash', async () => {
    await fc.assert(
      fc.asyncProperty(
        fc.constantFrom('network', 'timeout', 'server', '500', '403', '404'),
        async (errorType) => {
          vi.clearAllMocks();
          const consoleSpy = vi.spyOn(console, 'error').mockImplementation(() => {});

          const error = new Error(`API ${errorType} error`);

          mockedApi.get.mockImplementation((_url: string) => {
            return Promise.reject(error);
          });

          // Component should NOT throw/crash
          const { unmount } = render(<SystemLogsManagement />);

          await waitFor(() => {
            expect(mockedApi.get).toHaveBeenCalled();
          });

          // Wait for the error to be caught and logged
          // logger.error prepends [ERROR] prefix to messages
          await waitFor(() => {
            expect(consoleSpy).toHaveBeenCalledWith('[ERROR] Error fetching logs stats:', error);
          });

          // Component should still be rendered (not crashed)
          expect(screen.getByText('SystemLogsManagement')).toBeInTheDocument();

          consoleSpy.mockRestore();
          unmount();
        }
      ),
      { numRuns: 6 }
    );
  });

  /**
   * **Validates: Requirements 3.2**
   * 
   * Property: Both `/api/audit-trail` and `/api/system-errors` are fetched
   * concurrently (both calls are initiated before either resolves).
   */
  it('Property: both API endpoints are fetched concurrently via Promise.all', async () => {
    vi.clearAllMocks();

    const callOrder: string[] = [];
    let resolveAudit: (value: any) => void;
    let resolveErrors: (value: any) => void;

    const auditPromise = new Promise((resolve) => { resolveAudit = resolve; });
    const errorsPromise = new Promise((resolve) => { resolveErrors = resolve; });

    mockedApi.get.mockImplementation((url: string) => {
      callOrder.push(url);
      if (url === '/audit-trail') return auditPromise;
      if (url === '/system-errors') return errorsPromise;
      return Promise.reject(new Error('Unknown URL'));
    });

    const { unmount } = render(<SystemLogsManagement />);

    // Both calls should be initiated before either resolves (concurrent)
    await waitFor(() => {
      expect(callOrder).toContain('/audit-trail');
      expect(callOrder).toContain('/system-errors');
    });

    // Both calls were made before we resolve anything — proves concurrency
    expect(mockedApi.get).toHaveBeenCalledTimes(2);

    // Resolve to clean up
    await act(async () => {
      resolveAudit!({ data: { data: [], pagination: { page: 1, pageSize: 50, total: 0, totalPages: 0 } } });
      resolveErrors!({ data: { data: [], pagination: { page: 1, pageSize: 50, total: 0, totalPages: 0 } } });
    });

    unmount();
  });
});

import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { History, AlertCircle, LayoutDashboard, Terminal, Activity, ShieldCheck, Plus } from 'lucide-react';
import { motion, AnimatePresence } from 'motion/react';
import api from '../services/api';
import logger from '../utils/logger';

// Existing Module Logic
import AuditTrail from './AuditTrail';
import SystemErrorLogs from './SystemErrorLogs';

const SystemLogsManagement: React.FC = () => {
  const { t } = useTranslation();
  const [activeTab, setActiveTab ] = useState<'overview' | 'audit' | 'errors'>('overview');
  const [stats, setStats] = useState({ auditToday: 0, errorsCount: 0, healthPercent: 100, healthColor: 'text-emerald-500', healthStatus: 'stable' });
  const [loading, setLoading] = useState(false);

  const fetchStats = async () => {
    try {
      setLoading(true);
      const [auditRes, errorsRes] = await Promise.all([
        api.get('/audit-trail'),
        api.get('/system-errors')
      ]);

      // Normalize data (some endpoints return { data: [], total: ... })
      const auditData = Array.isArray(auditRes.data) ? auditRes.data : (auditRes.data?.data || []);
      const errorsData = Array.isArray(errorsRes.data) ? errorsRes.data : (errorsRes.data?.data || []);

      // Calculate audit actions for today
      const today = new Date().toISOString().split('T')[0];
      const todayAudit = auditData.filter((item: any) => 
        item.timestamp?.startsWith(today)
      ).length;

      // Use pagination.total for accurate counts across all pages
      const totalErrors = errorsRes.data?.pagination?.total ?? errorsData.length;
      const totalAudit = auditRes.data?.pagination?.total ?? auditData.length;

      // Compute dynamic health percentage
      const health = (totalAudit > 0 || totalErrors > 0)
        ? (totalAudit / (totalAudit + totalErrors)) * 100
        : 100;

      // Determine color and status based on thresholds
      let healthColor: string;
      let healthStatus: string;
      if (health >= 90) {
        healthColor = 'text-emerald-500';
        healthStatus = 'stable';
      } else if (health >= 70) {
        healthColor = 'text-amber-500';
        healthStatus = 'degraded';
      } else {
        healthColor = 'text-rose-500';
        healthStatus = 'critical';
      }

      setStats({
        auditToday: todayAudit,
        errorsCount: totalErrors,
        healthPercent: health,
        healthColor,
        healthStatus
      });
    } catch (error) {
      logger.error('Error fetching logs stats:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchStats();
  }, []);

  const tabs = [
    { id: 'overview', label: t('SystemLogsDashboard'), icon: LayoutDashboard },
    { id: 'audit', label: t('SystemLogsAudit'), icon: History },
    { id: 'errors', label: t('SystemLogsErrors'), icon: AlertCircle },
  ];

  return (
    <div className="space-y-8 pb-10">
      {/* Header Area */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div className="flex items-center gap-6">
          <div className="w-12 h-12 sm:w-16 sm:h-16 bg-[var(--color-primary)] rounded-2xl flex items-center justify-center text-white shadow-lg shadow-[var(--color-primary)]/20">
            <Terminal size={32} />
          </div>
          <div>
            <h2 className="text-2xl sm:text-4xl font-bold text-[var(--color-text-main)] tracking-tight">{t('SystemLogsManagement')}</h2>
            <p className="text-sm text-[var(--color-text-muted)] font-bold mt-2">{t('SystemLogsManagementDesc')}</p>
          </div>
        </div>
      </div>

      {/* Modern Tabs */}
      <div className="flex flex-wrap gap-2 p-1.5 bg-[var(--color-bg-main)]/50 rounded-2xl w-fit self-start border border-[var(--color-border-soft)]/50">
        {tabs.map((tab) => {
          const Icon = tab.icon;
          const isActive = activeTab === tab.id;
          return (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`flex items-center gap-2.5 px-6 py-3 rounded-xl text-sm font-bold transition-all cursor-pointer ${
                isActive 
                  ? 'bg-[var(--color-card)] text-[var(--color-primary)] shadow-sm shadow-[var(--color-border-soft)] border border-[var(--color-border-soft)]' 
                  : 'text-[var(--color-text-muted)] hover:text-[var(--color-text-main)] hover:bg-[var(--color-card)]/50'
              }`}
            >
              <Icon size={18} className={isActive ? 'text-[var(--color-primary)]' : 'text-[var(--color-text-muted)]'} />
              {tab.label}
            </button>
          );
        })}
      </div>

      {/* Tab Content */}
      <AnimatePresence mode="wait">
        <motion.div
          key={activeTab}
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -20 }}
          transition={{ duration: 0.2 }}
        >
          {activeTab === 'overview' && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {/* Bento Grid Analytics */}
              <div className="p-8 bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-2xl shadow-sm flex flex-col justify-between group">
                <div>
                  <div className="w-12 h-12 rounded-2xl bg-[var(--color-primary-light)] flex items-center justify-center text-blue-500 mb-6 group-hover:scale-110 transition-transform">
                    <History size={24} />
                  </div>
                  <h3 className="text-xl font-bold text-[var(--color-text-main)] mb-2">{t('SystemLogsAudit')}</h3>
                  <p className="text-sm font-bold text-[var(--color-text-muted)] leading-relaxed">
                    {t('systemLogsManagement.auditDesc')}
                  </p>
                </div>
                <button 
                  onClick={() => setActiveTab('audit')}
                  className="mt-8 flex items-center gap-2 text-blue-500 font-bold text-sm group/btn"
                >
                  {t('systemLogsManagement.openLog')} 
                  <Activity size={16} className="group-hover/btn:translate-x-1 transition-transform rtl:rotate-180" />
                </button>
              </div>

              <div className="p-8 bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-2xl shadow-sm flex flex-col justify-between group">
                <div>
                  <div className="w-12 h-12 rounded-2xl bg-rose-50 flex items-center justify-center text-rose-500 mb-6 group-hover:scale-110 transition-transform">
                    <AlertCircle size={24} />
                  </div>
                  <h3 className="text-xl font-bold text-[var(--color-text-main)] mb-2">{t('SystemLogsErrors')}</h3>
                  <p className="text-sm font-bold text-[var(--color-text-muted)] leading-relaxed">
                    {t('systemLogsManagement.errorsDesc')}
                  </p>
                </div>
                <button 
                  onClick={() => setActiveTab('errors')}
                  className="mt-8 flex items-center gap-2 text-rose-500 font-bold text-sm group/btn"
                >
                  {t('systemLogsManagement.openLog')} 
                  <Activity size={16} className="group-hover/btn:translate-x-1 transition-transform rtl:rotate-180" />
                </button>
              </div>

              <div className="p-8 bg-[var(--color-card)] border border-[var(--color-border-soft)] rounded-2xl shadow-sm flex flex-col justify-between group overflow-hidden relative">
                <div className="absolute top-0 end-0 p-8 opacity-[0.03] pointer-events-none">
                  <ShieldCheck size={120} className="text-emerald-500" />
                </div>
                <div className="relative z-10">
                  <div className="w-12 h-12 rounded-2xl bg-emerald-50 flex items-center justify-center text-emerald-500 mb-6 group-hover:scale-110 transition-transform">
                    <ShieldCheck size={24} />
                  </div>
                  <h3 className="text-xl font-bold text-[var(--color-text-main)] mb-2">{t('systemLogsManagement.systemHealth')}</h3>
                  <p className="text-sm font-bold text-[var(--color-text-muted)]">{t('systemLogsManagement.serverStatus')}</p>
                  <div className="mt-6 flex items-end gap-2">
                    <span className={`text-5xl font-bold tracking-tighter ${stats.healthColor}`}>{stats.healthPercent.toFixed(1)}%</span>
                    <span className="text-[var(--color-text-muted)] font-bold mb-1 text-xs uppercase tracking-widest">{t(`systemLogsManagement.${stats.healthStatus}`)}</span>
                  </div>
                </div>
                <div className="relative z-10 space-y-3 mt-8 pt-6 border-t border-[var(--color-border-soft)]">
                  <div className="flex justify-between items-center text-xs font-bold text-[var(--color-text-muted)]">
                    <span className="text-[var(--color-text-muted)]">{t('systemLogsManagement.auditToday')}</span>
                    <span>{stats.auditToday} {t('systemLogsManagement.actions')}</span>
                  </div>
                  <div className="flex justify-between items-center text-xs font-bold text-rose-500">
                    <span>{t('systemLogsManagement.totalErrors')}</span>
                    <span>{stats.errorsCount} {t('systemLogsManagement.errorCount')}</span>
                  </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'audit' && <AuditTrail />}
          {activeTab === 'errors' && <SystemErrorLogs />}
        </motion.div>
      </AnimatePresence>
    </div>
  );
};

export default SystemLogsManagement;

import React, { useState } from 'react';
import { motion } from 'motion/react';
import { History, Search, Filter, Shield, Clock, User, Activity } from 'lucide-react';
import { useTranslation } from 'react-i18next';

import Pagination from '../../components/Pagination';

import { useFormat } from '../../services/formatService';

interface HistoryLogsProps {
  loginHistory: any[];
  activityLogs: any[];
  historyPagination: any;
  activityPagination: any;
  onHistoryPageChange: (page: number) => void;
  onHistoryPageSizeChange: (size: number) => void;
  onActivityPageChange: (page: number) => void;
  onActivityPageSizeChange: (size: number) => void;
}

const HistoryLogs: React.FC<HistoryLogsProps> = ({
  loginHistory,
  activityLogs,
  historyPagination,
  activityPagination,
  onHistoryPageChange,
  onHistoryPageSizeChange,
  onActivityPageChange,
  onActivityPageSizeChange
}) => {
  const { t, i18n } = useTranslation();
  const { translateStatus, translateName } = useFormat();
  const [logTab, setLogTab] = useState<'login' | 'activity'>('login');

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-6">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-[var(--color-primary)]/10 rounded-2xl flex items-center justify-center text-[var(--color-primary)]">
            <History size={24} />
          </div>
          <div>
            <h3 className="text-2xl font-bold text-[var(--color-text-main)]">{t('userManagement.history.title')}</h3>
            <p className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('userManagement.history.subtitle')}</p>
          </div>
        </div>
        <div className="flex bg-[var(--color-bg-soft)] p-1 rounded-xl self-start border border-[var(--color-border-soft)]">
