import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { Shield, Save, CheckCircle, ChevronRight } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { PERMISSIONS } from '../../permissions';
import { useFormat } from '../../services/formatService';

interface RolePermissionsProps {
  allRoles: any[];
  allPermissions: any[];
  showSaveSuccess: boolean;
  getRoleLabel: (role: string) => string;
  onSave: (modifiedRoles: any[]) => void;
}

const RolePermissions: React.FC<RolePermissionsProps> = ({
  allRoles,
  allPermissions,
  showSaveSuccess,
  getRoleLabel,
  onSave
}) => {
  const { t } = useTranslation();
  const { formatNumber } = useFormat();
  const [selectedRoleId, setSelectedRoleId] = useState<number | null>(null);
  const [localRoles, setLocalRoles] = useState<any[]>([]);
  const [isDirty, setIsDirty] = useState(false);
  const [modifiedRoleIds, setModifiedRoleIds] = useState<Set<number>>(new Set());

  // Initialize selected role and local state when roles are loaded
  useEffect(() => {
    if (allRoles.length > 0 && selectedRoleId === null) {
      setSelectedRoleId(allRoles[0].id);
    }
    if (!isDirty && allRoles.length > 0) {
      setLocalRoles(JSON.parse(JSON.stringify(allRoles)));
      setModifiedRoleIds(new Set());
    }
  }, [allRoles, selectedRoleId, isDirty]);

  const handleToggle = (roleId: number, permId: number, checked: boolean) => {
    setLocalRoles(prev => prev.map(role => {
      if (role.id === roleId) {
        const perms = role.permissions || [];
        if (checked) {
          const permObj = allPermissions.find(p => p.id === permId);
          return { ...role, permissions: [...perms, permObj] };
        } else {
          return { ...role, permissions: perms.filter((p: any) => p.id !== permId) };
        }
      }
      return role;
    }));
    setModifiedRoleIds(prev => new Set(prev).add(roleId));
    setIsDirty(true);
  };

  const handleSave = () => {
    const rolesToSave = localRoles.filter(r => modifiedRoleIds.has(r.id));
    onSave(rolesToSave);
    setIsDirty(false);
    setModifiedRoleIds(new Set());
  };

  // Group permissions by module
  const fallbackModules = ['Audit', 'Finding', 'Risk', 'Recommendation', 'Correspondence', 'User', 'Setting'];
  const modules = allPermissions.length > 0 
    ? Array.from(new Set(allPermissions.map(p => p.module)))
    : fallbackModules;
    
  const actions = Object.values(PERMISSIONS);

  const selectedRole = localRoles.find(r => r.id === selectedRoleId);

  return (
    <div className="space-y-4 animate-in fade-in duration-500">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-[var(--color-primary)]/10 rounded-xl flex items-center justify-center text-[var(--color-primary)]">
            <Shield size={20} />
          </div>
          <div>
            <h3 className="text-xl font-bold text-[var(--color-text-main)]">{t('userManagement.roles.title')}</h3>
            <p className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-wider">{t('userManagement.roles.subtitle')}</p>
          </div>
        </div>
        <button 
          onClick={handleSave} 
          disabled={!isDirty}
          className={`btn-primary flex items-center gap-2 !py-2 !px-4 !text-xs ${!isDirty ? 'opacity-50 cursor-not-allowed' : ''}`}
        >
          <Save size={16} />
          {t('common.save')}
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-5 gap-4">
        {/* Roles Sidebar */}
        <div className="lg:col-span-1 space-y-1.5">
          <p className="text-[9px] font-bold text-[var(--color-text-muted)] uppercase tracking-wider px-2 mb-2">{t('userManagement.roles.rolesLabel')}</p>
          {localRoles.length > 0 ? localRoles.map(role => (
            <button
              key={role.id}
              onClick={() => setSelectedRoleId(role.id)}
              className={`w-full flex items-center justify-between p-3 rounded-xl transition-all duration-300 ${
                selectedRoleId === role.id 
                  ? 'bg-[var(--color-primary)] text-white shadow-lg shadow-[var(--color-primary)]/10 translate-x-1' 
                  : 'bg-[var(--color-card)] text-[var(--color-text-main)] hover:bg-[var(--color-bg-soft)] border border-[var(--color-border-soft)]'
              }`}
            >
              <div className="text-start truncate">
                <p className="text-xs font-bold truncate">{getRoleLabel(role.name)}</p>
                <p className={`text-[9px] ${selectedRoleId === role.id ? 'text-white/70' : 'text-[var(--color-text-muted)]'}`}>
                  {formatNumber((role.permissions || []).length)} {t('userManagement.roles.permissionsLabel')}
                </p>
              </div>
              <ChevronRight size={14} className={selectedRoleId === role.id ? 'opacity-100 flex-shrink-0' : 'opacity-0'} />
            </button>
          )) : (
            <div className="p-4 text-center text-[var(--color-text-muted)] text-[10px]">{t('common.loading')}</div>
          )}
        </div>

        {/* Permissions Matrix */}
        <div className="lg:col-span-4">
          <div className="glass-card overflow-hidden border-[var(--color-border-soft)]">
            <div className="overflow-x-auto">
              <table className="w-full text-start border-collapse">
                <thead>
                  <tr className="bg-[var(--color-bg-soft)] border-b border-[var(--color-border-soft)]">
                    <th className="px-5 py-3 text-[9px] font-bold text-[var(--color-text-muted)] uppercase tracking-wider text-start min-w-[140px]">{t('userManagement.roles.module')}</th>
                    {actions.map(action => (
                      <th key={action} className="px-4 py-3 text-[9px] font-bold text-[var(--color-text-muted)] uppercase tracking-wider text-center">
                        {t(`permissions.${action}`)}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-[var(--color-border-soft)]">
                  <AnimatePresence>
                    {modules.map((module, idx) => (
                      <motion.tr 
                        key={`${selectedRoleId}-${module}`}
                        initial={{ opacity: 0, x: 10 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ delay: idx * 0.01 }}
                        className="hover:bg-[var(--color-bg-soft)]/50 transition-colors"
                      >
                        <td className="px-5 py-3">
                          <span className="text-xs font-bold text-[var(--color-text-main)]">{t(`modules.${module}`)}</span>
                        </td>
                        {actions.map(action => {
                          const perm = allPermissions.find(p => p.module === module && p.action === action);
                          
                          // If no real permission object, show a dummy toggle that doesn't do anything for now 
                          // or just show a greyed out one
                          const hasPermission = perm ? (selectedRole?.permissions || []).some((p: any) => p.id === perm.id) : false;
                          const disabled = !perm || !selectedRoleId;
                          
                          return (
                            <td key={action} className="px-4 py-3 text-center">
                              <label className={`relative inline-flex items-center ${disabled ? 'opacity-30 cursor-not-allowed' : 'cursor-pointer'} group`}>
                                <input 
                                  type="checkbox" 
                                  className="sr-only peer"
                                  checked={hasPermission}
                                  disabled={disabled}
                                  onChange={(e) => perm && handleToggle(selectedRoleId!, perm.id, e.target.checked)}
                                />
                                <div className="w-9 h-5 bg-[var(--color-border-soft)] peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-[var(--color-card)] after:border-[var(--color-border-strong)] after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-[var(--color-primary)] group-hover:shadow-sm transition-all"></div>
                              </label>
                            </td>
                          );
                        })}
                      </motion.tr>
                    ))}
                  </AnimatePresence>
                </tbody>
              </table>
            </div>
          </div>
          {allPermissions.length === 0 && localRoles.length > 0 && (
            <p className="mt-2 text-[9px] text-[var(--color-warning)] font-bold text-center italic">{t('userManagement.roles.matrix')} (Preview Mode)</p>
          )}
        </div>
      </div>


      {showSaveSuccess && (
        <motion.div 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0 }}
          className="fixed bottom-10 end-10 bg-[var(--color-success)] text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-3 z-50"
        >
          <CheckCircle size={24} />
          <span className="font-bold uppercase tracking-widest text-xs">{t('settingsSavedSuccessfully')}</span>
        </motion.div>
      )}
    </div>
  );
};

export default RolePermissions;

import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { motion } from 'framer-motion';
import { CheckCircle, XCircle, Clock, Search, Filter, MessageSquare, User, Mail, FileText } from 'lucide-react';
import { getContactAdminRequests, updateContactAdminRequestStatus, ContactAdminRequest } from '../../services/contactAdminService';
import logger from '../../utils/logger';

const SupportRequests: React.FC = () => {
  const { t, i18n } = useTranslation();
  const [requests, setRequests] = useState<ContactAdminRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | 'pending' | 'resolved' | 'rejected'>('all');

  useEffect(() => {
    fetchRequests();
  }, []);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const data = await getContactAdminRequests();
      setRequests(data);
    } catch (error) {
      logger.error('Error fetching support requests:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleUpdateStatus = async (id: string, status: 'resolved' | 'rejected') => {
    try {
      await updateContactAdminRequestStatus(id, status);
      fetchRequests(); // Refresh list
    } catch (error) {
      logger.error('Error updating status:', error);
    }
  };

  const filteredRequests = requests.filter(req => {
    const matchesSearch = 
      req.fullName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      req.contactInfo.toLowerCase().includes(searchTerm.toLowerCase()) ||
      req.ticketId?.toLowerCase().includes(searchTerm.toLowerCase());
    
    const matchesStatus = statusFilter === 'all' || req.status === statusFilter;
    
    return matchesSearch && matchesStatus;
  });

  const getStatusBadge = (status?: string) => {
    switch (status) {
      case 'pending':
        return <span className="px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest bg-[var(--color-warning)]/10 text-[var(--color-warning)] flex items-center gap-1"><Clock size={12} /> {t('userManagement.supportRequests.pending')}</span>;
      case 'resolved':
        return <span className="px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest bg-[var(--color-success)]/10 text-[var(--color-success)] flex items-center gap-1"><CheckCircle size={12} /> {t('userManagement.supportRequests.resolved')}</span>;
      case 'rejected':
        return <span className="px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest bg-[var(--color-danger)]/10 text-[var(--color-danger)] flex items-center gap-1"><XCircle size={12} /> {t('userManagement.supportRequests.rejected')}</span>;
      default:
        return null;
    }
  };

  const getRequestTypeLabel = (type: string) => {
    const types: Record<string, string> = {
      newAccount: t('auth.contactAdminModal.requestTypes.newAccount'),
      loginProblem: t('auth.contactAdminModal.requestTypes.loginProblem'),
      passwordReset: t('auth.contactAdminModal.requestTypes.passwordReset'),
      permissionIssue: t('auth.contactAdminModal.requestTypes.permissionIssue'),
      other: t('auth.contactAdminModal.requestTypes.generalSupport')
    };
    return types[type] || type;
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col sm:flex-row gap-4 justify-between items-start sm:items-center bg-[var(--color-card)] p-4 rounded-2xl border border-[var(--color-border-soft)] shadow-sm">
        <div className="relative flex-1 w-full max-w-md">
          <Search className="absolute start-4 top-1/2 -translate-y-1/2 text-[var(--color-text-muted)]" size={20} />
          <input 
            type="text"
            placeholder={t('common.search')}
            className="input-field !ps-12 w-full"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <div className="flex items-center gap-2 w-full sm:w-auto">
          <Filter className="text-[var(--color-text-muted)]" size={20} />
          <select 
            className="input-field py-2"
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value as any)}
          >
            <option value="all">{t('userManagement.supportRequests.all')}</option>
            <option value="pending">{t('userManagement.supportRequests.pending')}</option>
            <option value="resolved">{t('userManagement.supportRequests.resolved')}</option>
            <option value="rejected">{t('userManagement.supportRequests.rejected')}</option>
          </select>
        </div>
      </div>

      {loading ? (
        <div className="flex justify-center items-center py-12">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[var(--color-primary)]"></div>
        </div>
      ) : filteredRequests.length === 0 ? (
        <div className="text-center py-16 bg-[var(--color-card)] rounded-2xl border border-[var(--color-border-soft)] border-dashed">
          <MessageSquare size={48} className="mx-auto text-[var(--color-text-muted)] mb-4 opacity-30" />
          <h3 className="text-lg font-bold text-[var(--color-text-main)] mb-1">{t('userManagement.supportRequests.noRequests')}</h3>
          <p className="text-[var(--color-text-muted)] font-bold">{t('common.noDataDesc')}</p>
        </div>
      ) : (
        <div className="grid gap-4">
          {filteredRequests.map((request) => (
            <motion.div 
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              key={request.id} 
              className="glass-card p-6 border-[var(--color-border-soft)] hover:border-[var(--color-primary)]/30 transition-all"
            >
              <div className="flex flex-col lg:flex-row gap-6 justify-between">
                <div className="space-y-4 flex-1">
                  <div className="flex flex-wrap items-center gap-3">
                    <span className="text-[10px] font-mono font-bold text-[var(--color-text-muted)] bg-[var(--color-bg-soft)] px-2 py-1 rounded-md border border-[var(--color-border-soft)]">
                      {request.ticketId}
                    </span>
                    {getStatusBadge(request.status)}
                    <span className="text-[10px] text-[var(--color-text-muted)] font-bold flex items-center gap-1 uppercase tracking-widest">
                      <Clock size={14} />
                      {new Date(request.createdAt || '').toLocaleString(i18n.language)}
                    </span>
                  </div>
                  
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="flex items-start gap-3">
                      <div className="w-10 h-10 rounded-xl bg-[var(--color-primary)]/10 flex items-center justify-center text-[var(--color-primary)] shrink-0">
                        <User size={20} />
                      </div>
                      <div>
                        <p className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-1">{t('common.name')}</p>
                        <p className="font-bold text-[var(--color-text-main)]">{request.fullName}</p>
                      </div>
                    </div>
                    <div className="flex items-start gap-3">
                      <div className="w-10 h-10 rounded-xl bg-[var(--color-primary)]/10 flex items-center justify-center text-[var(--color-primary)] shrink-0">
                        <Mail size={20} />
                      </div>
                      <div>
                        <p className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-widest mb-1">{t('userManagement.form.contactInfo')}</p>
                        <p className="font-bold text-[var(--color-text-main)]">{request.contactInfo}</p>
                      </div>
                    </div>
                  </div>

                  <div className="bg-[var(--color-bg-soft)] p-4 rounded-xl border border-[var(--color-border-soft)]">
                    <div className="flex items-center gap-2 mb-2">
                      <FileText size={16} className="text-[var(--color-text-muted)]" />
                      <span className="font-bold text-[var(--color-text-main)] text-sm uppercase tracking-widest">{getRequestTypeLabel(request.requestType)}</span>
                    </div>
                    <p className="text-[var(--color-text-muted)] text-sm font-bold whitespace-pre-wrap">{request.requestDetails || t('userManagement.supportRequests.noDetails')}</p>
                  </div>
                </div>

                {request.status === 'pending' && (
                  <div className="flex lg:flex-col gap-3 shrink-0 lg:w-40">
                    <button 
                      onClick={() => handleUpdateStatus(request.id!, 'resolved')}
                      className="flex-1 lg:flex-none py-2.5 bg-[var(--color-success)]/10 text-[var(--color-success)] hover:bg-[var(--color-success)]/20 font-bold text-[10px] uppercase tracking-widest rounded-xl transition-all flex items-center justify-center gap-2"
                    >
                      <CheckCircle size={18} />
                      {t('userManagement.supportRequests.resolve')}
                    </button>
                    <button 
                      onClick={() => handleUpdateStatus(request.id!, 'rejected')}
                      className="flex-1 lg:flex-none py-2.5 bg-[var(--color-danger)]/10 text-[var(--color-danger)] hover:bg-[var(--color-danger)]/20 font-bold text-[10px] uppercase tracking-widest rounded-xl transition-all flex items-center justify-center gap-2"
                    >
                      <XCircle size={18} />
                      {t('userManagement.supportRequests.reject')}
                    </button>
                  </div>
                )}
              </div>
            </motion.div>
          ))}
        </div>
      )}
    </div>
  );
};

export default SupportRequests;

import React from 'react';
import { motion } from 'motion/react';
import { useTranslation } from 'react-i18next';
import { AccessScope } from '../../constants';
import { ROLES } from '../../permissions';
import { ChevronDown } from 'lucide-react';

import { useFormat } from '../../services/formatService';
import { useDepartments } from '../../hooks/useDepartments';

interface UserFormProps {
  editingUser: any;
  newUser: any;
  userError: string;
  jobTitles: any[];
  users: any[];
  allRoles: any[];
  isLoading?: boolean;
  getRoleLabel: (role: string) => string;
  onCancel: () => void;
  onSave: () => void;
  onUpdateNewUser: (data: any) => void;
}

const UserForm: React.FC<UserFormProps> = ({
  editingUser,
  newUser,
  userError,
  jobTitles,
  users,
  allRoles,
  isLoading = false,
  getRoleLabel,
  onCancel,
  onSave,
  onUpdateNewUser
}) => {
  const { t } = useTranslation();
  const { translateName } = useFormat();
  const { departments } = useDepartments();

  const isFormDisabled = isLoading;

  return (
    <motion.div 
      initial={{ opacity: 0, y: -20 }}
      animate={{ opacity: 1, y: 0 }}
      className="glass-card p-6 border-[var(--color-primary)]/20"
    >
      <h3 className="text-lg font-bold text-[var(--color-text-main)] mb-6">{editingUser ? t('userManagement.editUser') : t('userManagement.addUser')}</h3>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        <div className="space-y-1">
          <label className="text-[9px] font-bold text-[var(--color-text-muted)] uppercase tracking-wider">{t('userManagement.form.username')}</label>
          <input className="input-field !py-2 !text-xs" placeholder={t('userManagement.form.username')} value={newUser.username || ''} onChange={e => onUpdateNewUser({ username: e.target.value })} disabled={!!editingUser || isFormDisabled} />
        </div>
        {!editingUser && (
          <div className="space-y-1">
            <label className="text-[9px] font-bold text-[var(--color-text-muted)] uppercase tracking-wider">{t('userManagement.form.password')}</label>
            <input className="input-field !py-2 !text-xs" type="password" placeholder={t('userManagement.form.password')} value={newUser.password || ''} onChange={e => onUpdateNewUser({ password: e.target.value })} disabled={isFormDisabled} />
          </div>
        )}
        <div className="space-y-1">
          <label className="text-[9px] font-bold text-[var(--color-text-muted)] uppercase tracking-wider">{t('userManagement.form.fullName')}</label>
          <input className="input-field !py-2 !text-xs" placeholder={t('userManagement.form.fullName')} value={newUser.name || ''} onChange={e => onUpdateNewUser({ name: e.target.value })} disabled={isFormDisabled} />
        </div>
        <div className="space-y-1">
          <label className="text-[9px] font-bold text-[var(--color-text-muted)] uppercase tracking-wider">{t('userManagement.form.email')}</label>
          <input className="input-field !py-2 !text-xs" placeholder={t('userManagement.form.email')} value={newUser.email || ''} onChange={e => onUpdateNewUser({ email: e.target.value })} disabled={isFormDisabled} />
        </div>
        <div className="space-y-1">
          <label className="text-[9px] font-bold text-[var(--color-text-muted)] uppercase tracking-wider">{t('userManagement.form.phoneNumber')}</label>
          <input className="input-field !py-2 !text-xs" placeholder={t('userManagement.form.phoneNumber')} value={newUser.phone_number || ''} onChange={e => onUpdateNewUser({ phone_number: e.target.value })} disabled={isFormDisabled} />
        </div>
        <div className="space-y-1">
          <label className="text-[9px] font-bold text-[var(--color-text-muted)] uppercase tracking-wider">{t('userManagement.form.jobTitle')}</label>
          <select className="input-field !py-2 !text-xs" value={newUser.job_title_id || ''} onChange={e => onUpdateNewUser({ job_title_id: e.target.value })} disabled={isFormDisabled}>
            <option value="">{t('userManagement.form.selectJobTitle')}</option>
            {jobTitles.map(title => (
              <option key={title.id} value={title.id}>{title.name}</option>
            ))}
          </select>
        </div>
        <div className="space-y-1">
          <label className="text-[9px] font-bold text-[var(--color-text-muted)] uppercase tracking-wider">{t('userManagement.form.department')}</label>
          <select className="input-field !py-2 !text-xs" value={newUser.department || ''} onChange={e => onUpdateNewUser({ department: e.target.value })} disabled={isFormDisabled}>
            <option value="">{t('userManagement.form.selectDepartment')}</option>
            {departments.map(dept => (
              <option key={dept.id} value={dept.name}>{dept.name}</option>
            ))}
          </select>
        </div>
        <div className="space-y-1">
          <label className="text-[9px] font-bold text-[var(--color-text-muted)] uppercase tracking-wider">{t('userManagement.form.unit')}</label>
          <input className="input-field !py-2 !text-xs" placeholder={t('userManagement.form.unit')} value={newUser.unit || ''} onChange={e => onUpdateNewUser({ unit: e.target.value })} disabled={isFormDisabled} />
        </div>
        <div className="space-y-1">
          <label className="text-[9px] font-bold text-[var(--color-text-muted)] uppercase tracking-wider">{t('userManagement.form.reportingManager')}</label>
          <select className="input-field !py-2 !text-xs" value={newUser.reporting_manager_id || ''} onChange={e => onUpdateNewUser({ reporting_manager_id: e.target.value })} disabled={isFormDisabled}>
            <option value="">{t('userManagement.form.selectManager')}</option>
            {users.filter(u => u.id !== editingUser?.id).map(u => (
              <option key={u.id} value={u.id}>{translateName(u.name)}</option>
            ))}
          </select>
        </div>
        <div className="space-y-1">
          <label className="text-[9px] font-bold text-[var(--color-text-muted)] uppercase tracking-wider">{t('userManagement.form.accessScope')}</label>
          <select className="input-field !py-2 !text-xs" value={newUser.access_scope || AccessScope.GLOBAL} onChange={e => onUpdateNewUser({ access_scope: e.target.value })} disabled={isFormDisabled}>
            <option value={AccessScope.GLOBAL}>{t('userManagement.form.global')}</option>
            <option value={AccessScope.DEPARTMENT}>{t('userManagement.form.department')}</option>
            <option value={AccessScope.UNIT}>{t('userManagement.form.unit')}</option>
          </select>
        </div>
        <div className="space-y-1">
          <label className="text-[9px] font-bold text-[var(--color-text-muted)] uppercase tracking-wider">{t('common.role')}</label>
          <div className="relative">
            <select 
              className="input-field appearance-none !py-2 !text-xs cursor-pointer pe-8"
              value={newUser.role || ROLES.VIEWER} 
              onChange={e => onUpdateNewUser({ role: e.target.value })} 
              disabled={isFormDisabled}
            >
              {allRoles.length === 0 ? (
                <option value="">{t('userManagement.form.loadingRoles')}</option>
              ) : (
                allRoles.map(role => (
                  <option key={role.id} value={role.name}>{getRoleLabel(role.name)}</option>
                ))
              )}
            </select>
            <div className="absolute start-3 top-1/2 -translate-y-1/2 pointer-events-none text-[var(--color-text-muted)]">
              <ChevronDown size={14} />
            </div>
          </div>
        </div>
        <div className="lg:col-span-1 space-y-1">
          <label className="text-[9px] font-bold text-[var(--color-text-muted)] uppercase tracking-wider">{t('userManagement.form.notes')}</label>
          <textarea 
            className="input-field !py-2 !text-xs min-h-[42px]" 
            placeholder={t('userManagement.form.additionalNotes')} 
            value={newUser.notes || ''} 
            onChange={e => onUpdateNewUser({ notes: e.target.value })}
            disabled={isFormDisabled}
          />
        </div>
      </div>
      {userError && (
        <div className="mt-4 p-2 bg-[var(--color-danger)]/10 text-[var(--color-danger)] rounded-lg text-xs">
          {userError}
        </div>
      )}
      <div className="flex justify-end gap-3 mt-6">
        <button onClick={onCancel} className="btn-secondary !py-2 !px-4 !text-xs" disabled={isFormDisabled}>{t('common.cancel')}</button>
        <button 
          onClick={onSave} 
          className="btn-primary flex items-center gap-2 !py-2 !px-4 !text-xs"
          disabled={isFormDisabled}
        >
          {isLoading && <div className="w-3 h-3 border-2 border-white/30 border-t-white rounded-full animate-spin" />}
          {editingUser ? t('common.save') : t('userManagement.addUser')}
        </button>
      </div>

    </motion.div>
  );
};

export default UserForm;

import React from 'react';
import { motion } from 'motion/react';
import { Mail, Shield, Building, Edit, Trash2, Unlock } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { useFormat } from '../../services/formatService';

interface UserListProps {
  users: any[];
  getRoleLabel: (role: string) => string;
  onEdit: (user: any) => void;
  onSuspend: (id: string) => void;
  onDelete: (id: string) => void;
  onResetPassword: (id: string) => void;
  onUnlock: (id: string) => void;
}

const UserList: React.FC<UserListProps> = ({
  users,
  getRoleLabel,
  onEdit,
  onSuspend,
  onDelete,
  onResetPassword,
  onUnlock
}) => {
  const { t, i18n } = useTranslation();
  const { translateStatus, formatDateTime, formatNumber, translateName } = useFormat();

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
      {users.map((user, idx) => (
        <motion.div 
          key={user.id}
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: idx * 0.05 }}
          className="glass-card group hover:shadow-xl hover:shadow-[var(--color-primary)]/5 transition-all duration-500 overflow-hidden flex flex-col"
        >
          <div className="p-4 sm:p-5 space-y-4 flex-1">
            <div className="flex items-start justify-between">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-[var(--color-bg-soft)] rounded-xl flex items-center justify-center text-[var(--color-text-muted)] group-hover:bg-[var(--color-primary)]/10 group-hover:text-[var(--color-primary)] transition-colors duration-500 flex-shrink-0">
                  <span className="text-base font-bold uppercase">{user.name?.charAt(0)}</span>
                </div>
                <div className="min-w-0">
                  <h3 className="text-sm font-bold text-[var(--color-text-main)] group-hover:text-[var(--color-primary)] transition-colors truncate">{translateName(user.name)}</h3>
                  <p className="text-[10px] font-bold text-[var(--color-text-muted)] truncate">@{user.username}</p>
                </div>
              </div>
              <div className="flex flex-col items-end gap-1.5 flex-shrink-0">
                <span className={`px-2 py-0.5 rounded-full text-[8px] font-bold uppercase tracking-wider ${
                  user.status === 'Active' ? 'bg-[var(--color-success)]/10 text-[var(--color-success)]' : 
                  user.status === 'Locked' ? 'bg-[var(--color-danger)]/10 text-[var(--color-danger)]' : 'bg-[var(--color-warning)]/10 text-[var(--color-warning)]'
                }`}>
                  {translateStatus(user.status)}
                </span>
                {user.status === 'Locked' && (
                  <div className="flex flex-col items-end gap-0.5">
                    <button 
                      onClick={() => onUnlock(user.id)}
                      className="flex items-center gap-1 text-[8px] font-bold text-[var(--color-success)] hover:underline"
                    >
                      <Unlock size={10} />
                      {t('userManagement.userCard.unlock')}
                    </button>
                    <span className="text-[7px] font-bold text-[var(--color-danger)] uppercase tracking-tighter opacity-80">
                      {formatNumber(user.failed_attempts || 0)} {t('userManagement.userCard.failedAttempts')}
                    </span>
                  </div>
                )}
              </div>
            </div>

            <div className="space-y-2">
              <div className="flex items-center gap-2 text-[var(--color-text-muted)]">
                <Mail size={14} className="opacity-50 flex-shrink-0" />
                <span className="text-[11px] font-bold truncate">{user.email}</span>
              </div>
              <div className="flex items-center gap-2 text-[var(--color-text-muted)]">
                <Shield size={14} className="opacity-50 flex-shrink-0" />
                <span className="text-[11px] font-bold truncate">{getRoleLabel(user.role)}</span>
              </div>
              <div className="flex items-center gap-2 text-[var(--color-text-muted)]">
                <Building size={14} className="opacity-50 flex-shrink-0" />
                <span className="text-[11px] font-bold truncate">{user.department}</span>
              </div>
            </div>

            <div className="pt-3 border-t border-[var(--color-border-soft)] flex items-center justify-between">
              <span className="text-[9px] font-bold text-[var(--color-text-muted)] uppercase tracking-wider">{t('userManagement.userCard.lastLogin')}</span>
              <span className="text-[9px] font-bold text-[var(--color-text-main)] opacity-70 truncate">{user.last_login ? formatDateTime(user.last_login) : t('userManagement.userCard.never')}</span>
            </div>
          </div>

          <div className="px-5 py-3 bg-[var(--color-bg-soft)]/30 border-t border-[var(--color-border-soft)] flex items-center justify-between">
            <div className="flex items-center gap-1">
              <button 
                onClick={() => onEdit(user)}
                className="p-1.5 text-[var(--color-text-muted)] hover:text-[var(--color-primary)] hover:bg-[var(--color-card)] rounded-lg transition-all"
                title={t('common.edit')}
              >
                <Edit size={16} />
              </button>
              <button 
                onClick={() => onResetPassword(user.id)}
                className="p-1.5 text-[var(--color-text-muted)] hover:text-[var(--color-warning)] hover:bg-[var(--color-card)] rounded-lg transition-all"
                title={t('userManagement.resetPassword')}
              >
                <Shield size={16} />
              </button>
              <button 
                onClick={() => onDelete(user.id)}
                className="p-1.5 text-[var(--color-text-muted)] hover:text-[var(--color-danger)] hover:bg-[var(--color-card)] rounded-lg transition-all"
                title={t('common.delete')}
              >
                <Trash2 size={16} />
              </button>
            </div>
            <button 
              onClick={() => onSuspend(user.id)}
              className={`text-[9px] font-bold uppercase tracking-wider px-3 py-1.5 rounded-lg transition-all ${
                user.status === 'Active' ? 'text-[var(--color-warning)] hover:bg-[var(--color-warning)]/10' : 'text-[var(--color-success)] hover:bg-[var(--color-success)]/10'
              }`}
            >
              {user.status === 'Active' ? t('userManagement.userCard.suspend') : t('userManagement.userCard.activate')}
            </button>
          </div>
        </motion.div>
      ))}
    </div>
  );
};

export default UserList;

import React from 'react';
import { motion } from 'motion/react';
import { Monitor, Smartphone, Globe, LogOut, Clock } from 'lucide-react';
import { useTranslation } from 'react-i18next';

interface UserSessionsProps {
  sessions: any[];
  onRevoke: (id: number) => void;
}

const UserSessions: React.FC<UserSessionsProps> = ({
  sessions,
  onRevoke
}) => {
  const { t, i18n } = useTranslation();

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex items-center gap-4">
        <div className="w-12 h-12 bg-[var(--color-primary)]/10 rounded-2xl flex items-center justify-center text-[var(--color-primary)]">
          <Globe size={24} />
        </div>
        <div>
          <h3 className="text-2xl font-bold text-[var(--color-text-main)]">{t('userManagement.sessions.title')}</h3>
          <p className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-widest">{t('userManagement.sessions.subtitle')}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {sessions.map((session, idx) => (
          <motion.div 
            key={session.id}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: idx * 0.05 }}
            className="glass-card p-8 flex items-center justify-between group"
          >
            <div className="flex items-center gap-6">
              <div className="w-14 h-14 bg-[var(--color-bg-soft)] rounded-2xl flex items-center justify-center text-[var(--color-text-muted)] group-hover:bg-[var(--color-primary)]/10 group-hover:text-[var(--color-primary)] transition-colors">
                {session.device_type === 'mobile' ? <Smartphone size={28} /> : <Monitor size={28} />}
              </div>
              <div className="space-y-1">
                <div className="flex items-center gap-2">
                  <h4 className="text-lg font-bold text-[var(--color-text-main)]">{session.username}</h4>
                  <span className="px-2 py-0.5 bg-[var(--color-success)]/10 text-[var(--color-success)] text-[10px] font-bold uppercase rounded-full">{t('userManagement.sessions.active')}</span>
                </div>
                <div className="flex flex-wrap gap-4 text-xs font-bold text-[var(--color-text-muted)]">
                  <div className="flex items-center gap-1">
                    <Globe size={14} />
                    {session.ip_address}
                  </div>
                  <div className="flex items-center gap-1">
                    <Clock size={14} />
                    {new Date(session.last_activity).toLocaleString(i18n.language === 'ar' ? 'ar-EG' : 'en-US')}
                  </div>
                </div>
                <p className="text-[10px] text-[var(--color-text-muted)] font-bold uppercase tracking-widest">{session.user_agent}</p>
              </div>
            </div>
            <button 
              onClick={() => onRevoke(session.id)}
              className="p-3 text-[var(--color-text-muted)] hover:text-[var(--color-danger)] hover:bg-[var(--color-danger)]/10 rounded-2xl transition-all"
              title={t('userManagement.sessions.revoke')}
            >
              <LogOut size={20} />
            </button>
          </motion.div>
        ))}
        {sessions.length === 0 && (
          <div className="lg:col-span-2 py-20 text-center border-2 border-dashed border-[var(--color-border-soft)] rounded-2xl">
            <p className="text-[var(--color-text-muted)] font-bold">{t('userManagement.sessions.noActiveSessions')}</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default UserSessions;

import React from 'react';
import { useTranslation } from 'react-i18next';
import { useFormat } from '../../services/formatService';

interface UserSummaryCardsProps {
  summary: any;
}

const UserSummaryCards: React.FC<UserSummaryCardsProps> = ({ summary }) => {
  const { t } = useTranslation();
  const { formatNumber } = useFormat();

  return (
    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
      <div className="glass-card p-4 border-[var(--color-success)]/20">
        <p className="text-[9px] font-bold text-[var(--color-text-muted)] uppercase tracking-wider mb-0.5">{t('userManagement.summary.totalUsers')}</p>
        <p className="text-2xl font-bold text-[var(--color-text-main)]">{formatNumber(summary?.total || 0)}</p>
        <div className="mt-1 flex items-center gap-1.5 text-[9px] font-bold text-[var(--color-success)]">
          <div className="w-1.5 h-1.5 rounded-full bg-[var(--color-success)]" />
          {formatNumber(summary?.active || 0)} {t('userManagement.summary.active')}
        </div>
      </div>
      <div className="glass-card p-4 border-[var(--color-warning)]/20">
        <p className="text-[9px] font-bold text-[var(--color-text-muted)] uppercase tracking-wider mb-0.5">{t('userManagement.summary.suspendedUsers')}</p>
        <p className="text-2xl font-bold text-[var(--color-text-main)]">{formatNumber(summary?.suspended || 0)}</p>
        <div className="mt-1 text-[9px] font-bold text-[var(--color-warning)]">
          {t('userManagement.summary.requiresReview')}
        </div>
      </div>
      <div className="glass-card p-4 border-[var(--color-danger)]/20">
        <p className="text-[9px] font-bold text-[var(--color-text-muted)] uppercase tracking-wider mb-0.5">{t('userManagement.summary.lockedAccounts')}</p>
        <p className="text-2xl font-bold text-[var(--color-text-main)]">{formatNumber(summary?.locked || 0)}</p>
        <div className="mt-1 text-[9px] font-bold text-[var(--color-danger)]">
          {t('userManagement.summary.dueToFailedAttempts')}
        </div>
      </div>
      <div className="glass-card p-4 border-[var(--color-border-soft)]">
        <p className="text-[9px] font-bold text-[var(--color-text-muted)] uppercase tracking-wider mb-0.5">{t('userManagement.summary.departments')}</p>
        <p className="text-2xl font-bold text-[var(--color-text-main)]">{formatNumber(summary?.departments_count || 0)}</p>
        <div className="mt-1 text-[9px] font-bold text-[var(--color-text-muted)]">
          {t('userManagement.summary.fullCoverage')}
        </div>
      </div>
    </div>
  );
};

export default UserSummaryCards;

import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useUserManagement } from '../../hooks/useUserManagement';
import { userService } from '../../services/userService';
import { ROLES } from '../../permissions';
import { UserManagementTab, AccessScope } from '../../constants';
import { useFormat } from '../../services/formatService';
import { useDebounce } from '../../hooks/useDebounce';
import api from '../../services/api';
import { extractErrorMessage } from '../../services/errorService';
import toast from 'react-hot-toast';
import logger from '../../utils/logger';

// Sub-components
import UserManagementHeader from './UserManagementHeader';
import UserSummaryCards from './UserSummaryCards';
import UserList from './UserList';
import UserForm from './UserForm';
import RolePermissions from './RolePermissions';
import ResetRequests from './ResetRequests';
import SupportRequests from './SupportRequests';
import UserSessions from './UserSessions';
import HistoryLogs from './HistoryLogs';
import ManagementSettings from './ManagementSettings';
import UserDetailsModal from './UserDetailsModal';
import ConfirmationModal from './ConfirmationModal';
import Pagination from '../../components/Pagination';

const UserManagement: React.FC = () => {
  const { t, i18n } = useTranslation();
  const { translateStatus, formatDateTime, translateName } = useFormat();
  
  // State
  const [searchTerm, setSearchTerm] = useState('');
  const debouncedSearchTerm = useDebounce(searchTerm, 500);
  const [activeTab, setActiveTab] = useState<UserManagementTab>(UserManagementTab.USERS);
  const [filterDept, setFilterDept] = useState('All');
  const [filterRole, setFilterRole] = useState('All');
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);
  const [historyPage, setHistoryPage] = useState(1);
  const [auditPage, setAuditPage] = useState(1);

  // Use custom hook for data management
  const {
    users,
    summary,
    roles: allRoles,
    permissions: allPermissions,
    sessions,
    settings: managementSettings,
    loginHistory,
    auditTrail: activityLogs,
    resetRequests,
    departments: allDepartments,
    jobTitles: allJobTitles,
    loading,
    error,
    pagination: userPagination,
    historyPagination,
    activityPagination,
    refreshAll,
    updateUser
  } = useUserManagement({
    page: currentPage,
    pageSize: pageSize,
    search: debouncedSearchTerm,
    department: filterDept !== 'All' ? filterDept : undefined,
    role: filterRole !== 'All' ? filterRole : undefined,
    historyPage,
    auditPage
  });

  // State for modals and UI
  const [selectedUserForDetails, setSelectedUserForDetails] = useState<any>(null);
  const [showUserDetails, setShowUserDetails] = useState(false);
  const [showAddUser, setShowAddUser] = useState(false);
  const [editingUser, setEditingUser] = useState<any>(null);
  const [newUser, setNewUser] = useState({ 
    username: '', 
    password: '', 
    name: '', 
    email: '', 
    department: '', 
    job_title_id: '', 
    role: ROLES.VIEWER,
    unit: '',
    reporting_manager_id: '',
    access_scope: AccessScope.GLOBAL,
    phone_number: '',
    notes: ''
  });
  const [showResetConfirm, setShowResetConfirm] = useState(false);
  const [selectedRequestId, setSelectedRequestId] = useState<string | number | null>(null);
  const [tempPassword, setTempPassword] = useState('');
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [showSuspendConfirm, setShowSuspendConfirm] = useState(false);
  const [showResetPassword, setShowResetPassword] = useState(false);
  const [showUnlockConfirm, setShowUnlockConfirm] = useState(false);
  const [selectedUserId, setSelectedUserId] = useState<string | null>(null);
  const [resetPasswordValue, setResetPasswordValue] = useState('');
  const [userError, setUserError] = useState('');
  const [resetError, setResetError] = useState('');
  const [resetSuccess, setResetSuccess] = useState('');
  const [unlockError, setUnlockError] = useState('');
  const [showSaveSuccess, setShowSaveSuccess] = useState(false);
  const [isSavingUser, setIsSavingUser] = useState(false);
  
  // Labels
  const getRoleLabel = (role: string) => {
    const roleMapping: Record<string, string> = {
      [ROLES.ADMIN]: 'admin',
      [ROLES.INTERNAL_AUDITOR]: 'internalAuditor',
      [ROLES.COMPLIANCE_OFFICER]: 'complianceOfficer',
      [ROLES.RISK_OFFICER]: 'riskOfficer',
      [ROLES.MANAGER]: 'manager',
      [ROLES.VIEWER]: 'viewer',
    };
    return t(`roles.${roleMapping[role] || 'viewer'}`);
  };

  const getPermissionLabel = (perm: string) => {
    const permMapping: Record<string, string> = {
      'view': t('permissions.View'),
      'create': t('permissions.Create'),
      'edit': t('permissions.Edit'),
      'delete': t('permissions.Delete'),
      'approve': t('permissions.Approve'),
    };
    return permMapping[(perm || '').toLowerCase()] || perm;
  };

  // Handlers
  const handleSavePermissions = async (modifiedRoles: any[]) => {
    try {
      const promises = modifiedRoles.map(modifiedRole => {
        const newPermIds = [...new Set((modifiedRole.permissions || []).map((p: any) => p.id))];
        return userService.updateRolePermissions(modifiedRole.id, { permissionIds: newPermIds });
      });

      await Promise.all(promises);
      
      toast.success(t('updateSuccess'));
      refreshAll();
    } catch (err: any) {
      logger.error('Error updating permissions:', err);
      refreshAll();
      toast.error(t('userManagement.permissionUpdateFailed'));
    }
  };

  const handleUpdateSettings = async (newSettings: any) => {
    try {
      await userService.updateSettings(newSettings);
      setShowSaveSuccess(true);
      setTimeout(() => setShowSaveSuccess(false), 3000);
      toast.success(t('updateSuccess'));
      refreshAll();
    } catch (err) { 
      logger.error('Operation failed', err);
      toast.error(t('errorOccurred'));
    }
  };

  const handleRevokeSession = async (sessionId: string | number) => {
    try {
      await userService.revokeSession(sessionId);
      refreshAll();
    } catch (err) { logger.error('Operation failed', err); }
  };

  const handleExportUsers = () => {
    const headers = [t('common.id'), t('common.username'), t('common.name'), t('common.email'), t('common.role'), t('common.department'), t('common.statusLabel'), t('common.lastLogin')];
    const rows = users.map(u => [
      u.id, u.username, translateName(u.name), u.email, getRoleLabel(u.role), u.department, translateStatus(u.status), u.last_login ? formatDateTime(u.last_login) : t('common.never')
    ]);
    const csvContent = "data:text/csv;charset=utf-8," 
      + headers.join(",") + "\n"
      + rows.map(e => e.join(",")).join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "users_report.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleSaveUser = async () => {
    setUserError('');
    if (!editingUser && newUser.password.length < 8) {
      setUserError(t('common.passwordTooShort'));
      return;
    }
    if (!newUser.username || !newUser.name || !newUser.email || !newUser.department || !newUser.role) {
      setUserError(t('common.fillAllFields'));
      return;
    }
    
    setIsSavingUser(true);
    try {
      const payload: any = {
        ...newUser,
        job_title_id: newUser.job_title_id || null,
        reporting_manager_id: newUser.reporting_manager_id || null
      };

      // Remove password if empty during edit
      if (editingUser && !newUser.password) {
        delete payload.password;
      }

      if (editingUser) {
        await userService.updateUser(editingUser.id, payload);
        toast.success(t('updateSuccess'));
      } else {
        await userService.createUser(payload);
        toast.success(t('createSuccess'));
      }
      
      refreshAll();
      setShowAddUser(false);
      setEditingUser(null);
      setNewUser({ 
        username: '', password: '', name: '', email: '', department: '', 
        job_title_id: '', role: ROLES.VIEWER, unit: '', reporting_manager_id: '',
        access_scope: AccessScope.GLOBAL, phone_number: '', notes: ''
      });
    } catch (err: any) {
      logger.error('Operation failed', err);
      setUserError(extractErrorMessage(err, t('userManagement.errorSavingUser')));
    } finally {
      setIsSavingUser(false);
    }
  };

  const handleEditUser = (user: any) => {
    setEditingUser(user);
    setNewUser({ 
      username: user.username || '',
      password: '', 
      name: user.name || '',
      email: user.email || '',
      department: user.department || '',
      job_title_id: user.job_title_id ? user.job_title_id.toString() : '',
      role: user.role || ROLES.VIEWER,
      unit: user.unit || '',
      reporting_manager_id: user.reporting_manager_id ? user.reporting_manager_id.toString() : '',
      access_scope: user.access_scope || AccessScope.GLOBAL,
      phone_number: user.phone_number || '',
      notes: user.notes || ''
    });
    setShowAddUser(true);
  };

  const handleConfirmSuspend = async () => {
    if (!selectedUserId) return;
    try {
      await userService.suspendUser(selectedUserId);
      toast.success(t('updateSuccess'));
      refreshAll();
    } catch (err) { 
      logger.error('Operation failed', err);
      toast.error(t('errorOccurred'));
    }
    setShowSuspendConfirm(false);
    setSelectedUserId(null);
  };

  const handleConfirmDelete = async () => {
    if (!selectedUserId) return;
    try {
      await userService.deleteUser(selectedUserId);
      toast.success(t('deleteSuccess'));
      refreshAll();
    } catch (err) { 
      logger.error('Operation failed', err);
      toast.error(t('errorOccurred'));
    }
    setShowDeleteConfirm(false);
    setSelectedUserId(null);
  };

  const handleConfirmResetPassword = async () => {
    setResetError('');
    setResetSuccess('');
    if (!selectedUserId || !resetPasswordValue) return;
    if (resetPasswordValue.length < 8) {
      setResetError(t('auth.passwordTooShort'));
      return;
    }
    try {
      await userService.resetPassword(selectedUserId, { newPassword: resetPasswordValue });
      toast.success(t('userManagement.resetPassword'));
      setTimeout(() => {
        setShowResetPassword(false);
        setSelectedUserId(null);
        setResetPasswordValue('');
      }, 2000);
    } catch (err) { 
      toast.error(t('userManagement.errorResettingPassword'));
    }
  };

  const handleConfirmUnlock = async () => {
    setUnlockError('');
    if (!selectedUserId) return;
    try {
      await userService.unlockUser(selectedUserId);
      toast.success(t('updateSuccess'));
      refreshAll();
      setShowUnlockConfirm(false);
      setSelectedUserId(null);
    } catch (err) {
      logger.error('Operation failed', err);
      toast.error(t('userManagement.errorUnlockingUser'));
    }
  };

  const handleApproveReset = async (requestId: string | number) => {
    try {
      await userService.approveReset({ requestId });
      refreshAll();
    } catch (err) { logger.error('Operation failed', err); }
  };

  const handleConfirmApproveReset = async () => {
    if (!selectedRequestId) return;
    try {
      const res = await api.post('/auth/approve-reset', { requestId: selectedRequestId });
      setTempPassword(res.data.tempPassword);
      refreshAll();
      setShowResetConfirm(false);
    } catch (err) { logger.error('Operation failed', err); }
  };

  const filteredUsers = users;

  return (
    <div className="space-y-10 animate-in fade-in duration-700" dir={i18n.dir()}>
      <UserManagementHeader 
        activeTab={activeTab}
        searchTerm={searchTerm}
        resetRequestsCount={resetRequests.length}
        onTabChange={setActiveTab}
        onSearchChange={setSearchTerm}
        onExport={handleExportUsers}
        onAddUser={() => {
          setEditingUser(null);
          setNewUser({ 
            username: '', password: '', name: '', email: '', department: '', 
            job_title_id: '', role: ROLES.VIEWER, unit: '', reporting_manager_id: '',
            access_scope: AccessScope.GLOBAL, phone_number: '', notes: ''
          });
          setShowAddUser(true);
        }}
      />

      {activeTab === UserManagementTab.USERS && (
        <div className="space-y-4">
          {summary && <UserSummaryCards summary={summary} />}
          
          {showAddUser ? (
            <UserForm 
              editingUser={editingUser}
              newUser={newUser}
              userError={userError}
              jobTitles={allJobTitles}
              users={users}
              allRoles={allRoles}
              isLoading={isSavingUser}
              getRoleLabel={getRoleLabel}
              onCancel={() => {
                setShowAddUser(false);
                setEditingUser(null);
                setUserError('');
              }}
              onSave={handleSaveUser}
              onUpdateNewUser={(data) => setNewUser(prev => ({ ...prev, ...data }))}
            />
          ) : (
            <div className="space-y-4">
              <UserList 
                users={filteredUsers}
                getRoleLabel={getRoleLabel}
                onEdit={handleEditUser}
                onSuspend={(id) => { setSelectedUserId(id); setShowSuspendConfirm(true); }}
                onDelete={(id) => { setSelectedUserId(id); setShowDeleteConfirm(true); }}
                onResetPassword={(id) => { setSelectedUserId(id); setResetPasswordValue(''); setShowResetPassword(true); }}
                onUnlock={(id) => { setSelectedUserId(id); setShowUnlockConfirm(true); }}
              />

              <Pagination 
                currentPage={userPagination.page}
                totalPages={userPagination.totalPages}
                onPageChange={(page) => setCurrentPage(page)}
                pageSize={userPagination.pageSize}
                onPageSizeChange={(size) => { setPageSize(size); setCurrentPage(1); }}
                totalItems={userPagination.total}
              />
            </div>
          )}
        </div>
      )}


      {activeTab === UserManagementTab.ROLES && (
        <RolePermissions 
          allRoles={allRoles}
          allPermissions={allPermissions}
          showSaveSuccess={showSaveSuccess}
          getRoleLabel={getRoleLabel}
          onSave={handleSavePermissions}
        />
      )}

      {activeTab === UserManagementTab.RESETS && (
        <ResetRequests 
          requests={resetRequests}
          tempPassword={tempPassword}
          onApprove={(id) => { setSelectedRequestId(id); setShowResetConfirm(true); }}
        />
      )}

      {activeTab === UserManagementTab.SUPPORT_REQUESTS && (
        <SupportRequests />
      )}

      {activeTab === UserManagementTab.SESSIONS && (
        <UserSessions 
          sessions={sessions}
          onRevoke={handleRevokeSession}
        />
      )}

      {activeTab === UserManagementTab.HISTORY && (
        <HistoryLogs 
          loginHistory={loginHistory}
          activityLogs={activityLogs}
          historyPagination={historyPagination}
          activityPagination={activityPagination}
          onHistoryPageChange={(page) => setHistoryPage(page)}
          onHistoryPageSizeChange={(size) => { setHistoryPage(1); /* In case size change resets to page 1 */ }} 
          onActivityPageChange={(page) => setAuditPage(page)}
          onActivityPageSizeChange={(size) => { setAuditPage(1); }}
        />
      )}

      {activeTab === UserManagementTab.SETTINGS && (
        <ManagementSettings 
          settings={managementSettings}
          onUpdate={handleUpdateSettings}
          showSuccess={showSaveSuccess}
        />
      )}

      {/* Modals */}
      <UserDetailsModal 
        user={selectedUserForDetails}
        onClose={() => { setShowUserDetails(false); setSelectedUserForDetails(null); }}
      />

      <ConfirmationModal 
        isOpen={showDeleteConfirm}
        title={t('userManagement.deleteUser')}
        message={t('userManagement.deleteUserConfirm')}
        confirmLabel={t('common.delete')}
        confirmVariant="danger"
        onClose={() => setShowDeleteConfirm(false)}
        onConfirm={handleConfirmDelete}
      />

      <ConfirmationModal 
        isOpen={showSuspendConfirm}
        title={t('userManagement.changeUserStatus')}
        message={t('userManagement.suspendUserConfirm')}
        confirmLabel={t('common.save')}
        confirmVariant="warning"
        onClose={() => setShowSuspendConfirm(false)}
        onConfirm={handleConfirmSuspend}
      />

      <ConfirmationModal 
        isOpen={showResetPassword}
        title={t('userManagement.resetPassword')}
        message={t('userManagement.enterNewPassword')}
        confirmLabel={t('userManagement.resetPassword')}
        onClose={() => setShowResetPassword(false)}
        onConfirm={handleConfirmResetPassword}
        error={resetError}
        success={resetSuccess}
      >
        <input 
          type="password"
          placeholder={t('userManagement.enterNewPassword')}
          className="input-field mb-4"
          value={resetPasswordValue}
          onChange={(e) => setResetPasswordValue(e.target.value)}
        />
      </ConfirmationModal>

      <ConfirmationModal 
        isOpen={showUnlockConfirm}
        title={t('userManagement.unlockUser')}
        message={t('userManagement.unlockUserConfirm')}
        confirmLabel={t('userManagement.unlockUser')}
        confirmVariant="success"
        onClose={() => setShowUnlockConfirm(false)}
        onConfirm={handleConfirmUnlock}
        error={unlockError}
      />

      <ConfirmationModal 
        isOpen={showResetConfirm}
        title={t('userManagement.approveResetRequest')}
        message={t('userManagement.resetPasswordConfirm')}
        confirmLabel={t('common.approve')}
        onClose={() => setShowResetConfirm(false)}
        onConfirm={handleConfirmApproveReset}
      />
    </div>
  );
};

