/**
 * Property-based tests for DB Auto-Seeder.
 *
 * Uses fast-check to verify seeding idempotency and completeness
 * across arbitrary module definitions and initial DB states.
 *
 * Tests use an in-memory mock DB that simulates the permissions
 * and role_permissions tables.
 */

import { describe, it, expect } from 'vitest';
import * as fc from 'fast-check';
import { seedModules, SeederDB } from '../seeder';
import { ModuleDefinition, PermissionAction } from '../types';
import { UserRole } from '../../constants';

// ─── Constants ─────────────────────────────────────────────────────────────────

const VALID_ACTIONS: PermissionAction[] = ['View', 'Create', 'Edit', 'Delete', 'Approve'];
const VALID_ROLES: string[] = Object.values(UserRole);

const UPPER_CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
const ALNUM_CHARS = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'.split('');

// ─── In-Memory Mock DB ─────────────────────────────────────────────────────────

interface PermissionRow {
  id: string;
  module: string;
  action: string;
  description: string;
}

interface RolePermissionRow {
  role_id: string;
  permission_id: string;
}

interface RoleRow {
  id: string;
  name: string;
}

/**
 * Creates an in-memory mock database that simulates the permissions,
 * role_permissions, and roles tables for testing the seeder.
 */
function createMockDB(options?: {
  initialPermissions?: PermissionRow[];
  initialRolePermissions?: RolePermissionRow[];
  roles?: RoleRow[];
}): SeederDB & {
  getPermissions(): PermissionRow[];
  getRolePermissions(): RolePermissionRow[];
} {
  let idCounter = 0;
  const permissions: PermissionRow[] = [...(options?.initialPermissions || [])];
  const rolePermissions: RolePermissionRow[] = [...(options?.initialRolePermissions || [])];
  const roles: RoleRow[] = options?.roles || VALID_ROLES.map((name, i) => ({
    id: `role-${i + 1}`,
    name,
  }));

  return {
    getPermissions: () => [...permissions],
    getRolePermissions: () => [...rolePermissions],

    prepare(sql: string) {
      return {
        async all(..._params: any[]): Promise<any[]> {
          if (sql.includes('SELECT module, action FROM permissions')) {
            return permissions.map((p) => ({ module: p.module, action: p.action }));
          }
          return [];
        },

        async get(...params: any[]): Promise<any> {
          if (sql.includes('INSERT INTO permissions')) {
            // Insert a new permission and return its id
            const newId = `perm-${++idCounter}`;
            const [module, action, description] = params;
            permissions.push({ id: newId, module, action, description });
            return { id: newId };
          }

          if (sql.includes('SELECT id FROM roles WHERE name')) {
            const [roleName] = params;
            const role = roles.find((r) => r.name === roleName);
            return role ? { id: role.id } : undefined;
          }

          return undefined;
        },

        async run(...params: any[]): Promise<{ lastInsertRowid: any; changes: number }> {
          if (sql.includes('INSERT INTO role_permissions')) {
            const [roleId, permissionId] = params;
            // ON CONFLICT DO NOTHING - check for duplicates
            const exists = rolePermissions.some(
              (rp) => rp.role_id === roleId && rp.permission_id === permissionId
            );
            if (!exists) {
              rolePermissions.push({ role_id: roleId, permission_id: permissionId });
              return { lastInsertRowid: 0, changes: 1 };
            }
            return { lastInsertRowid: 0, changes: 0 };
          }
          return { lastInsertRowid: 0, changes: 0 };
        },
      };
    },
  };
}

// ─── Arbitraries ───────────────────────────────────────────────────────────────

/** Generates a valid PascalCase name (1-20 chars for test efficiency) */
const validPascalCaseName = fc
  .tuple(
    fc.constantFrom(...UPPER_CHARS),
    fc.string({ unit: fc.constantFrom(...ALNUM_CHARS), minLength: 0, maxLength: 15 })
  )
  .map(([first, rest]) => first + rest);

/** Generates a valid non-empty actions array (subset of VALID_ACTIONS) */
const validActionsArray = fc
  .subarray(VALID_ACTIONS, { minLength: 1, maxLength: 5 })
  .map((arr) => [...new Set(arr)] as PermissionAction[]);

/** Generates valid defaults (keys are valid roles, values are subsets of provided actions) */
function validDefaultsFor(actions: PermissionAction[]) {
  return fc
    .subarray(VALID_ROLES, { minLength: 0, maxLength: 6 })
    .chain((roles) =>
      fc.tuple(
        fc.constant(roles),
        fc.array(
          fc.subarray(actions, { minLength: 1, maxLength: actions.length }),
          { minLength: roles.length, maxLength: roles.length }
        )
      )
    )
    .map(([roles, actionArrays]) => {
      const defaults: Record<string, PermissionAction[]> = {};
      roles.forEach((role, i) => {
        defaults[role] = actionArrays[i] as PermissionAction[];
      });
      return defaults;
    });
}

/** Generates a valid ModuleDefinition */
const validModuleDefinition: fc.Arbitrary<ModuleDefinition> = validActionsArray.chain(
  (actions) =>
    fc
      .tuple(
        validPascalCaseName,
        fc.record({
          en: fc.string({ unit: fc.constantFrom(...'abcdefghijklmnopqrstuvwxyz '.split('')), minLength: 1, maxLength: 30 }),
          ar: fc.string({ unit: fc.constantFrom(...'abcdefghijklmnopqrstuvwxyz '.split('')), minLength: 1, maxLength: 30 }),
        }),
        fc.constant(actions),
        validDefaultsFor(actions)
      )
      .map(([name, label, acts, defaults]): ModuleDefinition => ({
        name,
        label,
        actions: acts,
        defaults,
      }))
);

/** Generates a list of unique module definitions (deduplicated by name) */
const uniqueModuleDefinitions = fc
  .array(validModuleDefinition, { minLength: 1, maxLength: 6 })
  .map(deduplicateByName);

/**
 * Generates an initial DB state: a subset of module-action pairs that already exist.
 * This simulates a DB that has been partially seeded before.
 */
function initialDBStateFor(modules: ModuleDefinition[]) {
  // Collect all possible (module, action) pairs
  const allPairs = modules.flatMap((m) =>
    m.actions.map((a) => ({ module: m.name, action: a }))
  );

  // Pick a random subset to already exist in DB
  return fc.subarray(allPairs, { minLength: 0, maxLength: allPairs.length });
}

// ─── Property Tests ────────────────────────────────────────────────────────────

describe('DB Auto-Seeder Property Tests', () => {
  /**
   * **Validates: Requirements 2.4, 2.5, 2.6**
   *
   * Property 3: Seeding Idempotency
   * For any set of module definitions and any initial database state,
   * running seedModules() N times (N ≥ 1) produces the same database state
   * as running it once, and the sum of added + skipped in the result equals
   * the total number of module-action pairs.
   */
  describe('Property 3: Seeding Idempotency', () => {
    it('running seed N times produces same DB state as running once', async () => {
      await fc.assert(
        fc.asyncProperty(
          uniqueModuleDefinitions.chain((modules) =>
            fc.tuple(fc.constant(modules), initialDBStateFor(modules))
          ),
          fc.integer({ min: 2, max: 4 }),
          async ([modules, initialPairs], n) => {
            // Create initial DB state with some permissions already existing
            const initialPermissions: PermissionRow[] = initialPairs.map((p, i) => ({
              id: `existing-${i}`,
              module: p.module,
              action: p.action,
              description: `${p.action} existing`,
            }));

            // Run seed once and capture state S1
            const db1 = createMockDB({ initialPermissions: [...initialPermissions] });
            await seedModules(db1, modules);
            const stateS1Perms = db1.getPermissions();
            const stateS1RolePerms = db1.getRolePermissions();

            // Run seed N times starting from same initial state
            const dbN = createMockDB({ initialPermissions: [...initialPermissions] });
            for (let i = 0; i < n; i++) {
              await seedModules(dbN, modules);
            }
            const stateSNPerms = dbN.getPermissions();
            const stateSNRolePerms = dbN.getRolePermissions();

            // S1 === SN: same permissions (by module:action keys)
            const s1PermKeys = new Set(stateS1Perms.map((p) => `${p.module}:${p.action}`));
            const sNPermKeys = new Set(stateSNPerms.map((p) => `${p.module}:${p.action}`));
            expect(s1PermKeys).toEqual(sNPermKeys);

            // S1 === SN: same number of role_permissions
            expect(stateS1RolePerms.length).toBe(stateSNRolePerms.length);
          }
        ),
        { numRuns: 80 }
      );
    });

    it('added + skipped equals total module-action pairs', async () => {
      await fc.assert(
        fc.asyncProperty(
          uniqueModuleDefinitions.chain((modules) =>
            fc.tuple(fc.constant(modules), initialDBStateFor(modules))
          ),
          async ([modules, initialPairs]) => {
            const initialPermissions: PermissionRow[] = initialPairs.map((p, i) => ({
              id: `existing-${i}`,
              module: p.module,
              action: p.action,
              description: `${p.action} existing`,
            }));

            const mockDb = createMockDB({ initialPermissions });
            const result = await seedModules(mockDb, modules);

            // Total module-action pairs across all modules
            const totalPairs = modules.reduce(
              (sum, m) => sum + m.actions.length,
              0
            );

            // added + skipped must equal total pairs
            expect(result.added.length + result.skipped.length).toBe(totalPairs);
          }
        ),
        { numRuns: 120 }
      );
    });
  });

  /**
   * **Validates: Requirements 2.2, 2.3**
   *
   * Property 4: Seeding Completeness
   * For any module definition in the registry, after seeding completes,
   * the permissions table contains a record for every (module, action) pair,
   * and the role_permissions table contains entries matching the module's
   * defaults configuration for each new permission.
   */
  describe('Property 4: Seeding Completeness', () => {
    it('after seeding, all module-action pairs exist in permissions table', async () => {
      await fc.assert(
        fc.asyncProperty(uniqueModuleDefinitions, async (modules) => {
          const mockDb = createMockDB();
          await seedModules(mockDb, modules);

          const permissions = mockDb.getPermissions();
          const permKeys = new Set(
            permissions.map((p) => `${p.module}:${p.action}`)
          );

          // Every module-action pair from the definitions must exist
          for (const mod of modules) {
            for (const action of mod.actions) {
              const key = `${mod.name}:${action}`;
              expect(permKeys.has(key)).toBe(true);
            }
          }
        }),
        { numRuns: 120 }
      );
    });

    it('after seeding, role_permissions entries match module defaults for new permissions', async () => {
      await fc.assert(
        fc.asyncProperty(uniqueModuleDefinitions, async (modules) => {
          const roles = VALID_ROLES.map((name, i) => ({
            id: `role-${i + 1}`,
            name,
          }));

          const mockDb = createMockDB({ roles });
          await seedModules(mockDb, modules);

          const permissions = mockDb.getPermissions();
          const rolePerms = mockDb.getRolePermissions();

          // For each module and each role in its defaults
          for (const mod of modules) {
            for (const [roleName, roleActions] of Object.entries(mod.defaults)) {
              const role = roles.find((r) => r.name === roleName);
              if (!role) continue;

              for (const action of roleActions as PermissionAction[]) {
                // Find the permission record for this module:action
                const permRecord = permissions.find(
                  (p) => p.module === mod.name && p.action === action
                );
                expect(permRecord).toBeDefined();

                if (permRecord) {
                  // A role_permissions entry should exist for this role + permission
                  const hasRolePerm = rolePerms.some(
                    (rp) =>
                      rp.role_id === role.id &&
                      rp.permission_id === permRecord.id
                  );
                  expect(hasRolePerm).toBe(true);
                }
              }
            }
          }
        }),
        { numRuns: 80 }
      );
    });

    it('seeding with pre-existing permissions does not duplicate them', async () => {
      await fc.assert(
        fc.asyncProperty(
          uniqueModuleDefinitions.chain((modules) =>
            fc.tuple(fc.constant(modules), initialDBStateFor(modules))
          ),
          async ([modules, initialPairs]) => {
            const initialPermissions: PermissionRow[] = initialPairs.map((p, i) => ({
              id: `existing-${i}`,
              module: p.module,
              action: p.action,
              description: `${p.action} existing`,
            }));

            const mockDb = createMockDB({ initialPermissions });
            await seedModules(mockDb, modules);

            const permissions = mockDb.getPermissions();

            // Check no duplicate (module, action) pairs
            const permKeys = permissions.map((p) => `${p.module}:${p.action}`);
            const uniqueKeys = new Set(permKeys);
            expect(permKeys.length).toBe(uniqueKeys.size);
          }
        ),
        { numRuns: 100 }
      );
    });
  });
});

// ─── Helpers ───────────────────────────────────────────────────────────────────

/** Deduplicate module definitions by name, keeping the first occurrence */
function deduplicateByName(definitions: ModuleDefinition[]): ModuleDefinition[] {
  const seen = new Set<string>();
  return definitions.filter((def) => {
    if (seen.has(def.name)) return false;
    seen.add(def.name);
    return true;
  });
}

/**
 * Module Registry - Single source of truth for all permission modules.
 *
 * This registry stores module definitions and provides retrieval methods
 * for all consumers: DB seeder, middleware, frontend navigation, and admin UI.
 */

import { ModuleDefinition, NavigationConfig, PermissionAction } from './types';
import { UserRole } from '../constants';

/** Navigation item returned by getNavigationConfig() */
export interface NavigationItem {
  module: string;
  label: { en: string; ar: string };
  icon: string;
  path: string;
  order: number;
  parent?: string;
}

/** Valid PermissionAction values for validation */
const VALID_ACTIONS: PermissionAction[] = ['View', 'Create', 'Edit', 'Delete', 'Approve'];

/** Valid built-in role names */
const VALID_ROLES: string[] = Object.values(UserRole);

/** PascalCase pattern: starts with uppercase letter, followed by alphanumeric */
const PASCAL_CASE_PATTERN = /^[A-Z][a-zA-Z0-9]*$/;

/** Maximum module name length */
const MAX_NAME_LENGTH = 50;

/** Maximum label length */
const MAX_LABEL_LENGTH = 100;

export class ModuleRegistryImpl {
  private modules: Map<string, ModuleDefinition> = new Map();

  /**
   * Register a module definition with full validation.
   * Throws descriptive errors on validation failure.
   */
  register(definition: ModuleDefinition): void {
    this.validateDefinition(definition);
    this.modules.set(definition.name, definition);
  }

  /**
   * Get a module definition by name.
   * Returns undefined if the module is not registered.
   */
  getModule(name: string): ModuleDefinition | undefined {
    return this.modules.get(name);
  }

  /**
   * Get all registered module definitions.
   */
  getAllModules(): ModuleDefinition[] {
    return Array.from(this.modules.values());
  }

  /**
   * Get all registered module names.
   */
  getModuleNames(): string[] {
    return Array.from(this.modules.keys());
  }

  /**
   * Get default permissions for a given role across all registered modules.
   * Returns an empty object for unknown roles (never throws).
   */
  getDefaultPermissions(role: string): Record<string, PermissionAction[]> {
    const result: Record<string, PermissionAction[]> = {};

    for (const [name, mod] of this.modules) {
      const actions = mod.defaults[role];
      if (actions && actions.length > 0) {
        result[name] = [...actions];
      }
    }

    return result;
  }

  /**
   * Get navigation configuration for all modules that have navigation defined.
   * Returns items sorted by order.
   */
  getNavigationConfig(): NavigationItem[] {
    const items: NavigationItem[] = [];

    for (const mod of this.modules.values()) {
      if (mod.navigation) {
        items.push({
          module: mod.name,
          label: mod.label,
          icon: mod.navigation.icon,
          path: mod.navigation.path,
          order: mod.navigation.order,
          parent: mod.navigation.parent,
        });
      }
    }

    return items.sort((a, b) => a.order - b.order);
  }

  /**
   * Validate a module definition. Throws on any validation failure.
   */
  private validateDefinition(definition: ModuleDefinition): void {
    const { name, label, actions, defaults, navigation } = definition;

    // Validate name: unique, PascalCase, 1-50 chars
    if (!name || name.length > MAX_NAME_LENGTH || !PASCAL_CASE_PATTERN.test(name)) {
      throw new Error(
        `Invalid module name: '${name}'. Must be PascalCase (^[A-Z][a-zA-Z0-9]*$) and between 1 and 50 characters.`
      );
    }

    if (this.modules.has(name)) {
      throw new Error(`Module '${name}' already registered.`);
    }

    // Validate labels: both en and ar required, 1-100 chars each
    if (!label || !label.en || label.en.length === 0 || label.en.length > MAX_LABEL_LENGTH) {
      throw new Error(
        `Module '${name}': English label is required and must be between 1 and 100 characters.`
      );
    }
    if (!label.ar || label.ar.length === 0 || label.ar.length > MAX_LABEL_LENGTH) {
      throw new Error(
        `Module '${name}': Arabic label is required and must be between 1 and 100 characters.`
      );
    }

    // Validate actions: non-empty, valid values
    if (!actions || actions.length === 0) {
      throw new Error(
        `Module '${name}' must have at least one action.`
      );
    }

    for (const action of actions) {
      if (!VALID_ACTIONS.includes(action)) {
        throw new Error(
          `Module '${name}': Invalid action '${action}'. Valid actions are: ${VALID_ACTIONS.join(', ')}.`
        );
      }
    }

    // Validate defaults: role references must be valid built-in roles
    if (defaults) {
      for (const roleName of Object.keys(defaults)) {
        if (!VALID_ROLES.includes(roleName)) {
          throw new Error(
            `Module '${name}': Invalid role '${roleName}' in defaults. Valid roles are: ${VALID_ROLES.join(', ')}.`
          );
        }
      }
    }

    // Validate navigation path: must start with '/'
    if (navigation && navigation.path) {
      if (!navigation.path.startsWith('/')) {
        throw new Error(
          `Module '${name}': Navigation path must start with '/'. Got: '${navigation.path}'.`
        );
      }
    }
  }

  /**
   * Reset the registry (useful for testing).
   */
  _reset(): void {
    this.modules.clear();
  }
}

/** Singleton ModuleRegistry instance */
export const ModuleRegistry = new ModuleRegistryImpl();

/**
 * DB Auto-Seeder - Synchronizes ModuleRegistry definitions into the database.
 *
 * On application startup, compares registry definitions against existing DB
 * permission records and inserts any missing (module, action) pairs along with
 * their default role_permissions entries.
 *
 * Key behaviors:
 * - Idempotent: running multiple times produces the same DB state
 * - Existing permissions are never modified
 * - Missing roles referenced in defaults are logged as warnings (not errors)
 * - DB connection failures are caught and logged, allowing the app to start
 *
 * Requirements: 2.1, 2.2, 2.3, 2.4, 2.5, 2.6, 2.7, 2.8
 */

import { db } from '../server/db/index';
import { ModuleRegistry } from './registry';
import { ModuleDefinition, PermissionAction, SeedResult } from './types';

/**
 * Database abstraction interface for the seeder.
 * Allows injection of a mock DB for testing.
 */
export interface SeederDB {
  prepare(sql: string): {
    all(...params: any[]): Promise<any[]>;
    get(...params: any[]): Promise<any>;
    run(...params: any[]): Promise<{ lastInsertRowid: any; changes: number }>;
  };
}

/**
 * Seed modules into the database.
 *
 * Algorithm:
 * 1. Query all existing (module, action) pairs from the permissions table
 * 2. For each module in the provided definitions, for each action:
 *    a. If (module, action) already exists in DB → skip
 *    b. If not → INSERT into permissions table
 *    c. For each role in module.defaults that includes this action:
 *       - Look up role by name in roles table
 *       - If role exists → INSERT into role_permissions
 *       - If role doesn't exist → log warning
 * 3. Return SeedResult with added/skipped counts
 *
 * Preconditions:
 * - Database connection is active and permissions/roles tables exist
 *
 * Postconditions:
 * - Every (module, action) pair from the provided modules exists in permissions table
 * - Default role_permissions are created for new permissions only
 * - Existing permissions are unchanged (idempotent)
 *
 * @param database - Database instance (defaults to the app's db)
 * @param modules - Module definitions to seed (defaults to ModuleRegistry.getAllModules())
 */
export async function seedModules(
  database?: SeederDB,
  modules?: ModuleDefinition[]
): Promise<SeedResult> {
  const dbInstance = database || db;
  const registeredModules = modules || ModuleRegistry.getAllModules();

  try {
    const added: string[] = [];
    const skipped: string[] = [];

    // Step 1: Query all existing (module, action) pairs from DB (Req 2.1)
    const existingPermissions = (await dbInstance
      .prepare('SELECT module, action FROM permissions')
      .all()) as Array<{ module: string; action: string }>;

    const existingSet = new Set(
      existingPermissions.map((p) => `${p.module}:${p.action}`)
    );

    // Step 2: Process each module-action pair
    for (const moduleDef of registeredModules) {
      for (const action of moduleDef.actions) {
        const key = `${moduleDef.name}:${action}`;

        // Step 2a: Skip existing permissions (Req 2.4)
        if (existingSet.has(key)) {
          skipped.push(key);
          continue;
        }

        // Step 2b: Insert new permission record (Req 2.2)
        const description = `${action} ${moduleDef.label.en}`;
        const insertResult = await dbInstance
          .prepare(
            'INSERT INTO permissions (module, action, description) VALUES (?, ?, ?) RETURNING id'
          )
          .get(moduleDef.name, action, description);

        // If insert failed for any reason, treat as skipped
        if (!insertResult || !insertResult.id) {
          skipped.push(key);
          continue;
        }

        const permissionId = insertResult.id;

        // Step 2c: Create default role_permissions entries (Req 2.3)
        for (const [roleName, roleActions] of Object.entries(moduleDef.defaults)) {
          if (!(roleActions as PermissionAction[]).includes(action as PermissionAction)) {
            continue;
          }

          // Look up role by name
          const role = await dbInstance
            .prepare('SELECT id FROM roles WHERE name = ?')
            .get(roleName);

          if (!role) {
            // Req 2.8: Log warning if role doesn't exist
            console.warn(
              `[Seeder] Warning: Role '${roleName}' referenced in module '${moduleDef.name}' defaults does not exist in the database. Skipping role_permissions entry.`
            );
            continue;
          }

          // Insert role_permission entry
          await dbInstance
            .prepare(
              'INSERT INTO role_permissions (role_id, permission_id) VALUES (?, ?) ON CONFLICT DO NOTHING'
            )
            .run(role.id, permissionId);
        }

        added.push(key);
      }
    }

    // Step 3: Return result (Req 2.6)
    const result: SeedResult = {
      added,
      skipped,
      total: registeredModules.length,
    };

    console.log(
      `[Seeder] Seeding complete: ${added.length} added, ${skipped.length} skipped, ${registeredModules.length} modules processed.`
    );

    return result;
  } catch (error: any) {
    // Req 2.7: Handle DB connection failures gracefully
    console.error(
      `[Seeder] Error during permission seeding: ${error.message}. Application will continue with potentially incomplete permissions.`
    );

    // Return empty result to allow app to start
    return {
      added: [],
      skipped: [],
      total: 0,
    };
  }
}

// @vitest-environment node
import { describe, it, expect } from 'vitest';
import fc from 'fast-check';
import crypto from 'crypto';

/**
 * Property Test: Audit Trail Hash Chain Integrity (Property 1)
 *
 * Feature: comprehensive-testing
 * Property 1: سلسلة هاش التدقيق غير قابلة للتلاعب
 *
 * **Validates: Requirements 24.1, 24.2, 24.3, 24.4**
 *
 * For any sequence of audit trail records, if any field in an intermediate record
 * is modified, recomputing the hash chain will detect the tampering.
 *
 * Hash computation follows BaseService.logAudit:
 *   recordData = `${previousHash}|${username}|${action}|${module}|${details}|${timestamp}`
 *   hash = SHA-256(recordData)
 */

// ─── Helpers ─────────────────────────────────────────────────────────────────

interface AuditRecord {
  username: string;
  action: string;
  module: string;
  details: string;
  timestamp: string;
  hash: string;
  previous_hash: string;
}

/**
 * Computes the SHA-256 hash for an audit record, matching BaseService.logAudit logic.
 */
function computeAuditHash(
  previousHash: string,
  username: string,
  action: string,
  module: string,
  details: string,
  timestamp: string
): string {
  const recordData = `${previousHash}|${username}|${action}|${module}|${details}|${timestamp}`;
  return crypto.createHash('sha256').update(recordData).digest('hex');
}

/**
 * Builds a valid hash chain from raw audit data entries.
 */
function buildHashChain(
  entries: Array<{ username: string; action: string; module: string; details: string; timestamp: string }>
): AuditRecord[] {
  const records: AuditRecord[] = [];
  let previousHash = '0';

  for (const entry of entries) {
    const hash = computeAuditHash(
      previousHash,
      entry.username,
      entry.action,
      entry.module,
      entry.details,
      entry.timestamp
    );
    records.push({
      ...entry,
      hash,
      previous_hash: previousHash,
    });
    previousHash = hash;
  }

  return records;
}

/**
 * Verifies the integrity of a hash chain. Returns true if valid, false if tampered.
 */
function verifyHashChain(records: AuditRecord[]): boolean {
  for (let i = 0; i < records.length; i++) {
    const expectedPreviousHash = i === 0 ? '0' : records[i - 1].hash;
    if (records[i].previous_hash !== expectedPreviousHash) {
      return false;
    }
    const expectedHash = computeAuditHash(
      records[i].previous_hash,
      records[i].username,
      records[i].action,
      records[i].module,
      records[i].details,
      records[i].timestamp
    );
    if (records[i].hash !== expectedHash) {
      return false;
    }
  }
  return true;
}

// ─── Arbitraries ─────────────────────────────────────────────────────────────

/** Generates a valid username */
const usernameArb = fc.stringMatching(/^[a-zA-Z][a-zA-Z0-9_]{2,20}$/);

/** Generates a valid action string */
const actionArb = fc.constantFrom(
  'CREATE', 'UPDATE', 'DELETE', 'LOGIN', 'LOGOUT',
  'APPROVE', 'REJECT', 'ARCHIVE', 'RESTORE', 'EXPORT'
);

/** Generates a valid module string */
const moduleArb = fc.constantFrom(
  'AuditPlans', 'AuditTasks', 'RiskRegister', 'Compliance',
  'Correspondence', 'Users', 'Notifications', 'FraudLog',
  'Recommendations', 'Auth'
);

/** Generates a details string */
const detailsArb = fc.string({ minLength: 1, maxLength: 200 }).filter(s => s.trim().length > 0);

/** Generates an ISO timestamp string using integer milliseconds to avoid invalid date issues */
const timestampArb = fc.integer({
  min: new Date('2020-01-01').getTime(),
  max: new Date('2030-12-31').getTime(),
}).map(ms => new Date(ms).toISOString());

/** Generates a single audit entry (without hash fields) */
const auditEntryArb = fc.record({
  username: usernameArb,
  action: actionArb,
  module: moduleArb,
  details: detailsArb,
  timestamp: timestampArb,
});

/** Generates a sequence of audit entries */
const auditSequenceArb = (minLength: number, maxLength: number) =>
  fc.array(auditEntryArb, { minLength, maxLength });

// ─── Tests ───────────────────────────────────────────────────────────────────

describe('Property 1: Audit Trail Hash Chain Integrity', () => {
  it('each record\'s hash includes the previous record\'s hash', () => {
    fc.assert(
      fc.property(
        auditSequenceArb(2, 20),
        (entries) => {
          const records = buildHashChain(entries);

          for (let i = 1; i < records.length; i++) {
            // Each record's previous_hash must equal the prior record's hash
            expect(records[i].previous_hash).toBe(records[i - 1].hash);

            // Verify that changing the previous hash would produce a different hash
            const altHash = computeAuditHash(
              'tampered_previous_hash',
              records[i].username,
              records[i].action,
              records[i].module,
              records[i].details,
              records[i].timestamp
            );
            expect(altHash).not.toBe(records[i].hash);
          }
        }
      ),
      { numRuns: 100 }
    );
  });

  it('modifying any field in an intermediate record breaks the chain', () => {
    fc.assert(
      fc.property(
        auditSequenceArb(3, 20),
        fc.constantFrom('username', 'action', 'module', 'details', 'timestamp') as fc.Arbitrary<keyof Omit<AuditRecord, 'hash' | 'previous_hash'>>,
        fc.string({ minLength: 1, maxLength: 50 }).filter(s => s.trim().length > 0),
        (entries, fieldToModify, newValue) => {
          const records = buildHashChain(entries);

          // Pick a random intermediate record (not the last one, so chain continues after it)
          const targetIndex = Math.floor(entries.length / 2);

          // Tamper with the field
          const tamperedRecords = records.map((r, i) => ({ ...r }));
          (tamperedRecords[targetIndex] as any)[fieldToModify] = newValue + '_tampered';

          // Recompute expected hash for the tampered record
          const expectedHash = computeAuditHash(
            tamperedRecords[targetIndex].previous_hash,
            tamperedRecords[targetIndex].username,
            tamperedRecords[targetIndex].action,
            tamperedRecords[targetIndex].module,
            tamperedRecords[targetIndex].details,
            tamperedRecords[targetIndex].timestamp
          );

          // The stored hash no longer matches the recomputed hash
          expect(tamperedRecords[targetIndex].hash).not.toBe(expectedHash);

          // The chain is broken: verification fails
          expect(verifyHashChain(tamperedRecords)).toBe(false);
        }
      ),
      { numRuns: 100 }
    );
  });

  it('the first record uses \'0\' as previous hash', () => {
    fc.assert(
      fc.property(
        auditEntryArb,
        (entry) => {
          const records = buildHashChain([entry]);

          // First record must use '0' as previous_hash
          expect(records[0].previous_hash).toBe('0');

          // The hash must be computed with '0' as the previous hash
          const expectedHash = computeAuditHash(
            '0',
            entry.username,
            entry.action,
            entry.module,
            entry.details,
            entry.timestamp
          );
          expect(records[0].hash).toBe(expectedHash);
        }
      ),
      { numRuns: 100 }
    );
  });

  it('the hash includes all required fields (previousHash, username, action, module, details, timestamp)', () => {
    fc.assert(
      fc.property(
        auditSequenceArb(2, 10),
        (entries) => {
          const records = buildHashChain(entries);

          for (const record of records) {
            // Verify that changing any single field produces a different hash
            const fields = ['username', 'action', 'module', 'details', 'timestamp'] as const;

            for (const field of fields) {
              const modifiedValue = record[field] + '_modified';
              const modifiedHash = computeAuditHash(
                record.previous_hash,
                field === 'username' ? modifiedValue : record.username,
                field === 'action' ? modifiedValue : record.action,
                field === 'module' ? modifiedValue : record.module,
                field === 'details' ? modifiedValue : record.details,
                field === 'timestamp' ? modifiedValue : record.timestamp
              );

              // Each field contributes to the hash - changing it produces a different hash
              expect(modifiedHash).not.toBe(record.hash);
            }

            // Also verify that changing previous_hash produces a different hash
            const modifiedPrevHash = computeAuditHash(
              record.previous_hash + '_modified',
              record.username,
              record.action,
              record.module,
              record.details,
              record.timestamp
            );
            expect(modifiedPrevHash).not.toBe(record.hash);
          }
        }
      ),
      { numRuns: 100 }
    );
  });
});

