// @vitest-environment node
import { describe, it, expect, vi, beforeEach } from 'vitest';
import fc from 'fast-check';

/**
 * Property Test: Cron Notification Batching (Property 16)
 *
 * Feature: api-audit-improvements
 * Property 16: Cron Notification Batching
 *
 * **Validates: Requirements 9.2**
 *
 * For any set of overdue recommendations involving N distinct users, the
 * Cron_Scheduler SHALL produce exactly N notifications (one per user), each
 * containing the correct count of that user's overdue items.
 *
 * We test the core batching logic extracted from the cron job:
 * 1. Given overdue records with resolved user_ids, group by user
 * 2. Verify exactly N notifications are produced (one per distinct user)
 * 3. Verify each notification contains the correct count for that user
 * 4. Records where user_id is null (unresolved responsible) are skipped
 */

// ─── Extract the batching logic under test ───────────────────────────────────

interface OverdueRecord {
  id: string;
  responsible: string;
  finding_id: string;
  user_id: string | null;
}

interface NotificationCall {
  userId: string;
  type: string;
  message: string;
  module: string;
  link: string;
}

/**
 * Replicates the cron job's notification batching logic:
 * Groups overdue records by user_id, skips null user_ids,
 * and produces one notification per user with their overdue count.
 */
function batchNotifications(overdueWithUsers: OverdueRecord[]): NotificationCall[] {
  const userNotifications = new Map<string, number>();
  for (const rec of overdueWithUsers) {
    if (rec.user_id) {
      userNotifications.set(
        rec.user_id,
        (userNotifications.get(rec.user_id) || 0) + 1
      );
    }
  }

  const notifications: NotificationCall[] = [];
  for (const [userId, count] of userNotifications) {
    notifications.push({
      userId,
      type: 'recommendation_overdue',
      message: JSON.stringify({ key: 'notifications.recommendationsOverdue', params: { count } }),
      module: 'warning',
      link: '/recommendations',
    });
  }

  return notifications;
}

// ─── Custom Arbitraries ──────────────────────────────────────────────────────

/** Generates a valid UUID-like user ID */
const userIdArb = fc.uuid();

/** Generates a valid record ID */
const recordIdArb = fc.uuid();

/** Generates a responsible name string */
const responsibleArb = fc.string({ minLength: 1, maxLength: 50 }).filter(s => s.trim().length > 0);

/**
 * Generates a single overdue record with a resolved user_id.
 * The user_id is picked from a provided set of user IDs to control
 * the number of distinct users.
 */
function overdueRecordWithUserArb(userIds: string[]): fc.Arbitrary<OverdueRecord> {
  return fc.record({
    id: recordIdArb,
    responsible: responsibleArb,
    finding_id: recordIdArb,
    user_id: fc.constantFrom(...userIds),
  });
}

/**
 * Generates an overdue record with null user_id (unresolved responsible).
 */
const unresolvedRecordArb: fc.Arbitrary<OverdueRecord> = fc.record({
  id: recordIdArb,
  responsible: responsibleArb,
  finding_id: recordIdArb,
  user_id: fc.constant(null),
});

/**
 * Generates a set of N distinct user IDs and a list of overdue records
 * distributed among those users (with optional unresolved records).
 */
const overdueScenarioArb = fc
  .integer({ min: 1, max: 20 })
  .chain((numUsers) =>
    fc.tuple(
      // Generate N distinct user IDs
      fc.uniqueArray(userIdArb, { minLength: numUsers, maxLength: numUsers }),
      fc.constant(numUsers)
    )
  )
  .chain(([userIds, numUsers]) =>
    fc.tuple(
      fc.constant(userIds),
      fc.constant(numUsers),
      // Generate 1-50 resolved records distributed among the users
      fc.array(overdueRecordWithUserArb(userIds), { minLength: numUsers, maxLength: 50 }),
      // Generate 0-10 unresolved records
      fc.array(unresolvedRecordArb, { minLength: 0, maxLength: 10 })
    )
  );

// ─── Tests ───────────────────────────────────────────────────────────────────

describe('Property 16: Cron Notification Batching', () => {
  describe('batchNotifications produces exactly N notifications for N distinct users', () => {
    it('produces exactly one notification per distinct user with resolved user_id', () => {
      fc.assert(
        fc.property(overdueScenarioArb, ([userIds, _numUsers, resolvedRecords, unresolvedRecords]) => {
          const allRecords = [...resolvedRecords, ...unresolvedRecords];
          const notifications = batchNotifications(allRecords);

          // Count distinct user_ids that are non-null in the input
          const distinctUsersInInput = new Set(
            allRecords.filter(r => r.user_id !== null).map(r => r.user_id!)
          );

          // Exactly N notifications for N distinct users
          expect(notifications.length).toBe(distinctUsersInInput.size);

          // Each notification targets a unique user
          const notifiedUsers = new Set(notifications.map(n => n.userId));
          expect(notifiedUsers.size).toBe(notifications.length);

          // All notified users are from the input set
          for (const userId of notifiedUsers) {
            expect(distinctUsersInInput.has(userId)).toBe(true);
          }
        }),
        { numRuns: 300 }
      );
    });

    it('each notification contains the correct overdue count for that user', () => {
      fc.assert(
        fc.property(overdueScenarioArb, ([userIds, _numUsers, resolvedRecords, unresolvedRecords]) => {
          const allRecords = [...resolvedRecords, ...unresolvedRecords];
          const notifications = batchNotifications(allRecords);

          // Compute expected counts manually
          const expectedCounts = new Map<string, number>();
          for (const rec of allRecords) {
            if (rec.user_id) {
              expectedCounts.set(rec.user_id, (expectedCounts.get(rec.user_id) || 0) + 1);
            }
          }

          // Verify each notification has the correct count
          for (const notification of notifications) {
            const parsed = JSON.parse(notification.message);
            const actualCount = parsed.params.count;
            const expectedCount = expectedCounts.get(notification.userId);

            expect(actualCount).toBe(expectedCount);
          }
        }),
        { numRuns: 300 }
      );
    });

    it('records with null user_id produce no notifications', () => {
      fc.assert(
        fc.property(
          fc.array(unresolvedRecordArb, { minLength: 1, maxLength: 20 }),
          (unresolvedRecords) => {
            const notifications = batchNotifications(unresolvedRecords);

            // No notifications should be produced for unresolved records
            expect(notifications.length).toBe(0);
          }
        ),
        { numRuns: 200 }
      );
    });

    it('notification type is always recommendation_overdue', () => {
      fc.assert(
        fc.property(overdueScenarioArb, ([_userIds, _numUsers, resolvedRecords, unresolvedRecords]) => {
          const allRecords = [...resolvedRecords, ...unresolvedRecords];
          const notifications = batchNotifications(allRecords);

          for (const notification of notifications) {
            expect(notification.type).toBe('recommendation_overdue');
            expect(notification.module).toBe('warning');
            expect(notification.link).toBe('/recommendations');
          }
        }),
        { numRuns: 200 }
      );
    });

    it('total count across all notifications equals total resolved records', () => {
      fc.assert(
        fc.property(overdueScenarioArb, ([_userIds, _numUsers, resolvedRecords, unresolvedRecords]) => {
          const allRecords = [...resolvedRecords, ...unresolvedRecords];
          const notifications = batchNotifications(allRecords);

          // Sum of all notification counts should equal total resolved records
          const totalNotifiedCount = notifications.reduce((sum, n) => {
            const parsed = JSON.parse(n.message);
            return sum + parsed.params.count;
          }, 0);

          const totalResolvedRecords = allRecords.filter(r => r.user_id !== null).length;
          expect(totalNotifiedCount).toBe(totalResolvedRecords);
        }),
        { numRuns: 300 }
      );
    });
  });
});

// @vitest-environment node
import { describe, it, expect } from 'vitest';
import fc from 'fast-check';
import express from 'express';
import cookieParser from 'cookie-parser';
import request from 'supertest';
import { csrfMiddleware, generateCsrfToken } from '../middleware/csrf';
import type { CsrfOptions } from '../middleware/csrf';

/**
 * Property Test: CSRF token generation on authentication events (Property 3)
 *
 * Feature: technical-debt-remediation
 * Property 3: CSRF token generation on authentication events
 *
 * **Validates: Requirements 3.1, 3.6, 3.7**
 *
 * For any successful authentication event (login or token refresh), the response
 * must contain a new CSRF token that is cryptographically random with at least
 * 32 bytes of entropy (64 hex chars), and each generated token must be unique.
 */
describe('Property 3: CSRF token generation on authentication events', () => {
  it('each generated token is exactly 64 hex characters (32 bytes of entropy)', () => {
    fc.assert(
      fc.property(
        // Simulate authentication events by generating a count of events
        fc.integer({ min: 1, max: 50 }),
        (eventCount) => {
          for (let i = 0; i < eventCount; i++) {
            const token = generateCsrfToken();

            // Token must be exactly 64 hex characters (32 bytes * 2 hex chars per byte)
            expect(token).toHaveLength(64);
          }
        }
      ),
      { numRuns: 100 }
    );
  });

  it('each generated token is a valid hexadecimal string', () => {
    fc.assert(
      fc.property(
        fc.integer({ min: 1, max: 50 }),
        (eventCount) => {
          for (let i = 0; i < eventCount; i++) {
            const token = generateCsrfToken();

            // Token must contain only valid hex characters (0-9, a-f)
            expect(token).toMatch(/^[0-9a-f]{64}$/);
          }
        }
      ),
      { numRuns: 100 }
    );
  });

  it('all generated tokens are unique across authentication events', () => {
    fc.assert(
      fc.property(
        // Generate a batch size representing multiple auth events
        fc.integer({ min: 2, max: 100 }),
        (batchSize) => {
          const tokens = new Set<string>();

          for (let i = 0; i < batchSize; i++) {
            const token = generateCsrfToken();
            tokens.add(token);
          }

          // Every token must be unique - set size equals number of generated tokens
          expect(tokens.size).toBe(batchSize);
        }
      ),
      { numRuns: 100 }
    );
  });

  it('tokens have sufficient entropy (no repeated byte patterns)', () => {
    fc.assert(
      fc.property(
        fc.integer({ min: 1, max: 20 }),
        (_eventIndex) => {
          const token = generateCsrfToken();

          // Split token into 2-char byte representations
          const bytes: string[] = [];
          for (let i = 0; i < token.length; i += 2) {
            bytes.push(token.substring(i, i + 2));
          }

          // A token with 32 bytes of entropy should not have all identical bytes
          const uniqueBytes = new Set(bytes);
          // With 32 random bytes, having fewer than 2 unique byte values is
          // astronomically unlikely for a cryptographically random source
          expect(uniqueBytes.size).toBeGreaterThan(1);

          // Additionally, the token should not be all zeros or all ones
          expect(token).not.toMatch(/^0+$/);
          expect(token).not.toMatch(/^f+$/);
        }
      ),
      { numRuns: 100 }
    );
  });

  it('token generation with explicit byte length produces correct output size', () => {
    fc.assert(
      fc.property(
        // Test with various byte lengths, but always at least 32 for security
        fc.integer({ min: 32, max: 64 }),
        (byteLength) => {
          const token = generateCsrfToken(byteLength);

          // Token hex length should be exactly 2x the byte length
          expect(token).toHaveLength(byteLength * 2);

          // Must still be valid hex
          const hexPattern = new RegExp(`^[0-9a-f]{${byteLength * 2}}$`);
          expect(token).toMatch(hexPattern);
        }
      ),
      { numRuns: 100 }
    );
  });
});

/**
 * Property Test: CSRF validation on state-changing requests (Property 4)
 *
 * **Validates: Requirements 3.2, 3.3**
 *
 * For any state-changing HTTP request (POST, PUT, PATCH, DELETE) to a non-exempt endpoint,
 * the request must be rejected with HTTP 403 if it lacks a valid CSRF token,
 * and must succeed if a valid token is present.
 */
describe('Property 4: CSRF validation on state-changing requests', () => {
  const csrfOptions: CsrfOptions = {
    exemptPaths: ['/api/auth/login', '/health'],
    tokenHeader: 'x-csrf-token',
    cookieName: 'csrf-token',
    tokenByteLength: 32,
  };

  // Create a minimal Express app with CSRF middleware
  function createApp() {
    const app = express();
    app.use(cookieParser());
    app.use(csrfMiddleware(csrfOptions));
    // Catch-all handler that responds with 200 if middleware passes
    // Express 5 uses path-to-regexp v8 which requires named params for wildcards
    app.use((_req, res) => {
      res.status(200).json({ success: true });
    });
    return app;
  }

  // Generators
  const stateChangingMethods = fc.constantFrom('POST', 'PUT', 'PATCH', 'DELETE');
  const readOnlyMethods = fc.constantFrom('GET', 'HEAD', 'OPTIONS');

  // Generate non-exempt paths (avoid paths that start with exempt prefixes)
  const nonExemptPath = fc.stringMatching(/^\/[a-z][a-z0-9/]{1,30}$/).filter((path) => {
    return (
      !path.startsWith('/api/auth/login') &&
      !path.startsWith('/health')
    );
  });

  // Generate exempt paths
  const exemptPath = fc.constantFrom('/api/auth/login', '/health');

  it('state-changing requests without CSRF token are rejected with 403', async () => {
    const app = createApp();

    await fc.assert(
      fc.asyncProperty(stateChangingMethods, nonExemptPath, async (method, path) => {
        const res = await (request(app) as any)[method.toLowerCase()](path);

        expect(res.status).toBe(403);
        expect(res.body.error).toMatch(/CSRF token/i);
      }),
      { numRuns: 100 }
    );
  });

  it('state-changing requests with valid matching tokens succeed (200)', async () => {
    const app = createApp();

    await fc.assert(
      fc.asyncProperty(stateChangingMethods, nonExemptPath, async (method, path) => {
        const token = generateCsrfToken(csrfOptions.tokenByteLength);

        const res = await (request(app) as any)
          [method.toLowerCase()](path)
          .set('x-csrf-token', token)
          .set('Cookie', `csrf-token=${token}`);

        expect(res.status).toBe(200);
        expect(res.body.success).toBe(true);
      }),
      { numRuns: 100 }
    );
  });

  it('state-changing requests with mismatched tokens are rejected with 403', async () => {
    const app = createApp();

    await fc.assert(
      fc.asyncProperty(stateChangingMethods, nonExemptPath, async (method, path) => {
        const headerToken = generateCsrfToken(csrfOptions.tokenByteLength);
        const cookieToken = generateCsrfToken(csrfOptions.tokenByteLength);

        const res = await (request(app) as any)
          [method.toLowerCase()](path)
          .set('x-csrf-token', headerToken)
          .set('Cookie', `csrf-token=${cookieToken}`);

        expect(res.status).toBe(403);
        expect(res.body.error).toMatch(/CSRF token invalid/i);
      }),
      { numRuns: 100 }
    );
  });

  it('GET/HEAD/OPTIONS requests always pass through regardless of token', async () => {
    const app = createApp();

    await fc.assert(
      fc.asyncProperty(readOnlyMethods, nonExemptPath, async (method, path) => {
        const res = await (request(app) as any)[method.toLowerCase()](path);

        // GET/HEAD/OPTIONS should pass through without CSRF validation
        expect(res.status).toBe(200);
      }),
      { numRuns: 100 }
    );
  });

  it('exempt paths always pass through regardless of method or token', async () => {
    const app = createApp();

    await fc.assert(
      fc.asyncProperty(stateChangingMethods, exemptPath, async (method, path) => {
        // No CSRF token provided, but exempt path should still pass
        const res = await (request(app) as any)[method.toLowerCase()](path);

        expect(res.status).toBe(200);
        expect(res.body.success).toBe(true);
      }),
      { numRuns: 100 }
    );
  });
});

