  )
  .map(([base, segments, ext]) => `${base}\\${segments.join('\\')}${ext}`);

/** Generates file paths (both Unix and Windows) */
const filePathArb = fc.oneof(unixFilePathArb, windowsFilePathArb);

/** Generates stack trace lines */
const stackTraceArb = fc
