            };
          }

          return {
            get: vi.fn().mockResolvedValue(null),
            all: vi.fn().mockResolvedValue([]),
            run: vi.fn().mockResolvedValue({ changes: 0, lastInsertRowid: 0 }),
          };
        }),
      };

      const testModules = [
        {
          name: 'Existing',
          label: { en: 'Existing', ar: 'موجود' },
