import { PermissionService } from '../services/PermissionService';
import { ModuleRegistry } from '../../permissions/registry';

describe('Permission Middleware', () => {
  let db: any;
  let middlewares: ReturnType<typeof createAuthMiddlewares>;
  const JWT_SECRET = 'test-secret';
  const JWT_PUBLIC_KEY = 'test-public-key';

  beforeEach(() => {
    vi.clearAllMocks();

    db = {
      prepare: vi.fn().mockReturnValue({
        get: vi.fn().mockResolvedValue(null),
        all: vi.fn().mockResolvedValue([]),
        run: vi.fn().mockResolvedValue({ lastInsertRowid: 0, changes: 0 }),
      }),
    };

    middlewares = createAuthMiddlewares(db, JWT_SECRET, JWT_PUBLIC_KEY);
    // Clear the internal cache before each test
    middlewares.cache.clear();
  });

  function createMockReq(user: any, overrides: any = {}) {
    return {
      user,
      cookies: {},
      headers: {},
      originalUrl: '/api/test',
      ...overrides,
    };
  }

  function createMockRes() {
    const res: any = {};
    res.status = vi.fn().mockReturnValue(res);
    res.json = vi.fn().mockReturnValue(res);
    res.cookie = vi.fn().mockReturnValue(res);
    return res;
  }

  describe('checkPermission', () => {
    it('should allow Admin users to bypass permission checks', async () => {
      const req = createMockReq({ id: 'admin-1', role: UserRole.ADMIN });
      const res = createMockRes();
      const next = vi.fn();

      const middleware = middlewares.checkPermission('Audit', 'View');
      await middleware(req, res, next);

      expect(next).toHaveBeenCalled();
      expect(res.status).not.toHaveBeenCalled();
      // Admin bypass should NOT call PermissionService
      expect(PermissionService.hasPermission).not.toHaveBeenCalled();
    });

    it('should allow access when user has role-based permission', async () => {
      vi.mocked(PermissionService.hasPermission).mockResolvedValue(true);

      const req = createMockReq({ id: 'user-1', role: UserRole.INTERNAL_AUDITOR });
      const res = createMockRes();
      const next = vi.fn();

      const middleware = middlewares.checkPermission('Audit', 'View');
      await middleware(req, res, next);

      expect(next).toHaveBeenCalled();
      expect(res.status).not.toHaveBeenCalled();
      expect(PermissionService.hasPermission).toHaveBeenCalledWith('user-1', 'Audit', 'View');
    });

    it('should deny access when user lacks permission', async () => {
      vi.mocked(PermissionService.hasPermission).mockResolvedValue(false);

      const req = createMockReq({ id: 'user-1', role: UserRole.VIEWER });
      const res = createMockRes();
      const next = vi.fn();

      const middleware = middlewares.checkPermission('Audit', 'Edit');
      await middleware(req, res, next);

      expect(next).not.toHaveBeenCalled();
      expect(res.status).toHaveBeenCalledWith(403);
      expect(res.json).toHaveBeenCalledWith(
        expect.objectContaining({
          error: expect.stringContaining('Forbidden'),
          code: 'PERMISSION_DENIED',
          module: 'Audit',
          action: 'Edit',
        })
      );
    });

    it('should include module and action in the error message', async () => {
      vi.mocked(PermissionService.hasPermission).mockResolvedValue(false);

      const req = createMockReq({ id: 'user-1', role: UserRole.VIEWER });
      const res = createMockRes();
      const next = vi.fn();

      const middleware = middlewares.checkPermission('Finding', 'Delete');
      await middleware(req, res, next);

      expect(res.json).toHaveBeenCalledWith(
        expect.objectContaining({
          error: expect.stringContaining('Delete'),
          module: 'Finding',
          action: 'Delete',
        })
      );
      expect(res.json).toHaveBeenCalledWith(
        expect.objectContaining({
          error: expect.stringContaining('Finding'),
        })
      );
    });

    it('should return 401 when req.user is not populated', async () => {
      const req = createMockReq(undefined);
      const res = createMockRes();
      const next = vi.fn();

      const middleware = middlewares.checkPermission('Audit', 'View');
      await middleware(req, res, next);

      expect(next).not.toHaveBeenCalled();
      expect(res.status).toHaveBeenCalledWith(401);
      expect(res.json).toHaveBeenCalledWith(
        expect.objectContaining({ error: expect.stringContaining('Authentication required') })
      );
    });

    it('should return 500 when PermissionService throws an error', async () => {
      vi.mocked(PermissionService.hasPermission).mockRejectedValue(new Error('DB connection failed'));

      const req = createMockReq({ id: 'user-1', role: UserRole.VIEWER });
      const res = createMockRes();
      const next = vi.fn();

      const middleware = middlewares.checkPermission('Audit', 'View');
      await middleware(req, res, next);

      expect(next).not.toHaveBeenCalled();
      expect(res.status).toHaveBeenCalledWith(500);
      expect(res.json).toHaveBeenCalledWith(
        expect.objectContaining({ error: expect.stringContaining('Internal authorization error') })
      );
      // Should NOT expose internal error details
      expect(res.json).toHaveBeenCalledWith(
        expect.not.objectContaining({ error: expect.stringContaining('DB connection') })
      );
    });

    describe('unregistered module handling', () => {
      it('should throw at startup in dev mode when module is not registered', () => {
        // Make getModule return undefined for an unregistered module
        vi.mocked(ModuleRegistry.getModule).mockReturnValueOnce(undefined);

        const originalEnv = process.env.NODE_ENV;
        process.env.NODE_ENV = 'development';

        try {
          expect(() => {
            middlewares.checkPermission('NonExistentModule', 'View');
          }).toThrow(/NonExistentModule.*not registered/);
        } finally {
          process.env.NODE_ENV = originalEnv;
        }
      });

      it('should return 500 in production mode when module is not registered', async () => {
        vi.mocked(ModuleRegistry.getModule).mockReturnValueOnce(undefined);

        const originalEnv = process.env.NODE_ENV;
        process.env.NODE_ENV = 'production';

        try {
          const middleware = middlewares.checkPermission('NonExistentModule', 'View');
          const req = createMockReq({ id: 'user-1', role: UserRole.VIEWER });
          const res = createMockRes();
          const next = vi.fn();

          await middleware(req, res, next);

          expect(next).not.toHaveBeenCalled();
          expect(res.status).toHaveBeenCalledWith(500);
          expect(res.json).toHaveBeenCalledWith(
            expect.objectContaining({ error: expect.stringContaining('Internal authorization configuration error') })
          );
        } finally {
          process.env.NODE_ENV = originalEnv;
        }
      });
    });
  });

  describe('authorize', () => {
    it('should allow access when user role is in allowed roles', () => {
      const req = createMockReq({ id: 'user-1', role: UserRole.ADMIN });
      const res = createMockRes();
      const next = vi.fn();

      const middleware = middlewares.authorize([UserRole.ADMIN, UserRole.MANAGER]);
      middleware(req, res, next);

      expect(next).toHaveBeenCalled();
      expect(res.status).not.toHaveBeenCalled();
    });

    it('should deny access when user role is not in allowed roles', () => {
      const req = createMockReq({ id: 'user-1', role: UserRole.VIEWER });
      const res = createMockRes();
      const next = vi.fn();

      const middleware = middlewares.authorize([UserRole.ADMIN, UserRole.MANAGER]);
      middleware(req, res, next);

      expect(next).not.toHaveBeenCalled();
      expect(res.status).toHaveBeenCalledWith(403);
      expect(res.json).toHaveBeenCalledWith(
        expect.objectContaining({ error: 'Forbidden: Insufficient permissions' })
      );
    });

    it('should work with ADMIN_ROLES constant', () => {
      const adminReq = createMockReq({ id: 'admin-1', role: UserRole.ADMIN });
      const managerReq = createMockReq({ id: 'mgr-1', role: UserRole.MANAGER });
      const viewerReq = createMockReq({ id: 'viewer-1', role: UserRole.VIEWER });

      const res1 = createMockRes();
      const res2 = createMockRes();
      const res3 = createMockRes();
      const next1 = vi.fn();
      const next2 = vi.fn();
      const next3 = vi.fn();

      const middleware = middlewares.authorize(ADMIN_ROLES);

      middleware(adminReq, res1, next1);
      middleware(managerReq, res2, next2);
      middleware(viewerReq, res3, next3);

      expect(next1).toHaveBeenCalled();
      expect(next2).toHaveBeenCalled();
      expect(next3).not.toHaveBeenCalled();
    });

    it('should work with COMPLIANCE_ROLES constant', () => {
      const complianceReq = createMockReq({ id: 'co-1', role: UserRole.COMPLIANCE_OFFICER });
      const auditorReq = createMockReq({ id: 'aud-1', role: UserRole.INTERNAL_AUDITOR });

      const res1 = createMockRes();
      const res2 = createMockRes();
      const next1 = vi.fn();
      const next2 = vi.fn();

      const middleware = middlewares.authorize(COMPLIANCE_ROLES);

      middleware(complianceReq, res1, next1);
      middleware(auditorReq, res2, next2);

      expect(next1).toHaveBeenCalled();
      expect(next2).not.toHaveBeenCalled();
    });

    it('should work with STAFF_ROLES constant', () => {
      const auditorReq = createMockReq({ id: 'aud-1', role: UserRole.INTERNAL_AUDITOR });
      const riskReq = createMockReq({ id: 'risk-1', role: UserRole.RISK_OFFICER });

      const res1 = createMockRes();
      const res2 = createMockRes();
      const next1 = vi.fn();
      const next2 = vi.fn();

      const middleware = middlewares.authorize(STAFF_ROLES);

      middleware(auditorReq, res1, next1);
      middleware(riskReq, res2, next2);

      expect(next1).toHaveBeenCalled();
      expect(next2).not.toHaveBeenCalled(); // Risk Officer is not in STAFF_ROLES
    });
  });

  describe('authenticate', () => {
    it('should return 401 when no token is provided', async () => {
      const req = { cookies: {}, headers: {}, originalUrl: '/api/test' };
      const res = createMockRes();
      const next = vi.fn();

      await middlewares.authenticate(req, res, next);

      expect(res.status).toHaveBeenCalledWith(401);
      expect(res.json).toHaveBeenCalledWith({ error: 'Unauthorized' });
      expect(next).not.toHaveBeenCalled();
    });

    it('should return 401 when token is invalid', async () => {
      vi.mocked(jwt.verify).mockImplementation(() => {
        throw new (jwt as any).JsonWebTokenError('invalid token');
      });

      const req = { cookies: { token: 'invalid-token' }, headers: {}, originalUrl: '/api/test' };
      const res = createMockRes();
      const next = vi.fn();

      await middlewares.authenticate(req, res, next);

      expect(res.status).toHaveBeenCalledWith(401);
      expect(res.json).toHaveBeenCalledWith({ error: 'Invalid token' });
    });

    it('should return 403 when user account is suspended', async () => {
      vi.mocked(jwt.verify).mockReturnValue({ id: 'user-1', session_version: 1 } as any);

      db.prepare.mockReturnValue({
        get: vi.fn().mockResolvedValue({
          id: 'user-1',
          role: 'Admin',
          status: 'Suspended',
          username: 'testuser',
          name: 'Test',
          email: 'test@test.com',
          session_version: 1,
          requires_password_change: false,
        }),
        all: vi.fn(),
        run: vi.fn(),
      });

      const req = { cookies: { token: 'valid-token' }, headers: {}, originalUrl: '/api/test' };
      const res = createMockRes();
      const next = vi.fn();

      // Need a fresh middleware instance with the updated db mock
      middlewares = createAuthMiddlewares(db, JWT_SECRET, JWT_PUBLIC_KEY);
      middlewares.cache.clear();

      await middlewares.authenticate(req, res, next);

      expect(res.status).toHaveBeenCalledWith(403);
      expect(next).not.toHaveBeenCalled();
    });

    it('should return 401 when session version does not match', async () => {
      vi.mocked(jwt.verify).mockReturnValue({ id: 'user-1', session_version: 1 } as any);

      db.prepare.mockReturnValue({
        get: vi.fn().mockResolvedValue({
          id: 'user-1',
          role: 'Admin',
          status: 'Active',
          username: 'testuser',
          name: 'Test',
          email: 'test@test.com',
          session_version: 2, // Different from token's session_version
          requires_password_change: false,
        }),
        all: vi.fn(),
        run: vi.fn(),
      });

      const req = { cookies: { token: 'valid-token' }, headers: {}, originalUrl: '/api/test' };
      const res = createMockRes();
      const next = vi.fn();

      middlewares = createAuthMiddlewares(db, JWT_SECRET, JWT_PUBLIC_KEY);
      middlewares.cache.clear();

      await middlewares.authenticate(req, res, next);

      expect(res.status).toHaveBeenCalledWith(401);
      expect(res.json).toHaveBeenCalledWith({ error: 'Session invalidated' });
    });

    it('should extract token from Authorization header when cookie is absent', async () => {
      vi.mocked(jwt.verify).mockReturnValue({ id: 'user-1', session_version: 1 } as any);

      db.prepare.mockReturnValue({
        get: vi.fn().mockResolvedValue({
          id: 'user-1',
          role: 'Admin',
          status: 'Active',
          username: 'testuser',
          name: 'Test',
          email: 'test@test.com',
          session_version: 1,
          requires_password_change: false,
        }),
        all: vi.fn(),
        run: vi.fn(),
      });

      const req = {
        cookies: {},
        headers: { authorization: 'Bearer my-bearer-token' },
        originalUrl: '/api/test',
      };
      const res = createMockRes();
      const next = vi.fn();

      middlewares = createAuthMiddlewares(db, JWT_SECRET, JWT_PUBLIC_KEY);
      middlewares.cache.clear();

      await middlewares.authenticate(req, res, next);

      expect(jwt.verify).toHaveBeenCalledWith('my-bearer-token', JWT_PUBLIC_KEY, { algorithms: ['RS256'] });
      expect(next).toHaveBeenCalled();
    });
  });
});

import { describe, it, expect } from 'vitest';

describe('Rate Limiting Configuration', () => {
  it('should have appropriate global rate limit for NAT environments', () => {
    const GLOBAL_LIMIT = 300;
    const WINDOW_MS = 60 * 1000; // 1 minute
    
    // 300 requests per minute is reasonable for corporate NAT
    expect(GLOBAL_LIMIT).toBeGreaterThanOrEqual(150);
    expect(GLOBAL_LIMIT).toBeLessThanOrEqual(500);
    expect(WINDOW_MS).toBe(60000);
  });

  it('should have strict auth rate limit', () => {
    const AUTH_LIMIT = 10;
    const AUTH_WINDOW = 15 * 60 * 1000; // 15 minutes
    
    // 10 attempts per 15 minutes is strict enough for brute force protection
    expect(AUTH_LIMIT).toBeLessThanOrEqual(15);
    expect(AUTH_WINDOW).toBeGreaterThanOrEqual(10 * 60 * 1000);
  });

  it('should key auth limiter by IP + username', () => {
    // This prevents one user from blocking others behind the same NAT
    const keyGenerator = (req: any) => {
      const username = (req.body && req.body.usernameOrEmail) ? String(req.body.usernameOrEmail).toLowerCase() : 'unknown';
      return `${req.ip || 'no-ip'}_${username}`;
    };

    const result = keyGenerator({ ip: '192.168.1.1', body: { usernameOrEmail: 'Admin' } });
    expect(result).toBe('192.168.1.1_admin');
  });

  it('should handle missing IP gracefully', () => {
    const keyGenerator = (req: any) => {
      const username = (req.body && req.body.usernameOrEmail) ? String(req.body.usernameOrEmail).toLowerCase() : 'unknown';
      return `${req.ip || 'no-ip'}_${username}`;
    };

    const result = keyGenerator({ body: { usernameOrEmail: 'test' } });
    expect(result).toBe('no-ip_test');
  });
});

// @vitest-environment node
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import fc from 'fast-check';

/**
 * Property Test: Per-User Rate Limiting Fairness (Property 10)
 *
 * Feature: api-audit-improvements
 * Property 10: Per-User Rate Limiting Fairness
 *
 * **Validates: Requirements 14.1, 14.4**
 *
 * For any two authenticated users sharing the same IP address, one user
 * exhausting their rate limit SHALL NOT reduce the available quota of the
 * other user, and each user's request count SHALL be tracked independently.
 */

import {
  createRateLimiter,
  resetRateLimiterStore,
  stopRateLimiterCleanup,
} from '../../server/middleware/rateLimiter';
import {
  createAuthenticatedRequest,
  createMockResponse,
  createMockNext,
} from '../../server/__tests__/helpers/apiTestUtils';

// ─── Custom Arbitraries ──────────────────────────────────────────────────────

/** Generates valid user IDs (distinct from each other) */
const userIdArb = fc.uuid();

/** Generates valid IP addresses */
const ipArb = fc.tuple(
  fc.integer({ min: 1, max: 255 }),
  fc.integer({ min: 0, max: 255 }),
  fc.integer({ min: 0, max: 255 }),
  fc.integer({ min: 1, max: 254 })
).map(([a, b, c, d]) => `${a}.${b}.${c}.${d}`);

/** Generates rate limit values (small for fast testing) */
const limitArb = fc.integer({ min: 3, max: 20 });

/** Generates request counts for exhausting a user's limit */
const requestCountArb = fc.integer({ min: 1, max: 20 });

// ─── Tests ───────────────────────────────────────────────────────────────────

describe('Property 10: Per-User Rate Limiting Fairness', () => {
  afterEach(() => {
    resetRateLimiterStore();
    stopRateLimiterCleanup();
  });

  it('two users on same IP have independent quotas', () => {
    fc.assert(
      fc.property(
        userIdArb,
        userIdArb,
        ipArb,
        limitArb,
        requestCountArb,
        (userIdA, userIdB, sharedIp, limit, requestCount) => {
          // Ensure users are distinct
          fc.pre(userIdA !== userIdB);

          // Clamp requestCount to not exceed limit
          const numRequests = Math.min(requestCount, limit);

          resetRateLimiterStore();

          const rateLimiter = createRateLimiter({
            authenticatedLimit: limit,
            unauthenticatedLimit: limit,
            windowSeconds: 60,
          });

          // ─── User A makes numRequests requests ─────────────────────────
          for (let i = 0; i < numRequests; i++) {
            const req = createAuthenticatedRequest({
              user: { id: userIdA },
              ip: sharedIp,
            });
            const res = createMockResponse();
            const next = createMockNext();
            rateLimiter(req, res as any, next);
          }

          // ─── User B makes their first request on the same IP ───────────
          const reqB = createAuthenticatedRequest({
            user: { id: userIdB },
            ip: sharedIp,
          });
          const resB = createMockResponse();
          const nextB = createMockNext();
          rateLimiter(reqB, resB as any, nextB);

          // Property: User B's request is allowed (next was called)
          expect(nextB).toHaveBeenCalled();

          // Property: User B has full quota minus 1 (their own request)
          const remainingB = parseInt(resB._headers['x-ratelimit-remaining']);
          expect(remainingB).toBe(limit - 1);

          // Property: User B's limit is the full configured limit
          const limitB = parseInt(resB._headers['x-ratelimit-limit']);
          expect(limitB).toBe(limit);
        }
      ),
      { numRuns: 100 }
    );
  });

  it('one user exhausting limit does not reduce other user\'s quota', () => {
    fc.assert(
      fc.property(
        userIdArb,
        userIdArb,
        ipArb,
        limitArb,
        (userIdA, userIdB, sharedIp, limit) => {
          // Ensure users are distinct
          fc.pre(userIdA !== userIdB);

          resetRateLimiterStore();

          const rateLimiter = createRateLimiter({
            authenticatedLimit: limit,
            unauthenticatedLimit: limit,
            windowSeconds: 60,
          });

          // ─── User A exhausts their entire limit ────────────────────────
          for (let i = 0; i < limit; i++) {
            const req = createAuthenticatedRequest({
              user: { id: userIdA },
              ip: sharedIp,
            });
            const res = createMockResponse();
            const next = createMockNext();
            rateLimiter(req, res as any, next);
            // All should pass
            expect(next).toHaveBeenCalled();
          }

          // ─── Verify User A is now rate limited ─────────────────────────
          const reqABlocked = createAuthenticatedRequest({
            user: { id: userIdA },
            ip: sharedIp,
          });
          const resABlocked = createMockResponse();
          const nextABlocked = createMockNext();
          rateLimiter(reqABlocked, resABlocked as any, nextABlocked);

          // User A should be blocked (429)
          expect(nextABlocked).not.toHaveBeenCalled();
          expect(resABlocked.statusCode).toBe(429);

          // ─── User B should have full quota available ───────────────────
          const reqB = createAuthenticatedRequest({
            user: { id: userIdB },
            ip: sharedIp,
          });
          const resB = createMockResponse();
          const nextB = createMockNext();
          rateLimiter(reqB, resB as any, nextB);

          // Property: User B's request succeeds (not affected by User A)
          expect(nextB).toHaveBeenCalled();

          // Property: User B has full quota minus 1 (only their own request counted)
          const remainingB = parseInt(resB._headers['x-ratelimit-remaining']);
          expect(remainingB).toBe(limit - 1);

          // Property: User B's limit header shows the full configured limit
          const limitHeaderB = parseInt(resB._headers['x-ratelimit-limit']);
          expect(limitHeaderB).toBe(limit);
        }
      ),
      { numRuns: 100 }
    );
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import { ReadWriteLock, isReadQuery } from '../db/index';

describe('ReadWriteLock', () => {
  let lock: ReadWriteLock;

  beforeEach(() => {
    lock = new ReadWriteLock();
  });

  describe('acquireRead', () => {
    it('should grant read lock immediately when no writer is active', async () => {
      const release = await lock.acquireRead();
      expect(lock.readers).toBe(1);
      release();
      expect(lock.readers).toBe(0);
    });

    it('should allow multiple concurrent readers', async () => {
      const release1 = await lock.acquireRead();
      const release2 = await lock.acquireRead();
      const release3 = await lock.acquireRead();
      expect(lock.readers).toBe(3);
      release1();
      release2();
      release3();
      expect(lock.readers).toBe(0);
    });

    it('should queue readers when a writer is active', async () => {
      const writeRelease = await lock.acquireWrite();
      expect(lock.writing).toBe(true);

      let readGranted = false;
      const readPromise = lock.acquireRead().then(release => {
        readGranted = true;
        return release;
      });

      // Give the event loop a tick
      await new Promise(r => setTimeout(r, 10));
      expect(readGranted).toBe(false);
      expect(lock.readQueueLength).toBe(1);

      writeRelease();
      const readRelease = await readPromise;
      expect(readGranted).toBe(true);
      expect(lock.readers).toBe(1);
      readRelease();
    });

    it('should queue readers when a writer is waiting', async () => {
      // Acquire a read lock first
      const readRelease1 = await lock.acquireRead();

      // Now a writer tries to acquire - it should queue
      let writeGranted = false;
      const writePromise = lock.acquireWrite().then(release => {
        writeGranted = true;
        return release;
      });

      await new Promise(r => setTimeout(r, 10));
      expect(writeGranted).toBe(false);

      // A new reader should also queue (writer priority)
      let readGranted2 = false;
      const readPromise2 = lock.acquireRead().then(release => {
        readGranted2 = true;
        return release;
      });

      await new Promise(r => setTimeout(r, 10));
      expect(readGranted2).toBe(false);

      // Release the first reader - writer should get the lock
      readRelease1();
      const writeRelease = await writePromise;
      expect(writeGranted).toBe(true);
      expect(readGranted2).toBe(false);

      // Release writer - queued reader should get the lock
      writeRelease();
      const readRelease2 = await readPromise2;
      expect(readGranted2).toBe(true);
      readRelease2();
    });
  });

  describe('acquireWrite', () => {
    it('should grant write lock immediately when no readers or writers', async () => {
      const release = await lock.acquireWrite();
      expect(lock.writing).toBe(true);
      release();
      expect(lock.writing).toBe(false);
    });

    it('should queue writer when readers are active', async () => {
      const readRelease = await lock.acquireRead();

      let writeGranted = false;
      const writePromise = lock.acquireWrite().then(release => {
        writeGranted = true;
        return release;
      });

      await new Promise(r => setTimeout(r, 10));
      expect(writeGranted).toBe(false);
      expect(lock.writeQueueLength).toBe(1);

      readRelease();
      const writeRelease = await writePromise;
      expect(writeGranted).toBe(true);
      writeRelease();
    });

    it('should queue writer when another writer is active', async () => {
      const writeRelease1 = await lock.acquireWrite();

      let writeGranted2 = false;
      const writePromise2 = lock.acquireWrite().then(release => {
        writeGranted2 = true;
        return release;
      });

      await new Promise(r => setTimeout(r, 10));
      expect(writeGranted2).toBe(false);

      writeRelease1();
      const writeRelease2 = await writePromise2;
      expect(writeGranted2).toBe(true);
      writeRelease2();
    });

    it('should block all operations while write lock is held', async () => {
      const writeRelease = await lock.acquireWrite();

      let readGranted = false;
      let write2Granted = false;

      lock.acquireRead().then(release => {
        readGranted = true;
        return release;
      });
      lock.acquireWrite().then(release => {
        write2Granted = true;
        return release;
      });

      await new Promise(r => setTimeout(r, 10));
      expect(readGranted).toBe(false);
      expect(write2Granted).toBe(false);

      writeRelease();
      // After releasing, queued operations should proceed
      await new Promise(r => setTimeout(r, 10));
      // Writer has priority, so write2 should be granted first
      expect(write2Granted).toBe(true);
    });
  });

  describe('timeout', () => {
    it('should reject with 503 status when lock cannot be acquired within timeout', async () => {
      // Override timeout for testing
      const originalTimeout = ReadWriteLock.LOCK_TIMEOUT_MS;
      (ReadWriteLock as any).LOCK_TIMEOUT_MS = 50; // 50ms for fast test

      const lock = new ReadWriteLock();
      const writeRelease = await lock.acquireWrite();

      try {
        await lock.acquireRead();
        expect.fail('Should have thrown');
      } catch (error: any) {
        expect(error.message).toContain('Lock acquisition timeout');
        expect(error.message).toContain('read');
        expect(error.statusCode).toBe(503);
      } finally {
        writeRelease();
        (ReadWriteLock as any).LOCK_TIMEOUT_MS = originalTimeout;
      }
    });

    it('should reject write lock with 503 on timeout', async () => {
      const originalTimeout = ReadWriteLock.LOCK_TIMEOUT_MS;
      (ReadWriteLock as any).LOCK_TIMEOUT_MS = 50;

      const lock = new ReadWriteLock();
      const writeRelease = await lock.acquireWrite();

      try {
        await lock.acquireWrite();
        expect.fail('Should have thrown');
      } catch (error: any) {
        expect(error.message).toContain('Lock acquisition timeout');
        expect(error.message).toContain('write');
        expect(error.statusCode).toBe(503);
      } finally {
        writeRelease();
        (ReadWriteLock as any).LOCK_TIMEOUT_MS = originalTimeout;
      }
    });

    it('should not timeout if lock is acquired before deadline', async () => {
      const originalTimeout = ReadWriteLock.LOCK_TIMEOUT_MS;
      (ReadWriteLock as any).LOCK_TIMEOUT_MS = 200;

      const lock = new ReadWriteLock();
      const writeRelease = await lock.acquireWrite();

      // Release after 50ms (well before 200ms timeout)
      setTimeout(() => writeRelease(), 50);

      const readRelease = await lock.acquireRead();
      expect(lock.readers).toBe(1);
      readRelease();

      (ReadWriteLock as any).LOCK_TIMEOUT_MS = originalTimeout;
    });
  });

  describe('fairness and ordering', () => {
    it('should drain all queued readers when writer releases and no writer is waiting', async () => {
      const writeRelease = await lock.acquireWrite();

      const readPromises: Promise<() => void>[] = [];
      for (let i = 0; i < 5; i++) {
        readPromises.push(lock.acquireRead());
      }

      await new Promise(r => setTimeout(r, 10));
      expect(lock.readQueueLength).toBe(5);

      writeRelease();
      const releases = await Promise.all(readPromises);
      expect(lock.readers).toBe(5);

      releases.forEach(r => r());
      expect(lock.readers).toBe(0);
    });

    it('should prioritize writers over readers in queue', async () => {
      const readRelease1 = await lock.acquireRead();
      const order: string[] = [];

      // Queue a writer
      const writePromise = lock.acquireWrite().then(release => {
        order.push('write');
        return release;
      });

      await new Promise(r => setTimeout(r, 10));

      // Queue a reader (should go after writer)
      const readPromise = lock.acquireRead().then(release => {
        order.push('read');
        return release;
      });

      await new Promise(r => setTimeout(r, 10));

      // Release initial reader - writer should go first
      readRelease1();

      const writeRelease = await writePromise;
      writeRelease();

      const readRelease2 = await readPromise;
      readRelease2();

      expect(order).toEqual(['write', 'read']);
    });
  });
});

describe('isReadQuery', () => {
  it('should identify SELECT as read', () => {
    expect(isReadQuery('SELECT * FROM users')).toBe(true);
    expect(isReadQuery('  SELECT id FROM tasks')).toBe(true);
    expect(isReadQuery('select count(*) from items')).toBe(true);
  });

  it('should identify EXPLAIN as read', () => {
    expect(isReadQuery('EXPLAIN SELECT * FROM users')).toBe(true);
    expect(isReadQuery('EXPLAIN ANALYZE SELECT 1')).toBe(true);
  });

  it('should identify SHOW as read', () => {
    expect(isReadQuery('SHOW TABLES')).toBe(true);
  });

  it('should identify WITH ... SELECT as read', () => {
    expect(isReadQuery('WITH cte AS (SELECT 1) SELECT * FROM cte')).toBe(true);
  });

  it('should identify WITH ... INSERT as write', () => {
    expect(isReadQuery('WITH cte AS (SELECT 1) INSERT INTO t SELECT * FROM cte')).toBe(false);
  });

  it('should identify INSERT as write', () => {
    expect(isReadQuery('INSERT INTO users (name) VALUES ($1)')).toBe(false);
  });

  it('should identify UPDATE as write', () => {
    expect(isReadQuery('UPDATE users SET name = $1 WHERE id = $2')).toBe(false);
  });

  it('should identify DELETE as write', () => {
    expect(isReadQuery('DELETE FROM users WHERE id = $1')).toBe(false);
  });

  it('should identify CREATE as write', () => {
    expect(isReadQuery('CREATE TABLE test (id INT)')).toBe(false);
  });

  it('should identify ALTER as write', () => {
    expect(isReadQuery('ALTER TABLE users ADD COLUMN email TEXT')).toBe(false);
  });

  it('should identify DROP as write', () => {
    expect(isReadQuery('DROP TABLE IF EXISTS temp')).toBe(false);
  });

  it('should identify BEGIN/COMMIT/ROLLBACK as write', () => {
    expect(isReadQuery('BEGIN')).toBe(false);
    expect(isReadQuery('COMMIT')).toBe(false);
    expect(isReadQuery('ROLLBACK')).toBe(false);
  });
});

// @vitest-environment node
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import fc from 'fast-check';
import { createRequestLogger } from '../middleware/requestLogger';
import {
  createMockRequest,
  createMockResponse,
  createMockNext,
} from './helpers/apiTestUtils';

/**
 * Property Test: Request Logger Completeness (Property 14)
 *
 * Feature: api-audit-improvements
 * Property 14: Request Logger Completeness
 *
 * **Validates: Requirements 11.1, 10.4**
 *
 * For any request to a non-excluded path, the Request_Logger SHALL produce a log
 * entry containing all required fields (method, path, status code, duration, user ID,
 * IP, user agent), and the request ID in the log entry SHALL match the response's
 * X-Request-Id header.
 */

// Mock the db module
vi.mock('../db/index', () => ({
  default: {
    prepare: vi.fn(() => ({
      run: vi.fn().mockResolvedValue({ lastInsertRowid: 1, changes: 1 }),
    })),
  },
}));

// Mock the logger module
vi.mock('../utils/logger', () => ({
  default: {
    info: vi.fn(),
    warn: vi.fn(),
    error: vi.fn(),
    debug: vi.fn(),
  },
  requestContext: {
    run: vi.fn((store, fn) => fn()),
    getStore: vi.fn(),
  },
}));

import db from '../db/index';
import logger from '../utils/logger';

// ─── Custom Arbitraries ──────────────────────────────────────────────────────

/** Valid HTTP methods */
const httpMethodArb = fc.constantFrom('GET', 'POST', 'PUT', 'PATCH', 'DELETE');

/** Generates a valid UUID v4 for correlation IDs */
const uuidArb = fc.uuid();

/** Generates a non-excluded path (not /api/health or /uploads/*) */
const nonExcludedPathArb = fc
  .tuple(
    fc.constantFrom('/api/v1/', '/api/', '/'),
    fc.stringMatching(/^[a-z][a-z0-9-]{0,20}$/)
  )
  .map(([prefix, segment]) => `${prefix}${segment}`)
  .filter(
    (path) =>
      path !== '/api/health' &&
      !path.startsWith('/uploads/') &&
      !path.startsWith('/uploads')
  );

/** Generates a valid IP address */
const ipAddressArb = fc
  .tuple(
    fc.integer({ min: 1, max: 255 }),
    fc.integer({ min: 0, max: 255 }),
    fc.integer({ min: 0, max: 255 }),
    fc.integer({ min: 1, max: 254 })
  )
  .map(([a, b, c, d]) => `${a}.${b}.${c}.${d}`);

/** Generates a user agent string */
const userAgentArb = fc
  .tuple(
    fc.constantFrom('Mozilla', 'Chrome', 'Safari', 'Firefox', 'Edge', 'TestAgent'),
    fc.stringMatching(/^[0-9]{1,2}\.[0-9]{1,2}$/)
  )
  .map(([browser, version]) => `${browser}/${version}`);

/** Generates an optional user ID (null for unauthenticated) */
const userIdArb = fc.option(fc.uuid(), { nil: null });

/** Generates a valid HTTP status code */
const statusCodeArb = fc.integer({ min: 200, max: 599 });

/**
 * Composite arbitrary for a complete request scenario:
 * method, path, correlationId, userId, ip, userAgent, statusCode
 */
const requestScenarioArb = fc.record({
  method: httpMethodArb,
  path: nonExcludedPathArb,
  correlationId: uuidArb,
  userId: userIdArb,
  ip: ipAddressArb,
  userAgent: userAgentArb,
  statusCode: statusCodeArb,
});

// ─── Tests ───────────────────────────────────────────────────────────────────

describe('Property 14: Request Logger Completeness', () => {
  let stderrSpy: ReturnType<typeof vi.spyOn>;

  beforeEach(() => {
    vi.clearAllMocks();
    stderrSpy = vi.spyOn(process.stderr, 'write').mockImplementation(() => true);
  });

  afterEach(() => {
    stderrSpy.mockRestore();
  });

  describe('log entry contains all required fields for any non-excluded request', () => {
    it('every log entry contains method, path, statusCode, duration, userId, ip, and userAgent', { timeout: 15000 }, () => {
      fc.assert(
        fc.property(requestScenarioArb, (scenario) => {
          vi.clearAllMocks();

          const middleware = createRequestLogger();
          const req = createMockRequest({
            method: scenario.method,
            path: scenario.path,
            url: scenario.path,
            headers: { 'user-agent': scenario.userAgent },
            ip: scenario.ip,
          });
          (req as any).correlationId = scenario.correlationId;
          if (scenario.userId) {
            (req as any).user = { id: scenario.userId };
          }

          // Set up response with event emitter
          const listeners: Record<string, Function[]> = {};
          const res = createMockResponse();
          (res as any).on = vi.fn((event: string, handler: Function) => {
            if (!listeners[event]) listeners[event] = [];
            listeners[event].push(handler);
          });
          res.statusCode = scenario.statusCode;

          const next = createMockNext();

          middleware(req, res as any, next);

          // Simulate response finish
          if (listeners['finish']) {
            for (const handler of listeners['finish']) {
              handler();
            }
          }

          // Verify logger.info was called with all required fields
          expect(logger.info).toHaveBeenCalledTimes(1);
          const logCall = (logger.info as any).mock.calls[0];
          const logData = logCall[1];

          // All required fields must be present
          expect(logData).toHaveProperty('requestId');
          expect(logData).toHaveProperty('method');
          expect(logData).toHaveProperty('path');
          expect(logData).toHaveProperty('statusCode');
          expect(logData).toHaveProperty('duration');
          expect(logData).toHaveProperty('userId');
          expect(logData).toHaveProperty('ip');
          expect(logData).toHaveProperty('userAgent');

          // Verify field values match the request
          expect(logData.method).toBe(scenario.method);
          expect(logData.path).toBe(scenario.path);
          expect(logData.statusCode).toBe(scenario.statusCode);
          expect(typeof logData.duration).toBe('number');
          expect(logData.duration).toBeGreaterThanOrEqual(0);
          expect(logData.userId).toBe(scenario.userId);
          expect(logData.ip).toBe(scenario.ip);
          expect(logData.userAgent).toBe(scenario.userAgent);
        }),
        { numRuns: 300 }
      );
    });

    it('request ID in log entry matches the correlation ID (X-Request-Id)', { timeout: 15000 }, () => {
      fc.assert(
        fc.property(requestScenarioArb, (scenario) => {
          vi.clearAllMocks();

          const middleware = createRequestLogger();
          const req = createMockRequest({
            method: scenario.method,
            path: scenario.path,
            url: scenario.path,
            headers: { 'user-agent': scenario.userAgent },
            ip: scenario.ip,
          });
          (req as any).correlationId = scenario.correlationId;
          if (scenario.userId) {
            (req as any).user = { id: scenario.userId };
          }

          // Set up response with event emitter
          const listeners: Record<string, Function[]> = {};
          const res = createMockResponse();
          (res as any).on = vi.fn((event: string, handler: Function) => {
            if (!listeners[event]) listeners[event] = [];
            listeners[event].push(handler);
          });
          res.statusCode = scenario.statusCode;

          // Simulate the correlation ID middleware setting the X-Request-Id header
          res.setHeader('x-request-id', scenario.correlationId);

          const next = createMockNext();

          middleware(req, res as any, next);

          // Simulate response finish
          if (listeners['finish']) {
            for (const handler of listeners['finish']) {
              handler();
            }
          }

          // Verify the requestId in the log matches the X-Request-Id header
          expect(logger.info).toHaveBeenCalledTimes(1);
          const logCall = (logger.info as any).mock.calls[0];
          const logData = logCall[1];

          // The requestId in the log must match the correlation ID
          expect(logData.requestId).toBe(scenario.correlationId);

          // The X-Request-Id response header must also match
          const xRequestIdHeader = res._headers['x-request-id'];
          expect(logData.requestId).toBe(xRequestIdHeader);
        }),
        { numRuns: 300 }
      );
    });

    it('DB persist entry contains all required fields matching the log', { timeout: 15000 }, () => {
      fc.assert(
        fc.property(requestScenarioArb, (scenario) => {
          vi.clearAllMocks();

          const middleware = createRequestLogger();
          const req = createMockRequest({
            method: scenario.method,
            path: scenario.path,
            url: scenario.path,
            headers: { 'user-agent': scenario.userAgent },
            ip: scenario.ip,
          });
          (req as any).correlationId = scenario.correlationId;
          if (scenario.userId) {
            (req as any).user = { id: scenario.userId };
          }

          // Set up response with event emitter
          const listeners: Record<string, Function[]> = {};
          const res = createMockResponse();
          (res as any).on = vi.fn((event: string, handler: Function) => {
            if (!listeners[event]) listeners[event] = [];
            listeners[event].push(handler);
          });
          res.statusCode = scenario.statusCode;

          const next = createMockNext();

          middleware(req, res as any, next);

          // Simulate response finish
          if (listeners['finish']) {
            for (const handler of listeners['finish']) {
              handler();
            }
          }

          // Verify db.prepare was called with INSERT INTO request_logs
          expect(db.prepare).toHaveBeenCalledWith(
            expect.stringContaining('INSERT INTO request_logs')
          );

          // Verify the run call contains all required field values
          const prepareCall = (db.prepare as any).mock.results[0].value;
          const runCall = prepareCall.run.mock.calls[0];

          // Arguments order: requestId, userId, method, path, statusCode, durationMs, ipAddress, userAgent, errorMessage
          expect(runCall[0]).toBe(scenario.correlationId); // requestId
          expect(runCall[1]).toBe(scenario.userId);        // userId
          expect(runCall[2]).toBe(scenario.method);        // method
          expect(runCall[3]).toBe(scenario.path);          // path
          expect(runCall[4]).toBe(scenario.statusCode);    // statusCode
          expect(typeof runCall[5]).toBe('number');         // durationMs
          expect(runCall[5]).toBeGreaterThanOrEqual(0);
          expect(runCall[6]).toBe(scenario.ip);            // ipAddress
          expect(runCall[7]).toBe(scenario.userAgent);     // userAgent
        }),
        { numRuns: 300 }
      );
    });

    it('excluded paths do not produce log entries', () => {
      const excludedPathArb = fc.constantFrom(
        '/api/health',
        '/uploads/file.pdf',
        '/uploads/documents/report.docx',
        '/uploads/images/photo.png'
      );

      fc.assert(
        fc.property(excludedPathArb, httpMethodArb, (path, method) => {
          vi.clearAllMocks();

          const middleware = createRequestLogger();
          const req = createMockRequest({
