import { describe, it, expect } from 'vitest';
import fc from 'fast-check';
import { UserRole, ADMIN_ROLES, COMPLIANCE_ROLES, STAFF_ROLES } from '../../constants';
import {
  ROLES,
  MODULES,
  PERMISSIONS,
  DEFAULT_PERMISSIONS,
