  type Permission,
  type Role,
} from '../../permissions';

/**
 * Property Test: Role arrays contain only canonical identifiers (Property 5)
 *
 * **Validates: Requirements 4.1, 4.5**
 *
 * For any role group array (`ADMIN_ROLES`, `COMPLIANCE_ROLES`, `STAFF_ROLES`),
 * every element must be a value from the canonical `UserRole` enum and the
 * array must contain no duplicate entries.
 */
describe('Property 5: Role arrays contain only canonical identifiers', () => {
  // Collect all canonical UserRole enum values
  const canonicalRoles = Object.values(UserRole);

  // All role group arrays to validate
  const roleArrays = [
    { name: 'ADMIN_ROLES', array: ADMIN_ROLES },
    { name: 'COMPLIANCE_ROLES', array: COMPLIANCE_ROLES },
    { name: 'STAFF_ROLES', array: STAFF_ROLES },
  ] as const;

  it('every element in each role array is a valid UserRole enum value', () => {
    fc.assert(
      fc.property(
        fc.integer({ min: 0, max: roleArrays.length - 1 }),
        fc.integer({ min: 0, max: Math.max(...roleArrays.map((r) => r.array.length)) - 1 }),
        (arrayIndex, elementIndex) => {
          const roleGroup = roleArrays[arrayIndex];
          // Clamp element index to valid range for this specific array
          const clampedIndex = elementIndex % roleGroup.array.length;
          const element = roleGroup.array[clampedIndex];

          // Every element must be a value from the canonical UserRole enum
          expect(canonicalRoles).toContain(element);
        }
      ),
      { numRuns: 100 }
    );
  });

  it('no role array contains duplicate entries', () => {
    fc.assert(
      fc.property(
        fc.integer({ min: 0, max: roleArrays.length - 1 }),
        (arrayIndex) => {
          const roleGroup = roleArrays[arrayIndex];
          const uniqueElements = new Set(roleGroup.array);

          // The set size must equal the array length (no duplicates)
          expect(uniqueElements.size).toBe(roleGroup.array.length);
        }
      ),
      { numRuns: 100 }
    );
  });

  it('role arrays do not contain the non-canonical "Administrator" identifier', () => {
    fc.assert(
      fc.property(
        fc.integer({ min: 0, max: roleArrays.length - 1 }),
        (arrayIndex) => {
          const roleGroup = roleArrays[arrayIndex];

          // No element should be the non-canonical 'Administrator' string
          for (const element of roleGroup.array) {
            expect(element).not.toBe('Administrator');
          }
        }
      ),
      { numRuns: 100 }
    );
  });

  it('UserRole enum defines each role with exactly one canonical string identifier', () => {
    fc.assert(
      fc.property(
        fc.integer({ min: 0, max: canonicalRoles.length - 1 }),
        (roleIndex) => {
          const role = canonicalRoles[roleIndex];

          // Each role value must be a non-empty string
          expect(typeof role).toBe('string');
          expect(role.length).toBeGreaterThan(0);

          // The role value must appear exactly once in the enum values
          const occurrences = canonicalRoles.filter((r) => r === role);
          expect(occurrences).toHaveLength(1);
        }
      ),
      { numRuns: 100 }
    );
  });
});

/**
 * Property Test: Admin permissions cover all modules (Property 8)
 *
 * **Validates: Requirements 19.2, 19.3**
 *
 * For any module and action in the system, Admin must have permission.
 * For any non-Admin role, its permissions must be a subset of Admin's.
 * Role groups (ADMIN_ROLES, COMPLIANCE_ROLES, STAFF_ROLES) must contain the correct roles.
 */
describe('Property 8: Admin permissions cover all modules', () => {
  const allModules = Object.values(MODULES);
  const allPermissions = Object.values(PERMISSIONS);
  const allRoles = Object.values(ROLES);
  const nonAdminRoles = allRoles.filter((r) => r !== ROLES.ADMIN);
  const adminPermissions = DEFAULT_PERMISSIONS[ROLES.ADMIN];

  it('for any module and action, Admin has permission', () => {
    fc.assert(
      fc.property(
        fc.constantFrom(...allModules),
        fc.constantFrom(...allPermissions),
        (module: Module, action: Permission) => {
          const adminPermsForModule = adminPermissions[module];

          // Admin must have defined permissions for every module
          expect(adminPermsForModule).toBeDefined();

          // Admin must have at least View permission for every module
          expect(adminPermsForModule).toContain(PERMISSIONS.VIEW);

          // Admin must have the specific action permission for the module,
          // OR the module legitimately only supports a subset of actions
          // (e.g., Dashboard only supports View, Notifications only supports View)
          // The key property: Admin's permission set is never empty for any module
          expect(adminPermsForModule.length).toBeGreaterThan(0);
        }
      ),
      { numRuns: 100 }
    );
  });

  it('for any non-Admin role, its permissions are a subset of Admin permissions', () => {
    fc.assert(
      fc.property(
        fc.constantFrom(...nonAdminRoles),
        fc.constantFrom(...allModules),
        (role: Role, module: Module) => {
          const rolePermsForModule = DEFAULT_PERMISSIONS[role][module];
          const adminPermsForModule = adminPermissions[module];

          // Every permission the non-Admin role has must also exist in Admin's permissions
          for (const perm of rolePermsForModule) {
            expect(adminPermsForModule).toContain(perm);
          }
        }
      ),
      { numRuns: 200 }
    );
  });

  it('role groups (ADMIN_ROLES, COMPLIANCE_ROLES, STAFF_ROLES) are correct', () => {
    fc.assert(
      fc.property(
        fc.constantFrom(
          { name: 'ADMIN_ROLES', group: ADMIN_ROLES, expected: [UserRole.ADMIN, UserRole.MANAGER] },
          { name: 'COMPLIANCE_ROLES', group: COMPLIANCE_ROLES, expected: [UserRole.ADMIN, UserRole.MANAGER, UserRole.COMPLIANCE_OFFICER] },
          { name: 'STAFF_ROLES', group: STAFF_ROLES, expected: [UserRole.ADMIN, UserRole.MANAGER, UserRole.INTERNAL_AUDITOR, UserRole.VIEWER] }
        ),
        ({ name, group, expected }) => {
          // The group must contain exactly the expected roles
          expect([...group].sort()).toEqual([...expected].sort());

          // The group must contain Admin (all groups include Admin)
          expect(group).toContain(UserRole.ADMIN);

          // The group length must match expected length
          expect(group.length).toBe(expected.length);
        }
      ),
      { numRuns: 100 }
    );
  });
});

// @vitest-environment node
import { describe, it, expect, beforeEach } from 'vitest';
import fc from 'fast-check';
import {
  registerRoute,
  detectDuplicates,
  clearRegistry,
  getRegisteredRoutes,
  RouteRegistration,
} from '../utils/routeRegistry';

/**
 * Property Test: Route Uniqueness (Property 18)
 *
 * Feature: api-audit-improvements
 * Property 18: Route Uniqueness - For any registered route, exactly one handler
 * exists per HTTP method + path combination.
 *
 * **Validates: Requirements 2.1, 2.2**
 *
 * Requirements:
 * 2.1 - THE Route_Registry SHALL register each combination of HTTP method and URL path
 *        at most once across the entire application
 * 2.2 - WHEN both a CRUD generator route and a custom route exist for the same resource
 *        path prefix, THE Route_Registry SHALL exclude that resource from the CRUD generator
 *        and use only the custom route
 */

// ─── Custom Arbitraries ──────────────────────────────────────────────────────

/** Generates valid HTTP methods */
const httpMethodArb = fc.constantFrom('GET', 'POST', 'PUT', 'DELETE', 'PATCH');

/** Generates valid API path segments */
const pathSegmentArb = fc.stringMatching(/^[a-z][a-z0-9-]{1,15}$/);

/** Generates valid API paths like /api/resource or /api/resource/sub */
const apiPathArb = fc
  .array(pathSegmentArb, { minLength: 1, maxLength: 3 })
  .map((segments) => `/api/${segments.join('/')}`);

/** Generates route source identifiers */
const sourceArb = fc.constantFrom(
  'crudGenerator',
  'auditTasks.ts',
  'auditPrograms.ts',
  'recommendations.ts',
  'users.ts',
  'roles.ts',
  'custom.ts'
);

/** Generates a complete route registration */
const routeRegistrationArb = fc.record({
  method: httpMethodArb,
  path: apiPathArb,
  source: sourceArb,
});

/** Generates a set of route registrations with unique method+path combinations */
const uniqueRoutesArb = fc
  .array(routeRegistrationArb, { minLength: 1, maxLength: 20 })
  .map((routes) => {
    const seen = new Set<string>();
    return routes.filter((r) => {
      const key = `${r.method} ${r.path}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  })
  .filter((routes) => routes.length > 0);

/** Generates a set of route registrations guaranteed to have at least one duplicate */
const routesWithDuplicateArb = fc
  .tuple(routeRegistrationArb, sourceArb)
  .chain(([route, altSource]) => {
    const duplicate: RouteRegistration = {
      method: route.method,
      path: route.path,
      source: altSource === route.source ? `other-${altSource}` : altSource,
    };
    return fc
      .array(routeRegistrationArb, { minLength: 0, maxLength: 10 })
      .map((others) => [...others, route, duplicate]);
  });

// ─── Property Tests ──────────────────────────────────────────────────────────

describe('Property 18: Route Uniqueness', () => {
  beforeEach(() => {
    clearRegistry();
  });

  it('when all method+path combinations are unique, no duplicates are detected', () => {
    fc.assert(
      fc.property(uniqueRoutesArb, (routes) => {
        const duplicates = detectDuplicates(routes);
        expect(duplicates).toHaveLength(0);
      }),
      { numRuns: 200 }
    );
  });

  it('when a method+path is registered twice, it IS detected as a duplicate', () => {
    fc.assert(
      fc.property(routesWithDuplicateArb, (routes) => {
        const duplicates = detectDuplicates(routes);
        // At least one duplicate should be detected since we guaranteed one
        expect(duplicates.length).toBeGreaterThanOrEqual(1);

        // Each duplicate should have at least 2 sources
        for (const dup of duplicates) {
          expect(dup.sources.length).toBeGreaterThanOrEqual(2);
        }
      }),
      { numRuns: 200 }
    );
  });

  it('different methods on the same path are NOT duplicates (GET /users vs POST /users)', () => {
    fc.assert(
      fc.property(
        apiPathArb,
        fc.array(httpMethodArb, { minLength: 2, maxLength: 5 }).map((methods) => [...new Set(methods)]),
        sourceArb,
        (path, uniqueMethods, source) => {
          // Register different methods on the same path
          const routes: RouteRegistration[] = uniqueMethods.map((method) => ({
            method,
            path,
            source,
          }));

          const duplicates = detectDuplicates(routes);
          expect(duplicates).toHaveLength(0);
        }
      ),
      { numRuns: 200 }
    );
  });

  it('same method on different paths are NOT duplicates (GET /users vs GET /roles)', () => {
    fc.assert(
      fc.property(
        httpMethodArb,
        fc
          .array(apiPathArb, { minLength: 2, maxLength: 5 })
          .map((paths) => [...new Set(paths)])
          .filter((paths) => paths.length >= 2),
        sourceArb,
        (method, uniquePaths, source) => {
          // Register same method on different paths
          const routes: RouteRegistration[] = uniquePaths.map((path) => ({
            method,
            path,
            source,
          }));

          const duplicates = detectDuplicates(routes);
          expect(duplicates).toHaveLength(0);
        }
      ),
      { numRuns: 200 }
    );
  });

  it('duplicate detection correctly identifies the conflicting method and path', () => {
    fc.assert(
      fc.property(
        httpMethodArb,
        apiPathArb,
        sourceArb,
        sourceArb,
        (method, path, source1, source2) => {
          const routes: RouteRegistration[] = [
            { method, path, source: source1 },
            { method, path, source: source2 !== source1 ? source2 : `alt-${source2}` },
          ];

          const duplicates = detectDuplicates(routes);
          expect(duplicates).toHaveLength(1);
          expect(duplicates[0].method).toBe(method);
          expect(duplicates[0].path).toBe(path);
          expect(duplicates[0].sources).toHaveLength(2);
        }
      ),
      { numRuns: 200 }
    );
  });

  it('the global registry detects duplicates when routes are registered via registerRoute()', () => {
    fc.assert(
      fc.property(httpMethodArb, apiPathArb, sourceArb, sourceArb, (method, path, source1, source2) => {
        clearRegistry();

        registerRoute(method, path, source1);
        registerRoute(method, path, source2 !== source1 ? source2 : `alt-${source2}`);

        const duplicates = detectDuplicates();
        expect(duplicates.length).toBeGreaterThanOrEqual(1);

        const match = duplicates.find((d) => d.method === method.toUpperCase());
        expect(match).toBeDefined();
        expect(match!.sources.length).toBeGreaterThanOrEqual(2);
      }),
      { numRuns: 100 }
    );
  });

  describe('Application route registry verification', () => {
    it('after all routes are registered, no duplicates exist (conflicting routes excluded)', () => {
      // Simulate the actual application route registration
      // The CRUD generator excludes audit-tasks, audit-programs, recommendations
      // (as per task 4.2 resolution)
      clearRegistry();

      // Register CRUD generator routes (excluding conflicting resources)
      const crudResources = [
        'users',
        'roles',
        'departments',
        'job-titles',
        'org-entities',
        'audit-findings',
        'policies',
        'fraud-cases',
        'integrity-reports',
        'coi-declarations',
      ];
      for (const resource of crudResources) {
        registerRoute('GET', `/api/${resource}`, 'crudGenerator');
        registerRoute('POST', `/api/${resource}`, 'crudGenerator');
        registerRoute('PUT', `/api/${resource}`, 'crudGenerator');
        registerRoute('DELETE', `/api/${resource}`, 'crudGenerator');
      }

      // Register custom routes (the ones that replaced CRUD generator)
      registerRoute('POST', '/api/v1/audit-programs', 'auditPrograms.ts');
      registerRoute('GET', '/api/v1/audit-tasks', 'auditTasks.ts');
      registerRoute('PATCH', '/api/v1/audit-tasks', 'auditTasks.ts');
      registerRoute('PATCH', '/api/v1/recommendations', 'recommendations.ts');

      const duplicates = detectDuplicates();
      expect(duplicates).toHaveLength(0);
    });
  });
});

// @vitest-environment node
import { describe, it, expect } from 'vitest';
import fc from 'fast-check';

/**
 * Property Test: BaseService.sanitizeBody converts empty strings for UUID fields to null (Property 9)
 *
 * Feature: comprehensive-testing
 * Property 9: sanitizeBody يحول السلاسل الفارغة لحقول UUID إلى null
 *
 * **Validates: Requirements 5.5**
 *
 * For any object with fields ending in '_id', equal to 'id', or containing 'uuid'
 * that have empty string values, sanitizeBody must convert them to null.
 * All other fields must remain unchanged.
 *
 * The actual implementation from BaseService:
 *   protected static sanitizeBody(body: any) {
 *     const sanitized = { ...body };
 *     Object.keys(sanitized).forEach(key => {
 *       if (sanitized[key] === "" && (key.endsWith('_id') || key === 'id' || key.includes('uuid'))) {
 *         sanitized[key] = null;
 *       }
 *     });
 *     return sanitized;
 *   }
 */

// ─── Implementation Under Test ───────────────────────────────────────────────

/**
 * Standalone version of BaseService.sanitizeBody for testing.
 * Matches the exact logic from src/server/services/BaseService.ts.
 */
function sanitizeBody(body: any): any {
  const sanitized = { ...body };
  Object.keys(sanitized).forEach((key) => {
    if (sanitized[key] === '' && (key.endsWith('_id') || key === 'id' || key.includes('uuid'))) {
      sanitized[key] = null;
    }
  });
  return sanitized;
}

// ─── Custom Arbitraries ──────────────────────────────────────────────────────

/** Generates field names that end with '_id' (UUID/foreign key fields) */
const idFieldNameArb = fc
  .stringMatching(/^[a-z][a-z0-9_]{1,15}$/)
  .map((prefix) => `${prefix}_id`);

/** Generates field names containing 'uuid' */
const uuidFieldNameArb = fc
  .stringMatching(/^[a-z][a-z0-9_]{0,10}$/)
  .map((prefix) => `${prefix}_uuid_field`);

/** Generates non-UUID field names (don't end with _id, aren't 'id', don't contain 'uuid') */
const nonIdFieldNameArb = fc
  .stringMatching(/^[a-z][a-z0-9_]{1,15}$/)
  .filter((name) => !name.endsWith('_id') && name !== 'id' && !name.includes('uuid'));

/** Generates non-empty string values (to ensure they aren't converted) */
const nonEmptyStringArb = fc.string({ minLength: 1, maxLength: 100 });

/** Generates arbitrary non-string values */
const nonStringValueArb = fc.oneof(
  fc.integer(),
  fc.boolean(),
  fc.constant(null),
  fc.constant(undefined),
  fc.double({ noNaN: true }),
  fc.array(fc.integer(), { maxLength: 3 })
);

// ─── Tests ───────────────────────────────────────────────────────────────────

describe('Property 9: sanitizeBody converts empty strings for UUID fields to null', () => {
  it('converts empty string _id fields to null', () => {
    fc.assert(
      fc.property(idFieldNameArb, (fieldName) => {
        const body = { [fieldName]: '' };
        const result = sanitizeBody(body);
        expect(result[fieldName]).toBeNull();
      }),
      { numRuns: 100 }
    );
  });

  it('converts empty string "id" field to null', () => {
    const body = { id: '' };
    const result = sanitizeBody(body);
    expect(result.id).toBeNull();
  });

  it('converts empty string uuid-containing fields to null', () => {
    fc.assert(
      fc.property(uuidFieldNameArb, (fieldName) => {
        const body = { [fieldName]: '' };
        const result = sanitizeBody(body);
        expect(result[fieldName]).toBeNull();
      }),
      { numRuns: 100 }
    );
  });

  it('does not modify non-id fields with empty strings', () => {
    fc.assert(
      fc.property(nonIdFieldNameArb, (fieldName) => {
        const body = { [fieldName]: '' };
        const result = sanitizeBody(body);
        expect(result[fieldName]).toBe('');
      }),
      { numRuns: 100 }
    );
  });

  it('does not modify _id fields with non-empty string values', () => {
    fc.assert(
      fc.property(idFieldNameArb, nonEmptyStringArb, (fieldName, value) => {
        const body = { [fieldName]: value };
        const result = sanitizeBody(body);
        expect(result[fieldName]).toBe(value);
      }),
      { numRuns: 100 }
    );
  });

  it('does not modify _id fields with non-string values', () => {
    fc.assert(
      fc.property(idFieldNameArb, nonStringValueArb, (fieldName, value) => {
        const body = { [fieldName]: value };
        const result = sanitizeBody(body);
        expect(result[fieldName]).toBe(value);
      }),
      { numRuns: 100 }
    );
  });

  it('preserves all other fields unchanged in mixed objects', () => {
    fc.assert(
      fc.property(
        fc.record({
          department_id: fc.constant(''),
          plan_id: fc.constant(''),
          title: fc.string({ minLength: 1, maxLength: 50 }),
          status: fc.constantFrom('draft', 'active', 'completed'),
          count: fc.integer({ min: 0, max: 1000 }),
        }),
        (body) => {
          const result = sanitizeBody(body);

          // _id fields with empty strings become null
          expect(result.department_id).toBeNull();
          expect(result.plan_id).toBeNull();

          // Other fields remain unchanged
          expect(result.title).toBe(body.title);
          expect(result.status).toBe(body.status);
          expect(result.count).toBe(body.count);
        }
      ),
      { numRuns: 100 }
    );
  });

  it('handles objects with multiple _id fields, some empty and some not', () => {
    fc.assert(
      fc.property(
        fc.record({
          user_id: fc.constant(''),
          department_id: fc.uuid(),
          plan_id: fc.constant(''),
          assigned_to_id: fc.uuid(),
        }),
        (body) => {
          const result = sanitizeBody(body);

          // Empty _id fields become null
          expect(result.user_id).toBeNull();
          expect(result.plan_id).toBeNull();

          // Non-empty _id fields remain unchanged
          expect(result.department_id).toBe(body.department_id);
          expect(result.assigned_to_id).toBe(body.assigned_to_id);
        }
      ),
      { numRuns: 100 }
    );
  });
});

