import { describe, it, expect, vi, beforeEach } from 'vitest';
import fc from 'fast-check';

/**
 * Property Test: Soft Delete Cascade Integrity (Property 5)
 *
 * Feature: api-audit-improvements
 * Property 5: Soft Delete Cascade Integrity
 *
 * **Validates: Requirements 8.4, 8.6**
 *
 * For any parent record with N child records in related tables, soft-deleting
 * the parent SHALL also soft-delete all N child records within the same
 * transaction, and the total number of soft-deleted records SHALL equal N + 1.
 */

// ─── Hoisted Mocks ──────────────────────────────────────────────────────────

const { mockPrepare, mockTransaction, mockValidateIdentifier } = vi.hoisted(() => ({
  mockPrepare: vi.fn(),
  mockTransaction: vi.fn(),
  mockValidateIdentifier: vi.fn((name: string) => {
    if (!/^[a-zA-Z0-9_]+$/.test(name)) {
      throw new Error(`Invalid database identifier: ${name}`);
    }
    return name;
  }),
}));

// Mock the database module
vi.mock('../../server/db/index', () => ({
  db: {
    prepare: mockPrepare,
    transaction: mockTransaction,
    validateIdentifier: mockValidateIdentifier,
  },
}));

// Mock N8nService
vi.mock('../../server/utils/n8nService', () => ({
  N8nService: {
    sendEvent: vi.fn().mockResolvedValue(undefined),
  },
}));

// Mock AppCodeGenerator
vi.mock('../../server/utils/AppCodeGenerator', () => ({
  AppCodeGenerator: {
    generateCode: vi.fn(),
    generateFindingCode: vi.fn(),
  },
}));

// Mock crypto
vi.mock('crypto', () => ({
  default: {
    createHash: vi.fn(() => ({
      update: vi.fn().mockReturnThis(),
      digest: vi.fn(() => 'mock-hash-value'),
    })),
  },
}));

import { SoftDeleteService } from '../../server/services/SoftDeleteService';

// ─── Custom Arbitraries ──────────────────────────────────────────────────────

/** Generates valid parent table names */
const parentTableArb = fc.constantFrom(
  'audit_plans',
  'audit_programs',
  'audit_tasks'
);

/** Generates valid child table configurations */
const childTableArb = fc.record({
  table: fc.constantFrom(
    'audit_tasks',
    'audit_findings',
    'recommendations',
    'compliance_items'
  ),
  foreignKey: fc.constantFrom('plan_id', 'program_id', 'task_id', 'parent_id'),
});

/** Generates a cascade configuration with 1 to 5 child tables */
const cascadeArb = fc.array(childTableArb, { minLength: 1, maxLength: 5 });

/** Generates valid record IDs (positive integers) */
const recordIdArb = fc.integer({ min: 1, max: 100000 });

/** Generates valid user UUIDs */
const userIdArb = fc.uuid();

/** Generates the number of children per cascade table (0 to 20) */
const childCountArb = fc.integer({ min: 0, max: 20 });

// ─── Tests ───────────────────────────────────────────────────────────────────

describe('Property 5: Soft Delete Cascade Integrity', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('soft-deleting a parent with N children across cascade tables results in N+1 total soft-deleted records', async () => {
    await fc.assert(
      fc.asyncProperty(
        parentTableArb,
        recordIdArb,
        userIdArb,
        cascadeArb,
        fc.array(childCountArb, { minLength: 1, maxLength: 5 }),
        async (parentTable, parentId, userId, cascadeTables, childCounts) => {
          // Ensure childCounts matches cascadeTables length
          const effectiveCascade = cascadeTables.slice(0, Math.min(cascadeTables.length, childCounts.length));
          const effectiveChildCounts = childCounts.slice(0, effectiveCascade.length);

          // Total children across all cascade tables
          const totalChildren = effectiveChildCounts.reduce((sum, count) => sum + count, 0);

          // Track all SQL statements and their arguments
          const sqlCalls: { sql: string; args: any[] }[] = [];
          let responseIndex = 0;

          // Build response sequence:
          // 1. Parent soft delete UPDATE RETURNING id -> get
          // 2..N+1. Cascade UPDATE for each child table -> run (returns changes count)
          // N+2. Audit hash SELECT -> get
          // N+3. Audit INSERT -> run
          const responses: any[] = [
            { id: parentId }, // Parent soft delete succeeds
          ];

          // Add cascade responses (one per cascade table)
          for (const count of effectiveChildCounts) {
            responses.push({ changes: count }); // Each cascade UPDATE affects `count` children
          }

          // Audit trail responses
          responses.push({ hash: 'prev-hash' }); // Audit hash
          responses.push({ lastInsertRowid: 1, changes: 1 }); // Audit insert

          mockValidateIdentifier.mockImplementation((name: string) => {
            if (!/^[a-zA-Z0-9_]+$/.test(name)) {
              throw new Error(`Invalid database identifier: ${name}`);
            }
            return name;
          });

          mockTransaction.mockImplementation((fn: Function) => {
            return async (...args: any[]) => fn(...args);
          });

          mockPrepare.mockImplementation((sql: string) => {
            const currentIndex = responseIndex++;
            return {
              get: async (...args: any[]) => {
                sqlCalls.push({ sql, args });
                return responses[currentIndex];
              },
              all: async (...args: any[]) => {
                sqlCalls.push({ sql, args });
                return responses[currentIndex];
              },
              run: async (...args: any[]) => {
                sqlCalls.push({ sql, args });
                return responses[currentIndex];
              },
            };
          });

          // Execute soft delete with cascade
          await SoftDeleteService.softDelete({
            tableName: parentTable,
            id: parentId,
            deletedBy: userId,
            cascade: effectiveCascade,
          });

          // ─── Verify Property: Cascade Integrity ─────────────────────────

          // 1. Verify parent was soft-deleted (first SQL is the parent UPDATE)
          const parentSql = sqlCalls[0].sql;
          expect(parentSql).toContain(`UPDATE ${parentTable}`);
          expect(parentSql).toContain('SET deleted_at');
          expect(parentSql).toContain('deleted_by');
          expect(parentSql).toContain('deleted_at IS NULL');
          expect(parentSql).toContain('RETURNING id');

          // 2. Verify each cascade table received an UPDATE statement
          //    Cascade calls are at indices 1..effectiveCascade.length (right after parent)
          for (let i = 0; i < effectiveCascade.length; i++) {
            const cascadeSql = sqlCalls[i + 1].sql;
            expect(cascadeSql).toContain(`UPDATE ${effectiveCascade[i].table}`);
            expect(cascadeSql).toContain('SET deleted_at');
            expect(cascadeSql).toContain('deleted_by');
            expect(cascadeSql).toContain(`${effectiveCascade[i].foreignKey} = ?`);
            expect(cascadeSql).toContain('deleted_at IS NULL');
          }

          // 3. Verify total soft-deleted count equals N + 1
          //    (1 parent + sum of all children across cascade tables)
          const expectedTotal = 1 + totalChildren;
          const actualParentDeleted = 1; // Parent RETURNING id confirms 1 record
          const actualChildrenDeleted = effectiveChildCounts.reduce((sum, count) => sum + count, 0);
          const actualTotal = actualParentDeleted + actualChildrenDeleted;

          expect(actualTotal).toBe(expectedTotal);

          // 4. Verify the number of cascade UPDATE statements equals cascade config length
          //    The first SQL call is the parent, the next effectiveCascade.length are cascades
          const cascadeCallCount = effectiveCascade.length;
          // Verify we have at least 1 (parent) + cascadeCallCount SQL calls
          expect(sqlCalls.length).toBeGreaterThanOrEqual(1 + cascadeCallCount);

          // Each cascade SQL should NOT contain RETURNING id (only parent has that)
          for (let i = 0; i < effectiveCascade.length; i++) {
            const cascadeSql = sqlCalls[i + 1].sql;
            expect(cascadeSql).not.toContain('RETURNING id');
          }
        }
      ),
      { numRuns: 100 }
    );
  });

  it('all cascade operations occur within the same transaction as the parent soft delete', async () => {
    await fc.assert(
      fc.asyncProperty(
        parentTableArb,
        recordIdArb,
        userIdArb,
        cascadeArb,
        async (parentTable, parentId, userId, cascadeTables) => {
          let transactionExecuted = false;
          let operationsInsideTransaction: string[] = [];

          mockValidateIdentifier.mockImplementation((name: string) => {
            if (!/^[a-zA-Z0-9_]+$/.test(name)) {
              throw new Error(`Invalid database identifier: ${name}`);
            }
            return name;
          });

          // Track that all operations happen inside the transaction callback
          mockTransaction.mockImplementation((fn: Function) => {
            return async (...args: any[]) => {
              transactionExecuted = true;
              const result = await fn(...args);
              return result;
            };
          });

          let responseIndex = 0;
          const responses: any[] = [
            { id: parentId }, // Parent soft delete
          ];
          for (let i = 0; i < cascadeTables.length; i++) {
            responses.push({ changes: 2 }); // Each cascade table has 2 children
          }
          responses.push({ hash: 'prev-hash' }); // Audit hash
          responses.push({ lastInsertRowid: 1, changes: 1 }); // Audit insert

          mockPrepare.mockImplementation((sql: string) => {
            operationsInsideTransaction.push(sql);
            const currentIndex = responseIndex++;
            return {
              get: async (..._args: any[]) => responses[currentIndex],
              all: async (..._args: any[]) => responses[currentIndex],
              run: async (..._args: any[]) => responses[currentIndex],
            };
          });

          await SoftDeleteService.softDelete({
            tableName: parentTable,
            id: parentId,
            deletedBy: userId,
            cascade: cascadeTables,
          });

          // Verify transaction was used
          expect(transactionExecuted).toBe(true);

          // Verify parent UPDATE and all cascade UPDATEs happened inside the transaction
          const parentUpdate = operationsInsideTransaction.find(sql =>
            sql.includes(`UPDATE ${parentTable}`) && sql.includes('RETURNING id')
          );
          expect(parentUpdate).toBeDefined();

          for (const rel of cascadeTables) {
            const cascadeUpdate = operationsInsideTransaction.find(sql =>
              sql.includes(`UPDATE ${rel.table}`) && sql.includes(`${rel.foreignKey} = ?`)
            );
            expect(cascadeUpdate).toBeDefined();
          }
        }
      ),
      { numRuns: 100 }
    );
  });
});

// @vitest-environment node
import { describe, it, expect, vi, beforeEach } from 'vitest';
import fc from 'fast-check';

/**
 * Property Test: Soft Delete Round-Trip (Property 4)
 *
 * Feature: api-audit-improvements
 * Property 4: Soft Delete Round-Trip
 *
 * **Validates: Requirements 8.1, 8.2, 8.3**
 *
 * For any record in any soft-delete-enabled table, performing a soft delete
 * followed by a restore SHALL return the record to its original active state
 * with `deleted_at` equal to null, and while soft-deleted the record SHALL NOT
 * appear in standard query results.
 */

// ─── Hoisted Mocks ──────────────────────────────────────────────────────────

const { mockPrepare, mockTransaction, mockValidateIdentifier } = vi.hoisted(() => ({
  mockPrepare: vi.fn(),
  mockTransaction: vi.fn(),
  mockValidateIdentifier: vi.fn((name: string) => {
    if (!/^[a-zA-Z0-9_]+$/.test(name)) {
      throw new Error(`Invalid database identifier: ${name}`);
    }
    return name;
  }),
}));

// Mock the database module
vi.mock('../../server/db/index', () => ({
  db: {
    prepare: mockPrepare,
    transaction: mockTransaction,
    validateIdentifier: mockValidateIdentifier,
  },
}));

// Mock N8nService
vi.mock('../../server/utils/n8nService', () => ({
  N8nService: {
    sendEvent: vi.fn().mockResolvedValue(undefined),
  },
}));

// Mock AppCodeGenerator
vi.mock('../../server/utils/AppCodeGenerator', () => ({
  AppCodeGenerator: {
    generateCode: vi.fn(),
    generateFindingCode: vi.fn(),
  },
}));

// Mock crypto
vi.mock('crypto', () => ({
  default: {
    createHash: vi.fn(() => ({
      update: vi.fn().mockReturnThis(),
      digest: vi.fn(() => 'mock-hash-value'),
    })),
  },
}));

import { SoftDeleteService } from '../../server/services/SoftDeleteService';
import { BaseService } from '../../server/services/BaseService';

// ─── Custom Arbitraries ──────────────────────────────────────────────────────

/** Generates valid table names (alphanumeric + underscore, common entity tables) */
const tableNameArb = fc.constantFrom(
  'audit_plans',
  'audit_tasks',
  'audit_programs',
  'audit_findings',
  'recommendations',
  'risk_register',
  'compliance_items'
);

/** Generates valid record IDs (positive integers) */
const recordIdArb = fc.integer({ min: 1, max: 100000 });

/** Generates valid user UUIDs */
const userIdArb = fc.uuid();

// ─── Helper ──────────────────────────────────────────────────────────────────

/**
 * Sets up the mock database to capture SQL statements and provide sequential responses.
 * Each call to db.prepare(sql) captures the SQL and returns a statement object.
 * The statement's get/all/run methods return the next value from the response queue.
 */
function setupMocksWithResponses(responses: any[]) {
  const sqlCalls: string[] = [];
  let responseIndex = 0;

  mockValidateIdentifier.mockImplementation((name: string) => {
    if (!/^[a-zA-Z0-9_]+$/.test(name)) {
      throw new Error(`Invalid database identifier: ${name}`);
    }
    return name;
  });

  mockTransaction.mockImplementation((fn: Function) => {
    return async (...args: any[]) => fn(...args);
  });

  mockPrepare.mockImplementation((sql: string) => {
    sqlCalls.push(sql);
    return {
      get: async (..._args: any[]) => responses[responseIndex++],
      all: async (..._args: any[]) => responses[responseIndex++],
      run: async (..._args: any[]) => responses[responseIndex++],
    };
  });

  return { sqlCalls };
}

// ─── Tests ───────────────────────────────────────────────────────────────────

describe('Property 4: Soft Delete Round-Trip', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('soft delete followed by restore returns record to original active state (deleted_at = null)', async () => {
    await fc.assert(
      fc.asyncProperty(
        tableNameArb,
        recordIdArb,
        userIdArb,
        async (tableName, recordId, userId) => {
          // Responses for the full round-trip:
          // Phase 1 - Soft Delete (inside transaction):
          //   1. UPDATE ... RETURNING id (soft delete main record) -> get
          //   2. SELECT hash FROM audit_trail (get previous hash) -> get
          //   3. INSERT INTO audit_trail (log audit) -> run
          // Phase 2 - Restore (no transaction):
          //   4. UPDATE ... SET deleted_at = NULL ... RETURNING id -> get
          //   5. SELECT hash FROM audit_trail (get previous hash) -> get
          //   6. INSERT INTO audit_trail (log audit) -> run
          const { sqlCalls } = setupMocksWithResponses([
            { id: recordId },                              // 0: soft delete RETURNING
            { hash: 'prev-hash' },                         // 1: audit hash
            { lastInsertRowid: 1, changes: 1 },            // 2: audit insert
            { id: recordId },                              // 3: restore RETURNING
            { hash: 'prev-hash' },                         // 4: audit hash
            { lastInsertRowid: 2, changes: 1 },            // 5: audit insert
          ]);

          // Phase 1: Soft Delete
          await SoftDeleteService.softDelete({
            tableName,
            id: recordId,
            deletedBy: userId,
          });

          // Verify soft delete SQL sets deleted_at and requires record is not already deleted
          const softDeleteSql = sqlCalls[0];
          expect(softDeleteSql).toContain('deleted_at');
          expect(softDeleteSql).toContain('deleted_by');
          expect(softDeleteSql).toContain('deleted_at IS NULL');

          // Phase 2: Restore
          await SoftDeleteService.restore(tableName, recordId, userId);

          // Find the restore SQL (should clear deleted_at and deleted_by)
          const restoreSql = sqlCalls.find(sql =>
            sql.includes('SET deleted_at = NULL') && sql.includes('deleted_by = NULL')
          );
          expect(restoreSql).toBeDefined();
          expect(restoreSql!).toContain('deleted_at IS NOT NULL');

          // The round-trip property: after soft delete + restore,
          // the restore SQL clears deleted_at and deleted_by back to NULL
          // confirming the record returns to its original active state
          expect(restoreSql!).toContain('SET deleted_at = NULL, deleted_by = NULL');
        }
      ),
      { numRuns: 100 }
    );
  });

  it('soft-deleted records do not appear in standard findAll queries (deleted_at IS NULL filter)', async () => {
    await fc.assert(
      fc.asyncProperty(
        tableNameArb,
        fc.integer({ min: 1, max: 10 }),
        async (tableName, totalActiveRecords) => {
          // findAll makes 2 prepare calls: COUNT and SELECT
          const activeRecords = Array.from({ length: totalActiveRecords }, (_, i) => ({
            id: i + 1,
            title: `Active Record ${i + 1}`,
            deleted_at: null,
          }));

          const { sqlCalls } = setupMocksWithResponses([
            { total: totalActiveRecords },  // 0: COUNT query -> get
            activeRecords,                   // 1: SELECT query -> all
          ]);

          const result = await BaseService.findAll(tableName, { page: 1, pageSize: 20 });

          // Both COUNT and SELECT queries must include the soft-delete exclusion filter
          expect(sqlCalls.length).toBeGreaterThanOrEqual(2);
          const countQuery = sqlCalls[0];
          const selectQuery = sqlCalls[1];
          expect(countQuery).toContain('deleted_at IS NULL');
          expect(selectQuery).toContain('deleted_at IS NULL');

          // Verify no returned records have deleted_at set (all are active)
          expect(Array.isArray(result.data)).toBe(true);
          for (const record of result.data) {
            expect(record.deleted_at).toBeNull();
          }
        }
      ),
      { numRuns: 100 }
    );
  });

  it('soft-deleted records do not appear in standard findById queries (deleted_at IS NULL filter)', async () => {
    await fc.assert(
      fc.asyncProperty(
        tableNameArb,
        recordIdArb,
        async (tableName, recordId) => {
          // findById returns null when record is soft-deleted (filtered by deleted_at IS NULL)
          const { sqlCalls } = setupMocksWithResponses([
            null, // 0: SELECT ... WHERE id = ? AND deleted_at IS NULL -> get returns null
          ]);

          // findById should throw NotFoundError for soft-deleted records
          await expect(
            BaseService.findById(tableName, recordId)
          ).rejects.toThrow();

          // Verify the query includes the soft-delete exclusion filter
          const findByIdQuery = sqlCalls[0];
          expect(findByIdQuery).toContain('deleted_at IS NULL');
          expect(findByIdQuery).toContain('WHERE id = ?');
        }
      ),
      { numRuns: 100 }
    );
  });

  it('restore only succeeds on soft-deleted records (requires deleted_at IS NOT NULL)', async () => {
    await fc.assert(
      fc.asyncProperty(
        tableNameArb,
        recordIdArb,
        userIdArb,
        async (tableName, recordId, userId) => {
          // Mock: restore on a record that is NOT soft-deleted returns null
          const { sqlCalls } = setupMocksWithResponses([
            null, // 0: UPDATE ... WHERE deleted_at IS NOT NULL -> get returns null
          ]);

          // Restore should throw NotFoundError for records that aren't soft-deleted
          await expect(
            SoftDeleteService.restore(tableName, recordId, userId)
          ).rejects.toThrow();

          // Verify the SQL requires deleted_at IS NOT NULL
          const restoreQuery = sqlCalls[0];
          expect(restoreQuery).toContain('deleted_at IS NOT NULL');
        }
      ),
      { numRuns: 100 }
    );
  });
});

// @vitest-environment node
import { describe, it, expect, vi, beforeEach } from 'vitest';
import fc from 'fast-check';
import {
  auditTaskStatusArb,
  validStatusTransitionArb,
  invalidStatusTransitionArb,
} from '../../test/helpers/arbitraries';

/**
 * Property Test: Audit task status transitions follow the allowed sequence (Property 11)
 *
 * Feature: comprehensive-testing
 * Property 11: انتقالات حالة مهام التدقيق تتبع التسلسل المسموح
 *
 * **Validates: Requirements 9.4**
 *
 * For any audit task in a given status, only allowed transitions are accepted
 * (draft→in_progress→review→approved→completed, plus review→in_progress).
 * All other transitions must be rejected with a ValidationError.
 *
 * The actual implementation from AuditTaskService:
 *   ALLOWED_TRANSITIONS maps each status to its valid next statuses with role constraints.
 *   changeStatus() throws ValidationError('Invalid status transition') for disallowed transitions.
 */

// ─── Implementation Under Test ───────────────────────────────────────────────

/**
 * Standalone version of the ALLOWED_TRANSITIONS map from AuditTaskService.
 * Matches the exact logic from src/server/services/AuditTaskService.ts.
 */
const ALLOWED_TRANSITIONS: Record<string, Record<string, { roles: string[] }>> = {
  draft: {
    in_progress: { roles: ['Auditor', 'Internal Auditor', 'Manager'] },
  },
  in_progress: {
    review: { roles: ['Auditor', 'Internal Auditor'] },
  },
  review: {
    approved: { roles: ['Manager'] },
    in_progress: { roles: ['Manager'] },
  },
  approved: {
    completed: { roles: ['Manager'] },
  },
};

/**
 * Validates whether a status transition is allowed.
 * Returns true if the transition is valid, false otherwise.
 */
function isTransitionAllowed(currentStatus: string, newStatus: string): boolean {
  const allowed = ALLOWED_TRANSITIONS[currentStatus.toLowerCase()]?.[newStatus.toLowerCase()];
  return !!allowed;
}

/**
 * Simulates AuditTaskService.changeStatus validation logic.
 * Throws an error for invalid transitions, returns success for valid ones.
 */
function validateStatusTransition(currentStatus: string, newStatus: string): void {
  const allowed = ALLOWED_TRANSITIONS[currentStatus.toLowerCase()]?.[newStatus.toLowerCase()];
  if (!allowed) {
    throw new Error('Invalid status transition');
  }
}

// ─── Tests ───────────────────────────────────────────────────────────────────

describe('Property 11: Audit task status transitions follow the allowed sequence', () => {
  it('accepts all valid status transitions', () => {
    fc.assert(
      fc.property(validStatusTransitionArb, ([fromStatus, toStatus]) => {
        // Valid transitions should not throw
        expect(() => validateStatusTransition(fromStatus, toStatus)).not.toThrow();
        expect(isTransitionAllowed(fromStatus, toStatus)).toBe(true);
      }),
      { numRuns: 100 }
    );
  });

  it('rejects all invalid status transitions', () => {
    fc.assert(
      fc.property(invalidStatusTransitionArb, ([fromStatus, toStatus]) => {
        // Invalid transitions should throw
        expect(() => validateStatusTransition(fromStatus, toStatus)).toThrow(
          'Invalid status transition'
        );
        expect(isTransitionAllowed(fromStatus, toStatus)).toBe(false);
      }),
      { numRuns: 100 }
    );
  });

  it('rejects transitions from terminal state (completed)', () => {
    fc.assert(
      fc.property(auditTaskStatusArb, (targetStatus) => {
        // 'completed' is a terminal state - no transitions allowed from it
        expect(() => validateStatusTransition('completed', targetStatus)).toThrow(
          'Invalid status transition'
        );
        expect(isTransitionAllowed('completed', targetStatus)).toBe(false);
      }),
      { numRuns: 100 }
    );
  });

  it('rejects self-transitions (same status to same status)', () => {
    fc.assert(
      fc.property(auditTaskStatusArb, (status) => {
        // A task cannot transition to its own current status
        expect(() => validateStatusTransition(status, status)).toThrow(
          'Invalid status transition'
        );
        expect(isTransitionAllowed(status, status)).toBe(false);
      }),
      { numRuns: 100 }
    );
  });

  it('rejects backward transitions except review→in_progress', () => {
    // Define backward transitions that should be rejected
    const invalidBackwardTransitions: Array<[string, string]> = [
      ['in_progress', 'draft'],
      ['approved', 'review'],
      ['approved', 'in_progress'],
      ['approved', 'draft'],
      ['completed', 'approved'],
      ['completed', 'review'],
      ['completed', 'in_progress'],
      ['completed', 'draft'],
    ];

    const backwardTransitionArb = fc.constantFrom(...invalidBackwardTransitions);

    fc.assert(
      fc.property(backwardTransitionArb, ([fromStatus, toStatus]) => {
        expect(() => validateStatusTransition(fromStatus, toStatus)).toThrow(
          'Invalid status transition'
        );
        expect(isTransitionAllowed(fromStatus, toStatus)).toBe(false);
      }),
      { numRuns: 100 }
    );
  });

  it('each status has a deterministic set of allowed next statuses', () => {
    // Verify the exact allowed transitions for each status
    const expectedTransitions: Record<string, string[]> = {
      draft: ['in_progress'],
      in_progress: ['review'],
      review: ['approved', 'in_progress'],
      approved: ['completed'],
      completed: [],
    };

    fc.assert(
      fc.property(auditTaskStatusArb, (status) => {
        const expected = expectedTransitions[status] || [];
        const allStatuses = ['draft', 'in_progress', 'review', 'approved', 'completed'];

        for (const target of allStatuses) {
          if (expected.includes(target)) {
            expect(isTransitionAllowed(status, target)).toBe(true);
          } else {
            expect(isTransitionAllowed(status, target)).toBe(false);
          }
        }
      }),
      { numRuns: 100 }
    );
  });
});

// @vitest-environment node
import { describe, it, expect } from 'vitest';
import fc from 'fast-check';
import { z } from 'zod';
import { validateBody, validate } from '../middleware/validate';
import {
  createMockRequest,
  createMockResponse,
  createMockNext,
} from './helpers/apiTestUtils';

/**
 * Property Test: Validation Layer Unknown Field Stripping (Property 13)
 *
 * Feature: api-audit-improvements
 * Property 13: Validation Layer Unknown Field Stripping
 *
 * **Validates: Requirements 6.2, 6.5**
 *
 * For any request body containing fields not defined in the endpoint's Zod schema,
 * those fields SHALL be removed before the request reaches the handler, and the
 * handler SHALL only receive schema-defined fields.
 */

// ─── Schemas Under Test ──────────────────────────────────────────────────────

/** Simple flat schema with required and optional fields */
const flatSchema = z.object({
  name: z.string().min(1).max(100),
  email: z.string().email(),
  age: z.number().int().positive().optional(),
});

/** Nested object schema */
const nestedSchema = z.object({
  title: z.string().min(1).max(200),
  metadata: z.object({
    priority: z.enum(['low', 'medium', 'high']),
    tags: z.array(z.string()).optional(),
  }),
  active: z.boolean().default(true),
});

/** Schema with various field types */
const mixedTypesSchema = z.object({
  id: z.number().int().positive(),
  label: z.string().min(1),
  enabled: z.boolean(),
  score: z.number().min(0).max(100).optional(),
  notes: z.string().nullable().optional(),
});

// ─── Reserved/Prototype property names to exclude from generated field names ─

const RESERVED_PROPERTIES = new Set([
  'toString',
  'valueOf',
  'hasOwnProperty',
  'isPrototypeOf',
  'propertyIsEnumerable',
  'toLocaleString',
  'constructor',
  '__proto__',
  '__defineGetter__',
  '__defineSetter__',
  '__lookupGetter__',
  '__lookupSetter__',
]);

// ─── Custom Arbitraries ──────────────────────────────────────────────────────

/**
 * Generates safe field names: starts with a letter, alphanumeric + underscore,
 * excludes JS prototype properties and schema-defined fields.
 */
function safeFieldNameArb(schemaKeys: string[]): fc.Arbitrary<string> {
  return fc
    .stringMatching(/^[a-z][a-z0-9_]{0,20}$/)
    .filter((s) => !schemaKeys.includes(s) && !RESERVED_PROPERTIES.has(s) && s.length >= 2);
}

/** Generates arbitrary JSON-safe values for unknown fields */
const arbitraryValueArb = fc.oneof(
  fc.string({ maxLength: 50 }),
  fc.integer(),
  fc.boolean(),
  fc.constant(null),
  fc.array(fc.string({ maxLength: 10 }), { maxLength: 3 })
);

/** Generates 1-5 unknown extra fields as a record for flat schema */
const extraFlatFieldsArb = fc
  .array(fc.tuple(safeFieldNameArb(['name', 'email', 'age']), arbitraryValueArb), {
    minLength: 1,
    maxLength: 5,
  })
  .map((pairs) => Object.fromEntries(pairs));

/** Generates extra fields for nested schema */
const extraNestedFieldsArb = fc
  .array(fc.tuple(safeFieldNameArb(['title', 'metadata', 'active']), arbitraryValueArb), {
    minLength: 1,
    maxLength: 5,
  })
  .map((pairs) => Object.fromEntries(pairs));

/** Generates extra fields for mixed types schema */
const extraMixedFieldsArb = fc
  .array(
    fc.tuple(safeFieldNameArb(['id', 'label', 'enabled', 'score', 'notes']), arbitraryValueArb),
    { minLength: 1, maxLength: 5 }
  )
  .map((pairs) => Object.fromEntries(pairs));

/**
 * Generates valid emails that pass Zod's email validation.
 * Uses a structured approach: localpart@domain.tld
 */
const validEmailArb = fc
  .tuple(
    fc.stringMatching(/^[a-z][a-z0-9]{1,8}$/),
    fc.stringMatching(/^[a-z]{2,6}$/),
    fc.constantFrom('com', 'org', 'net', 'io', 'dev')
  )
  .map(([local, domain, tld]) => `${local}@${domain}.${tld}`);

/** Generates valid data for the flat schema */
const validFlatDataArb = fc.record({
  name: fc.string({ minLength: 1, maxLength: 50 }).filter((s) => s.trim().length >= 1),
  email: validEmailArb,
  age: fc.option(fc.integer({ min: 1, max: 150 }), { nil: undefined }),
});

/** Generates valid data for the nested schema */
const validNestedDataArb = fc.record({
  title: fc.string({ minLength: 1, maxLength: 100 }).filter((s) => s.trim().length >= 1),
  metadata: fc.record({
    priority: fc.constantFrom('low' as const, 'medium' as const, 'high' as const),
    tags: fc.option(fc.array(fc.string({ minLength: 1, maxLength: 10 }), { maxLength: 3 }), {
      nil: undefined,
    }),
  }),
  active: fc.option(fc.boolean(), { nil: undefined }),
});

/** Generates valid data for the mixed types schema */
const validMixedDataArb = fc.record({
  id: fc.integer({ min: 1, max: 100000 }),
  label: fc.string({ minLength: 1, maxLength: 50 }).filter((s) => s.trim().length >= 1),
  enabled: fc.boolean(),
  score: fc.option(fc.integer({ min: 0, max: 100 }), { nil: undefined }),
  notes: fc.option(fc.oneof(fc.string({ maxLength: 100 }), fc.constant(null)), {
    nil: undefined,
  }),
});

// ─── Tests ───────────────────────────────────────────────────────────────────

describe('Property 13: Validation Layer Unknown Field Stripping', () => {
  describe('validateBody strips unknown fields from flat schemas', () => {
    it('strips all unknown fields while preserving schema-defined fields', () => {
      fc.assert(
        fc.property(validFlatDataArb, extraFlatFieldsArb, (validData, extraFields) => {
          // Combine valid data with extra unknown fields
          const bodyWithExtras = { ...validData, ...extraFields };

          const req = createMockRequest({
            method: 'POST',
            body: bodyWithExtras,
          });
          const res = createMockResponse();
          const next = createMockNext();

          validateBody(flatSchema)(req, res as any, next);

          // Handler should have been called (validation passed)
          expect(next).toHaveBeenCalled();

          // Verify only schema-defined keys remain
          const resultKeys = Object.keys(req.body);
          const schemaKeys = ['name', 'email', 'age'];
          for (const key of resultKeys) {
            expect(schemaKeys).toContain(key);
          }

          // Verify no extra field keys are present (check own properties only)
          for (const extraKey of Object.keys(extraFields)) {
            expect(Object.prototype.hasOwnProperty.call(req.body, extraKey)).toBe(false);
          }

          // Verify schema-defined fields are preserved
          expect(req.body.name).toBe(validData.name);
          expect(req.body.email).toBe(validData.email);
        }),
        { numRuns: 200 }
      );
    });

    it('handler receives only schema-defined keys regardless of extra field count', () => {
      fc.assert(
        fc.property(
          validFlatDataArb,
          fc.integer({ min: 1, max: 15 }),
          (validData, extraCount) => {
            // Generate N extra fields dynamically with safe names
            const extraFields: Record<string, unknown> = {};
            for (let i = 0; i < extraCount; i++) {
              extraFields[`xtra_field_${i}`] = `value_${i}`;
            }

            const bodyWithExtras = { ...validData, ...extraFields };

            const req = createMockRequest({
              method: 'POST',
              body: bodyWithExtras,
            });
            const res = createMockResponse();
            const next = createMockNext();

            validateBody(flatSchema)(req, res as any, next);

            expect(next).toHaveBeenCalled();

            // Result should have at most the schema-defined keys
            const resultKeys = Object.keys(req.body);
            expect(resultKeys.length).toBeLessThanOrEqual(3); // name, email, age
            expect(resultKeys.every((k) => ['name', 'email', 'age'].includes(k))).toBe(true);
          }
        ),
        { numRuns: 200 }
      );
    });
  });

  describe('validateBody strips unknown fields from nested schemas', () => {
    it('strips top-level unknown fields from nested schema bodies', () => {
      fc.assert(
        fc.property(validNestedDataArb, extraNestedFieldsArb, (validData, extraFields) => {
          const bodyWithExtras = { ...validData, ...extraFields };

          const req = createMockRequest({
            method: 'POST',
            body: bodyWithExtras,
          });
          const res = createMockResponse();
          const next = createMockNext();

          validateBody(nestedSchema)(req, res as any, next);

          expect(next).toHaveBeenCalled();

          // Verify only schema-defined top-level keys remain
          const resultKeys = Object.keys(req.body);
          const schemaKeys = ['title', 'metadata', 'active'];
          for (const key of resultKeys) {
            expect(schemaKeys).toContain(key);
          }

          // Verify extra fields are stripped (check own properties only)
          for (const extraKey of Object.keys(extraFields)) {
            expect(Object.prototype.hasOwnProperty.call(req.body, extraKey)).toBe(false);
          }

          // Verify schema-defined fields are preserved
          expect(req.body.title).toBe(validData.title);
          expect(req.body.metadata.priority).toBe(validData.metadata.priority);
        }),
        { numRuns: 200 }
      );
    });
  });

  describe('validate() combined middleware strips unknown fields from body', () => {
    it('strips unknown fields when using combined validate with body schema', () => {
      const querySchema = z.object({
        format: z.enum(['json', 'csv']).default('json'),
      });

      fc.assert(
        fc.property(validMixedDataArb, extraMixedFieldsArb, (validData, extraFields) => {
          const bodyWithExtras = { ...validData, ...extraFields };

          const req = createMockRequest({
            method: 'POST',
            body: bodyWithExtras,
            query: { format: 'json' },
          });
          const res = createMockResponse();
          const next = createMockNext();

          validate({ body: mixedTypesSchema, query: querySchema })(req, res as any, next);

          expect(next).toHaveBeenCalled();

          // Verify only schema-defined keys remain in body
          const resultKeys = Object.keys(req.body);
          const schemaKeys = ['id', 'label', 'enabled', 'score', 'notes'];
          for (const key of resultKeys) {
            expect(schemaKeys).toContain(key);
          }

          // Verify extra fields are stripped (check own properties only)
          for (const extraKey of Object.keys(extraFields)) {
            expect(Object.prototype.hasOwnProperty.call(req.body, extraKey)).toBe(false);
          }
        }),
        { numRuns: 200 }
      );
    });
  });

  describe('stripping preserves data integrity of schema-defined fields', () => {
    it('schema-defined field values are unchanged after stripping', () => {
      fc.assert(
        fc.property(validFlatDataArb, extraFlatFieldsArb, (validData, extraFields) => {
          const bodyWithExtras = { ...validData, ...extraFields };

          const req = createMockRequest({
            method: 'POST',
            body: bodyWithExtras,
          });
          const res = createMockResponse();
          const next = createMockNext();

          validateBody(flatSchema)(req, res as any, next);

          expect(next).toHaveBeenCalled();

          // Values of schema-defined fields must be identical
          expect(req.body.name).toBe(validData.name);
          expect(req.body.email).toBe(validData.email);
          if (validData.age !== undefined) {
            expect(req.body.age).toBe(validData.age);
          }
        }),
        { numRuns: 200 }
      );
    });
  });
});

import { describe, it, expect } from 'vitest';

describe('WebSocket Security', () => {
  it('should reject connections without token during upgrade (HTTP 401)', () => {
    // The upgrade handler checks for ?token= query parameter
    // If missing, it writes HTTP/1.1 401 and destroys the socket
    const token: string | null = null;
    const shouldReject = !token;
    expect(shouldReject).toBe(true);
  });

  it('should reject connections with invalid token during upgrade (HTTP 401)', () => {
    // If token verification fails (expired, invalid signature, etc.)
    // the upgrade handler writes HTTP/1.1 401 and destroys the socket
    const tokenIsValid = false;
    const shouldReject = !tokenIsValid;
    expect(shouldReject).toBe(true);
  });

  it('should use RS256 algorithm for WebSocket token verification', () => {
    const EXPECTED_ALGORITHM = 'RS256';
    const algorithms = ['RS256'];

    expect(algorithms).toContain(EXPECTED_ALGORITHM);
    // Should NOT accept HS256 (symmetric) for asymmetric key verification
    expect(algorithms).not.toContain('HS256');
  });

  it('should attach userId and username to authenticated WebSocket', () => {
    // After successful JWT verification during upgrade,
    // userId and username are attached to the ws instance
    const decoded = { id: 'user-123', username: 'testuser' };
    const ws: any = {};
    ws.userId = decoded.id;
    ws.username = decoded.username;
    ws.authenticated = true;

    expect(ws.userId).toBe('user-123');
    expect(ws.username).toBe('testuser');
    expect(ws.authenticated).toBe(true);
  });

  it('should not allow any unauthenticated connection to remain open', () => {
    // With upgrade-based auth, connections are either:
    // 1. Rejected immediately (no token or invalid token) - never opened
    // 2. Accepted with full authentication - always authenticated
    // There is no window where an unauthenticated connection exists
    const authenticationIsImmediate = true;
    const noUnauthenticatedConnectionsPossible = authenticationIsImmediate;
    expect(noUnauthenticatedConnectionsPossible).toBe(true);
  });

  it('should implement heartbeat mechanism for authenticated connections', () => {
    const HEARTBEAT_INTERVAL = 30000;

    // 30 second heartbeat is standard for detecting stale connections
    expect(HEARTBEAT_INTERVAL).toBe(30000);
  });
});

import Redis from 'ioredis';

/**
 * SessionCacheAdapter interface for session/permission caching.
 * Supports both Redis (multi-instance) and in-memory (single-instance/dev) backends.
 */
export interface SessionCacheAdapter {
  get(key: string): Promise<{ data: unknown; expires: number } | undefined>;
  set(key: string, value: { data: unknown; expires: number }): Promise<void>;
  delete(key: string): Promise<void>;
  clear(pattern?: string): Promise<void>;
  keys(): Promise<string[]>;
}

/**
 * In-memory session cache using a Map.
 * Used as fallback when REDIS_URL is not defined (single-instance/dev mode).
 */
export class InMemorySessionCache implements SessionCacheAdapter {
  private cache = new Map<string, { data: unknown; expires: number }>();
  private maxSize: number;

  constructor(maxSize = 1000) {
    this.maxSize = maxSize;
  }

  async get(key: string): Promise<{ data: unknown; expires: number } | undefined> {
    const cached = this.cache.get(key);
    if (cached && cached.expires > Date.now()) return cached;
    if (cached) this.cache.delete(key);
    return undefined;
  }

  async set(key: string, value: { data: unknown; expires: number }): Promise<void> {
    // Evict expired entries and enforce max size
    if (this.cache.size >= this.maxSize) {
      const now = Date.now();
      for (const [k, v] of this.cache) {
        if (v.expires < now) this.cache.delete(k);
      }
      // If still too large, clear oldest 20%
      if (this.cache.size >= this.maxSize) {
        const entries = [...this.cache.entries()].sort((a, b) => a[1].expires - b[1].expires);
        const toRemove = Math.ceil(entries.length * 0.2);
        for (let i = 0; i < toRemove; i++) {
          this.cache.delete(entries[i][0]);
        }
      }
    }
    this.cache.set(key, value);
  }

  async delete(key: string): Promise<void> {
    this.cache.delete(key);
  }

  async clear(pattern?: string): Promise<void> {
    if (!pattern) {
      this.cache.clear();
      return;
    }
    for (const key of this.cache.keys()) {
      if (key.startsWith(pattern)) {
        this.cache.delete(key);
      }
    }
  }

  async keys(): Promise<string[]> {
    return [...this.cache.keys()];
  }
}

/**
 * Redis-backed session cache for multi-instance deployments.
 * Shares session state across all instances via Redis on port 6379.
 * TTL is managed server-side by Redis PEXPIRE.
 */
export class RedisSessionCache implements SessionCacheAdapter {
  private redis: Redis;
  private prefix: string;

  constructor(redisUrl: string, prefix = 'session_cache:') {
    this.redis = new Redis(redisUrl, {
      maxRetriesPerRequest: 3,
      retryStrategy(times: number) {
        if (times > 3) return null;
        return Math.min(times * 200, 2000);
      },
      lazyConnect: true,
    });
    this.prefix = prefix;

    this.redis.on('error', (err: Error) => {
      // Log but don't crash — callers handle fallback
      if (process.env.NODE_ENV !== 'test') {
        console.error('[RedisSessionCache] Redis connection error:', err.message);
      }
    });
  }

  private prefixedKey(key: string): string {
    return `${this.prefix}${key}`;
  }

  async get(key: string): Promise<{ data: unknown; expires: number } | undefined> {
    try {
      const raw = await this.redis.get(this.prefixedKey(key));
      if (!raw) return undefined;
      const parsed = JSON.parse(raw) as { data: unknown; expires: number };
      if (parsed.expires <= Date.now()) {
        await this.redis.del(this.prefixedKey(key));
        return undefined;
      }
      return parsed;
    } catch {
      return undefined;
    }
  }

  async set(key: string, value: { data: unknown; expires: number }): Promise<void> {
    try {
      const ttlMs = value.expires - Date.now();
      if (ttlMs <= 0) return;
      await this.redis.set(
        this.prefixedKey(key),
        JSON.stringify(value),
        'PX',
        ttlMs
      );
    } catch {
      // Silently fail — cache is best-effort
    }
  }

  async delete(key: string): Promise<void> {
    try {
      await this.redis.del(this.prefixedKey(key));
    } catch {
      // Silently fail
    }
  }

  async clear(pattern?: string): Promise<void> {
    try {
      if (!pattern) {
        // Clear all keys with our prefix
        const keys = await this.redis.keys(`${this.prefix}*`);
        if (keys.length > 0) {
          await this.redis.del(...keys);
        }
        return;
      }
      // Clear keys matching prefix + pattern
      const keys = await this.redis.keys(`${this.prefix}${pattern}*`);
      if (keys.length > 0) {
        await this.redis.del(...keys);
      }
    } catch {
      // Silently fail
    }
  }

  async keys(): Promise<string[]> {
    try {
      const keys = await this.redis.keys(`${this.prefix}*`);
      return keys.map(k => k.slice(this.prefix.length));
    } catch {
      return [];
    }
  }

  async connect(): Promise<void> {
    await this.redis.connect();
  }

  async disconnect(): Promise<void> {
    await this.redis.disconnect();
  }
}

/**
 * Factory: creates the appropriate cache adapter based on environment.
 * Uses Redis when REDIS_URL is defined, in-memory otherwise.
 */
export function createSessionCache(): SessionCacheAdapter {
  const redisUrl = process.env.REDIS_URL;
  if (redisUrl) {
    const redisCache = new RedisSessionCache(redisUrl);
    // Attempt connection — non-blocking
    redisCache.connect().catch((err: Error) => {
      console.error('[SessionCache] Failed to connect to Redis, operations will fail gracefully:', err.message);
    });
    return redisCache;
  }
  return new InMemorySessionCache();
}

import cron from 'node-cron';
import { db } from '../db/index';
import logger from '../utils/logger';
import { NotificationService } from '../services/NotificationService';
import { UserRole } from '../../constants';
import { backupScheduler } from '../utils/backup';
import { updateCronLastRun } from '../routes/health';
import { partitionManager } from '../services/PartitionManager';

export const startAutomationJobs = () => {
  logger.info('[CRON] Starting automation jobs...');

  // Run every day at midnight (0 0 * * *)
  // For testing purposes, we could run it more frequently, but daily is standard.
  cron.schedule('0 0 * * *', async () => {
    logger.info('[CRON] Running daily automation tasks...');
    try {
      await runDailyAutomations();
    } catch (error) {
      logger.error('[CRON] Error running daily automations:', error);
    }
    try {
      await checkUpcomingDeadlines();
    } catch (error) {
      logger.error('[CRON] Error running deadline checks:', error);
    }
  });

  // Daily backup at 2:00 AM via BackupScheduler (default schedule: '0 2 * * *')
  backupScheduler.start();

  // Monthly partition maintenance (1st of each month at midnight)
  // Creates future partitions (3 months ahead) and drops old ones based on retention policy
  partitionManager.scheduleMaintenanceJob();

  // Run immediately on startup to catch up
  runDailyAutomations().catch(err => {
    logger.error('[CRON] Error running initial automations:', err);
  });

  // Run deadline checks on startup (with once-per-day guard)
  checkUpcomingDeadlines().catch(err => {
    logger.error('[CRON] Error running initial deadline checks:', err);
  });
};

const runDailyAutomations = async () => {
  const now = new Date();
  const todayStr = now.toISOString().split('T')[0];
  
  logger.info(`[CRON] Executing automations for date: ${todayStr}`);

  // 1. Auto-Status Update for Audit Plans (Planned -> In Progress)
  try {
    const plansToUpdate = await db.prepare(`
      SELECT id, title, lead_auditor 
      FROM audit_plans 
      WHERE status = 'Planned' AND planned_start_date <= ?
    `).all(todayStr);

    if (plansToUpdate && plansToUpdate.length > 0) {
      logger.info(`[CRON] Found ${plansToUpdate.length} audit plans to start.`);
      
      const updateStmt = await db.prepare(`
        UPDATE audit_plans 
        SET status = 'In Progress' 
        WHERE status = 'Planned' AND planned_start_date <= ?
      `);
      await updateStmt.run(todayStr);

      // Notify lead auditors
      for (const plan of plansToUpdate) {
        if (plan.lead_auditor) {
          // Find user ID for lead auditor
          const user = await db.prepare(`SELECT id FROM users WHERE name = ? OR username = ?`).get(plan.lead_auditor, plan.lead_auditor);
          if (user) {
            await NotificationService.create(
              user.id,
              'plan_started',
              `The audit plan "${plan.title}" has automatically started today.`,
              'info',
              `/plan`
            );
          }
        }
      }
    }
  } catch (err) {
    logger.error('[CRON] Error updating audit plans:', err);
  }

  // 2. Auto-Status Update for Recommendations (Open/In Progress -> Overdue)
  // Optimized: single JOIN query, bulk UPDATE, grouped notifications per user
  try {
    // Single JOIN query to get overdue recommendations with resolved user info
    const overdueWithUsers = await db.prepare(`
      SELECT r.id, r.responsible, r.finding_id, u.id as user_id
      FROM recommendations r
      LEFT JOIN users u ON (u.name = r.responsible OR u.username = r.responsible)
      WHERE r.status IN ('Open', 'In Progress') AND r.due_date < ?
    `).all(todayStr) as Array<{ id: string; responsible: string; finding_id: string; user_id: string | null }>;

    if (overdueWithUsers && overdueWithUsers.length > 0) {
      logger.info(`[CRON] Found ${overdueWithUsers.length} overdue recommendations.`);

      // Single bulk UPDATE for all overdue recommendations
      await db.prepare(`
        UPDATE recommendations 
        SET status = 'Overdue' 
        WHERE status IN ('Open', 'In Progress') AND due_date < ?
      `).run(todayStr);

      // Group notifications by user (one notification per user with count)
      // Skip records where responsible doesn't resolve to a valid user
      const userNotifications = new Map<string, number>();
      for (const rec of overdueWithUsers) {
        if (rec.user_id) {
          userNotifications.set(
            rec.user_id,
            (userNotifications.get(rec.user_id) || 0) + 1
          );
        }
      }

      // Send one notification per user with their overdue count
      for (const [userId, count] of userNotifications) {
        await NotificationService.create(
          userId,
          'recommendation_overdue',
          JSON.stringify({ key: 'notifications.recommendationsOverdue', params: { count } }),
          'warning',
          '/recommendations'
        );
      }

      logger.info(`[CRON] Sent overdue notifications to ${userNotifications.size} users.`);
    }
  } catch (err) {
    logger.error('[CRON] Error updating overdue recommendations:', { error: err, date: todayStr });
    // Abort: do not send partial notifications — error is logged with context
  }

  // 3. Smart Escalation (Reminders for upcoming recommendations - 7 days before)
  try {
    const nextWeek = new Date(now);
    nextWeek.setDate(now.getDate() + 7);
    const nextWeekStr = nextWeek.toISOString().split('T')[0];

    const upcomingRecs = await db.prepare(`
      SELECT id, responsible 
      FROM recommendations 
      WHERE status IN ('Open', 'In Progress') AND due_date = ?
    `).all(nextWeekStr);

    if (upcomingRecs && upcomingRecs.length > 0) {
      logger.info(`[CRON] Found ${upcomingRecs.length} recommendations due in 7 days.`);
      
      for (const rec of upcomingRecs) {
        if (rec.responsible) {
          const user = await db.prepare(`SELECT id FROM users WHERE name = ? OR username = ?`).get(rec.responsible, rec.responsible);
          if (user) {
            await NotificationService.create(
              user.id,
              'recommendation_due_soon',
              `A recommendation assigned to you is due in 7 days.`,
              'info',
              `/recommendations`
            );
          }
        }
      }
    }
  } catch (err) {
    logger.error('[CRON] Error sending upcoming recommendation reminders:', err);
  }

  // 4. Compliance Automation: Flag overdue central bank instructions
  try {
    const overdueInstructions = await db.prepare(`
      SELECT id, title, related_department 
      FROM central_bank_instructions 
      WHERE status IN ('Draft', 'Under Review') AND issue_date < ?
    `).all(todayStr);

    if (overdueInstructions && overdueInstructions.length > 0) {
      logger.info(`[CRON] Found ${overdueInstructions.length} overdue central bank instructions.`);
      
      const updateStmt = await db.prepare(`
        UPDATE central_bank_instructions 
        SET status = 'Overdue' 
        WHERE status IN ('Draft', 'Under Review') AND issue_date < ?
      `);
      await updateStmt.run(todayStr);

      // Notify department heads or compliance officers
      // For now, notify all admins
      const admins = await db.prepare(`SELECT id FROM users WHERE role IN ('${UserRole.ADMIN}')`).all();
      for (const admin of admins) {
        await NotificationService.create(
          admin.id,
          'instruction_overdue',
          `Central Bank Instruction(s) have become overdue. Please review.`,
          'warning',
          `/regulatory`
        );
      }
    }
  } catch (err) {
    logger.error('[CRON] Error updating central bank instructions:', err);
  }

  // 5. Policy Automation: Periodic review reminders (e.g., 1 year since upload)
  try {
    const lastYear = new Date(now);
    lastYear.setFullYear(now.getFullYear() - 1);
    const lastYearStr = lastYear.toISOString().split('T')[0];

    const policiesToReview = await db.prepare(`
      SELECT id, title, department 
      FROM internal_policies 
      WHERE status = 'active' AND upload_date <= ?
    `).all(lastYearStr);

    if (policiesToReview && policiesToReview.length > 0) {
      logger.info(`[CRON] Found ${policiesToReview.length} policies requiring annual review.`);
      
      const updateStmt = await db.prepare(`
        UPDATE internal_policies 
        SET status = 'needs_review' 
        WHERE status = 'active' AND upload_date <= ?
      `);
      await updateStmt.run(lastYearStr);

      const admins = await db.prepare(`SELECT id FROM users WHERE role IN ('${UserRole.ADMIN}')`).all();
      for (const admin of admins) {
        await NotificationService.create(
          admin.id,
          'policy_review_required',
          `${policiesToReview.length} internal policies have reached their 1-year review mark.`,
          'info',
          `/legal`
        );
      }
    }
  } catch (err) {
    logger.error('[CRON] Error updating internal policies:', err);
  }

  // 6. Audit Tasks — Deadline approaching (3 days before due_date)
  try {
    const threeDaysLater = new Date(now);
    threeDaysLater.setDate(now.getDate() + 3);
    const threeDaysStr = threeDaysLater.toISOString().split('T')[0];

    const upcomingTasks = await db.prepare(`
      SELECT id, title, assigned_to, due_date
      FROM audit_tasks 
      WHERE status NOT IN ('completed', 'cancelled') 
        AND due_date = ? 
        AND deleted_at IS NULL
        AND assigned_to IS NOT NULL
    `).all(threeDaysStr);

    if (upcomingTasks && upcomingTasks.length > 0) {
      logger.info(`[CRON] Found ${upcomingTasks.length} tasks due in 3 days.`);
      
      for (const task of upcomingTasks) {
        await NotificationService.create(
          task.assigned_to,
          'task_status_changed',
          JSON.stringify({ key: 'notifications.taskDeadlineNear', params: { title: task.title, date: task.due_date } }),
          'AuditTasks',
          `/tasks`,
          { entityId: task.id, entityType: 'audit_task', title: JSON.stringify({ key: 'notifications.taskDeadlineNear' }) }
        );
      }
    }
  } catch (err) {
    logger.error('[CRON] Error sending task deadline reminders:', err);
  }

  logger.info('[CRON] Daily automations completed.');
  updateCronLastRun();
};

// ─── Deadline Notification Helpers (exported for testing) ────────────────────

/** Track last run date to ensure once-per-day execution */
let lastDeadlineCheckDate: string | null = null;

/**
 * Get Manager/Admin user IDs.
 */
export async function getManagerAdminIds(): Promise<string[]> {
  const users = await db.prepare(
    `SELECT id FROM users WHERE role IN ('${UserRole.ADMIN}', '${UserRole.MANAGER}') AND status = 'active'`
  ).all() as any[];
  return users.map((u: any) => u.id);
}

/**
 * Determine which tasks are due tomorrow (today + 1 day) and not completed/approved.
 * Returns the assigned user IDs for each task via task_assignments.
 */
export async function getTasksDueTomorrow(todayStr: string): Promise<Array<{ taskId: string; title: string; dueDate: string; assignedUserIds: string[] }>> {
  const tomorrow = new Date(todayStr);
  tomorrow.setDate(tomorrow.getDate() + 1);
  const tomorrowStr = tomorrow.toISOString().split('T')[0];

  const tasks = await db.prepare(`
    SELECT t.id, t.title, t.due_date
    FROM audit_tasks t
    WHERE t.due_date = ?
      AND t.status NOT IN ('completed', 'approved')
      AND (t.deleted_at IS NULL)
  `).all(tomorrowStr) as any[];

  const results: Array<{ taskId: string; title: string; dueDate: string; assignedUserIds: string[] }> = [];

  for (const task of tasks) {
    const assignments = await db.prepare(
      `SELECT user_id FROM task_assignments WHERE task_id = ?`
    ).all(task.id) as any[];

    const assignedUserIds = assignments.map((a: any) => a.user_id);
    if (assignedUserIds.length > 0) {
      results.push({
        taskId: task.id,
        title: task.title,
        dueDate: task.due_date,
        assignedUserIds,
      });
    }
  }

  return results;
}

/**
 * Determine which plans have start/end dates 3 days from today and are not archived.
 * Returns plan info with lead_auditor (may be null).
 */
export async function getPlansDueIn3Days(todayStr: string): Promise<Array<{ planId: string; title: string; dateType: 'start' | 'end'; date: string; leadAuditor: string | null }>> {
  const threeDaysLater = new Date(todayStr);
  threeDaysLater.setDate(threeDaysLater.getDate() + 3);
  const threeDaysStr = threeDaysLater.toISOString().split('T')[0];

  const plans = await db.prepare(`
    SELECT id, title, planned_start_date, planned_end_date, lead_auditor
    FROM audit_plans
    WHERE is_archived = false
      AND (planned_start_date = ? OR planned_end_date = ?)
  `).all(threeDaysStr, threeDaysStr) as any[];

  const results: Array<{ planId: string; title: string; dateType: 'start' | 'end'; date: string; leadAuditor: string | null }> = [];

  for (const plan of plans) {
    if (plan.planned_start_date === threeDaysStr) {
      results.push({
        planId: plan.id,
        title: plan.title,
        dateType: 'start',
        date: plan.planned_start_date,
        leadAuditor: plan.lead_auditor || null,
      });
    }
    if (plan.planned_end_date === threeDaysStr) {
      results.push({
        planId: plan.id,
        title: plan.title,
        dateType: 'end',
        date: plan.planned_end_date,
        leadAuditor: plan.lead_auditor || null,
      });
    }
  }

  return results;
}

/**
 * Check if unarchived plans exist for the current year (used for Dec 15 reminder).
 */
export async function getUnarchivedPlansForYear(year: number): Promise<Array<{ id: string; title: string }>> {
  const plans = await db.prepare(
    `SELECT id, title FROM audit_plans WHERE year = ? AND is_archived = false`
  ).all(year) as any[];
  return plans;
}

/**
 * Resolve lead auditor name to user ID. Returns null if not found.
 */
export async function resolveLeadAuditorId(leadAuditor: string | null): Promise<string | null> {
  if (!leadAuditor) return null;
  const user = await db.prepare(
    `SELECT id FROM users WHERE (name = ? OR username = ?) AND status = 'active'`
  ).get(leadAuditor, leadAuditor) as any;
  return user?.id || null;
}

/**
 * Main deadline checking function. Runs once per calendar day.
 * 
 * 1. Task due date notifications: 1 day before → notify all assigned users (via task_assignments)
 * 2. Plan date notifications: 3 days before start/end → notify Manager/Admin + lead auditor
 * 3. Year-end reminder: December 15 → notify Manager/Admin if unarchived plan exists
 */
export async function checkUpcomingDeadlines(dateOverride?: string): Promise<void> {
  const now = new Date();
  const todayStr = dateOverride || now.toISOString().split('T')[0];

  // Once-per-day guard: skip if already ran today
  if (lastDeadlineCheckDate === todayStr) {
    logger.info(`[CRON:Deadlines] Already ran for ${todayStr}, skipping.`);
    return;
  }

  logger.info(`[CRON:Deadlines] Running deadline checks for ${todayStr}...`);

  // 1. Task due date notifications (due_date = today + 1 day, status not completed/approved)
  try {
    const tasksDue = await getTasksDueTomorrow(todayStr);
    if (tasksDue.length > 0) {
      logger.info(`[CRON:Deadlines] Found ${tasksDue.length} tasks due tomorrow.`);
      for (const task of tasksDue) {
        await NotificationService.create(
          task.assignedUserIds,
          'task_status_changed',
          JSON.stringify({ key: 'notifications.taskDueTomorrow', params: { title: task.title, dueDate: task.dueDate } }),
          'AuditTasks',
          '/tasks',
          { entityId: task.taskId, entityType: 'audit_task' }
        );
      }
    }
  } catch (err) {
    logger.error('[CRON:Deadlines] Error checking task deadlines:', err);
  }

  // 2. Plan date notifications (start/end date = today + 3 days, not archived)
  try {
    const plansDue = await getPlansDueIn3Days(todayStr);
    if (plansDue.length > 0) {
      logger.info(`[CRON:Deadlines] Found ${plansDue.length} plan date(s) in 3 days.`);
      const managerAdminIds = await getManagerAdminIds();

      for (const plan of plansDue) {
        const recipientIds = [...managerAdminIds];
        let missingLeadAuditor = false;

        // Resolve lead auditor and add to recipients
        const leadAuditorId = await resolveLeadAuditorId(plan.leadAuditor);
        if (leadAuditorId) {
          if (!recipientIds.includes(leadAuditorId)) {
            recipientIds.push(leadAuditorId);
          }
        } else {
          missingLeadAuditor = true;
        }

        const messageKey = plan.dateType === 'start'
          ? 'notifications.planStartingSoon'
          : 'notifications.planEndingSoon';

        await NotificationService.create(
          recipientIds,
          'plan_status_changed',
          JSON.stringify({
            key: messageKey,
            params: {
              title: plan.title,
              date: plan.date,
              missingLeadAuditor,
            },
          }),
          'AuditPlans',
          '/plan',
          { entityId: plan.planId, entityType: 'audit_plan' }
        );
      }
    }
  } catch (err) {
    logger.error('[CRON:Deadlines] Error checking plan deadlines:', err);
  }

  // 3. Year-end reminder: December 15 → notify Manager/Admin if unarchived plan exists
  try {
    const month = now.getMonth(); // 0-indexed: 11 = December
    const day = now.getDate();
    const currentYear = now.getFullYear();

    // Use dateOverride for testing if provided
    const checkMonth = dateOverride ? new Date(dateOverride).getMonth() : month;
    const checkDay = dateOverride ? new Date(dateOverride).getDate() : day;
    const checkYear = dateOverride ? new Date(dateOverride).getFullYear() : currentYear;

    if (checkMonth === 11 && checkDay === 15) { // December 15
      const unarchivedPlans = await getUnarchivedPlansForYear(checkYear);
      if (unarchivedPlans.length > 0) {
        logger.info(`[CRON:Deadlines] Dec 15 reminder: ${unarchivedPlans.length} unarchived plan(s) for ${checkYear}.`);
        const managerAdminIds = await getManagerAdminIds();

        await NotificationService.create(
          managerAdminIds,
          'plan_status_changed',
          JSON.stringify({
            key: 'notifications.yearEndArchiveReminder',
            params: {
              year: checkYear,
              planCount: unarchivedPlans.length,
              planTitles: unarchivedPlans.map(p => p.title).join(', '),
            },
          }),
          'AuditPlans',
          '/plan'
        );
      }
    }
  } catch (err) {
    logger.error('[CRON:Deadlines] Error checking year-end reminder:', err);
  }

  // Mark as completed for today
  lastDeadlineCheckDate = todayStr;
  logger.info(`[CRON:Deadlines] Deadline checks completed for ${todayStr}.`);
}

/** Reset the last deadline check date (for testing purposes) */
export function resetDeadlineCheckDate(): void {
  lastDeadlineCheckDate = null;
}

/** Get the last deadline check date (for testing purposes) */
export function getLastDeadlineCheckDate(): string | null {
  return lastDeadlineCheckDate;
}

// @vitest-environment node
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import fc from 'fast-check';
import { MigrationRunner, Migration } from '../migrationRunner';

/**
 * Creates a PGlite-based DB wrapper that adapts to the DBWrapper interface
 * expected by MigrationRunner.
 */
function createPgliteDBWrapper(pglite: any) {
  return {
    prepare(sql: string) {
      // Convert ? placeholders to $1, $2, etc. (PostgreSQL style)
      let counter = 1;
      const pgSql = sql.replace(/\?/g, () => `$${counter++}`);

      return {
        async get(...params: any[]): Promise<any> {
          const res = await pglite.query(pgSql, params);
          return res.rows ? res.rows[0] : undefined;
        },
        async all(...params: any[]): Promise<any[]> {
          const res = await pglite.query(pgSql, params);
          return res.rows || [];
        },
        async run(...params: any[]): Promise<{ lastInsertRowid: number; changes: number }> {
          let finalSql = pgSql;
          if (finalSql.trim().toUpperCase().startsWith('INSERT')) {
            if (!finalSql.toUpperCase().includes('RETURNING')) {
              finalSql += ' RETURNING *';
            }
            const res = await pglite.query(finalSql, params);
            return {
              lastInsertRowid: (res.rows && res.rows[0] as any)?.id || 0,
              changes: res.rowCount || 0,
            };
          } else {
            const res = await pglite.query(finalSql, params);
            return { lastInsertRowid: 0, changes: res.rowCount || 0 };
          }
        },
      };
    },
    async exec(sql: string): Promise<void> {
      await pglite.query(sql);
    },
    transaction(fn: Function) {
      return async (...args: any[]) => {
        await pglite.query('BEGIN');
        try {
          const result = await fn(...args);
          await pglite.query('COMMIT');
          return result;
        } catch (e) {
          await pglite.query('ROLLBACK');
          throw e;
        }
      };
    },
  };
}

/**
 * Property Test: Migration versioning idempotence (Property 6)
 *
 * **Validates: Requirements 5.2, 5.3**
 *
 * For any set of migrations that have been previously applied, running the
 * migration system again must execute zero migrations and leave the
 * schema_migrations table unchanged.
 */
describe('Property 6: Migration versioning idempotence', () => {
  let pglite: any;
  let dbWrapper: ReturnType<typeof createPgliteDBWrapper>;

  beforeEach(async () => {
    const { PGlite } = await import('@electric-sql/pglite');
    pglite = new PGlite();
    await pglite.waitReady;
    dbWrapper = createPgliteDBWrapper(pglite);
  });

  afterEach(async () => {
    if (pglite) {
      await pglite.close();
    }
  });

  it('re-running previously applied migrations executes zero migrations and leaves schema_migrations unchanged', async () => {
    // Arbitrary for generating a set of unique migrations
    const migrationsArb = fc
      .uniqueArray(
        fc.record({
          version: fc.stringMatching(/^[0-9]{3}$/),
          name: fc.stringMatching(/^[a-z_]{3,20}$/),
          type: fc.constantFrom('schema' as const, 'seed' as const),
        }),
        { minLength: 1, maxLength: 10, selector: (m) => m.version }
      )
      .filter((arr) => arr.length >= 1);

    await fc.assert(
      fc.asyncProperty(migrationsArb, async (migrationDefs) => {
        // Reset the database for each iteration
        await pglite.query('DROP TABLE IF EXISTS schema_migrations');

        // Track execution counts
        const executionCounts: Record<string, number> = {};

        // Build Migration objects with tracked up() functions
        const migrations: Migration[] = migrationDefs.map((def) => {
          executionCounts[def.version] = 0;
          return {
            version: def.version,
            name: def.name,
            type: def.type,
            up: async () => {
              executionCounts[def.version]++;
            },
          };
        });

        // First run: apply all migrations
        const runner = new MigrationRunner(dbWrapper as any);
        await runner.initialize();
        await runner.run(migrations);

        // Snapshot schema_migrations table after first run
        const recordsAfterFirstRun = await pglite.query(
          'SELECT version, name, type, applied_at FROM schema_migrations ORDER BY version ASC'
        );
        const snapshotAfterFirstRun = recordsAfterFirstRun.rows;

        // Verify all migrations were applied in the first run
        expect(snapshotAfterFirstRun.length).toBe(migrations.length);

        // Reset execution counts for the second run
        for (const key of Object.keys(executionCounts)) {
          executionCounts[key] = 0;
        }

        // Second run: run the same migrations again
        await runner.run(migrations);

        // Verify zero migrations were executed on the second run
        for (const [version, count] of Object.entries(executionCounts)) {
          expect(count).toBe(0);
        }

        // Verify schema_migrations table is unchanged
        const recordsAfterSecondRun = await pglite.query(
          'SELECT version, name, type, applied_at FROM schema_migrations ORDER BY version ASC'
        );
        const snapshotAfterSecondRun = recordsAfterSecondRun.rows;

        expect(snapshotAfterSecondRun.length).toBe(snapshotAfterFirstRun.length);
        expect(snapshotAfterSecondRun).toEqual(snapshotAfterFirstRun);
      }),
      { numRuns: 100 }
    );
  }, 120000); // 2 minute timeout for 100 iterations with PGlite
});


/**
 * Property Test: Successful migration recording (Property 7)
 *
 * **Validates: Requirements 5.4**
 *
 * For any migration that completes without error, the schema_migrations table
 * must contain a record with that migration's version and a valid timestamp.
 */
describe('Property 7: Successful migration recording', () => {
  let pglite: any;
  let dbWrapper: ReturnType<typeof createPgliteDBWrapper>;

  beforeEach(async () => {
    const { PGlite } = await import('@electric-sql/pglite');
    pglite = new PGlite();
    await pglite.waitReady;
    dbWrapper = createPgliteDBWrapper(pglite);
  });

  afterEach(async () => {
    if (pglite) {
      await pglite.close();
    }
  });

  it('every successfully completed migration has a record in schema_migrations with a valid timestamp', async () => {
    const migrationsArb = fc
      .uniqueArray(
        fc.record({
          version: fc.stringMatching(/^[0-9]{3}$/),
          name: fc.stringMatching(/^[a-z_]{3,20}$/),
          type: fc.constantFrom('schema' as const, 'seed' as const),
        }),
        { minLength: 1, maxLength: 10, selector: (m) => m.version }
      )
      .filter((arr) => arr.length >= 1);

    await fc.assert(
      fc.asyncProperty(migrationsArb, async (migrationDefs) => {
        // Reset the database for each iteration
        await pglite.query('DROP TABLE IF EXISTS schema_migrations');

        // Build Migration objects that all succeed (resolve without error)
        const migrations: Migration[] = migrationDefs.map((def) => ({
          version: def.version,
          name: def.name,
          type: def.type,
          up: async () => {
            // Successful migration - does nothing but resolves
          },
        }));

        // Run the migration system
        const runner = new MigrationRunner(dbWrapper as any);
        await runner.initialize();
        await runner.run(migrations);

        // Verify each migration has a corresponding record in schema_migrations
        const records = await pglite.query(
          'SELECT version, name, type, applied_at FROM schema_migrations ORDER BY version ASC'
        );
        const rows = records.rows as Array<{
          version: string;
          name: string;
          type: string;
          applied_at: string | Date | null;
        }>;

        // There should be exactly as many records as migrations
        expect(rows.length).toBe(migrations.length);

        // Build a map of recorded versions for easy lookup
        const recordMap = new Map(rows.map((r) => [r.version, r]));

        for (const migration of migrations) {
          // Each migration must have a corresponding record
          const record = recordMap.get(migration.version);
          expect(record).toBeDefined();

          // The record must have the correct name and type
          expect(record!.name).toBe(migration.name);
          expect(record!.type).toBe(migration.type);

          // applied_at must not be null and must be a valid date
          expect(record!.applied_at).not.toBeNull();
          const appliedAt = new Date(record!.applied_at as string | Date);
          expect(appliedAt.getTime()).not.toBeNaN();
          // Timestamp should be recent (within the last 60 seconds)
          const now = Date.now();
          const sixtySecondsAgo = now - 60_000;
          expect(appliedAt.getTime()).toBeGreaterThanOrEqual(sixtySecondsAgo);
          expect(appliedAt.getTime()).toBeLessThanOrEqual(now);
        }
      }),
      { numRuns: 100 }
    );
  }, 120000); // 2 minute timeout for 100 iterations with PGlite
});


/**
 * Property Test: Failed migration halts execution (Property 8)
 *
 * **Validates: Requirements 5.5**
 *
 * For any migration that throws an error during execution, the schema_migrations
 * table must not contain that version, and no subsequent migrations in the pending
 * list must be executed.
 */
describe('Property 8: Failed migration halts execution', () => {
  let pglite: any;
  let dbWrapper: ReturnType<typeof createPgliteDBWrapper>;

  beforeEach(async () => {
    const { PGlite } = await import('@electric-sql/pglite');
    pglite = new PGlite();
    await pglite.waitReady;
    dbWrapper = createPgliteDBWrapper(pglite);
  });

  afterEach(async () => {
    if (pglite) {
      await pglite.close();
    }
  });

  it('a failing migration is not recorded, no subsequent migrations execute, and prior migrations are recorded', async () => {
    // Generate a list of 2-10 unique migrations and pick a random index for the failing one
    const testCaseArb = fc
      .uniqueArray(
        fc.record({
          version: fc.stringMatching(/^[0-9]{3}$/),
          name: fc.stringMatching(/^[a-z_]{3,20}$/),
          type: fc.constantFrom('schema' as const, 'seed' as const),
        }),
        { minLength: 2, maxLength: 10, selector: (m) => m.version }
      )
      .filter((arr) => arr.length >= 2)
      .chain((migrationDefs) =>
        fc.record({
          migrations: fc.constant(migrationDefs),
          failIndex: fc.integer({ min: 0, max: migrationDefs.length - 1 }),
        })
      );

    await fc.assert(
      fc.asyncProperty(testCaseArb, async ({ migrations: migrationDefs, failIndex }) => {
        // Reset the database for each iteration
        await pglite.query('DROP TABLE IF EXISTS schema_migrations');

        // Sort migration defs by version to know the execution order
        const sortedDefs = [...migrationDefs].sort((a, b) =>
          a.version.localeCompare(b.version)
        );

        // Track which migrations were executed
        const executed: string[] = [];

        // Build Migration objects; the one at failIndex (in sorted order) throws
        const failingVersion = sortedDefs[failIndex].version;
        const migrations: Migration[] = sortedDefs.map((def) => ({
          version: def.version,
          name: def.name,
          type: def.type,
          up: async () => {
            if (def.version === failingVersion) {
              throw new Error(`Migration ${def.version} intentionally failed`);
            }
            executed.push(def.version);
          },
        }));

        // Run the migration system - it should throw
        const runner = new MigrationRunner(dbWrapper as any);
        await runner.initialize();

        await expect(runner.run(migrations)).rejects.toThrow();

        // Query schema_migrations to see what was recorded
        const records = await pglite.query(
          'SELECT version FROM schema_migrations ORDER BY version ASC'
        );
        const recordedVersions = new Set(
          (records.rows as Array<{ version: string }>).map((r) => r.version)
        );

        // 1. The failing migration's version must NOT be in schema_migrations
        expect(recordedVersions.has(failingVersion)).toBe(false);

        // 2. No migrations AFTER the failing one (in sorted order) should have executed
        const afterFailingVersions = sortedDefs
          .slice(failIndex + 1)
          .map((d) => d.version);
        for (const version of afterFailingVersions) {
          expect(executed).not.toContain(version);
          expect(recordedVersions.has(version)).toBe(false);
        }

        // 3. All migrations BEFORE the failing one (in sorted order) should be recorded
        const beforeFailingVersions = sortedDefs
          .slice(0, failIndex)
          .map((d) => d.version);
        for (const version of beforeFailingVersions) {
          expect(executed).toContain(version);
          expect(recordedVersions.has(version)).toBe(true);
        }
      }),
      { numRuns: 100 }
    );
  }, 120000); // 2 minute timeout for 100 iterations with PGlite
});


/**
 * Property Test: Migration sequential ordering (Property 9)
 *
 * **Validates: Requirements 5.6**
 *
 * For any set of pending migrations presented in arbitrary order, the migration
 * runner must execute them in strictly ascending version order.
 */
describe('Property 9: Migration sequential ordering', () => {
  let pglite: any;
  let dbWrapper: ReturnType<typeof createPgliteDBWrapper>;

  beforeEach(async () => {
    const { PGlite } = await import('@electric-sql/pglite');
    pglite = new PGlite();
    await pglite.waitReady;
    dbWrapper = createPgliteDBWrapper(pglite);
  });

  afterEach(async () => {
    if (pglite) {
      await pglite.close();
    }
  });

  it('migrations presented in random order are executed in strictly ascending version order', async () => {
    // Generate 2-10 migrations with unique version strings, then shuffle them
    const migrationsArb = fc
      .uniqueArray(
        fc.record({
          version: fc.stringMatching(/^[0-9]{3}$/),
          name: fc.stringMatching(/^[a-z_]{3,20}$/),
          type: fc.constantFrom('schema' as const, 'seed' as const),
        }),
        { minLength: 2, maxLength: 10, selector: (m) => m.version }
      )
      .filter((arr) => arr.length >= 2)
      .chain((migrationDefs) =>
        // Shuffle the array to present migrations in random order
        fc.shuffledSubarray(migrationDefs, {
          minLength: migrationDefs.length,
          maxLength: migrationDefs.length,
        })
      );

    await fc.assert(
      fc.asyncProperty(migrationsArb, async (shuffledDefs) => {
        // Reset the database for each iteration
        await pglite.query('DROP TABLE IF EXISTS schema_migrations');

        // Track the execution order
        const executionOrder: string[] = [];

        // Build Migration objects in the SHUFFLED order (not sorted)
        const migrations: Migration[] = shuffledDefs.map((def) => ({
          version: def.version,
          name: def.name,
          type: def.type,
          up: async () => {
            executionOrder.push(def.version);
          },
        }));

        // Run the migration system with migrations in random order
        const runner = new MigrationRunner(dbWrapper as any);
        await runner.initialize();
        await runner.run(migrations);

        // All migrations should have been executed
        expect(executionOrder.length).toBe(shuffledDefs.length);

        // Verify execution order is strictly ascending by version string
        for (let i = 1; i < executionOrder.length; i++) {
          expect(
            executionOrder[i - 1].localeCompare(executionOrder[i])
          ).toBeLessThan(0);
        }

        // Additionally verify the execution order matches the sorted version order
        const expectedOrder = [...shuffledDefs.map((d) => d.version)].sort(
          (a, b) => a.localeCompare(b)
        );
        expect(executionOrder).toEqual(expectedOrder);
      }),
      { numRuns: 100 }
    );
  }, 120000); // 2 minute timeout for 100 iterations with PGlite
});

