import logger from '../utils/logger';

/**
 * Represents a single migration definition.
 */
export interface Migration {
  version: string;          // e.g., '001', '002'
  name: string;             // Human-readable description
  type: 'schema' | 'seed'; // DDL or data
  up: () => Promise<void>;  // Forward migration
}

/**
 * Represents a recorded migration in the schema_migrations table.
 */
export interface MigrationRecord {
  version: string;
  name: string;
  type: string;
  applied_at: string;       // ISO timestamp
}

/**
 * DBWrapper interface matching the project's database wrapper from src/server/db/index.ts.
 * Uses the subset of methods needed by MigrationRunner.
 */
interface DBWrapper {
  prepare(sql: string): {
    get(...params: any[]): Promise<any>;
    all(...params: any[]): Promise<any[]>;
    run(...params: any[]): Promise<{ lastInsertRowid: number; changes: number }>;
  };
  exec(sql: string): Promise<void>;
  transaction(fn: Function): (...args: any[]) => Promise<any>;
}

/**
 * MigrationRunner manages database schema versioning.
 * It tracks applied migrations in a `schema_migrations` table and ensures
 * each migration runs exactly once, in sequential version order.
 */
export class MigrationRunner {
  constructor(private db: DBWrapper) {}

  /**
   * Creates the schema_migrations table if it does not already exist.
   */
  async initialize(): Promise<void> {
    logger.info('Initializing migration system');
    await this.db.exec(`
      CREATE TABLE IF NOT EXISTS schema_migrations (
        version TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        type TEXT NOT NULL DEFAULT 'schema',
        applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      )
    `);
    logger.info('schema_migrations table ready');
  }

  /**
   * Returns all previously applied migration records from the schema_migrations table.
   */
  async getApplied(): Promise<MigrationRecord[]> {
    const rows = await this.db.prepare(
      'SELECT version, name, type, applied_at FROM schema_migrations ORDER BY version ASC'
    ).all();
    return rows as MigrationRecord[];
  }

  /**
   * Filters available migrations to return only those not yet applied,
   * sorted in ascending version order.
   */
  async getPending(available: Migration[]): Promise<Migration[]> {
    const applied = await this.getApplied();
    const appliedVersions = new Set(applied.map(r => r.version));

    return available
      .filter(m => !appliedVersions.has(m.version))
      .sort((a, b) => a.version.localeCompare(b.version));
  }

  /**
   * Executes all pending migrations in sequential version order.
   * Each migration runs within a transaction. On success, the version is recorded
   * in schema_migrations within the same transaction. On failure, execution halts
   * and the failing migration's version is NOT recorded.
   */
  async run(available: Migration[]): Promise<void> {
    const pending = await this.getPending(available);

    if (pending.length === 0) {
      logger.info('No pending migrations to run');
      return;
    }

    logger.info(`Found ${pending.length} pending migration(s) to execute`);

    for (const migration of pending) {
      logger.info(`Running migration ${migration.version}: ${migration.name} (${migration.type})`);

      const executeMigration = this.db.transaction(async () => {
        // Execute the migration's up function
        await migration.up();

        // Record the migration in schema_migrations
        await this.db.prepare(
          'INSERT INTO schema_migrations (version, name, type) VALUES (?, ?, ?)'
        ).run(migration.version, migration.name, migration.type);
      });

      try {
        await executeMigration();
        logger.info(`Migration ${migration.version} applied successfully`);
      } catch (error: any) {
        logger.error(`Migration ${migration.version} failed: ${error.message}`, {
          version: migration.version,
          name: migration.name,
          error: error.message,
        });
        throw error;
      }
    }

    logger.info(`All ${pending.length} migration(s) applied successfully`);
  }
}

import fs from "fs";

/**
 * SSL configuration for PostgreSQL database connections.
 * 
 * - Production: enforces SSL with rejectUnauthorized: true
 * - Development: no SSL required (PGlite doesn't use network)
 * - Supports custom CA certificate via DB_SSL_CA_PATH
 */

export interface DBSSLConfig {
  ssl: {
    rejectUnauthorized: boolean;
    ca?: string;
  };
}

/**
 * Creates SSL configuration based on environment variables.
 * 
 * @param env - The process environment variables
 * @returns SSL config object for pg.Pool, or undefined if SSL is not needed
 */
export function createSSLConfig(env: NodeJS.ProcessEnv): DBSSLConfig | undefined {
  const nodeEnv = env.NODE_ENV || "development";
  const databaseUrl = env.DATABASE_URL;

  // No DATABASE_URL means PGlite (embedded) — no SSL needed
  if (!databaseUrl) {
    return undefined;
  }

  // Development mode: no SSL required (PGlite or local PostgreSQL)
  if (nodeEnv !== "production") {
    return undefined;
  }

  // Production mode: enforce SSL
  const sslConfig: DBSSLConfig = {
    ssl: {
      rejectUnauthorized: true,
    },
  };

  // Support custom CA certificate via DB_SSL_CA_PATH
  const caPath = env.DB_SSL_CA_PATH;
  if (caPath) {
    try {
      const caCert = fs.readFileSync(caPath, "utf-8");
      sslConfig.ssl.ca = caCert;
    } catch (err: any) {
      throw new Error(
        `[DB SSL] Failed to read CA certificate from DB_SSL_CA_PATH="${caPath}": ${err.message}`
      );
    }
  }

  return sslConfig;
}

/**
 * Validates that the SSL connection to the database works in production.
 * If DATABASE_URL is set in production and SSL connection fails, the server should refuse to start.
 * 
 * @param pool - The pg.Pool instance to test
 * @returns true if connection succeeds, throws if it fails
 */
export async function validateSSLConnection(pool: any): Promise<boolean> {
  try {
    await pool.query("SELECT 1");
    return true;
  } catch (err: any) {
    const message = err.message || String(err);
    throw new Error(
      `[DB SSL] Production SSL connection validation failed: ${message}. ` +
      `The server cannot start without a secure database connection in production.`
    );
  }
}

