/**
 * Helper to create a mock file record as returned from the database.
 */
function createFileRecord(overrides: Partial<{
  id: string;
  original_name: string;
  module: string | null;
  mime_type: string;
}> = {}) {
  return {
    id: 'file-001',
    original_name: 'report.pdf',
    module: 'AuditPlans',
    mime_type: 'application/pdf',
    ...overrides,
  };
}

/**
 * Helper to create a mock request for file access.
 */
function createMockReq(user: any, filePath: string = '/file-001.pdf') {
  return {
    user,
    params: { id: 'file-001' },
    path: filePath,
    ip: '127.0.0.1',
    socket: { remoteAddress: '127.0.0.1' },
    originalUrl: `/api/v1/files${filePath}`,
    query: {},
  };
}

/**
 * Helper to create a mock response.
 */
function createMockRes() {
  const res: any = {
    statusCode: 200,
    _json: null,
    _headers: {},
  };
  res.status = vi.fn((code: number) => {
    res.statusCode = code;
    return res;
  });
  res.json = vi.fn((data: any) => {
    res._json = data;
    return res;
  });
  res.setHeader = vi.fn((name: string, value: string) => {
    res._headers[name] = value;
    return res;
  });
  res.sendFile = vi.fn();
  res.send = vi.fn();
  return res;
}

