    it('should deny access when file record has empty module field', async () => {
      const user = { id: 'user-1', role: UserRole.INTERNAL_AUDITOR };
      const fileRecord = createFileRecord({ module: '' });

      mockDbGet.mockResolvedValue(fileRecord);

