import { Request, Response, NextFunction } from 'express';
import { v4 as uuidv4 } from 'uuid';
import { requestContext } from '../utils/logger';
import { CorrelationIdOptions } from '../types/middleware';

/**
 * UUID v4 format regex: xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx
 * Validates 36-character string with hex digits and hyphens in correct positions.
 */
const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/**
 * Validates whether a string matches UUID format (36 chars, pattern xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx).
 */
export function isValidUuid(value: string): boolean {
  return typeof value === 'string' && value.length === 36 && UUID_REGEX.test(value);
}

/**
 * Creates a correlation ID middleware with configurable options.
 *
 * The middleware:
 * 1. Checks for an existing correlation ID in the request header (case-insensitive)
 * 2. Validates the header value matches UUID format (36 chars, xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx)
 * 3. If valid, uses the provided value as the request ID
 * 4. If missing or invalid, generates a new UUID v4
 * 5. Attaches the ID to the request context (req.correlationId) for downstream use
 * 6. Sets the response header with the correlation ID
 * 7. Stores the correlation ID in AsyncLocalStorage for logger access
 */
export function createCorrelationIdMiddleware(options: CorrelationIdOptions = {}) {
  const {
    headerName = 'x-correlation-id',
    responseHeader = 'X-Request-Id',
  } = options;

  return (req: Request, res: Response, next: NextFunction) => {
    const headerValue = req.headers[headerName.toLowerCase()] as string | undefined;

    // Use provided header value only if it's a valid UUID format
    const correlationId = headerValue && isValidUuid(headerValue)
      ? headerValue
      : uuidv4();

    // Attach to request context for downstream middleware/handlers
    (req as any).correlationId = correlationId;

    // Set response header
    res.setHeader(responseHeader, correlationId);

    // Store in AsyncLocalStorage for logger access
    const userId = (req as any).user?.id;
    requestContext.run({ correlationId, userId }, () => {
      next();
    });
  };
}

/**
 * Default correlation ID middleware instance with standard options.
 * Generates UUID v4 when X-Correlation-Id header is missing or invalid.
 * Accepts and validates existing X-Correlation-Id header (UUID format).
 * Attaches request ID to req.correlationId for downstream use.
 */
export const correlationIdMiddleware = createCorrelationIdMiddleware();

import crypto from 'crypto';
import type { Request, Response, NextFunction, RequestHandler } from 'express';

export interface CsrfOptions {
  exemptPaths: string[];       // e.g., ['/api/auth/login', '/health']
  tokenHeader: string;         // 'x-csrf-token'
  cookieName: string;          // 'csrf-token'
  tokenByteLength: number;     // 32
}

/**
 * Generates a cryptographically random CSRF token.
 * Uses crypto.randomBytes with the specified byte length (default 32 bytes = 64 hex chars).
 */
export function generateCsrfToken(byteLength: number = 32): string {
  return crypto.randomBytes(byteLength).toString('hex');
}

/**
 * Attaches a CSRF token to the response via both a non-httpOnly cookie
 * and a response header, allowing the client to read and send it back.
 */
export function attachCsrfToken(res: Response, token: string): void {
  // Set as a non-httpOnly cookie so client-side JS can read it
  res.cookie('csrf-token', token, {
    httpOnly: false,
    sameSite: 'strict',
    path: '/',
  });

  // Also set as a response header for convenience
  res.setHeader('x-csrf-token', token);
}

/**
 * Express middleware that validates CSRF tokens on state-changing requests.
 * 
 * - Skips GET, HEAD, OPTIONS requests (read-only methods)
 * - Skips exempt paths (e.g., login, health)
 * - Reads token from the x-csrf-token request header
 * - Compares against the csrf-token cookie value using timing-safe comparison
 * - Returns 403 if the token is missing or invalid
 */
export function csrfMiddleware(options: CsrfOptions): RequestHandler {
  const { exemptPaths, tokenHeader, cookieName } = options;

  return (req: Request, res: Response, next: NextFunction): void => {
    // Skip non-state-changing methods
    const method = req.method.toUpperCase();
    if (method === 'GET' || method === 'HEAD' || method === 'OPTIONS') {
      next();
      return;
    }

    // Skip exempt paths
    // Use req.originalUrl for matching because when middleware is mounted
    // on a path prefix (e.g. app.use('/api', ...)), req.path is relative
    // to the mount point (e.g. '/auth/login' instead of '/api/auth/login').
    const requestPath = req.originalUrl.split('?')[0]; // strip query params
    if (exemptPaths.some(path => requestPath === path || requestPath.startsWith(path + '/'))) {
      next();
      return;
    }

    // Read token from request header
    const headerToken = req.headers[tokenHeader.toLowerCase()] as string | undefined;

    // Read expected token from cookie
    const cookieToken = req.cookies?.[cookieName] as string | undefined;

    // Both must be present
    if (!headerToken || !cookieToken) {
      res.status(403).json({ error: 'CSRF token missing' });
      return;
    }

    // Compare using timing-safe comparison to prevent timing attacks
    if (!timingSafeCompare(headerToken, cookieToken)) {
      res.status(403).json({ error: 'CSRF token invalid' });
      return;
    }

    next();
  };
}

/**
 * Performs a timing-safe string comparison using crypto.timingSafeEqual.
 * Returns false if strings have different lengths (without leaking length info
 * beyond the boolean result).
 */
function timingSafeCompare(a: string, b: string): boolean {
  if (a.length !== b.length) {
    return false;
  }

  const bufA = Buffer.from(a, 'utf-8');
  const bufB = Buffer.from(b, 'utf-8');

  return crypto.timingSafeEqual(bufA, bufB);
}

