import { setupRoutes, CURRENT_API_VERSION, SUPPORTED_VERSIONS } from '../index';

function createTestApp() {
  const app = express();
  app.use(express.json());
  setupRoutes(app, 'jwt-secret', 'jwt-private', 'jwt-public', vi.fn(), vi.fn());
  return app;
}

describe('API Versioning (Task 4.1)', () => {
  let app: express.Application;

  beforeEach(() => {
    app = createTestApp();
  });

  describe('Requirement 4.1: Version prefix /api/v1/', () => {
    it('should serve health check at /api/v1/health', async () => {
      const res = await request(app).get('/api/v1/health');
      expect(res.status).toBe(200);
      expect(['healthy', 'degraded']).toContain(res.body.status);
    });

    it('should serve routes under /api/v1/ prefix', async () => {
      const res = await request(app).get('/api/v1/auth');
      expect(res.status).toBe(200);
      expect(res.body.route).toBe('/auth');
    });
  });

  describe('Requirement 4.2: Fallback from /api/ to current version (v1)', () => {
    it('should route /api/health to v1 health check', async () => {
      const res = await request(app).get('/api/health');
      expect(res.status).toBe(200);
      expect(['healthy', 'degraded']).toContain(res.body.status);
    });

    it('should route /api/auth to /api/v1/auth', async () => {
      const res = await request(app).get('/api/auth');
      expect(res.status).toBe(200);
      expect(res.body.route).toBe('/auth');
    });

    it('should route /api/notifications to /api/v1/notifications', async () => {
      const res = await request(app).get('/api/notifications');
      expect(res.status).toBe(200);
      expect(res.body.route).toBe('/notifications');
    });
  });

  describe('Requirement 4.3: X-API-Version response header', () => {
    it('should set X-API-Version header to "1.0" on /api/v1/ responses', async () => {
      const res = await request(app).get('/api/v1/health');
      expect(res.headers['x-api-version']).toBe('1.0');
    });

    it('should set X-API-Version header on /api/ fallback responses', async () => {
      const res = await request(app).get('/api/health');
      expect(res.headers['x-api-version']).toBe('1.0');
    });

    it('should set X-API-Version header on 404 responses for unsupported versions', async () => {
      const res = await request(app).get('/api/v2/health');
      expect(res.headers['x-api-version']).toBe('1.0');
    });
  });

  describe('Requirement 4.4: 404 for unsupported version segments', () => {
    it('should return 404 for /api/v2/', async () => {
      const res = await request(app).get('/api/v2/health');
      expect(res.status).toBe(404);
      expect(res.body.success).toBe(false);
      expect(res.body.error.code).toBe('VERSION_NOT_FOUND');
      expect(res.body.error.message).toContain('v2');
      expect(res.body.error.message).toContain('v1');
    });

    it('should return 404 for /api/v99/', async () => {
      const res = await request(app).get('/api/v99/anything');
      expect(res.status).toBe(404);
      expect(res.body.success).toBe(false);
      expect(res.body.error.code).toBe('VERSION_NOT_FOUND');
    });

    it('should return 404 for /api/v0/ (version must be positive)', async () => {
      const res = await request(app).get('/api/v0/health');
      expect(res.status).toBe(404);
      expect(res.body.success).toBe(false);
      expect(res.body.error.code).toBe('VERSION_NOT_FOUND');
    });

    it('should return 404 for non-numeric version like /api/vabc/', async () => {
      const res = await request(app).get('/api/vabc/health');
      expect(res.status).toBe(404);
      expect(res.body.success).toBe(false);
      expect(res.body.error.code).toBe('VERSION_NOT_FOUND');
    });
  });

  describe('Exported constants', () => {
    it('should export CURRENT_API_VERSION with major and minor', () => {
      expect(CURRENT_API_VERSION).toEqual({ major: 1, minor: 0 });
    });

    it('should export SUPPORTED_VERSIONS containing version 1', () => {
      expect(SUPPORTED_VERSIONS).toContain(1);
    });
  });

  describe('Backward compatibility', () => {
    it('should return 404 for completely unknown API paths', async () => {
      const res = await request(app).get('/api/nonexistent-endpoint-xyz');
      expect(res.status).toBe(404);
    });

    it('should return 404 for unknown paths under /api/v1/', async () => {
      const res = await request(app).get('/api/v1/nonexistent-endpoint-xyz');
      expect(res.status).toBe(404);
    });
  });
});

// @vitest-environment node
import { describe, it, expect, vi, beforeEach } from 'vitest';
import express from 'express';
import request from 'supertest';

/**
 * Integration Tests - Audit Plans Routes
 *
 * Tests the audit plans CRUD routes using supertest against a minimal Express app.
 * The audit plans are managed via the generic CRUD generator, so we simulate that pattern.
 */

interface MockAuditPlan {
  id: string;
  title: string;
  department: string;
  type: string;
  risk_rating: string;
  planned_start_date: string;
  planned_end_date: string;
  lead_auditor: string;
  status: string;
  plan_code: string;
}

function createAuditPlansTestApp() {
  const app = express();
  app.use(express.json());

  const plans: MockAuditPlan[] = [
    {
      id: 'plan-1',
      title: 'Q1 Operational Audit',
      department: 'Finance',
      type: 'Operational',
      risk_rating: 'High',
      planned_start_date: '2025-01-15',
      planned_end_date: '2025-03-15',
      lead_auditor: 'John Smith',
      status: 'Planned',
      plan_code: 'IA-PL-25-001',
    },
    {
      id: 'plan-2',
      title: 'Compliance Review',
      department: 'Legal',
      type: 'Compliance',
      risk_rating: 'Medium',
      planned_start_date: '2025-02-01',
      planned_end_date: '2025-04-01',
      lead_auditor: 'Jane Doe',
      status: 'In Progress',
      plan_code: 'IA-PL-25-002',
    },
  ];

  // Simulate authenticate middleware
  const authenticate = (req: any, res: any, next: any) => {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({ error: 'Unauthorized' });
    }
    req.user = { id: 'user-1', role: 'Admin', username: 'admin', name: 'Admin User' };
    next();
  };

  // Simulate checkPermission middleware
  const checkPermission = (module: string, action: string) => (req: any, res: any, next: any) => {
    if (req.user.role !== 'Admin' && req.user.role !== 'Manager') {
      return res.status(403).json({ error: `Forbidden: Missing permission ${action} on ${module}` });
    }
    next();
  };

  const router = express.Router();

  // GET all audit plans
  router.get('/', authenticate, checkPermission('Audit Plans', 'View'), (req, res) => {
    const { status, department } = req.query;
    let filtered = [...plans];
    if (status) filtered = filtered.filter(p => p.status === status);
    if (department) filtered = filtered.filter(p => p.department === department);
    res.json({ data: filtered, total: filtered.length });
  });

  // GET single audit plan
  router.get('/:id', authenticate, checkPermission('Audit Plans', 'View'), (req, res) => {
    const plan = plans.find(p => p.id === req.params.id);
    if (!plan) return res.status(404).json({ error: 'Audit plan not found' });
    res.json(plan);
  });

  // POST create audit plan
  router.post('/', authenticate, checkPermission('Audit Plans', 'Create'), (req, res) => {
    const { title, department, type, risk_rating, planned_start_date, planned_end_date, lead_auditor, status } = req.body;
    if (!title || !department) {
      return res.status(400).json({ error: 'Title and department are required' });
    }
    const newPlan: MockAuditPlan = {
      id: `plan-${Date.now()}`,
      title,
      department,
      type: type || 'Operational',
      risk_rating: risk_rating || 'Medium',
      planned_start_date: planned_start_date || '',
      planned_end_date: planned_end_date || '',
      lead_auditor: lead_auditor || '',
      status: status || 'Planned',
      plan_code: `IA-PL-25-${String(plans.length + 1).padStart(3, '0')}`,
    };
    plans.push(newPlan);
    res.status(201).json(newPlan);
  });

  // PUT update audit plan
  router.put('/:id', authenticate, checkPermission('Audit Plans', 'Edit'), (req, res) => {
    const idx = plans.findIndex(p => p.id === req.params.id);
    if (idx === -1) return res.status(404).json({ error: 'Audit plan not found' });
    plans[idx] = { ...plans[idx], ...req.body };
    res.json(plans[idx]);
  });

  // DELETE audit plan
  router.delete('/:id', authenticate, checkPermission('Audit Plans', 'Delete'), (req, res) => {
    const idx = plans.findIndex(p => p.id === req.params.id);
    if (idx === -1) return res.status(404).json({ error: 'Audit plan not found' });
    plans.splice(idx, 1);
    res.json({ success: true });
  });

  app.use('/api/audit-plans', router);

  return { app };
}

describe('Audit Plans Integration Tests', () => {
  let app: express.Application;

  beforeEach(() => {
    vi.clearAllMocks();
    const testApp = createAuditPlansTestApp();
    app = testApp.app;
  });

  describe('GET /api/audit-plans', () => {
    it('should return 200 with list of audit plans when authenticated', async () => {
      const res = await request(app)
        .get('/api/audit-plans')
        .set('Authorization', 'Bearer valid-token');

      expect(res.status).toBe(200);
      expect(res.body.data).toBeDefined();
      expect(res.body.data.length).toBe(2);
      expect(res.body.total).toBe(2);
    });

    it('should return 401 when not authenticated', async () => {
      const res = await request(app).get('/api/audit-plans');

      expect(res.status).toBe(401);
      expect(res.body.error).toBe('Unauthorized');
    });

    it('should filter by status query parameter', async () => {
      const res = await request(app)
        .get('/api/audit-plans?status=Planned')
        .set('Authorization', 'Bearer valid-token');

      expect(res.status).toBe(200);
      expect(res.body.data.length).toBe(1);
      expect(res.body.data[0].status).toBe('Planned');
    });

    it('should filter by department query parameter', async () => {
      const res = await request(app)
        .get('/api/audit-plans?department=Finance')
        .set('Authorization', 'Bearer valid-token');

      expect(res.status).toBe(200);
      expect(res.body.data.length).toBe(1);
      expect(res.body.data[0].department).toBe('Finance');
    });
  });

  describe('GET /api/audit-plans/:id', () => {
    it('should return 200 with plan details for valid ID', async () => {
      const res = await request(app)
        .get('/api/audit-plans/plan-1')
        .set('Authorization', 'Bearer valid-token');

      expect(res.status).toBe(200);
      expect(res.body.id).toBe('plan-1');
      expect(res.body.title).toBe('Q1 Operational Audit');
      expect(res.body.plan_code).toBe('IA-PL-25-001');
