      app.use((req: any, res, next) => {
        req.user = { id: 'user-1', role: UserRole.VIEWER };
        next();
      });

      app.get('/api/test', middlewares.checkPermission(module, action as any), (req: any, res) => {
        res.json({ success: true });
      });

      return app;
    }

    it('Admin users bypass all permission checks', async () => {
      const app = createApp();
      app.use((req: any, res, next) => {
        req.user = { id: 'admin-1', role: UserRole.ADMIN };
        next();
      });
      app.get('/api/test', middlewares.checkPermission('Audit', 'Edit'), (req: any, res) => {
        res.json({ success: true });
      });

      const res = await request(app).get('/api/test');

      expect(res.status).toBe(200);
      expect(res.body.success).toBe(true);
    });

    it('returns 403 with module and action in error message when permission is denied', async () => {
      // Mock PermissionService to deny permission
      mockHasPermission.mockResolvedValue(false);

      middlewares = createAuthMiddlewares(db, JWT_SECRET, JWT_PUBLIC_KEY);
      middlewares.cache.clear();

      const app = createAppWithPermission('Finding', 'Delete');

      const res = await request(app).get('/api/test');

      expect(res.status).toBe(403);
      expect(res.body.error).toContain('Finding');
      expect(res.body.error).toContain('Delete');
      expect(res.body.code).toBe('PERMISSION_DENIED');
      expect(res.body.module).toBe('Finding');
      expect(res.body.action).toBe('Delete');
    });
  });

  describe('authorize middleware', () => {
    function createAppWithAuthorize(allowedRoles: readonly string[], userRole: string) {
      const app = createApp();
      app.use((req: any, res, next) => {
        req.user = { id: 'user-1', role: userRole };
        next();
      });
      app.get('/api/test', middlewares.authorize(allowedRoles), (req: any, res) => {
        res.json({ success: true });
      });
      return app;
    }

    it('allows access when user role is in allowed roles', async () => {
      const app = createAppWithAuthorize([UserRole.ADMIN, UserRole.MANAGER], UserRole.ADMIN);

      const res = await request(app).get('/api/test');

      expect(res.status).toBe(200);
      expect(res.body.success).toBe(true);
    });

    it('returns 403 when user role is not in allowed roles', async () => {
      const app = createAppWithAuthorize([UserRole.ADMIN, UserRole.MANAGER], UserRole.VIEWER);

      const res = await request(app).get('/api/test');

      expect(res.status).toBe(403);
      expect(res.body.error).toContain('Forbidden');
    });
  });

  describe('validateSchema middleware', () => {
    const testSchema = z.object({
      name: z.string().min(2, 'Name must be at least 2 characters'),
      email: z.string().email('Invalid email format'),
      age: z.number().int().positive().optional(),
    });

    function createAppWithValidation() {
      const app = createApp();
      app.post('/api/test', validateSchema(testSchema), (req: any, res) => {
        res.json({ data: req.body });
      });
      app.use(globalErrorHandler);
      return app;
    }

    it('passes when request body matches Zod schema', async () => {
      const app = createAppWithValidation();

      const res = await request(app)
        .post('/api/test')
        .send({ name: 'John', email: 'john@example.com' });

      expect(res.status).toBe(200);
      expect(res.body.data.name).toBe('John');
      expect(res.body.data.email).toBe('john@example.com');
    });

    it('returns 400 with validation error details when body does not match schema', async () => {
      const app = createAppWithValidation();

      const res = await request(app)
        .post('/api/test')
        .send({ name: 'J', email: 'not-an-email' });

      expect(res.status).toBe(400);
      expect(res.body.error).toBeDefined();
    });

    it('strips unknown fields from the request body', async () => {
      const app = createAppWithValidation();

      const res = await request(app)
        .post('/api/test')
        .send({ name: 'John', email: 'john@example.com', unknownField: 'should be stripped' });

      expect(res.status).toBe(200);
      expect(res.body.data.name).toBe('John');
      expect(res.body.data.email).toBe('john@example.com');
      expect(res.body.data.unknownField).toBeUndefined();
    });
  });

  describe('Rate limiter (authLimiter)', () => {
    it('returns 429 with TOO_MANY_ATTEMPTS after exceeding limit', async () => {
      // Create fresh middlewares to get a fresh rate limiter
      const freshMiddlewares = createAuthMiddlewares(db, JWT_SECRET, JWT_PUBLIC_KEY);

      const app = createApp();
      app.post('/api/auth/login', freshMiddlewares.authLimiter, (req: any, res) => {
        res.json({ success: true });
      });

      // Send requests up to the limit (10) - they should pass
      for (let i = 0; i < 10; i++) {
        const res = await request(app)
          .post('/api/auth/login')
          .send({ usernameOrEmail: 'testuser', password: 'pass' });
        expect(res.status).toBe(200);
      }

      // The 11th request should be rate limited
      const res = await request(app)
        .post('/api/auth/login')
        .send({ usernameOrEmail: 'testuser', password: 'pass' });

      expect(res.status).toBe(429);
      expect(res.body.error).toBe('TOO_MANY_ATTEMPTS');
    });
  });
});

// @vitest-environment node
import { describe, it, expect, vi, beforeEach } from 'vitest';
import express from 'express';
import request from 'supertest';
import path from 'path';
import fs from 'fs';

/**
 * Integration Tests - Miscellaneous Routes
 *
 * Tests the health check, OpenAPI docs, and 404 handler endpoints.
 * These routes do not require authentication.
 *
 * Validates: Requirements 21.5, 21.6
 */

function createMiscTestApp() {
  const app = express();
  app.use(express.json());

  // Health Check - mirrors the real route logic
  app.get('/api/health', (req, res) => {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      database: 'PGlite',
      persistence: 'in-memory',
    });
  });

  // OpenAPI Specification
  app.get('/api/docs', (req, res) => {
    try {
      const specPath = path.resolve(__dirname, '../../../../docs/openapi.yaml');
      const spec = fs.readFileSync(specPath, 'utf-8');
      res.setHeader('Content-Type', 'text/yaml; charset=utf-8');
      res.send(spec);
    } catch (err) {
      res.status(404).json({ error: 'OpenAPI specification not found' });
    }
  });

  // Global API 404 Handler
  app.use('/api', (req, res) => {
    res.status(404).json({ error: `API endpoint ${req.originalUrl} not found` });
  });

  return app;
}

describe('Miscellaneous Routes Integration Tests', () => {
  let app: express.Application;

  beforeEach(() => {
    app = createMiscTestApp();
  });

  // ─── GET /api/health ─────────────────────────────────────────────────────

  describe('GET /api/health', () => {
    it('should return 200 with status, timestamp, database, and persistence', async () => {
      const res = await request(app).get('/api/health');

      expect(res.status).toBe(200);
      expect(res.body.status).toBe('ok');
      expect(res.body.timestamp).toBeDefined();
      expect(new Date(res.body.timestamp).toISOString()).toBe(res.body.timestamp);
      expect(res.body.database).toBeDefined();
      expect(res.body.persistence).toBeDefined();
    });

    it('should not require authentication', async () => {
      // No Authorization header sent
      const res = await request(app).get('/api/health');
      expect(res.status).toBe(200);
    });
  });

  // ─── GET /api/docs ───────────────────────────────────────────────────────

  describe('GET /api/docs', () => {
    it('should return 200 with YAML content type when spec exists', async () => {
      const res = await request(app).get('/api/docs');

      // The spec file exists in the project
      expect(res.status).toBe(200);
      expect(res.headers['content-type']).toContain('text/yaml');
    });

    it('should return 404 if spec file does not exist', async () => {
      // Create an app with a non-existent spec path
      const appWithMissingSpec = express();
      appWithMissingSpec.get('/api/docs', (req, res) => {
        try {
          const specPath = path.resolve(__dirname, '../../../../docs/nonexistent.yaml');
          const spec = fs.readFileSync(specPath, 'utf-8');
          res.setHeader('Content-Type', 'text/yaml; charset=utf-8');
          res.send(spec);
        } catch (err) {
          res.status(404).json({ error: 'OpenAPI specification not found' });
        }
      });

      const res = await request(appWithMissingSpec).get('/api/docs');
      expect(res.status).toBe(404);
      expect(res.body.error).toBe('OpenAPI specification not found');
    });
  });

  // ─── 404 Handler ─────────────────────────────────────────────────────────

  describe('404 Handler for non-existent API endpoints', () => {
    it('should return 404 with error message for non-existent /api/* endpoints', async () => {
      const res = await request(app).get('/api/nonexistent-endpoint');

      expect(res.status).toBe(404);
      expect(res.body.error).toBeDefined();
    });

    it('should include the requested URL in the error message', async () => {
      const res = await request(app).get('/api/some/random/path');

      expect(res.status).toBe(404);
      expect(res.body.error).toContain('/api/some/random/path');
    });
  });
});

// @vitest-environment node
import { describe, it, expect, vi, beforeEach } from 'vitest';
import fc from 'fast-check';
import express from 'express';
import request from 'supertest';

/**
 * Property Tests for Permission Admin API
 *
 * Property 14: Custom Role Lifecycle Safety
 * Property 15: Role Name Validation
 * Property 16: Permission Matrix Update with Cache Invalidation
 * Property 18: Override Validation
 *
 * **Validates: Requirements 7.2, 7.3, 7.5, 7.6, 7.7, 7.8, 8.2, 9.2, 9.3**
 */

// ─── Mocks ───────────────────────────────────────────────────────────────────

// Mock the database module (for audit logging that uses module-level db import)
vi.mock('../../db/index', () => {
  const mockPrepare = vi.fn().mockReturnValue({
    get: vi.fn().mockResolvedValue(undefined),
    all: vi.fn().mockResolvedValue([]),
    run: vi.fn().mockResolvedValue(undefined),
  });
  return {
    db: { prepare: mockPrepare, transaction: vi.fn((fn: any) => fn) },
    default: { prepare: mockPrepare, transaction: vi.fn((fn: any) => fn) },
  };
});

// Mock PermissionService
const updateRolePermissionsMock = vi.fn();
const invalidateCacheMock = vi.fn();
vi.mock('../../services/PermissionService', () => ({
  PermissionService: {
    updateRolePermissions: (...args: any[]) => updateRolePermissionsMock(...args),
    invalidateCache: (...args: any[]) => invalidateCacheMock(...args),
    getRolePermissions: vi.fn().mockResolvedValue({ permissions: {} }),
    getUserPermissions: vi.fn().mockResolvedValue({
      userId: '', role: '', roleId: '', isCustomRole: false,
      permissions: {}, overrides: [],
    }),
  },
}));

// Mock ModuleRegistry
const getModuleMock = vi.fn();
const getAllModulesMock = vi.fn().mockReturnValue([]);
vi.mock('../../../permissions/registry', () => ({
  ModuleRegistry: {
    getModule: (...args: any[]) => getModuleMock(...args),
    getAllModules: (...args: any[]) => getAllModulesMock(...args),
    getModuleNames: vi.fn().mockReturnValue([]),
  },
}));

import { createPermissionAdminRoutes } from '../permissionAdmin';
import { PermissionAction } from '../../../permissions/types';

// ─── Custom Arbitraries ──────────────────────────────────────────────────────

/** Generates a valid role name (2-100 printable ASCII chars) */
const validRoleNameArb = fc
  .string({ minLength: 2, maxLength: 100 })
  .filter(s => s.trim().length >= 2 && /^[\x20-\x7E]+$/.test(s));

/** Generates a valid UUID */
const uuidArb = fc.uuid();

/** Generates a valid module name from a realistic set */
const moduleNameArb = fc.constantFrom(
  'Dashboard', 'AuditCharter', 'AuditPlans', 'AuditFindings',
  'Policies', 'RiskRegister', 'Analytics', 'Compliance',
  'Correspondence', 'Fraud', 'Integrity', 'Recommendations',
  'Regulatory', 'UserManagement', 'Settings'
);

/** Generates a valid permission action */
const validActionArb = fc.constantFrom(
  'View', 'Create', 'Edit', 'Delete', 'Approve'
) as fc.Arbitrary<PermissionAction>;

/** Generates an invalid action not in the supported set */
const invalidActionArb = fc.constantFrom(
  'Read', 'Write', 'Execute', 'Manage', 'Admin', 'Update', 'Remove'
);

/** Generates a number of assigned users (0 or more) */
const assignedUsersCountArb = fc.nat({ max: 10 });

// ─── Helper Functions ────────────────────────────────────────────────────────

/**
 * Creates a test Express app with the permission admin router mounted.
 * Uses a mock db object that can be configured per test.
 */
function createTestApp(mockDb: any) {
  const app = express();
  app.use(express.json());

  const mockAuthenticate = (req: any, _res: any, next: any) => {
    req.user = { id: 'admin-user-id', role: 'Admin' };
    next();
  };
  const mockCheckPermission = () => (_req: any, _res: any, next: any) => next();
  const mockLogError = vi.fn();

  const router = createPermissionAdminRoutes(
    mockDb,
    mockAuthenticate,
    mockCheckPermission,
    mockLogError
  );

  app.use(router);
  return app;
}

/**
 * Creates a mock DB object with configurable prepare responses.
 */
function createMockDb(handlers: Record<string, any> = {}) {
  const prepareFn = vi.fn().mockImplementation((sql: string) => {
    for (const [pattern, handler] of Object.entries(handlers)) {
      if (sql.includes(pattern)) {
        return handler;
      }
    }
    return {
      get: vi.fn().mockResolvedValue(undefined),
      all: vi.fn().mockResolvedValue([]),
      run: vi.fn().mockResolvedValue(undefined),
    };
  });

  const transactionFn = vi.fn().mockImplementation((fn: any) => fn);

  return { prepare: prepareFn, transaction: transactionFn };
}

// ─── Tests ───────────────────────────────────────────────────────────────────

describe('Property 14: Custom Role Lifecycle Safety', () => {
  /**
   * Deletion succeeds only with zero assigned users;
   * built-in roles cannot be deleted or modified.
   *
   * **Validates: Requirements 7.5, 7.6, 7.7, 7.8**
   */

  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('deletion of a custom role succeeds only when zero users are assigned', async () => {
    await fc.assert(
      fc.asyncProperty(
        uuidArb,
        assignedUsersCountArb,
        async (roleId, assignedCount) => {
          const users = Array.from({ length: assignedCount }, (_, i) => ({
            id: `user-${i}`,
          }));

          const mockDb = createMockDb({
            'SELECT id, name': {
              get: vi.fn().mockResolvedValue({
                id: roleId, name: 'TestCustomRole', is_custom: true,
              }),
            },
            'SELECT id FROM users WHERE role_id': {
              all: vi.fn().mockResolvedValue(users),
            },
            'SELECT COUNT': {
              get: vi.fn().mockResolvedValue({ total: assignedCount }),
            },
            'DELETE FROM role_permissions': {
              run: vi.fn().mockResolvedValue(undefined),
            },
            'DELETE FROM roles': {
              run: vi.fn().mockResolvedValue(undefined),
            },
            'permission_audit_logs': {
              get: vi.fn().mockResolvedValue({ id: 'log-id' }),
              run: vi.fn().mockResolvedValue(undefined),
            },
          });

          const app = createTestApp(mockDb);
          const res = await request(app).delete(`/roles/${roleId}`);

          if (assignedCount === 0) {
            expect(res.status).toBe(200);
          } else {
            expect(res.status).toBe(409);
            expect(res.body.code).toBe('CONFLICT');
            expect(res.body.affectedUserIds).toBeDefined();
          }
        }
      ),
      { numRuns: 50 }
    );
  }, 60000);

  it('built-in roles cannot be deleted', async () => {
    await fc.assert(
      fc.asyncProperty(
        uuidArb,
        fc.constantFrom(
          'Admin', 'Manager', 'Internal Auditor',
          'Compliance Officer', 'Risk Officer', 'Viewer'
        ),
        async (roleId, roleName) => {
          const mockDb = createMockDb({
            'SELECT id, name': {
              get: vi.fn().mockResolvedValue({
                id: roleId, name: roleName, is_custom: false,
              }),
            },
          });

          const app = createTestApp(mockDb);
          const res = await request(app).delete(`/roles/${roleId}`);

          expect(res.status).toBe(403);
          expect(res.body.code).toBe('FORBIDDEN');
        }
      ),
      { numRuns: 30 }
    );
  }, 60000);

  it('built-in roles cannot be modified (PUT returns 403)', async () => {
    await fc.assert(
      fc.asyncProperty(
        uuidArb,
        fc.constantFrom(
          'Admin', 'Manager', 'Internal Auditor',
          'Compliance Officer', 'Risk Officer', 'Viewer'
        ),
        validRoleNameArb,
        async (roleId, roleName, newName) => {
          const mockDb = createMockDb({
            'SELECT id, name, description, is_custom, created_at FROM roles': {
              get: vi.fn().mockResolvedValue({
                id: roleId, name: roleName, description: '',
                is_custom: false, created_at: new Date().toISOString(),
              }),
            },
          });

          const app = createTestApp(mockDb);
          const res = await request(app)
            .put(`/roles/${roleId}`)
            .send({ name: newName });

          expect(res.status).toBe(403);
          expect(res.body.code).toBe('FORBIDDEN');
        }
      ),
      { numRuns: 30 }
    );
  }, 60000);
});


describe('Property 15: Role Name Validation', () => {
  /**
   * Name accepted iff 2-100 chars and no case-insensitive conflict.
   *
   * **Validates: Requirements 7.2, 7.3**
   */

  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('role creation succeeds when name is 2-100 chars and no conflict', async () => {
    await fc.assert(
      fc.asyncProperty(validRoleNameArb, async (name) => {
        const mockDb = createMockDb({
          'LOWER(name) = LOWER': {
            get: vi.fn().mockResolvedValue(undefined), // No conflict
          },
          'INSERT INTO roles': {
            get: vi.fn().mockResolvedValue({
              id: 'new-role-id', name, description: '',
              is_custom: true, created_at: new Date().toISOString(),
            }),
          },
          'permission_audit_logs': {
            get: vi.fn().mockResolvedValue({ id: 'log-id' }),
            run: vi.fn().mockResolvedValue(undefined),
          },
        });

        const app = createTestApp(mockDb);
        const res = await request(app)
          .post('/roles')
          .send({ name, description: '' });

        expect(res.status).toBe(201);
        expect(res.body.name).toBe(name);
        expect(res.body.isCustom).toBe(true);
      }),
      { numRuns: 50 }
    );
  }, 60000);

  it('role creation fails with 400 when name is too short or too long', async () => {
    const invalidNames = ['', 'a', ' ', 'A'.repeat(101)];

    for (const name of invalidNames) {
      const mockDb = createMockDb({});
      const app = createTestApp(mockDb);
      const res = await request(app)
        .post('/roles')
        .send({ name, description: '' });

      expect(res.status).toBe(400);
      expect(res.body.code).toBe('VALIDATION_ERROR');
    }
  }, 30000);

  it('role creation fails with 409 when name conflicts case-insensitively', async () => {
    await fc.assert(
      fc.asyncProperty(validRoleNameArb, uuidArb, async (name, existingId) => {
        const mockDb = createMockDb({
          'LOWER(name) = LOWER': {
            get: vi.fn().mockResolvedValue({ id: existingId }), // Conflict!
          },
        });

        const app = createTestApp(mockDb);
        const res = await request(app)
          .post('/roles')
          .send({ name, description: '' });

        expect(res.status).toBe(409);
        expect(res.body.code).toBe('CONFLICT');
      }),
      { numRuns: 50 }
    );
  }, 60000);
});


describe('Property 16: Permission Matrix Update with Cache Invalidation', () => {
  /**
   * Update persists and invalidates cache for all affected users.
   *
   * **Validates: Requirements 8.2**
   */

  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('permission matrix update on custom role calls updateRolePermissions', async () => {
    await fc.assert(
      fc.asyncProperty(
        uuidArb,
        fc.array(
          fc.record({
            module: moduleNameArb,
            action: validActionArb,
            granted: fc.boolean(),
          }),
          { minLength: 1, maxLength: 5 }
        ),
        async (roleId, permissions) => {
          vi.clearAllMocks();

          const mockDb = createMockDb({
            'SELECT id, name': {
              get: vi.fn().mockResolvedValue({
                id: roleId, name: 'CustomRole', is_custom: true,
              }),
            },
            'permission_audit_logs': {
              get: vi.fn().mockResolvedValue({ id: 'log-id' }),
              run: vi.fn().mockResolvedValue(undefined),
            },
          });

          // All modules are registered with all actions
          getModuleMock.mockImplementation((name: string) => ({
            name,
            actions: ['View', 'Create', 'Edit', 'Delete', 'Approve'],
            label: { en: name, ar: name },
            defaults: {},
          }));

          updateRolePermissionsMock.mockResolvedValue(undefined);

          const app = createTestApp(mockDb);
          const res = await request(app)
            .put(`/roles/${roleId}/permissions`)
