          expect(res.body.code).toBe('VALIDATION_ERROR');
          expect(invalidateCacheMock).not.toHaveBeenCalled();
        }
      ),
      { numRuns: 50 }
    );
  }, 60000);

  it('override is rejected when module is not registered', async () => {
    await fc.assert(
      fc.asyncProperty(
