describe('Preservation: Admin Bypass in checkPermission() (Requirements 3.1)', () => {
  /**
   * **Validates: Requirements 3.1**
   *
   * The checkPermission() middleware has an Admin bypass:
   * `if (user.role === 'Admin') return next()`
   * This must remain unchanged after the fix.
   */

  it('property: for all modules and actions, Admin always passes checkPermission', async () => {
    await fc.assert(
      fc.asyncProperty(
        fc.record({
          module: fc.constantFrom('User', 'Audit', 'Finding', 'Risk', 'Recommendation', 'Correspondence', 'Setting'),
          action: fc.constantFrom('View', 'Create', 'Edit', 'Delete', 'Approve'),
        }),
        async ({ module, action }) => {
          // Create a minimal app with checkPermission middleware
          const testApp = express();
          testApp.use(express.json());

          // Simulate checkPermission with Admin bypass (mirrors actual implementation)
          const checkPermission = (mod: string, act: string) => {
            return (req: any, res: any, next: any) => {
              if (req.user.role === 'Admin') return next();
              // For non-admin, would check DB - but we're testing Admin bypass
              return res.status(403).json({ error: 'Forbidden' });
            };
          };

          testApp.get('/test', (req: any, res, next) => {
            req.user = { id: 'admin-1', role: 'Admin', username: 'admin' };
            next();
          }, checkPermission(module, action), (req, res) => {
            res.json({ allowed: true });
          });

          const res = await request(testApp).get('/test');
          expect(res.status).toBe(200);
          expect(res.body.allowed).toBe(true);
        }
      ),
      { numRuns: 20 }
    );
  });
});

import express from 'express';
import { asyncHandler } from '../utils/asyncHandler';
import { backupScheduler } from '../utils/backup';
import { UserRole } from '../../constants';
import logger from '../utils/logger';

/**
 * Creates admin-only backup management routes.
 * - POST /backup — triggers an immediate manual backup
 * - GET /backup/history — returns recent backup history
 */
export const createAdminBackupRoutes = (
  authenticate: any,
  checkPermission: any
) => {
  const router = express.Router();

  // All routes require authentication + Settings Edit permission
  router.use(authenticate);
  router.use(checkPermission('Settings', 'Edit'));

  /**
   * POST /api/admin/backup
   * Triggers an immediate manual backup and returns the result.
   */
  router.post('/backup', asyncHandler(async (req, res) => {
    try {
      const result = await backupScheduler.runNow();
      res.json(result);
    } catch (error: any) {
      logger.error('[ADMIN] Manual backup trigger failed:', error);
      res.status(500).json({
        error: 'Backup failed',
        message: error.message || 'An unexpected error occurred during backup',
      });
    }
  }));

  /**
   * GET /api/admin/backup/history
   * Returns recent backup history records.
   */
  router.get('/backup/history', asyncHandler(async (req, res) => {
    const limit = Math.min(Math.max(parseInt(req.query.limit as string) || 20, 1), 100);
    const history = await backupScheduler.getHistory(limit);
    res.json(history);
  }));

  return router;
};

