    }
    await SettingsService.updatePdfSettings(validation.data);
    res.json({ success: true });
  }));

  router.get('/app-settings', authenticate, asyncHandler(async (req, res) => {
    const settings = await SettingsService.getAppSettings();
    res.json(settings);
  }));

