    const validation = appSettingsSchema.safeParse(req.body);
    if (!validation.success) {
      throw new ValidationError("Invalid App settings", validation.error.format());
    }
    await SettingsService.updateAppSettings(validation.data);
    res.json({ success: true });
  }));

  return router;
};

import { Router } from 'express';
import { AuthenticatedRequest } from '../types';
import { asyncHandler } from '../utils/asyncHandler';
import { ArchiveService } from '../services/ArchiveService';
import { AuditPlanService } from '../services/AuditPlanService';
import { ValidationError } from '../utils/errors';
import { methodNotAllowed } from '../utils/routeRegistry';

export const createArchiveRoutes = (
  db: any,
  authenticate: any,
  checkPermission: any,
  logError: any
) => {
  const router = Router();

  /**
   * POST /api/v1/audit-plans/:id/archive
   * Archives a plan and all its related data.
   * Requires Manager or Admin role.
   */
  router.post(
    '/audit-plans/:id/archive',
    authenticate,
    checkPermission('AuditPlans', 'Approve'),
    asyncHandler(async (req, res) => {
      const typedReq = req as unknown as AuthenticatedRequest;
      const { id } = req.params;
      const userId = typedReq.user.id;
      const userRole = typedReq.user.role;

      await ArchiveService.archivePlan(id, userId, userRole);

      res.json({
        success: true,
        message: 'تمت أرشفة الخطة بنجاح / Plan archived successfully',
      });
    })
  );

  /**
   * GET /api/v1/audit-plans/can-create
   * Checks if a new plan can be created for the given year.
   * Query param: year (required, integer)
   */
  router.get(
    '/audit-plans/can-create',
    authenticate,
    asyncHandler(async (req, res) => {
      const yearParam = req.query.year;

      if (!yearParam) {
        throw new ValidationError('year query parameter is required');
      }

      const year = parseInt(String(yearParam), 10);

      if (isNaN(year) || year < 2000 || year > 2100) {
        throw new ValidationError('year must be an integer between 2000 and 2100');
      }

      const result = await AuditPlanService.canCreateNewPlan(year);

      res.json({
        success: true,
        data: result,
      });
    })
  );

  /**
   * GET /api/v1/archived-plans
   * Returns all archived plans.
   */
  router.get(
    '/archived-plans',
    authenticate,
    checkPermission('AuditPlans', 'View'),
    asyncHandler(async (req, res) => {
      const archivedPlans = await db
        .prepare('SELECT * FROM archived_plans ORDER BY year DESC, archived_at DESC')
        .all();

      res.json({
        success: true,
        data: archivedPlans,
      });
    })
  );

  /**
   * GET /api/v1/archived-plans/:year
   * Returns archived plans for a specific year.
   */
  router.get(
    '/archived-plans/:year',
    authenticate,
    checkPermission('AuditPlans', 'View'),
    asyncHandler(async (req, res) => {
      const yearParam = req.params.year;
      const year = parseInt(yearParam, 10);

      if (isNaN(year) || year < 2000 || year > 2100) {
        throw new ValidationError('year must be an integer between 2000 and 2100');
      }

      const archivedPlans = await db
        .prepare('SELECT * FROM archived_plans WHERE year = ? ORDER BY archived_at DESC')
        .all(year);

      res.json({
        success: true,
        data: archivedPlans,
      });
    })
  );

  // 405 Method Not Allowed for unsupported methods
  router.all('/audit-plans/:id/archive', methodNotAllowed(['POST']));
  router.all('/audit-plans/can-create', methodNotAllowed(['GET']));
  router.all('/archived-plans', methodNotAllowed(['GET']));
  router.all('/archived-plans/:year', methodNotAllowed(['GET']));

  return router;
};

import express from 'express';
import { UploadedFile } from 'express-fileupload';
import { asyncHandler } from '../utils/asyncHandler';
import { AuditService, CreateFindingInput } from '../services/AuditService';
import { BaseService } from '../services/BaseService';
import { EvidenceStorageService } from '../services/EvidenceStorageService';
import { NotFoundError, ValidationError } from '../utils/errors';

export const createAuditFindingRoutes = (
  db: any,
  authenticate: any,
  checkPermission: any,
  logError: any
) => {
  const router = express.Router();

  // GET /audit-findings/by-plan/:planId - Get findings for a specific plan
  // Must be registered BEFORE /:id to prevent "by-plan" from matching as an id
  router.get('/by-plan/:planId', authenticate, checkPermission('AuditFindings', 'View'), asyncHandler(async (req, res) => {
    const { planId } = req.params;
    const findings = await AuditService.getFindingsByPlan(planId);
    res.json({ success: true, data: findings });
  }));

  // GET /audit-findings - List findings with pagination
  router.get('/', authenticate, checkPermission('AuditFindings', 'View'), asyncHandler(async (req, res) => {
    const result = await AuditService.getFindings(req.query);
    res.json(result);
  }));

  // GET /audit-findings/:id - Get single finding
  router.get('/:id', authenticate, checkPermission('AuditFindings', 'View'), asyncHandler(async (req, res) => {
    const id = req.params.id;
    const result = await BaseService.findById('audit_findings', id);
    if (!result) throw new NotFoundError('Finding not found');
    res.json(result);
  }));

  // POST /audit-findings - Create finding with auto-recommendation
  router.post('/', authenticate, checkPermission('AuditFindings', 'Create'), asyncHandler(async (req, res) => {
    const typedReq = req as any;
    const userId = typedReq.user.id;

    const input: CreateFindingInput = {
      audit_id: req.body.audit_id,
      title: req.body.title,
      description: req.body.description,
      criteria: req.body.criteria,
      condition: req.body.condition,
      finding_type: req.body.finding_type,
      consequence: req.body.consequence,
      risk_level: req.body.risk_level,
    };

    const result = await AuditService.createFinding(input, userId);

    res.status(201).json({
      success: true,
      findingId: result.findingId,
      recommendationId: result.recommendationId,
    });
  }));

  // PUT /audit-findings/:id - Update finding
  router.put('/:id', authenticate, checkPermission('AuditFindings', 'Edit'), asyncHandler(async (req, res) => {
    const typedReq = req as any;
    const id = req.params.id;
    const userId = typedReq.user.id;

    await AuditService.updateFinding(id, req.body, userId);
    res.json({ success: true });
  }));

  // PATCH /audit-findings/:id/status - Change finding status
  router.patch('/:id/status', authenticate, checkPermission('AuditFindings', 'Edit'), asyncHandler(async (req, res) => {
    const typedReq = req as any;
    const { id } = req.params;
    const { status } = req.body;
    const userId = typedReq.user.id;
    const userRole = typedReq.user.role;

    if (!status) {
      throw new ValidationError('الحالة مطلوبة / Status is required');
    }

    const result = await AuditService.changeFindingStatus(id, status, userId, userRole);
    res.json({ success: true, syncSuccess: result.syncSuccess });
  }));

  // DELETE /audit-findings/:id - Delete finding
  router.delete('/:id', authenticate, checkPermission('AuditFindings', 'Delete'), asyncHandler(async (req, res) => {
    const id = req.params.id;
    await AuditService.deleteFinding(id);
    res.json({ success: true });
  }));

  // POST /audit-findings/:findingId/evidence - Upload evidence for a finding
  // Requirements: 8.1, 8.2, 8.3, 8.4, 8.5, 8.6, 8.7
  router.post('/:findingId/evidence', authenticate, checkPermission('AuditFindings', 'Edit'), asyncHandler(async (req, res) => {
    const typedReq = req as any;
    const { findingId } = req.params;
    const userId = typedReq.user.id;

    // Validate file is present
    if (!typedReq.files || !typedReq.files.file) {
      throw new ValidationError('الملف مطلوب / File is required');
    }

    const uploadedFile: UploadedFile = Array.isArray(typedReq.files.file)
      ? typedReq.files.file[0]
      : typedReq.files.file;

    // Validate evidence metadata
    const { type, description } = req.body;
    if (!type || !description) {
      throw new ValidationError('نوع الدليل والوصف مطلوبان / Evidence type and description are required');
    }

    const validTypes = ['Document', 'Email', 'Screenshot', 'System Log', 'Contract'];
    if (!validTypes.includes(type)) {
      throw new ValidationError(`نوع الدليل غير صالح / Invalid evidence type. Must be one of: ${validTypes.join(', ')}`);
    }

    // Map express-fileupload UploadedFile to EvidenceFile interface
    const evidenceFile = {
      originalname: uploadedFile.name,
      buffer: uploadedFile.data,
      mimetype: uploadedFile.mimetype,
    };

    const result = await EvidenceStorageService.attachEvidence(
      findingId,
      evidenceFile,
      { type, description },
      userId
    );

    res.status(201).json({
      success: true,
      data: result,
    });
  }));

  // GET /audit-findings/:findingId/evidence - Get all evidence for a finding
  // Requirements: 8.1, 8.4
  router.get('/:findingId/evidence', authenticate, checkPermission('AuditFindings', 'View'), asyncHandler(async (req, res) => {
    const { findingId } = req.params;

    // Verify finding exists
    const finding = await BaseService.findById('audit_findings', findingId);
    if (!finding) {
      throw new NotFoundError('الملاحظة غير موجودة / Finding not found');
    }

    const evidence = await db.prepare(
      `SELECT id, audit_id, finding_id, evidence_number, type, description,
              uploaded_by, upload_date, file_name, file_path
       FROM audit_evidence
       WHERE finding_id = ?
       ORDER BY upload_date ASC`
    ).all(findingId);

    res.json({
      success: true,
      data: evidence,
    });
  }));

  return router;
};

import { Router } from "express";
import { z } from "zod";
import { AuthenticatedRequest } from "../types";
import { asyncHandler } from "../utils/asyncHandler";
import { AuditProgramService } from "../services/AuditProgramService";
import { AuthService } from "../services/AuthService";
import { ValidationError } from "../utils/errors";
import { methodNotAllowed } from "../utils/routeRegistry";

export const createAuditProgramRoutes = (db: any, authenticate: any, checkPermission: any, logError: any) => {
  const router = Router();

  router.post("/:id/duplicate", authenticate, asyncHandler(async (req, res) => {
    const typedReq = req as unknown as AuthenticatedRequest;
    const id = req.params.id as string;
    if (!id || id === 'undefined') {
      throw new ValidationError("Invalid audit program ID");
    }
    const user = typedReq.user.username;
    
    const newId = await AuditProgramService.duplicate(id, user);
    
    await AuthService.logAudit(user, "Duplicate", "Audit Program Library", `Duplicated program ID: ${id} to ${newId}`);
      
    res.json({ id: newId });
  }));

  router.post("/:id/approve", authenticate, asyncHandler(async (req, res) => {
    const typedReq = req as unknown as AuthenticatedRequest;
    const id = req.params.id as string;
    if (!id || id === 'undefined') {
      throw new ValidationError("Invalid audit program ID");
    }
    const user = typedReq.user.username;
    const userId = typedReq.user.id;
    const userRole = typedReq.user.role;
    
    await AuditProgramService.approveProgram(id, userId, userRole);
    
    await AuthService.logAudit(user, "Approve", "Audit Program Library", `Approved program ID: ${id}`);
      
    res.json({ success: true });
  }));

  // 405 Method Not Allowed for methods not implemented on this custom route
  // This route only supports POST (duplicate, approve) - no GET, PUT, DELETE at root level
  router.all("/", methodNotAllowed(['POST']));
  router.all("/:id", methodNotAllowed(['POST']));

  return router;
};

import express from 'express';
import { AuditTaskService } from '../services/AuditTaskService';
import { NotificationService } from '../services/NotificationService';
import { asyncHandler } from '../utils/asyncHandler';
import { methodNotAllowed } from '../utils/routeRegistry';
import { UserRole } from '../../constants';

export const createAuditTaskRoutes = (
  db: any,
  authenticate: any,
  logError: any
) => {
  const router = express.Router();

  // Custom route for status transitions
  router.patch('/:id/status', authenticate, asyncHandler(async (req, res) => {
    const { id } = req.params;
    const { status } = req.body;
    
    const typedReq = req as any;
    const userId = typedReq.user.id;
    const userRole = typedReq.user.role;

    try {
      await AuditTaskService.changeStatus(String(id), status, userId, userRole, db);

      // Notify assigned user about status change
      try {
        const task = await db.prepare("SELECT title, assigned_to, created_by FROM audit_tasks WHERE id = ?::uuid").get(id) as any;
        if (task) {
          const recipients: string[] = [];
          if (task.assigned_to && task.assigned_to !== userId) recipients.push(task.assigned_to);
          if (task.created_by && task.created_by !== userId && task.created_by !== task.assigned_to) recipients.push(task.created_by);
          
          if (recipients.length > 0) {
            await NotificationService.create(
              recipients,
              'task_status_changed',
              JSON.stringify({ key: 'notifications.taskStatusChanged', params: { title: task.title, status: status } }),
              'AuditTasks',
              '/tasks',
              {
                actorId: userId,
                entityId: id,
                entityType: 'audit_task',
                title: JSON.stringify({ key: 'notifications.taskStatusChanged' }),
                wss: (req.app as any).wss,
                data: { new_status: status }
              }
            );
          }
        }
      } catch (e) {
        console.error("[AuditTasks] Notification failed:", e);
      }

      res.json({ success: true, message: 'Status updated successfully' });
    } catch (err: any) {
      logError(err, 'PATCH', req.originalUrl, req.ip, userId);
      res.status(400).json({ success: false, error: { message: err.message, code: err.code || 'BAD_REQUEST' } });
    }
  }));

  // POST /api/v1/audit-tasks/:id/assign - Assign users to a task
  // Requirements: 4.1, 4.3, 4.5
  router.post('/:id/assign', authenticate, asyncHandler(async (req, res) => {
    const { id } = req.params;
    const { userIds } = req.body;

    const typedReq = req as any;
    const userId = typedReq.user.id;
    const userRole = typedReq.user.role;

    // Role validation: only Manager or Admin can assign users
    const allowedRoles = [UserRole.MANAGER, UserRole.ADMIN];
    if (!allowedRoles.includes(userRole)) {
      return res.status(403).json({
        success: false,
        error: {
          message: 'لا تملك صلاحية تعيين مستخدمين للمهام. يجب أن يكون دورك مدير أو مسؤول',
          code: 'FORBIDDEN'
        }
      });
    }

    try {
      const result = await AuditTaskService.assignUsers(String(id), userIds, userId);

      // Send notification to each assigned user (Requirement 4.3: within 60 seconds)
      try {
        const task = await db.prepare("SELECT title, task_number FROM audit_tasks WHERE id = ?::uuid").get(id) as any;
        if (task && result.assignments.length > 0) {
          const assignedUserIds = result.assignments.map((a: any) => a.user_id);

          await NotificationService.create(
            assignedUserIds,
            'task_assigned',
            JSON.stringify({ key: 'notifications.taskAssigned', params: { title: task.title, taskNumber: task.task_number } }),
            'AuditTasks',
            '/tasks',
            {
              actorId: userId,
              entityId: id,
              entityType: 'audit_task',
              title: JSON.stringify({ key: 'notifications.taskAssigned' }),
              wss: (req.app as any).wss,
              data: { task_id: id, task_number: task.task_number }
            }
          );
        }
      } catch (e) {
        console.error("[AuditTasks] Assignment notification failed:", e);
      }

      res.status(201).json({ success: true, data: result });
    } catch (err: any) {
      logError(err, 'POST', req.originalUrl, req.ip, userId);
      const statusCode = err.statusCode || 400;
      res.status(statusCode).json({
        success: false,
        error: { message: err.message, code: err.errorCode || 'BAD_REQUEST', details: err.details }
      });
    }
  }));

  // DELETE /api/v1/audit-tasks/:id/assign/:userId - Unassign a user from a task
  // Requirements: 4.4, 4.5
  router.delete('/:id/assign/:userId', authenticate, asyncHandler(async (req, res) => {
    const { id, userId: targetUserId } = req.params;

    const typedReq = req as any;
    const currentUserId = typedReq.user.id;
    const userRole = typedReq.user.role;

    // Role validation: only Manager or Admin can unassign users
    const allowedRoles = [UserRole.MANAGER, UserRole.ADMIN];
    if (!allowedRoles.includes(userRole)) {
      return res.status(403).json({
        success: false,
        error: {
          message: 'لا تملك صلاحية إزالة تعيين المستخدمين من المهام. يجب أن يكون دورك مدير أو مسؤول',
          code: 'FORBIDDEN'
        }
      });
    }

    try {
      const result = await AuditTaskService.unassignUser(String(id), String(targetUserId), currentUserId);
      res.json({ success: true, data: result });
    } catch (err: any) {
      logError(err, 'DELETE', req.originalUrl, req.ip, currentUserId);
      const statusCode = err.statusCode || 400;
      res.status(statusCode).json({
        success: false,
        error: { message: err.message, code: err.errorCode || 'BAD_REQUEST' }
      });
    }
  }));

  router.get('/', authenticate, asyncHandler(async (req, res) => {
    const tasks = await AuditTaskService.getTasks(req.query);
    res.json(tasks);
  }));

  // 405 Method Not Allowed for methods not implemented on this custom route
  // This route supports GET (list) and PATCH (status change) only
  router.all('/', methodNotAllowed(['GET']));
  router.all('/:id', methodNotAllowed(['PATCH']));

  return router;
};

import express from 'express';
import { createLoginRoutes } from './login';
import { createSessionRoutes } from './session';
import { createPasswordRoutes } from './password';
import { createTwoFactorRoutes } from './twoFactor';

export const createAuthRoutes = (
  db: any,
  JWT_SECRET: string,
  JWT_PRIVATE_KEY: string,
  authLimiter: any,
  authenticate: any,
  checkPermission: any,
  createNotification: any,
  logError: any
) => {
  const router = express.Router();

  router.use(createLoginRoutes(db, JWT_SECRET, JWT_PRIVATE_KEY, authLimiter, logError));
  router.use(createSessionRoutes(db, JWT_SECRET, JWT_PRIVATE_KEY, authenticate, logError));
  router.use(createPasswordRoutes(db, JWT_SECRET, JWT_PRIVATE_KEY, authLimiter, authenticate, checkPermission, createNotification, logError));
  router.use(createTwoFactorRoutes(db, JWT_SECRET, JWT_PRIVATE_KEY, authenticate, logError));

  return router;
};

import express from 'express';
import jwt from 'jsonwebtoken';
import { z } from 'zod';
import { AuthService } from '../../services/AuthService';
import { totpService } from '../../services/TOTPService';
import { asyncHandler } from '../../utils/asyncHandler';
import { validateSchema } from '../../middleware/validate';
import { generateCsrfToken, attachCsrfToken } from '../../middleware/csrf';

const loginSchema = z.object({
  usernameOrEmail: z.string().min(1, "Username or Email is required").max(100),
  password: z.string().min(1, "Password is required").max(100),
  rememberMe: z.boolean().optional(),
});

export const createLoginRoutes = (
  db: any,
  JWT_SECRET: string,
  JWT_PRIVATE_KEY: string,
  authLimiter: any,
  logError: any
) => {
  const router = express.Router();

  router.post("/login", authLimiter, validateSchema(loginSchema), asyncHandler(async (req, res) => {
    const { usernameOrEmail, password, rememberMe } = req.body; 

    const result = await AuthService.login(usernameOrEmail, password, JWT_SECRET, JWT_PRIVATE_KEY, req.ip, req.get('user-agent'), rememberMe);

    // Check if user has 2FA enabled — if so, return a short-lived temp token
    // instead of full access tokens
    if (await totpService.isEnabled(result.user.id)) {
      const tempToken = jwt.sign(
        { id: result.user.id, username: result.user.username, type: '2fa_pending' },
        JWT_PRIVATE_KEY,
        { algorithm: 'RS256', expiresIn: '5m' }
      );
      return res.json({ requires2FA: true, tempToken });
    }

    // Normal login flow (no 2FA) — issue full tokens
    // In production: sameSite: 'none' + secure: true (supports cross-origin/iframe)
    // In development: sameSite: 'lax' + secure: false (works on HTTP localhost)
    const isProduction = process.env.NODE_ENV === 'production';
    const cookieOptions: any = { 
      httpOnly: true, 
      secure: isProduction, 
      sameSite: isProduction ? 'none' : 'lax', 
      path: '/' 
    };

    res.cookie('token', result.token, {
      ...cookieOptions,
      maxAge: 15 * 60 * 1000 // 15 minutes
    });
    
    // Refresh Token: Cookie-Only Storage
    res.cookie('refreshToken', result.refreshToken, {
      httpOnly: true,
      secure: isProduction, 
      sameSite: isProduction ? 'none' : 'lax', 
      path: '/api/auth/refresh', // Restrict cookie path
      maxAge: rememberMe ? 30 * 24 * 60 * 60 * 1000 : 8 * 60 * 60 * 1000 // 30 days or 8 hours in ms
    });

    await AuthService.logAudit(result.user.username, "Login", "Authentication", "User logged in");

    // Generate and attach CSRF token on successful login
    const csrfToken = generateCsrfToken();
    attachCsrfToken(res, csrfToken);

    // Return ONLY the access token in the response body:
    res.json({ user: result.user, token: result.token });
  }));

  return router;
};

import express from 'express';
import jwt from 'jsonwebtoken';
import { z } from 'zod';
import { PasswordService } from '../../services/PasswordService';
import { AuthService } from '../../services/AuthService';
import { asyncHandler } from '../../utils/asyncHandler';
import { ValidationError } from '../../utils/errors';

const forgotPasswordSchema = z.object({
  username: z.string().min(1)
});

const approveResetSchema = z.object({
  requestId: z.string().min(1)
});

const changePasswordSchema = z.object({
  newPassword: z.string().min(8).max(100)
});

const updatePasswordSchema = z.object({
  currentPassword: z.string().min(1),
  newPassword: z.string().min(8).max(100)
});

export const createPasswordRoutes = (
  db: any,
  JWT_SECRET: string,
  JWT_PRIVATE_KEY: string,
  authLimiter: any,
  authenticate: any,
  checkPermission: any,
  createNotification: any,
  logError: any
) => {
  const router = express.Router();

  // Forgot Password
  router.post("/forgot-password", authLimiter, asyncHandler(async (req, res) => {
    const validation = forgotPasswordSchema.safeParse(req.body);
    if (!validation.success) {
      throw new ValidationError("Invalid username", validation.error.format());
    }
    const { username } = validation.data;
    const result = await PasswordService.requestReset(username);
    
    if (result.user && result.admins) {
      for (const admin of result.admins) {
        await createNotification(admin.id, 'password_reset_request', result.alertMsg, 'Security', '/users', { actorId: result.user.id, wss: (req.app as any).wss });
      }
      await AuthService.logAudit(result.user.username, "Password Reset Request", "Security", "User requested password reset");
    }

    res.json({ success: true, message: result.message });
  }));

  // Check Reset Status
  router.get("/reset-status/:username", authLimiter, asyncHandler(async (req, res) => {
    const username = req.params.username as string;
    const status = await PasswordService.getResetStatus(username);
    res.json({ status });
  }));

  // Admin: Get Reset Requests
  router.get("/reset-requests", authenticate, checkPermission('UserManagement', 'Edit'), asyncHandler(async (req, res) => {
    const data = await PasswordService.getResetRequests();
    res.json(data);
  }));

  // Admin: Approve Reset Request
  router.post("/approve-reset", authenticate, checkPermission('UserManagement', 'Edit'), asyncHandler(async (req, res) => {
    const validation = approveResetSchema.safeParse(req.body);
    if (!validation.success) {
      throw new ValidationError("Invalid request ID", validation.error.format());
    }
    const { requestId } = validation.data;
    const adminId = (req as any).user.id;
    const result = await PasswordService.approveReset(requestId, adminId);

    await AuthService.logAudit((req as any).user.username, "Admin Password Reset", "Security", `Admin reset password for user: ${result.username}. Request ID: ${requestId}`);

    res.json({ success: true, tempPassword: result.tempPassword });
  }));

  // User: Change Password (Mandatory or Voluntary)
  router.post("/change-password", authLimiter, authenticate, asyncHandler(async (req, res) => {
    const validation = changePasswordSchema.safeParse(req.body);
    if (!validation.success) {
      throw new ValidationError("Invalid password data", validation.error.format());
    }
    const { newPassword } = validation.data;
    const userId = (req as any).user.id;
    
    const user = await PasswordService.changePassword(userId, newPassword);
    
    await AuthService.logAudit(user.username, "Change Password", "Security", "User changed their password");
    
    const token = jwt.sign(
      { id: user.id, username: user.username, role: user.role, session_version: user.session_version },
      JWT_PRIVATE_KEY,
      { algorithm: 'RS256', expiresIn: '15m' }
    );

    res.cookie('token', token, { httpOnly: true, secure: true, sameSite: 'none', path: '/' });
    res.json({ success: true, token });
  }));

  // User: Update Password
  router.post("/update-password", authLimiter, authenticate, asyncHandler(async (req, res) => {
    const validation = updatePasswordSchema.safeParse(req.body);
    if (!validation.success) {
      throw new ValidationError("Invalid password data", validation.error.format());
    }
    const { currentPassword, newPassword } = validation.data;
    const userId = (req as any).user.id;
    
    const user = await PasswordService.updatePassword(userId, currentPassword, newPassword);
    
    await AuthService.logAudit(user.username, "Change Password", "Settings", "User changed their password");
    
    const token = jwt.sign(
      { id: user.id, username: user.username, role: user.role, session_version: user.session_version },
      JWT_PRIVATE_KEY,
      { algorithm: 'RS256', expiresIn: '15m' }
    );

    res.cookie('token', token, { httpOnly: true, secure: true, sameSite: 'none', path: '/' });
    res.json({ success: true, token });
  }));

  return router;
};

import express from 'express';
import rateLimit from 'express-rate-limit';
import { SessionService } from '../../services/SessionService';
import { AuthService } from '../../services/AuthService';
import { asyncHandler } from '../../utils/asyncHandler';
import { AuthError } from '../../utils/errors';
import { generateCsrfToken, attachCsrfToken } from '../../middleware/csrf';

export const createSessionRoutes = (
  db: any,
  JWT_SECRET: string,
  JWT_PRIVATE_KEY: string,
  authenticate: any,
  logError: any
) => {
  const router = express.Router();

  const refreshLimiter = rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 30,
    message: { error: "TOO_MANY_ATTEMPTS" },
    standardHeaders: true,
    legacyHeaders: false,
  });

  // Current User
  router.get("/me", authenticate, asyncHandler(async (req, res) => {
    const user = (req as any).user;
    
    // Fetch permissions from DB for the current user
    let permissions: Array<{ module: string; action: string }> = [];
    try {
      permissions = await db.prepare(`
        SELECT p.module, p.action FROM permissions p
        JOIN role_permissions rp ON p.id = rp.permission_id
        WHERE rp.role_id = (SELECT role_id FROM users WHERE id = ?)
        UNION
        SELECT p.module, p.action FROM permissions p
        JOIN user_permissions up ON p.id = up.permission_id
        WHERE up.user_id = ? AND up.is_allowed = 1
      `).all(user.id, user.id) as Array<{ module: string; action: string }>;
    } catch (e) {
      console.error("[Session] Failed to fetch permissions:", e);
    }

    res.json({ user: { ...user, permissions } });
  }));

  // Refresh Token
  router.post("/refresh", refreshLimiter, asyncHandler(async (req, res) => {
    const refreshToken = req.cookies.refreshToken;
    
    if (!refreshToken) {
      // If no refresh token is present, just return 401 without throwing (to avoid noisy logs)
      return res.status(401).json({ 
        success: false, 
        error: { code: 'UNAUTHORIZED', message: "No refresh token" } 
      });
    }

    try {
      const result = await SessionService.refresh(refreshToken, JWT_SECRET, JWT_PRIVATE_KEY);

      // In production: sameSite: 'none' + secure: true (supports cross-origin/iframe)
      // In development: sameSite: 'lax' + secure: false (works on HTTP localhost)
      const isProduction = process.env.NODE_ENV === 'production';
      const cookieOptions: any = {
        httpOnly: true,
        secure: isProduction,
        sameSite: isProduction ? 'none' : 'lax',
        path: '/'
      };

      // Refresh Token: Cookie-Only Storage
      res.cookie('refreshToken', result.refreshToken, {
        httpOnly: true,
        secure: isProduction,
        sameSite: isProduction ? 'none' : 'lax',
        path: '/api/auth/refresh', // Restrict cookie path
        maxAge: result.rememberMe ? 30 * 24 * 60 * 60 * 1000 : 8 * 60 * 60 * 1000 // 30 days or 8 hours in ms
      });

      res.cookie('token', result.token, {
        ...cookieOptions,
        maxAge: 15 * 60 * 1000 // 15 minutes
      });

      await AuthService.logAudit(result.user.username, "Refresh Token", "Auth", "Token refreshed successfully");

      // Generate and attach CSRF token on successful refresh
      const csrfToken = generateCsrfToken();
      attachCsrfToken(res, csrfToken);

      res.json({ success: true });
    } catch (error) {
      // Clear cookies with same options
      const isProduction = process.env.NODE_ENV === 'production';
      const clearOptions: any = { httpOnly: true, secure: isProduction, sameSite: isProduction ? 'none' : 'lax', path: '/' };
      const refreshClearOptions: any = { ...clearOptions, path: '/api/auth/refresh' };
      res.clearCookie('refreshToken', refreshClearOptions);
      res.clearCookie('token', clearOptions);
      throw error;
    }
  }));

  // Logout
  router.post("/logout", asyncHandler(async (req, res) => {
    const refreshToken = req.cookies.refreshToken;
    const username = await SessionService.logout(refreshToken);
    
    if (username) {
      await AuthService.logAudit(username, "Logout", "Auth", "User logged out");
    }

    // Clear cookies with same options
    const isProduction = process.env.NODE_ENV === 'production';
    const clearOptions: any = { httpOnly: true, secure: isProduction, sameSite: isProduction ? 'none' : 'lax', path: '/' };
    const refreshClearOptions: any = { ...clearOptions, path: '/api/auth/refresh' };
    res.clearCookie('refreshToken', refreshClearOptions);
    res.clearCookie('token', clearOptions);
    res.json({ success: true });
  }));

  // Logout All
  router.post("/logout-all", authenticate, asyncHandler(async (req, res) => {
    const userId = (req as any).user.id;
    await SessionService.logoutAll(userId);
    
    await AuthService.logAudit((req as any).user.username, "Logout All", "Settings", "User invalidated all active sessions");

    res.json({ success: true });
  }));

  // WebSocket Token - issues a short-lived token for WebSocket connections
  // Since the access token is in an httpOnly cookie (not accessible from JS),
  // the frontend calls this endpoint to get a token it can pass as a query parameter.
  router.get("/ws-token", authenticate, asyncHandler(async (req, res) => {
    const user = (req as any).user;
    const jwt = await import('jsonwebtoken');
    const wsToken = jwt.default.sign(
      { id: user.id, username: user.username, type: 'ws' },
      JWT_PRIVATE_KEY,
      { algorithm: 'RS256', expiresIn: '30s' }
    );
    res.json({ token: wsToken });
  }));

  return router;
};

import express from 'express';
import jwt from 'jsonwebtoken';
import { z } from 'zod';
import { totpService } from '../../services/TOTPService';
import { AuthService } from '../../services/AuthService';
import { asyncHandler } from '../../utils/asyncHandler';
import { validateBody } from '../../middleware/validate';
import { db } from '../../db/index';
import { AuthError } from '../../utils/errors';
import logger from '../../utils/logger';
import { generateCsrfToken, attachCsrfToken } from '../../middleware/csrf';

// ─── Schemas ─────────────────────────────────────────────────────────────────

const verifySchema = z.object({
  token: z.string().length(6, 'TOTP code must be exactly 6 digits').regex(/^\d{6}$/, 'TOTP code must be 6 digits'),
});

const validateSchema = z.object({
  tempToken: z.string().min(1, 'Temp token is required'),
  token: z.string().length(6, 'TOTP code must be exactly 6 digits').regex(/^\d{6}$/, 'TOTP code must be 6 digits'),
});

const backupSchema = z.object({
  tempToken: z.string().min(1, 'Temp token is required'),
  code: z.string().min(1, 'Backup code is required'),
});

const disableSchema = z.object({
  password: z.string().min(1, 'Password is required'),
});

// ─── Helper: Verify temp token ───────────────────────────────────────────────

function verifyTempToken(tempToken: string, jwtPublicKey: string): { userId: string; username: string } {
  try {
    const decoded = jwt.verify(tempToken, jwtPublicKey, { algorithms: ['RS256'] }) as any;
    if (decoded.type !== '2fa_pending') {
      throw new AuthError('Invalid token type');
    }
    return { userId: decoded.id, username: decoded.username };
  } catch (err) {
    if (err instanceof AuthError) throw err;
    throw new AuthError('Invalid or expired temp token');
  }
}

// ─── Helper: Issue full tokens (mirrors login flow) ──────────────────────────

async function issueFullTokens(userId: string, jwtPrivateKey: string, req: any, res: any) {
  const user = await db.prepare(
    'SELECT id, username, role, name, email, session_version FROM users WHERE id = ?'
  ).get(userId) as any;

  if (!user) {
    throw new AuthError('User not found');
  }

  const token = jwt.sign(
    { id: user.id, username: user.username, role: user.role, session_version: user.session_version },
    jwtPrivateKey,
    { algorithm: 'RS256', expiresIn: '15m' }
  );

  const refreshToken = jwt.sign(
    { id: user.id, username: user.username, role: user.role, session_version: user.session_version, rememberMe: false },
    jwtPrivateKey,
    { algorithm: 'RS256', expiresIn: '8h' }
  );

  // Store refresh token
  const refreshExpiry = new Date(Date.now() + 8 * 60 * 60 * 1000); // 8 hours
  await db.prepare(
    'INSERT INTO refresh_tokens (token, user_id, expires_at) VALUES (?::text, ?::uuid, ?::timestamp)'
  ).run(refreshToken, userId, refreshExpiry.toISOString());

  // Set cookies (same pattern as login)
  const isProduction = process.env.NODE_ENV === 'production';
  const cookieOptions: any = {
    httpOnly: true,
    secure: isProduction,
    sameSite: isProduction ? 'none' : 'lax',
    path: '/',
  };

  res.cookie('token', token, {
    ...cookieOptions,
    maxAge: 15 * 60 * 1000, // 15 minutes
  });

  res.cookie('refreshToken', refreshToken, {
    httpOnly: true,
    secure: isProduction,
    sameSite: isProduction ? 'none' : 'lax',
    path: '/api/auth/refresh',
    maxAge: 8 * 60 * 60 * 1000, // 8 hours
  });

  // Generate and attach CSRF token
  const csrfToken = generateCsrfToken();
  attachCsrfToken(res, csrfToken);

  await AuthService.logAudit(user.username, '2FA Login', 'Authentication', 'User completed 2FA verification');

  return { token, refreshToken, user: { id: user.id, username: user.username, role: user.role, name: user.name } };
}

// ─── Route Factory ───────────────────────────────────────────────────────────

export const createTwoFactorRoutes = (
  db: any,
  JWT_SECRET: string,
  JWT_PRIVATE_KEY: string,
  authenticate: any,
  logError: any
) => {
  const router = express.Router();

  // We need the public key for verifying temp tokens
  // The authenticate middleware uses JWT_PUBLIC_KEY internally, but we need it here too
  // JWT_SECRET is actually the public key passed from the auth routes index
  const JWT_PUBLIC_KEY = JWT_SECRET;

  // ─── POST /2fa/setup ─────────────────────────────────────────────────────
  // Requires authentication. Generates TOTP secret, QR code, and backup codes.
  router.post('/2fa/setup', authenticate, asyncHandler(async (req: any, res) => {
    const userId = req.user.id;

    const result = await totpService.setup(userId);

    res.json({
      secret: result.secret,
      qrCodeDataUrl: result.qrCodeDataUrl,
      backupCodes: result.backupCodes,
    });
  }));

  // ─── POST /2fa/verify ────────────────────────────────────────────────────
  // Requires authentication. Confirms 2FA setup by verifying the first TOTP code.
  // On success, enables 2FA (is_enabled = true, enabled_at = NOW()).
  router.post('/2fa/verify', authenticate, validateBody(verifySchema), asyncHandler(async (req: any, res) => {
    const userId = req.user.id;
    const { token } = req.body;

    const isValid = await totpService.verify(userId, token);

    if (!isValid) {
      return res.status(400).json({ error: 'Invalid TOTP code' });
    }

    // Enable 2FA
    await db.prepare(
      'UPDATE user_totp SET is_enabled = TRUE, enabled_at = CURRENT_TIMESTAMP WHERE user_id = ?'
    ).run(userId);

    logger.info(`[2FA] 2FA enabled for user ${userId}`);
    await AuthService.logAudit(req.user.username, '2FA Enabled', 'Security', 'User enabled two-factor authentication');

    res.json({ success: true });
  }));

  // ─── POST /2fa/validate ──────────────────────────────────────────────────
  // Does NOT require full auth. Uses tempToken (short-lived JWT with type='2fa_pending').
  // Validates TOTP during login flow and issues full access/refresh tokens.
  router.post('/2fa/validate', validateBody(validateSchema), asyncHandler(async (req: any, res) => {
    const { tempToken, token } = req.body;

    // Verify the temp token
    const { userId } = verifyTempToken(tempToken, JWT_PUBLIC_KEY);

    // Verify TOTP code
    const isValid = await totpService.verify(userId, token);

    if (!isValid) {
      return res.status(401).json({ error: 'Invalid TOTP code' });
    }

    // Issue full tokens
    const result = await issueFullTokens(userId, JWT_PRIVATE_KEY, req, res);

    res.json({ user: result.user, token: result.token });
  }));

  // ─── POST /2fa/backup ────────────────────────────────────────────────────
  // Does NOT require full auth. Uses tempToken.
  // Accepts a backup code as alternative to TOTP during login.
  router.post('/2fa/backup', validateBody(backupSchema), asyncHandler(async (req: any, res) => {
    const { tempToken, code } = req.body;

    // Verify the temp token
    const { userId } = verifyTempToken(tempToken, JWT_PUBLIC_KEY);

    // Verify backup code
    const isValid = await totpService.useBackupCode(userId, code);

    if (!isValid) {
      return res.status(401).json({ error: 'Invalid backup code' });
    }

    // Issue full tokens
    const result = await issueFullTokens(userId, JWT_PRIVATE_KEY, req, res);

    res.json({ user: result.user, token: result.token });
  }));

  // ─── DELETE /2fa ─────────────────────────────────────────────────────────
  // Requires authentication. Disables 2FA after password confirmation.
  router.delete('/2fa', authenticate, validateBody(disableSchema), asyncHandler(async (req: any, res) => {
    const userId = req.user.id;
    const { password } = req.body;

    try {
      await totpService.disable(userId, password);
    } catch (err: any) {
      if (err.statusCode === 401) {
        return res.status(401).json({ error: 'Incorrect password' });
      }
      throw err;
    }

    await AuthService.logAudit(req.user.username, '2FA Disabled', 'Security', 'User disabled two-factor authentication');

    res.json({ success: true });
  }));

  return router;
};

import express from 'express';
import { asyncHandler } from '../utils/asyncHandler';
import { ValidationError } from '../utils/errors';
import { BulkOperationsService, BulkOperation } from '../services/BulkOperationsService';
import { AuthenticatedRequest } from '../types';

/**
 * Creates the bulk operations router.
 *
 * Endpoint: POST /api/v1/bulk/:resource
 * Body: { operation: 'create' | 'update' | 'delete', items: [...] }
 *
 * Validates all items before processing; rejects entire batch on validation failure.
 * Processes all valid items in a single transaction; rolls back on any processing failure.
 * Returns response with processed count, success count, and per-item status.
 *
 * Requirements: 16.1, 16.2, 16.3, 16.4, 16.5, 16.6
 */
export const createBulkRoutes = (authenticate: any) => {
  const router = express.Router();

  const VALID_OPERATIONS: BulkOperation[] = ['create', 'update', 'delete'];

  router.post('/:resource', authenticate, asyncHandler(async (req, res) => {
    const typedReq = req as unknown as AuthenticatedRequest;
    const resource = typedReq.params.resource;
    const { operation, items } = typedReq.body;

    // Validate operation type
    if (!operation || !VALID_OPERATIONS.includes(operation)) {
      throw new ValidationError(
        `Invalid operation. Must be one of: ${VALID_OPERATIONS.join(', ')}`,
        { field: 'operation', received: operation }
      );
    }

    // Validate items is present and is an array
    if (!items || !Array.isArray(items)) {
      throw new ValidationError(
        'Request body must contain an "items" array',
        { field: 'items' }
      );
    }

    const username = typedReq.user?.username || 'unknown';

    const result = await BulkOperationsService.execute(
      resource,
      operation as BulkOperation,
      items,
      username
    );

    res.json(result);
  }));

  return router;
};

import express from 'express';
import { z } from 'zod';
import { CoiService } from '../services/CoiService';
import { asyncHandler } from '../utils/asyncHandler';
import { ValidationError } from '../utils/errors';

const coiCreateSchema = z.object({
  description: z.string().min(1).max(2000),
  related_party: z.string().min(1).max(255),
});

const coiUpdateSchema = z.object({
  status: z.enum(['Pending', 'Approved', 'Rejected', 'Closed']),
  reviewer_notes: z.string().optional().nullable(),
});

export const createCoiRoutes = (
  db: any,
  authenticate: any,
  checkPermission: any,
  logError: any
) => {
  const router = express.Router();

  router.get('/coi', authenticate, asyncHandler(async (req, res) => {
    const records = await CoiService.getAll();
    res.json(records);
  }));

  router.post('/coi', authenticate, asyncHandler(async (req, res) => {
    const validation = coiCreateSchema.safeParse(req.body);
