    res.json({ success: true });
  }));

  return router;
};

import express from 'express';
import { z } from 'zod';
import { CommentService } from '../services/CommentService';
import { NotificationService } from '../services/NotificationService';
import { asyncHandler } from '../utils/asyncHandler';
import { ValidationError } from '../utils/errors';

const commentSchema = z.object({
  related_type: z.string().min(1),
  related_id: z.string().min(1),
  content: z.string().min(1).max(5000),
});

export const createCommentRoutes = (db: any, authenticate: any, logError: any) => {
  const router = express.Router();

  router.get("/:type/:id", authenticate, asyncHandler(async (req, res) => {
    const comments = await CommentService.getComments(req.params.type as string, req.params.id as string);
    res.json(comments);
  }));

  router.post("/", authenticate, asyncHandler(async (req, res) => {
    const validation = commentSchema.safeParse(req.body);
    if (!validation.success) {
      throw new ValidationError("Invalid comment data", validation.error.format());
    }
    const userId = (req as any).user.id;
    const result = await CommentService.createComment(userId, validation.data);

    // Notify other participants on this entity
    try {
      const { related_type, related_id } = validation.data;
      // Get all users who previously commented on this entity
      const previousCommenters = await db.prepare(
        "SELECT DISTINCT user_id FROM comments WHERE related_type = ? AND related_id = ?::uuid AND user_id != ?::uuid"
      ).all(related_type, related_id, userId) as any[];
      
      const recipientIds = previousCommenters.map((c: any) => c.user_id);
      
      if (recipientIds.length > 0) {
        const actorName = (req as any).user.name || (req as any).user.username;
        await NotificationService.create(
          recipientIds,
          'comment_added',
          JSON.stringify({ key: 'notifications.commentAdded', params: { actor: actorName, type: related_type } }),
          related_type,
          `/${related_type}`,
          {
            actorId: userId,
            entityId: related_id,
            entityType: related_type,
            title: JSON.stringify({ key: 'notifications.commentAdded' }),
            wss: (req.app as any).wss
          }
        );
      }
    } catch (e) {
      console.error("[Comments] Failed to send notification:", e);
    }

    res.json(result);
  }));

  return router;
};

import { Router } from 'express';
import { z } from 'zod';
import { ComplianceService } from '../services/ComplianceService';
import { asyncHandler } from '../utils/asyncHandler';
import { ValidationError } from '../utils/errors';

const itemSchema = z.object({
  ref_number:            z.string().min(1),
  title:                 z.string().min(1).max(500),
  source_type:           z.enum(['cbi_instruction', 'law', 'internal_policy', 'admin_decision']),
  issuing_authority:     z.string().optional().nullable(),
  category:              z.string().optional().nullable(),
  issue_date:            z.string().optional().nullable(),
  effective_date:        z.string().optional().nullable(),
  review_date:           z.string().optional().nullable(),
  compliance_status:     z.enum(['compliant', 'partial', 'non_compliant', 'under_review']).optional(),
  maturity_score:        z.coerce.number().min(0).max(100).optional().nullable(),
  gap_notes:             z.string().optional().nullable(),
  responsible_person_id: z.string().uuid().optional().nullable(),
  department_id:         z.string().uuid().optional().nullable(),
  description:           z.string().optional().nullable(),
  keywords:              z.string().optional().nullable(),
  version:               z.string().optional().nullable(),
  attachment_path:       z.string().optional().nullable(),
});

export const createComplianceRoutes = (
  db: any, authenticate: any, checkPermission: any, logError: any, saveFile: any
) => {
  const router = Router();

  // GET /compliance
  router.get('/', authenticate, asyncHandler(async (req: any, res: any) => {
    const { source_type, compliance_status, search } = req.query as any;
    const data = await ComplianceService.getAll({ source_type, compliance_status, search });
    res.json({ success: true, data });
  }));

  // GET /compliance/summary
  router.get('/summary', authenticate, asyncHandler(async (_req: any, res: any) => {
    const data = await ComplianceService.getSummary();
    res.json({ success: true, data });
  }));

  // GET /compliance/:id
  router.get('/:id', authenticate, asyncHandler(async (req: any, res: any) => {
    const data = await ComplianceService.getById(req.params.id);
    res.json({ success: true, data });
  }));

  // POST /compliance
  router.post('/', authenticate, checkPermission('ComplianceMatrix', 'Create'),
    asyncHandler(async (req: any, res: any) => {
      const body = { ...req.body };
      
      // Handle file upload
      if (req.files && req.files.attachment) {
        const file = Array.isArray(req.files.attachment) ? req.files.attachment[0] : req.files.attachment;
        body.attachment_path = await saveFile(file);
      }

      const parsed = itemSchema.safeParse(body);
      if (!parsed.success) throw new ValidationError('Invalid data', parsed.error.format());
      const result = await ComplianceService.create(parsed.data, req.user.id);
      res.status(201).json({ success: true, data: result });
    })
  );

  // PUT /compliance/:id
  router.put('/:id', authenticate, checkPermission('ComplianceMatrix', 'Edit'),
    asyncHandler(async (req: any, res: any) => {
      const body = { ...req.body };

      // Handle file upload
      if (req.files && req.files.attachment) {
        const file = Array.isArray(req.files.attachment) ? req.files.attachment[0] : req.files.attachment;
        body.attachment_path = await saveFile(file);
      }

      const parsed = itemSchema.partial().safeParse(body);
      if (!parsed.success) throw new ValidationError('Invalid data', parsed.error.format());
      await ComplianceService.update(req.params.id, parsed.data);
      res.json({ success: true });
    })
  );

  // PATCH /compliance/:id/status
  router.patch('/:id/status', authenticate, checkPermission('ComplianceMatrix', 'Edit'),
    asyncHandler(async (req: any, res: any) => {
      const { compliance_status } = req.body;
      const allowed = ['compliant', 'partial', 'non_compliant', 'under_review'];
      if (!allowed.includes(compliance_status)) {
        throw new ValidationError('Invalid status value');
      }
      await ComplianceService.update(req.params.id, { compliance_status });
      res.json({ success: true });
    })
  );

  // DELETE /compliance/:id
  router.delete('/:id', authenticate, checkPermission('ComplianceMatrix', 'Delete'),
    asyncHandler(async (req: any, res: any) => {
      await ComplianceService.softDelete(req.params.id);
      res.json({ success: true });
    })
  );

  return router;
};

import express from 'express';
import { z } from 'zod';
import { asyncHandler } from '../utils/asyncHandler';
import { CorrespondenceService } from '../services/CorrespondenceService';
import { AuthService } from '../services/AuthService';
import { ValidationError } from '../utils/errors';
import { parsePaginationParams } from '../utils/paginationService';

const incomingSchema = z.object({
  letter_number: z.string().min(1).max(100),
  sender_entity: z.string().min(1).max(255),
  sender_entity_type: z.string().optional(),
  subject: z.string().min(1).max(500),
  letter_date: z.string().min(1),
  receipt_date: z.string().min(1),
  classification: z.string().optional(),
  priority: z.string().optional(),
  method: z.string().optional(),
  receiving_dept_id: z.string().uuid().optional().nullable(),
  assigned_dept_id: z.string().uuid().optional().nullable(),
  assigned_user_id: z.string().uuid().optional().nullable(),
  follow_up_required: z.boolean().optional(),
  follow_up_date: z.string().optional().nullable(),
  response_required: z.boolean().optional(),
  response_due_date: z.string().optional().nullable(),
  notes: z.string().optional().nullable()
});

const outgoingSchema = z.object({
  letter_date: z.string().min(1),
  recipient_entity: z.string().min(1).max(255),
  subject: z.string().min(1).max(500),
  classification: z.string().optional(),
  sending_method: z.string().optional(),
  attachment_file: z.string().optional().nullable()
});

const referSchema = z.object({
  incoming_id: z.string().uuid(),
  to_dept_id: z.string().uuid(),
  to_user_id: z.string().uuid().optional().nullable(),
  notes: z.string().optional().nullable()
});

const linkSchema = z.object({
  incoming_id: z.string().uuid(),
  outgoing_id: z.string().uuid(),
  link_type: z.string().optional().default('Reply')
});

const statusUpdateSchema = z.object({
  new_status: z.string().min(1),
  notes: z.string().optional().nullable()
});

export const createCorrespondenceRoutes = (
  db: any,
  authenticate: any,
  checkPermission: any,
  logError: any,
  saveFile: any
) => {
  const router = express.Router();

  // 1. Incoming Correspondence
  router.get("/incoming", authenticate, checkPermission('Correspondence', 'View'), asyncHandler(async (req, res) => {
    const user = (req as any).user;
    const userContext = { userId: user.id, userRole: user.role, departmentId: user.department_id || null };
    const result = await CorrespondenceService.getIncoming(req.query, userContext);
    res.json(result);
  }));

  router.post("/incoming", authenticate, checkPermission('Correspondence', 'Create'), asyncHandler(async (req, res) => {
    const validation = incomingSchema.safeParse(req.body);
    if (!validation.success) {
      throw new ValidationError("Invalid incoming correspondence data", validation.error.format());
    }
    const userId = (req as any).user.id;
    const result = await CorrespondenceService.createIncoming(validation.data, userId);

    await AuthService.logAudit((req as any).user.username, "CREATE", "Correspondence", `Created incoming letter ${result.sequence_number}`);
    res.json(result);
  }));

  router.put("/incoming/:id", authenticate, checkPermission('Correspondence', 'Edit'), asyncHandler(async (req, res) => {
    const id = req.params.id as string;
    const validation = incomingSchema.partial().safeParse(req.body);
    if (!validation.success) {
      throw new ValidationError("Invalid incoming correspondence data", validation.error.format());
    }
    const user = (req as any).user;
    const userContext = { userId: user.id, userRole: user.role, departmentId: user.department_id || null };
    await CorrespondenceService.updateIncoming(id, validation.data, userContext);
    
    await AuthService.logAudit((req as any).user.username, "UPDATE", "Correspondence", `Updated incoming letter ID: ${id}`);
    res.json({ success: true });
  }));

  router.delete("/incoming/:id", authenticate, checkPermission('Correspondence', 'Delete'), asyncHandler(async (req, res) => {
    const id = req.params.id as string;
    const user = (req as any).user;
    const userContext = { userId: user.id, userRole: user.role, departmentId: user.department_id || null };
    await CorrespondenceService.deleteIncoming(id, userContext);
    
    await AuthService.logAudit((req as any).user.username, "DELETE", "Correspondence", `Deleted incoming letter ID: ${id}`);
    res.json({ success: true });
  }));

  // 2. Status History and Updates
  router.put("/status/:type/:id", authenticate, checkPermission('Correspondence', 'Edit'), asyncHandler(async (req, res) => {
    const type = req.params.type as string;
    const id = req.params.id as string;
    const validation = statusUpdateSchema.safeParse(req.body);
    if (!validation.success) {
      throw new ValidationError("Invalid status update data", validation.error.format());
    }
    const { new_status, notes } = validation.data;
    const user = (req as any).user;
    const userId = user.id;
    const userContext = { userId: user.id, userRole: user.role, departmentId: user.department_id || null };
    
    const result = await CorrespondenceService.updateStatus(type, id, new_status, notes || '', userId, userContext);

    await AuthService.logAudit((req as any).user.username, "UPDATE_STATUS", "Correspondence", `Changed ${type} ${id} status from ${result.oldStatus} to ${new_status}`);
    res.json({ success: true });
  }));

  // 4. Referrals
  router.post("/refer", authenticate, checkPermission('Correspondence', 'Edit'), asyncHandler(async (req, res) => {
    const validation = referSchema.safeParse(req.body);
    if (!validation.success) {
      throw new ValidationError("Invalid referral data", validation.error.format());
    }
    const user = (req as any).user;
    const userId = user.id;
    const userContext = { userId: user.id, userRole: user.role, departmentId: user.department_id || null };
    await CorrespondenceService.refer(validation.data, userId, userContext);

    await AuthService.logAudit((req as any).user.username, "REFER", "Correspondence", `Referred incoming letter ${validation.data.incoming_id} to dept ${validation.data.to_dept_id}`);
    res.json({ success: true });
  }));

  // 5. Linking
  router.post("/link", authenticate, checkPermission('Correspondence', 'Edit'), asyncHandler(async (req, res) => {
    const validation = linkSchema.safeParse(req.body);
    if (!validation.success) {
      throw new ValidationError("Invalid link data", validation.error.format());
    }
    const user = (req as any).user;
    const userId = user.id;
    const userContext = { userId: user.id, userRole: user.role, departmentId: user.department_id || null };
    await CorrespondenceService.link(validation.data, userId, userContext);
    
    await AuthService.logAudit((req as any).user.username, "LINK", "Correspondence", `Linked incoming ${validation.data.incoming_id} with outgoing ${validation.data.outgoing_id}`);
    res.json({ success: true });
  }));

  // 6. Archiving
  router.put("/archive/:type/:id", authenticate, checkPermission('Correspondence', 'Edit'), asyncHandler(async (req, res) => {
    const type = req.params.type as string;
    const id = req.params.id as string;
    const user = (req as any).user;
    const userContext = { userId: user.id, userRole: user.role, departmentId: user.department_id || null };
    await CorrespondenceService.archive(type, id, userContext);
    
    await AuthService.logAudit((req as any).user.username, "ARCHIVE", "Correspondence", `Archived ${type} ${id}`);
    res.json({ success: true });
  }));

  // 6.1 Archive List (Unified & Paginated)
  router.get("/archive", authenticate, checkPermission('Correspondence', 'View'), asyncHandler(async (req, res) => {
    const user = (req as any).user;
    const userContext = { userId: user.id, userRole: user.role, departmentId: user.department_id || null };
    const result = await CorrespondenceService.getArchive(req.query, userContext);
    res.json(result);
  }));

  // 7. Attachments
  router.get("/attachments/:type/:id", authenticate, checkPermission('Correspondence', 'View'), asyncHandler(async (req, res) => {
    const type = req.params.type as string;
    const id = req.params.id as string;
    const user = (req as any).user;
    const userContext = { userId: user.id, userRole: user.role, departmentId: user.department_id || null };
    const data = await CorrespondenceService.getAttachments(type, id, userContext);
    res.json(data);
  }));

  router.post("/attachments", authenticate, checkPermission('Correspondence', 'Edit'), asyncHandler(async (req, res) => {
    const user = (req as any).user;
    const userId = user.id;
    const userContext = { userId: user.id, userRole: user.role, departmentId: user.department_id || null };
    await CorrespondenceService.addAttachment(req.body, userId, userContext);
    
    await AuthService.logAudit((req as any).user.username, "UPLOAD", "Correspondence", `Uploaded attachment for ${req.body.correspondence_type} ${req.body.correspondence_id}`);
    res.json({ success: true });
  }));

  // 8. Stats for Dashboard
  router.get("/stats", authenticate, checkPermission('Correspondence', 'View'), asyncHandler(async (req, res) => {
    const user = (req as any).user;
    const userContext = { userId: user.id, userRole: user.role, departmentId: user.department_id || null };
    const stats = await CorrespondenceService.getStats(userContext);
    res.json(stats);
  }));

  // 9. Details (Unified)
  router.get("/details/:type/:id", authenticate, checkPermission('Correspondence', 'View'), asyncHandler(async (req, res) => {
    const type = req.params.type as string;
    const id = req.params.id as string;
    const user = (req as any).user;
    const userContext = { userId: user.id, userRole: user.role, departmentId: user.department_id || null };
    const details = await CorrespondenceService.getDetails(type, id, userContext);
    res.json(details);
  }));

  // Outgoing Letters Routes
  router.get("/outgoing", authenticate, checkPermission('Correspondence', 'View'), asyncHandler(async (req, res) => {
    const { page, pageSize } = parsePaginationParams(req.query as Record<string, any>);
    const user = (req as any).user;
    const userContext = { userId: user.id, userRole: user.role, departmentId: user.department_id || null };
    const result = await CorrespondenceService.getOutgoing(page, pageSize, userContext);
    res.json(result);
  }));

  router.post("/outgoing", authenticate, checkPermission('Correspondence', 'Create'), asyncHandler(async (req, res) => {
    const typedReq = req as unknown as any;
    const body = { ...typedReq.body };
    const userId = typedReq.user.id;
    const username = typedReq.user.username;
    
    // Handle file upload if present
    const files = typedReq.files;
    if (files && files.attachment_file) {
      const fileOrFiles = files.attachment_file;
      const file = Array.isArray(fileOrFiles) ? fileOrFiles[0] : fileOrFiles;
      body.attachment_file = await saveFile(file);
    }

    const validation = outgoingSchema.safeParse(body);
    if (!validation.success) {
      throw new ValidationError("Invalid outgoing correspondence data", validation.error.format());
    }
    
    const result = await CorrespondenceService.createOutgoing(validation.data, userId);
    
    await AuthService.logAudit(username, "Create", "Outgoing Letters", `Created letter: ${result.sequence_number}`);
        
    res.json(result);
  }));

  router.put("/outgoing/:id", authenticate, checkPermission('Correspondence', 'Edit'), asyncHandler(async (req, res) => {
    const typedReq = req as unknown as any;
    const id = typedReq.params.id as string;
    const body = { ...typedReq.body };
    const username = typedReq.user.username;
    const userContext = { userId: typedReq.user.id, userRole: typedReq.user.role, departmentId: typedReq.user.department_id || null };
    
    const files = typedReq.files;
    if (files && files.attachment_file) {
      const fileOrFiles = files.attachment_file;
      const file = Array.isArray(fileOrFiles) ? fileOrFiles[0] : fileOrFiles;
      body.attachment_file = await saveFile(file);
    }

    const validation = outgoingSchema.partial().safeParse(body);
    if (!validation.success) {
      throw new ValidationError("Invalid outgoing correspondence data", validation.error.format());
    }
    
    await CorrespondenceService.updateOutgoing(id, validation.data, userContext);
    
    await AuthService.logAudit(username, "Update", "Outgoing Letters", `Updated letter ID: ${id}`);
        
    res.json({ success: true });
  }));

  router.delete("/outgoing/:id", authenticate, checkPermission('Correspondence', 'Delete'), asyncHandler(async (req, res) => {
    const typedReq = req as unknown as any;
    const id = typedReq.params.id as string;
    const username = typedReq.user.username;
    const userContext = { userId: typedReq.user.id, userRole: typedReq.user.role, departmentId: typedReq.user.department_id || null };
    
    await CorrespondenceService.deleteOutgoing(id, userContext);
    
    await AuthService.logAudit(username, "Delete", "Outgoing Letters", `Deleted letter ID: ${id}`);
        
    res.json({ success: true });
  }));

  return router;
};

