/**
 * File Routes
 *
 * POST /api/files/upload - Upload a file to object storage via temp bucket.
 * GET /api/files/:fileId/download - Download a file via presigned URL redirect.
 *
 * Accepts multipart file upload, validates with file-validation module,
 * streams to temp bucket, computes SHA-256, creates FileRecord,
 * enqueues process-file job, returns 202 Accepted with jobId.
 *
 * Requirements: 1.1, 1.2, 1.3, 1.4, 1.5, 1.6, 1.7, 1.8, 3.1, 3.2, 3.4, 3.5, 3.6, 11.5
 */

import { Router, Request, Response } from 'express';
import crypto from 'crypto';
import { v4 as uuidv4 } from 'uuid';
import { asyncHandler } from '../utils/asyncHandler';
import { validateFile } from '../utils/file-validation';
import { StorageService, UploadTimeoutError } from '../services/storage.service';
import { QueueService } from '../services/queue.service';
import { generateStorageKey, type EntityRef } from '../utils/storage-key';
import { AuthService } from '../services/AuthService';
import { db } from '../db/index';
import logger from '../utils/logger';
import type { BucketName, FileStatus } from '../../models/file-record.model';
import { ADMIN_ROLES } from '../../constants';

// ─── Types ───────────────────────────────────────────────────────────────────

interface UploadRequestBody {
  entityType?: string;
  entityId?: string;
}

// ─── Route Factory ───────────────────────────────────────────────────────────

export function createFileRoutes(
  authenticate: any,
  storageService: StorageService,
  queueService: QueueService,
  logError: any,
) {
  const router = Router();

  /**
   * POST /upload
   *
   * Accepts a multipart file upload. Validates the file, streams to the
   * MinIO temp bucket, computes SHA-256 checksum, creates a FileRecord,
   * and enqueues a process-file background job.
   *
   * Returns 202 Accepted with { jobId, fileId }.
   * Returns 400 for validation failures.
   * Returns 503 if MinIO is unreachable.
   */
  router.post('/upload', authenticate, asyncHandler(async (req: Request, res: Response) => {
    const userId = (req as any).user.id as string;
    const username = (req as any).user.username as string;

    // ── 1. Check for uploaded file ─────────────────────────────────────────
    const files = (req as any).files;
    if (!files || !files.file) {
      return res.status(400).json({
        success: false,
        error: { code: 'NO_FILE', message: 'No file provided. Upload a file with field name "file".' },
      });
    }

    const uploadedFile = files.file;

    // Reject multiple files (array means multiple were uploaded)
    if (Array.isArray(uploadedFile)) {
      return res.status(400).json({
        success: false,
        error: { code: 'MULTIPLE_FILES', message: 'Only a single file upload is supported.' },
      });
    }

    // ── 2. Parse request body for entity association ───────────────────────
    const body: UploadRequestBody = req.body || {};
    const entityType = body.entityType as string | undefined;
    const entityId = body.entityId as string | undefined;

    // Determine the target bucket based on entity type
    const targetBucket: BucketName = resolveTargetBucket(entityType);

    // ── 3. Validate file using the file-validation module ──────────────────
    const validationResult = await validateFile({
      buffer: uploadedFile.data,
      filename: uploadedFile.name,
      declaredContentType: uploadedFile.mimetype,
      bucket: targetBucket,
    });

    if (!validationResult.valid) {
      await logAuditTrail(username, 'UPLOAD', 'Files', null, 'failure', validationResult.errors.map(e => e.message).join('; '));
      return res.status(400).json({
        success: false,
        error: {
          code: 'VALIDATION_FAILED',
          message: 'File validation failed.',
          details: validationResult.errors,
        },
      });
    }

    // ── 4. Compute SHA-256 checksum ────────────────────────────────────────
    const checksum = crypto
      .createHash('sha256')
      .update(uploadedFile.data)
      .digest('hex');

    // ── 5. Generate storage key ────────────────────────────────────────────
    const entityRef: EntityRef | undefined = (entityType && entityId)
      ? { type: entityType as EntityRef['type'], id: entityId }
      : undefined;

    // Use a default entity ref for unassociated uploads
    const effectiveEntityRef: EntityRef = entityRef ?? { type: 'audit', id: 'unassociated' };
    const storageKey = generateStorageKey(effectiveEntityRef, uploadedFile.name);
    const tempKey = `pending/${storageKey}`;

    // ── 6. Stream file to temp bucket ──────────────────────────────────────
    try {
      await storageService.upload({
        key: tempKey,
        body: uploadedFile.data,
        contentType: validationResult.detectedMimeType || uploadedFile.mimetype,
        bucket: 'temp',
        metadata: { checksum, uploadedBy: userId },
      });
    } catch (error: any) {
      // If upload timed out (Requirement 9.4): update FileRecord to failed
      if (error instanceof UploadTimeoutError) {
        logger.error('[FileUpload] Upload timed out, marking file as failed', {
          key: tempKey,
          timeoutMs: error.timeoutMs,
        });
        await logAuditTrail(username, 'UPLOAD', 'Files', null, 'failure', `Upload timed out after ${error.timeoutMs}ms`);
        return res.status(408).json({
          success: false,
          error: {
            code: 'UPLOAD_TIMEOUT',
            message: `File upload exceeded the maximum allowed time (${error.timeoutMs / 1000}s). Please try again with a smaller file or better connection.`,
          },
        });
      }

      // If MinIO is unreachable, return 503
      if (isStorageUnavailableError(error)) {
        logger.error('[FileUpload] MinIO unreachable during upload', { error: error.message });
        await logAuditTrail(username, 'UPLOAD', 'Files', null, 'failure', 'Storage temporarily unavailable');
        return res.status(503).json({
          success: false,
          error: {
            code: 'STORAGE_UNAVAILABLE',
            message: 'Storage is temporarily unavailable. Please retry your upload.',
          },
        });
      }
      throw error;
    }

    // ── 7. Create FileRecord in PostgreSQL ─────────────────────────────────
    const fileId = uuidv4();
    const now = new Date();
    const sanitizedName = sanitizeOriginalName(uploadedFile.name);
    const contentType = validationResult.detectedMimeType || uploadedFile.mimetype;
    const fileSize = uploadedFile.data.length;

    await db.prepare(`
      INSERT INTO files (id, original_name, storage_key, bucket, content_type, size, checksum, uploaded_by, associated_entity, associated_entity_type, status, created_at, updated_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).run(
      fileId,
      sanitizedName,
      storageKey,
      targetBucket,
      contentType,
      fileSize,
      checksum,
      userId,
      entityId || null,
      entityType || null,
      'uploading' satisfies FileStatus,
      now.toISOString(),
      now.toISOString(),
    );

    // ── 8. Enqueue process-file job ────────────────────────────────────────
    const jobRef = await queueService.enqueue('process-file', {
      tempKey,
      targetBucket,
      metadata: {
        fileId,
        storageKey,
        checksum,
        contentType,
      },
    }, {
      attempts: 3,
      backoff: { type: 'exponential', delay: 2000 },
    });

    // ── 9. Log to audit trail ──────────────────────────────────────────────
    await logAuditTrail(username, 'UPLOAD', 'Files', fileId, 'success', `Uploaded file: ${sanitizedName}`);

    // ── 10. Return 202 Accepted ────────────────────────────────────────────
    logger.info('[FileUpload] File accepted for processing', {
      fileId,
      jobId: jobRef.jobId,
      filename: sanitizedName,
      size: fileSize,
    });

    return res.status(202).json({
      success: true,
      message: 'File accepted for processing',
      jobId: jobRef.jobId,
      fileId,
    });
  }));

  /**
   * GET /:fileId/download
   *
   * Downloads a file by generating a presigned URL and redirecting (302).
   * Only files with status 'ready' can be downloaded.
   *
   * Returns 302 redirect to presigned URL on success.
   * Returns 404 if file not found or not ready.
   * Returns 403 if user not authorized to access this file.
   *
   * Requirements: 3.1, 3.2, 3.4, 3.5, 3.6, 11.5
   */
  router.get('/:fileId/download', authenticate, asyncHandler(async (req: Request, res: Response) => {
    const userId = (req as any).user.id as string;
    const username = (req as any).user.username as string;
    const userRole = (req as any).user.role as string;
    const fileId = req.params.fileId;

    // ── 1. Look up FileRecord by fileId ────────────────────────────────────
    const fileRecord = await db.prepare(`
      SELECT id, original_name, storage_key, bucket, content_type, size, checksum, uploaded_by, associated_entity, associated_entity_type, status, created_at, updated_at
      FROM files WHERE id = ?
    `).get(fileId) as any;

    // ── 2. If not found: return 404 ────────────────────────────────────────
    if (!fileRecord) {
      await logAuditTrail(username, 'DOWNLOAD', 'Files', fileId, 'failure', 'File not found');
      return res.status(404).json({
        success: false,
        error: { code: 'FILE_NOT_FOUND', message: 'File not found.' },
      });
    }

    // ── 3. If status !== 'ready': return 404 ───────────────────────────────
    if (fileRecord.status !== 'ready') {
      await logAuditTrail(username, 'DOWNLOAD', 'Files', fileId, 'failure', `File not available for download (status: ${fileRecord.status})`);
      return res.status(404).json({
        success: false,
        error: { code: 'FILE_NOT_AVAILABLE', message: 'File not available for download.' },
      });
    }

    // ── 4. Authorization: file belongs to user or user has admin role ──────
    const isOwner = fileRecord.uploaded_by === userId;
    const isAdmin = ADMIN_ROLES.includes(userRole as any);

    if (!isOwner && !isAdmin) {
      await logAuditTrail(username, 'DOWNLOAD', 'Files', fileId, 'failure', 'Insufficient permissions');
      return res.status(403).json({
        success: false,
        error: { code: 'FORBIDDEN', message: 'Insufficient permissions to access this file.' },
      });
    }

    // ── 5. Generate presigned URL ──────────────────────────────────────────
    const presignedUrl = await storageService.getPresignedUrl(
      fileRecord.storage_key,
      fileRecord.bucket as BucketName,
      3600,
    );

    // ── 6. Log download to audit trail ─────────────────────────────────────
    await logAuditTrail(username, 'DOWNLOAD', 'Files', fileId, 'success', `Downloaded file: ${fileRecord.original_name}`);

    logger.info('[FileDownload] Presigned URL generated', {
      fileId,
      userId,
      filename: fileRecord.original_name,
    });

    // ── 7. Redirect 302 to presigned URL ───────────────────────────────────
    return res.redirect(302, presignedUrl);
  }));

  return router;
}

// ─── Helper Functions ────────────────────────────────────────────────────────

/**
 * Resolves the target bucket based on entity type.
 * Defaults to 'evidence' for most upload scenarios.
 */
function resolveTargetBucket(entityType?: string): BucketName {
  if (entityType === 'report') return 'reports';
  return 'evidence';
}

/**
 * Sanitizes the original filename for storage in the database.
 * Removes path separators and null bytes, trims to 255 chars.
 */
function sanitizeOriginalName(filename: string): string {
  let sanitized = filename;
  sanitized = sanitized.replace(/\0/g, '');
  sanitized = sanitized.replace(/\\/g, '');
  sanitized = sanitized.replace(/\//g, '');
  if (sanitized.length > 255) {
    sanitized = sanitized.slice(0, 255);
  }
  return sanitized;
}

/**
 * Determines if an error indicates that MinIO/storage is unreachable.
 */
function isStorageUnavailableError(error: any): boolean {
  if (!error) return false;
  const message = (error.message || '').toLowerCase();
  const code = (error.code || '').toLowerCase();
  const name = (error.name || '').toLowerCase();

  return (
    code === 'econnrefused' ||
    code === 'econnreset' ||
    code === 'etimedout' ||
    code === 'enotfound' ||
    name === 'networkingerror' ||
    message.includes('connect econnrefused') ||
    message.includes('network') ||
    message.includes('socket hang up') ||
    message.includes('timeout') ||
    message.includes('unreachable')
  );
}

/**
 * Logs a file operation to the audit trail.
 * Requirement: 11.5
 */
async function logAuditTrail(
  username: string,
  operation: string,
  module: string,
  fileId: string | null,
  outcome: 'success' | 'failure',
  details: string,
): Promise<void> {
  try {
    const logDetails = fileId
      ? `[${outcome}] File ${fileId}: ${details}`
      : `[${outcome}] ${details}`;
    await AuthService.logAudit(username, operation, module, logDetails);
  } catch (error) {
    // Don't let audit logging failures break the main flow
    logger.error('[FileUpload] Failed to log audit trail', { error, operation, fileId });
  }
}

import { Router } from "express";
import { z } from "zod";
import { AuthenticatedRequest } from "../types";
import { FraudService } from "../services/FraudService";
import { AuthService } from "../services/AuthService";
import { asyncHandler } from "../utils/asyncHandler";
import { ValidationError } from "../utils/errors";
import { UserRole } from "../../constants";

const fraudRequestSchema = z.object({
  reason: z.string().min(5).max(1000),
});

const fraudApproveSchema = z.object({
  duration: z.coerce.number().int().positive().max(365),
});

const fraudRejectSchema = z.object({
  reason: z.string().min(5).max(1000),
});

export const createFraudRoutes = (db: any, authenticate: any, checkPermission: any, logError: any, createNotification: any) => {
  const router = Router();

  router.post("/", authenticate, asyncHandler(async (req, res) => {
    const typedReq = req as unknown as AuthenticatedRequest;
    const validation = fraudRequestSchema.safeParse(typedReq.body);
    if (!validation.success) {
      throw new ValidationError("Invalid request data", validation.error.format());
    }
    const { reason } = validation.data;
    const userId = typedReq.user.id;
    const userName = typedReq.user.username;

    const requestId = await FraudService.createRequest(userId, userName, reason);

    // Notify Admins/Managers in Parallel (Fixing Sequential Awaiting Delay)
    const admins = await db.prepare(`SELECT id FROM users WHERE role IN ('${UserRole.ADMIN}', '${UserRole.MANAGER}')`).all() as { id: number }[];
    
    await Promise.all(
      admins.map(admin => 
        createNotification(admin.id, "access_requested", `${userName} requested access to Fraud Log`, "Fraud Log", "/fraud-log", { actorId: userId, wss: (req.app as any).wss })
      )
    );

    // Using AuthService directly since it's correctly mapped or we can use BaseService later
    await AuthService.logAudit(userName, "Request Access", "Fraud Log", "User requested access to Fraud Log");

    res.json({ success: true, id: requestId });
  }));

  router.get("/", authenticate, asyncHandler(async (req, res) => {
    const typedReq = req as unknown as AuthenticatedRequest;
    const requests = await FraudService.getRequests(typedReq.user);
    res.json(requests);
  }));

  router.get("/my-status", authenticate, asyncHandler(async (req, res) => {
    const typedReq = req as unknown as AuthenticatedRequest;
    const status = await FraudService.getMyStatus(typedReq.user.id);
    res.json(status);
  }));

  router.put("/:id/approve", authenticate, checkPermission('IntegrityManagement', 'Approve'), asyncHandler(async (req, res) => {
    const typedReq = req as unknown as AuthenticatedRequest;
    const id = req.params.id as string;
    const validation = fraudApproveSchema.safeParse(typedReq.body);
    if (!validation.success) {
      throw new ValidationError("Invalid duration", validation.error.format());
    }
    const { duration } = validation.data;
    const responderId = typedReq.user.id;
    
    const request = await FraudService.approveRequest(id, duration, responderId);

    // Notify User
    await createNotification(request.user_id, "access_approved", "Your access request to Fraud Log has been approved.", "Fraud Log", "/fraud-log", { actorId: typedReq.user.id, wss: (req.app as any).wss });

    await AuthService.logAudit(typedReq.user.username, "Approve Access", "Fraud Log", `Approved access for user ID ${request.user_id} for ${duration} days`);

    res.json({ success: true });
  }));

  router.put("/:id/reject", authenticate, checkPermission('IntegrityManagement', 'Approve'), asyncHandler(async (req, res) => {
    const typedReq = req as unknown as AuthenticatedRequest;
    const id = req.params.id as string;
    const validation = fraudRejectSchema.safeParse(typedReq.body);
    if (!validation.success) {
      throw new ValidationError("Invalid reject reason", validation.error.format());
    }
    const { reason } = validation.data;
    const responderId = typedReq.user.id;

    const request = await FraudService.rejectRequest(id, reason, responderId);

    // Notify User
    await createNotification(request.user_id, "access_rejected", `Your access request to Fraud Log was rejected: ${reason}`, "Fraud Log", "/fraud-log", { actorId: typedReq.user.id, wss: (req.app as any).wss });

    await AuthService.logAudit(typedReq.user.username, "Reject Access", "Fraud Log", `Rejected access for user ID ${request.user_id}`);

    res.json({ success: true });
  }));

  return router;
};

import { Router, Request, Response } from 'express';
import fs from 'fs';
import path from 'path';
import { db } from '../db/index';
import { HealthStatus, SubsystemCheck } from '../types/api';
import { QueueService, type QueueHealth } from '../services/queue.service.js';

/**
 * Cron status tracker.
 * Updated by the cron module after each successful run.
 * The expected interval is 24 hours (daily cron).
 */
let cronLastRunTimestamp: string | null = null;
const CRON_EXPECTED_INTERVAL_MS = 25 * 60 * 60 * 1000; // 25 hours (24h + 1h grace)

export function updateCronLastRun(): void {
  cronLastRunTimestamp = new Date().toISOString();
}

export function getCronLastRun(): string | null {
  return cronLastRunTimestamp;
}

/**
 * Individual check timeout (2 seconds).
 */
const CHECK_TIMEOUT_MS = 2000;

/**
 * Overall response timeout (3 seconds).
 */
const OVERALL_TIMEOUT_MS = 3000;

/**
 * Wraps a check function with an independent 2-second timeout.
 * Returns the SubsystemCheck result with latency measured regardless of outcome.
 */
async function withTimeout(
  checkFn: () => Promise<SubsystemCheck>
): Promise<SubsystemCheck> {
  const start = Date.now();

  return new Promise<SubsystemCheck>((resolve) => {
    const timer = setTimeout(() => {
      resolve({
        status: 'timeout',
        latency: Date.now() - start,
        details: { reason: 'Check timed out after 2000ms' },
      });
    }, CHECK_TIMEOUT_MS);

    checkFn()
      .then((result) => {
        clearTimeout(timer);
        resolve(result);
      })
      .catch((err) => {
        clearTimeout(timer);
        resolve({
          status: 'fail',
          latency: Date.now() - start,
          details: { reason: err?.message || 'Unknown error' },
        });
      });
  });
}

/**
 * Check database connectivity by executing a simple query.
 */
async function checkDatabase(): Promise<SubsystemCheck> {
  const start = Date.now();
  await db.prepare('SELECT 1 AS health_check').get();
  return {
    status: 'ok',
    latency: Date.now() - start,
    details: {
      type: db.isExternal ? 'PostgreSQL' : 'PGlite',
    },
  };
}

/**
 * Check filesystem: uploads directory is writable and has at least 100MB free space.
 * Uses Node.js fs.statfs (available in Node 18.15+) for disk space.
 */
async function checkFilesystem(): Promise<SubsystemCheck> {
  const start = Date.now();
  const uploadDir = path.join(process.cwd(), 'uploads');

  // Check directory exists and is writable
  await fs.promises.access(uploadDir, fs.constants.W_OK);

  // Check free space (≥100MB)
  let freeSpaceMB: number | null = null;
  try {
    const stats = await fs.promises.statfs(uploadDir);
    const freeBytes = stats.bfree * stats.bsize;
    freeSpaceMB = Math.round(freeBytes / (1024 * 1024));

    if (freeSpaceMB < 100) {
      return {
        status: 'fail',
        latency: Date.now() - start,
        details: { freeSpaceMB, reason: 'Less than 100MB free space' },
      };
    }
  } catch {
    // statfs may not be available on all platforms; if writable, consider it ok
    freeSpaceMB = null;
  }

  return {
    status: 'ok',
    latency: Date.now() - start,
    details: { writable: true, ...(freeSpaceMB !== null && { freeSpaceMB }) },
  };
}

/**
 * Check memory usage: heap used should be less than 90% of heap total.
 */
async function checkMemory(): Promise<SubsystemCheck> {
  const start = Date.now();
  const mem = process.memoryUsage();
  const heapUsedMB = Math.round(mem.heapUsed / (1024 * 1024));
  const heapTotalMB = Math.round(mem.heapTotal / (1024 * 1024));
  const usagePercent = (mem.heapUsed / mem.heapTotal) * 100;

  if (usagePercent >= 90) {
    return {
      status: 'fail',
      latency: Date.now() - start,
      details: {
        heapUsedMB,
        heapTotalMB,
        usagePercent: Math.round(usagePercent),
        reason: 'Heap usage exceeds 90% threshold',
      },
    };
  }

  return {
    status: 'ok',
    latency: Date.now() - start,
    details: { heapUsedMB, heapTotalMB, usagePercent: Math.round(usagePercent) },
  };
}

/**
 * Check WebSocket server: verify it's accepting connections.
 * Accesses the wss instance from the Express app.
 */
async function checkWebSocket(req: Request): Promise<SubsystemCheck> {
  const start = Date.now();
  const wss = (req.app as any).wss;

  if (!wss) {
    return {
      status: 'fail',
      latency: Date.now() - start,
      details: { reason: 'WebSocket server not initialized' },
    };
  }

  // Check that the WSS is in a state that accepts connections
  // WebSocketServer doesn't have a "closed" property, but we can check
  // if it has the clients Set (indicating it's operational)
  const clientCount = wss.clients ? wss.clients.size : 0;

  return {
    status: 'ok',
    latency: Date.now() - start,
    details: { connections: clientCount },
  };
}

/**
 * Check cron status: verify the last scheduled execution completed within the expected interval.
 */
async function checkCron(): Promise<SubsystemCheck> {
  const start = Date.now();
  const lastRun = getCronLastRun();

  if (!lastRun) {
    // If cron has never run, it might be a fresh start - check if server just started
    const uptimeSeconds = process.uptime();
    // If server has been up for less than the expected interval, it's ok (cron hasn't had a chance to run yet)
    if (uptimeSeconds < CRON_EXPECTED_INTERVAL_MS / 1000) {
      return {
        status: 'ok',
        latency: Date.now() - start,
        details: { lastRun: null, note: 'Server recently started, cron not yet due' },
      };
    }

    return {
      status: 'fail',
      latency: Date.now() - start,
      details: { lastRun: null, reason: 'Cron has never run and server uptime exceeds expected interval' },
    };
  }

  const lastRunTime = new Date(lastRun).getTime();
  const elapsed = Date.now() - lastRunTime;

  if (elapsed > CRON_EXPECTED_INTERVAL_MS) {
    return {
      status: 'fail',
      latency: Date.now() - start,
      details: {
        lastRun,
        elapsedMs: elapsed,
        reason: 'Last cron run exceeds expected interval',
      },
    };
  }

  return {
    status: 'ok',
    latency: Date.now() - start,
    details: { lastRun },
  };
}

/**
 * Derive overall health status from individual check results.
 * - "unhealthy" (503) if database fails
 * - "degraded" (200) if any non-database check fails
 * - "healthy" (200) if all pass
 */
function deriveOverallStatus(checks: HealthStatus['checks']): HealthStatus['status'] {
  if (checks.database.status !== 'ok') {
    return 'unhealthy';
  }

  const nonDbChecks = [checks.filesystem, checks.memory, checks.websocket, checks.cron];
  const anyNonDbFailed = nonDbChecks.some((c) => c.status !== 'ok');

  if (anyNonDbFailed) {
    return 'degraded';
  }

  return 'healthy';
}

/**
 * Creates the enhanced health check router.
 * Optionally accepts a QueueService instance for the /health/queue endpoint.
 */
export function createHealthRouter(queueService?: QueueService): Router {
  const router = Router();

  /**
   * GET /health/queue
   * Returns queue health metrics: connected, waiting, active, completed, failed, delayed, workers.
   * Always returns 200 — monitoring tools can check the `connected` field to detect issues.
   * Requirements: 8.1
   */
  router.get('/health/queue', async (_req: Request, res: Response) => {
    if (!queueService) {
      // QueueService not yet wired — return a disconnected response
      const health: QueueHealth = {
        connected: false,
        waiting: 0,
        active: 0,
        completed: 0,
        failed: 0,
        delayed: 0,
        workers: 0,
      };
      return res.status(200).json(health);
    }

    try {
      const health = await queueService.getQueueHealth();
      return res.status(200).json(health);
    } catch {
      // If Redis is unreachable or an error occurs, still return 200 with connected=false
      const health: QueueHealth = {
        connected: false,
        waiting: 0,
        active: 0,
        completed: 0,
        failed: 0,
        delayed: 0,
        workers: 0,
      };
      return res.status(200).json(health);
    }
  });

  router.get('/health', async (req: Request, res: Response) => {
    // Overall timeout: respond within 3 seconds regardless
    const overallStart = Date.now();

    const overallTimeout = new Promise<null>((resolve) => {
      setTimeout(() => resolve(null), OVERALL_TIMEOUT_MS);
    });

    const checksPromise = (async () => {
      // Run all checks in parallel with independent timeouts
      const [database, filesystem, memory, websocket, cron] = await Promise.all([
        withTimeout(checkDatabase),
        withTimeout(checkFilesystem),
        withTimeout(checkMemory),
        withTimeout(() => checkWebSocket(req)),
        withTimeout(checkCron),
      ]);

      return { database, filesystem, memory, websocket, cron };
    })();

    // Race between checks completing and overall timeout
    const checks = await Promise.race([checksPromise, overallTimeout]);

    // If overall timeout hit, return partial results
    const finalChecks: HealthStatus['checks'] = checks || {
      database: { status: 'timeout', latency: OVERALL_TIMEOUT_MS, details: { reason: 'Overall timeout' } },
      filesystem: { status: 'timeout', latency: OVERALL_TIMEOUT_MS, details: { reason: 'Overall timeout' } },
      memory: { status: 'timeout', latency: OVERALL_TIMEOUT_MS, details: { reason: 'Overall timeout' } },
      websocket: { status: 'timeout', latency: OVERALL_TIMEOUT_MS, details: { reason: 'Overall timeout' } },
      cron: { status: 'timeout', latency: OVERALL_TIMEOUT_MS, details: { reason: 'Overall timeout' } },
    };

    const status = deriveOverallStatus(finalChecks);
    const httpStatus = status === 'unhealthy' ? 503 : 200;

    const response: HealthStatus = {
      status,
      checks: finalChecks,
      uptime: process.uptime(),
      version: '1.0',
    };

    res.status(httpStatus).json(response);
  });

  return router;
}

import express from "express";
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import { db } from "../db/index";
import { createAuthMiddlewares } from "../middleware/auth";
import { createAuthRoutes } from "./auth";
import { createUserRoutes } from "./users";
import { createRoleRoutes } from "./roles";
import { createJobTitleRoutes } from "./jobTitles";
import { createSessionRoutes } from "./sessions";
import { createLogRoutes } from "./logs";
import { createSettingsRoutes } from "./settings";
import { createPdfTemplatesRoutes } from "./pdfTemplates";
import { createProfileRoutes } from "./profile";
import { createDashboardRoutes } from "./dashboard";
import { createCorrespondenceRoutes } from "./correspondence";
import { createOrgEntitiesRoutes } from "./orgEntities";
import { createCoiRoutes } from "./coi";
import { createPoliciesRoutes } from "./policies";
import { createAppSettingsRoutes } from "./appSettings";
import { createExecutiveReportsRoutes } from "./executiveReports";
import { createDepartmentRoutes } from "./departments";
import { createCrudRoutes } from "../utils/crudGenerator";
import { createAnalyticsRoutes } from "./analytics";
import { createIntegrityRoutes } from "./integrity";
import { createAuditProgramRoutes } from "./auditPrograms";
import { createFraudRoutes } from "./fraud";
import { createComplianceRoutes } from "./compliance";
import { createNotificationRoutes } from "./notifications";
import { createCommentRoutes } from "./comments";
import { createAuditTaskRoutes } from "./auditTasks";
import { createRecommendationRoutes } from "./recommendations";
import { createAuditFindingRoutes } from "./auditFindings";
import { NotificationService } from "../services/NotificationService";
import { logDuplicateRoutes, registerRoutes } from "../utils/routeRegistry";
import { createHealthRouter } from "./health";
import { createBulkRoutes } from "./bulk";
import { createAdminBackupRoutes } from "./adminBackup";
import { createPermissionAdminRoutes } from "./permissionAdmin";
import { createArchiveRoutes } from "./archive";
import { createLookupRoutes } from "./lookups";
import { createIdempotencyMiddleware } from "../middleware/idempotency";
import { createJobRoutes } from "./jobs.routes";
import { getQueueService, isInfrastructureReady } from "../services/infrastructure";
import type { QueueService } from "../services/queue.service";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const createNotification = NotificationService.create.bind(NotificationService);

/**
 * Current supported API version.
 * Used for the X-API-Version header and version routing.
 */
export const CURRENT_API_VERSION = { major: 1, minor: 0 };
export const SUPPORTED_VERSIONS = [1];

export const setupRoutes = (
  app: express.Application,
  JWT_SECRET: string,
  JWT_PRIVATE_KEY: string,
  JWT_PUBLIC_KEY: string,
  saveFile: any,
  logError: any
) => {
  // API Version Header - set on all /api/ responses
  app.use('/api/', (req: any, res: any, next: any) => {
    res.setHeader('X-API-Version', `${CURRENT_API_VERSION.major}.${CURRENT_API_VERSION.minor}`);
    next();
  });

  // ─── Unsupported Version Handler ─────────────────────────────────────────
  // Intercept requests to /api/v{n}/ where n is not a supported version.
  // Must be registered BEFORE the fallback and versioned routes.
  app.use('/api/v:version', (req: any, res: any, next: any) => {
    const versionStr = req.params.version;
    // Extract just the numeric part (e.g., "2" from "2/something")
    const versionNum = parseInt(versionStr, 10);

    if (isNaN(versionNum) || versionNum < 1 || !Number.isInteger(Number(versionStr))) {
      return res.status(404).json({
        success: false,
        error: {
          code: 'VERSION_NOT_FOUND',
          message: `API version 'v${versionStr}' is not available. Supported versions: ${SUPPORTED_VERSIONS.map(v => `v${v}`).join(', ')}`,
        },
      });
    }

    if (!SUPPORTED_VERSIONS.includes(versionNum)) {
      return res.status(404).json({
        success: false,
        error: {
          code: 'VERSION_NOT_FOUND',
          message: `API version 'v${versionNum}' is not available. Supported versions: ${SUPPORTED_VERSIONS.map(v => `v${v}`).join(', ')}`,
        },
      });
    }

    // Supported version - continue to actual route handlers
    next();
  });

  // ─── Version Fallback ────────────────────────────────────────────────────
  // Requests to /api/{resource} (without version prefix) are rewritten to /api/v1/{resource}.
  // This ensures backward compatibility - existing clients using /api/resource still work.
  app.use('/api', (req: any, res: any, next: any) => {
    // If the path already starts with /v{n}/, let it pass through
    if (/^\/v\d+/.test(req.path)) {
      return next();
    }

    // Rewrite the URL to include the version prefix
    req.url = `/v${CURRENT_API_VERSION.major}${req.url === '/' ? '' : req.url}`;
    next();
  });

  // ─── Versioned Router (v1) ───────────────────────────────────────────────
  // All API routes are mounted under /api/v1/
  const v1Router = express.Router();

  // Auth Middleware
  const { authenticate, checkPermission, authorize, authLimiter } = createAuthMiddlewares(db, JWT_SECRET, JWT_PUBLIC_KEY);

  // Idempotency Middleware (applies to POST/PUT requests with X-Idempotency-Key header)
  // Must be after auth since it scopes keys per authenticated user
  v1Router.use(createIdempotencyMiddleware());

  // Health Check (enhanced - checks all subsystems)
  v1Router.use("/", createHealthRouter());

  // OpenAPI Specification
  v1Router.get("/docs", (req, res) => {
    try {
      const specPath = path.resolve(__dirname, '../../../docs/openapi.yaml');
      const spec = fs.readFileSync(specPath, 'utf-8');
      res.setHeader('Content-Type', 'text/yaml; charset=utf-8');
      res.send(spec);
    } catch (err) {
      res.status(404).json({ error: 'OpenAPI specification not found' });
    }
  });

  // Auth Routes
  v1Router.use("/auth", createAuthRoutes(db, JWT_SECRET, JWT_PRIVATE_KEY, authLimiter, authenticate, checkPermission, createNotification, logError));
  
  // Lookup Routes (simplified data for dropdowns in forms)
  // Must be registered BEFORE CRUD routes to prevent /:id pattern from matching "lookup"
  v1Router.use("/", createLookupRoutes(db, authenticate, checkPermission, logError));

  // Generic CRUD API Generator with Auth & Logging
  v1Router.use("/", createCrudRoutes(db, authenticate, checkPermission, logError, createNotification, saveFile));

  // Notification Routes
  v1Router.use("/notifications", createNotificationRoutes(db, authenticate));
  
  // Comments Routes
  v1Router.use("/comments", createCommentRoutes(db, authenticate, logError));

  // Modular Routes
  v1Router.use("/job-titles", createJobTitleRoutes(db, authenticate, checkPermission, logError));
  v1Router.use("/users", createUserRoutes(db, authenticate, authorize, checkPermission, logError));
  v1Router.use("/", createRoleRoutes(db, authenticate, authorize, checkPermission, logError));
  v1Router.use("/user-sessions", createSessionRoutes(db, authenticate, checkPermission, logError));
  v1Router.use("/", createLogRoutes(db, authenticate, checkPermission, logError));
  v1Router.use("/", createSettingsRoutes(db, authenticate, checkPermission, logError));
  v1Router.use("/", createPdfTemplatesRoutes(db, authenticate, checkPermission, logError));
  v1Router.use("/", createProfileRoutes(db, authenticate, authorize, logError));
  v1Router.use("/", createDashboardRoutes(db, authenticate, authorize, logError));
  v1Router.use("/correspondence", createCorrespondenceRoutes(db, authenticate, checkPermission, logError, saveFile));
  v1Router.use("/", createOrgEntitiesRoutes(db, authenticate, checkPermission, logError));
  v1Router.use("/", createCoiRoutes(db, authenticate, checkPermission, logError));
  v1Router.use("/", createPoliciesRoutes(db, authenticate, checkPermission, logError));
  v1Router.use("/", createAppSettingsRoutes(db, authenticate, checkPermission, logError));
  v1Router.use("/", createExecutiveReportsRoutes(db, authenticate, checkPermission, logError));
  v1Router.use("/departments", createDepartmentRoutes(db, authenticate, checkPermission, logError));
  
  // Newly Extracted Routes
  v1Router.use("/analytics", createAnalyticsRoutes(db, authenticate, checkPermission, logError));
  v1Router.use("/", createIntegrityRoutes(authenticate));
  v1Router.use("/audit-programs", createAuditProgramRoutes(db, authenticate, checkPermission, logError));
  v1Router.use("/audit-tasks", createAuditTaskRoutes(db, authenticate, logError));
  v1Router.use("/audit-findings", createAuditFindingRoutes(db, authenticate, checkPermission, logError));
  v1Router.use("/recommendations", createRecommendationRoutes(db, authenticate, logError));

  // Archive Routes (audit plan archiving and archived plan retrieval)
  v1Router.use("/", createArchiveRoutes(db, authenticate, checkPermission, logError));

  v1Router.use("/fraud-access-requests", createFraudRoutes(db, authenticate, checkPermission, logError, createNotification));
  v1Router.use("/compliance", createComplianceRoutes(db, authenticate, checkPermission, logError, saveFile));

  // Bulk Operations
  v1Router.use("/bulk", createBulkRoutes(authenticate));

  // Admin Routes
  v1Router.use("/admin", createAdminBackupRoutes(authenticate, checkPermission));

  // Permission Admin Routes (role management, permission matrix, user overrides, audit logs)
  v1Router.use("/", createPermissionAdminRoutes(db, authenticate, checkPermission, logError));

  // Job Status Routes (background job status polling)
  // Uses lazy resolution: getQueueService() is called at request time (not registration time)
  // because infrastructure is initialized after routes are registered.
  const lazyQueueService = new Proxy({} as QueueService, {
    get(_target, prop) {
      if (!isInfrastructureReady()) {
        if (prop === 'getJobStatus') {
          return async () => null;
        }
        if (prop === 'getQueueHealth') {
          return async () => ({ connected: false, waiting: 0, active: 0, completed: 0, failed: 0, delayed: 0, workers: 0 });
        }
        return () => { throw new Error('Infrastructure not yet initialized'); };
      }
      const service = getQueueService();
      const value = (service as any)[prop];
      return typeof value === 'function' ? value.bind(service) : value;
    },
  });
  v1Router.use("/jobs", createJobRoutes(authenticate, lazyQueueService));

  // Mount the v1 router under /api/v1
  app.use("/api/v1", v1Router);

  // Register custom routes in the route registry for duplicate detection
  registerRoutes(['POST'], '/api/v1/audit-programs', 'auditPrograms.ts');
  registerRoutes(['GET', 'POST', 'PUT', 'DELETE'], '/api/v1/audit-findings', 'auditFindings.ts');
  registerRoutes(['GET', 'PATCH'], '/api/v1/audit-tasks', 'auditTasks.ts');
  registerRoutes(['POST'], '/api/v1/audit-tasks/:id/assign', 'auditTasks.ts');
  registerRoutes(['DELETE'], '/api/v1/audit-tasks/:id/assign/:userId', 'auditTasks.ts');
  registerRoutes(['POST', 'PATCH'], '/api/v1/recommendations', 'recommendations.ts');
  registerRoutes(['POST', 'GET'], '/api/v1/audit-findings/:findingId/evidence', 'auditFindings.ts');

  // Detect and log duplicate route registrations at startup
  logDuplicateRoutes();

  // Global API 404 Handler - MUST be after all API routes
  // Handles both /api/v1/unknown and /api/unknown (which gets rewritten to /api/v1/unknown)
  app.use("/api", (req, res) => {
    res.status(404).json({ error: `API endpoint ${req.originalUrl} not found` });
  });
};

