import { db } from '../db/index';
import { N8nService } from '../utils/n8nService';
import { ValidationError, NotFoundError, ForbiddenError } from '../utils/errors';

/**
 * ArchiveService: Handles the full archive workflow for audit plans.
 *
 * The archive process:
 * 1. Validates user role (Manager/Admin)
 * 2. Validates plan exists and is not already archived
 * 3. Checks all tasks are 'completed', findings are 'Closed',
 *    recommendations are 'Implemented' or 'Closed'
 * 4. Copies plan, tasks, findings, recommendations, evidence to archive tables as JSONB
 * 5. Verifies copy completeness before deletion
 * 6. Deletes details from regular tables (evidence → recommendations → findings → tasks)
 * 7. Marks plan as is_archived = true, status = 'Archived'
 * 8. Sends audit_plan.archived event to N8nService with retry (up to 3 attempts)
 *
 * The entire operation runs within a single transaction.
 * On any failure, the transaction rolls back and data remains unchanged.
 */
export class ArchiveService {
  private static readonly MAX_N8N_RETRIES = 3;

  /**
   * Archives a plan and all its related data (tasks, findings, recommendations, evidence).
   *
   * @param planId - The ID of the plan to archive
   * @param userId - The ID of the user requesting the archive
   * @param userRole - The role of the user (must be 'Manager' or 'Admin')
   * @throws ForbiddenError if user doesn't have Manager/Admin role
   * @throws NotFoundError if plan doesn't exist or is already archived
   * @throws ValidationError if there are open tasks, findings, or recommendations
   */
  static async archivePlan(
    planId: string,
    userId: string,
    userRole: string
  ): Promise<void> {
    // 1. Validate user role
    const allowedRoles = ['Manager', 'Admin'];
    if (!allowedRoles.includes(userRole)) {
      throw new ForbiddenError('ليس لديك صلاحية الأرشفة. يجب أن تكون مديراً أو مسؤولاً.');
    }

    // Execute the entire archive operation within a single transaction
    await db.transaction(async () => {
      // 2. Validate plan exists and is not already archived
      const plan = await db.prepare(
        "SELECT * FROM audit_plans WHERE id = ? AND is_archived = false"
      ).get(planId) as any;

      if (!plan) {
        // Check if plan exists but is already archived
        const existingPlan = await db.prepare(
          "SELECT id, is_archived FROM audit_plans WHERE id = ?"
        ).get(planId) as any;

        if (existingPlan && existingPlan.is_archived) {
          throw new NotFoundError('الخطة مؤرشفة مسبقاً');
        }
        throw new NotFoundError('الخطة غير موجودة أو مؤرشفة مسبقاً');
      }

      // 3. Check all tasks are 'completed'
      const openTasks = await db.prepare(
        "SELECT COUNT(*) as count FROM audit_tasks WHERE plan_id = ? AND status != 'completed'"
      ).get(planId) as any;

      if (openTasks && Number(openTasks.count) > 0) {
        // Get detailed counts for the error message
        const taskDetails = await db.prepare(
          "SELECT status, COUNT(*) as count FROM audit_tasks WHERE plan_id = ? AND status != 'completed' GROUP BY status"
        ).all(planId) as any[];

        const detailStr = taskDetails
          .map((d: any) => `${d.count} مهمة بحالة "${d.status}"`)
          .join('، ');

        throw new ValidationError(
          `يجب إغلاق جميع المهام قبل الأرشفة. توجد عناصر مفتوحة: ${detailStr}`,
          { openTasks: Number(openTasks.count), details: taskDetails }
        );
      }

      // 4. Check all findings are 'Closed'
      const openFindings = await db.prepare(
        "SELECT COUNT(*) as count FROM audit_findings WHERE audit_id = ? AND status != 'Closed'"
      ).get(planId) as any;

      if (openFindings && Number(openFindings.count) > 0) {
        const findingDetails = await db.prepare(
          "SELECT status, COUNT(*) as count FROM audit_findings WHERE audit_id = ? AND status != 'Closed' GROUP BY status"
        ).all(planId) as any[];

        const detailStr = findingDetails
          .map((d: any) => `${d.count} ملاحظة بحالة "${d.status}"`)
          .join('، ');

        throw new ValidationError(
          `يجب إغلاق جميع الملاحظات قبل الأرشفة. توجد عناصر مفتوحة: ${detailStr}`,
          { openFindings: Number(openFindings.count), details: findingDetails }
        );
      }

      // 5. Check all recommendations are 'Implemented' or 'Closed'
      const openRecs = await db.prepare(
        `SELECT COUNT(*) as count FROM recommendations 
         WHERE finding_id IN (SELECT id FROM audit_findings WHERE audit_id = ?)
         AND status NOT IN ('Implemented', 'Closed')`
      ).get(planId) as any;

      if (openRecs && Number(openRecs.count) > 0) {
        const recDetails = await db.prepare(
          `SELECT status, COUNT(*) as count FROM recommendations 
           WHERE finding_id IN (SELECT id FROM audit_findings WHERE audit_id = ?)
           AND status NOT IN ('Implemented', 'Closed')
           GROUP BY status`
        ).all(planId) as any[];

        const detailStr = recDetails
          .map((d: any) => `${d.count} توصية بحالة "${d.status}"`)
          .join('، ');

        throw new ValidationError(
          `يجب إغلاق جميع التوصيات قبل الأرشفة. توجد عناصر مفتوحة: ${detailStr}`,
          { openRecommendations: Number(openRecs.count), details: recDetails }
        );
      }

      // --- Archive Operation ---

      // 6a. Copy plan to archived_plans
      await db.prepare(
        "INSERT INTO archived_plans (original_plan_id, plan_data, year, archived_by) VALUES (?, ?::jsonb, ?, ?)"
      ).run(planId, JSON.stringify(plan), plan.year, userId);

      // 6b. Copy tasks to archived_tasks
      const tasks = await db.prepare(
        "SELECT * FROM audit_tasks WHERE plan_id = ?"
      ).all(planId) as any[];

      for (const task of tasks) {
        await db.prepare(
          "INSERT INTO archived_tasks (original_task_id, plan_id, task_data) VALUES (?, ?, ?::jsonb)"
        ).run(task.id, planId, JSON.stringify(task));
      }

      // 6c. Copy findings to archived_findings
      const findings = await db.prepare(
        "SELECT * FROM audit_findings WHERE audit_id = ?"
      ).all(planId) as any[];

      for (const finding of findings) {
        await db.prepare(
          "INSERT INTO archived_findings (original_finding_id, plan_id, finding_data) VALUES (?, ?, ?::jsonb)"
        ).run(finding.id, planId, JSON.stringify(finding));
      }

      // 6d. Copy recommendations to archived_recommendations
      const recs = await db.prepare(
        `SELECT r.* FROM recommendations r
         JOIN audit_findings f ON r.finding_id = f.id
         WHERE f.audit_id = ?`
      ).all(planId) as any[];

      for (const rec of recs) {
        await db.prepare(
          "INSERT INTO archived_recommendations (original_recommendation_id, plan_id, recommendation_data) VALUES (?, ?, ?::jsonb)"
        ).run(rec.id, planId, JSON.stringify(rec));
      }

      // 6e. Copy evidence to archived_evidence
      const evidence = await db.prepare(
        "SELECT * FROM audit_evidence WHERE audit_id = ?"
      ).all(planId) as any[];

      for (const ev of evidence) {
        await db.prepare(
          "INSERT INTO archived_evidence (original_evidence_id, plan_id, evidence_data) VALUES (?, ?, ?::jsonb)"
        ).run(ev.id, planId, JSON.stringify(ev));
      }

      // 7. Verify copy completeness before deletion
      const archivedTaskCount = await db.prepare(
        "SELECT COUNT(*) as count FROM archived_tasks WHERE plan_id = ?"
      ).get(planId) as any;

      const archivedFindingCount = await db.prepare(
        "SELECT COUNT(*) as count FROM archived_findings WHERE plan_id = ?"
      ).get(planId) as any;

      const archivedRecCount = await db.prepare(
        "SELECT COUNT(*) as count FROM archived_recommendations WHERE plan_id = ?"
      ).get(planId) as any;

      const archivedEvidenceCount = await db.prepare(
        "SELECT COUNT(*) as count FROM archived_evidence WHERE plan_id = ?"
      ).get(planId) as any;

      if (Number(archivedTaskCount.count) !== tasks.length) {
        throw new Error('فشل التحقق من اكتمال نسخ المهام إلى الأرشيف');
      }
      if (Number(archivedFindingCount.count) !== findings.length) {
        throw new Error('فشل التحقق من اكتمال نسخ الملاحظات إلى الأرشيف');
      }
      if (Number(archivedRecCount.count) !== recs.length) {
        throw new Error('فشل التحقق من اكتمال نسخ التوصيات إلى الأرشيف');
      }
      if (Number(archivedEvidenceCount.count) !== evidence.length) {
        throw new Error('فشل التحقق من اكتمال نسخ الأدلة إلى الأرشيف');
      }

      // 8. Delete details from regular tables (respecting FK constraints)
      // Order: evidence → recommendations → findings → tasks
      await db.prepare(
        "DELETE FROM audit_evidence WHERE audit_id = ?"
      ).run(planId);

      await db.prepare(
        `DELETE FROM recommendations 
         WHERE finding_id IN (SELECT id FROM audit_findings WHERE audit_id = ?)`
      ).run(planId);

      await db.prepare(
        "DELETE FROM audit_findings WHERE audit_id = ?"
      ).run(planId);

      await db.prepare(
        "DELETE FROM audit_tasks WHERE plan_id = ?"
      ).run(planId);

      // 9. Mark plan as archived (plan row stays for quick lookup)
      await db.prepare(
        "UPDATE audit_plans SET is_archived = true, archived_at = CURRENT_TIMESTAMP, archived_by = ?, status = 'Archived' WHERE id = ?"
      ).run(userId, planId);
    })();

    // 10. Send automation event (outside transaction - archive stays even if this fails)
    await this.sendArchiveEventWithRetry(planId, userId);
  }

  /**
   * Sends the audit_plan.archived event to N8nService with retry logic.
   * Up to 3 attempts. If all fail, the archive remains intact (no rollback).
   */
  private static async sendArchiveEventWithRetry(
    planId: string,
    userId: string
  ): Promise<void> {
    // Fetch the plan year for the event payload
    const plan = await db.prepare(
      "SELECT year FROM audit_plans WHERE id = ?"
    ).get(planId) as any;

    const payload = {
      planId,
      year: plan?.year,
      archivedBy: userId,
    };

    let lastError: Error | null = null;

    for (let attempt = 1; attempt <= this.MAX_N8N_RETRIES; attempt++) {
      try {
        await N8nService.sendEvent('audit_plan.archived', payload);
        return; // Success
      } catch (error: any) {
        lastError = error;
        console.error(
          `[ArchiveService] Failed to send audit_plan.archived event (attempt ${attempt}/${this.MAX_N8N_RETRIES}):`,
          error?.message
        );

        // Wait before retry (exponential backoff: 1s, 2s, 4s)
        if (attempt < this.MAX_N8N_RETRIES) {
          await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempt - 1) * 1000));
        }
      }
    }

    // All retries failed - log but don't throw (archive is already complete)
    console.error(
      `[ArchiveService] All ${this.MAX_N8N_RETRIES} attempts to send audit_plan.archived event failed.`,
      lastError?.message
    );
  }
}

import { db } from '../db/index';
import { BaseService } from './BaseService';
import { NotificationService } from './NotificationService';
import { N8nService } from '../utils/n8nService';
import { NumberingService } from './NumberingService';
import { ValidationError, ConflictError, ForbiddenError, NotFoundError } from '../utils/errors';

/** Valid quarter values for audit plans */
const VALID_QUARTERS = ['Q1', 'Q2', 'Q3', 'Q4', 'Annual'] as const;
type Quarter = typeof VALID_QUARTERS[number];

export class AuditPlanService extends BaseService {
  /**
   * Checks whether a new plan can be created for the given fiscal year.
   *
   * Rules:
   * 1. No existing plan for the same fiscal year (regardless of status)
   * 2. Previous year's plan must be archived (if it exists)
   *
   * @param year - The fiscal year (e.g., 2025)
   * @returns Object with `allowed` boolean and optional `reason` string
   */
  static async canCreateNewPlan(year: number): Promise<{ allowed: boolean; reason?: string }> {
    // Check 1: No existing plan for the same fiscal year
    const sameYear = await db.prepare(
      "SELECT id FROM audit_plans WHERE year = ?"
    ).all(year) as any[];

    if (sameYear.length > 0) {
      return {
        allowed: false,
        reason: `توجد خطة للسنة المالية ${year} بالفعل`
      };
    }

    // Check 2: Previous year's plan must be archived (if it exists)
    const previousYear = year - 1;
    const unarchived = await db.prepare(
      "SELECT id, title FROM audit_plans WHERE year = ? AND is_archived = false"
    ).all(previousYear) as any[];

    if (unarchived.length > 0) {
      return {
        allowed: false,
        reason: `يجب أرشفة خطة السنة المالية ${previousYear} أولاً قبل إنشاء خطة جديدة`
      };
    }

    return { allowed: true };
  }

  /**
   * Returns the fixed fiscal year bounds (Jan 1 - Dec 31) for a given year.
   *
   * @param year - The fiscal year (e.g., 2025)
   * @returns Object with `start` (YYYY-01-01) and `end` (YYYY-12-31) date strings
   */
  static fiscalYearBounds(year: number): { start: string; end: string } {
    return {
      start: `${year}-01-01`,
      end: `${year}-12-31`,
    };
  }

  /**
   * Closes an audit plan after validating:
   * 1. The user has Manager or Admin role
   * 2. All recommendations linked to the plan's findings are 'Implemented' or 'Closed'
   *
   * @param planId - The ID of the plan to close
   * @param userId - The ID of the user requesting closure
   * @throws ForbiddenError if user lacks Manager/Admin role
   * @throws NotFoundError if plan does not exist
   * @throws ValidationError if open recommendations exist
   */
  static async closePlan(planId: string, userId: string): Promise<{ success: boolean; planId: string }> {
    // 1. Validate user role is Manager or Admin
    const user = await db.prepare(
      "SELECT id, role FROM users WHERE id = ?"
    ).get(userId) as any;

    if (!user) {
      throw new ForbiddenError('المستخدم غير موجود أو لا يملك الصلاحية');
    }

    const allowedRoles = ['Manager', 'Admin'];
    if (!allowedRoles.includes(user.role)) {
      throw new ForbiddenError('لا تملك صلاحية إغلاق الخطة. يجب أن يكون دورك مدير أو مسؤول');
    }

    // 2. Verify plan exists
    const plan = await db.prepare(
      "SELECT id, status FROM audit_plans WHERE id = ?"
    ).get(planId) as any;

    if (!plan) {
      throw new NotFoundError('الخطة غير موجودة');
    }

    // 3. Check all related recommendations are 'Implemented' or 'Closed'
    const openRecommendations = await db.prepare(
      `SELECT COUNT(*) as count FROM recommendations 
       WHERE finding_id IN (SELECT id FROM audit_findings WHERE audit_id = ?)
       AND status NOT IN ('Implemented', 'Closed')`
    ).get(planId) as any;

    const openCount = openRecommendations?.count || 0;

    if (openCount > 0) {
      throw new ValidationError(
        `لا يمكن إغلاق الخطة: توجد ${openCount} توصية غير مكتملة. يجب أن تكون جميع التوصيات بحالة "منفذة" أو "مغلقة"`,
        { openRecommendationsCount: openCount }
      );
    }

    // 4. Set plan status to 'Closed'
    await db.prepare(
      "UPDATE audit_plans SET status = 'Closed', updated_at = CURRENT_TIMESTAMP WHERE id = ?"
    ).run(planId);

    return { success: true, planId };
  }

  static async generatePlanCode(departmentName?: string): Promise<string> {
    const currentYear = new Date().getFullYear();
    const shortYear = currentYear.toString().slice(-2);
    
    // Attempt to resolve department code
    let deptCode = 'IA'; // Internal Audit by default
    if (departmentName) {
      try {
        const dept = await db.prepare("SELECT entity_code FROM org_entities WHERE name_ar = ? OR name_en = ?").get(departmentName, departmentName) as any;
        if (dept && dept.entity_code) {
          deptCode = dept.entity_code;
        }
      } catch (e) {
        // ignore
      }
    }

    const docType = 'PL'; // Plan
    const prefix = `${deptCode}-${docType}-${shortYear}-`;
    
    try {
      // Find the latest plan code with this format
      const latestPlan = await db.prepare(
        `SELECT plan_code FROM audit_plans 
         WHERE plan_code LIKE ? 
         ORDER BY plan_code DESC LIMIT 1`
      ).get(`${prefix}%`) as any;

      let nextNumber = 1;
      if (latestPlan && latestPlan.plan_code) {
        const parts = latestPlan.plan_code.split('-');
        const lastNumber = parseInt(parts[parts.length - 1]);
        if (!isNaN(lastNumber)) {
          nextNumber = lastNumber + 1;
        }
      }

      // Format with leading zeros (e.g., 001)
      const formattedNumber = nextNumber.toString().padStart(3, '0');
      const newCode = `${prefix}${formattedNumber}`;
      return newCode;
    } catch (error) {
      console.error('[AuditPlanService] Error generating plan code:', error);
      return `${prefix}ERR-${Date.now().toString().slice(-3)}`;
    }
  }

  /**
   * Creates a new audit plan with fiscal year validation, quarter enforcement,
   * single-plan-per-year constraint, and unified numbering via NumberingService.
   *
   * Validates:
   * - Year is within 2000-2100
   * - Quarter is one of: Q1, Q2, Q3, Q4, Annual
   * - No existing plan for the same fiscal year
   * - Previous year's plan is archived (if exists)
   * - Generates plan_code via NumberingService
   * - Sets default dates to fiscal year bounds
   * - Sets initial status to 'Planned'
   */
  static async create(tableName: string, data: any) {
    const year = data.year;
    const quarter = data.quarter || 'Annual';

    // Validate year range (2000-2100)
    if (year == null || !Number.isInteger(year) || year < 2000 || year > 2100) {
      throw new ValidationError(
        'السنة المالية يجب أن تكون عدداً صحيحاً بين 2000 و 2100',
        { field: 'year', value: year }
      );
    }

    // Validate quarter value
    if (!VALID_QUARTERS.includes(quarter as Quarter)) {
      throw new ValidationError(
        `قيمة الربع غير صالحة. القيم المسموحة: ${VALID_QUARTERS.join(', ')}`,
        { field: 'quarter', value: quarter }
      );
    }

    // Enforce single plan per fiscal year and previous year archived
    const canCreate = await this.canCreateNewPlan(year);
    if (!canCreate.allowed) {
      throw new ConflictError(canCreate.reason!);
    }

    // Generate plan_code via NumberingService (unified hierarchical numbering)
    const planCode = await NumberingService.nextPlanCode(year);

    // Set fiscal year default dates
    const { start, end } = this.fiscalYearBounds(year);

    const body = {
      ...data,
      plan_code: planCode,
      year,
      quarter,
      planned_start_date: data.planned_start_date || start,
      planned_end_date: data.planned_end_date || end,
      status: 'Planned',
      is_archived: false,
    };

    const result = await super.create(tableName, body);
    
    // --- AUTOMATION: Send event to n8n ---
    await N8nService.sendEvent('audit_plan.created', {
      planId: result.id,
      title: body.title,
      department: body.department,
      planCode: body.plan_code
    });

    return result;
  }

  static async update(tableName: string, id: string | number, data: any) {
    // Get the current status before update
    const currentPlan = await db.prepare("SELECT status, title, lead_auditor FROM audit_plans WHERE id = ?").get(id) as any;
    
    const result = await super.update(tableName, id, data);

    // --- AUTOMATION: Send event to n8n ---
    if (data.status && currentPlan && currentPlan.status !== data.status) {
      await N8nService.sendEvent('audit_plan.status_changed', {
        planId: id,
        oldStatus: currentPlan.status,
        newStatus: data.status,
        title: data.title || currentPlan.title
      });
    }

    // --- AUTOMATION: Auto-generate report when audit plan is completed ---
    if (data.status === 'Completed' || data.status === 'Closed') {
      if (currentPlan && currentPlan.status !== data.status) {
        try {
          // Check if a report already exists for this audit
          const existingReport = await db.prepare("SELECT id FROM audit_reports WHERE audit_id = ?").get(id);
          
          if (!existingReport) {
            // Generate a new report
            const reportTitle = `Final Audit Report: ${data.title || currentPlan.title}`;
            const reportSummary = `This is an automatically generated final report for the audit engagement: ${data.title || currentPlan.title}. The audit has been marked as ${data.status}.`;
            
            await db.prepare(`
              INSERT INTO audit_reports (title, type, audit_id, summary, findings_included, status, created_by) 
              VALUES (?, ?, ?, ?, ?, ?, ?)
            `).run(reportTitle, 'Audit Report', id, reportSummary, 1, 'Final', 'System');

            await this.logAudit('System', `Auto-generated final report for Audit ID: ${id}`, "audit_reports", JSON.stringify({ title: reportTitle }));

            // Notify the lead auditor
            const leadAuditor = data.lead_auditor || currentPlan.lead_auditor;
            if (leadAuditor) {
              const user = await db.prepare("SELECT id FROM users WHERE name = ? OR username = ?").get(leadAuditor, leadAuditor) as any;
              if (user) {
                await NotificationService.create(
                  user.id,
                  'Report Auto-Generated',
                  `The final audit report for "${data.title || currentPlan.title}" has been automatically generated.`,
                  'audit_reports',
                  '/reports'
                );
              }
            }
          }
        } catch (err: any) {
          console.error('[Automation Error] Failed to auto-generate report:', err);
          
          try {
            // Un-silence the error by escalating it to the system error logs for Administrator visibility
            await db.prepare(`
              INSERT INTO system_error_log (user_id, module, url, message, stack, user_agent, request_data, severity)
              VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            `).run(
              null, "AuditPlanService.update", "System_Job", 
              err?.message || "Unknown error generating report", err?.stack ? err.stack.substring(0, 2000) : "", 
              "System_Job", null, "error"
            );
          } catch (loggingErr) {
            console.error("Critical failure writing to system_error_log", loggingErr);
          }
        }
      }
    }
    // ------------------------------------------------------------------------

    return result;
  }
}

import { db } from '../db/index';
import { NotFoundError, ForbiddenError, ValidationError } from '../utils/errors';
import { UserRole } from '../../constants';
import { NotificationService } from './NotificationService';
import { DEFAULT_PERMISSIONS, MODULES, PERMISSIONS } from '../../permissions';
import type { Role } from '../../permissions';

export interface CreateProgramInput {
  program_code: string;
  program_title: string;
  audit_area: string;
  department: string;
  audit_type: string;
  audit_objective: string;
  audit_scope: string;
  key_risks?: string;
  reference_standard?: string;
  risk_ids?: string[];
  compliance_item_ids?: string[];
}

export class AuditProgramService {
  private static db = db;

  /**
   * Creates a new audit program with risk and compliance linking.
   * 
   * Restrictions:
   * - Only Internal Auditor role can create programs
   * - Sets initial status to 'Draft' and version_number to 1
   * - Validates risk_ids exist in risk_register (max 200, no duplicates)
   * - Validates compliance_item_ids exist in compliance_items (max 200, no duplicates)
   * - Creates links in program_risk_links and program_compliance_links
   * - Sends notification to Manager/Admin for approval
   * 
   * @param data - Program creation data including optional risk_ids and compliance_item_ids
   * @param userId - The ID of the user creating the program
   * @param userRole - The role of the user (must be 'Internal Auditor')
   * @throws ForbiddenError if user is not Internal Auditor
   * @throws ValidationError if risk_ids or compliance_item_ids are invalid
   */
  static async createProgram(
    data: CreateProgramInput,
    userId: string,
    userRole: string
  ): Promise<{ programId: string }> {
    // 1. Only Internal Auditor can create programs
    if (userRole !== UserRole.INTERNAL_AUDITOR) {
      throw new ForbiddenError('فقط المدقق الداخلي يمكنه إنشاء برامج التدقيق');
    }

    const riskIds = data.risk_ids || [];
    const complianceItemIds = data.compliance_item_ids || [];

    // 2. Validate max 200 risk_ids
    if (riskIds.length > 200) {
      throw new ValidationError('لا يمكن ربط أكثر من 200 مخاطرة بالبرنامج', {
        field: 'risk_ids',
        max: 200,
        provided: riskIds.length,
      });
    }

    // 3. Validate max 200 compliance_item_ids
    if (complianceItemIds.length > 200) {
      throw new ValidationError('لا يمكن ربط أكثر من 200 معيار امتثال بالبرنامج', {
        field: 'compliance_item_ids',
        max: 200,
        provided: complianceItemIds.length,
      });
    }

    // 4. Check for duplicate risk_ids
    const uniqueRiskIds = new Set(riskIds);
    if (uniqueRiskIds.size !== riskIds.length) {
      throw new ValidationError('قائمة معرّفات المخاطر تحتوي على قيم مكررة', {
        field: 'risk_ids',
        duplicates: riskIds.filter((id, idx) => riskIds.indexOf(id) !== idx),
      });
    }

    // 5. Check for duplicate compliance_item_ids
    const uniqueComplianceIds = new Set(complianceItemIds);
    if (uniqueComplianceIds.size !== complianceItemIds.length) {
      throw new ValidationError('قائمة معرّفات معايير الامتثال تحتوي على قيم مكررة', {
        field: 'compliance_item_ids',
        duplicates: complianceItemIds.filter((id, idx) => complianceItemIds.indexOf(id) !== idx),
      });
    }

    return await this.db.transaction(async () => {
      // 6. Validate risk_ids exist in risk_register
      if (riskIds.length > 0) {
        const placeholders = riskIds.map(() => '?').join(',');
        const existingRisks = await this.db.prepare(
          `SELECT id FROM risk_register WHERE id IN (${placeholders})`
        ).all(...riskIds) as any[];

        const existingRiskIds = new Set(existingRisks.map((r: any) => r.id));
        const missingRiskIds = riskIds.filter(id => !existingRiskIds.has(id));

        if (missingRiskIds.length > 0) {
          throw new ValidationError('بعض معرّفات المخاطر غير موجودة في سجل المخاطر', {
            field: 'risk_ids',
            missing: missingRiskIds,
          });
        }
      }

      // 7. Validate compliance_item_ids exist in compliance_items
      if (complianceItemIds.length > 0) {
        const placeholders = complianceItemIds.map(() => '?').join(',');
        const existingCompliance = await this.db.prepare(
          `SELECT id FROM compliance_items WHERE id IN (${placeholders})`
        ).all(...complianceItemIds) as any[];

        const existingComplianceIds = new Set(existingCompliance.map((c: any) => c.id));
        const missingComplianceIds = complianceItemIds.filter(id => !existingComplianceIds.has(id));

        if (missingComplianceIds.length > 0) {
          throw new ValidationError('بعض معرّفات معايير الامتثال غير موجودة في مصفوفة الامتثال', {
            field: 'compliance_item_ids',
            missing: missingComplianceIds,
          });
        }
      }

      // 8. Create the program with status 'Draft' and version_number 1
      const program = await this.db.prepare(`
        INSERT INTO audit_programs (
          program_code, program_title, audit_area, department,
          audit_type, audit_objective, audit_scope, key_risks,
          reference_standard, status, version_number, created_by
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'Draft', 1, ?)
        RETURNING id
      `).get(
        data.program_code, data.program_title, data.audit_area,
        data.department, data.audit_type, data.audit_objective,
        data.audit_scope, data.key_risks || '',
        data.reference_standard || '', userId
      ) as any;

      const programId = program.id;

      // 9. Create risk links
      for (const riskId of riskIds) {
        await this.db.prepare(
          "INSERT INTO program_risk_links (program_id, risk_id) VALUES (?, ?)"
        ).run(programId, riskId);
      }

      // 10. Create compliance links
      for (const complianceId of complianceItemIds) {
        await this.db.prepare(
          "INSERT INTO program_compliance_links (program_id, compliance_item_id) VALUES (?, ?)"
        ).run(programId, complianceId);
      }

      // 11. Send notification to Manager and Admin for approval
      const managerAndAdminIds = await this.db.prepare(
        `SELECT id FROM users WHERE role IN (?, ?) AND status = 'active'`
      ).all(UserRole.MANAGER, UserRole.ADMIN) as any[];

      const recipientIds = managerAndAdminIds.map((u: any) => u.id);

      if (recipientIds.length > 0) {
        await NotificationService.create(
          recipientIds,
          'record_created',
          JSON.stringify({ key: 'notifications.programPendingApproval', params: { title: data.program_title } }),
          'AuditProgramLibrary',
          '/library',
          { actorId: userId, entityId: programId, entityType: 'audit_program' }
        );
      }

      return { programId };
    })();
  }

  static async duplicate(id: string | number, username: string) {
    return await this.db.transaction(async () => {
      const program = await this.db.prepare("SELECT * FROM audit_programs WHERE id = ?").get(id) as any;
      if (!program) throw new NotFoundError("Program not found");
      
      const { id: oldId, created_at, updated_at, ...programData } = program;
      programData.program_title = `${programData.program_title} (Copy)`;
      programData.program_code = `${programData.program_code}-COPY`;
      programData.status = 'Draft';
      programData.created_by = username;
      programData.version_number = 1;
      
      const keys = Object.keys(programData).map(k => this.db.validateIdentifier(k));
      const values = Object.values(programData);
      const placeholders = keys.map(() => "?").join(",");
      const stmt = this.db.prepare(`INSERT INTO audit_programs (${keys.join(",")}) VALUES (${placeholders}) RETURNING id`);
      const res = await stmt.get(...values);
      const newId = res.id;
      
      // Duplicate procedures using a single efficient INSERT INTO ... SELECT query (Replacing N+1 Query)
      await this.db.prepare(`
        INSERT INTO audit_procedures (
          program_id, procedure_number, audit_step, audit_test_description, 
          risk_addressed, control_test_type, expected_evidence, 
          sampling_method, responsible_auditor, remarks
        )
        SELECT 
          ?, procedure_number, audit_step, audit_test_description, 
          risk_addressed, control_test_type, expected_evidence, 
          sampling_method, responsible_auditor, remarks
        FROM audit_procedures WHERE program_id = ?
      `).run(newId, id);
      
      return newId;
    })();
  }

  /**
   * Approves an audit program after validating permissions and status.
   * 
   * Restrictions:
   * - User must have APPROVE permission on AUDIT_PROGRAM_LIBRARY module
   *   (Manager and Admin roles per the permission matrix)
   * - Program must exist
   * - Program status must be 'Draft' or 'Submitted'
   * - Sets status to 'Approved', records approved_by and approved_at
   * 
   * @param programId - The ID of the program to approve
   * @param userId - The ID of the user performing the approval
   * @param userRole - The role of the user
   * @throws ForbiddenError if user lacks APPROVE permission on AUDIT_PROGRAM_LIBRARY
   * @throws NotFoundError if program doesn't exist
   * @throws ValidationError if program status is not 'Draft' or 'Submitted'
   */
  static async approveProgram(
    programId: string,
    userId: string,
    userRole: string
  ): Promise<void> {
    // 1. Validate user has APPROVE permission on AUDIT_PROGRAM_LIBRARY
    const rolePermissions = DEFAULT_PERMISSIONS[userRole as Role];
    const modulePermissions = rolePermissions?.[MODULES.AUDIT_PROGRAM_LIBRARY] || [];
    
    if (!modulePermissions.includes(PERMISSIONS.APPROVE)) {
      throw new ForbiddenError('ليس لديك صلاحية اعتماد برامج التدقيق');
    }

    // 2. Validate program exists
    const program = await this.db.prepare(
      "SELECT id, status FROM audit_programs WHERE id = ?"
    ).get(programId) as any;

    if (!program) {
      throw new NotFoundError('برنامج التدقيق غير موجود');
    }

    // 3. Validate program status is 'Draft' or 'Submitted'
    const approvableStatuses = ['Draft', 'Submitted'];
    if (!approvableStatuses.includes(program.status)) {
      throw new ValidationError(
        'لا يمكن اعتماد البرنامج إلا إذا كانت حالته "مسودة" أو "مُقدَّم"',
        { currentStatus: program.status, allowedStatuses: approvableStatuses }
      );
    }

    // 4. Set status to 'Approved', record approved_by and approved_at
    await this.db.prepare(
      "UPDATE audit_programs SET status = 'Approved', approved_by = ?, approved_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP WHERE id = ?"
    ).run(userId, programId);
  }
}

import { db } from '../db/index';
import { ValidationError, NotFoundError, ForbiddenError } from '../utils/errors';
import { N8nService } from '../utils/n8nService';
import { NumberingService } from './NumberingService';
import { NotificationService } from './NotificationService';
import { UserRole, ADMIN_ROLES } from '../../constants';
import { DEFAULT_PERMISSIONS, MODULES, PERMISSIONS } from '../../permissions';
import type { Role } from '../../permissions';

const VALID_FINDING_TYPES = ['control_design_deficiency', 'operational_design_deficiency'] as const;
type FindingType = typeof VALID_FINDING_TYPES[number];

/** Allowed finding status transitions */
export const ALLOWED_FINDING_TRANSITIONS: Record<string, string[]> = {
  'Open': ['In Progress'],
  'In Progress': ['Closed', 'Pending Approval'],
  'Pending Approval': ['Closed', 'In Progress'],
  'Closed': [],
};

/** Maps finding status to recommendation status for sync */
export const FINDING_TO_RECOMMENDATION_STATUS: Record<string, string> = {
  'Open': 'Open',
  'In Progress': 'In Progress',
  'Closed': 'Implemented',
  'Pending Approval': 'In Progress',
};

export interface CreateFindingInput {
  audit_id: string;
  title: string;
  description?: string;
  criteria?: string;
  condition?: string;
  finding_type: FindingType;
  consequence?: string;
  risk_level: 'Low' | 'Medium' | 'High' | 'Critical';
}

export class AuditService {
  static async getFindings(params: any = {}) {
    const page = parseInt(params.page) || 1;
    const pageSize = parseInt(params.pageSize) || 20;
    const offset = (page - 1) * pageSize;

    let query = `SELECT af.*, u.name as created_by_name 
                 FROM audit_findings af
                 LEFT JOIN users u ON af.created_by = u.id`;
    let countQuery = "SELECT COUNT(*) as total FROM audit_findings af";
    const args: any[] = [];
    let whereClause = "";

    if (params.audit_id) {
      whereClause = " WHERE af.audit_id = ?";
      args.push(params.audit_id);
    }

    query += whereClause + " ORDER BY af.created_at DESC LIMIT ? OFFSET ?";
    countQuery += whereClause;

    const [data, countRes] = await Promise.all([
      db.prepare(query).all(...args, pageSize, offset),
      db.prepare(countQuery).get(...args)
    ]) as [any[], any];

    const total = countRes?.total || 0;

    return {
      data,
      pagination: {
        total,
        page,
        pageSize,
        totalPages: Math.ceil(total / pageSize)
      }
    };
  }

  /**
   * Returns findings for a specific plan.
   *
   * Validates:
   * - planId must reference an existing plan (throws NotFoundError otherwise)
   *
   * @param planId - The ID of the audit plan
   * @returns Array of findings belonging to the specified plan
   * @throws NotFoundError if plan does not exist
   */
  static async getFindingsByPlan(planId: string): Promise<any[]> {
    if (!planId) {
      throw new NotFoundError('الخطة غير موجودة / Audit plan not found');
    }

    // Validate plan exists
    const plan = await db.prepare(
      "SELECT id FROM audit_plans WHERE id = ?"
    ).get(planId) as any;

    if (!plan) {
      throw new NotFoundError('الخطة غير موجودة / Audit plan not found');
    }

    // Return findings for this plan only
    const findings = await db.prepare(
      "SELECT * FROM audit_findings WHERE audit_id = ? ORDER BY created_at DESC"
    ).all(planId) as any[];

    return findings;
  }

  /**
   * Creates a new audit finding with auto-generated recommendation.
   *
   * Validates:
   * - title: non-empty, max 200 chars
   * - finding_type: must be one of VALID_FINDING_TYPES
   * - audit_id: must reference an existing, non-archived plan
   *
   * Auto-generates:
   * - finding_number via NumberingService
   * - One recommendation with same risk_level, status 'Open', rec_number via NumberingService
   *
   * Sends:
   * - Notification to Manager/Admin users
   * - N8n automation event
   */
  static async createFinding(data: CreateFindingInput, userId: string): Promise<{ findingId: string; recommendationId: string }> {
    // Validate title
    const title = data.title?.trim();
    if (!title || title.length === 0) {
      throw new ValidationError('عنوان الملاحظة إلزامي ولا يمكن أن يكون فارغاً / Finding title is required and cannot be empty');
    }
    if (title.length > 200) {
      throw new ValidationError('عنوان الملاحظة يجب ألا يتجاوز 200 حرف / Finding title must not exceed 200 characters');
    }

    // Validate finding_type
    if (!data.finding_type || !VALID_FINDING_TYPES.includes(data.finding_type as FindingType)) {
      throw new ValidationError(
        'نوع الملاحظة غير مقبول. القيم المسموحة: control_design_deficiency, operational_design_deficiency / ' +
        'Invalid finding type. Allowed values: control_design_deficiency, operational_design_deficiency'
      );
    }

    // Validate audit_id
    if (!data.audit_id) {
      throw new ValidationError('معرّف الخطة (audit_id) مطلوب / audit_id is required');
    }

    return await db.transaction(async () => {
      // Fetch the plan (for plan_code and department)
      const plan = await db.prepare(
        "SELECT id, plan_code, department, is_archived FROM audit_plans WHERE id = ?"
      ).get(data.audit_id) as any;

      if (!plan) {
        throw new NotFoundError('الخطة غير موجودة / Audit plan not found');
      }

      if (plan.is_archived) {
        throw new ValidationError('لا يمكن إضافة ملاحظة لخطة مؤرشفة / Cannot add finding to an archived plan');
      }

      // Generate finding number via NumberingService
      const findingNumber = await NumberingService.nextFindingNumber(data.audit_id, plan.plan_code);

      // Insert the finding
      const findingResult = await db.prepare(`
        INSERT INTO audit_findings (
          audit_id, finding_number, title, description, criteria, condition,
          finding_type, consequence, risk_level, status, created_by
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'Open', ?)
        RETURNING id
      `).get(
        data.audit_id,
        findingNumber,
        title,
        data.description || '',
        data.criteria || '',
        data.condition || '',
        data.finding_type,
        data.consequence || '',
        data.risk_level || 'Medium',
        userId
      ) as any;

      const findingId = findingResult?.id || findingResult?.lastInsertRowid;
      if (!findingId) {
        throw new Error('Failed to create finding');
      }

      // Generate recommendation number via NumberingService
      const recNumber = await NumberingService.nextRecommendationNumber(String(findingId), findingNumber);

      // Auto-create one recommendation with same risk_level
      const recResult = await db.prepare(`
        INSERT INTO recommendations (
          finding_id, plan_id, rec_number, department, responsible, due_date, status, risk_level
        ) VALUES (?, ?, ?, ?, 'TBD', '', 'Open', ?)
        RETURNING id
      `).get(
        findingId,
        data.audit_id,
        recNumber,
        plan.department || '',
        data.risk_level || 'Medium'
      ) as any;

      const recommendationId = recResult?.id || recResult?.lastInsertRowid;

      // Send notification to Manager/Admin
      try {
        const adminIds = await NotificationService.getAdminIds();
        const managerIds = await db.prepare(
          `SELECT id FROM users WHERE role = ? AND status = 'active'`
        ).all(UserRole.MANAGER) as any[];
        const managerUserIds = managerIds.map((m: any) => m.id);

        const allTargetIds = [...new Set([...adminIds, ...managerUserIds])];

        if (allTargetIds.length > 0) {
          await NotificationService.create(
            allTargetIds,
            'finding_added',
            JSON.stringify({ key: 'notifications.findingAdded', params: { title } }),
            'AuditFindings',
            '/audit-findings',
            { actorId: userId, entityId: String(findingId), entityType: 'audit_findings' }
          );
        }
      } catch (notifError) {
        // Notification failure should not block finding creation
        console.error('[AuditService] Notification failed:', (notifError as any)?.message);
      }

      // Send n8n automation event
      try {
        await N8nService.sendEvent('finding.created', {
          findingId: String(findingId),
          title,
          auditId: data.audit_id,
          riskLevel: data.risk_level,
          findingType: data.finding_type
        });
      } catch (n8nError) {
        // N8n failure should not block finding creation
        console.error('[AuditService] N8n event failed:', (n8nError as any)?.message);
      }

      return { findingId: String(findingId), recommendationId: String(recommendationId) };
    });
  }

  static async updateFinding(id: string, body: any, userId: string) {
    return await db.transaction(async () => {
      // Fetch the finding to check ownership
      const finding = await db.prepare(
        "SELECT id, created_by FROM audit_findings WHERE id = ?"
      ).get(id) as any;

      if (!finding) {
        throw new NotFoundError('الملاحظة غير موجودة / Finding not found');
      }

      // Ownership check: only the creator can edit
      if (finding.created_by !== userId) {
        throw new ForbiddenError(
          'ليس لديك صلاحية تعديل هذه الملاحظة. فقط كاتب الملاحظة يمكنه التعديل / ' +
          'You do not have permission to edit this finding. Only the finding creator can edit.'
        );
      }

      const data = { ...body };
      delete data.id;
      delete data.created_by; // Prevent overwriting ownership

      const keys = Object.keys(data).map(k => db.validateIdentifier(k));
      const values = Object.values(data);
      
      if (keys.length === 0) {
        throw new ValidationError("No data provided for update");
      }

      const setClause = keys.map(k => `${k} = ?`).join(",");
      await db.prepare(`UPDATE audit_findings SET ${setClause} WHERE id = ?`).run(...values, id);

      // Sync risk_level change to associated recommendation
      if (data.risk_level) {
        await db.prepare("UPDATE recommendations SET risk_level = ? WHERE finding_id = ?").run(data.risk_level, id);
      }

      // --- AUTOMATION: Send event to n8n ---
      await N8nService.sendEvent('finding.updated', {
        findingId: id,
        updates: data
      });
    });
  }

  static async deleteFinding(id: string) {
    return await db.transaction(async () => {
      await db.prepare("DELETE FROM recommendations WHERE finding_id = ?").run(id);
      await db.prepare("DELETE FROM audit_findings WHERE id = ?").run(id);

      // --- AUTOMATION: Send event to n8n ---
      await N8nService.sendEvent('finding.deleted', {
        findingId: id
      });
    });
  }

  /**
   * Changes the status of a finding with allowed transition enforcement and recommendation sync.
   *
   * Validates:
   * - Finding exists
   * - Transition is allowed per ALLOWED_FINDING_TRANSITIONS
   * - For Pending Approval→Closed: user must have APPROVE permission on AUDIT_FINDINGS
   *
   * Side effects:
   * - Syncs recommendation status via FINDING_TO_RECOMMENDATION_STATUS map (with retry up to 3 attempts)
   * - Sends notification to Manager/Admin on status change
   *
   * @param findingId - The ID of the finding to update
   * @param newStatus - The target status
   * @param userId - The ID of the user performing the action
   * @param userRole - The role of the user
   * @throws NotFoundError if finding does not exist
   * @throws ValidationError if transition is not allowed
   * @throws ForbiddenError if user lacks APPROVE permission for Pending Approval→Closed
   */
  static async changeFindingStatus(
    findingId: string,
    newStatus: string,
    userId: string,
    userRole: string
  ): Promise<{ syncSuccess: boolean }> {
    // 1. Validate finding exists
    const finding = await db.prepare(
      "SELECT * FROM audit_findings WHERE id = ?"
    ).get(findingId) as any;

    if (!finding) {
      throw new NotFoundError('الملاحظة غير موجودة / Finding not found');
    }

    // 2. Enforce allowed transitions
    const allowedTransitions = ALLOWED_FINDING_TRANSITIONS[finding.status];
    if (!allowedTransitions || !allowedTransitions.includes(newStatus)) {
      throw new ValidationError(
        `انتقال حالة غير صالح من "${finding.status}" إلى "${newStatus}" / ` +
        `Invalid status transition from "${finding.status}" to "${newStatus}"`
      );
    }

    // 3. For Pending Approval→Closed: require APPROVE permission
    if (finding.status === 'Pending Approval' && newStatus === 'Closed') {
      const rolePermissions = DEFAULT_PERMISSIONS[userRole as Role];
      const modulePermissions = rolePermissions?.[MODULES.AUDIT_FINDINGS] || [];

      if (!modulePermissions.includes(PERMISSIONS.APPROVE)) {
        throw new ForbiddenError(
          'ليس لديك صلاحية الاعتماد لإغلاق هذه الملاحظة / ' +
          'You do not have APPROVE permission to close this finding'
        );
      }
    }

    // 4. Update finding status
    await db.prepare(
      "UPDATE audit_findings SET status = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?"
    ).run(newStatus, findingId);

    // 5. Sync recommendation status with retry logic (up to 3 attempts)
    const recStatus = FINDING_TO_RECOMMENDATION_STATUS[newStatus];
    let syncSuccess = true;

    if (recStatus) {
      const MAX_RETRIES = 3;
      let lastError: Error | null = null;

      for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        try {
          await db.prepare(
            "UPDATE recommendations SET status = ?, updated_at = CURRENT_TIMESTAMP WHERE finding_id = ?"
          ).run(recStatus, findingId);
          lastError = null;
          break;
        } catch (err) {
          lastError = err as Error;
          console.error(
            `[AuditService] Recommendation sync attempt ${attempt}/${MAX_RETRIES} failed:`,
            (err as Error)?.message
          );
        }
      }

      if (lastError) {
        syncSuccess = false;
        console.error(
          '[AuditService] All recommendation sync attempts failed. Finding status updated but recommendation remains at last consistent state.'
        );
      }
    }

    // 6. Send notification to Manager/Admin on status change
    try {
      const adminIds = await NotificationService.getAdminIds();
      const managerIds = await db.prepare(
        `SELECT id FROM users WHERE role = ? AND status = 'active'`
      ).all(UserRole.MANAGER) as any[];
      const managerUserIds = managerIds.map((m: any) => m.id);

      const allTargetIds = [...new Set([...adminIds, ...managerUserIds])];

      if (allTargetIds.length > 0) {
        await NotificationService.create(
          allTargetIds,
          'finding_status_changed',
          JSON.stringify({
            key: 'notifications.findingStatusChanged',
            params: { title: finding.title, oldStatus: finding.status, newStatus }
          }),
          'AuditFindings',
          '/audit-findings',
          { actorId: userId, entityId: String(findingId), entityType: 'audit_findings' }
        );
      }
    } catch (notifError) {
      // Notification failure should not block status change
      console.error('[AuditService] Status change notification failed:', (notifError as any)?.message);
    }

    return { syncSuccess };
  }
}

import { db } from '../db/index';
import { NotFoundError, ValidationError, ForbiddenError, ConflictError } from '../utils/errors';
import { N8nService } from '../utils/n8nService';
import { UserRole } from '../../constants';
import { parsePaginationParams, computePaginationMeta } from '../utils/paginationService';

const ALLOWED_TRANSITIONS: Record<string, Record<string, { roles: string[] }>> = {
  'draft': {
    'in_progress': { roles: ['Auditor', UserRole.INTERNAL_AUDITOR, UserRole.MANAGER] }
  },
  'in_progress': {
    'review': { roles: ['Auditor', UserRole.INTERNAL_AUDITOR] }
  },
  'review': {
    'approved': { roles: [UserRole.MANAGER] },
    'in_progress': { roles: [UserRole.MANAGER] }
  },
  'approved': {
    'completed': { roles: [UserRole.MANAGER] }
  }
};

export class AuditTaskService {
  static async changeStatus(taskId: string, newStatus: string, userId: string, userRole: string, _db: any) {
    const database = _db || db;
    const task = await database.prepare('SELECT id, title, task_number, status, plan_id FROM audit_tasks WHERE id = ?').get(taskId) as any;
    
    if (!task) throw new NotFoundError('IAMS-NOT-001');
    
    const allowed = ALLOWED_TRANSITIONS[task.status.toLowerCase()]?.[newStatus.toLowerCase()];
    if (!allowed) throw new ValidationError('Invalid status transition');
    
    if (!allowed.roles.includes(userRole)) {
      throw new ForbiddenError('IAMS-PERM-001');
    }

    // in_progress -> review: block on open critical/high findings
    if (newStatus === 'review') {
      const blocking = await database.prepare(`
        SELECT id FROM audit_findings 
        WHERE audit_id = ? AND status = 'open' 
        AND risk_level IN ('Critical', 'High')
      `).all(task.plan_id);
      
      if (blocking.length > 0)
        throw new ValidationError('Open critical/high findings block this transition');
    }

    // review -> approved: block if any recommendation lacks an action plan
    if (newStatus === 'approved') {
      const incomplete = await database.prepare(`
        SELECT r.id FROM recommendations r
        JOIN audit_findings f ON r.finding_id = f.id
        WHERE f.audit_id = ? 
        AND (r.action_plan IS NULL OR r.action_plan = '' OR r.due_date IS NULL)
      `).all(task.plan_id);
      
      if (incomplete.length > 0)
        throw new ValidationError('All recommendations must have an action plan and due date');
    }

    const result = await database.prepare(
      'UPDATE audit_tasks SET status = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?'
    ).run(newStatus, taskId);

    // --- AUTOMATION: Send event to n8n ---
    await N8nService.sendEvent('audit_task.status_changed', {
      taskId: taskId,
      taskNumber: task.task_number,
      title: task.title,
      oldStatus: task.status,
      newStatus: newStatus,
      changedByUserId: userId
    }).catch(e => console.error("n8n send error", e));

    return result;
  }

  /**
   * Assigns multiple users to a task within a single transaction.
   *
   * Validates:
   * - assignedBy user has Manager or Admin role
   * - Task exists
   * - userIds is non-empty and has at most 50 entries
   * - All user IDs exist in the users table
   * - No duplicate assignments (UNIQUE constraint on task_id, user_id)
   *
   * @param taskId - The task to assign users to
   * @param userIds - Array of user IDs to assign (1-50)
   * @param assignedBy - The user performing the assignment
   * @returns Array of created assignment records
   */
  static async assignUsers(taskId: string, userIds: string[], assignedBy: string): Promise<{ assignments: any[] }> {
    // Validate userIds is non-empty and within limit
    if (!userIds || !Array.isArray(userIds) || userIds.length === 0) {
      throw new ValidationError('قائمة المستخدمين فارغة. يجب تحديد مستخدم واحد على الأقل', { field: 'userIds' });
    }
    if (userIds.length > 50) {
      throw new ValidationError('لا يمكن تعيين أكثر من 50 مستخدماً لمهمة واحدة', { field: 'userIds', max: 50 });
    }

    // Validate assignedBy role is Manager or Admin
    const assigner = await db.prepare(
      "SELECT id, role FROM users WHERE id = ?"
    ).get(assignedBy) as any;

    if (!assigner) {
      throw new ForbiddenError('المستخدم المُعيِّن غير موجود');
    }

    const allowedRoles = [UserRole.MANAGER, UserRole.ADMIN];
    if (!allowedRoles.includes(assigner.role)) {
      throw new ForbiddenError('لا تملك صلاحية تعيين مستخدمين للمهام. يجب أن يكون دورك مدير أو مسؤول');
    }

    // Validate task exists
    const task = await db.prepare(
      "SELECT id FROM audit_tasks WHERE id = ?"
    ).get(taskId) as any;

    if (!task) {
      throw new NotFoundError('المهمة غير موجودة');
    }

    // Validate all user IDs exist
    const uniqueUserIds = [...new Set(userIds)];
    const placeholders = uniqueUserIds.map(() => '?').join(', ');
    const existingUsers = await db.prepare(
      `SELECT id FROM users WHERE id IN (${placeholders})`
    ).all(...uniqueUserIds) as any[];

    if (existingUsers.length !== uniqueUserIds.length) {
      const existingIds = new Set(existingUsers.map((u: any) => u.id));
      const missingIds = uniqueUserIds.filter(id => !existingIds.has(id));
      throw new ValidationError(
        'بعض معرّفات المستخدمين غير موجودة',
        { missingUserIds: missingIds }
      );
    }

    // Insert assignments within a single transaction
    const doAssign = db.transaction(async () => {
      const assignments: any[] = [];

      for (const userId of uniqueUserIds) {
        // Check for existing assignment (UNIQUE constraint)
        const existing = await db.prepare(
          "SELECT id FROM task_assignments WHERE task_id = ? AND user_id = ?"
        ).get(taskId, userId) as any;

        if (existing) {
          throw new ConflictError(`المستخدم ${userId} معيّن مسبقاً لهذه المهمة`);
        }

        const result = await db.prepare(
          `INSERT INTO task_assignments (task_id, user_id, assigned_by)
           VALUES (?, ?, ?)
           RETURNING id, task_id, user_id, assigned_at, assigned_by`
        ).get(taskId, userId, assignedBy) as any;

        assignments.push(result);
      }

      return assignments;
    });

    const assignments = await doAssign();
    return { assignments };
  }

  /**
   * Removes a user assignment from a task.
   *
   * Validates:
   * - removedBy user has Manager or Admin role
   * - The assignment exists
   *
   * @param taskId - The task to unassign from
   * @param userId - The user to unassign
   * @param removedBy - The user performing the removal
   */
  static async unassignUser(taskId: string, userId: string, removedBy: string): Promise<{ success: boolean }> {
    // Validate removedBy role is Manager or Admin
    const remover = await db.prepare(
      "SELECT id, role FROM users WHERE id = ?"
    ).get(removedBy) as any;

    if (!remover) {
      throw new ForbiddenError('المستخدم غير موجود');
    }

    const allowedRoles = [UserRole.MANAGER, UserRole.ADMIN];
    if (!allowedRoles.includes(remover.role)) {
      throw new ForbiddenError('لا تملك صلاحية إزالة تعيين المستخدمين من المهام. يجب أن يكون دورك مدير أو مسؤول');
    }

    // Check assignment exists
    const assignment = await db.prepare(
      "SELECT id FROM task_assignments WHERE task_id = ? AND user_id = ?"
    ).get(taskId, userId) as any;

    if (!assignment) {
      throw new NotFoundError('التعيين غير موجود');
    }

    // Delete the assignment
    await db.prepare(
      "DELETE FROM task_assignments WHERE task_id = ? AND user_id = ?"
    ).run(taskId, userId);

    return { success: true };
  }

  /**
   * Gets all users assigned to a specific task.
   *
   * @param taskId - The task ID to get assignments for
   * @returns Array of assignment records with user details
   */
  static async getTaskAssignments(taskId: string): Promise<any[]> {
    const assignments = await db.prepare(
      `SELECT ta.id, ta.task_id, ta.user_id, ta.assigned_at, ta.assigned_by,
              u.name as user_name, u.username as user_username
       FROM task_assignments ta
       LEFT JOIN users u ON ta.user_id = u.id
       WHERE ta.task_id = ?
       ORDER BY ta.assigned_at ASC`
    ).all(taskId) as any[];

    return assignments;
  }

  static async getTasks(params: any = {}) {
    const { page, pageSize, offset } = parsePaginationParams(params);

    let query = `
      SELECT t.id, t.title, t.task_number, t.status, t.due_date, t.assigned_to,
             p.title as plan_title, u.name as assigned_name, e.name_en as audited_unit_name
      FROM audit_tasks t
      LEFT JOIN audit_plans p ON t.plan_id = p.id
      LEFT JOIN users u ON t.assigned_to = u.id
      LEFT JOIN org_entities e ON t.audited_unit_id = e.id
    `;
    
    let countQuery = "SELECT COUNT(*) as total FROM audit_tasks t";
    const args: any[] = [];
    let whereClause = "";

    if (params.plan_id) {
      whereClause = " WHERE t.plan_id = ?";
      args.push(params.plan_id);
    }

    query += whereClause + " ORDER BY t.created_at DESC LIMIT ? OFFSET ?";
    countQuery += whereClause;

    const [data, countRes] = await Promise.all([
      db.prepare(query).all(...args, pageSize, offset),
      db.prepare(countQuery).get(...args)
    ]) as [any[], any];

    const total = countRes?.total || 0;

    return {
      data,
      pagination: computePaginationMeta(page, pageSize, total)
    };
  }
}

import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
import crypto from 'crypto';
import { db } from '../db/index';
import { AuthError, ForbiddenError } from '../utils/errors';
import { UserRole } from '../../constants';

export class AuthService {
  static async login(usernameOrEmail: string, password: string, jwtSecret: string, JWT_PRIVATE_KEY: string, ipAddress?: string, userAgent?: string, rememberMe?: boolean) {
    return await db.transaction(async () => {
      // Support login by username or email, case-insensitive
      const user = await db.prepare(`
        SELECT * FROM users 
        WHERE LOWER(username) = LOWER(?::text) OR LOWER(email) = LOWER(?::text)
      `).get(usernameOrEmail, usernameOrEmail) as any;
      
      if (!user) {
        console.warn(`[AuthService] Login failed: User not found for "${usernameOrEmail}"`);
        throw new AuthError("Invalid credentials");
      }

      if (user.status === 'Suspended') {
        console.warn(`[AuthService] Login failed: Account suspended for "${user.username}"`);
        throw new ForbiddenError("Account suspended");
      }

      if (user.locked_until && new Date(user.locked_until) > new Date()) {
        console.warn(`[AuthService] Login failed: Account locked for "${user.username}"`);
        throw new ForbiddenError("Account locked");
      }

      if (!bcrypt.compareSync(password, user.password)) {
        console.warn(`[AuthService] Login failed: Invalid password for "${user.username}"`);
        await db.prepare("UPDATE users SET failed_attempts = failed_attempts + 1 WHERE id = ?::uuid").run(user.id);
        
        // Read threshold from settings (default 5 if not configured)
        let lockThreshold = 5;
        try {
          const settings = await db.prepare("SELECT failed_login_threshold FROM user_management_settings WHERE id = 1").get() as any;
          if (settings?.failed_login_threshold) lockThreshold = settings.failed_login_threshold;
        } catch (e) { /* use default */ }
        
        if (user.failed_attempts + 1 >= lockThreshold) {
          await db.prepare("UPDATE users SET locked_until = ?::timestamp WHERE id = ?::uuid").run(new Date(Date.now() + 15 * 60 * 1000).toISOString(), user.id);
          
          // Notify all admins about the locked account
          try {
            const admins = await db.prepare(`SELECT id FROM users WHERE role = '${UserRole.ADMIN}' AND status = 'active'`).all() as any[];
            for (const admin of admins) {
              await db.prepare("INSERT INTO notifications (user_id, event_type, description, related_module, link, status, actor_id, entity_type) VALUES (?::uuid, ?::text, ?::text, ?::text, ?::text, 'Unread', ?::uuid, 'user')")
                .run(admin.id, 'account_locked', `Account "${user.username}" locked after 5 failed login attempts (IP: ${ipAddress || 'Unknown'})`, 'Security', '/users', user.id);
            }
          } catch (notifErr) {
            console.error("[AuthService] Failed to send lockout notification:", notifErr);
          }
        }
        throw new AuthError("Invalid credentials");
      }

      await db.prepare("UPDATE users SET failed_attempts = 0, locked_until = NULL, last_login = CURRENT_TIMESTAMP WHERE id = ?::uuid").run(user.id);

      // Check password expiry
      let requiresPasswordChange = !!user.requires_password_change;
      if (!requiresPasswordChange && user.password_last_changed) {
        try {
          const settings = await db.prepare("SELECT password_expiry_days FROM user_management_settings WHERE id = 1").get() as any;
          const expiryDays = settings?.password_expiry_days || 90;
          if (expiryDays > 0) {
            const lastChanged = new Date(user.password_last_changed);
            const daysSinceChange = Math.floor((Date.now() - lastChanged.getTime()) / (1000 * 60 * 60 * 24));
            if (daysSinceChange >= expiryDays) {
              requiresPasswordChange = true;
              // Mark in DB so middleware also blocks
              await db.prepare("UPDATE users SET requires_password_change = 1 WHERE id = ?::uuid").run(user.id);
            }
          }
        } catch (e) {
          // If settings table doesn't exist or query fails, skip expiry check
          console.error("[AuthService] Password expiry check failed:", e);
        }
      }

      // Log login history
      try {
        await db.prepare("INSERT INTO login_history (user_id, ip_address, user_agent, status) VALUES (?::uuid, ?::text, ?::text, 'Success')")
          .run(user.id, ipAddress || 'Unknown', userAgent || 'Unknown');
      } catch (e) {
        console.error("[AuthService] Failed to log login history", e);
      }

      const token = jwt.sign(
        { id: user.id, username: user.username, role: user.role, session_version: user.session_version },
        JWT_PRIVATE_KEY,
        { algorithm: 'RS256', expiresIn: '15m' }
      );

      const refreshToken = jwt.sign(
        { id: user.id, username: user.username, role: user.role, session_version: user.session_version, rememberMe: !!rememberMe },
        JWT_PRIVATE_KEY,
        { algorithm: 'RS256', expiresIn: rememberMe ? '30d' : '8h' }
      );
      const sessionToken = crypto.randomBytes(64).toString('hex');
      
      const refreshExpiry = rememberMe ? new Date(Date.now() + 30 * 24 * 60 * 60 * 1000) : new Date(Date.now() + 8 * 60 * 60 * 1000); // 30 days or 8 hours
      // Insert into refresh_tokens for compatibility
      await db.prepare("INSERT INTO refresh_tokens (token, user_id, expires_at) VALUES (?::text, ?::uuid, ?::timestamp)").run(refreshToken, user.id, refreshExpiry.toISOString());
      
      // Insert into user_sessions for session management
      try {
        await db.prepare(`
          INSERT INTO user_sessions (user_id, session_token, refresh_token, ip_address, browser, status)
          VALUES (?::uuid, ?::text, ?::text, ?::text, ?::text, 'Active')
        `).run(user.id, sessionToken, refreshToken, ipAddress || 'Unknown', userAgent || 'Unknown');
      } catch (e) {
        console.error("[AuthService] Failed to create user session", e);
      }

      // Fetch user permissions from DB (role_permissions + user_permissions)
      let permissions: Array<{ module: string; action: string }> = [];
      try {
        permissions = await db.prepare(`
          SELECT p.module, p.action FROM permissions p
          JOIN role_permissions rp ON p.id = rp.permission_id
          WHERE rp.role_id = (SELECT role_id FROM users WHERE id = ?::uuid)
          UNION
          SELECT p.module, p.action FROM permissions p
          JOIN user_permissions up ON p.id = up.permission_id
          WHERE up.user_id = ?::uuid AND up.is_allowed = 1
        `).all(user.id, user.id) as Array<{ module: string; action: string }>;
      } catch (e) {
        console.error("[AuthService] Failed to fetch permissions during login:", e);
      }

      return {
        user: {
          id: user.id,
          username: user.username,
          role: user.role,
          name: user.name,
          requires_password_change: requiresPasswordChange,
          permissions
        },
        token,
        refreshToken
      };
    })();
  }

  static async logAudit(username: string, action: string, module: string, details: string) {
    const timestamp = new Date().toISOString();
    
    // Hash chaining for tamper-evident audit trail
    let previousHash = '0';
    try {
      const lastRecord = await db.prepare("SELECT hash FROM audit_trail WHERE hash IS NOT NULL ORDER BY timestamp DESC LIMIT 1").get() as any;
      if (lastRecord?.hash) {
        previousHash = lastRecord.hash;
      }
    } catch (e) {
      // If hash column doesn't exist yet, continue without it
    }
    
    const recordData = `${previousHash}|${username}|${action}|${module}|${details}|${timestamp}`;
    const hash = crypto.createHash('sha256').update(recordData).digest('hex');
    
    await db.prepare("INSERT INTO audit_trail (\"user\", action, module, details, hash, previous_hash, timestamp) VALUES (?::text, ?::text, ?::text, ?::text, ?::text, ?::text, ?::timestamp)")
      .run(username, action, module, details, hash, previousHash, timestamp);
  }
}

import { db } from '../db/index';
import { NotFoundError, ValidationError } from '../utils/errors';
import { AppCodeGenerator } from '../utils/AppCodeGenerator';
import { N8nService } from '../utils/n8nService';
import { computePaginationMeta } from '../utils/paginationService';
import crypto from 'crypto';

export class BaseService {
  protected static db = db;

  static async logAudit(username: string, action: string, module: string, details: string) {
    try {
      const timestamp = new Date().toISOString();
      
      // Hash chaining for tamper-evident audit trail
      let previousHash = '0';
      try {
        const lastRecord = await this.db.prepare("SELECT hash FROM audit_trail WHERE hash IS NOT NULL ORDER BY timestamp DESC LIMIT 1").get() as any;
        if (lastRecord?.hash) {
          previousHash = lastRecord.hash;
        }
      } catch (e) {
        // If hash column doesn't exist yet, continue without it
      }
      
      const recordData = `${previousHash}|${username}|${action}|${module}|${details}|${timestamp}`;
      const hash = crypto.createHash('sha256').update(recordData).digest('hex');
      
      await this.db.prepare("INSERT INTO audit_trail (\"user\", action, module, details, hash, previous_hash, timestamp) VALUES (?::text, ?::text, ?::text, ?::text, ?::text, ?::text, ?::timestamp)")
        .run(username, action, module, details, hash, previousHash, timestamp);
    } catch (error) {
      console.error("[System Log Error] Failed to insert audit trail:", error);
    }
  }

  protected static sanitizeBody(body: any) {
    const sanitized = { ...body };
    Object.keys(sanitized).forEach(key => {
      // Convert empty strings to null for fields that are likely UUIDs or foreign keys
      if (sanitized[key] === "" && (key.endsWith('_id') || key === 'id' || key.includes('uuid'))) {
        sanitized[key] = null;
      }
    });
    return sanitized;
  }

  static async findAll(tableName: string, options: { page?: number; pageSize?: number; orderBy?: string; where?: Record<string, any>; select?: string[]; includeDeleted?: boolean } = {}) {
    const { page = 1, pageSize = 10, orderBy = 'id DESC', where = {}, select, includeDeleted = false } = options;
    const offset = (page - 1) * pageSize;

    const validatedTable = this.db.validateIdentifier(tableName);
    
    // Validate orderBy to prevent SQL injection
    const orderParts = (orderBy || 'id').trim().split(/\s+/);
    const orderColumn = orderParts[0] || 'id';
    const orderDirection = (orderParts[1] || 'DESC').toUpperCase();
    
    // Strict regex for column name
    if (orderColumn && !/^[a-zA-Z0-9_]+$/.test(orderColumn)) {
      throw new ValidationError(`Invalid orderBy column name: ${orderColumn}`);
    }
    // Strict match for direction
    if (orderDirection !== 'ASC' && orderDirection !== 'DESC') {
      throw new ValidationError(`Invalid orderBy direction: ${orderDirection}`);
    }
    // Final safe orderBy string
    const safeOrderBy = `${orderColumn} ${orderDirection}`;

    // Safe select columns
    const safeSelect = select && select.length > 0
      ? select.filter(s => /^[a-zA-Z0-9_]+$/.test(s)).join(', ')
      : '*';

    let whereClause = '';
    const whereValues: any[] = [];
    const { search, ...restWhere } = where;
    const whereKeys = Object.keys(restWhere);
    
    if (whereKeys.length > 0) {
      whereClause = 'WHERE ' + whereKeys.map((key, i) => `${this.db.validateIdentifier(key)} = ?`).join(' AND ');
      whereValues.push(...Object.values(restWhere));
    }

    // Exclude soft-deleted records from standard queries (Requirement 8.2)
    if (!includeDeleted) {
      if (whereClause) {
        whereClause += ' AND deleted_at IS NULL';
      } else {
        whereClause = 'WHERE deleted_at IS NULL';
      }
    }

    // Add search functionality if provided
    if (search && typeof search === 'string' && search.trim() !== '') {
      const searchPattern = `%${search.trim()}%`;
      // We'll try to find common text columns to search on based on the table name
      const searchColumns: Record<string, string[]> = {
        audit_plans: ['title', 'plan_code', 'department', 'lead_auditor'],
        audit_tasks: ['title', 'task_number', 'audit_type'],
        audit_programs: ['program_title', 'program_code', 'audit_area'],
        audit_findings: ['title', 'description', 'finding_number'],
        recommendations: ['rec_number', 'department', 'action_plan'],
        risk_register: ['risk_id', 'description', 'owner'],
        compliance_items: ['ref_number', 'title', 'notes']
      };

      const tableSearchCols = searchColumns[tableName] || ['title', 'name', 'description'].filter(c => c); // Fallback
      
      if (tableSearchCols.length > 0) {
        const searchClause = '(' + tableSearchCols.map(col => `${this.db.validateIdentifier(col)} LIKE ?`).join(' OR ') + ')';
        if (whereClause) {
          whereClause += ` AND ${searchClause}`;
        } else {
          whereClause = `WHERE ${searchClause}`;
        }
        tableSearchCols.forEach(() => whereValues.push(searchPattern));
      }
    }

    const countRes = await this.db.prepare(`SELECT COUNT(*) as total FROM ${validatedTable} ${whereClause}`).get(...whereValues);
    const total = countRes?.total || 0;

    const query = `SELECT ${safeSelect} FROM ${validatedTable} ${whereClause} ORDER BY ${safeOrderBy} LIMIT ? OFFSET ?`;
    const data = await this.db.prepare(query).all(...whereValues, pageSize, offset);

    return {
      data,
      pagination: computePaginationMeta(page, pageSize, total)
    };
  }

  static async findById(tableName: string, id: string | number, options: { includeDeleted?: boolean } = {}) {
    const { includeDeleted = false } = options;
    const validatedTable = this.db.validateIdentifier(tableName);
    const deletedFilter = includeDeleted ? '' : ' AND deleted_at IS NULL';
    const item = await this.db.prepare(`SELECT * FROM ${validatedTable} WHERE id = ?${deletedFilter}`).get(id);
    if (!item) {
      throw new NotFoundError(`${tableName} item with ID ${id} not found`);
    }
    return item;
  }

  static async create(tableName: string, data: any) {
    return await db.transaction(async () => {
      const body = this.sanitizeBody(data);
      // Only delete internal fields, ensure plan_code stays if provided
      const restrictedColumns = ['id', 'created_at', 'updated_at'];
      restrictedColumns.forEach(col => {
        if (col in body) delete body[col];
      });

      // Determine relevant code column
      const codeColumns: Record<string, string> = {
        audit_plans: 'plan_code',
        audit_programs: 'program_code',
        audit_tasks: 'task_number',
        audit_findings: 'finding_number',
        recommendations: 'rec_number',
        risk_register: 'risk_id',
        compliance_items: 'ref_number'
      };
      
      const codeCol = codeColumns[tableName];
      if (codeCol && !body[codeCol]) {
         let code: string | null = null;
         if (tableName === 'audit_findings' && body.audit_id) {
           code = await AppCodeGenerator.generateFindingCode(body.audit_id);
         } else {
           code = await AppCodeGenerator.generateCode(tableName, body.department);
         }
         if (code) body[codeCol] = code;
      }

      const keys = Object.keys(body).map(k => this.db.validateIdentifier(k));
      const values = Object.values(body);

      if (keys.length === 0) {
        throw new ValidationError("No data provided for creation");
      }

      const placeholders = keys.map(() => "?").join(",");
      const validatedTable = this.db.validateIdentifier(tableName);
      const stmt = this.db.prepare(`INSERT INTO ${validatedTable} (${keys.join(",")}) VALUES (${placeholders})`);
      const info = await stmt.run(...values) as any;

      // --- AUTOMATION: Send event to n8n ---
      await N8nService.sendEvent(`${tableName}.created`, {
        id: info.lastInsertRowid,
        ...body
      }).catch((e) => console.error("N8n send event failed", e));

      return { id: info.lastInsertRowid, ...body };
    })();
  }

  static async update(tableName: string, id: string | number, data: any) {
    return await db.transaction(async () => {
      const body = this.sanitizeBody(data);
      
      // Strict exclusion of immutable/system fields to prevent Mass Assignment
      const immutableFields = [
        'id', 'created_at', 'updated_at', 
        'plan_code', 'program_code', 'task_number', 'finding_number', 
        'rec_number', 'risk_id', 'employee_id'
      ];
      immutableFields.forEach(col => delete body[col]);

      const keys = Object.keys(body).map(k => this.db.validateIdentifier(k));
      const values = Object.values(body);

      if (keys.length === 0) {
        throw new ValidationError("No data provided for update");
      }

      const setClause = keys.map(k => `${k} = ?`).join(",");
      const validatedTable = this.db.validateIdentifier(tableName);
      
      // Explicitly update updated_at timestamp
      const updateQuery = `UPDATE ${validatedTable} SET ${setClause}, updated_at = CURRENT_TIMESTAMP WHERE id = ? RETURNING id`;
      const updatedRow = await this.db.prepare(updateQuery).get(...values, id);

      if (!updatedRow) {
        throw new NotFoundError(`${tableName} item with ID ${id} not found`);
      }

      // --- AUTOMATION: Send event to n8n ---
      await N8nService.sendEvent(`${tableName}.updated`, {
        id,
        ...body
      }).catch((e) => console.error("N8n send event failed", e));

      return { id, ...body };
    })();
  }

  static async delete(tableName: string, id: string | number) {
    const validatedTable = this.db.validateIdentifier(tableName);
    await this.db.prepare(`DELETE FROM ${validatedTable} WHERE id = ?`).run(id);
    
    // --- AUTOMATION: Send event to n8n ---
    await N8nService.sendEvent(`${tableName}.deleted`, {
      id
    }).catch((e) => console.error("N8n send event failed", e));
    
    return true;
  }
}

