import { db } from '../db/index';
import { BaseService } from './BaseService';
import { ValidationError } from '../utils/errors';

/**
 * Supported bulk operation types.
 */
export type BulkOperation = 'create' | 'update' | 'delete';

/**
 * A single item in a bulk operation request.
 */
export interface BulkItem {
  id?: string | number;
  [key: string]: any;
}

/**
 * Per-item result in the bulk operation response.
 */
export interface BulkItemResult {
  index: number;
  id?: string | number;
  success: boolean;
  error?: string;
}

/**
 * Validation error for a single item in the batch.
 */
export interface BulkItemValidationError {
  index: number;
  errors: string[];
}

/**
 * Response from a successful bulk operation.
 */
export interface BulkOperationResponse {
  processed: number;
  success: number;
  failed: number;
  details: BulkItemResult[];
}

/**
 * Allowed resource tables for bulk operations.
 * Maps route resource names to database table names.
 */
export const BULK_ALLOWED_RESOURCES: Record<string, string> = {
  'audit-plans': 'audit_plans',
  'audit-tasks': 'audit_tasks',
  'audit-programs': 'audit_programs',
  'audit-procedures': 'audit_procedures',
  'audit-evidence': 'audit_evidence',
  'risk-register': 'risk_register',
  'fraud-log': 'fraud_log',
  'central-bank-instructions': 'central_bank_instructions',
  'law-bank': 'law_bank',
  'audit-reports': 'audit_reports',
  'audit-findings': 'audit_findings',
  'recommendations': 'recommendations',
  'compliance-items': 'compliance_items',
};

/** Minimum batch size */
export const MIN_BATCH_SIZE = 1;

/** Maximum batch size */
export const MAX_BATCH_SIZE = 100;

/**
 * Bulk Operations Service for the AL-SAQI system.
 *
 * Processes multiple create/update/delete operations in a single transactional request.
 * Validates all items before processing; rejects entire batch on validation failure.
 * Processes all valid items in a single transaction; rolls back on any processing failure.
 *
 * Requirements: 16.1, 16.2, 16.3, 16.4, 16.5, 16.6
 */
export class BulkOperationsService extends BaseService {
  /**
   * Validates the batch size is within the allowed range (1-100).
   *
   * @param items - The items array to validate
   * @throws ValidationError if batch size is outside the allowed range
   */
  static validateBatchSize(items: any[]): void {
    if (!Array.isArray(items) || items.length < MIN_BATCH_SIZE || items.length > MAX_BATCH_SIZE) {
      throw new ValidationError(
        `Batch size must be between ${MIN_BATCH_SIZE} and ${MAX_BATCH_SIZE} items`,
        { min: MIN_BATCH_SIZE, max: MAX_BATCH_SIZE, received: Array.isArray(items) ? items.length : 0 }
      );
    }
  }

  /**
   * Resolves a resource route name to a database table name.
   *
   * @param resource - The resource route name (e.g., 'audit-plans')
   * @returns The database table name
   * @throws ValidationError if the resource is not allowed
   */
  static resolveTable(resource: string): string {
    const tableName = BULK_ALLOWED_RESOURCES[resource];
    if (!tableName) {
      throw new ValidationError(
        `Resource '${resource}' is not supported for bulk operations`,
        { allowedResources: Object.keys(BULK_ALLOWED_RESOURCES) }
      );
    }
    return tableName;
  }

  /**
   * Validates all items in the batch before processing.
   * Returns per-item validation errors if any item fails.
   *
   * @param operation - The bulk operation type
   * @param items - The items to validate
   * @param tableName - The target database table
   * @returns Array of validation errors (empty if all valid)
   */
  static validateItems(
    operation: BulkOperation,
    items: BulkItem[],
    tableName: string
  ): BulkItemValidationError[] {
    const errors: BulkItemValidationError[] = [];

    for (let i = 0; i < items.length; i++) {
      const item = items[i];
      const itemErrors: string[] = [];

      if (typeof item !== 'object' || item === null || Array.isArray(item)) {
        itemErrors.push('Item must be a non-null object');
        errors.push({ index: i, errors: itemErrors });
        continue;
      }

      switch (operation) {
        case 'create':
          // For create, item must have at least one field (excluding id)
          const createFields = Object.keys(item).filter(k => k !== 'id');
          if (createFields.length === 0) {
            itemErrors.push('Item must have at least one field for creation');
          }
          break;

        case 'update':
          // For update, item must have an id and at least one other field
          if (!item.id) {
            itemErrors.push('Item must have an "id" field for update operations');
          }
          const updateFields = Object.keys(item).filter(k => k !== 'id');
          if (updateFields.length === 0) {
            itemErrors.push('Item must have at least one field to update besides "id"');
          }
          break;

        case 'delete':
          // For delete, item must have an id
          if (!item.id) {
            itemErrors.push('Item must have an "id" field for delete operations');
          }
          break;

        default:
          itemErrors.push(`Unsupported operation: ${operation}`);
      }

      if (itemErrors.length > 0) {
        errors.push({ index: i, errors: itemErrors });
      }
    }

    return errors;
  }

  /**
   * Executes a bulk operation within a single database transaction.
   * All items are processed; if any fails, the entire transaction is rolled back.
   *
   * @param resource - The resource route name
   * @param operation - The bulk operation type
   * @param items - The items to process
   * @param username - The username performing the operation (for audit logging)
   * @returns The bulk operation response with per-item status
   * @throws ValidationError if batch size is invalid, resource is unsupported, or items fail validation
   *
   * Requirements: 16.1, 16.2, 16.3, 16.4, 16.5, 16.6
   */
  static async execute(
    resource: string,
    operation: BulkOperation,
    items: BulkItem[],
    username: string
  ): Promise<BulkOperationResponse> {
    // Validate batch size (Requirement 16.3)
    this.validateBatchSize(items);

    // Resolve resource to table name
    const tableName = this.resolveTable(resource);

    // Validate all items before processing (Requirement 16.1, 16.2)
    const validationErrors = this.validateItems(operation, items, tableName);
    if (validationErrors.length > 0) {
      throw new ValidationError(
        'Batch validation failed: one or more items have errors',
        { items: validationErrors }
      );
    }

    // Process all items in a single transaction (Requirement 16.1, 16.4)
    const details: BulkItemResult[] = await db.transaction(async () => {
      const results: BulkItemResult[] = [];

      for (let i = 0; i < items.length; i++) {
        const item = items[i];

        try {
          switch (operation) {
            case 'create': {
              const result = await this.processCreate(tableName, item);
              results.push({ index: i, id: result.id, success: true });
              break;
            }
            case 'update': {
              const { id, ...data } = item;
              await this.processUpdate(tableName, id!, data);
              results.push({ index: i, id: id!, success: true });
              break;
            }
            case 'delete': {
              await this.processDelete(tableName, item.id!);
              results.push({ index: i, id: item.id!, success: true });
              break;
            }
          }
        } catch (error: any) {
          // If any item fails during processing, throw to trigger rollback (Requirement 16.4)
          throw new Error(
            `Processing failed at item index ${i}: ${error.message || 'Unknown error'}`
          );
        }
      }

      return results;
    })();

    // Record single audit log entry for the bulk operation (Requirement 16.6)
    await this.logAudit(
      username,
      `Bulk ${operation}`,
      resource,
      `Bulk ${operation} on ${tableName}: ${items.length} items processed`
    );

    // Return response (Requirement 16.5)
    const successCount = details.filter(d => d.success).length;
    return {
      processed: details.length,
      success: successCount,
      failed: details.length - successCount,
      details,
    };
  }

  /**
   * Processes a single create operation within the transaction.
   */
  private static async processCreate(tableName: string, data: BulkItem): Promise<{ id: string | number }> {
    const body = this.sanitizeBody({ ...data });
    // Remove system fields
    const restrictedColumns = ['id', 'created_at', 'updated_at'];
    restrictedColumns.forEach(col => {
      if (col in body) delete body[col];
    });

    const keys = Object.keys(body).map(k => this.db.validateIdentifier(k));
    const values = Object.values(body);

    if (keys.length === 0) {
      throw new ValidationError('No data provided for creation');
    }

    const placeholders = keys.map(() => '?').join(',');
    const validatedTable = this.db.validateIdentifier(tableName);
    const info = await this.db.prepare(
      `INSERT INTO ${validatedTable} (${keys.join(',')}) VALUES (${placeholders})`
    ).run(...values) as any;

    return { id: info.lastInsertRowid };
  }

  /**
   * Processes a single update operation within the transaction.
   */
  private static async processUpdate(tableName: string, id: string | number, data: Record<string, any>): Promise<void> {
    const body = this.sanitizeBody({ ...data });
    // Remove immutable fields
    const immutableFields = [
      'id', 'created_at', 'updated_at',
      'plan_code', 'program_code', 'task_number', 'finding_number',
      'rec_number', 'risk_id', 'employee_id'
    ];
    immutableFields.forEach(col => delete body[col]);

    const keys = Object.keys(body).map(k => this.db.validateIdentifier(k));
    const values = Object.values(body);

    if (keys.length === 0) {
      throw new ValidationError('No data provided for update');
    }

    const setClause = keys.map(k => `${k} = ?`).join(',');
    const validatedTable = this.db.validateIdentifier(tableName);
    const result = await this.db.prepare(
      `UPDATE ${validatedTable} SET ${setClause}, updated_at = CURRENT_TIMESTAMP WHERE id = ? AND deleted_at IS NULL RETURNING id`
    ).get(...values, id);

    if (!result) {
      throw new Error(`Record with ID ${id} not found or is deleted`);
    }
  }

  /**
   * Processes a single delete operation within the transaction.
   * Uses soft delete (sets deleted_at) to be consistent with the system's soft delete approach.
   */
  private static async processDelete(tableName: string, id: string | number): Promise<void> {
    const validatedTable = this.db.validateIdentifier(tableName);
    const now = new Date().toISOString();

    const result = await this.db.prepare(
      `UPDATE ${validatedTable} SET deleted_at = ?::timestamptz WHERE id = ? AND deleted_at IS NULL RETURNING id`
    ).get(now, id);

    if (!result) {
      throw new Error(`Record with ID ${id} not found or already deleted`);
    }
  }
}

import axios, { AxiosError } from 'axios';
import { db } from '../db/index.js';
import logger from '../utils/logger.js';

/**
 * Circuit Breaker States
 */
export enum CircuitState {
  CLOSED = 'CLOSED',
  OPEN = 'OPEN',
  HALF_OPEN = 'HALF_OPEN',
}

/**
 * Configuration for the circuit breaker
 */
export interface CircuitBreakerConfig {
  /** Maximum retry attempts before giving up (default: 3) */
  maxRetries: number;
  /** Initial backoff delay in ms (default: 1000) */
  initialBackoffMs: number;
  /** Number of consecutive failures to open the circuit (default: 5) */
  failureThreshold: number;
  /** Time window in ms for counting failures (default: 60000) */
  failureWindowMs: number;
  /** Health probe interval in ms while circuit is open (default: 30000) */
  healthProbeIntervalMs: number;
  /** Timeout for health probe in ms (default: 5000) */
  healthProbeTimeoutMs: number;
  /** Request timeout in ms (default: 5000) */
  requestTimeoutMs: number;
}

const DEFAULT_CONFIG: CircuitBreakerConfig = {
  maxRetries: 3,
  initialBackoffMs: 1000,
  failureThreshold: 5,
  failureWindowMs: 60000,
  healthProbeIntervalMs: 30000,
  healthProbeTimeoutMs: 5000,
  requestTimeoutMs: 5000,
};

/**
 * Dead Letter Queue entry
 */
export interface DeadLetterEntry {
  event_type: string;
  payload: string;
  failure_reason: string;
  retry_count: number;
}

/**
 * Circuit Breaker with retry logic and dead letter queue for external service calls.
 *
 * Implements:
 * - Retry with exponential backoff (1s start, 3 max attempts)
 * - Circuit breaker: opens after 5 consecutive failures in 60s window
 * - While open: stores events in dead_letter_queue, returns success for core operation
 * - Health probe every 30s while open; closes after 1 successful probe within 5s
 */
export class CircuitBreaker {
  private _state: CircuitState = CircuitState.CLOSED;
  private _failures: number[] = []; // timestamps of consecutive failures
  private _consecutiveFailures: number = 0;
  private _healthProbeTimer: ReturnType<typeof setInterval> | null = null;
  private _config: CircuitBreakerConfig;
  private _serviceUrl: string | null;
  private _serviceHeaders: Record<string, string>;

  constructor(
    serviceUrl: string | null,
    headers: Record<string, string> = {},
    config: Partial<CircuitBreakerConfig> = {}
  ) {
    this._serviceUrl = serviceUrl;
    this._serviceHeaders = headers;
    this._config = { ...DEFAULT_CONFIG, ...config };
  }

  get state(): CircuitState {
    return this._state;
  }

  get consecutiveFailures(): number {
    return this._consecutiveFailures;
  }

  /**
   * Execute an external service call with retry and circuit breaker logic.
   * 
   * @param eventType - The type of event being sent
   * @param payload - The event payload
   * @returns true if the event was sent successfully, false if it was stored in the dead letter queue
   */
  async call(eventType: string, payload: any): Promise<boolean> {
    // If service URL is not configured, skip silently
    if (!this._serviceUrl) {
      logger.warn(`[CircuitBreaker] Service URL not configured. Skipping event: ${eventType}`);
      return true;
    }

    // If circuit is open, store in dead letter queue immediately
    if (this._state === CircuitState.OPEN) {
      logger.warn(`[CircuitBreaker] Circuit is OPEN. Storing event in dead letter queue: ${eventType}`);
      await this.storeInDeadLetterQueue(eventType, payload, 'Circuit breaker is open');
      return false;
    }

    // Attempt the call with retries
    let lastError: string = '';
    for (let attempt = 1; attempt <= this._config.maxRetries; attempt++) {
      try {
        await this.executeRequest(eventType, payload);
        // Success - reset failure count
        this._consecutiveFailures = 0;
        this._failures = [];
        
        // If we were in HALF_OPEN, close the circuit
        if (this._state === CircuitState.HALF_OPEN) {
          this.closeCircuit();
        }
        
        return true;
      } catch (error: any) {
        lastError = this.extractErrorReason(error);
        logger.warn(
          `[CircuitBreaker] Attempt ${attempt}/${this._config.maxRetries} failed for event ${eventType}: ${lastError}`
        );

        // If not the last attempt, wait with exponential backoff
        if (attempt < this._config.maxRetries) {
          const backoffMs = this._config.initialBackoffMs * Math.pow(2, attempt - 1);
          await this.sleep(backoffMs);
        }
      }
    }

    // All retries exhausted - record failure
    this.recordFailure();
    
    // Store in dead letter queue
    await this.storeInDeadLetterQueue(eventType, payload, lastError);
    
    logger.error(
      `[CircuitBreaker] All ${this._config.maxRetries} attempts failed for event ${eventType}. Stored in dead letter queue.`
    );

    return false;
  }

  /**
   * Execute the actual HTTP request to the external service.
   */
  private async executeRequest(eventType: string, payload: any): Promise<void> {
    const response = await axios.post(
      this._serviceUrl!,
      {
        event: eventType,
        timestamp: new Date().toISOString(),
        data: payload,
      },
      {
        headers: this._serviceHeaders,
        timeout: this._config.requestTimeoutMs,
      }
    );

    // Treat 5xx responses as failures
    if (response.status >= 500) {
      throw new Error(`Server error: HTTP ${response.status}`);
    }
  }

  /**
   * Record a failure and check if the circuit should open.
   */
  private recordFailure(): void {
    const now = Date.now();
    this._consecutiveFailures++;
    this._failures.push(now);

    // Remove failures outside the window
    const windowStart = now - this._config.failureWindowMs;
    this._failures = this._failures.filter(t => t >= windowStart);

    // Check if we should open the circuit
    if (this._consecutiveFailures >= this._config.failureThreshold) {
      this.openCircuit();
    }
  }

  /**
   * Open the circuit breaker - stop calling the external service.
   */
  private openCircuit(): void {
    if (this._state === CircuitState.OPEN) return;

    this._state = CircuitState.OPEN;
    logger.error(
      `[CircuitBreaker] Circuit OPENED after ${this._consecutiveFailures} consecutive failures.`
    );

    // Start health probing
    this.startHealthProbe();
  }

  /**
   * Close the circuit breaker - resume normal operation.
   */
  private closeCircuit(): void {
    this._state = CircuitState.CLOSED;
    this._consecutiveFailures = 0;
    this._failures = [];
    this.stopHealthProbe();
    logger.info('[CircuitBreaker] Circuit CLOSED. External service is healthy.');
  }

  /**
   * Start periodic health probes while the circuit is open.
   */
  private startHealthProbe(): void {
    this.stopHealthProbe(); // Clear any existing timer

    this._healthProbeTimer = setInterval(async () => {
      await this.performHealthProbe();
    }, this._config.healthProbeIntervalMs);
  }

  /**
   * Stop the health probe timer.
   */
  private stopHealthProbe(): void {
    if (this._healthProbeTimer) {
      clearInterval(this._healthProbeTimer);
      this._healthProbeTimer = null;
    }
  }

  /**
   * Perform a single health probe to the external service.
   * If successful within the timeout, close the circuit.
   */
  async performHealthProbe(): Promise<boolean> {
    if (!this._serviceUrl) return false;

    try {
      this._state = CircuitState.HALF_OPEN;
      logger.info('[CircuitBreaker] Performing health probe...');

      await axios.get(this._serviceUrl, {
        headers: this._serviceHeaders,
        timeout: this._config.healthProbeTimeoutMs,
      });

      // Probe succeeded - close the circuit
      this.closeCircuit();
      return true;
    } catch (error: any) {
      // Probe failed - keep circuit open
      this._state = CircuitState.OPEN;
      logger.warn(`[CircuitBreaker] Health probe failed: ${this.extractErrorReason(error)}`);
      return false;
    }
  }

  /**
   * Store a failed event in the dead_letter_queue table.
   */
  async storeInDeadLetterQueue(
    eventType: string,
    payload: any,
    failureReason: string
  ): Promise<void> {
    try {
      const payloadStr = typeof payload === 'string' ? payload : JSON.stringify(payload);
      await db.prepare(
        `INSERT INTO dead_letter_queue (event_type, payload, failure_reason, retry_count) VALUES (?, ?, ?, ?)`
      ).run(eventType, payloadStr, failureReason, 0);
      
      logger.info(`[CircuitBreaker] Event stored in dead letter queue: ${eventType}`);
    } catch (dbError: any) {
      // If we can't even store in the DLQ, log to stderr but don't throw
      logger.error(
        `[CircuitBreaker] CRITICAL: Failed to store event in dead letter queue: ${dbError.message}`
      );
    }
  }

  /**
   * Extract a human-readable error reason from an error object.
   */
  private extractErrorReason(error: any): string {
    if (axios.isAxiosError(error)) {
      const axiosErr = error as AxiosError;
      if (axiosErr.code === 'ECONNABORTED' || axiosErr.code === 'ETIMEDOUT') {
        return `Connection timeout (>${this._config.requestTimeoutMs}ms)`;
      }
      if (axiosErr.code === 'ECONNREFUSED') {
        return 'Connection refused';
      }
      if (axiosErr.code === 'ENOTFOUND') {
        return 'Host not found';
      }
      if (axiosErr.response) {
        return `HTTP ${axiosErr.response.status}: ${axiosErr.response.statusText}`;
      }
      return `Network error: ${axiosErr.message}`;
    }
    return error?.message || 'Unknown error';
  }

  /**
   * Check if an error is a retryable failure (5xx, timeout, network error).
   */
  static isRetryableError(error: any): boolean {
    if (axios.isAxiosError(error)) {
      const axiosErr = error as AxiosError;
      // Network errors (timeout, connection refused, etc.)
      if (!axiosErr.response) return true;
      // 5xx server errors
      if (axiosErr.response.status >= 500) return true;
    }
    return false;
  }

  /**
   * Utility sleep function for backoff delays.
   */
  private sleep(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  /**
   * Clean up resources (stop health probe timer).
   */
  destroy(): void {
    this.stopHealthProbe();
  }

  /**
   * Reset the circuit breaker to its initial state (useful for testing).
   */
  reset(): void {
    this._state = CircuitState.CLOSED;
    this._consecutiveFailures = 0;
    this._failures = [];
    this.stopHealthProbe();
  }
}

// Singleton instance for the n8n webhook service
let n8nCircuitBreaker: CircuitBreaker | null = null;

/**
 * Get or create the singleton circuit breaker instance for n8n webhook calls.
 */
export function getN8nCircuitBreaker(): CircuitBreaker {
  if (!n8nCircuitBreaker) {
    const webhookUrl = process.env.N8N_WEBHOOK_URL || null;
    const apiKey = process.env.N8N_WEBHOOK_API_KEY || null;

    const headers: Record<string, string> = {};
    if (apiKey) {
      headers['X-N8N-API-KEY'] = apiKey;
      headers['Authorization'] = `Bearer ${apiKey}`;
    }

    n8nCircuitBreaker = new CircuitBreaker(webhookUrl, headers);
  }
  return n8nCircuitBreaker;
}

/**
 * Reset the singleton instance (useful for testing).
 */
export function resetN8nCircuitBreaker(): void {
  if (n8nCircuitBreaker) {
    n8nCircuitBreaker.destroy();
    n8nCircuitBreaker = null;
  }
}

import { db } from '../db/index';
import { NotFoundError } from '../utils/errors';
import { N8nService } from '../utils/n8nService';

export class CoiService {
  static async getAll() {
    return await db.prepare("SELECT * FROM conflict_of_interest ORDER BY declaration_date DESC").all();
  }

  static async create(userId: string | number, username: string, data: any) {
    const { description, related_party } = data;
    const stmt = db.prepare(`INSERT INTO conflict_of_interest (user_id, user_name, declaration_date, description, related_party) VALUES (?, ?, ?, ?, ?)`);
    const info = await stmt.run(userId, username, new Date().toISOString().split('T')[0], description, related_party);
    
    await db.prepare("INSERT INTO audit_trail (user, action, module, details) VALUES (?::text, ?::text, ?::text, ?::text)")
      .run(username, 'Created Conflict of Interest Declaration', 'Governance', `ID: ${info.lastInsertRowid}`);
      
    // --- AUTOMATION: Send event to n8n ---
    await N8nService.sendEvent('coi.created', {
      id: info.lastInsertRowid,
      userId,
      username,
      description,
      relatedParty: related_party
    });

    return { id: info.lastInsertRowid };
  }

  static async updateStatus(id: string | number, data: any, username: string) {
    const { status, reviewer_notes } = data;
    const stmt = db.prepare(`UPDATE conflict_of_interest SET status = ?, reviewer_notes = ? WHERE id = ?`);
    await stmt.run(status, reviewer_notes, id);
    
    await db.prepare("INSERT INTO audit_trail (user, action, module, details) VALUES (?::text, ?::text, ?::text, ?::text)")
      .run(username, 'Updated Conflict of Interest Status', 'Governance', `ID: ${id}`);
      
    // --- AUTOMATION: Send event to n8n ---
    await N8nService.sendEvent('coi.status_changed', {
      id,
      status,
      reviewerNotes: reviewer_notes,
      updatedBy: username
    });

    return true;
  }
}

import { db } from '../db/index';
import { NotificationService } from './NotificationService';
import { ValidationError, NotFoundError } from '../utils/errors';

export class CommentService {
  static async getComments(type: string, id: string | number) {
    return await db.prepare(`
      SELECT c.*, u.name as user_name 
      FROM comments c
      JOIN users u ON c.user_id = u.id
      WHERE c.related_type = ? AND c.related_id = ?
      ORDER BY c.created_at ASC
    `).all(type, id);
  }

  static async createComment(userId: string | number, data: any) {
    const { related_type, related_id, content } = data;
    const stmt = db.prepare(`
      INSERT INTO comments (related_type, related_id, user_id, content)
      VALUES (?, ?, ?, ?)
    `);
    const result = await stmt.run(related_type, related_id, userId, content);
    return { id: result.lastInsertRowid };
  }

  /**
   * Create a comment on an audit finding with targeted notification logic.
   * 
   * Notification rules:
   * 1. If commenter ≠ finding creator → notify finding creator
   * 2. If commenter = finding creator AND previous different commenter exists → notify last different commenter
   * 3. If commenter = finding creator AND no previous different commenter → no notification
   * 
   * Requirements: 9.1, 9.2, 9.3, 9.4, 9.5, 9.6
   */
  static async createFindingComment(
    findingId: string,
    content: string,
    userId: string
  ): Promise<{ commentId: string }> {
    // Validate content: non-empty after trim, max 2000 chars (Requirement 9.1, 9.5)
    const trimmedContent = content?.trim() ?? '';
    if (trimmedContent.length === 0 || trimmedContent.length > 2000) {
      throw new ValidationError(
        'Comment content must be non-empty and at most 2000 characters after trimming'
      );
    }

    // Validate finding exists (Requirement 9.6)
    const finding = await db.prepare(
      "SELECT id, created_by FROM audit_findings WHERE id = ?"
    ).get(findingId) as { id: string; created_by: string } | undefined;

    if (!finding) {
      throw new NotFoundError('Finding not found');
    }

    // Create the comment record (Requirement 9.1)
    const result = await db.prepare(`
      INSERT INTO comments (related_type, related_id, user_id, content)
      VALUES ('audit_findings', ?, ?, ?)
    `).get(findingId, userId, trimmedContent) as { id: string } | undefined;

    const commentId = result?.id || (await db.prepare(
      "SELECT id FROM comments WHERE related_type = 'audit_findings' AND related_id = ? AND user_id = ? ORDER BY created_at DESC LIMIT 1"
    ).get(findingId, userId) as any)?.id;

    // Notification logic (Requirements 9.2, 9.3, 9.4)
    if (userId !== finding.created_by) {
      // Case 1: Commenter ≠ finding creator → notify finding creator (Requirement 9.2)
      await NotificationService.create(
        finding.created_by,
        'comment_added',
        JSON.stringify({ key: 'notifications.commentOnYourFinding', params: { findingId } }),
        'AuditFindings',
        `/findings/${findingId}`,
        {
          actorId: userId,
          entityId: findingId,
          entityType: 'audit_findings',
        }
      );
    } else {
      // Commenter = finding creator (reply scenario)
      // Find the last different commenter (Requirement 9.3)
      const lastCommenter = await db.prepare(`
        SELECT user_id FROM comments 
        WHERE related_type = 'audit_findings' AND related_id = ? AND user_id != ?
        ORDER BY created_at DESC LIMIT 1
      `).get(findingId, userId) as { user_id: string } | undefined;

      if (lastCommenter) {
        // Case 2: Previous different commenter exists → notify them (Requirement 9.3)
        await NotificationService.create(
          lastCommenter.user_id,
          'comment_added',
          JSON.stringify({ key: 'notifications.replyToYourComment', params: { findingId } }),
          'AuditFindings',
          `/findings/${findingId}`,
          {
            actorId: userId,
            entityId: findingId,
            entityType: 'audit_findings',
          }
        );
      }
      // Case 3: No previous different commenter → no notification (Requirement 9.4)
    }

    return { commentId };
  }
}

import { db } from '../db/index';

export class ComplianceService {

  static async getAll(filters?: {
    source_type?: string;
    compliance_status?: string;
    search?: string;
  }) {
    let sql = `
      SELECT
        ci.*,
        u.name  AS responsible_person_name,
        o.name_en       AS department_name,
        (SELECT COUNT(*) FROM finding_compliance fc WHERE fc.compliance_id = ci.id) AS open_findings_count
      FROM compliance_items ci
      LEFT JOIN users      u ON ci.responsible_person_id = u.id
      LEFT JOIN org_entities o ON ci.department_id = o.id
      WHERE ci.deleted_at IS NULL
    `;
    const params: any[] = [];

    if (filters?.source_type) {
      sql += ` AND ci.source_type = ?`;
      params.push(filters.source_type);
    }
    if (filters?.compliance_status) {
      sql += ` AND ci.compliance_status = ?`;
      params.push(filters.compliance_status);
    }
    if (filters?.search) {
      sql += ` AND (ci.title LIKE ? OR ci.ref_number LIKE ? OR ci.description LIKE ?)`;
      const term = `%${filters.search}%`;
      params.push(term, term, term);
    }

    sql += ` ORDER BY ci.created_at DESC`;
    // Wait, PGlite requires `db.prepare(sql).all(...params)` ? 
    // Yes, but let's check PGlite docs. PGlite `db.query(sql, params)`. 
    // Wait, the project uses `db.prepare().all()` - maybe it's not PGlite, or it's a wrapper.
    // The previous instructions show: return await db.prepare(sql).all(...params);
    return await db.prepare(sql).all(...params);
  }

  static async getById(id: string) {
    const item = await db.prepare(`
      SELECT ci.*,
        u.name AS responsible_person_name,
        o.name_en      AS department_name
      FROM compliance_items ci
      LEFT JOIN users       u ON ci.responsible_person_id = u.id
      LEFT JOIN org_entities o ON ci.department_id = o.id
      WHERE ci.id = ? AND ci.deleted_at IS NULL
    `).get(id);
    if (!item) throw new Error('NOT_FOUND');
    return item;
  }

  static async create(data: any, createdBy: string) {
    const id = crypto.randomUUID();
    await db.prepare(`
      INSERT INTO compliance_items
        (id, ref_number, title, source_type, issuing_authority, category,
         issue_date, effective_date, review_date, compliance_status,
         maturity_score, gap_notes, responsible_person_id, department_id,
         description, keywords, version, attachment_path, created_by)
      VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
    `).run(
      id, data.ref_number, data.title, data.source_type,
      data.issuing_authority ?? null, data.category ?? null,
      data.issue_date ?? null, data.effective_date ?? null,
      data.review_date ?? null, data.compliance_status ?? 'under_review',
      data.maturity_score ?? null, data.gap_notes ?? null,
      data.responsible_person_id ?? null, data.department_id ?? null,
      data.description ?? null, data.keywords ?? null,
      data.version ?? null, data.attachment_path ?? null, createdBy
    );
    return { id };
  }

  static async update(id: string, data: any) {
    await db.prepare(`
      UPDATE compliance_items SET
        title = COALESCE(?, title),
        source_type = COALESCE(?, source_type),
        issuing_authority = COALESCE(?, issuing_authority),
        category = COALESCE(?, category),
        issue_date = COALESCE(?, issue_date),
        effective_date = COALESCE(?, effective_date),
        review_date = COALESCE(?, review_date),
        compliance_status = COALESCE(?, compliance_status),
        maturity_score = COALESCE(?, maturity_score),
        gap_notes = COALESCE(?, gap_notes),
        responsible_person_id = COALESCE(?, responsible_person_id),
        department_id = COALESCE(?, department_id),
        description = COALESCE(?, description),
        keywords = COALESCE(?, keywords),
        version = COALESCE(?, version),
        attachment_path = COALESCE(?, attachment_path),
        updated_at = CURRENT_TIMESTAMP
      WHERE id = ? AND deleted_at IS NULL
    `).run(
      data.title, data.source_type, data.issuing_authority,
      data.category, data.issue_date, data.effective_date,
      data.review_date, data.compliance_status, data.maturity_score,
      data.gap_notes, data.responsible_person_id, data.department_id,
      data.description, data.keywords, data.version, data.attachment_path, id
    );
  }

  static async softDelete(id: string) {
    await db.prepare(
      `UPDATE compliance_items SET deleted_at = CURRENT_TIMESTAMP WHERE id = ?`
    ).run(id);
  }

  static async getSummary() {
    const counts = await db.prepare(`
      SELECT
        compliance_status,
        COUNT(*) AS count
      FROM compliance_items
      WHERE deleted_at IS NULL
      GROUP BY compliance_status
    `).all() as any[];

    const overdueReview = await db.prepare(`
      SELECT COUNT(*) AS count
      FROM compliance_items
      WHERE deleted_at IS NULL
        AND review_date IS NOT NULL
        AND review_date != ''
        AND CAST(review_date AS date) < CURRENT_DATE
    `).get() as any;

    const dueSoon = await db.prepare(`
      SELECT COUNT(*) AS count
      FROM compliance_items
      WHERE deleted_at IS NULL
        AND review_date IS NOT NULL
        AND review_date != ''
        AND CAST(review_date AS date) BETWEEN CURRENT_DATE AND (CURRENT_DATE + interval '30 days')
    `).get() as any;

    return { counts, overdueReview: overdueReview?.count ?? 0, dueSoon: dueSoon?.count ?? 0 };
  }
}

import { db } from '../db/index';
import { NotFoundError, ValidationError, ForbiddenError } from '../utils/errors';
import { QueryBuilder } from '../utils/QueryBuilder';
import { N8nService } from '../utils/n8nService';
import { computePaginationMeta } from '../utils/paginationService';
import { UserRole } from '../../constants';

/**
 * Represents the user context passed from the authenticated request.
 * Used for row-level security (scope) checks in the service layer.
 */
export interface UserContext {
  userId: string;
  userRole: string;
  departmentId: string | null;
}

export class CorrespondenceService {
  private static db = db;

  /**
   * Centralized scope-checking logic for row-level security.
   * Determines if a given correspondence record is within the user's authorized scope.
   *
   * - Admin: full access to all records (no filtering)
   * - Manager: access limited to records assigned to their department
   * - Regular users: access if assigned to their dept, assigned to them, or created by them
   *
   * @param record - The correspondence record to check (must have assigned_dept_id, assigned_user_id, created_by fields)
   * @param userContext - The authenticated user's context (userId, userRole, departmentId)
   * @returns true if the record is within the user's authorized scope
   */
  private static isWithinScope(record: any, userContext: UserContext): boolean {
    // Admin users have full access — no row-level filtering
    if (userContext.userRole === UserRole.ADMIN) {
      return true;
    }

    // Manager users can access all records within their department
    if (userContext.userRole === UserRole.MANAGER) {
      return record.assigned_dept_id === userContext.departmentId;
    }

    // Regular users: access if record is in their department, assigned to them, or created by them
    return (
      record.assigned_dept_id === userContext.departmentId ||
      record.assigned_user_id === userContext.userId ||
      record.created_by === userContext.userId
    );
  }

  static async getIncoming(filters: any, userContext?: UserContext) {
    const { archived, search, status, priority, dept_id, start_date, end_date, page = 1, pageSize = 10 } = filters;
    const isArchived = archived === 'true' ? 1 : 0;
    
    let baseQueryString = `
      FROM incoming_correspondence i
      LEFT JOIN org_entities d ON i.assigned_dept_id = d.id
      LEFT JOIN users u ON i.assigned_user_id = u.id
    `;
    
    const qb = new QueryBuilder(baseQueryString)
      .where('i.is_archived = ?', isArchived)
      .whereIf(!!status, 'i.status = ?', status)
      .whereIf(!!priority, 'i.priority = ?', priority)
      .whereIf(!!dept_id, 'i.assigned_dept_id = ?', dept_id)
      .whereIf(!!start_date, 'i.letter_date >= ?', start_date)
      .whereIf(!!end_date, 'i.letter_date <= ?', end_date);
    
    // Department-scoped filtering for non-Admin users
    if (userContext && userContext.userRole !== UserRole.ADMIN) {
      if (userContext.departmentId) {
        qb.where(
          '(i.assigned_dept_id = ? OR i.assigned_user_id = ? OR i.created_by = ?)',
          userContext.departmentId,
          userContext.userId,
          userContext.userId
        );
      } else {
        // User has no department — can only see records assigned to them or created by them
        qb.where(
          '(i.assigned_user_id = ? OR i.created_by = ?)',
          userContext.userId,
          userContext.userId
        );
      }
    }

    if (search) {
      const s = `%${search}%`;
      qb.where('(i.sequence_number LIKE ? OR i.letter_number LIKE ? OR i.subject LIKE ? OR i.sender_entity LIKE ?)', s, s, s, s);
    }

    const countQuery = `SELECT COUNT(*) as total ${qb.buildCountQuery()}`;
    const countRes = await this.db.prepare(countQuery).get(...qb.buildParams());
    const total = countRes?.total || 0;

    qb.orderBy('i.registration_date', 'DESC');
    const pagination = qb.paginate(page, pageSize);

    const dataQuery = `
      SELECT i.*, d.name_ar as assigned_dept_name_ar, d.name_en as assigned_dept_name_en, u.name as assigned_user_name
      ${qb.buildDataQuery()}
    `;
    
    const data = await this.db.prepare(dataQuery).all(...qb.buildParams(pagination));
    
    return {
      data,
      pagination: computePaginationMeta(page, pageSize, total)
    };
  }

  static async createIncoming(data: any, userId: string | number) {
    const { 
      letter_number, sender_entity, sender_entity_type, subject, letter_date, 
      receipt_date, classification, priority, method, receiving_dept_id, 
      assigned_dept_id, assigned_user_id, follow_up_required, follow_up_date, 
      response_required, response_due_date, notes 
    } = data;

    const year = new Date().getFullYear();
    const last = await this.db.prepare("SELECT sequence_number FROM incoming_correspondence WHERE sequence_number LIKE ? ORDER BY id DESC LIMIT 1").get(`INC-${year}-%`) as any;
    let nextNum = 1;
    if (last) {
      const parts = last.sequence_number.split('-');
      nextNum = parseInt(parts[parts.length - 1]) + 1;
    }
    const sequence_number = `INC-${year}-${nextNum.toString().padStart(4, '0')}`;

    const result = await this.db.prepare(`
      INSERT INTO incoming_correspondence (
        sequence_number, letter_number, sender_entity, sender_entity_type, subject, 
        letter_date, receipt_date, classification, priority, method, 
        receiving_dept_id, assigned_dept_id, assigned_user_id, 
        follow_up_required, follow_up_date, response_required, response_due_date, 
        notes, created_by
      ) VALUES (?::text, ?::text, ?::text, ?::text, ?::text, ?::text, ?::text, ?::text, ?::text, ?::text, ?::uuid, ?::uuid, ?::uuid, ?::integer, ?::text, ?::integer, ?::text, ?::text, ?::uuid)
    `).run(
      sequence_number, letter_number, sender_entity, sender_entity_type, subject, 
      letter_date, receipt_date, classification, priority, method, 
      receiving_dept_id, assigned_dept_id, assigned_user_id, 
      follow_up_required ? 1 : 0, follow_up_date, response_required ? 1 : 0, response_due_date, 
      notes, userId
    );

    // --- AUTOMATION: Send event to n8n ---
    await N8nService.sendEvent('incoming_correspondence.created', {
      id: result.lastInsertRowid,
      sequence_number,
      subject,
      sender_entity
    });

    return { id: result.lastInsertRowid, sequence_number };
  }

  static async updateStatus(type: string, id: string | number, newStatus: string, notes: string, userId: string | number, userContext?: UserContext) {
    const table = this.db.validateIdentifier(type === 'Outgoing' ? 'outgoing_letters' : 'incoming_correspondence');
    
    // Verify the record is within the user's authorized scope before modifying
    if (userContext) {
      const recordToCheck = await this.db.prepare(`SELECT * FROM ${table} WHERE id = ?`).get(id);
      if (!recordToCheck) throw new NotFoundError("Record not found");
      if (!this.isWithinScope(recordToCheck, userContext)) {
        throw new ForbiddenError('Access denied to this record');
      }
    }

    return await this.db.transaction(async () => {
      const oldRecord = await this.db.prepare(`SELECT status FROM ${table} WHERE id = ?`).get(id);
      if (!oldRecord) throw new NotFoundError("Record not found");

      await this.db.prepare(`UPDATE ${table} SET status = ?::text, updated_at = CURRENT_TIMESTAMP WHERE id = ?::uuid`).run(newStatus, id);
      
      await this.db.prepare(`
        INSERT INTO correspondence_status_history (correspondence_id, correspondence_type, old_status, new_status, changed_by, notes)
        VALUES (?::uuid, ?::text, ?::text, ?::text, ?::uuid, ?::text)
      `).run(id, type, oldRecord.status, newStatus, userId, notes);

      // --- AUTOMATION: Send event to n8n ---
      await N8nService.sendEvent('correspondence.status_changed', {
        id,
        type,
        oldStatus: oldRecord.status,
        newStatus,
        changedBy: userId
      });

      return { oldStatus: oldRecord.status };
    })();
  }

  static async refer(data: any, userId: string | number, userContext?: UserContext) {
    const { incoming_id, to_dept_id, to_user_id, notes } = data;
    
    // Verify the incoming record is within the user's authorized scope
    if (userContext) {
      const incomingRecord = await this.db.prepare(`SELECT * FROM incoming_correspondence WHERE id = ?`).get(incoming_id);
      if (!incomingRecord) throw new NotFoundError("Record not found");
      if (!this.isWithinScope(incomingRecord, userContext)) {
        throw new ForbiddenError('Access denied to this record');
      }
    }

    await this.db.transaction(async () => {
      await this.db.prepare(`
        INSERT INTO correspondence_referrals (incoming_id, from_user_id, to_dept_id, to_user_id, notes)
        VALUES (?::uuid, ?::uuid, ?::uuid, ?::uuid, ?::text)
      `).run(incoming_id, userId, to_dept_id, to_user_id, notes);

      // Update incoming status to 'Referred'
      await this.db.prepare("UPDATE incoming_correspondence SET status = 'Referred', assigned_dept_id = ?::uuid, assigned_user_id = ?::uuid, updated_at = CURRENT_TIMESTAMP WHERE id = ?::uuid")
        .run(to_dept_id, to_user_id, incoming_id);
    })();
  }

  static async link(data: any, userId: string | number, userContext?: UserContext) {
    const { incoming_id, outgoing_id, link_type } = data;
    
    // Verify both records are within the user's authorized scope
    if (userContext) {
      const incomingRecord = await this.db.prepare(`SELECT * FROM incoming_correspondence WHERE id = ?`).get(incoming_id);
      if (!incomingRecord) throw new NotFoundError("Record not found");
      if (!this.isWithinScope(incomingRecord, userContext)) {
        throw new ForbiddenError('Access denied to this record');
      }

      const outgoingRecord = await this.db.prepare(`SELECT * FROM outgoing_letters WHERE id = ?`).get(outgoing_id);
      if (!outgoingRecord) throw new NotFoundError("Record not found");
      if (!this.isWithinScope(outgoingRecord, userContext)) {
        throw new ForbiddenError('Access denied to this record');
      }
    }

    await this.db.prepare("INSERT INTO correspondence_links (incoming_id, outgoing_id, link_type, linked_by) VALUES (?::uuid, ?::uuid, ?::text, ?::uuid)")
      .run(incoming_id, outgoing_id, link_type || 'Reply', userId);
  }

  static async archive(type: string, id: string | number, userContext?: UserContext) {
    const table = this.db.validateIdentifier(type === 'Incoming' ? 'incoming_correspondence' : 'outgoing_letters');
    
    // Verify the record is within the user's authorized scope before archiving
    if (userContext) {
      const record = await this.db.prepare(`SELECT * FROM ${table} WHERE id = ?`).get(id);
      if (!record) throw new NotFoundError("Record not found");
      if (!this.isWithinScope(record, userContext)) {
        throw new ForbiddenError('Access denied to this record');
      }
    }

    await this.db.prepare(`UPDATE ${table} SET is_archived = 1, status = 'Archived', updated_at = CURRENT_TIMESTAMP WHERE id = ?::uuid`).run(id);
  }

  static async getArchive(filters: any, userContext?: UserContext) {
    const { search, type, page = 1, pageSize = 15 } = filters;

    let query = "";
    let countQuery = "";
    
    // Helper to build scope condition for non-Admin users
    const isScoped = userContext && userContext.userRole !== UserRole.ADMIN;

    if (type === 'Incoming') {
      const qb = new QueryBuilder(`FROM incoming_correspondence`)
        .where("is_archived = 1");
      if (isScoped) {
        if (userContext!.departmentId) {
          qb.where(
            '(assigned_dept_id = ? OR assigned_user_id = ? OR created_by = ?)',
            userContext!.departmentId,
            userContext!.userId,
            userContext!.userId
          );
        } else {
          qb.where(
            '(assigned_user_id = ? OR created_by = ?)',
            userContext!.userId,
            userContext!.userId
          );
        }
      }
      if (search) {
        qb.where("(sequence_number LIKE ? OR subject LIKE ? OR sender_entity LIKE ?)", `%${search}%`, `%${search}%`, `%${search}%`);
      }
      countQuery = `SELECT COUNT(*) as total ${qb.buildCountQuery()}`;
      const countRes = await this.db.prepare(countQuery).get(...qb.buildParams());
      qb.orderBy('updated_at', 'DESC');
      const pagination = qb.paginate(page, pageSize);
      const data = await this.db.prepare(`SELECT *, 'Incoming' as type, sender_entity as entity ${qb.buildDataQuery()}`).all(...qb.buildParams(pagination));
      return { data, pagination: computePaginationMeta(page, pageSize, countRes?.total || 0) };
      
    } else if (type === 'Outgoing') {
      const qb = new QueryBuilder(`FROM outgoing_letters`)
        .where("is_archived = 1");
      if (isScoped) {
        if (userContext!.departmentId) {
          qb.where(
            '(created_by = ? OR created_by IN (SELECT id FROM users WHERE department_id = ?))',
            userContext!.userId,
            userContext!.departmentId
          );
        } else {
          qb.where('created_by = ?', userContext!.userId);
        }
      }
      if (search) {
        qb.where("(sequence_number LIKE ? OR subject LIKE ? OR recipient_entity LIKE ?)", `%${search}%`, `%${search}%`, `%${search}%`);
      }
      countQuery = `SELECT COUNT(*) as total ${qb.buildCountQuery()}`;
      const countRes = await this.db.prepare(countQuery).get(...qb.buildParams());
      qb.orderBy('updated_at', 'DESC');
      const pagination = qb.paginate(page, pageSize);
      const data = await this.db.prepare(`SELECT *, 'Outgoing' as type, recipient_entity as entity ${qb.buildDataQuery()}`).all(...qb.buildParams(pagination));
      return { data, pagination: computePaginationMeta(page, pageSize, countRes?.total || 0) };
      
    } else {
      // Combined Logic
      const qb = new QueryBuilder("").where("is_archived = 1");
      if (search) {
         const s = `%${search}%`;
         qb.where("(sequence_number LIKE ? OR subject LIKE ? OR search_column LIKE ?)", s, s, s);
      }
      
      const whereBlock = qb.getWhereBlock();
      const incWhere = whereBlock.replace('search_column', 'sender_entity');
      const outWhere = whereBlock.replace('search_column', 'recipient_entity');

      // Build scope conditions for combined query
      let incScopeClause = '';
      let outScopeClause = '';
      const incScopeParams: any[] = [];
      const outScopeParams: any[] = [];
      
      if (isScoped) {
        if (userContext!.departmentId) {
          incScopeClause = ' AND (assigned_dept_id = ? OR assigned_user_id = ? OR created_by = ?)';
          incScopeParams.push(userContext!.departmentId, userContext!.userId, userContext!.userId);
          outScopeClause = ' AND (created_by = ? OR created_by IN (SELECT id FROM users WHERE department_id = ?))';
          outScopeParams.push(userContext!.userId, userContext!.departmentId);
        } else {
          incScopeClause = ' AND (assigned_user_id = ? OR created_by = ?)';
          incScopeParams.push(userContext!.userId, userContext!.userId);
          outScopeClause = ' AND created_by = ?';
          outScopeParams.push(userContext!.userId);
        }
      }

      const incQuery = `SELECT id, sequence_number, subject, sender_entity as entity, updated_at, 'Incoming' as type, is_archived FROM incoming_correspondence ${incWhere}${incScopeClause}`;
      const outQuery = `SELECT id, sequence_number, subject, recipient_entity as entity, updated_at, 'Outgoing' as type, is_archived FROM outgoing_letters ${outWhere}${outScopeClause}`;
      
      query = `SELECT * FROM (${incQuery} UNION ALL ${outQuery}) as combined`;
      countQuery = `SELECT COUNT(*) as total FROM (${incQuery} UNION ALL ${outQuery}) as combined`;
      
      const allCountParams = [...qb.buildParams(), ...incScopeParams, ...qb.buildParams(), ...outScopeParams];
      const countRes = await this.db.prepare(countQuery).get(...allCountParams);
      const pagination = qb.paginate(page, pageSize);
      const data = await this.db.prepare(`${query} ORDER BY updated_at DESC LIMIT ? OFFSET ?`).all(...qb.buildParams(), ...incScopeParams, ...qb.buildParams(), ...outScopeParams, pagination.limit, pagination.offset);
      
      return {
        data,
        pagination: computePaginationMeta(page, pageSize, countRes?.total || 0)
      };
    }
  }

  static async getAttachments(type: string, id: string | number, userContext?: UserContext) {
    if (userContext) {
      const table = type === 'Outgoing' || type === 'outgoing' 
        ? 'outgoing_letters' 
        : 'incoming_correspondence';
      const record = await this.db.prepare(`SELECT * FROM ${table} WHERE id = ?`).get(id);
      if (!record) throw new NotFoundError("Record not found");
      if (!this.isWithinScope(record, userContext)) {
        throw new ForbiddenError('Access denied to this record');
      }
    }
    return await this.db.prepare("SELECT id, file_name, file_type, uploaded_at, description FROM correspondence_attachments WHERE correspondence_type = ? AND correspondence_id = ?")
      .all(type, id);
  }

  static async addAttachment(data: any, userId: string | number, userContext?: UserContext) {
    const { correspondence_id, correspondence_type, file_name, file_type, file_data, description } = data;
    
    // Verify the target correspondence record is within the user's authorized scope
    if (userContext) {
      const table = correspondence_type === 'Outgoing' || correspondence_type === 'outgoing' 
        ? 'outgoing_letters' 
        : 'incoming_correspondence';
      const record = await this.db.prepare(`SELECT * FROM ${table} WHERE id = ?`).get(correspondence_id);
      if (!record) throw new NotFoundError("Record not found");
      if (!this.isWithinScope(record, userContext)) {
        throw new ForbiddenError('Access denied to this record');
      }
    }

    await this.db.prepare(`
      INSERT INTO correspondence_attachments (correspondence_id, correspondence_type, file_name, file_type, file_data, description, uploaded_by)
      VALUES (?::uuid, ?::text, ?::text, ?::text, ?::text, ?::text, ?::uuid)
    `).run(correspondence_id, correspondence_type, file_name, file_type, file_data, description, userId);
  }

  static async getStats(userContext?: UserContext) {
    // Department-scoped filtering for non-Admin users
    let incomingWhere = '';
    let outgoingWhere = '';
    const incomingParams: any[] = [];
    const outgoingParams: any[] = [];
    
    if (userContext && userContext.userRole !== UserRole.ADMIN) {
      if (userContext.departmentId) {
        incomingWhere = ' AND (assigned_dept_id = ? OR assigned_user_id = ? OR created_by = ?)';
        incomingParams.push(userContext.departmentId, userContext.userId, userContext.userId);
        outgoingWhere = ' WHERE (created_by = ? OR created_by IN (SELECT id FROM users WHERE department_id = ?))';
        outgoingParams.push(userContext.userId, userContext.departmentId);
      } else {
        incomingWhere = ' AND (assigned_user_id = ? OR created_by = ?)';
        incomingParams.push(userContext.userId, userContext.userId);
        outgoingWhere = ' WHERE created_by = ?';
        outgoingParams.push(userContext.userId);
      }
    }

    return {
      total_incoming: (await this.db.prepare(`SELECT COUNT(*) as count FROM incoming_correspondence WHERE is_archived = 0${incomingWhere}`).get(...incomingParams) as any).count,
      total_outgoing: (await this.db.prepare(`SELECT COUNT(*) as count FROM outgoing_letters${outgoingWhere}`).get(...outgoingParams) as any).count,
      pending_response: (await this.db.prepare(`SELECT COUNT(*) as count FROM incoming_correspondence WHERE response_required = 1 AND status != 'Closed' AND is_archived = 0${incomingWhere}`).get(...incomingParams) as any).count,
      follow_up: (await this.db.prepare(`SELECT COUNT(*) as count FROM incoming_correspondence WHERE follow_up_required = 1 AND is_archived = 0${incomingWhere}`).get(...incomingParams) as any).count,
      archived: (await this.db.prepare(`SELECT COUNT(*) as count FROM incoming_correspondence WHERE is_archived = 1${incomingWhere}`).get(...incomingParams) as any).count
    };
  }

  static async getDetails(type: string, id: string | number, userContext?: UserContext) {
    const table = this.db.validateIdentifier(type === 'outgoing' ? 'outgoing_letters' : 'incoming_correspondence');
    
    let record;
    if (type === 'outgoing') {
      record = await this.db.prepare(`
        SELECT r.*, u.name as creator_name
        FROM ${table} r
        LEFT JOIN users u ON r.created_by = u.id
        WHERE r.id = ?
      `).get(id);
    } else {
      const deptField = 'r.assigned_dept_id';
      record = await this.db.prepare(`
        SELECT r.*, d.name_ar as dept_name_ar, d.name_en as dept_name_en, u.name as creator_name
        FROM ${table} r
        LEFT JOIN org_entities d ON ${deptField} = d.id
        LEFT JOIN users u ON r.created_by = u.id
        WHERE r.id = ?
      `).get(id);
    }

    if (!record) throw new NotFoundError("Record not found");

    // Verify the record is within the user's authorized scope
    if (userContext && !this.isWithinScope(record, userContext)) {
      throw new ForbiddenError('Access denied to this record');
    }

    const attachments = await this.db.prepare("SELECT id, file_name, file_type, uploaded_at, description FROM correspondence_attachments WHERE correspondence_type = ? AND correspondence_id = ?").all(type, id);
    const history = await this.db.prepare("SELECT h.*, u.name as user_name FROM correspondence_status_history h LEFT JOIN users u ON h.changed_by = u.id WHERE correspondence_type = ? AND correspondence_id = ? ORDER BY h.change_date DESC").all(type, id);
    
    let links = [];
    let referrals = [];

    if (type !== 'outgoing') {
      referrals = await this.db.prepare(`
        SELECT r.*, u1.name as from_user, u2.name as to_user, d.name_ar as to_dept
        FROM correspondence_referrals r
        LEFT JOIN users u1 ON r.from_user_id = u1.id
        LEFT JOIN users u2 ON r.to_user_id = u2.id
        LEFT JOIN org_entities d ON r.to_dept_id = d.id
        WHERE r.incoming_id = ?
        ORDER BY r.referral_date DESC
      `).all(id);
    }

    return { main: record, attachments, history, links, referrals };
  }

  static async getOutgoing(page = 1, pageSize = 10, userContext?: UserContext) {
    const offset = (page - 1) * pageSize;
    
    // Department-scoped filtering for non-Admin users
    let whereClause = '';
    const params: any[] = [];
    
    if (userContext && userContext.userRole !== UserRole.ADMIN) {
      if (userContext.departmentId) {
        whereClause = 'WHERE (created_by = ? OR created_by IN (SELECT id FROM users WHERE department_id = ?))';
        params.push(userContext.userId, userContext.departmentId);
      } else {
        whereClause = 'WHERE created_by = ?';
        params.push(userContext.userId);
      }
    }
    
    const countRes = await this.db.prepare(`SELECT COUNT(*) as total FROM outgoing_letters ${whereClause}`).get(...params);
    const total = countRes?.total || 0;

    const data = await this.db.prepare(`SELECT id, sequence_number, letter_date, recipient_entity, subject, classification, sending_method, status, is_archived, created_at, updated_at, created_by FROM outgoing_letters ${whereClause} ORDER BY created_at DESC LIMIT ? OFFSET ?`).all(...params, pageSize, offset);
    
    return {
      data,
      pagination: computePaginationMeta(page, pageSize, total)
    };
  }

  static async createOutgoing(data: any, userId: string | number) {
    const { letter_date, recipient_entity, subject, classification, sending_method, attachment_file } = data;
    
    // Auto-generate sequence number: OUT-YYYY-NNNN
    const year = new Date().getFullYear();
    const last = await this.db.prepare("SELECT sequence_number FROM outgoing_letters WHERE sequence_number LIKE ? ORDER BY id DESC LIMIT 1").get(`OUT-${year}-%`) as any;
    let nextNum = 1;
    if (last) {
      const parts = last.sequence_number.split('-');
      nextNum = parseInt(parts[parts.length - 1]) + 1;
    }
    const sequence_number = `OUT-${year}-${nextNum.toString().padStart(4, '0')}`;

    const stmt = this.db.prepare(`
      INSERT INTO outgoing_letters (sequence_number, letter_date, recipient_entity, subject, classification, sending_method, attachment_file, created_by)
      VALUES (?::text, ?::text, ?::text, ?::text, ?::text, ?::text, ?::text, ?::uuid)
    `);
    const result = await stmt.run(sequence_number, letter_date, recipient_entity, subject, classification, sending_method, attachment_file, userId);
    
    // --- AUTOMATION: Send event to n8n ---
    await N8nService.sendEvent('outgoing_correspondence.created', {
      id: result.lastInsertRowid,
      sequence_number,
      subject,
      recipient_entity
    });

    return { id: result.lastInsertRowid, sequence_number };
  }

  static async updateOutgoing(id: string | number, data: any, userContext?: UserContext) {
    if (userContext) {
      const record = await this.db.prepare(`SELECT * FROM outgoing_letters WHERE id = ?`).get(id);
      if (!record) throw new NotFoundError("Record not found");
      if (!this.isWithinScope(record, userContext)) {
        throw new ForbiddenError('Access denied to this record');
      }
    }

    const { letter_date, recipient_entity, subject, classification, sending_method, attachment_file } = data;
    
    if (attachment_file !== undefined) {
      await this.db.prepare(`
        UPDATE outgoing_letters 
        SET letter_date = ?::text, recipient_entity = ?::text, subject = ?::text, classification = ?::text, sending_method = ?::text, attachment_file = ?::text
        WHERE id = ?::uuid
      `).run(letter_date, recipient_entity, subject, classification, sending_method, attachment_file, id);
    } else {
      await this.db.prepare(`
        UPDATE outgoing_letters 
        SET letter_date = ?::text, recipient_entity = ?::text, subject = ?::text, classification = ?::text, sending_method = ?::text
        WHERE id = ?::uuid
      `).run(letter_date, recipient_entity, subject, classification, sending_method, id);
    }

    // --- AUTOMATION: Send event to n8n ---
    await N8nService.sendEvent('outgoing_correspondence.updated', {
      id,
      updates: data
    });
  }

  static async deleteOutgoing(id: string | number, userContext?: UserContext) {
    if (userContext) {
      const record = await this.db.prepare(`SELECT * FROM outgoing_letters WHERE id = ?`).get(id);
      if (!record) throw new NotFoundError("Record not found");
      if (!this.isWithinScope(record, userContext)) {
        throw new ForbiddenError('Access denied to this record');
      }
    }

    await this.db.prepare("DELETE FROM outgoing_letters WHERE id = ?").run(id);

    // --- AUTOMATION: Send event to n8n ---
    await N8nService.sendEvent('outgoing_correspondence.deleted', {
      id
    });
  }

  static async updateIncoming(id: string | number, data: any, userContext?: UserContext) {
    if (userContext) {
      const record = await this.db.prepare(`SELECT * FROM incoming_correspondence WHERE id = ?`).get(id);
      if (!record) throw new NotFoundError("Record not found");
      if (!this.isWithinScope(record, userContext)) {
        throw new ForbiddenError('Access denied to this record');
      }
    }

    const { 
      letter_number, sender_entity, sender_entity_type, subject, letter_date, 
      receipt_date, classification, priority, method, receiving_dept_id, 
      assigned_dept_id, assigned_user_id, follow_up_required, follow_up_date, 
      response_required, response_due_date, notes 
    } = data;

    await this.db.prepare(`
      UPDATE incoming_correspondence SET 
        letter_number = ?::text, sender_entity = ?::text, sender_entity_type = ?::text, subject = ?::text, 
        letter_date = ?::text, receipt_date = ?::text, classification = ?::text, priority = ?::text, method = ?::text, 
        receiving_dept_id = ?::uuid, assigned_dept_id = ?::uuid, assigned_user_id = ?::uuid, 
        follow_up_required = ?::integer, follow_up_date = ?::text, response_required = ?::integer, response_due_date = ?::text, 
        notes = ?::text, updated_at = CURRENT_TIMESTAMP
      WHERE id = ?::uuid
    `).run(
      letter_number, sender_entity, sender_entity_type, subject, 
      letter_date, receipt_date, classification, priority, method, 
      receiving_dept_id, assigned_dept_id, assigned_user_id, 
      follow_up_required ? 1 : 0, follow_up_date, response_required ? 1 : 0, response_due_date, 
      notes, id
    );

    // --- AUTOMATION: Send event to n8n ---
    await N8nService.sendEvent('incoming_correspondence.updated', {
      id,
      updates: data
    });
  }

  static async deleteIncoming(id: string | number, userContext?: UserContext) {
    if (userContext) {
      const record = await this.db.prepare(`SELECT * FROM incoming_correspondence WHERE id = ?`).get(id);
      if (!record) throw new NotFoundError("Record not found");
      if (!this.isWithinScope(record, userContext)) {
        throw new ForbiddenError('Access denied to this record');
      }
    }

    // Cleanup related records first
    await this.db.transaction(async () => {
      await this.db.prepare("DELETE FROM correspondence_attachments WHERE correspondence_type = 'Incoming' AND correspondence_id = ?").run(id);
      await this.db.prepare("DELETE FROM correspondence_referrals WHERE incoming_id = ?").run(id);
      await this.db.prepare("DELETE FROM correspondence_links WHERE incoming_id = ?").run(id);
      await this.db.prepare("DELETE FROM correspondence_status_history WHERE correspondence_type = 'Incoming' AND correspondence_id = ?").run(id);
      
      await this.db.prepare("DELETE FROM incoming_correspondence WHERE id = ?").run(id);
    })();

    // --- AUTOMATION: Send event to n8n ---
    await N8nService.sendEvent('incoming_correspondence.deleted', {
      id
    });
  }
}

import { db } from '../db/index';
import { NotFoundError } from '../utils/errors';
import { QueryBuilder } from '../utils/QueryBuilder';
import { computePaginationMeta } from '../utils/paginationService';

export class DashboardService {
  private static db = db;

  static async getDashboardStats(filters: { department?: string; riskLevel?: string } = {}) {
    const { department, riskLevel } = filters;
    const isFiltered = !!(department && department !== 'all');
    
    // Map lowercase filter to database values
    const deptMap: Record<string, string> = {
      'operational': 'Operational',
      'financial': 'Financial',
      'it': 'IT',
      'compliance': 'Compliance'
    };
    const mappedDept = isFiltered ? (deptMap[department!.toLowerCase()] || department) : null;

    // Plans Builder
    const auditQb = new QueryBuilder("FROM audit_plans").whereIf(isFiltered, "type = ?", mappedDept);
    
    // Findings Builder
    const findingsBase = isFiltered ? "FROM audit_findings f JOIN audit_plans p ON f.audit_id = p.id" : "FROM audit_findings f";
    const findingsQb = new QueryBuilder(findingsBase)
      .whereIf(isFiltered, "p.type = ?", mappedDept)
      .whereIf(!!riskLevel, "f.risk_level = ?", riskLevel);
      
    // Recommendations Builder
    const recBase = isFiltered ? "FROM recommendations r JOIN audit_findings f ON r.finding_id = f.id JOIN audit_plans p ON f.audit_id = p.id" : "FROM recommendations r";
    const recQb = new QueryBuilder(recBase)
      .whereIf(isFiltered, "p.type = ?", mappedDept)
      .whereIf(!!riskLevel, "r.risk_level = ?", riskLevel);
      
    // Risk Builder
    const riskQb = new QueryBuilder("FROM risk_register").whereIf(isFiltered, "type = ?", mappedDept);

    // Compliance Builder
    const complianceQb = new QueryBuilder("FROM central_bank_instructions")
      .where("status = 'Active'")
      .whereIf(isFiltered, "category = ?", mappedDept);

    // Execute unified query to minimize mutex locking overhead
    const bigQuery = `
      SELECT
        (SELECT json_build_object(
          'total', COUNT(*),
          'completed', COALESCE(SUM(CASE WHEN status = 'Closed' THEN 1 ELSE 0 END), 0),
          'in_progress', COALESCE(SUM(CASE WHEN status IN ('Fieldwork', 'Reporting') THEN 1 ELSE 0 END), 0),
          'delayed', COALESCE(SUM(CASE WHEN status != 'Closed' AND planned_end_date < TO_CHAR(CURRENT_DATE, 'YYYY-MM-DD') THEN 1 ELSE 0 END), 0)
        ) ${auditQb.buildCountQuery()}) as audit_stats,
        
        (SELECT json_build_object(
          'total', COUNT(*),
          'open_count', COALESCE(SUM(CASE WHEN f.status != 'Closed' THEN 1 ELSE 0 END), 0),
          'high_risk_open', COALESCE(SUM(CASE WHEN f.risk_level IN ('High', 'Critical') AND f.status != 'Closed' THEN 1 ELSE 0 END), 0)
        ) ${findingsQb.buildCountQuery()}) as findings_stats,

        (SELECT json_agg(t) FROM (
          SELECT f.risk_level as level, COUNT(*) as count ${findingsQb.buildCountQuery()} GROUP BY f.risk_level
        ) t) as findings_by_risk,

        (SELECT json_build_object(
          'total', COUNT(*),
          'pending_count', COALESCE(SUM(CASE WHEN r.status != 'Implemented' THEN 1 ELSE 0 END), 0),
          'overdue_count', COALESCE(SUM(CASE WHEN r.status != 'Implemented' AND r.due_date < TO_CHAR(CURRENT_DATE, 'YYYY-MM-DD') THEN 1 ELSE 0 END), 0)
        ) ${recQb.buildCountQuery()}) as rec_stats,

        (SELECT json_build_object(
          'total', COUNT(*),
          'high_count', COALESCE(SUM(CASE WHEN rating IN ('High', 'Critical') THEN 1 ELSE 0 END), 0)
        ) ${riskQb.buildCountQuery()}) as risk_stats,

        (SELECT json_agg(t) FROM (
          SELECT rating as level, COUNT(*) as count ${riskQb.buildCountQuery()} GROUP BY rating
        ) t) as risks_by_level,

        (SELECT json_build_object(
          'incoming_total', (SELECT COUNT(*) FROM incoming_correspondence),
          'outgoing_total', (SELECT COUNT(*) FROM outgoing_letters),
          'pending_responses', (SELECT COUNT(*) FROM incoming_correspondence WHERE response_required = 1 AND status != 'Closed')
        )) as corr_stats,

        (SELECT COUNT(*) ${complianceQb.buildCountQuery()}) as compliance_count,

        (SELECT json_agg(t) FROM (
          SELECT id, "user", action, module, timestamp, details FROM audit_trail ORDER BY timestamp DESC LIMIT 10
        ) t) as recent_activity,

        (SELECT json_agg(t) FROM (
          SELECT 
            type,
            COUNT(*) as planned,
            COALESCE(SUM(CASE WHEN status = 'Closed' THEN 1 ELSE 0 END), 0) as completed
          FROM audit_plans
          GROUP BY type
        ) t) as audit_progress
    `;

    const allParams = [
      ...auditQb.buildParams(),
      ...findingsQb.buildParams(),
      ...findingsQb.buildParams(),
      ...recQb.buildParams(),
      ...riskQb.buildParams(),
      ...riskQb.buildParams(),
      ...complianceQb.buildParams()
    ];

    const data = await this.db.prepare(bigQuery).get(...allParams);

    return {
      audits: {
        total: Number(data?.audit_stats?.total || 0),
        completed: Number(data?.audit_stats?.completed || 0),
        in_progress: Number(data?.audit_stats?.in_progress || 0),
        delayed: Number(data?.audit_stats?.delayed || 0),
        progress_by_type: data?.audit_progress || []
      },
      findings: {
        summary: {
          total: Number(data?.findings_stats?.total || 0),
          open: Number(data?.findings_stats?.open_count || 0),
          high_risk_open: Number(data?.findings_stats?.high_risk_open || 0)
        },
        byRisk: data?.findings_by_risk || []
      },
      recommendations: {
        total: Number(data?.rec_stats?.total || 0),
        open: Number(data?.rec_stats?.pending_count || 0),
        overdue: Number(data?.rec_stats?.overdue_count || 0)
      },
      risks: {
        summary: {
          total: Number(data?.risk_stats?.total || 0),
          high: Number(data?.risk_stats?.high_count || 0)
        },
        byLevel: data?.risks_by_level || []
      },
      correspondence: {
        incoming_total: Number(data?.corr_stats?.incoming_total || 0),
        outgoing_total: Number(data?.corr_stats?.outgoing_total || 0),
        pending_responses: Number(data?.corr_stats?.pending_responses || 0)
      },
      compliance: {
        total: Number(data?.compliance_count || 0)
      },
      activity: data?.recent_activity || []
    };
  }

  static async getMyTasks(userId: string | number, page: number = 1, pageSize: number = 10) {
    const offset = (page - 1) * pageSize;
    const query = `
      SELECT t.id, t.title, t.task_number, t.status, t.due_date,
             p.title as plan_title
      FROM audit_tasks t
      LEFT JOIN audit_plans p ON t.plan_id = p.id
      WHERE t.assigned_to = ?
      ORDER BY t.created_at DESC
      LIMIT ? OFFSET ?
    `;
    
    const countQuery = "SELECT COUNT(*) as total FROM audit_tasks WHERE assigned_to = ?";

    const [data, countRes] = await Promise.all([
      this.db.prepare(query).all(userId, pageSize, offset),
      this.db.prepare(countQuery).get(userId)
    ]) as [any[], any];

    const total = countRes?.total || 0;

    return {
      data,
      pagination: computePaginationMeta(page, pageSize, total)
    };
  }
}

// src/server/services/DepartmentService.ts
import { db } from '../db/index';
import { NotFoundError, ValidationError } from '../utils/errors';
import * as crypto from 'crypto';

/**
 * DepartmentService — thin alias over org_entities.
 * All write operations go to org_entities.
 * getAll() returns a shape compatible with both legacy consumers
 * (that expect { id, name }) and new consumers (that use name_ar/name_en).
 */
export class DepartmentService {

  /** Returns org_entities in a shape that satisfies all existing dropdowns */
  static async getAll() {
    try {
      return await db.prepare(`
        SELECT
          id,
          name_ar        AS name,          -- legacy consumers use .name
          name_ar,
          name_en,
          entity_code    AS code,
          entity_type,
          parent_id,
          manager_id,
          manager_name,
          level,
          status,
          display_order
        FROM org_entities
        WHERE status != 'Archived'
        ORDER BY level, display_order, name_ar
      `).all();
    } catch (error) {
      console.error("Error in DepartmentService.getAll:", error);
      return [];
    }
  }

  /** Returns only root-level entities and their children as a nested tree */
  static async getTree() {
    const all = await DepartmentService.getAll() as any[];
    return DepartmentService.buildTree(all, null);
  }

  private static buildTree(nodes: any[], parentId: string | null): any[] {
    return nodes
      .filter(n => (n.parent_id ?? null) === parentId)
      .map(n => ({ ...n, children: DepartmentService.buildTree(nodes, n.id) }));
  }

  static async create(data: {
    entity_code: string;
    name_ar: string;
    name_en?: string;
    entity_type?: string;
    parent_id?: string | null;
    manager_name?: string;
    description?: string;
    location?: string;
    cost_center_code?: string;
  }, createdBy: string) {
    const existing = await db.prepare(
      `SELECT id FROM org_entities WHERE entity_code = ?`
    ).get(data.entity_code) as any;
    if (existing) throw new ValidationError('Entity code already exists');

    const id = crypto.randomUUID();
    const parent = data.parent_id
      ? await db.prepare(`SELECT level FROM org_entities WHERE id = ?`).get(data.parent_id) as any
      : null;
    const level = parent ? parent.level + 1 : 1;

    await db.prepare(`
      INSERT INTO org_entities
        (id, entity_code, name_ar, name_en, entity_type, parent_id,
         manager_name, level, status, description, location, cost_center_code,
         created_at, updated_at)
      VALUES (?,?,?,?,?,?,?,?,'Active',?,?,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
    `).run(
      id, data.entity_code, data.name_ar, data.name_en || data.name_ar,
      data.entity_type ?? 'Department', data.parent_id ?? null,
      data.manager_name ?? null, level,
      data.description ?? null, data.location ?? null,
      data.cost_center_code ?? null
    );

    await db.prepare(
      `INSERT INTO audit_trail ("user", action, module, details)
       VALUES (?, ?, ?, ?)`
    ).run(createdBy, 'Created Org Entity', 'OrgStructure',
      `Created: ${data.name_ar} (${data.entity_code})`);

    return { id, name: data.name_ar };
  }

  static async update(id: string, data: Partial<{
    name_ar: string; name_en: string; entity_type: string;
    parent_id: string | null; manager_name: string;
    description: string; location: string;
    cost_center_code: string; status: string;
  }>, updatedBy: string) {
    const existing = await db.prepare(
      `SELECT name_ar FROM org_entities WHERE id = ?`
    ).get(id) as any;
    if (!existing) throw new NotFoundError('Org entity not found');

    const entries = Object.entries(data).filter(([, v]) => v !== undefined);
    const sets = entries.map(([k]) => `${k} = ?`).join(', ');
    const vals = entries.map(([, v]) => v);

    if (sets) {
      await db.prepare(
        `UPDATE org_entities SET ${sets}, updated_at = CURRENT_TIMESTAMP WHERE id = ?`
      ).run(...vals, id);
    }

    await db.prepare(
      `INSERT INTO audit_trail ("user", action, module, details)
       VALUES (?, ?, ?, ?)`
    ).run(updatedBy, 'Updated Org Entity', 'OrgStructure', `Updated entity ID: ${id}`);

    return { id };
  }

  /** Soft-delete: set status = Archived. Hard delete if no children and no references. */
  static async delete(id: string, deletedBy: string) {
    const children = await db.prepare(
      `SELECT COUNT(*) AS count FROM org_entities WHERE parent_id = ? AND status != 'Archived'`
    ).get(id) as any;
    if (children.count > 0) {
      throw new ValidationError(
        'Cannot delete an entity that has sub-units. Move or delete them first.'
      );
    }

    await db.prepare(
      `UPDATE org_entities SET status = 'Archived', updated_at = CURRENT_TIMESTAMP WHERE id = ?`
    ).run(id);

    await db.prepare(
      `INSERT INTO audit_trail ("user", action, module, details)
       VALUES (?, ?, ?, ?)`
    ).run(deletedBy, 'Archived Org Entity', 'OrgStructure', `Archived entity ID: ${id}`);
  }
}

import fs from 'fs';
import path from 'path';
import { db } from '../db/index';
import { NumberingService } from './NumberingService';
import { NotFoundError, ValidationError } from '../utils/errors';

/**
 * EvidenceStorageService: Manages structured file storage for audit evidence.
 *
 * Evidence files are stored in organized directories following the pattern:
 *   /uploads/findings/{plan_id}/{finding_id}/{evidence_number}_{file_name}
 *
 * Provides:
 * - Path construction with sanitized file names
 * - File name sanitization (path traversal prevention)
 * - Atomic evidence attachment with rollback on failure
 *
 * Requirements: 8.1, 8.2, 8.3, 8.4, 8.5, 8.6, 8.7
 */

export interface EvidenceFile {
  originalname: string;
  buffer: Buffer;
  mimetype?: string;
}

export interface EvidenceData {
  type: 'Document' | 'Email' | 'Screenshot' | 'System Log' | 'Contract';
  description: string;
}

export interface AttachEvidenceResult {
  id: string;
  evidence_number: string;
  file_path: string;
  finding_id: string;
}

export class EvidenceStorageService {
  /** Base directory for uploads (relative to process.cwd()) */
  private static readonly UPLOAD_BASE = path.join(process.cwd(), 'uploads', 'findings');

  /**
   * Sanitizes a file name by removing path separators, traversal sequences,
   * absolute path prefixes, and truncating to 255 characters.
   *
   * Prevents path traversal attacks by stripping:
   * - Forward slashes (/)
   * - Backslashes (\)
   * - Parent directory sequences (../ or ..\)
   * - Absolute path prefixes (e.g., C:\, D:\, /)
   *
   * @param fileName - The original file name to sanitize
   * @returns The sanitized file name, truncated to 255 chars max
   */
  static sanitizeFileName(fileName: string): string {
    if (!fileName) return '';

    let sanitized = fileName;

    // Remove ../ and ..\ sequences (repeated until none remain)
    while (sanitized.includes('../') || sanitized.includes('..\\')) {
      sanitized = sanitized.replace(/\.\.\//g, '').replace(/\.\.\\/g, '');
    }

    // Remove absolute path prefixes (Windows drive letters like C:\, D:/)
    sanitized = sanitized.replace(/^[A-Za-z]:[/\\]/g, '');

    // Remove leading slash (Unix absolute path)
    sanitized = sanitized.replace(/^[/\\]+/, '');

    // Remove all remaining path separators
    sanitized = sanitized.replace(/[/\\]/g, '');

    // Truncate to 255 characters
    if (sanitized.length > 255) {
      sanitized = sanitized.substring(0, 255);
    }

    return sanitized;
  }

  /**
   * Builds the structured evidence file path.
   *
   * Format: /uploads/findings/{plan_id}/{finding_id}/{evidence_number}_{file_name}
   *
   * @param planId - The audit plan UUID
   * @param findingId - The finding UUID
   * @param evidenceNumber - The sequential evidence number (e.g., "IA-PL-25-001-F01-E01")
   * @param fileName - The original file name (will be sanitized)
   * @returns The full relative path for the evidence file
   */
  static buildEvidencePath(
    planId: string,
    findingId: string,
    evidenceNumber: string,
    fileName: string
  ): string {
    const sanitizedName = this.sanitizeFileName(fileName);
    return `/uploads/findings/${planId}/${findingId}/${evidenceNumber}_${sanitizedName}`;
  }

  /**
   * Attaches evidence to a finding with atomic file write + DB insert.
   *
   * Workflow:
   * 1. Validate finding exists (fetch finding + plan info)
   * 2. Generate evidence_number via NumberingService
   * 3. Build structured file path
   * 4. Write file to disk (if fails → no DB insert)
   * 5. Insert DB record (if fails → delete written file)
   *
   * @param findingId - The finding UUID to attach evidence to
   * @param file - The uploaded file (buffer + originalname)
   * @param data - Evidence metadata (type, description)
   * @param userId - The user performing the upload
   * @returns The created evidence record details
   * @throws NotFoundError if finding does not exist
   * @throws Error if file write or DB insert fails
   */
  static async attachEvidence(
    findingId: string,
    file: EvidenceFile,
    data: EvidenceData,
    userId: string
  ): Promise<AttachEvidenceResult> {
    // 1. Validate finding exists and get plan info
    const finding = await db.prepare(
      `SELECT af.id, af.audit_id, af.finding_number
       FROM audit_findings af
       WHERE af.id = ?`
    ).get(findingId) as { id: string; audit_id: string; finding_number: string } | undefined;

    if (!finding) {
      throw new NotFoundError('الملاحظة غير موجودة / Finding not found');
    }

    const planId = finding.audit_id;

    // 2. Generate evidence number via NumberingService
    const evidenceNumber = await NumberingService.nextEvidenceNumber(findingId, finding.finding_number);

    // 3. Build structured file path
    const filePath = this.buildEvidencePath(planId, findingId, evidenceNumber, file.originalname);

    // 4. Write file to disk
    const absolutePath = path.join(process.cwd(), filePath);
    const dir = path.dirname(absolutePath);

    try {
      await fs.promises.mkdir(dir, { recursive: true });
      await fs.promises.writeFile(absolutePath, file.buffer, { mode: 0o600 });
    } catch (fileError) {
      // File write failed → no DB insert (Requirement 8.6)
      throw new Error(`فشل كتابة الملف / File storage failed: ${(fileError as Error).message}`);
    }

    // 5. Insert DB record - if fails, rollback file write (Requirement 8.7)
    try {
      const record = await db.prepare(`
        INSERT INTO audit_evidence (
          audit_id, finding_id, evidence_number, type, description,
          uploaded_by, upload_date, file_name, file_path
        ) VALUES (?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, ?, ?)
        RETURNING id, evidence_number, file_path, finding_id
      `).get(
        planId,
        findingId,
        evidenceNumber,
        data.type,
        data.description,
        userId,
        file.originalname,
        filePath
      ) as AttachEvidenceResult | undefined;

      if (!record) {
        throw new Error('Failed to insert evidence record');
      }

      return record;
    } catch (dbError) {
      // DB insert failed → rollback file write (delete the written file)
      try {
        await fs.promises.unlink(absolutePath);
      } catch {
        // Best effort cleanup - file may not exist if write was partial
      }
      throw new Error(`فشل حفظ سجل الدليل / Evidence record save failed: ${(dbError as Error).message}`);
    }
  }
}

import { db } from '../db/index';

export class ExecutiveReportService {
  static async getExecutiveSummary() {
    const totalAudits = await db.prepare("SELECT COUNT(*) as count FROM audit_plans").get() as any;
    const completedAudits = await db.prepare("SELECT COUNT(*) as count FROM audit_plans WHERE status = 'Closed'").get() as any;
    const highRiskFindings = await db.prepare("SELECT COUNT(*) as count FROM audit_findings WHERE risk_level IN ('High', 'Critical') AND status != 'Closed'").get() as any;
