    const findingsByDept = await db.prepare(`
      SELECT p.department, COUNT(f.id) as count 
      FROM audit_findings f 
      JOIN audit_plans p ON f.audit_id = p.id 
      GROUP BY p.department
    `).all();

    return {
      totalAudits: totalAudits.count,
      completedAudits: completedAudits.count,
      highRiskFindings: highRiskFindings.count,
      topRisks,
      findingsByDept
    };
  }
}

import { db } from '../db/index';
import { ValidationError, NotFoundError, ConflictError } from '../utils/errors';
import { ADMIN_ROLES } from '../../constants';
import { N8nService } from '../utils/n8nService';

export class FraudService {
  static async createRequest(userId: number | string, userName: string, reason: string) {
    const existing = await db.prepare("SELECT * FROM fraud_access_requests WHERE user_id = ? AND status = 'Pending'").get(userId);
    if (existing) {
      throw new ConflictError("You already have a pending request.");
    }

    const stmt = db.prepare("INSERT INTO fraud_access_requests (user_id, user_name, reason) VALUES (?::uuid, ?::text, ?::text)");
    const info = await stmt.run(userId, userName, reason);
    
    // --- AUTOMATION: Send event to n8n ---
    await N8nService.sendEvent('fraud_access_request.created', {
      requestId: info.lastInsertRowid,
      userId,
      userName,
      reason
    });

    return info.lastInsertRowid;
  }

  static async getRequests(user: any) {
    if (ADMIN_ROLES.includes(user.role)) {
      return await db.prepare("SELECT * FROM fraud_access_requests ORDER BY request_date DESC").all();
    } else {
      return await db.prepare("SELECT * FROM fraud_access_requests WHERE user_id = ? ORDER BY request_date DESC").all(user.id);
    }
  }

  static async getMyStatus(userId: number | string) {
    const approved = await db.prepare(`
      SELECT * FROM fraud_access_requests 
      WHERE user_id = ? 
      AND status = 'Approved' 
      AND (expires_at IS NULL OR expires_at > CURRENT_TIMESTAMP)
    `).get(userId);

    if (approved) {
      return { status: 'Approved', ...(approved as any) };
    }
    
    const latest = await db.prepare("SELECT * FROM fraud_access_requests WHERE user_id = ? ORDER BY request_date DESC LIMIT 1").get(userId);
    if (latest) {
      if ((latest as any).status === 'Approved') {
        return { status: 'None' };
      }
      return latest;
    }
    return { status: 'None' };
  }

  static async approveRequest(id: string, duration: number | string, responderId: number | string) {
    const request = await db.prepare("SELECT * FROM fraud_access_requests WHERE id = ?").get(id) as any;
    if (!request) throw new NotFoundError("Request not found");

    let expiresAt = null;
    if (duration) {
      const date = new Date();
      const durationNum = typeof duration === 'string' ? parseInt(duration, 10) : duration;
      date.setDate(date.getDate() + durationNum);
      expiresAt = date.toISOString();
    }

    await db.prepare("UPDATE fraud_access_requests SET status = 'Approved', response_date = CURRENT_TIMESTAMP, responded_by = ?::uuid, expires_at = ?::timestamp WHERE id = ?::uuid")
              .run(responderId, expiresAt, id);
    
    // --- AUTOMATION: Send event to n8n ---
    await N8nService.sendEvent('fraud_access_request.status_changed', {
      requestId: id,
      status: 'Approved',
      duration,
      responderId
    });

    return request;
  }

  static async rejectRequest(id: string, reason: string, responderId: number | string) {
    const request = await db.prepare("SELECT * FROM fraud_access_requests WHERE id = ?").get(id) as any;
    if (!request) throw new NotFoundError("Request not found");

    await db.prepare("UPDATE fraud_access_requests SET status = 'Rejected', rejection_reason = ?::text, response_date = CURRENT_TIMESTAMP, responded_by = ?::uuid WHERE id = ?::uuid")
              .run(reason, responderId, id);
    
    // --- AUTOMATION: Send event to n8n ---
    await N8nService.sendEvent('fraud_access_request.status_changed', {
      requestId: id,
      status: 'Rejected',
      reason,
      responderId
    });

    return request;
  }
}

import { db } from '../db/index';

export class IntegrityService {
  static async getIntegrityStats() {
    const promises = [
      db.prepare("SELECT COUNT(*) as count FROM conflict_of_interest").get(),
      db.prepare("SELECT COUNT(*) as count FROM fraud_log").get(),
      db.prepare("SELECT COUNT(*) as count FROM conflict_of_interest WHERE status = 'pending'").get(),
      db.prepare("SELECT COUNT(*) as count FROM fraud_log WHERE status = 'Open' OR status = 'Pending'").get()
    ];

    const [conflictsTotal, fraudTotal, pendingConflicts, openFraud] = await Promise.all(promises) as any[];

    return {
      conflicts: {
        total: Number(conflictsTotal?.count || 0),
        pending: Number(pendingConflicts?.count || 0)
      },
      fraud: {
        total: Number(fraudTotal?.count || 0),
        open: Number(openFraud?.count || 0)
      },
      summary: {
        total: Number(conflictsTotal?.count || 0) + Number(fraudTotal?.count || 0),
        active: Number(pendingConflicts?.count || 0) + Number(openFraud?.count || 0)
      }
    };
  }
}

import { db } from '../db/index';
import { NotFoundError, ValidationError } from '../utils/errors';

export class JobTitleService {
  static async getAll() {
    return await db.prepare(`SELECT * FROM job_titles`).all();
  }

  static async create(data: any, username: string) {
    const { name, department, job_level, description, reporting_to, status } = data;
    const stmt = db.prepare(`INSERT INTO job_titles (name, department, job_level, description, reporting_to, status) VALUES (?, ?, ?, ?, ?, ?)`);
    const info = await stmt.run(name, department, job_level, description, reporting_to || null, status || 'Active');
    
    await db.prepare("INSERT INTO audit_trail (user, action, module, details) VALUES (?::text, ?::text, ?::text, ?::text)")
      .run(username, "Created Job Title", "Job Titles", `Created job title ${name}`);
      
    return { id: info.lastInsertRowid, name, department, job_level, description, reporting_to, status: status || 'Active' };
  }

  static async update(id: string | number, data: any, username: string) {
    const { name, department, job_level, description, reporting_to, status } = data;
    await db.prepare(`UPDATE job_titles SET name = ?, department = ?, job_level = ?, description = ?, reporting_to = ?, status = ? WHERE id = ?`)
      .run(name, department, job_level, description, reporting_to || null, status, id);
    
    await db.prepare("INSERT INTO audit_trail (user, action, module, details) VALUES (?::text, ?::text, ?::text, ?::text)")
      .run(username, "Updated Job Title", "Job Titles", `Updated job title ID ${id}`);
      
    return true;
  }

  static async delete(id: string | number, username: string) {
    // Check if assigned to any users
    const assignedUsers = await db.prepare("SELECT COUNT(*) as count FROM users WHERE job_title_id = ?").get(id) as any;
    if (assignedUsers.count > 0) {
      throw new ValidationError("Cannot delete job title assigned to users. Please mark as Inactive instead.");
    }

    const jobTitle = await db.prepare("SELECT name FROM job_titles WHERE id = ?").get(id) as any;
    if (!jobTitle) throw new NotFoundError("Job title not found");
    
    await db.prepare(`DELETE FROM job_titles WHERE id = ?`).run(id);
    
    await db.prepare("INSERT INTO audit_trail (user, action, module, details) VALUES (?::text, ?::text, ?::text, ?::text)")
      .run(username, "Deleted Job Title", "Job Titles", `Deleted job title ${jobTitle.name}`);
      
    return true;
  }
}

import { db } from '../db/index';
import { NotFoundError } from '../utils/errors';

export class LogService {
  static async getLoginHistory(query: any) {
    const page = parseInt(query.page as string) || 1;
    const pageSize = parseInt(query.pageSize as string) || 50;
    const offset = (page - 1) * pageSize;

    const countRes = await db.prepare(`SELECT COUNT(*) as total FROM login_history`).get() as any;
    const total = countRes?.total || 0;

    const history = await db.prepare(`
      SELECT l.id, l.user_id, l.login_time, l.ip_address, l.user_agent, l.status, u.name as user_name
      FROM login_history l
      LEFT JOIN users u ON l.user_id = u.id
      ORDER BY l.login_time DESC
      LIMIT ? OFFSET ?
    `).all(pageSize, offset);
    
    return {
      data: history,
      pagination: {
        page,
        pageSize,
        total,
        totalPages: Math.ceil(total / pageSize)
      }
    };
  }

  static async getAuditTrail(query: any) {
    const page = parseInt(query.page as string) || 1;
    const pageSize = parseInt(query.pageSize as string) || 50;
    const offset = (page - 1) * pageSize;
    const { module, action, username } = query;

    const conditions: string[] = [];
    const params: any[] = [];

    if (module) {
      conditions.push("LOWER(module) LIKE ?");
      params.push(`%${module.toLowerCase()}%`);
    }
    if (action) {
      conditions.push("LOWER(action) LIKE ?");
      params.push(`%${action.toLowerCase()}%`);
    }
    if (username) {
      conditions.push('"user" LIKE ?');
      params.push(`%${username}%`);
    }

    const whereClause = conditions.length > 0 ? ` WHERE ${conditions.join(' AND ')}` : "";

    const countRes = await db.prepare(`SELECT COUNT(*) as total FROM audit_trail${whereClause}`).get(...params) as any;
    const total = countRes?.total || 0;

    const logs = await db.prepare(`SELECT id, "user", action, module, details, timestamp FROM audit_trail${whereClause} ORDER BY timestamp DESC LIMIT ? OFFSET ?`)
      .all(...params, pageSize, offset);
    
    return {
      data: logs,
      pagination: {
        page,
        pageSize,
        total,
        totalPages: Math.ceil(total / pageSize)
      }
    };
  }

  static async logSystemError(data: any) {
    const { message, stack, module, userId, severity, user_agent, url, request_data } = data;
    await db.prepare(`
      INSERT INTO system_error_log 
      (message, stack, module, user_id, severity, user_agent, url, request_data) 
      VALUES (?::text, ?::text, ?::text, ?::uuid, ?::text, ?::text, ?::text, ?::text)
    `).run(
      message, 
      stack ? stack.substring(0, 2000) : null, 
      module, 
      userId || null, 
      severity || 'error', 
      user_agent || null, 
      url || null, 
      request_data ? JSON.stringify(request_data) : null
    );
    return true;
  }

  static async getSystemErrors(query: any) {
    const page = parseInt(query.page as string) || 1;
    const pageSize = parseInt(query.pageSize as string) || 50;
    const offset = (page - 1) * pageSize;
    const { module, severity, start_date, end_date, user_id } = query;

    const conditions: string[] = [];
    const params: any[] = [];

    if (module) {
      conditions.push("module LIKE ?");
      params.push(`%${module}%`);
    }
    if (severity) {
      conditions.push("severity = ?");
      params.push(severity);
    }
    if (start_date) {
      conditions.push("timestamp >= ?");
      params.push(start_date);
    }
    if (end_date) {
      conditions.push("timestamp <= ?");
      params.push(end_date);
    }
    if (user_id) {
      conditions.push("user_id = ?");
      params.push(user_id);
    }

    const whereClause = conditions.length > 0 ? ` WHERE ${conditions.join(' AND ')}` : "";

    const countRes = await db.prepare(`SELECT COUNT(*) as total FROM system_error_log${whereClause}`).get(...params) as any;
    const total = countRes?.total || 0;

    const logs = await db.prepare(`SELECT id, message, module, user_id, severity, url, timestamp FROM system_error_log${whereClause} ORDER BY timestamp DESC LIMIT ? OFFSET ?`)
      .all(...params, pageSize, offset) as any[];
    
    return {
      data: logs.map(log => ({ ...log, request_data: log.request_data ? JSON.parse(log.request_data) : null })),
      pagination: {
        page,
        pageSize,
        total,
        totalPages: Math.ceil(total / pageSize)
      }
    };
  }

  static async clearSystemErrors() {
    await db.prepare("DELETE FROM system_error_log").run();
    return true;
  }

  static async getSystemErrorsForExport() {
    return await db.prepare("SELECT * FROM system_error_log ORDER BY timestamp DESC").all();
  }

  static async getSystemErrorAnalytics() {
    return await db.prepare(`
      SELECT severity, COUNT(*) as count, DATE(timestamp) as date
      FROM system_error_log
      GROUP BY severity, DATE(timestamp)
      ORDER BY date DESC
    `).all();
  }
}

