export class NotificationService {
  /**
   * Get notifications for a user with pagination (uses notification_recipients join).
   * Falls back to legacy single-table if notification_recipients doesn't exist yet.
   */
  static async getNotifications(userId: string | number, page = 1, pageSize = 20): Promise<{ data: NotificationFeedItem[]; pagination: PaginationMeta }> {
    const offset = (page - 1) * pageSize;

    try {
      // Try new two-table architecture first
      const countRes = await db.prepare(
        "SELECT COUNT(*) as total FROM notification_recipients WHERE recipient_id = ?::uuid AND is_dismissed = false"
      ).get(userId) as any;
      const total = countRes?.total || 0;

      const results = await db.prepare(`
        SELECT 
          n.id,
          nr.id as recipient_row_id,
          n.event_type,
          n.title,
          n.description,
          n.related_module,
          n.link,
          n.actor_id,
          n.entity_id,
          n.entity_type,
          n.data,
          n.date,
          nr.is_read,
          nr.read_at
        FROM notification_recipients nr
        JOIN notifications n ON n.id = nr.notification_id
        WHERE nr.recipient_id = ?::uuid AND nr.is_dismissed = false
        ORDER BY n.date DESC
        LIMIT ? OFFSET ?
      `).all(userId, pageSize, offset) as any[];

      return {
        data: results,
        pagination: computePaginationMeta(page, pageSize, total)
      };
    } catch {
      // Fallback to legacy single-table
      const countRes = await db.prepare(
        "SELECT COUNT(*) as total FROM notifications WHERE user_id = ?::uuid"
      ).get(userId) as any;
      const total = countRes?.total || 0;

      const results = await db.prepare(
        "SELECT id, id as recipient_row_id, event_type, description, related_module, link, actor_id, entity_id, entity_type, data, date, CASE WHEN status = 'Read' THEN true ELSE false END as is_read, NULL as read_at, NULL as title FROM notifications WHERE user_id = ?::uuid ORDER BY date DESC LIMIT ? OFFSET ?"
      ).all(userId, pageSize, offset) as any[];
      return {
        data: results,
        pagination: computePaginationMeta(page, pageSize, total)
      };
    }
  }

  /**
   * Get unread count for a user.
   */
  static async getUnreadCount(userId: string | number): Promise<{ count: number }> {
    try {
      const result = await db.prepare(
        "SELECT COUNT(*) as count FROM notification_recipients WHERE recipient_id = ?::uuid AND is_read = false AND is_dismissed = false"
      ).get(userId) as any;
      return result || { count: 0 };
    } catch {
      // Fallback
      const result = await db.prepare(
        "SELECT COUNT(*) as count FROM notifications WHERE user_id = ?::uuid AND status = 'Unread'"
      ).get(userId) as any;
      return result || { count: 0 };
    }
  }

  /**
   * Mark a single notification as read for a specific user.
   */
  static async markAsRead(notificationId: string | number, userId: string | number) {
    try {
      await db.prepare(
        "UPDATE notification_recipients SET is_read = true, read_at = CURRENT_TIMESTAMP WHERE notification_id = ?::uuid AND recipient_id = ?::uuid"
      ).run(notificationId, userId);
    } catch {
      // Fallback
      await db.prepare(
        "UPDATE notifications SET status = 'Read' WHERE id = ?::uuid AND user_id = ?::uuid"
      ).run(notificationId, userId);
    }
    return true;
  }

  /**
   * Mark all notifications as read for a specific user.
   */
  static async markAllRead(userId: string | number) {
    try {
      await db.prepare(
        "UPDATE notification_recipients SET is_read = true, read_at = CURRENT_TIMESTAMP WHERE recipient_id = ?::uuid AND is_read = false"
      ).run(userId);
    } catch {
      // Fallback
      await db.prepare(
        "UPDATE notifications SET status = 'Read' WHERE user_id = ?::uuid AND status = 'Unread'"
      ).run(userId);
    }
    return true;
  }

  /**
   * Dismiss (soft-delete) a notification for a specific user.
   * Does NOT delete from DB — just marks is_dismissed = true for this user.
   */
  static async dismiss(notificationId: string | number, userId: string | number) {
    try {
      await db.prepare(
        "UPDATE notification_recipients SET is_dismissed = true, dismissed_at = CURRENT_TIMESTAMP WHERE notification_id = ?::uuid AND recipient_id = ?::uuid"
      ).run(notificationId, userId);
    } catch {
      // Fallback: actually delete from legacy table
      await db.prepare(
        "DELETE FROM notifications WHERE id = ?::uuid AND user_id = ?::uuid"
      ).run(notificationId, userId);
    }
    return true;
  }

  /**
   * Create a notification and insert recipient rows for each target user.
   * One notification row → many recipient rows (per-user isolation).
   */
  static async create(
    recipientIds: string | string[] | 'all',
    type: string,
    message: string,
    module: string,
    link: string,
    options?: CreateNotificationOptions
  ) {
    const { actorId, entityId, entityType, data, wss, title } = options || {};
    const dataJson = data ? JSON.stringify(data) : '{}';

    // Resolve recipient list
    let targetUserIds: string[] = [];

    if (recipientIds === 'all') {
      const users = await db.prepare("SELECT id FROM users WHERE status = 'active'").all() as any[];
      targetUserIds = users.map((u: any) => u.id);
    } else if (Array.isArray(recipientIds)) {
      targetUserIds = [...recipientIds];
    } else {
      targetUserIds = [String(recipientIds)];
    }

    // Exclude the actor from recipients (don't notify yourself)
    if (actorId) {
      targetUserIds = targetUserIds.filter(id => id !== actorId);
    }

    if (targetUserIds.length === 0) return true;

    try {
      // Insert ONE notification row
      const notifResult = await db.prepare(`
        INSERT INTO notifications (event_type, description, related_module, link, actor_id, entity_id, entity_type, data, title, status, user_id, date)
        VALUES (?::text, ?::text, ?::text, ?::text, ${actorId ? '?::uuid' : 'NULL'}, ${entityId ? '?::uuid' : 'NULL'}, ${entityType ? '?::text' : 'NULL'}, ?::jsonb, ${title ? '?::text' : 'NULL'}, 'Unread', ?::uuid, CURRENT_TIMESTAMP)
        RETURNING id, date
      `).get(
        ...[type, message, module, link,
          ...(actorId ? [actorId] : []),
          ...(entityId ? [entityId] : []),
          ...(entityType ? [entityType] : []),
          dataJson,
          ...(title ? [title] : []),
          targetUserIds[0] // user_id for legacy compat
        ]
      ) as any;

      const notificationId = notifResult?.id;
      const notificationDate = notifResult?.date;

      if (notificationId) {
        // Insert recipient rows for each target user
        for (const uid of targetUserIds) {
          await db.prepare(
            "INSERT INTO notification_recipients (notification_id, recipient_id) VALUES (?::uuid, ?::uuid)"
          ).run(notificationId, uid);
        }

        // Also insert legacy rows for remaining users (backward compat with old frontend queries)
        // Skip first user since we already used them for the main notification row
        for (let i = 1; i < targetUserIds.length; i++) {
          await db.prepare(`
            INSERT INTO notifications (event_type, description, related_module, link, actor_id, entity_id, entity_type, data, title, status, user_id, date)
            VALUES (?::text, ?::text, ?::text, ?::text, ${actorId ? '?::uuid' : 'NULL'}, ${entityId ? '?::uuid' : 'NULL'}, ${entityType ? '?::text' : 'NULL'}, ?::jsonb, ${title ? '?::text' : 'NULL'}, 'Unread', ?::uuid, CURRENT_TIMESTAMP)
          `).run(
            ...[type, message, module, link,
              ...(actorId ? [actorId] : []),
              ...(entityId ? [entityId] : []),
              ...(entityType ? [entityType] : []),
              dataJson,
              ...(title ? [title] : []),
              targetUserIds[i]
            ]
          );
        }
      }

      // Real-time WebSocket push to each target user
      if (wss && targetUserIds.length > 0) {
        const payload = JSON.stringify({
          type: 'NEW_NOTIFICATION',
          notification: {
            id: notificationId,
            event_type: type,
            title: title || null,
            description: message,
            related_module: module,
            link,
            is_read: false,
            date: notificationDate || new Date().toISOString(),
            actor_id: actorId || null,
            entity_id: entityId || null,
            entity_type: entityType || null,
          }
        });

        wss.clients.forEach((client: any) => {
          if (client.readyState === 1 && client.authenticated && targetUserIds.includes(client.userId)) {
            client.send(payload);
          }
        });
      }
    } catch (e) {
      // Fallback: insert one row per user (legacy behavior)
      console.error("[NotificationService] Two-table insert failed, using legacy:", (e as any)?.message);
      for (const uid of targetUserIds) {
        try {
          await db.prepare(`
            INSERT INTO notifications (user_id, event_type, description, related_module, link, status, actor_id, entity_id, entity_type, data)
            VALUES (?::uuid, ?::text, ?::text, ?::text, ?::text, 'Unread', ${actorId ? '?::uuid' : 'NULL'}, ${entityId ? '?::uuid' : 'NULL'}, ${entityType ? '?::text' : 'NULL'}, ?::jsonb)
          `).run(
            ...[uid, type, message, module, link,
              ...(actorId ? [actorId] : []),
              ...(entityId ? [entityId] : []),
              ...(entityType ? [entityType] : []),
              dataJson
            ]
          );
        } catch { /* skip */ }
      }
    }

    return true;
  }

  /** Get admin user IDs */
  static async getAdminIds(): Promise<string[]> {
    const admins = await db.prepare(
      `SELECT id FROM users WHERE role = '${UserRole.ADMIN}' AND status = 'active'`
    ).all() as any[];
    return admins.map((a: any) => a.id);
  }

  /** Get user ID by name or username */
  static async getUserIdByName(name: string): Promise<string | null> {
    const user = await db.prepare(
      "SELECT id FROM users WHERE name = ? OR username = ?"
    ).get(name, name) as any;
    return user?.id || null;
  }

  /** Get users in a specific department */
  static async getUserIdsByDepartment(department: string): Promise<string[]> {
    const users = await db.prepare(
      "SELECT id FROM users WHERE department = ? AND status = 'active'"
    ).all(department) as any[];
    return users.map((u: any) => u.id);
  }
}

import { db } from '../db/index';
import { ValidationError, ConflictError } from '../utils/errors';

export class OrgService {
  static async getOrgEntities() {
    return await db.prepare(`
      SELECT e.*, p.name_ar as parent_name_ar, p.name_en as parent_name_en, u.name as manager_name_full
      FROM org_entities e
      LEFT JOIN org_entities p ON e.parent_id = p.id
      LEFT JOIN users u ON e.manager_id = u.id
      ORDER BY e.display_order, e.name_ar
    `).all();
  }

  static async createOrgEntity(data: any) {
    const { 
      entity_code, name_ar, name_en, entity_type, parent_id, 
      manager_id, manager_name, level, status, description, 
      display_order, location, cost_center_code, notes 
    } = data;

    try {
      const result = await db.prepare(`
        INSERT INTO org_entities (
          entity_code, name_ar, name_en, entity_type, parent_id, 
          manager_id, manager_name, level, status, description, 
          display_order, location, cost_center_code, notes
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `).run(
        entity_code, name_ar, name_en, entity_type, parent_id, 
        manager_id, manager_name, level || 1, status || 'Active', description, 
        display_order || 0, location, cost_center_code, notes
      );

      return result.lastInsertRowid;
    } catch (error: any) {
      if (error.message.includes("UNIQUE constraint failed: org_entities.entity_code")) {
        throw new ConflictError("Entity code must be unique");
      }
      throw error;
    }
  }

  static async updateOrgEntity(id: string, data: any) {
    const { 
      entity_code, name_ar, name_en, entity_type, parent_id, 
      manager_id, manager_name, level, status, description, 
      display_order, location, cost_center_code, notes 
    } = data;

    // Check for circular reference
    if (parent_id && parseInt(parent_id) === parseInt(id)) {
      throw new ValidationError("An entity cannot be its own parent");
    }

    await db.prepare(`
      UPDATE org_entities SET 
        entity_code = ?, name_ar = ?, name_en = ?, entity_type = ?, parent_id = ?, 
        manager_id = ?, manager_name = ?, level = ?, status = ?, description = ?, 
        display_order = ?, location = ?, cost_center_code = ?, notes = ?, updated_at = CURRENT_TIMESTAMP
      WHERE id = ?
    `).run(
      entity_code, name_ar, name_en, entity_type, parent_id, 
      manager_id, manager_name, level, status, description, 
      display_order, location, cost_center_code, notes, id
    );
  }

  static async deleteOrgEntity(id: string) {
    // Check if has children
    const children = await db.prepare("SELECT COUNT(*) as count FROM org_entities WHERE parent_id = ?").get(id) as any;
    if (children.count > 0) {
      throw new ValidationError("Cannot delete entity with sub-entities. Move or delete children first.");
    }

    // Check if linked to users
    const users = await db.prepare("SELECT COUNT(*) as count FROM users WHERE org_entity_id = ? OR division_id = ? OR unit_id = ?").get(id, id, id) as any;
    if (users.count > 0) {
      throw new ValidationError("Cannot delete entity linked to users. Archive it instead.");
    }

    await db.prepare("DELETE FROM org_entities WHERE id = ?").run(id);
  }
}

import crypto from 'crypto';
import bcrypt from 'bcryptjs';
import { db } from '../db/index';
import { NotFoundError, ValidationError, AuthError } from '../utils/errors';
import { invalidateUserCache } from '../middleware/auth';
import { UserRole } from '../../constants';

export class PasswordService {
  static async requestReset(username: string) {
    const user = await db.prepare("SELECT id, username, name, department FROM users WHERE LOWER(username) = LOWER(?) OR LOWER(email) = LOWER(?)").get(username, username) as any;
    
    if (!user) {
      return { success: true, message: "If the username exists, a request has been sent to the administrator." };
    }

    const existing = await db.prepare("SELECT id FROM password_reset_requests WHERE user_id = ? AND status = 'Pending'").get(user.id);
    if (existing) {
      return { success: true, message: "A request is already pending." };
    }

    await db.prepare(`INSERT INTO password_reset_requests (user_id, username, name, department) VALUES (?::uuid, ?::text, ?::text, ?::text)`)
      .run(user.id, user.username, user.name, user.department);
    
    const admins = await db.prepare(`SELECT id FROM users WHERE role = '${UserRole.ADMIN}'`).all() as {id: number}[];
    const alertMsg = `Password Reset Request\nUsername: ${user.username}\nName: ${user.name}\nDepartment: ${user.department || 'N/A'}`;
    
    return {
      success: true,
      user,
      admins,
      alertMsg
    };
  }

  static async getResetStatus(username: string) {
    const user = await db.prepare("SELECT id, requires_password_change FROM users WHERE LOWER(username) = LOWER(?) OR LOWER(email) = LOWER(?)").get(username, username) as any;
    if (!user) return 'None';

    if (user.requires_password_change === 0) return 'None';

    const request = await db.prepare("SELECT status FROM password_reset_requests WHERE user_id = ? ORDER BY request_date DESC LIMIT 1").get(user.id) as any;
    if (!request) return 'None';

    return request.status;
  }

  static async approveReset(requestId: string, adminId: string) {
    const request = await db.prepare("SELECT * FROM password_reset_requests WHERE id = ?").get(requestId) as any;
    
    if (!request) {
      throw new NotFoundError("Request not found");
    }

    const tempPass = crypto.randomBytes(6).toString('base64url') + "!";
    const hashedTemp = bcrypt.hashSync(tempPass, 12);

    await db.prepare("UPDATE users SET password = ?::text, requires_password_change = 1, failed_attempts = 0, locked_until = NULL, session_version = session_version + 1 WHERE id = ?::uuid")
      .run(hashedTemp, request.user_id);

    await db.prepare("UPDATE password_reset_requests SET status = 'Approved', resolved_date = CURRENT_TIMESTAMP, resolved_by = ?::uuid WHERE id = ?::uuid")
      .run(adminId, requestId);

    return {
      tempPassword: tempPass,
      username: request.username,
      userId: request.user_id
    };
  }

  static async changePassword(userId: string, newPassword: string) {
    const user = await db.prepare("SELECT id, password, session_version, username, role FROM users WHERE id = ?").get(userId) as any;

    if (!user) throw new NotFoundError("User not found");

    // Validate password against policy settings
    await this.validatePasswordPolicy(newPassword);

    if (bcrypt.compareSync(newPassword, user.password)) {
      throw new ValidationError("New password cannot be the same as the current password");
    }

    const history = await db.prepare("SELECT password_hash FROM password_history WHERE user_id = ? ORDER BY created_at DESC LIMIT 5").all(user.id) as { password_hash: string }[];
    
    for (const record of history) {
      if (bcrypt.compareSync(newPassword, record.password_hash)) {
        throw new ValidationError("Password has been used previously. Please choose a different one.");
      }
    }

    const hashed = bcrypt.hashSync(newPassword, 12);
    
    const transaction = db.transaction(async () => {
      await db.prepare("INSERT INTO password_history (user_id, password_hash) VALUES (?::uuid, ?::text)").run(user.id, user.password);
      await db.prepare("UPDATE users SET password = ?::text, password_last_changed = CURRENT_TIMESTAMP, requires_password_change = 0, session_version = session_version + 1 WHERE id = ?::uuid").run(hashed, user.id);
    });
    
    await transaction();
    
    // Invalidate cached user data so middleware picks up new session_version
    invalidateUserCache(user.id);
    
    const updatedUser = await db.prepare("SELECT id, username, role, session_version FROM users WHERE id = ?").get(user.id) as any;
    return updatedUser;
  }

  static async updatePassword(userId: string, currentPassword: string, newPassword: string) {
    const user = await db.prepare("SELECT id, password, username, role FROM users WHERE id = ?").get(userId) as any;
    
    if (!user) throw new NotFoundError("User not found");

    if (!bcrypt.compareSync(currentPassword, user.password)) {
      throw new AuthError("Incorrect current password");
    }

    if (currentPassword === newPassword) {
      throw new ValidationError("New password cannot be the same as the current password");
    }

    // Validate password against policy settings
    await this.validatePasswordPolicy(newPassword);

    const history = await db.prepare("SELECT password_hash FROM password_history WHERE user_id = ? ORDER BY created_at DESC LIMIT 5").all(user.id) as { password_hash: string }[];
    
    for (const record of history) {
      if (bcrypt.compareSync(newPassword, record.password_hash)) {
        throw new ValidationError("Password has been used previously. Please choose a different one.");
      }
    }

    const hashed = bcrypt.hashSync(newPassword, 12);
    
    const transaction = db.transaction(async () => {
      await db.prepare("INSERT INTO password_history (user_id, password_hash) VALUES (?::uuid, ?::text)").run(user.id, user.password);
      await db.prepare("UPDATE users SET password = ?::text, password_last_changed = CURRENT_TIMESTAMP, requires_password_change = 0, session_version = session_version + 1 WHERE id = ?::uuid").run(hashed, user.id);
    });
    
    await transaction();
    
    // Invalidate cached user data so middleware picks up new session_version
    invalidateUserCache(user.id);
    
    const updatedUser = await db.prepare("SELECT id, username, role, session_version FROM users WHERE id = ?").get(user.id) as any;
    return updatedUser;
  }

  /** Validate password against system policy settings */
  private static async validatePasswordPolicy(password: string) {
    try {
      const settings = await db.prepare("SELECT password_min_length, password_require_uppercase, password_require_lowercase, password_require_numbers, password_require_symbols FROM user_management_settings WHERE id = 1").get() as any;
      
      if (!settings) return; // No settings, skip validation

      const minLength = settings.password_min_length || 8;
      if (password.length < minLength) {
        throw new ValidationError(`Password must be at least ${minLength} characters`);
      }
      if (settings.password_require_uppercase && !/[A-Z]/.test(password)) {
        throw new ValidationError("Password must contain at least one uppercase letter");
      }
      if (settings.password_require_lowercase && !/[a-z]/.test(password)) {
        throw new ValidationError("Password must contain at least one lowercase letter");
      }
      if (settings.password_require_numbers && !/[0-9]/.test(password)) {
        throw new ValidationError("Password must contain at least one number");
      }
      if (settings.password_require_symbols && !/[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(password)) {
        throw new ValidationError("Password must contain at least one special character");
      }
    } catch (e) {
      if (e instanceof ValidationError) throw e;
      // If settings query fails, skip policy validation
    }
  }

  static async getResetRequests() {
    return await db.prepare("SELECT * FROM password_reset_requests WHERE status = 'Pending' ORDER BY request_date DESC").all();
  }
}

import { db } from '../db/index';
import { NotFoundError, ValidationError } from '../utils/errors';
import { BaseService } from './BaseService';

export class PdfTemplateService {
  static async getAll() {
    return await db.prepare("SELECT * FROM pdf_templates ORDER BY created_at DESC").all();
  }

  static async getById(id: string) {
    const template = await db.prepare("SELECT * FROM pdf_templates WHERE id = ?::uuid").get(id);
    if (!template) throw new NotFoundError("Template not found");
    return template;
  }
  
  static async getActiveByType(type: string) {
    const template = await db.prepare("SELECT * FROM pdf_templates WHERE template_type = ? AND status = 'Approved' AND is_default = 1 LIMIT 1").get(type);
    return template;
  }

  static async create(data: any, username: string) {
    if (!data.template_name || !data.template_type || !data.content) {
      throw new ValidationError("Missing required fields for PDF template");
    }

    return await db.transaction(async () => {
      // If saving as default, unset others of same type
      if (data.is_default && String(data.is_default) === '1') {
        await db.prepare("UPDATE pdf_templates SET is_default = 0 WHERE template_type = ?").run(data.template_type);
      }

      const stmt = db.prepare(`
        INSERT INTO pdf_templates (template_name, template_type, content, status, is_default, version, created_by, updated_by)
        VALUES (?, ?, ?, ?, ?, 1, ?, ?)
        RETURNING *
      `);
      
      const newTemplate = await stmt.get(
        data.template_name,
        data.template_type,
        data.content,
        data.status || 'Draft',
        data.is_default ? 1 : 0,
        username,
        username
      );

      await db.prepare("INSERT INTO audit_trail (user, action, module, details) VALUES (?, ?, ?, ?)").run(
        username, 'Created PDF Template', 'Settings', `Template ID: ${newTemplate.id}`
      );

      return newTemplate;
    });
  }

  static async update(id: string, data: any, username: string) {
    const existing = await this.getById(id);
    
    return await db.transaction(async () => {
      if (data.is_default && String(data.is_default) === '1') {
        await db.prepare("UPDATE pdf_templates SET is_default = 0 WHERE template_type = ?").run(data.template_type || existing.template_type);
      }

      // If content changed and not just status, maybe bump version
      let version = existing.version;
      if (data.content && data.content !== existing.content) {
        version += 1;
      }

      const stmt = db.prepare(`
        UPDATE pdf_templates 
        SET template_name = COALESCE(?, template_name),
            template_type = COALESCE(?, template_type),
            content = COALESCE(?, content),
            status = COALESCE(?, status),
            is_default = COALESCE(?, is_default),
            version = ?,
            updated_by = ?,
            updated_at = CURRENT_TIMESTAMP
        WHERE id = ?::uuid
        RETURNING *
      `);

      const updated = await stmt.get(
        data.template_name,
        data.template_type,
        data.content,
        data.status,
        data.is_default !== undefined ? (data.is_default ? 1 : 0) : null,
        version,
        username,
        id
      );

      await db.prepare("INSERT INTO audit_trail (user, action, module, details) VALUES (?, ?, ?, ?)").run(
        username, 'Updated PDF Template', 'Settings', `Template ID: ${id}, Status: ${updated.status}`
      );

      return updated;
    });
  }

  static async approve(id: string, username: string) {
    return await this.update(id, { status: 'Approved' }, username);
  }

  static async delete(id: string, username: string) {
    return await db.transaction(async () => {
      await db.prepare("DELETE FROM pdf_templates WHERE id = ?::uuid").run(id);
      
      await db.prepare("INSERT INTO audit_trail (user, action, module, details) VALUES (?, ?, ?, ?)").run(
        username, 'Deleted PDF Template', 'Settings', `Template ID: ${id}`
      );
      return true;
    });
  }
}

import { db } from '../db/index';

/**
 * Audit event types for permission changes.
 */
export type PermissionAuditEventType =
  | 'role_permission_change'
  | 'user_override_change'
  | 'custom_role_created'
  | 'custom_role_deleted';

/**
 * Audit log entry structure.
 */
export interface PermissionAuditEntry {
  id: string;
  eventType: PermissionAuditEventType;
  actorUserId: string;
  targetRoleId: string | null;
  targetUserId: string | null;
  oldState: any;
  newState: any;
  timestamp: string;
}

/**
 * Query filters for retrieving audit logs.
 */
export interface AuditLogQueryParams {
  actorUserId?: string;
  targetRoleId?: string;
  targetUserId?: string;
  eventType?: PermissionAuditEventType;
  startDate?: string;
  endDate?: string;
  page?: number;
  limit?: number;
}

/**
 * PermissionAuditService - Append-only audit logging for permission changes.
 *
 * Logs:
 * - Role permission changes (Req 12.1)
 * - User override changes (Req 12.2)
 * - Custom role creation/deletion (Req 12.3)
 *
 * Provides paginated, filterable retrieval (Req 12.4).
 * Entries are append-only - no modify/delete via API (Req 12.5).
 *
 * Requirements: 12.1, 12.2, 12.3, 12.4, 12.5, 12.6
 */
export class PermissionAuditService {
  /**
   * Create an audit log entry for a permission change.
   * Throws on failure so the caller can roll back the permission change (Req 12.6).
   */
  static async logPermissionChange(params: {
    eventType: PermissionAuditEventType;
    actorUserId: string;
    targetRoleId?: string | null;
    targetUserId?: string | null;
    oldState: any;
    newState: any;
  }): Promise<void> {
    const { eventType, actorUserId, targetRoleId, targetUserId, oldState, newState } = params;
    const timestamp = new Date().toISOString();

    await db
      .prepare(
        `INSERT INTO permission_audit_logs (event_type, actor_user_id, target_role_id, target_user_id, old_state, new_state, timestamp)
         VALUES (?, ?, ?, ?, ?, ?, ?)`
      )
      .run(
        eventType,
        actorUserId,
        targetRoleId || null,
        targetUserId || null,
        oldState !== null && oldState !== undefined ? JSON.stringify(oldState) : null,
        newState !== null && newState !== undefined ? JSON.stringify(newState) : null,
        timestamp
      );
  }

  /**
   * Query audit log entries with pagination and filtering.
   * Max 50 entries per page (Req 12.4).
   */
  static async getAuditLogs(params: AuditLogQueryParams): Promise<{
    entries: PermissionAuditEntry[];
    total: number;
    page: number;
    limit: number;
    totalPages: number;
  }> {
    const page = Math.max(1, params.page || 1);
    const limit = Math.min(50, Math.max(1, params.limit || 50));
    const offset = (page - 1) * limit;

    // Build WHERE clauses
    const conditions: string[] = [];
    const queryParams: any[] = [];

    if (params.actorUserId) {
      conditions.push('actor_user_id = ?');
      queryParams.push(params.actorUserId);
    }

    if (params.targetRoleId) {
      conditions.push('target_role_id = ?');
      queryParams.push(params.targetRoleId);
    }

    if (params.targetUserId) {
      conditions.push('target_user_id = ?');
      queryParams.push(params.targetUserId);
    }

    if (params.eventType) {
      conditions.push('event_type = ?');
      queryParams.push(params.eventType);
    }

    if (params.startDate) {
      conditions.push('timestamp >= ?');
      queryParams.push(params.startDate);
    }

    if (params.endDate) {
      conditions.push('timestamp <= ?');
      queryParams.push(params.endDate);
    }

    const whereClause = conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : '';

    // Get total count
    const countResult = await db
      .prepare(`SELECT COUNT(*)::int AS total FROM permission_audit_logs ${whereClause}`)
      .get(...queryParams);

    const total = countResult?.total || 0;

    // Get paginated entries
    const entries = await db
      .prepare(
        `SELECT id, event_type, actor_user_id, target_role_id, target_user_id, old_state, new_state, timestamp
         FROM permission_audit_logs
         ${whereClause}
         ORDER BY timestamp DESC
         LIMIT ? OFFSET ?`
      )
      .all(...queryParams, limit, offset);

    const mappedEntries: PermissionAuditEntry[] = entries.map((entry: any) => ({
      id: entry.id,
      eventType: entry.event_type,
      actorUserId: entry.actor_user_id,
      targetRoleId: entry.target_role_id || null,
      targetUserId: entry.target_user_id || null,
      oldState: entry.old_state ? JSON.parse(entry.old_state) : null,
      newState: entry.new_state ? JSON.parse(entry.new_state) : null,
      timestamp: entry.timestamp,
    }));

    return {
      entries: mappedEntries,
      total,
      page,
      limit,
      totalPages: Math.ceil(total / limit),
    };
  }
}

/**
 * PermissionCache - LRU cache for permission check results.
 *
 * Stores permission check results with key format: `perm_{userId}_{module}_{action}`
 * Default: max 1000 entries with 5-minute TTL and LRU eviction.
 *
 * Requirements: 5.1, 5.2, 5.3, 5.4, 5.6, 5.7
 */

interface CacheEntry {
  value: boolean;
  expiresAt: number;
}

export class PermissionCache {
  private store: Map<string, CacheEntry>;
  private readonly maxEntries: number;
  private readonly ttlMs: number;

  /**
   * @param maxEntries Maximum number of entries before LRU eviction (default: 1000)
   * @param ttlMinutes Time-to-live in minutes for each entry (default: 5)
   */
  constructor(maxEntries: number = 1000, ttlMinutes: number = 5) {
    this.store = new Map();
    this.maxEntries = maxEntries;
    this.ttlMs = ttlMinutes * 60 * 1000;
  }

  /**
   * Get a cached permission result.
   * Returns undefined on cache miss or expired entry.
   * Req 5.2, 5.7 (graceful fallback on failure)
   */
  get(key: string): boolean | undefined {
    try {
      const entry = this.store.get(key);
      if (!entry) return undefined;

      // Check TTL expiration (entry valid while now <= expiresAt)
      if (Date.now() > entry.expiresAt) {
        this.store.delete(key);
        return undefined;
      }

      // Move to end of Map for LRU ordering (most recently accessed = last)
      this.store.delete(key);
      this.store.set(key, entry);

      return entry.value;
    } catch (e) {
      // Req 5.7: graceful fallback on cache failure
      console.warn('[PermissionCache] get failed:', e);
      return undefined;
    }
  }

  /**
   * Store a permission result in cache.
   * Req 5.1: key format `perm_{userId}_{module}_{action}`, TTL 5 minutes
   * Req 5.6: max entries with LRU eviction
   */
  set(key: string, value: boolean): void {
    try {
      // If key already exists, delete it first to update LRU order
      if (this.store.has(key)) {
        this.store.delete(key);
      } else if (this.store.size >= this.maxEntries) {
        // Evict LRU entry (first entry in Map iteration order)
        const firstKey = this.store.keys().next().value;
        if (firstKey !== undefined) {
          this.store.delete(firstKey);
        }
      }

      this.store.set(key, {
        value,
        expiresAt: Date.now() + this.ttlMs,
      });
    } catch (e) {
      // Req 5.7: graceful fallback on cache failure - silently warn
      console.warn('[PermissionCache] set failed:', e);
    }
  }

  /**
   * Invalidate all cache entries for a specific user.
   * Removes entries matching prefix `perm_{userId}_`
   * Req 5.3
   */
  invalidateUser(userId: string): void {
    try {
      const prefix = `perm_${userId}_`;
      for (const key of this.store.keys()) {
        if (key.startsWith(prefix)) {
          this.store.delete(key);
        }
      }
    } catch (e) {
      console.warn('[PermissionCache] invalidateUser failed:', e);
    }
  }

  /**
   * Invalidate all permission cache entries (prefix `perm_`).
   * Req 5.4
   */
  invalidateAll(): void {
    try {
      for (const key of this.store.keys()) {
        if (key.startsWith('perm_')) {
          this.store.delete(key);
        }
      }
    } catch (e) {
      console.warn('[PermissionCache] invalidateAll failed:', e);
    }
  }

  /**
   * Get current cache size.
   */
  get size(): number {
    return this.store.size;
  }

  /**
   * Clear entire cache (for testing).
   */
  _reset(): void {
    this.store.clear();
  }
}

/** Default singleton PermissionCache instance (1000 entries, 5-min TTL) */
export const permissionCache = new PermissionCache();

import { db } from '../db/index';
import { ModuleRegistry } from '../../permissions/registry';
import { permissionCache } from './PermissionCache';
import {
  PermissionAction,
  PermissionUpdate,
  UserPermissionSet,
  RolePermissionSet,
} from '../../permissions/types';
import { UserRole } from '../../constants';

/**
 * PermissionService - Centralized service for all permission queries and mutations.
 *
 * Implements the permission resolution logic:
 * 1. Admin role → always true (no DB query)
 * 2. Module/action not in registry → always false
 * 3. Check cache → return if hit
 * 4. Check user_permissions (override) → if exists, use is_allowed
 * 5. Fall back to role_permissions → return whether a matching record exists
 * 6. Cache the result
 *
 * Requirements: 4.1, 4.2, 4.3, 4.4, 4.5, 4.6, 4.7, 5.1, 5.2, 5.3, 5.4, 5.5
 */
export class PermissionService {
  private static cache = permissionCache;

  /**
   * Check if a user has a specific permission.
   *
   * Resolution order:
   * - Admin role → true immediately (Req 4.5)
   * - Module/action not registered → false (Req 4.6)
   * - Cache hit → return cached value (Req 5.2)
   * - User override exists → use is_allowed (Req 4.2, 4.3)
   * - Role permission exists → true (Req 4.4)
   * - Otherwise → false (Req 4.7)
   */
  static async hasPermission(
    userId: string,
    module: string,
    action: string
  ): Promise<boolean> {
    // Req 4.5: Admin always has permission
    const user = await this.getUser(userId);
    if (!user) return false;
    if (user.role === UserRole.ADMIN) return true;

    // Req 4.6: Deny if module/action not registered
    const moduleDef = ModuleRegistry.getModule(module);
    if (!moduleDef) return false;
    if (!moduleDef.actions.includes(action as PermissionAction)) return false;

    // Req 5.2: Check cache first
    const cacheKey = `perm_${userId}_${module}_${action}`;
    const cached = this.cache.get(cacheKey);
    if (cached !== undefined) return cached;

    // Req 4.1-4.4: Check user override first, then role permissions
    const result = await this.resolvePermission(userId, module, action, user.role_id);

    // Req 5.1: Cache the result
    this.cache.set(cacheKey, result);

    return result;
  }

  /**
   * Get all effective permissions for a user.
   * Combines role-level permissions with user-specific overrides.
   */
  static async getUserPermissions(userId: string): Promise<UserPermissionSet> {
    const user = await this.getUser(userId);
    if (!user) {
      throw new Error(`User ${userId} not found`);
    }

    const role = await this.getRole(user.role_id);
    const roleName = role?.name || user.role || 'Unknown';
    const roleId = user.role_id || '';
    const isCustomRole = role?.is_custom === 1 || role?.is_custom === true;

    // Get all role permissions
    const rolePermissions = user.role_id
      ? await db
          .prepare(
            `SELECT p.module, p.action
             FROM permissions p
             JOIN role_permissions rp ON p.id = rp.permission_id
             WHERE rp.role_id = ?`
          )
          .all(user.role_id)
      : [];

    // Get all user overrides
    const userOverrides = (await db
      .prepare(
        `SELECT p.module, p.action, up.is_allowed
         FROM permissions p
         JOIN user_permissions up ON p.id = up.permission_id
         WHERE up.user_id = ?`
      )
      .all(userId)) as Array<{ module: string; action: string; is_allowed: number }>;

    // Build effective permissions map
    const permissions: Record<string, PermissionAction[]> = {};

    // Start with role permissions
    for (const rp of rolePermissions as Array<{ module: string; action: string }>) {
      if (!permissions[rp.module]) {
        permissions[rp.module] = [];
      }
      if (!permissions[rp.module].includes(rp.action as PermissionAction)) {
        permissions[rp.module].push(rp.action as PermissionAction);
      }
    }

    // Apply user overrides
    for (const override of userOverrides) {
      if (!permissions[override.module]) {
        permissions[override.module] = [];
      }

      if (override.is_allowed === 1 || override.is_allowed === true) {
        // Grant: add action if not already present
        if (!permissions[override.module].includes(override.action as PermissionAction)) {
          permissions[override.module].push(override.action as PermissionAction);
        }
      } else {
        // Deny: remove action if present
        permissions[override.module] = permissions[override.module].filter(
          (a) => a !== override.action
        );
      }
    }

    // Clean up empty arrays
    for (const mod of Object.keys(permissions)) {
      if (permissions[mod].length === 0) {
        delete permissions[mod];
      }
    }

    // Build overrides array
    const overrides = userOverrides.map((o) => ({
      module: o.module,
      action: o.action as PermissionAction,
      isAllowed: o.is_allowed === 1 || o.is_allowed === true,
    }));

    return {
      userId,
      role: roleName,
      roleId: roleId,
      isCustomRole,
      permissions,
      overrides,
    };
  }

  /**
   * Get the permission matrix for a role.
   */
  static async getRolePermissions(roleId: string): Promise<RolePermissionSet> {
    const role = await this.getRole(roleId);
    if (!role) {
      throw new Error(`Role ${roleId} not found`);
    }

    const rolePerms = (await db
      .prepare(
        `SELECT p.module, p.action
         FROM permissions p
         JOIN role_permissions rp ON p.id = rp.permission_id
         WHERE rp.role_id = ?`
      )
      .all(roleId)) as Array<{ module: string; action: string }>;

    const permissions: Record<string, PermissionAction[]> = {};
    for (const rp of rolePerms) {
      if (!permissions[rp.module]) {
        permissions[rp.module] = [];
      }
      if (!permissions[rp.module].includes(rp.action as PermissionAction)) {
        permissions[rp.module].push(rp.action as PermissionAction);
      }
    }

    return {
      roleId,
      roleName: role.name,
      isCustom: role.is_custom === 1 || role.is_custom === true,
      permissions,
    };
  }

  /**
   * Update a role's permissions.
   * Applies the given permission updates and invalidates cache for all affected users.
   */
  static async updateRolePermissions(
    roleId: string,
    permissions: PermissionUpdate[]
  ): Promise<void> {
    const transaction = db.transaction(async () => {
      for (const perm of permissions) {
        // Get the permission record ID
        const permRecord = (await db
          .prepare(
            'SELECT id FROM permissions WHERE module = ? AND action = ?'
          )
          .get(perm.module, perm.action)) as { id: string } | undefined;

        if (!permRecord) continue;

        if (perm.granted) {
          // Grant: insert role_permission if not exists
          await db
            .prepare(
              'INSERT INTO role_permissions (role_id, permission_id) VALUES (?::uuid, ?::uuid) ON CONFLICT DO NOTHING'
            )
            .run(roleId, permRecord.id);
        } else {
          // Revoke: delete role_permission
          await db
            .prepare(
              'DELETE FROM role_permissions WHERE role_id = ?::uuid AND permission_id = ?::uuid'
            )
            .run(roleId, permRecord.id);
        }
      }
    });

    await transaction();

    // Invalidate cache for all users with this role
    await this.invalidateCacheForRole(roleId);
  }

  /**
   * Set a user-specific permission override.
   * Upserts the user_permissions record and invalidates the user's cache.
   */
  static async setUserPermissionOverride(
    userId: string,
    module: string,
    action: string,
    allowed: boolean
  ): Promise<void> {
    // Get the permission record ID
    const permRecord = (await db
      .prepare('SELECT id FROM permissions WHERE module = ? AND action = ?')
      .get(module, action)) as { id: string } | undefined;

    if (!permRecord) {
      throw new Error(
        `Permission record not found for module '${module}' action '${action}'`
      );
    }

    const isAllowed = allowed ? 1 : 0;

    // Upsert: try to update first, insert if not exists
    const existing = await db
      .prepare(
        'SELECT 1 FROM user_permissions WHERE user_id = ?::uuid AND permission_id = ?::uuid'
      )
      .get(userId, permRecord.id);

    if (existing) {
      await db
        .prepare(
          'UPDATE user_permissions SET is_allowed = ? WHERE user_id = ?::uuid AND permission_id = ?::uuid'
        )
        .run(isAllowed, userId, permRecord.id);
    } else {
      await db
        .prepare(
          'INSERT INTO user_permissions (user_id, permission_id, is_allowed) VALUES (?::uuid, ?::uuid, ?)'
        )
        .run(userId, permRecord.id, isAllowed);
    }

    // Invalidate cache for this user
    this.invalidateCache(userId);
  }

  /**
   * Invalidate permission cache.
   * - If userId provided: remove all entries for that user (prefix `perm_{userId}_`)
   * - If no userId: remove all permission cache entries (prefix `perm_`)
   *
   * Req 5.3, 5.4
   */
  static invalidateCache(userId?: string): void {
    if (userId) {
      this.cache.invalidateUser(userId);
    } else {
      this.cache.invalidateAll();
    }
  }

  // ─── Private Helpers ───────────────────────────────────────────────────────

  /**
   * Resolve a permission by checking user overrides first, then role permissions.
   */
  private static async resolvePermission(
    userId: string,
    module: string,
    action: string,
    roleId: string | null
  ): Promise<boolean> {
    // Check user-level override first (Req 4.1, 4.2, 4.3)
    const userOverride = (await db
      .prepare(
        `SELECT up.is_allowed
         FROM user_permissions up
         JOIN permissions p ON up.permission_id = p.id
         WHERE up.user_id = ? AND p.module = ? AND p.action = ?`
      )
      .get(userId, module, action)) as { is_allowed: number } | undefined;

    if (userOverride !== undefined) {
      // User override exists - use it regardless of role permission
      return userOverride.is_allowed === 1 || (userOverride.is_allowed as any) === true;
    }

    // No user override - fall back to role permissions (Req 4.4)
    if (!roleId) return false; // Req 4.7: no role assigned → deny

    const rolePermission = await db
      .prepare(
        `SELECT 1
         FROM role_permissions rp
         JOIN permissions p ON rp.permission_id = p.id
         WHERE rp.role_id = ? AND p.module = ? AND p.action = ?`
      )
      .get(roleId, module, action);

    return !!rolePermission;
  }

  /**
   * Get user record from DB (with basic fields needed for permission checks).
   */
  private static async getUser(
    userId: string
  ): Promise<{ id: string; role: string; role_id: string } | undefined> {
    return (await db
      .prepare('SELECT id, role, role_id FROM users WHERE id = ?')
      .get(userId)) as { id: string; role: string; role_id: string } | undefined;
  }

  /**
   * Get role record from DB.
   */
  private static async getRole(
    roleId: string | null
  ): Promise<{ id: string; name: string; is_custom: number | boolean } | undefined> {
    if (!roleId) return undefined;
    return (await db
      .prepare('SELECT id, name, is_custom FROM roles WHERE id = ?')
      .get(roleId)) as { id: string; name: string; is_custom: number | boolean } | undefined;
  }

  /**
   * Invalidate cache for all users assigned to a specific role.
   * Req 5.5: When a role's permissions change, invalidate all affected users.
   */
  private static async invalidateCacheForRole(roleId: string): Promise<void> {
    const users = (await db
      .prepare('SELECT id FROM users WHERE role_id = ?')
      .all(roleId)) as Array<{ id: string }>;

    for (const user of users) {
      this.cache.invalidateUser(user.id);
    }
  }
}

import { db } from '../db/index';
import { NotFoundError } from '../utils/errors';

export class PolicyService {
  static async getAll() {
    return await db.prepare("SELECT id, title, department, version, upload_date, status FROM internal_policies ORDER BY upload_date DESC").all();
  }

  static async getById(id: string | number) {
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    
    if (typeof id === 'string' && uuidRegex.test(id)) {
      const record = await db.prepare("SELECT * FROM internal_policies WHERE id = ?").get(id);
      if (record) return record;
    }

    // Try system_policies if not a UUID or not found in internal_policies
    const systemPolicy = await db.prepare("SELECT * FROM system_policies WHERE policy_key = ?").get(id);
    if (systemPolicy) return systemPolicy;

    throw new NotFoundError("Policy not found");
  }

  static async getFile(id: string | number) {
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    
    if (typeof id === 'string' && uuidRegex.test(id)) {
      const record = await db.prepare("SELECT file_url FROM internal_policies WHERE id = ?").get(id);
      if (record) return record;
    }

    throw new NotFoundError("Policy file not found");
  }

  static async create(data: any, username: string) {
    const { title, department, version, file_url, status } = data;
    const stmt = db.prepare(`INSERT INTO internal_policies (title, department, version, upload_date, file_url, status) VALUES (?, ?, ?, ?, ?, ?)`);
    const info = await stmt.run(title, department, version, new Date().toISOString().split('T')[0], file_url, status || 'Active');
    
    await db.prepare("INSERT INTO audit_trail (user, action, module, details) VALUES (?::text, ?::text, ?::text, ?::text)")
      .run(username, 'Added Internal Policy', 'Governance', `Title: ${title}`);
      
    return { id: info.lastInsertRowid };
  }

  static async update(id: string | number, data: any, username: string) {
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    
    if (typeof id === 'string' && uuidRegex.test(id)) {
      const { title, department, version, file_url, status } = data;
      const stmt = db.prepare(`UPDATE internal_policies SET title = ?, department = ?, version = ?, file_url = ?, status = ? WHERE id = ?`);
      await stmt.run(title, department, version, file_url, status, id);
      
      await db.prepare("INSERT INTO audit_trail (user, action, module, details) VALUES (?::text, ?::text, ?::text, ?::text)")
        .run(username, 'Updated Internal Policy', 'Governance', `ID: ${id}`);
      return true;
    }

    // Handle system_policies update
    const { content } = data;
    if (content !== undefined) {
      const stmt = db.prepare(`UPDATE system_policies SET content = ?, updated_by = ?, updated_at = CURRENT_TIMESTAMP WHERE policy_key = ?`);
      await stmt.run(content, username, id);
      
      await db.prepare("INSERT INTO audit_trail (user, action, module, details) VALUES (?::text, ?::text, ?::text, ?::text)")
        .run(username, 'Updated System Policy', 'Governance', `Key: ${id}`);
      return true;
    }
      
    return false;
  }

  static async delete(id: string | number, username: string) {
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    
    if (typeof id === 'string' && uuidRegex.test(id)) {
      const stmt = db.prepare(`DELETE FROM internal_policies WHERE id = ?`);
      await stmt.run(id);
      
      await db.prepare("INSERT INTO audit_trail (user, action, module, details) VALUES (?::text, ?::text, ?::text, ?::text)")
        .run(username, 'Deleted Internal Policy', 'Governance', `ID: ${id}`);
      return true;
    }

    // Handle system_policies delete
    const stmt = db.prepare(`DELETE FROM system_policies WHERE policy_key = ?`);
    await stmt.run(id);
    
    await db.prepare("INSERT INTO audit_trail (user, action, module, details) VALUES (?::text, ?::text, ?::text, ?::text)")
      .run(username, 'Deleted System Policy', 'Governance', `Key: ${id}`);
      
    return true;
  }
}

import { db } from '../db/index';
import { NotFoundError } from '../utils/errors';

export class ProfileService {
  static async getProfile(userId: string | number) {
    const user = await db.prepare(`
      SELECT u.id, u.employee_id, u.username, u.name, u.email, u.department, u.role, u.profile_picture, u.last_login, u.language, u.dashboard_layout, u.notifications_enabled, u.theme, j.name as job_title 
      FROM users u 
      LEFT JOIN job_titles j ON u.job_title_id = j.id 
      WHERE u.id = ?
    `).get(userId) as any;
    
    if (!user) throw new NotFoundError("User profile not found");

    // Fetch user permissions from DB (role_permissions + user_permissions)
    let permissions: Array<{ module: string; action: string }> = [];
    try {
      permissions = await db.prepare(`
        SELECT p.module, p.action FROM permissions p
        JOIN role_permissions rp ON p.id = rp.permission_id
        WHERE rp.role_id = (SELECT role_id FROM users WHERE id = ?)
        UNION
        SELECT p.module, p.action FROM permissions p
        JOIN user_permissions up ON p.id = up.permission_id
        WHERE up.user_id = ? AND up.is_allowed = 1
      `).all(userId, userId) as Array<{ module: string; action: string }>;
    } catch (e) {
      // If permissions query fails, return empty array (frontend will use fallback)
    }

    return { ...user, permissions };
  }

  static async updateProfile(userId: string | number, data: any, username: string) {
    const { name, email, department, profile_picture } = data;
    await db.prepare("UPDATE users SET name = ?, email = ?, department = ?, profile_picture = ? WHERE id = ?")
      .run(name, email, department, profile_picture, userId);
    
    await db.prepare("INSERT INTO audit_trail (user, action, module, details) VALUES (?::text, ?::text, ?::text, ?::text)")
      .run(username, "Update Profile", "Settings", "User updated personal profile");
      
    return true;
  }

  static async updatePreferences(userId: string | number, data: any, username: string) {
    const { language, dashboard_layout, notifications_enabled, theme } = data;
    await db.prepare("UPDATE users SET language = ?, dashboard_layout = ?, notifications_enabled = ?, theme = ? WHERE id = ?")
      .run(language, dashboard_layout, notifications_enabled ? 1 : 0, theme || 'light', userId);
    
    await db.prepare("INSERT INTO audit_trail (user, action, module, details) VALUES (?::text, ?::text, ?::text, ?::text)")
      .run(username, "Update Preferences", "Settings", "User updated preferences");
      
    return true;
  }
}

import { db } from '../db/index';
import { NotFoundError, ValidationError } from '../utils/errors';
import { NotificationService } from './NotificationService';
import { N8nService } from '../utils/n8nService';

export interface RecommendationFilters {
  department?: string;
  plan_id?: string;
  status?: string;
  page?: number | string;
  pageSize?: number | string;
}

export class RecommendationService {
  static async getAll() {
    return await db.prepare("SELECT * FROM recommendations").all();
  }

  /**
   * Returns paginated recommendations matching the given filters.
   *
   * Filters:
   * - department: filter by department
   * - plan_id: filter by plan_id
   * - status: filter by status
   * - page: page number (default 1)
   * - pageSize: items per page (default 20, max 100)
   *
   * Excludes recommendations from archived plans (WHERE plan_id NOT IN archived plans).
   *
   * @param filters - The filter criteria
   * @returns Paginated results with data and pagination metadata
   */
  static async getRecommendations(filters: RecommendationFilters = {}): Promise<{
    data: any[];
    pagination: { total: number; page: number; pageSize: number; totalPages: number };
  }> {
    const page = Math.max(1, parseInt(String(filters.page)) || 1);
    let pageSize = parseInt(String(filters.pageSize)) || 20;
    // Enforce max pageSize of 100
    if (pageSize > 100) {
      pageSize = 100;
    }
    if (pageSize < 1) {
      pageSize = 20;
    }
    const offset = (page - 1) * pageSize;

    const conditions: string[] = [];
    const args: any[] = [];

    // Exclude recommendations from archived plans
    conditions.push("plan_id NOT IN (SELECT id FROM audit_plans WHERE is_archived = true)");

    if (filters.department) {
      conditions.push("department = ?");
      args.push(filters.department);
    }

    if (filters.plan_id) {
      conditions.push("plan_id = ?");
      args.push(filters.plan_id);
    }

    if (filters.status) {
      conditions.push("status = ?");
      args.push(filters.status);
    }

    const whereClause = conditions.length > 0 ? " WHERE " + conditions.join(" AND ") : "";

    const countQuery = "SELECT COUNT(*) as total FROM recommendations" + whereClause;
    const dataQuery = "SELECT * FROM recommendations" + whereClause + " ORDER BY created_at DESC LIMIT ? OFFSET ?";

    const [countRes, data] = await Promise.all([
      db.prepare(countQuery).get(...args),
      db.prepare(dataQuery).all(...args, pageSize, offset),
    ]) as [any, any[]];

    const total = countRes?.total || 0;

    return {
      data,
      pagination: {
        total,
        page,
        pageSize,
        totalPages: Math.ceil(total / pageSize),
      },
    };
  }

  static async update(id: string | number, data: any, username: string) {
    const body = { ...data };
    delete body.id;

    const keys = Object.keys(body).map(k => db.validateIdentifier(k));
    const values = Object.values(body);
    
    if (keys.length === 0) {
      throw new ValidationError("No data provided for update");
    }

    const setClause = keys.map(k => `${k} = ?`).join(",");
    await db.prepare(`UPDATE recommendations SET ${setClause} WHERE id = ?`).run(...values, id);

    await db.prepare("INSERT INTO audit_trail (user, action, module, details) VALUES (?::text, ?::text, ?::text, ?::text)")
      .run(username, `Updated recommendations ID: ${id}`, "recommendations", JSON.stringify(body));

    // --- AUTOMATION: Send event to n8n ---
    await N8nService.sendEvent('recommendation.updated', {
      recommendationId: id,
      newStatus: body.status,
      updatedBy: username,
      dueDate: body.due_date
    });

    // --- AUTOMATION: Auto-close finding if all recommendations are implemented ---
    if (body.status === 'Implemented') {
      try {
        // Get the finding_id for this recommendation
        const rec = await db.prepare("SELECT finding_id FROM recommendations WHERE id = ?").get(id) as any;
        if (rec && rec.finding_id) {
          // Check if there are any recommendations for this finding that are NOT 'Implemented'
          const openRecs = await db.prepare("SELECT COUNT(*) as count FROM recommendations WHERE finding_id = ? AND status != 'Implemented'").get(rec.finding_id);
          
          if (openRecs && (openRecs as any).count === 0) {
            // Check if finding is already closed
            const finding = await db.prepare("SELECT status, audit_id, title FROM audit_findings WHERE id = ?").get(rec.finding_id) as any;
            
            if (finding && finding.status !== 'Closed') {
              // All recommendations are implemented, so close the finding
              await db.prepare("UPDATE audit_findings SET status = 'Closed' WHERE id = ?").run(rec.finding_id);
              
              await db.prepare("INSERT INTO audit_trail (user, action, module, details) VALUES (?::text, ?::text, ?::text, ?::text)")
                .run('System', `Auto-closed finding ID: ${rec.finding_id} as all recommendations are implemented`, "audit_findings", JSON.stringify({ status: 'Closed' }));

              // --- AUTOMATION: Send event to n8n ---
              await N8nService.sendEvent('finding.auto_closed', {
                findingId: rec.finding_id,
                title: finding.title,
                auditId: finding.audit_id
              });

              // Get lead auditor to notify
              if (finding.audit_id) {
                const plan = await db.prepare("SELECT lead_auditor FROM audit_plans WHERE id = ?").get(finding.audit_id) as any;
                if (plan && plan.lead_auditor) {
                  const user = await db.prepare("SELECT id FROM users WHERE name = ? OR username = ?").get(plan.lead_auditor, plan.lead_auditor) as any;
                  if (user) {
                    await NotificationService.create(
                      user.id,
                      'Finding Auto-Closed',
                      `The finding "${finding.title}" has been automatically closed because all its recommendations are now implemented.`,
                      'audit_findings',
                      '/findings'
                    );
                  }
                }
              }
            }
          }
        }
      } catch (err) {
        console.error('[Automation Error] Failed to auto-close finding:', err);
      }
    }
    // ------------------------------------------------------------------------

    return { id, ...body };
  }
}

import { BaseService } from './BaseService';

export class RiskService extends BaseService {
  static computeRiskScore(data: any) {
    if (data.likelihood_num !== undefined && data.impact_num !== undefined) {
      data.risk_score_calc = data.likelihood_num * data.impact_num;
      const score = data.risk_score_calc;
      data.risk_level_calc = score >= 20 ? 'critical' : score >= 8 ? 'high' : score >= 4 ? 'medium' : score >= 2 ? 'low' : 'negligible';
    }
  }

  static async create(tableName: string, data: any) {
    if (tableName === 'risk_register') {
      this.computeRiskScore(data);
    }
    return super.create(tableName, data);
  }

  static async update(tableName: string, id: string | number, data: any) {
    if (tableName === 'risk_register') {
      this.computeRiskScore(data);
    }
    return super.update(tableName, id, data);
  }
}

import { db } from '../db/index';
import { NotFoundError } from '../utils/errors';

export class RoleService {
  static async getAllRoles() {
    const roles = await db.prepare("SELECT * FROM roles ORDER BY name ASC").all() as any[];
    
    const roleIds = roles.map(r => r.id);
    let allPermissions: any[] = [];
    
    if (roleIds.length > 0) {
      const placeholders = roleIds.map(() => '?').join(',');
      allPermissions = await db.prepare(`
        SELECT rp.role_id, p.id, p.module, p.action
        FROM permissions p
        JOIN role_permissions rp ON p.id = rp.permission_id
        WHERE rp.role_id IN (${placeholders})
      `).all(...roleIds);
    }
    
    const rolesWithPermissions = roles.map(role => ({
      ...role,
      permissions: allPermissions
        .filter(p => p.role_id === role.id)
        .map(p => ({ id: p.id, module: p.module, action: p.action }))
    }));

    return rolesWithPermissions;
  }

  static async getRolePermissions(roleId: string | number) {
    const perms = await db.prepare(`
      SELECT p.* 
      FROM permissions p
      JOIN role_permissions rp ON p.id = rp.permission_id
      WHERE rp.role_id = ?
    `).all(roleId);
    return perms;
  }

  static async updateRolePermissions(roleId: string | number, permissionIds: (string | number)[]) {
    const uniquePermissionIds = Array.isArray(permissionIds) ? [...new Set(permissionIds)] : [];
    
    const transaction = db.transaction(async () => {
      await db.prepare("DELETE FROM role_permissions WHERE role_id = ?::uuid").run(roleId);
      for (const pid of uniquePermissionIds) {
        await db.prepare("INSERT INTO role_permissions (role_id, permission_id) VALUES (?::uuid, ?::uuid) ON CONFLICT DO NOTHING").run(roleId, pid);
      }
    });
    await transaction();
    return true;
  }

  static async getAllPermissions() {
    return await db.prepare("SELECT * FROM permissions ORDER BY module ASC, action ASC").all();
  }
}

import logger from '../utils/logger.js';
import fs from 'fs/promises';

export class SecurityService {
  private static magika: any = null;
  private static isLoaded = false;
  private static initPromise: Promise<void> | null = null;

  /**
   * Initializes the Magika model.
   * This is called lazily when the first identification request is made.
   */
  private static async init() {
    if (this.isLoaded) return;
    if (this.initPromise) return this.initPromise;

    this.initPromise = (async () => {
      try {
        logger.info('Initializing Magika AI for file identification...');
        const { MagikaNode } = await import('magika/node');
        this.magika = await MagikaNode.create();
        this.isLoaded = true;
        logger.info('Magika AI initialized successfully.');
      } catch (error) {
        logger.error('Failed to initialize Magika AI:', error);
        this.initPromise = null;
        // Don't throw - allow server to start without Magika
        logger.warn('Server will continue without AI file identification.');
      }
    })();

    return this.initPromise;
  }

  /**
   * Identifies the content type of a file buffer or path using Google's Magika (AI-based).
   * @param source The file content as a Buffer or a path to the file
   * @returns Detailed identification result
   */
  static async identifyFile(source: Buffer | string) {
    if (!this.isLoaded) {
      await this.init();
    }

    if (!this.magika) {
      throw new Error('Magika service not available');
    }

    try {
      let buffer: Uint8Array;
      if (typeof source === 'string') {
        const fileData = await fs.readFile(source);
        buffer = new Uint8Array(fileData);
      } else {
        buffer = new Uint8Array(source);
      }

      const result = await this.magika.identifyBytes(buffer);
      return result;
    } catch (error) {
      logger.error('Error during Magika file identification:', error);
      throw new Error('Security check failed during file analysis.');
    }
  }

  /**
   * Validates if the file content matches its claimed extension and is safe.
   * @param source File content (Buffer or path)
   * @param claimedExtension Extension provided by the user (e.g., '.pdf')
   * @param allowedMimeTypes Optional whitelist of allowed MIME types
   * @returns boolean true if the file is considered safe and matches
   */
  static async validateFileSafety(source: Buffer | string, claimedExtension: string, allowedMimeTypes?: string[]) {
    try {
      const identification = await this.identifyFile(source);
      const prediction = identification.prediction;
      const detectedLabel = prediction.output.label;
      const score = prediction.score;
      
      // Log detected type for audit
      const fileName = typeof source === 'string' ? source.split('/').pop() : 'buffer';
      logger.info(`AI Security Check [${fileName}]: Claimed=${claimedExtension}, Detected=${detectedLabel}, Score=${score}`);

      // High confidence threshold (Magika is very accurate, but we can set a threshold)
      const CONFIDENCE_THRESHOLD = 0.5;
      
      if (score < CONFIDENCE_THRESHOLD) {
          logger.warn(`Low confidence AI identification for ${claimedExtension}. Score: ${score}`);
      }

      // Basic safety check: detected type should be consistent with allowed types if provided
      if (allowedMimeTypes && allowedMimeTypes.length > 0) {
          // Check if detected label matches any allowed MIME type or extension
          const isMimeAllowed = allowedMimeTypes.some(mime => 
              mime.toLowerCase().includes(detectedLabel.toLowerCase()) || 
              detectedLabel.toLowerCase().includes(mime.toLowerCase())
          );
          
          if (!isMimeAllowed) {
              logger.error(`Security Alert: AI mismatch for ${claimedExtension}. Detected: ${detectedLabel}. Whitelist: ${allowedMimeTypes.join(', ')}`);
              return false;
          }
      }

      return true;
    } catch (error) {
      logger.error('File safety validation error:', error);
      // Fail-closed: if security check fails, reject the file
      // Only allow if Magika is simply not loaded (graceful degradation)
      if (!this.isLoaded) {
        logger.warn('Magika not available - allowing file with extension-only validation');
        return true;
      }
      return false; 
    }
  }
}

import { db } from '../db/index';
import { AuthError } from '../utils/errors';
import jwt from 'jsonwebtoken';

export class SessionService {
  static async getActiveSessions() {
    return await db.prepare(`
      SELECT s.*, u.name as user_name, u.username
      FROM user_sessions s
      JOIN users u ON s.user_id = u.id
      WHERE s.status = 'Active'
      ORDER BY s.last_activity DESC
    `).all();
  }

  static async terminateSession(id: string | number) {
    await db.prepare("UPDATE user_sessions SET status = 'Terminated' WHERE id = ?").run(id);
    return true;
  }

  static async refresh(refreshToken: string, JWT_SECRET: string, JWT_PRIVATE_KEY: string) {
    const session = await db.prepare("SELECT * FROM user_sessions WHERE refresh_token = ? AND status = 'Active'").get(refreshToken) as any;
    if (!session) throw new AuthError("Invalid session");

    const user = await db.prepare("SELECT * FROM users WHERE id = ?").get(session.user_id) as any;
    if (!user) throw new AuthError("User not found");

    let decodedToken: any = {};
    try {
      decodedToken = jwt.decode(refreshToken) || {};
    } catch (e) {}

    const rememberMe = !!decodedToken.rememberMe;

    const token = jwt.sign({ id: user.id, username: user.username, role: user.role, session_version: user.session_version }, JWT_PRIVATE_KEY, { algorithm: 'RS256', expiresIn: '15m' });
    const newRefreshToken = jwt.sign({ id: user.id, rememberMe }, JWT_PRIVATE_KEY, { algorithm: 'RS256', expiresIn: rememberMe ? '30d' : '8h' });

    // Update both tables for compatibility
    await db.prepare("UPDATE user_sessions SET refresh_token = ?, last_activity = CURRENT_TIMESTAMP WHERE id = ?").run(newRefreshToken, session.id);
    
    const refreshExpiry = rememberMe ? new Date(Date.now() + 30 * 24 * 60 * 60 * 1000) : new Date(Date.now() + 8 * 60 * 60 * 1000); // 30 days or 8 hours
    
    try {
      await db.prepare("UPDATE refresh_tokens SET token = ?, expires_at = ? WHERE token = ?").run(
        newRefreshToken, 
        refreshExpiry.toISOString(),
        refreshToken
      );
    } catch (e) {
      // Ignore
    }

    return {
      token,
      refreshToken: newRefreshToken,
      user,
      expiresAt: refreshExpiry,
      rememberMe
    };
  }

  static async logout(refreshToken: string) {
    const session = await db.prepare("SELECT user_id FROM user_sessions WHERE refresh_token = ?").get(refreshToken) as any;
    
    // Also revoke in refresh_tokens table for compatibility
    try {
      await db.prepare("UPDATE refresh_tokens SET is_revoked = 1, revoked_at = CURRENT_TIMESTAMP WHERE token = ?").run(refreshToken);
    } catch (e) {
      // Ignore if table doesn't exist or other issues
    }

    if (session) {
      const user = await db.prepare("SELECT username FROM users WHERE id = ?").get(session.user_id) as any;
      await db.prepare("UPDATE user_sessions SET status = 'LoggedOut' WHERE refresh_token = ?").run(refreshToken);
      return user?.username;
    }
    return null;
  }

  static async logoutAll(userId: string | number) {
    await db.prepare("UPDATE user_sessions SET status = 'Terminated' WHERE user_id = ? AND status = 'Active'").run(userId);
    return true;
  }
}

