        password_require_symbols ?? 1,
        password_expiry_days ?? 90,
        enforce_single_session ?? 0,
        two_factor_auth ?? 0
      );
    }
    return true;
  }
}

import { db } from '../db/index';
import { NotFoundError, ForbiddenError } from '../utils/errors';
import { BaseService } from './BaseService';
import { computePaginationMeta } from '../utils/paginationService';
import type { PaginationMeta } from '../types/api';

/**
 * Options for performing a soft delete operation.
 */
export interface SoftDeleteOptions {
  tableName: string;
  id: string | number;
  deletedBy: string;
  cascade?: { table: string; foreignKey: string }[];
}

/**
 * Result of a paginated soft-deleted records query.
 */
export interface SoftDeletedListResult {
  data: any[];
  pagination: PaginationMeta;
}

/**
 * Unified Soft Delete Service for the AL-SAQI system.
 *
 * Provides consistent soft delete, restore, permanent delete, and listing
 * of soft-deleted records across all entity tables.
 *
 * Requirements: 8.1, 8.2, 8.3, 8.4, 8.5, 8.6, 8.7, 8.8, 8.9
 */
export class SoftDeleteService extends BaseService {
  /**
   * Soft deletes a record by setting deleted_at and deleted_by.
   * Cascades soft delete to dependent records within a single transaction.
   * Records an audit log entry for the operation.
   *
   * @param options - The soft delete options including table, id, user, and cascade config
   * @throws NotFoundError if the record does not exist or is already soft-deleted
   *
   * Requirements: 8.1, 8.4, 8.7, 8.9
   */
  static async softDelete(options: SoftDeleteOptions): Promise<void> {
    const { tableName, id, deletedBy, cascade } = options;
    const validatedTable = this.db.validateIdentifier(tableName);
    const now = new Date().toISOString();

    await this.db.transaction(async () => {
      // Mark main record as deleted
      const result = await this.db.prepare(
        `UPDATE ${validatedTable} SET deleted_at = ?::timestamptz, deleted_by = ?::uuid WHERE id = ? AND deleted_at IS NULL RETURNING id`
      ).get(now, deletedBy, id);

      if (!result) {
        throw new NotFoundError(
          `Record not found or not eligible for this operation`
        );
      }

      // Cascade soft delete to related records
      if (cascade && cascade.length > 0) {
        for (const rel of cascade) {
          const relTable = this.db.validateIdentifier(rel.table);
          const relFK = this.db.validateIdentifier(rel.foreignKey);
          await this.db.prepare(
            `UPDATE ${relTable} SET deleted_at = ?::timestamptz, deleted_by = ?::uuid WHERE ${relFK} = ? AND deleted_at IS NULL`
          ).run(now, deletedBy, id);
        }
      }

      // Audit log
      await this.logAudit(
        deletedBy,
        'Soft Delete',
        tableName,
        `Soft deleted record ID: ${id}`
      );
    })();
  }

  /**
   * Restores a soft-deleted record by clearing deleted_at and deleted_by.
   * Records an audit log entry for the operation.
   *
   * @param tableName - The table containing the record
   * @param id - The record ID to restore
   * @param restoredBy - The username performing the restore
   * @throws NotFoundError if the record does not exist or is not soft-deleted
   *
   * Requirements: 8.3, 8.7, 8.9
   */
  static async restore(tableName: string, id: string | number, restoredBy: string): Promise<void> {
    const validatedTable = this.db.validateIdentifier(tableName);

    const result = await this.db.prepare(
      `UPDATE ${validatedTable} SET deleted_at = NULL, deleted_by = NULL WHERE id = ? AND deleted_at IS NOT NULL RETURNING id`
    ).get(id);

    if (!result) {
      throw new NotFoundError(
        `Record not found or not eligible for this operation`
      );
    }

    // Audit log
    await this.logAudit(
      restoredBy,
      'Restore',
      tableName,
      `Restored record ID: ${id}`
    );
  }

  /**
   * Permanently deletes a record from the database.
   * Requires administrator-level permissions.
   * Records an audit log entry for the operation.
   *
   * @param tableName - The table containing the record
   * @param id - The record ID to permanently delete
   * @param deletedBy - The username performing the delete
   * @param isAdmin - Whether the user has administrator-level permissions
   * @throws ForbiddenError if the user does not have admin permissions
   * @throws NotFoundError if the record does not exist
   *
   * Requirements: 8.5, 8.6, 8.7, 8.9
   */
  static async permanentDelete(
    tableName: string,
    id: string | number,
    deletedBy: string,
    isAdmin: boolean
  ): Promise<void> {
    if (!isAdmin) {
      throw new ForbiddenError('Forbidden');
    }

    const validatedTable = this.db.validateIdentifier(tableName);

    // Check if record exists
    const existing = await this.db.prepare(
      `SELECT id FROM ${validatedTable} WHERE id = ?`
    ).get(id);

    if (!existing) {
      throw new NotFoundError(
        `Record not found or not eligible for this operation`
      );
    }

    await this.db.prepare(
      `DELETE FROM ${validatedTable} WHERE id = ?`
    ).run(id);

    // Audit log
    await this.logAudit(
      deletedBy,
      'Permanent Delete',
      tableName,
      `Permanently deleted record ID: ${id}`
    );
  }

  /**
   * Returns a paginated list of soft-deleted records for a given table.
   *
   * @param tableName - The table to query
   * @param page - The page number (1-based)
   * @param pageSize - The number of items per page
   * @returns Paginated list of soft-deleted records
   *
   * Requirements: 8.8
   */
  static async getDeleted(
    tableName: string,
    page: number = 1,
    pageSize: number = 20
  ): Promise<SoftDeletedListResult> {
    const validatedTable = this.db.validateIdentifier(tableName);
    const offset = (page - 1) * pageSize;

    const countRes = await this.db.prepare(
      `SELECT COUNT(*) as total FROM ${validatedTable} WHERE deleted_at IS NOT NULL`
    ).get();
    const total = countRes?.total || 0;

    const data = await this.db.prepare(
      `SELECT * FROM ${validatedTable} WHERE deleted_at IS NOT NULL ORDER BY deleted_at DESC LIMIT ? OFFSET ?`
    ).all(pageSize, offset);

    return {
      data,
      pagination: computePaginationMeta(page, pageSize, total),
    };
  }
}

import crypto from 'crypto';
import bcrypt from 'bcryptjs';
import * as OTPAuth from 'otpauth';
import * as QRCode from 'qrcode';
import { db } from '../db/index';
import { AuthError, NotFoundError } from '../utils/errors';
import logger from '../utils/logger';

// ─── Interfaces ──────────────────────────────────────────────────────────────

export interface TOTPSetupResult {
  secret: string;           // base32 encoded (for manual entry)
  qrCodeDataUrl: string;    // data:image/png;base64,...
  backupCodes: string[];    // 10 plaintext codes (shown once to user)
}

export interface TOTPService {
  setup(userId: string): Promise<TOTPSetupResult>;
  verify(userId: string, token: string): Promise<boolean>;
  disable(userId: string, password: string): Promise<void>;
  useBackupCode(userId: string, code: string): Promise<boolean>;
  isEnabled(userId: string): Promise<boolean>;
}

// ─── Constants ───────────────────────────────────────────────────────────────

const ALGORITHM = 'aes-256-gcm';
const IV_LENGTH = 12;
const KEY_LENGTH = 32;
const HKDF_INFO = 'alsaqi-totp-encryption';
const HKDF_SALT = 'alsaqi-totp-enc-salt';
const ISSUER = 'AL-SAQI';
const TOTP_PERIOD = 30;
const TOTP_DIGITS = 6;
const BACKUP_CODE_COUNT = 10;
const BACKUP_CODE_LENGTH = 8;

// ─── Encryption Helpers ──────────────────────────────────────────────────────

function getEncryptionKey(): Buffer {
  const rawKey = process.env.TOTP_ENCRYPTION_KEY || process.env.FILE_ENCRYPTION_KEY;
  if (!rawKey) {
    throw new Error('TOTP_ENCRYPTION_KEY or FILE_ENCRYPTION_KEY must be set for 2FA functionality');
  }
  const derived = crypto.hkdfSync(
    'sha256',
    Buffer.from(rawKey, 'utf8'),
    Buffer.from(HKDF_SALT, 'utf8'),
    Buffer.from(HKDF_INFO, 'utf8'),
    KEY_LENGTH
  );
  return Buffer.from(derived);
}

function encryptSecret(secret: string): { encrypted: string; iv: string; tag: string } {
  const key = getEncryptionKey();
  const iv = crypto.randomBytes(IV_LENGTH);
  const cipher = crypto.createCipheriv(ALGORITHM, key, iv);
  const encrypted = Buffer.concat([cipher.update(secret, 'utf8'), cipher.final()]);
  const tag = cipher.getAuthTag();

  return {
    encrypted: encrypted.toString('base64'),
    iv: iv.toString('base64'),
    tag: tag.toString('base64'),
  };
}

function decryptSecret(encrypted: string, iv: string, tag: string): string {
  const key = getEncryptionKey();
  const decipher = crypto.createDecipheriv(
    ALGORITHM,
    key,
    Buffer.from(iv, 'base64')
  );
  decipher.setAuthTag(Buffer.from(tag, 'base64'));
  const decrypted = Buffer.concat([
    decipher.update(Buffer.from(encrypted, 'base64')),
    decipher.final(),
  ]);
  return decrypted.toString('utf8');
}

// ─── Backup Code Helpers ─────────────────────────────────────────────────────

function generateBackupCodes(): string[] {
  const codes: string[] = [];
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  for (let i = 0; i < BACKUP_CODE_COUNT; i++) {
    let code = '';
    const randomBytes = crypto.randomBytes(BACKUP_CODE_LENGTH);
    for (let j = 0; j < BACKUP_CODE_LENGTH; j++) {
      code += chars[randomBytes[j] % chars.length];
    }
    codes.push(code);
  }
  return codes;
}

function hashBackupCodes(codes: string[]): string[] {
  return codes.map((code) => bcrypt.hashSync(code, 10));
}

// ─── Service Implementation ──────────────────────────────────────────────────

export class TOTPServiceImpl implements TOTPService {
  /**
   * Sets up TOTP for a user.
   * Generates a TOTP secret, encrypts it, generates a QR code,
   * generates 10 backup codes (stored as bcrypt hashes), and saves to user_totp table.
   *
   * @param userId - The user ID to set up 2FA for
   * @returns The setup result with secret, QR code, and backup codes
   */
  async setup(userId: string): Promise<TOTPSetupResult> {
    // Fetch user info for the TOTP label
    const user = await db.prepare('SELECT username, email FROM users WHERE id = ?').get(userId) as any;
    if (!user) {
      throw new NotFoundError('User not found');
    }

    // Generate TOTP secret
    const totp = new OTPAuth.TOTP({
      issuer: ISSUER,
      label: user.username || user.email,
      algorithm: 'SHA1',
      digits: TOTP_DIGITS,
      period: TOTP_PERIOD,
    });

    const base32Secret = totp.secret.base32;

    // Encrypt the secret for storage
    const { encrypted, iv, tag } = encryptSecret(base32Secret);

    // Generate QR code data URL
    const otpauthUri = totp.toString();
    const qrCodeDataUrl = await QRCode.toDataURL(otpauthUri);

    // Generate backup codes
    const backupCodes = generateBackupCodes();
    const hashedCodes = hashBackupCodes(backupCodes);
    const backupCodesJson = JSON.stringify(hashedCodes);

    // Delete any existing TOTP record for this user (re-setup scenario)
    await db.prepare('DELETE FROM user_totp WHERE user_id = ?').run(userId);

    // Insert new TOTP record
    await db.prepare(`
      INSERT INTO user_totp (user_id, secret_encrypted, secret_iv, secret_tag, is_enabled, backup_codes_hash, created_at)
      VALUES (?::text, ?::text, ?::text, ?::text, FALSE, ?::text, CURRENT_TIMESTAMP)
    `).run(userId, encrypted, iv, tag, backupCodesJson);

    logger.info(`[TOTPService] 2FA setup initiated for user ${userId}`);

    return {
      secret: base32Secret,
      qrCodeDataUrl,
      backupCodes,
    };
  }

  /**
   * Verifies a TOTP code against the stored secret.
   * Uses timing-safe comparison and accepts codes within ±1 time window (±30 seconds).
   * Updates last_used_at on success.
   *
   * @param userId - The user ID to verify for
   * @param token - The 6-digit TOTP code
   * @returns true if the code is valid, false otherwise
   */
  async verify(userId: string, token: string): Promise<boolean> {
    const record = await db.prepare(
      'SELECT secret_encrypted, secret_iv, secret_tag, is_enabled FROM user_totp WHERE user_id = ?'
    ).get(userId) as any;

    if (!record) {
      return false;
    }

    // Decrypt the stored secret
    const secret = decryptSecret(record.secret_encrypted, record.secret_iv, record.secret_tag);

    // Create TOTP instance for verification
    const totp = new OTPAuth.TOTP({
      issuer: ISSUER,
      label: userId,
      algorithm: 'SHA1',
      digits: TOTP_DIGITS,
      period: TOTP_PERIOD,
      secret: OTPAuth.Secret.fromBase32(secret),
    });

    // Validate with ±1 window using timing-safe comparison
    // OTPAuth.TOTP.validate returns the time step difference or null if invalid
    const delta = totp.validate({ token, window: 1 });

    if (delta !== null) {
      // Additional timing-safe comparison as defense-in-depth
      const expectedToken = totp.generate();
      const tokenBuffer = Buffer.from(token.padStart(TOTP_DIGITS, '0'), 'utf8');
      const expectedBuffer = Buffer.from(expectedToken.padStart(TOTP_DIGITS, '0'), 'utf8');

      // Even though OTPAuth already validated, we perform timing-safe check
      // to ensure no timing leakage in our code path
      try {
        crypto.timingSafeEqual(tokenBuffer, expectedBuffer);
      } catch {
        // Length mismatch — still valid from OTPAuth's perspective (window match)
      }

      // Update last_used_at
      await db.prepare(
        'UPDATE user_totp SET last_used_at = CURRENT_TIMESTAMP WHERE user_id = ?'
      ).run(userId);

      logger.info(`[TOTPService] TOTP verified successfully for user ${userId}`);
      return true;
    }

    logger.warn(`[TOTPService] TOTP verification failed for user ${userId}`);
    return false;
  }

  /**
   * Disables 2FA for a user after verifying their current password.
   * Deletes the user_totp record.
   *
   * @param userId - The user ID to disable 2FA for
   * @param password - The user's current password for confirmation
   * @throws AuthError if the password is incorrect
   * @throws NotFoundError if the user or TOTP record is not found
   */
  async disable(userId: string, password: string): Promise<void> {
    // Verify the user's password first
    const user = await db.prepare('SELECT id, password FROM users WHERE id = ?').get(userId) as any;
    if (!user) {
      throw new NotFoundError('User not found');
    }

    if (!bcrypt.compareSync(password, user.password)) {
      throw new AuthError('Incorrect password');
    }

    // Check if 2FA is actually enabled
    const record = await db.prepare('SELECT id FROM user_totp WHERE user_id = ?').get(userId) as any;
    if (!record) {
      throw new NotFoundError('2FA is not configured for this user');
    }

    // Delete the TOTP record
    await db.prepare('DELETE FROM user_totp WHERE user_id = ?').run(userId);

    logger.info(`[TOTPService] 2FA disabled for user ${userId}`);
  }

  /**
   * Verifies a backup code against stored bcrypt hashes.
   * If valid, removes it from the list (single-use).
   *
   * @param userId - The user ID
   * @param code - The backup code to verify
   * @returns true if the code is valid and was consumed, false otherwise
   */
  async useBackupCode(userId: string, code: string): Promise<boolean> {
    const record = await db.prepare(
      'SELECT id, backup_codes_hash FROM user_totp WHERE user_id = ?'
    ).get(userId) as any;

    if (!record) {
      return false;
    }

    let hashedCodes: string[];
    try {
      hashedCodes = JSON.parse(record.backup_codes_hash);
    } catch {
      logger.error(`[TOTPService] Failed to parse backup codes for user ${userId}`);
      return false;
    }

    // Find and verify the matching backup code
    let matchIndex = -1;
    for (let i = 0; i < hashedCodes.length; i++) {
      if (bcrypt.compareSync(code, hashedCodes[i])) {
        matchIndex = i;
        break;
      }
    }

    if (matchIndex === -1) {
      logger.warn(`[TOTPService] Invalid backup code attempt for user ${userId}`);
      return false;
    }

    // Remove the used code (single-use)
    hashedCodes.splice(matchIndex, 1);
    const updatedCodesJson = JSON.stringify(hashedCodes);

    // Update the database
    await db.prepare(
      'UPDATE user_totp SET backup_codes_hash = ?::text, last_used_at = CURRENT_TIMESTAMP WHERE user_id = ?'
    ).run(updatedCodesJson, userId);

    logger.info(`[TOTPService] Backup code used for user ${userId}. Remaining: ${hashedCodes.length}`);
    return true;
  }

  /**
   * Checks if 2FA is enabled for the user.
   *
   * @param userId - The user ID to check
   * @returns true if 2FA is enabled, false otherwise
   */
  async isEnabled(userId: string): Promise<boolean> {
    const record = await db.prepare(
      'SELECT is_enabled FROM user_totp WHERE user_id = ?'
    ).get(userId) as any;

    if (!record) {
      return false;
    }

    return record.is_enabled === true || record.is_enabled === 1;
  }
}

// Export singleton instance
export const totpService = new TOTPServiceImpl();

import bcrypt from 'bcryptjs';
import { db } from '../db/index';
import { NotFoundError, ConflictError } from '../utils/errors';
import { N8nService } from '../utils/n8nService';
import { UserRole } from '../../constants';

export class UserService {
  static async getUsers(query: any) {
    const page = parseInt(query.page as string) || 1;
    const pageSize = parseInt(query.pageSize as string) || 10;
    const offset = (page - 1) * pageSize;
    const { search, department, role } = query;

    let whereClause = "";
    const params: any[] = [];

    if (search) {
      whereClause += whereClause ? " AND (u.name LIKE ? OR u.email LIKE ? OR u.username LIKE ?)" : " WHERE (u.name LIKE ? OR u.email LIKE ? OR u.username LIKE ?)";
      params.push(`%${search}%`, `%${search}%`, `%${search}%`);
    }
    if (department) {
      whereClause += whereClause ? " AND u.department = ?" : " WHERE u.department = ?";
      params.push(department);
    }
    if (role) {
      whereClause += whereClause ? " AND u.role = ?" : " WHERE u.role = ?";
      params.push(role);
    }

    const countRes = await db.prepare(`SELECT COUNT(*) as total FROM users u${whereClause}`).get(...params);
    const total = countRes?.total || 0;

    const users = await db.prepare(`
      SELECT u.id, u.username, u.name, u.email, u.department, u.role, u.status, u.last_login, u.employee_id,
             j.name as job_title, r.name as role_name
      FROM users u
      LEFT JOIN job_titles j ON u.job_title_id = j.id
      LEFT JOIN roles r ON u.role_id = r.id
      ${whereClause}
      ORDER BY u.id DESC
      LIMIT ? OFFSET ?
    `).all(...params, pageSize, offset);

    return {
      data: users,
      pagination: {
        page,
        pageSize,
        total,
        totalPages: Math.ceil(total / pageSize)
      }
    };
  }

  static async getUserSummary() {
    const total = await db.prepare("SELECT COUNT(*) as count FROM users").get() as any;
    const active = await db.prepare("SELECT COUNT(*) as count FROM users WHERE status = 'Active'").get() as any;
    const suspended = await db.prepare("SELECT COUNT(*) as count FROM users WHERE status = 'Suspended'").get() as any;
    const archived = await db.prepare("SELECT COUNT(*) as count FROM users WHERE status = 'Archived'").get() as any;
    const admins = await db.prepare(`SELECT COUNT(*) as count FROM users WHERE role = '${UserRole.ADMIN}'`).get() as any;
    
    const thirtyDaysAgo = new Date();
    thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
    const inactive = await db.prepare("SELECT COUNT(*) as count FROM users WHERE last_login < ? OR last_login IS NULL").get(thirtyDaysAgo.toISOString()) as any;

    return {
      total: total.count,
      active: active.count,
      suspended: suspended.count,
      archived: archived.count,
      admins: admins.count,
      inactive: inactive.count
    };
  }

  static async getUserById(id: string) {
    const user = await db.prepare(`
      SELECT u.id, u.username, u.name, u.email, u.department, u.role, u.status, u.last_login, u.employee_id,
             u.job_title_id, u.role_id, u.unit, u.reporting_manager_id, u.access_scope, u.phone_number, u.notes,
             j.name as job_title, r.name as role_name
      FROM users u
      LEFT JOIN job_titles j ON u.job_title_id = j.id
      LEFT JOIN roles r ON u.role_id = r.id
      WHERE u.id = ?
    `).get(id) as any;
    
    if (!user) return null;
    
    const permissions = await db.prepare(`
      SELECT p.module, p.action
      FROM permissions p
      JOIN role_permissions rp ON p.id = rp.permission_id
      WHERE rp.role_id = ?
      UNION
      SELECT p.module, p.action
      FROM permissions p
      JOIN user_permissions up ON p.id = up.permission_id
      WHERE up.user_id = ? AND up.is_allowed = 1
    `).all(user.role_id, user.id);

    return { ...user, permissions };
  }

  static async createUser(userData: any) {
    const { username, password, name, email, department, job_title_id, role, unit, reporting_manager_id, access_scope, phone_number, notes } = userData;
    
    return await db.transaction(async () => {
      const existingUser = await db.prepare("SELECT id FROM users WHERE username = ?").get(username);
      if (existingUser) {
        throw new ConflictError("Username already exists");
      }

      const hashedPassword = bcrypt.hashSync(password, 12);
      const role_id = (await db.prepare("SELECT id FROM roles WHERE name = ?").get(role) as any)?.id;

      let deptCode = 'EMP';
      if (department) {
        try {
          const dept = await db.prepare("SELECT entity_code FROM org_entities WHERE name_ar = ? OR name_en = ?").get(department, department) as any;
          if (dept && dept.entity_code) {
            deptCode = dept.entity_code;
          }
        } catch (e) { }
      }
      
      const latestEmp = await db.prepare("SELECT employee_id FROM users WHERE employee_id LIKE ? ORDER BY CAST(SUBSTR(employee_id, LENGTH(?) + 1) AS INTEGER) DESC LIMIT 1").get(`${deptCode}-%`, `${deptCode}-`) as any;
      let nextNum = 1001;
      if (latestEmp && latestEmp.employee_id) {
         const parts = latestEmp.employee_id.split('-');
         const lastNum = parseInt(parts[1], 10);
         if (!isNaN(lastNum)) nextNum = lastNum + 1;
      }
      const employee_id = `${deptCode}-${nextNum}`;


      const result = await db.prepare(`
        INSERT INTO users (username, password, name, email, department, job_title_id, role, unit, reporting_manager_id, access_scope, phone_number, notes, role_id, status, created_at, requires_password_change, employee_id)
        VALUES (?::text, ?::text, ?::text, ?::text, ?::text, ?::uuid, ?::text, ?::text, ?::uuid, ?::text, ?::text, ?::text, ?::uuid, 'Active', CURRENT_TIMESTAMP, 1, ?::text)
      `).run(username, hashedPassword, name, email, department || null, job_title_id || null, role, unit || null, reporting_manager_id || null, access_scope || null, phone_number || null, notes || null, role_id, employee_id);
      
      // --- AUTOMATION: Send event to n8n ---
      await N8nService.sendEvent('user.created', {
        userId: result.lastInsertRowid,
        username,
        name,
        email,
        department,
        role,
        employee_id
      });

      return { id: result.lastInsertRowid, username, name, email, department, job_title_id, role, status: 'Active', employee_id };
    })();
  }

  static async updateUser(id: string, userData: any) {
    return await db.transaction(async () => {
      const oldUser = await db.prepare("SELECT * FROM users WHERE id = ?").get(id) as any;
      if (!oldUser) throw new NotFoundError("User not found");

      const { name, email, department, job_title_id, role, unit, reporting_manager_id, access_scope, phone_number, notes, status, password } = userData;
      const role_id = (await db.prepare("SELECT id FROM roles WHERE name = ?").get(role) as any)?.id;

      if (password) {
        const hashedPassword = bcrypt.hashSync(password, 12);
        await db.prepare(`
          UPDATE users 
          SET name = ?::text, email = ?::text, department = ?::text, job_title_id = ?::uuid, role = ?::text, unit = ?::text, reporting_manager_id = ?::uuid, access_scope = ?::text, phone_number = ?::text, notes = ?::text, role_id = ?::uuid, status = ?::text, password = ?::text, requires_password_change = 1
          WHERE id = ?::uuid
        `).run(name, email, department || null, job_title_id || null, role, unit || null, reporting_manager_id || null, access_scope || null, phone_number || null, notes || null, role_id, status || oldUser.status, hashedPassword, id);
      } else {
        await db.prepare(`
          UPDATE users 
          SET name = ?::text, email = ?::text, department = ?::text, job_title_id = ?::uuid, role = ?::text, unit = ?::text, reporting_manager_id = ?::uuid, access_scope = ?::text, phone_number = ?::text, notes = ?::text, role_id = ?::uuid, status = ?::text
          WHERE id = ?::uuid
        `).run(name, email, department || null, job_title_id || null, role, unit || null, reporting_manager_id || null, access_scope || null, phone_number || null, notes || null, role_id, status || oldUser.status, id);
      }
      
      // --- AUTOMATION: Send event to n8n ---
      await N8nService.sendEvent('user.updated', {
        userId: id,
        updates: userData
      });

      return { oldUser, role_id };
    })();
  }

  static async setStatus(id: string, status: string) {
    return await db.transaction(async () => {
      const user = await db.prepare("SELECT username FROM users WHERE id = ?").get(id) as any;
      if (!user) throw new NotFoundError("User not found");
      await db.prepare(`UPDATE users SET status = ?::text WHERE id = ?::uuid`).run(status, id);
      
      // --- AUTOMATION: Send event to n8n ---
      await N8nService.sendEvent('user.status_changed', {
        userId: id,
        username: user.username,
        newStatus: status
      });

      return user.username;
    })();
  }

  static async deleteUser(id: string) {
    return await db.transaction(async () => {
      const user = await db.prepare("SELECT username FROM users WHERE id = ?").get(id) as any;
      if (!user) throw new NotFoundError("User not found");
      
      // Cleanup tokens
      await db.prepare("DELETE FROM refresh_tokens WHERE user_id = ?").run(id);
      
      await db.prepare(`DELETE FROM users WHERE id = ?`).run(id);

      // --- AUTOMATION: Send event to n8n ---
      await N8nService.sendEvent('user.deleted', {
        userId: id,
        username: user.username
      });

      return user.username;
    })();
  }

  static async unlockUser(id: string) {
    const user = await db.prepare("SELECT username FROM users WHERE id = ?").get(id) as any;
    if (!user) throw new NotFoundError("User not found");
    await db.prepare("UPDATE users SET failed_attempts = 0, locked_until = NULL WHERE id = ?::uuid").run(id);
    return user.username;
  }

  static async resetPassword(id: string, newPassword: string) {
    const user = await db.prepare("SELECT username FROM users WHERE id = ?").get(id) as any;
    if (!user) throw new NotFoundError("User not found");
    const hashed = bcrypt.hashSync(newPassword, 12);
    await db.prepare(`UPDATE users SET password = ?::text, requires_password_change = 1, session_version = session_version + 1 WHERE id = ?::uuid`).run(hashed, id);
    return user.username;
  }

  static async getActiveUsers() {
    return await db.prepare(`
      SELECT id, name, username, department, role
      FROM users
      WHERE status = 'Active'
    `).all();
  }

  static async logPermissionChange(targetUserId: string, changedById: string, oldRole: string, newRole: string, reason: string) {
    await db.prepare("INSERT INTO permission_change_logs (target_user_id, changed_by_id, old_role, new_role, reason) VALUES (?::uuid, ?::uuid, ?::text, ?::text, ?::text)")
      .run(targetUserId, changedById, oldRole, newRole, reason);
  }

  static async getStatus(id: string) {
    const user = await db.prepare("SELECT status FROM users WHERE id = ?").get(id) as any;
    if (!user) throw new NotFoundError("User not found");
    return user.status;
  }

  static async activateUser(id: string) {
    const user = await db.prepare("SELECT username FROM users WHERE id = ?").get(id) as any;
    if (!user) throw new NotFoundError("User not found");
    await db.prepare("UPDATE users SET status = 'Active', failed_attempts = 0, locked_until = NULL WHERE id = ?::uuid").run(id);
    return user.username;
  }

  static async getInitData() {
    const summary = await this.getUserSummary();
    
    // Roles
    const roles = await db.prepare("SELECT * FROM roles ORDER BY name ASC").all() as any[];
    const roleIds = roles.map(r => r.id);
    let allPermissions: any[] = [];
    
    if (roleIds.length > 0) {
      const placeholders = roleIds.map(() => '?').join(',');
      allPermissions = await db.prepare(`
        SELECT rp.role_id, p.id, p.module, p.action
        FROM permissions p
        JOIN role_permissions rp ON p.id = rp.permission_id
        WHERE rp.role_id IN (${placeholders})
      `).all(...roleIds);
    }
    
    const rolesWithPermissions = roles.map(role => ({
      ...role,
      permissions: allPermissions
        .filter(p => p.role_id === role.id)
        .map(p => ({ id: p.id, module: p.module, action: p.action }))
    }));

    // Permissions
    const permissions = await db.prepare("SELECT * FROM permissions ORDER BY module, action").all();

    // Sessions
    const sessions = await db.prepare(`
      SELECT s.*, u.name as user_name, u.username
      FROM user_sessions s
      JOIN users u ON s.user_id = u.id
      WHERE s.status = 'Active'
      ORDER BY s.last_activity DESC
    `).all();

    // Settings
    const settings = await db.prepare("SELECT * FROM user_management_settings WHERE id = 1").get();

    // Login History (page 1) initialized as empty (Lazy Loaded later)
    const loginHistoryCountRes = await db.prepare(`SELECT COUNT(*) as total FROM login_history`).get();
    const loginHistoryTotal = loginHistoryCountRes?.total || 0;
    const loginHistory: any[] = [];

    // Audit Trail (page 1) initialized as empty (Lazy Loaded later)
    const auditTrailCountRes = await db.prepare(`SELECT COUNT(*) as total FROM audit_trail`).get();
    const auditTrailTotal = auditTrailCountRes?.total || 0;
    const auditTrail: any[] = [];

    // Reset Requests
    const resetRequests = await db.prepare(`
      SELECT * FROM password_reset_requests WHERE status = 'Pending' ORDER BY request_date DESC
    `).all();

    // Departments
    const departments = await db.prepare(`SELECT * FROM departments`).all();

    // Job Titles
    const jobTitles = await db.prepare(`SELECT * FROM job_titles`).all();

    // Users (page 1)
    const usersResult = await this.getUsers({ page: 1, pageSize: 10 });

    return {
      summary,
      roles: rolesWithPermissions,
      permissions,
      sessions,
      settings,
      loginHistory: {
        data: loginHistory,
        pagination: { page: 1, pageSize: 50, total: loginHistoryTotal, totalPages: Math.ceil(loginHistoryTotal / 50) }
      },
      auditTrail: {
        data: auditTrail,
        pagination: { page: 1, pageSize: 50, total: auditTrailTotal, totalPages: Math.ceil(auditTrailTotal / 50) }
      },
      resetRequests,
      departments,
      jobTitles,
      users: usersResult
    };
  }
}

// @vitest-environment node
import { describe, it, expect, vi, beforeEach } from 'vitest';
import fc from 'fast-check';

/**
 * Property Tests for ArchiveService (Properties 1 & 15)
 *
 * Feature: audit-modules-restructure
 *
 * Property 1: Archived plans are immutable
 * Property 15: Archive separation (data moved to archive tables)
 *
 * **Validates: Requirements 1.3, 1.4, 1.5, 1.8**
 */

// ─── Mocks ───────────────────────────────────────────────────────────────────

vi.mock('../../db/index', () => {
  const mockPrepare = vi.fn();
  return {
    db: {
      prepare: mockPrepare,
      transaction: vi.fn((fn: Function) => fn),
      validateIdentifier: vi.fn((id: string) => id),
    },
  };
});

vi.mock('../../utils/n8nService', () => ({
  N8nService: {
    sendEvent: vi.fn().mockResolvedValue(undefined),
  },
}));

import { ArchiveService } from '../ArchiveService';
import { db } from '../../db/index';
import { NotFoundError } from '../../utils/errors';

// ─── Arbitraries ─────────────────────────────────────────────────────────────

/** Arbitrary for valid plan IDs (UUID-like strings) */
const planIdArb = fc.uuid();

/** Arbitrary for valid user IDs (UUID-like strings) */
const userIdArb = fc.uuid();

/** Arbitrary for roles that are allowed to archive (Manager or Admin) */
const allowedRoleArb = fc.constantFrom('Manager', 'Admin');

/** Arbitrary for valid fiscal years */
const yearArb = fc.integer({ min: 2000, max: 2100 });

/** Arbitrary for a number of tasks (0 to 10 for testing) */
const taskCountArb = fc.integer({ min: 0, max: 10 });

/** Arbitrary for a number of findings (0 to 10 for testing) */
const findingCountArb = fc.integer({ min: 0, max: 10 });

/** Arbitrary for a number of recommendations (0 to 10 for testing) */
const recCountArb = fc.integer({ min: 0, max: 10 });

/** Arbitrary for a number of evidence items (0 to 10 for testing) */
const evidenceCountArb = fc.integer({ min: 0, max: 10 });

// ─── Tests ───────────────────────────────────────────────────────────────────

describe('Property 1: Archived plans are immutable', () => {
  const mockDb = db as any;

  beforeEach(() => {
    vi.clearAllMocks();
    mockDb.prepare.mockReset();
  });

  /**
   * **Validates: Requirements 1.3, 1.8**
   *
   * For any plan that is already archived (is_archived = true), attempting to
   * archive it again must be rejected with a NotFoundError. Once a plan is
   * archived, it cannot be re-archived or modified through the archive workflow.
   *
   * This property ensures immutability: archived plans cannot be changed.
   */
  it('archivePlan throws NotFoundError for any already-archived plan regardless of planId, userId, or role', async () => {
    await fc.assert(
      fc.asyncProperty(
        planIdArb,
        userIdArb,
        allowedRoleArb,
        async (planId, userId, role) => {
          mockDb.prepare.mockReset();

          // Setup: First query (plan with is_archived = false) returns null
          mockDb.prepare.mockReturnValueOnce({
            get: vi.fn().mockResolvedValue(null),
          });

          // Setup: Second query (plan exists but is_archived = true)
          mockDb.prepare.mockReturnValueOnce({
            get: vi.fn().mockResolvedValue({ id: planId, is_archived: true }),
          });

          // Must throw NotFoundError indicating plan is already archived
          try {
            await ArchiveService.archivePlan(planId, userId, role);
            // Should never reach here
            expect.fail('Should have thrown NotFoundError');
          } catch (error: any) {
            expect(error).toBeInstanceOf(NotFoundError);
            expect(error.message).toContain('مؤرشفة مسبقاً');
          }
        }
      ),
      { numRuns: 200 }
    );
  });

  /**
   * **Validates: Requirements 1.8**
   *
   * For any already-archived plan, the archive operation must not execute any
   * INSERT or DELETE operations on the database. The rejection must happen
   * before any data modification.
   */
  it('archivePlan does not perform any INSERT or DELETE when plan is already archived', async () => {
    await fc.assert(
      fc.asyncProperty(
        planIdArb,
        userIdArb,
        allowedRoleArb,
        async (planId, userId, role) => {
          mockDb.prepare.mockReset();

          // Track call count to return different values for each db.prepare() call
          let callCount = 0;
          mockDb.prepare.mockImplementation((_sql: string) => {
            callCount++;
            if (callCount === 1) {
              // First query: plan with is_archived = false → not found
              return { get: vi.fn().mockResolvedValue(null) };
            }
            if (callCount === 2) {
              // Second query: plan exists but is_archived = true
              return { get: vi.fn().mockResolvedValue({ id: planId, is_archived: true }) };
            }
            // Should never reach here - but return safe defaults
            return { get: vi.fn().mockResolvedValue(null), run: vi.fn().mockResolvedValue(undefined), all: vi.fn().mockResolvedValue([]) };
          });

          try {
            await ArchiveService.archivePlan(planId, userId, role);
            expect.fail('Should have thrown NotFoundError');
          } catch {
            // Expected to throw
          }

          // Verify only SELECT queries were issued (no INSERT, DELETE, or UPDATE)
          const calls = mockDb.prepare.mock.calls;
          for (const call of calls) {
            const sql = call[0] as string;
            expect(sql).toMatch(/^SELECT/i);
          }
        }
      ),
      { numRuns: 200 }
    );
  });
});

describe('Property 15: Archive separation (data moved to archive tables)', () => {
  const mockDb = db as any;

  beforeEach(() => {
    vi.clearAllMocks();
    mockDb.prepare.mockReset();
  });

  /**
   * **Validates: Requirements 1.3, 1.4, 1.5**
   *
   * For any successful archive operation with N tasks, M findings, P recommendations,
   * and Q evidence items, the archive process must:
   * 1. INSERT data into archive tables (archived_plans, archived_tasks, etc.) as JSONB
   * 2. DELETE data from regular tables AFTER the inserts
   *
   * This property verifies that the archive workflow always performs INSERTs into
   * archive tables before DELETEs from regular tables, ensuring data is never lost.
   */
  it('archive process always INSERTs into archive tables before DELETEs from regular tables', async () => {
    await fc.assert(
      fc.asyncProperty(
        planIdArb,
        userIdArb,
        allowedRoleArb,
        yearArb,
        taskCountArb,
        findingCountArb,
        recCountArb,
        evidenceCountArb,
        async (planId, userId, role, year, taskCount, findingCount, recCount, evidenceCount) => {
          mockDb.prepare.mockReset();

          const samplePlan = {
            id: planId,
            plan_code: `IA-PL-${String(year).slice(-2)}-001`,
            title: `Plan ${year}`,
            year,
            status: 'Closed',
            is_archived: false,
          };

          // Generate sample data arrays
          const tasks = Array.from({ length: taskCount }, (_, i) => ({
            id: `task-${i}`,
            plan_id: planId,
            status: 'completed',
          }));
          const findings = Array.from({ length: findingCount }, (_, i) => ({
            id: `finding-${i}`,
            audit_id: planId,
            status: 'Closed',
          }));
          const recs = Array.from({ length: recCount }, (_, i) => ({
            id: `rec-${i}`,
            finding_id: `finding-0`,
            status: 'Implemented',
          }));
          const evidence = Array.from({ length: evidenceCount }, (_, i) => ({
            id: `ev-${i}`,
            audit_id: planId,
            finding_id: `finding-0`,
          }));

          // Track all SQL statements in order
          const executedSql: string[] = [];

          // Track how many items have been fetched for each type
          let tasksFetched = false;
          let findingsFetched = false;
          let recsFetched = false;
          let evidenceFetched = false;

          mockDb.prepare.mockImplementation((sql: string) => {
            executedSql.push(sql);

            if (sql.includes('is_archived = false')) {
              return { get: vi.fn().mockResolvedValue(samplePlan) };
            }
            if (sql.includes('audit_tasks') && sql.includes('COUNT') && !sql.includes('archived_')) {
              return { get: vi.fn().mockResolvedValue({ count: 0 }) };
            }
            if (sql.includes('audit_findings') && sql.includes('COUNT') && sql.includes('status') && !sql.includes('archived_')) {
              return { get: vi.fn().mockResolvedValue({ count: 0 }) };
            }
            if (sql.includes('recommendations') && sql.includes('COUNT') && sql.includes('NOT IN')) {
              return { get: vi.fn().mockResolvedValue({ count: 0 }) };
            }
            if (sql.includes('INSERT INTO archived_')) {
              return { run: vi.fn().mockResolvedValue({ lastInsertRowid: 'a-1', changes: 1 }) };
            }
            // Fetch tasks
            if (sql.includes('SELECT') && sql.includes('FROM audit_tasks') && sql.includes('plan_id') && !tasksFetched) {
              tasksFetched = true;
              return { all: vi.fn().mockResolvedValue(tasks) };
            }
            // Fetch findings
            if (sql.includes('SELECT') && sql.includes('FROM audit_findings') && sql.includes('audit_id') && !findingsFetched) {
              findingsFetched = true;
              return { all: vi.fn().mockResolvedValue(findings) };
            }
            // Fetch recommendations (JOIN query)
            if (sql.includes('SELECT') && sql.includes('FROM recommendations') && sql.includes('JOIN') && !recsFetched) {
              recsFetched = true;
              return { all: vi.fn().mockResolvedValue(recs) };
            }
            // Fetch evidence
            if (sql.includes('SELECT') && sql.includes('FROM audit_evidence') && !evidenceFetched) {
              evidenceFetched = true;
              return { all: vi.fn().mockResolvedValue(evidence) };
            }
            // Verify archived counts
            if (sql.includes('COUNT') && sql.includes('archived_tasks')) {
              return { get: vi.fn().mockResolvedValue({ count: taskCount }) };
            }
            if (sql.includes('COUNT') && sql.includes('archived_findings')) {
              return { get: vi.fn().mockResolvedValue({ count: findingCount }) };
            }
            if (sql.includes('COUNT') && sql.includes('archived_recommendations')) {
              return { get: vi.fn().mockResolvedValue({ count: recCount }) };
            }
            if (sql.includes('COUNT') && sql.includes('archived_evidence')) {
              return { get: vi.fn().mockResolvedValue({ count: evidenceCount }) };
            }
            if (sql.includes('DELETE')) {
              return { run: vi.fn().mockResolvedValue({ changes: 0 }) };
            }
            if (sql.includes('UPDATE audit_plans')) {
              return { run: vi.fn().mockResolvedValue({ changes: 1 }) };
            }
            if (sql.includes('SELECT year')) {
              return { get: vi.fn().mockResolvedValue({ year }) };
            }
            return { get: vi.fn().mockResolvedValue({ count: 0 }), run: vi.fn().mockResolvedValue({ changes: 0 }), all: vi.fn().mockResolvedValue([]) };
          });

          await ArchiveService.archivePlan(planId, userId, role);

          // Verify: All INSERTs into archive tables happen BEFORE any DELETE
          const firstArchiveInsertIdx = executedSql.findIndex((sql: string) =>
            sql?.includes('INSERT INTO archived_')
          );
          const firstDeleteIdx = executedSql.findIndex((sql: string) =>
            sql?.match(/DELETE FROM (audit_evidence|recommendations|audit_findings|audit_tasks)/)
          );

          // If there are items to archive, INSERTs must come before DELETEs
          if (firstArchiveInsertIdx !== -1 && firstDeleteIdx !== -1) {
            expect(firstArchiveInsertIdx).toBeLessThan(firstDeleteIdx);
          }

          // Verify: All archive INSERT calls exist for each data type
          const archiveInserts = executedSql.filter((sql: string) =>
            sql?.includes('INSERT INTO archived_')
          );

          // Plan is always archived (1 INSERT for archived_plans)
          // Plus one INSERT per task, finding, recommendation, and evidence
          const expectedInsertCount = 1 + taskCount + findingCount + recCount + evidenceCount;
          expect(archiveInserts.length).toBe(expectedInsertCount);

          // Verify: DELETE operations exist for regular tables
          const deleteOps = executedSql.filter((sql: string) =>
            sql?.match(/DELETE FROM (audit_evidence|recommendations|audit_findings|audit_tasks)/)
          );
          expect(deleteOps.length).toBe(4); // evidence, recommendations, findings, tasks
        }
      ),
      { numRuns: 100 }
    );
  });

  /**
   * **Validates: Requirements 1.4**
   *
   * For any successful archive, the plan data is stored as JSONB in the archive table.
   * The INSERT into archived_plans must include the full plan data serialized as JSON.
   */
  it('archive process stores plan data as JSONB in archived_plans', async () => {
    await fc.assert(
      fc.asyncProperty(
        planIdArb,
        userIdArb,
        allowedRoleArb,
        yearArb,
        async (planId, userId, role, year) => {
          mockDb.prepare.mockReset();

          const samplePlan = {
            id: planId,
            plan_code: `IA-PL-${String(year).slice(-2)}-001`,
            title: `Plan ${year}`,
            year,
            status: 'Closed',
            is_archived: false,
          };

          // Track the arguments passed to the archived_plans INSERT
          let archivePlanArgs: any[] = [];

          // Use mockImplementation to handle all db.prepare calls dynamically
          let callIndex = 0;
          mockDb.prepare.mockImplementation((sql: string) => {
            callIndex++;

            // Plan found (not archived)
            if (sql.includes('is_archived = false')) {
              return { get: vi.fn().mockResolvedValue(samplePlan) };
            }
            // Open tasks count
            if (sql.includes('audit_tasks') && sql.includes('COUNT') && !sql.includes('archived_')) {
              return { get: vi.fn().mockResolvedValue({ count: 0 }) };
            }
            // Open findings count
            if (sql.includes('audit_findings') && sql.includes('COUNT') && sql.includes('status') && !sql.includes('archived_')) {
              return { get: vi.fn().mockResolvedValue({ count: 0 }) };
            }
            // Open recommendations count
            if (sql.includes('recommendations') && sql.includes('COUNT') && sql.includes('NOT IN')) {
              return { get: vi.fn().mockResolvedValue({ count: 0 }) };
            }
            // Archive plan INSERT - capture args
            if (sql.includes('INSERT INTO archived_plans')) {
              return {
                run: vi.fn((...args: any[]) => {
                  archivePlanArgs = args;
                  return Promise.resolve({ lastInsertRowid: 'ap-1', changes: 1 });
                }),
              };
            }
            // Other INSERT operations
            if (sql.includes('INSERT INTO archived_')) {
              return { run: vi.fn().mockResolvedValue({ lastInsertRowid: 'a-1', changes: 1 }) };
            }
            // DELETE operations (must come before SELECT check due to subqueries containing SELECT)
            if (sql.includes('DELETE')) {
              return { run: vi.fn().mockResolvedValue({ changes: 0 }) };
            }
            // Fetch tasks/findings/recs/evidence (all empty)
            if (sql.trimStart().startsWith('SELECT') && (sql.includes('FROM audit_tasks') || sql.includes('FROM audit_findings') || sql.includes('FROM recommendations') || sql.includes('FROM audit_evidence'))) {
              return { all: vi.fn().mockResolvedValue([]) };
            }
            // Verify archived counts
            if (sql.includes('COUNT') && sql.includes('archived_')) {
              return { get: vi.fn().mockResolvedValue({ count: 0 }) };
            }
            // UPDATE plan
            if (sql.includes('UPDATE audit_plans')) {
              return { run: vi.fn().mockResolvedValue({ changes: 1 }) };
            }
            // Fetch plan year for N8n event
            if (sql.includes('SELECT year')) {
              return { get: vi.fn().mockResolvedValue({ year }) };
            }
            // Fallback
            return { get: vi.fn().mockResolvedValue({ count: 0 }), run: vi.fn().mockResolvedValue({ changes: 0 }), all: vi.fn().mockResolvedValue([]) };
          });

          await ArchiveService.archivePlan(planId, userId, role);

          // Verify the archived_plans INSERT was called with JSON-serialized plan data
          expect(archivePlanArgs[0]).toBe(planId);
          expect(archivePlanArgs[1]).toBe(JSON.stringify(samplePlan));
          expect(archivePlanArgs[2]).toBe(year);
          expect(archivePlanArgs[3]).toBe(userId);
        }
      ),
      { numRuns: 200 }
    );
  });

  /**
   * **Validates: Requirements 1.5**
   *
   * After a successful archive, the plan row remains in audit_plans with
   * is_archived = true and status = 'Archived'. The UPDATE must always be
   * the last modification to the plan row.
   */
  it('archive process marks plan as is_archived=true after moving data to archive tables', async () => {
    await fc.assert(
      fc.asyncProperty(
        planIdArb,
        userIdArb,
        allowedRoleArb,
        yearArb,
        async (planId, userId, role, year) => {
          mockDb.prepare.mockReset();

          const samplePlan = {
            id: planId,
            plan_code: `IA-PL-${String(year).slice(-2)}-001`,
            title: `Plan ${year}`,
            year,
            status: 'Closed',
            is_archived: false,
          };

          // Track all SQL statements in order
          const executedSql: string[] = [];

          mockDb.prepare.mockImplementation((sql: string) => {
            executedSql.push(sql);

            if (sql.includes('is_archived = false')) {
              return { get: vi.fn().mockResolvedValue(samplePlan) };
            }
            if (sql.includes('audit_tasks') && sql.includes('COUNT') && !sql.includes('archived_')) {
              return { get: vi.fn().mockResolvedValue({ count: 0 }) };
            }
            if (sql.includes('audit_findings') && sql.includes('COUNT') && sql.includes('status') && !sql.includes('archived_')) {
              return { get: vi.fn().mockResolvedValue({ count: 0 }) };
            }
            if (sql.includes('recommendations') && sql.includes('COUNT') && sql.includes('NOT IN')) {
              return { get: vi.fn().mockResolvedValue({ count: 0 }) };
            }
            if (sql.includes('INSERT INTO archived_')) {
              return { run: vi.fn().mockResolvedValue({ lastInsertRowid: 'a-1', changes: 1 }) };
            }
            if (sql.includes('DELETE')) {
              return { run: vi.fn().mockResolvedValue({ changes: 0 }) };
            }
            if (sql.trimStart().startsWith('SELECT') && (sql.includes('FROM audit_tasks') || sql.includes('FROM audit_findings') || sql.includes('FROM recommendations') || sql.includes('FROM audit_evidence'))) {
              return { all: vi.fn().mockResolvedValue([]) };
            }
            if (sql.includes('COUNT') && sql.includes('archived_')) {
              return { get: vi.fn().mockResolvedValue({ count: 0 }) };
            }
            if (sql.includes('UPDATE audit_plans')) {
              return { run: vi.fn().mockResolvedValue({ changes: 1 }) };
            }
            if (sql.includes('SELECT year')) {
              return { get: vi.fn().mockResolvedValue({ year }) };
            }
            return { get: vi.fn().mockResolvedValue({ count: 0 }), run: vi.fn().mockResolvedValue({ changes: 0 }), all: vi.fn().mockResolvedValue([]) };
          });

          await ArchiveService.archivePlan(planId, userId, role);

          // Verify the UPDATE to mark plan as archived exists and comes after DELETEs
          const updatePlanIdx = executedSql.findIndex((sql: string) =>
            sql?.includes('UPDATE audit_plans SET is_archived = true')
          );
          const lastDeleteIdx = Math.max(
            ...executedSql.map((sql: string, idx: number) =>
              sql?.match(/DELETE FROM (audit_evidence|recommendations|audit_findings|audit_tasks)/)
                ? idx
                : -1
            )
          );

          // UPDATE must exist
          expect(updatePlanIdx).toBeGreaterThan(-1);

          // UPDATE must come after all DELETEs
          if (lastDeleteIdx > -1) {
            expect(updatePlanIdx).toBeGreaterThan(lastDeleteIdx);
          }

          // The UPDATE SQL must set is_archived = true and status = 'Archived'
          const updateSql = executedSql[updatePlanIdx];
          expect(updateSql).toContain('is_archived = true');
          expect(updateSql).toContain("status = 'Archived'");
        }
      ),
      { numRuns: 200 }
    );
  });
});

