import { describe, it, expect, beforeEach, vi } from 'vitest';

// Mock the db module
vi.mock('../../db/index', () => {
  const mockPrepare = vi.fn();
  const mockTransaction = vi.fn((fn: Function) => fn);
  return {
    db: {
      prepare: mockPrepare,
      transaction: mockTransaction,
    },
  };
