      mockGet.mockResolvedValueOnce({ total: 5 });
      mockAll.mockResolvedValueOnce([{ id: 1, status: 'Active' }]);

      await BaseService.findAll('audit_plans', {
        where: { status: 'Active', department: 'IT' },
