      ).rejects.toThrow(NotFoundError);

      await expect(
        BaseService.findById('audit_plans', 999)
      ).rejects.toThrow('audit_plans item with ID 999 not found');
    });
  });

  describe('create', () => {
    it('should remove restricted fields (id, created_at, updated_at) from body', async () => {
