  },
}));

// Mock logger
vi.mock('../../utils/logger', () => ({
  default: {
    info: vi.fn(),
    warn: vi.fn(),
    error: vi.fn(),
    debug: vi.fn(),
  },
}));

// Mock axios
vi.mock('axios', () => {
  const mockAxios: any = {
    post: vi.fn(),
