import { EvidenceStorageService } from '../EvidenceStorageService';
import { db } from '../../db/index';
import { NumberingService } from '../NumberingService';
import fs from 'fs';
import { NotFoundError } from '../../utils/errors';

describe('EvidenceStorageService', () => {
  const mockDb = db as any;

  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('sanitizeFileName', () => {
    it('should return empty string for empty input', () => {
      expect(EvidenceStorageService.sanitizeFileName('')).toBe('');
    });

    it('should return empty string for null/undefined input', () => {
      expect(EvidenceStorageService.sanitizeFileName(null as any)).toBe('');
      expect(EvidenceStorageService.sanitizeFileName(undefined as any)).toBe('');
    });

    it('should pass through a normal file name unchanged', () => {
      expect(EvidenceStorageService.sanitizeFileName('report.pdf')).toBe('report.pdf');
    });

    it('should remove forward slashes', () => {
      expect(EvidenceStorageService.sanitizeFileName('path/to/file.pdf')).toBe('pathtofile.pdf');
    });

    it('should remove backslashes', () => {
      expect(EvidenceStorageService.sanitizeFileName('path\\to\\file.pdf')).toBe('pathtofile.pdf');
    });

    it('should remove ../ sequences', () => {
      expect(EvidenceStorageService.sanitizeFileName('../../../etc/passwd')).toBe('etcpasswd');
    });

    it('should remove ..\\ sequences', () => {
      expect(EvidenceStorageService.sanitizeFileName('..\\..\\windows\\system32')).toBe('windowssystem32');
    });

    it('should remove Windows absolute path prefixes (C:\\)', () => {
      expect(EvidenceStorageService.sanitizeFileName('C:\\Users\\file.pdf')).toBe('Usersfile.pdf');
    });

    it('should remove Windows absolute path prefixes (D:/)', () => {
      expect(EvidenceStorageService.sanitizeFileName('D:/data/file.pdf')).toBe('datafile.pdf');
    });

    it('should remove Unix absolute path prefix (/)', () => {
      expect(EvidenceStorageService.sanitizeFileName('/etc/passwd')).toBe('etcpasswd');
    });

    it('should remove multiple leading slashes', () => {
      expect(EvidenceStorageService.sanitizeFileName('///file.pdf')).toBe('file.pdf');
    });

    it('should truncate to 255 characters', () => {
      const longName = 'a'.repeat(300) + '.pdf';
      const result = EvidenceStorageService.sanitizeFileName(longName);
      expect(result.length).toBe(255);
    });

    it('should handle combined attack vectors', () => {
      const malicious = 'C:\\..\\..\\../uploads/../../../etc/passwd';
      const result = EvidenceStorageService.sanitizeFileName(malicious);
      expect(result).not.toContain('/');
      expect(result).not.toContain('\\');
      expect(result).not.toContain('..');
    });

    it('should preserve file extension after sanitization', () => {
      expect(EvidenceStorageService.sanitizeFileName('my-file.pdf')).toBe('my-file.pdf');
      expect(EvidenceStorageService.sanitizeFileName('report_2025.docx')).toBe('report_2025.docx');
    });

    it('should handle file names with spaces', () => {
      expect(EvidenceStorageService.sanitizeFileName('my file name.pdf')).toBe('my file name.pdf');
    });

    it('should handle file names with dots (not traversal)', () => {
      expect(EvidenceStorageService.sanitizeFileName('file.v2.backup.pdf')).toBe('file.v2.backup.pdf');
    });
  });

  describe('buildEvidencePath', () => {
    it('should build correct path with all components', () => {
      const result = EvidenceStorageService.buildEvidencePath(
        'plan-uuid-001',
        'finding-uuid-001',
        'IA-PL-25-001-F01-E01',
        'report.pdf'
      );
      expect(result).toBe('/uploads/findings/plan-uuid-001/finding-uuid-001/IA-PL-25-001-F01-E01_report.pdf');
    });

    it('should sanitize the file name in the path', () => {
      const result = EvidenceStorageService.buildEvidencePath(
        'plan-uuid-001',
        'finding-uuid-001',
        'IA-PL-25-001-F01-E01',
        '../../../etc/passwd'
      );
      expect(result).toBe('/uploads/findings/plan-uuid-001/finding-uuid-001/IA-PL-25-001-F01-E01_etcpasswd');
      expect(result).not.toContain('..');
    });

    it('should handle file names with special characters', () => {
      const result = EvidenceStorageService.buildEvidencePath(
        'plan-001',
        'finding-001',
        'E01',
        'تقرير المراجعة.pdf'
      );
      expect(result).toBe('/uploads/findings/plan-001/finding-001/E01_تقرير المراجعة.pdf');
    });
  });

  describe('attachEvidence', () => {
    const findingId = 'finding-uuid-001';
    const userId = 'user-uuid-001';
    const file = {
      originalname: 'evidence-doc.pdf',
      buffer: Buffer.from('file content'),
      mimetype: 'application/pdf',
    };
    const data = {
      type: 'Document' as const,
      description: 'Audit evidence document',
    };

    it('should throw NotFoundError when finding does not exist', async () => {
      mockDb.prepare.mockReturnValueOnce({
        get: vi.fn().mockResolvedValue(undefined),
      });

      await expect(
        EvidenceStorageService.attachEvidence(findingId, file, data, userId)
      ).rejects.toThrow(NotFoundError);
    });

    it('should successfully attach evidence when finding exists', async () => {
      // Finding exists
      mockDb.prepare.mockReturnValueOnce({
        get: vi.fn().mockResolvedValue({
          id: findingId,
          audit_id: 'plan-uuid-001',
          finding_number: 'IA-PL-25-001-F01',
        }),
      });

      // NumberingService returns evidence number
      vi.mocked(NumberingService.nextEvidenceNumber).mockResolvedValue('IA-PL-25-001-F01-E01');

      // fs.promises.mkdir succeeds
      vi.mocked(fs.promises.mkdir).mockResolvedValue(undefined as any);

      // fs.promises.writeFile succeeds
      vi.mocked(fs.promises.writeFile).mockResolvedValue(undefined);

      // DB insert succeeds
      mockDb.prepare.mockReturnValueOnce({
        get: vi.fn().mockResolvedValue({
          id: 'evidence-uuid-001',
          evidence_number: 'IA-PL-25-001-F01-E01',
          file_path: '/uploads/findings/plan-uuid-001/finding-uuid-001/IA-PL-25-001-F01-E01_evidence-doc.pdf',
          finding_id: findingId,
        }),
      });

      const result = await EvidenceStorageService.attachEvidence(findingId, file, data, userId);

      expect(result.id).toBe('evidence-uuid-001');
      expect(result.evidence_number).toBe('IA-PL-25-001-F01-E01');
      expect(result.file_path).toContain('/uploads/findings/plan-uuid-001/finding-uuid-001/');
      expect(result.finding_id).toBe(findingId);

      // Verify NumberingService was called correctly
      expect(NumberingService.nextEvidenceNumber).toHaveBeenCalledWith(findingId, 'IA-PL-25-001-F01');

      // Verify file was written
      expect(fs.promises.mkdir).toHaveBeenCalled();
      expect(fs.promises.writeFile).toHaveBeenCalled();
    });

    it('should not insert DB record when file write fails (Requirement 8.6)', async () => {
      // Finding exists
      mockDb.prepare.mockReturnValueOnce({
        get: vi.fn().mockResolvedValue({
          id: findingId,
          audit_id: 'plan-uuid-001',
          finding_number: 'IA-PL-25-001-F01',
        }),
      });

      // NumberingService returns evidence number
      vi.mocked(NumberingService.nextEvidenceNumber).mockResolvedValue('IA-PL-25-001-F01-E01');

      // fs.promises.mkdir succeeds
      vi.mocked(fs.promises.mkdir).mockResolvedValue(undefined as any);

      // fs.promises.writeFile FAILS
      vi.mocked(fs.promises.writeFile).mockRejectedValue(new Error('Disk full'));

      await expect(
        EvidenceStorageService.attachEvidence(findingId, file, data, userId)
      ).rejects.toThrow(/File storage failed/);

      // DB insert should NOT have been called (only 1 prepare call for finding lookup)
      expect(mockDb.prepare).toHaveBeenCalledTimes(1);
    });

    it('should delete written file when DB insert fails (Requirement 8.7)', async () => {
      // Finding exists
      mockDb.prepare.mockReturnValueOnce({
        get: vi.fn().mockResolvedValue({
          id: findingId,
          audit_id: 'plan-uuid-001',
          finding_number: 'IA-PL-25-001-F01',
        }),
      });

      // NumberingService returns evidence number
      vi.mocked(NumberingService.nextEvidenceNumber).mockResolvedValue('IA-PL-25-001-F01-E01');

      // fs.promises.mkdir succeeds
      vi.mocked(fs.promises.mkdir).mockResolvedValue(undefined as any);

      // fs.promises.writeFile succeeds
      vi.mocked(fs.promises.writeFile).mockResolvedValue(undefined);

      // DB insert FAILS
      mockDb.prepare.mockReturnValueOnce({
        get: vi.fn().mockRejectedValue(new Error('DB constraint violation')),
      });

      // fs.promises.unlink for rollback
      vi.mocked(fs.promises.unlink).mockResolvedValue(undefined);

      await expect(
        EvidenceStorageService.attachEvidence(findingId, file, data, userId)
      ).rejects.toThrow(/Evidence record save failed/);

      // Verify file was deleted (rollback)
      expect(fs.promises.unlink).toHaveBeenCalled();
    });

    it('should handle rollback file deletion failure gracefully', async () => {
      // Finding exists
      mockDb.prepare.mockReturnValueOnce({
        get: vi.fn().mockResolvedValue({
          id: findingId,
          audit_id: 'plan-uuid-001',
          finding_number: 'IA-PL-25-001-F01',
        }),
      });

      // NumberingService returns evidence number
      vi.mocked(NumberingService.nextEvidenceNumber).mockResolvedValue('IA-PL-25-001-F01-E01');

      // fs.promises.mkdir succeeds
      vi.mocked(fs.promises.mkdir).mockResolvedValue(undefined as any);

      // fs.promises.writeFile succeeds
      vi.mocked(fs.promises.writeFile).mockResolvedValue(undefined);

      // DB insert FAILS
      mockDb.prepare.mockReturnValueOnce({
        get: vi.fn().mockRejectedValue(new Error('DB error')),
      });

      // fs.promises.unlink ALSO fails (file cleanup fails)
      vi.mocked(fs.promises.unlink).mockRejectedValue(new Error('Permission denied'));

      // Should still throw the DB error, not the unlink error
      await expect(
        EvidenceStorageService.attachEvidence(findingId, file, data, userId)
      ).rejects.toThrow(/Evidence record save failed/);
    });

    it('should sanitize file name in the stored path', async () => {
      const maliciousFile = {
        originalname: '../../../etc/passwd',
        buffer: Buffer.from('content'),
        mimetype: 'text/plain',
      };

      // Finding exists
      mockDb.prepare.mockReturnValueOnce({
        get: vi.fn().mockResolvedValue({
          id: findingId,
          audit_id: 'plan-uuid-001',
          finding_number: 'IA-PL-25-001-F01',
        }),
      });

      // NumberingService returns evidence number
      vi.mocked(NumberingService.nextEvidenceNumber).mockResolvedValue('IA-PL-25-001-F01-E01');

      // fs operations succeed
      vi.mocked(fs.promises.mkdir).mockResolvedValue(undefined as any);
      vi.mocked(fs.promises.writeFile).mockResolvedValue(undefined);

      // DB insert succeeds
      mockDb.prepare.mockReturnValueOnce({
        get: vi.fn().mockResolvedValue({
          id: 'evidence-uuid-002',
          evidence_number: 'IA-PL-25-001-F01-E01',
          file_path: '/uploads/findings/plan-uuid-001/finding-uuid-001/IA-PL-25-001-F01-E01_etcpasswd',
          finding_id: findingId,
        }),
      });

      const result = await EvidenceStorageService.attachEvidence(findingId, maliciousFile, data, userId);

      // The path should not contain traversal sequences
      expect(result.file_path).not.toContain('..');
      expect(result.file_path).not.toContain('etc/passwd');
    });

    it('should create directory structure before writing file', async () => {
      // Finding exists
      mockDb.prepare.mockReturnValueOnce({
        get: vi.fn().mockResolvedValue({
          id: findingId,
          audit_id: 'plan-uuid-001',
          finding_number: 'IA-PL-25-001-F01',
        }),
      });

      vi.mocked(NumberingService.nextEvidenceNumber).mockResolvedValue('IA-PL-25-001-F01-E01');
      vi.mocked(fs.promises.mkdir).mockResolvedValue(undefined as any);
      vi.mocked(fs.promises.writeFile).mockResolvedValue(undefined);

      mockDb.prepare.mockReturnValueOnce({
        get: vi.fn().mockResolvedValue({
          id: 'evidence-uuid-003',
          evidence_number: 'IA-PL-25-001-F01-E01',
          file_path: '/uploads/findings/plan-uuid-001/finding-uuid-001/IA-PL-25-001-F01-E01_evidence-doc.pdf',
          finding_id: findingId,
        }),
      });

      await EvidenceStorageService.attachEvidence(findingId, file, data, userId);

      // Verify mkdir was called with recursive: true
      expect(fs.promises.mkdir).toHaveBeenCalledWith(
        expect.any(String),
        { recursive: true }
      );
    });
  });
});

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { FileEncryptionService } from '../FileEncryptionService';
import crypto from 'crypto';
import fs from 'fs';
import path from 'path';
import os from 'os';

describe('FileEncryptionService', () => {
  const originalEnv = process.env;
  let tmpDir: string;
  let service: FileEncryptionService;

  beforeEach(async () => {
    // Create a temporary directory for test files
    tmpDir = await fs.promises.mkdtemp(path.join(os.tmpdir(), 'enc-test-'));
    process.env = { ...originalEnv, FILE_ENCRYPTION_KEY: 'test-encryption-key-for-unit-tests-minimum-32-chars' };
    service = new FileEncryptionService(tmpDir);
  });

  afterEach(async () => {
    process.env = originalEnv;
    // Clean up temp directory
    try {
      await fs.promises.rm(tmpDir, { recursive: true, force: true });
    } catch {
      // Ignore cleanup errors
    }
  });

  describe('initialization', () => {
    it('should enable encryption when FILE_ENCRYPTION_KEY is set', () => {
      expect(service.isEncryptionEnabled()).toBe(true);
    });

    it('should disable encryption when FILE_ENCRYPTION_KEY is not set', () => {
      delete process.env.FILE_ENCRYPTION_KEY;
      const noKeyService = new FileEncryptionService(tmpDir);
      expect(noKeyService.isEncryptionEnabled()).toBe(false);
    });
  });

  describe('encryptFile', () => {
    it('should encrypt a file and return metadata with iv, authTag, and checksum', async () => {
      const buffer = Buffer.from('Hello, this is a test file content for encryption.');
      const input = {
        fileId: 'test-file-001',
        originalName: 'document.pdf',
        mimeType: 'application/pdf',
        size: buffer.length,
        keyVersion: 1,
      };

      const result = await service.encryptFile(buffer, input);

      expect(result.metadata.fileId).toBe('test-file-001');
      expect(result.metadata.originalName).toBe('document.pdf');
      expect(result.metadata.mimeType).toBe('application/pdf');
      expect(result.metadata.size).toBe(buffer.length);
      expect(result.metadata.iv).toBeTruthy();
      expect(result.metadata.authTag).toBeTruthy();
      expect(result.metadata.checksum).toBeTruthy();
      expect(result.metadata.encryptedAt).toBeTruthy();
      expect(result.metadata.keyVersion).toBe(1);
      expect(result.path).toContain('.enc');
    });

    it('should save encrypted file with .enc extension', async () => {
      const buffer = Buffer.from('Test content');
      const input = {
        fileId: 'test-file-002',
        originalName: 'report.docx',
        mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
        size: buffer.length,
        keyVersion: 1,
      };

      const result = await service.encryptFile(buffer, input);

      expect(result.path).toBe(path.join(tmpDir, 'test-file-002.enc'));
      // Verify file exists
      const stat = await fs.promises.stat(result.path);
      expect(stat.isFile()).toBe(true);
    });

    it('should write encrypted file in format [IV(12)][AuthTag(16)][Ciphertext]', async () => {
      const buffer = Buffer.from('Content to verify format');
      const input = {
        fileId: 'test-file-003',
        originalName: 'test.txt',
        mimeType: 'text/plain',
        size: buffer.length,
        keyVersion: 1,
      };

      const result = await service.encryptFile(buffer, input);
      const fileData = await fs.promises.readFile(result.path);

      // File should be at least IV(12) + AuthTag(16) + some ciphertext
      expect(fileData.length).toBeGreaterThan(28);

      // IV should be 12 bytes
      const iv = fileData.subarray(0, 12);
      expect(iv.length).toBe(12);

      // AuthTag should be 16 bytes
      const authTag = fileData.subarray(12, 28);
      expect(authTag.length).toBe(16);
    });

    it('should compute correct SHA-256 checksum of original file', async () => {
      const buffer = Buffer.from('Checksum verification content');
      const expectedChecksum = crypto.createHash('sha256').update(buffer).digest('hex');

      const input = {
        fileId: 'test-file-004',
        originalName: 'check.txt',
        mimeType: 'text/plain',
        size: buffer.length,
        keyVersion: 1,
      };

      const result = await service.encryptFile(buffer, input);
      expect(result.metadata.checksum).toBe(expectedChecksum);
    });

    it('should generate unique IVs for different files', async () => {
      const buffer = Buffer.from('Same content');
      const input1 = {
        fileId: 'test-file-005a',
        originalName: 'file1.txt',
        mimeType: 'text/plain',
        size: buffer.length,
        keyVersion: 1,
      };
      const input2 = {
        fileId: 'test-file-005b',
        originalName: 'file2.txt',
        mimeType: 'text/plain',
        size: buffer.length,
        keyVersion: 1,
      };

      const result1 = await service.encryptFile(buffer, input1);
      const result2 = await service.encryptFile(buffer, input2);

      expect(result1.metadata.iv).not.toBe(result2.metadata.iv);
    });

    it('should store file unencrypted when encryption is disabled', async () => {
      delete process.env.FILE_ENCRYPTION_KEY;
      const noKeyService = new FileEncryptionService(tmpDir);

      const content = 'Unencrypted content';
      const buffer = Buffer.from(content);
      const input = {
        fileId: 'test-file-006',
        originalName: 'plain.txt',
        mimeType: 'text/plain',
        size: buffer.length,
        keyVersion: 0,
      };

      const result = await noKeyService.encryptFile(buffer, input);

      // File should be stored without .enc extension
      expect(result.path).not.toContain('.enc');
      // File content should be the original buffer
      const stored = await fs.promises.readFile(result.path);
      expect(stored.toString()).toBe(content);
      // Metadata should have empty iv and authTag
      expect(result.metadata.iv).toBe('');
      expect(result.metadata.authTag).toBe('');
      expect(result.metadata.keyVersion).toBe(0);
      // Checksum should still be computed
      expect(result.metadata.checksum).toBeTruthy();
    });
  });

  describe('decryptFile', () => {
    it('should decrypt an encrypted file and return original content', async () => {
      const originalContent = 'This is the original file content that should be recovered after decryption.';
      const buffer = Buffer.from(originalContent);
      const input = {
        fileId: 'test-decrypt-001',
        originalName: 'secret.pdf',
        mimeType: 'application/pdf',
        size: buffer.length,
        keyVersion: 1,
      };

      await service.encryptFile(buffer, input);
      const result = await service.decryptFile('test-decrypt-001');

      expect(result.buffer.toString()).toBe(originalContent);
      expect(result.metadata.fileId).toBe('test-decrypt-001');
    });

    it('should throw error for non-existent file metadata', async () => {
      await expect(service.decryptFile('non-existent-id')).rejects.toThrow(
        'File metadata not found'
      );
    });

    it('should throw error when encryption key is missing but file was encrypted', async () => {
      const buffer = Buffer.from('Encrypted content');
      const input = {
        fileId: 'test-decrypt-002',
        originalName: 'locked.pdf',
        mimeType: 'application/pdf',
        size: buffer.length,
        keyVersion: 1,
      };

      // Encrypt with key
      await service.encryptFile(buffer, input);

      // Create a new service without key but with the same metadata
      delete process.env.FILE_ENCRYPTION_KEY;
      const noKeyService = new FileEncryptionService(tmpDir);
      noKeyService.setMetadata('test-decrypt-002', service.getMetadata('test-decrypt-002')!);

      await expect(noKeyService.decryptFile('test-decrypt-002')).rejects.toThrow(
        'Cannot decrypt file: FILE_ENCRYPTION_KEY is not set'
      );
    });

    it('should return unencrypted file when keyVersion is 0', async () => {
      delete process.env.FILE_ENCRYPTION_KEY;
      const noKeyService = new FileEncryptionService(tmpDir);

      const content = 'Plain text file';
      const buffer = Buffer.from(content);
      const input = {
        fileId: 'test-decrypt-003',
        originalName: 'plain.txt',
        mimeType: 'text/plain',
        size: buffer.length,
        keyVersion: 0,
      };

      await noKeyService.encryptFile(buffer, input);
      const result = await noKeyService.decryptFile('test-decrypt-003');

      expect(result.buffer.toString()).toBe(content);
    });
  });

  describe('encryption roundtrip', () => {
    it('should satisfy decrypt(encrypt(data)) === data for various content', async () => {
      const testCases = [
        Buffer.from('Simple text'),
        Buffer.from('مرحبا بالعالم - Arabic text'),
        crypto.randomBytes(1024), // Random binary data
        Buffer.alloc(0), // Empty buffer
        Buffer.from('A'.repeat(10000)), // Larger content
      ];

      for (let i = 0; i < testCases.length; i++) {
        const buffer = testCases[i];
        const input = {
          fileId: `roundtrip-${i}`,
          originalName: `test-${i}.bin`,
          mimeType: 'application/octet-stream',
          size: buffer.length,
          keyVersion: 1,
        };

        await service.encryptFile(buffer, input);
        const result = await service.decryptFile(`roundtrip-${i}`);

        expect(Buffer.compare(result.buffer, buffer)).toBe(0);
      }
    });
  });

  describe('verifyIntegrity', () => {
    it('should return true for a valid encrypted file', async () => {
      const buffer = Buffer.from('Integrity check content');
      const input = {
        fileId: 'integrity-001',
        originalName: 'check.txt',
        mimeType: 'text/plain',
        size: buffer.length,
        keyVersion: 1,
      };

      await service.encryptFile(buffer, input);
      const isValid = await service.verifyIntegrity('integrity-001');

      expect(isValid).toBe(true);
    });

    it('should return false for a tampered file', async () => {
      const buffer = Buffer.from('Original content');
      const input = {
        fileId: 'integrity-002',
        originalName: 'tampered.txt',
        mimeType: 'text/plain',
        size: buffer.length,
        keyVersion: 1,
      };

      await service.encryptFile(buffer, input);

      // Tamper with the encrypted file (modify a byte in the ciphertext area)
      const encPath = path.join(tmpDir, 'integrity-002.enc');
      const fileData = await fs.promises.readFile(encPath);
      // Modify a byte in the ciphertext (after IV + AuthTag)
      const tampered = Buffer.from(fileData);
      if (tampered.length > 29) {
        tampered[29] = tampered[29] ^ 0xff;
      }
      await fs.promises.writeFile(encPath, tampered);

      const isValid = await service.verifyIntegrity('integrity-002');
      expect(isValid).toBe(false);
    });

    it('should return false for non-existent file', async () => {
      const isValid = await service.verifyIntegrity('non-existent');
      expect(isValid).toBe(false);
    });
  });

  describe('rotateKey', () => {
    it('should re-encrypt a file with a new key', async () => {
      const originalContent = 'Content to be re-encrypted with new key';
      const buffer = Buffer.from(originalContent);
      const oldKey = 'test-encryption-key-for-unit-tests-minimum-32-chars';
      const newKey = 'new-encryption-key-for-rotation-testing-minimum-32';

      const input = {
        fileId: 'rotate-001',
        originalName: 'rotate.pdf',
        mimeType: 'application/pdf',
        size: buffer.length,
        keyVersion: 1,
      };

      const encResult = await service.encryptFile(buffer, input);
      const originalIv = encResult.metadata.iv;

      // Rotate key
      const updatedMetadata = await service.rotateKey('rotate-001', oldKey, newKey, 2);

      expect(updatedMetadata.keyVersion).toBe(2);
      // New IV should be different from the original
      expect(updatedMetadata.iv).not.toBe(originalIv);

      // Verify we can still decrypt with the new key active
      const result = await service.decryptFile('rotate-001');
      expect(result.buffer.toString()).toBe(originalContent);
    });

    it('should throw error for non-existent file during rotation', async () => {
      await expect(
        service.rotateKey('non-existent', 'old', 'new', 2)
      ).rejects.toThrow('File metadata not found');
    });
  });

  describe('rotateEncryptionKey (bulk)', () => {
    it('should re-encrypt all files with the new key', async () => {
      const contents = ['File 1 content', 'File 2 content', 'File 3 content'];

      for (let i = 0; i < contents.length; i++) {
        const buffer = Buffer.from(contents[i]);
        await service.encryptFile(buffer, {
          fileId: `bulk-${i}`,
          originalName: `file-${i}.txt`,
          mimeType: 'text/plain',
          size: buffer.length,
          keyVersion: 1,
        });
      }

      const oldKey = Buffer.from('test-encryption-key-for-unit-tests-minimum-32-chars', 'utf8');
      const newKey = Buffer.from('new-bulk-rotation-key-for-testing-minimum-32-chars!', 'utf8');

      await service.rotateEncryptionKey(oldKey, newKey);

      // Verify all files can still be decrypted
      for (let i = 0; i < contents.length; i++) {
        const result = await service.decryptFile(`bulk-${i}`);
        expect(result.buffer.toString()).toBe(contents[i]);
        expect(result.metadata.keyVersion).toBe(2);
      }
    });

    it('should skip unencrypted files during bulk rotation', async () => {
      delete process.env.FILE_ENCRYPTION_KEY;
      const mixedService = new FileEncryptionService(tmpDir);

      // Store an unencrypted file
      const buffer = Buffer.from('Unencrypted');
      await mixedService.encryptFile(buffer, {
        fileId: 'unenc-001',
        originalName: 'plain.txt',
        mimeType: 'text/plain',
        size: buffer.length,
        keyVersion: 0,
      });

      // Now enable encryption and add an encrypted file
      process.env.FILE_ENCRYPTION_KEY = 'test-encryption-key-for-unit-tests-minimum-32-chars';
      const encService = new FileEncryptionService(tmpDir);
      // Copy metadata from mixed service
      encService.setMetadata('unenc-001', mixedService.getMetadata('unenc-001')!);

      const encBuffer = Buffer.from('Encrypted content');
      await encService.encryptFile(encBuffer, {
        fileId: 'enc-001',
        originalName: 'secret.pdf',
        mimeType: 'application/pdf',
        size: encBuffer.length,
        keyVersion: 1,
      });

      const oldKey = Buffer.from('test-encryption-key-for-unit-tests-minimum-32-chars', 'utf8');
      const newKey = Buffer.from('new-bulk-rotation-key-for-testing-minimum-32-chars!', 'utf8');

      // Should not throw for unencrypted files
      await encService.rotateEncryptionKey(oldKey, newKey);

      // Encrypted file should be re-encrypted
      const result = await encService.decryptFile('enc-001');
      expect(result.buffer.toString()).toBe('Encrypted content');
      expect(result.metadata.keyVersion).toBe(2);

      // Unencrypted file metadata should remain unchanged
      const unencMeta = encService.getMetadata('unenc-001');
      expect(unencMeta?.keyVersion).toBe(0);
    });
  });
});

// @vitest-environment node
import { describe, it, expect, vi, beforeEach } from 'vitest';

// Use vi.hoisted to create mock references that can be used in vi.mock factories
const { mockPrepare } = vi.hoisted(() => ({
  mockPrepare: vi.fn(),
}));

// Mock the database module
vi.mock('../../db/index', () => ({
  db: {
    prepare: mockPrepare,
  },
}));

import { NotificationService } from '../NotificationService';

describe('NotificationService', () => {
  let mockGet: ReturnType<typeof vi.fn>;
  let mockAll: ReturnType<typeof vi.fn>;
  let mockRun: ReturnType<typeof vi.fn>;

  beforeEach(() => {
    vi.clearAllMocks();
    mockGet = vi.fn();
    mockAll = vi.fn();
    mockRun = vi.fn();
    mockPrepare.mockReturnValue({
      get: mockGet,
      all: mockAll,
      run: mockRun,
    });
  });

  // ─── getNotifications ──────────────────────────────────────────────────────

  describe('getNotifications', () => {
    it('returns paginated notifications ordered by date DESC', async () => {
      const mockNotifications = [
        { id: 'n1', event_type: 'task_assigned', description: 'Task assigned', date: '2024-01-02' },
        { id: 'n2', event_type: 'comment_added', description: 'New comment', date: '2024-01-01' },
      ];
      // First call: count query
      mockGet.mockResolvedValueOnce({ total: 2 });
      // Second call: data query
      mockAll.mockResolvedValueOnce(mockNotifications);

      const result = await NotificationService.getNotifications('user-1', 1, 20);

      expect(result.data).toEqual(mockNotifications);
      expect(result.pagination).toEqual({
        page: 1,
        pageSize: 20,
        total: 2,
        totalPages: 1,
        hasNext: false,
        hasPrev: false,
      });
      expect(mockPrepare).toHaveBeenCalledWith(
        expect.stringContaining('ORDER BY n.date DESC')
      );
    });

    it('uses correct LIMIT and OFFSET based on page/pageSize', async () => {
      // First call: count query
      mockGet.mockResolvedValueOnce({ total: 30 });
      // Second call: data query
      mockAll.mockResolvedValueOnce([]);

      await NotificationService.getNotifications('user-1', 3, 10);

      // page 3, pageSize 10 → offset = (3-1)*10 = 20
      expect(mockAll).toHaveBeenCalledWith('user-1', 10, 20);
    });

    it('falls back to legacy table if notification_recipients fails', async () => {
      // First call (count on new table) throws
      mockGet.mockRejectedValueOnce(new Error('table not found'));
      // Fallback: count query on legacy table
      mockGet.mockResolvedValueOnce({ total: 1 });
      // Fallback: data query on legacy table
      const legacyResults = [
        { id: 'n1', event_type: 'task_assigned', description: 'Legacy notification', date: '2024-01-01' },
      ];
      mockAll.mockResolvedValueOnce(legacyResults);

      const result = await NotificationService.getNotifications('user-1', 1, 20);

      expect(result.data).toEqual(legacyResults);
      expect(result.pagination.total).toBe(1);
      expect(mockPrepare).toHaveBeenCalledWith(
        expect.stringContaining('FROM notifications WHERE user_id')
      );
    });
  });

  // ─── getUnreadCount ────────────────────────────────────────────────────────

  describe('getUnreadCount', () => {
    it('returns correct unread count for a user', async () => {
      mockGet.mockResolvedValueOnce({ count: 5 });

      const result = await NotificationService.getUnreadCount('user-1');

      expect(result).toEqual({ count: 5 });
      expect(mockPrepare).toHaveBeenCalledWith(
        expect.stringContaining('notification_recipients')
      );
    });

    it('returns { count: 0 } when no unread notifications', async () => {
      mockGet.mockResolvedValueOnce(null);

      const result = await NotificationService.getUnreadCount('user-1');

      expect(result).toEqual({ count: 0 });
    });
  });

  // ─── markAsRead ────────────────────────────────────────────────────────────

  describe('markAsRead', () => {
    it('updates is_read to true and sets read_at timestamp', async () => {
      mockRun.mockResolvedValueOnce({ changes: 1 });

      const result = await NotificationService.markAsRead('notif-1', 'user-1');

      expect(result).toBe(true);
      expect(mockPrepare).toHaveBeenCalledWith(
        expect.stringContaining('SET is_read = true, read_at = CURRENT_TIMESTAMP')
      );
      expect(mockRun).toHaveBeenCalledWith('notif-1', 'user-1');
    });

    it('falls back to legacy status update', async () => {
      // First call (new table) throws
      mockRun.mockRejectedValueOnce(new Error('table not found'));
      // Second call (legacy) succeeds
      mockRun.mockResolvedValueOnce({ changes: 1 });

      const result = await NotificationService.markAsRead('notif-1', 'user-1');

      expect(result).toBe(true);
      expect(mockPrepare).toHaveBeenCalledTimes(2);
      expect(mockPrepare).toHaveBeenLastCalledWith(
        expect.stringContaining("SET status = 'Read'")
      );
    });
  });

  // ─── markAllRead ───────────────────────────────────────────────────────────

  describe('markAllRead', () => {
    it('updates all unread notifications for the user', async () => {
      mockRun.mockResolvedValueOnce({ changes: 3 });

      const result = await NotificationService.markAllRead('user-1');

      expect(result).toBe(true);
      expect(mockPrepare).toHaveBeenCalledWith(
        expect.stringContaining('SET is_read = true, read_at = CURRENT_TIMESTAMP')
      );
      expect(mockPrepare).toHaveBeenCalledWith(
        expect.stringContaining('is_read = false')
      );
      expect(mockRun).toHaveBeenCalledWith('user-1');
    });
  });

  // ─── dismiss ───────────────────────────────────────────────────────────────

  describe('dismiss', () => {
    it('sets is_dismissed to true without deleting the record', async () => {
      mockRun.mockResolvedValueOnce({ changes: 1 });

      const result = await NotificationService.dismiss('notif-1', 'user-1');

      expect(result).toBe(true);
      expect(mockPrepare).toHaveBeenCalledWith(
        expect.stringContaining('SET is_dismissed = true')
      );
      expect(mockPrepare).not.toHaveBeenCalledWith(
        expect.stringContaining('DELETE')
      );
    });

    it('falls back to DELETE in legacy mode', async () => {
      // First call (new table) throws
      mockRun.mockRejectedValueOnce(new Error('table not found'));
      // Second call (legacy DELETE) succeeds
      mockRun.mockResolvedValueOnce({ changes: 1 });

      const result = await NotificationService.dismiss('notif-1', 'user-1');

      expect(result).toBe(true);
      expect(mockPrepare).toHaveBeenLastCalledWith(
        expect.stringContaining('DELETE FROM notifications')
      );
    });
  });

  // ─── create ────────────────────────────────────────────────────────────────

  describe('create', () => {
    it('creates notification with single recipient', async () => {
      mockGet.mockResolvedValueOnce({ id: 'new-notif-id', date: '2024-01-01T00:00:00Z' });
      mockRun.mockResolvedValue({ changes: 1 });

      const result = await NotificationService.create(
        'user-1',
        'task_assigned',
        'You have a new task',
        'audit',
        '/audit/tasks/1'
      );

      expect(result).toBe(true);
      // Should insert into notifications table
      expect(mockPrepare).toHaveBeenCalledWith(
        expect.stringContaining('INSERT INTO notifications')
      );
      // Should insert into notification_recipients table
      expect(mockPrepare).toHaveBeenCalledWith(
        expect.stringContaining('INSERT INTO notification_recipients')
      );
    });

    it('creates notification with multiple recipients', async () => {
      mockGet.mockResolvedValueOnce({ id: 'new-notif-id', date: '2024-01-01T00:00:00Z' });
      mockRun.mockResolvedValue({ changes: 1 });

      const result = await NotificationService.create(
        ['user-1', 'user-2', 'user-3'],
        'plan_started',
        'Audit plan started',
        'audit',
        '/audit/plans/1'
      );

      expect(result).toBe(true);
      // Should insert recipient rows for each user
      expect(mockPrepare).toHaveBeenCalledWith(
        expect.stringContaining('INSERT INTO notification_recipients')
      );
    });

    it('creates notification with "all" recipients (queries all active users)', async () => {
      // First call: query all active users
      mockAll.mockResolvedValueOnce([
        { id: 'user-1' },
        { id: 'user-2' },
        { id: 'user-3' },
      ]);
      // Insert notification
      mockGet.mockResolvedValueOnce({ id: 'new-notif-id', date: '2024-01-01T00:00:00Z' });
      mockRun.mockResolvedValue({ changes: 1 });

      const result = await NotificationService.create(
        'all',
        'policy_review_required',
        'Policy review required',
        'compliance',
        '/compliance/policies'
      );

      expect(result).toBe(true);
      expect(mockPrepare).toHaveBeenCalledWith(
        expect.stringContaining("SELECT id FROM users WHERE status = 'active'")
      );
    });

    it('excludes the actor from recipients', async () => {
      mockGet.mockResolvedValueOnce({ id: 'new-notif-id', date: '2024-01-01T00:00:00Z' });
      mockRun.mockResolvedValue({ changes: 1 });

      await NotificationService.create(
        ['user-1', 'user-2', 'actor-user'],
        'comment_added',
        'New comment',
        'audit',
        '/audit/tasks/1',
        { actorId: 'actor-user' }
      );

      // The notification_recipients insert should NOT include actor-user
      // We verify by checking that run was called with user-1 and user-2 but not actor-user
      const recipientInsertCalls = mockRun.mock.calls.filter(
        (call) => call.length === 2 && call[0] === 'new-notif-id'
      );
      const recipientIds = recipientInsertCalls.map((call) => call[1]);
      expect(recipientIds).not.toContain('actor-user');
    });

    it('sends WebSocket message to connected authenticated users', async () => {
      mockGet.mockResolvedValueOnce({ id: 'new-notif-id', date: '2024-01-01T00:00:00Z' });
      mockRun.mockResolvedValue({ changes: 1 });

      const mockClient1 = { readyState: 1, authenticated: true, userId: 'user-1', send: vi.fn() };
      const mockClient2 = { readyState: 1, authenticated: true, userId: 'user-2', send: vi.fn() };
      const mockClient3 = { readyState: 1, authenticated: false, userId: 'user-3', send: vi.fn() };
      const mockWss = {
        clients: new Set([mockClient1, mockClient2, mockClient3]),
      };

      await NotificationService.create(
        ['user-1', 'user-2'],
        'task_assigned',
        'New task',
        'audit',
        '/audit/tasks/1',
        { wss: mockWss }
      );

      // Authenticated clients in recipient list should receive the message
      expect(mockClient1.send).toHaveBeenCalledWith(
        expect.stringContaining('NEW_NOTIFICATION')
      );
      expect(mockClient2.send).toHaveBeenCalledWith(
        expect.stringContaining('NEW_NOTIFICATION')
      );
      // Non-authenticated client should NOT receive
      expect(mockClient3.send).not.toHaveBeenCalled();
    });

    it('falls back to legacy single-table insert on error', async () => {
      // First insert (new table) throws
      mockGet.mockRejectedValueOnce(new Error('notification_recipients does not exist'));
      // Legacy fallback inserts succeed
      mockRun.mockResolvedValue({ changes: 1 });

      const consoleSpy = vi.spyOn(console, 'error').mockImplementation(() => {});

      const result = await NotificationService.create(
        ['user-1', 'user-2'],
        'task_assigned',
        'New task',
        'audit',
        '/audit/tasks/1'
      );

      expect(result).toBe(true);
      // Should log the error
      expect(consoleSpy).toHaveBeenCalledWith(
        expect.stringContaining('[NotificationService]'),
        expect.any(String)
      );
      // Should fall back to legacy inserts (one per user)
      const legacyInsertCalls = mockPrepare.mock.calls.filter(
        (call) => typeof call[0] === 'string' && call[0].includes('INSERT INTO notifications') && call[0].includes('user_id')
      );
      expect(legacyInsertCalls.length).toBeGreaterThanOrEqual(2);

      consoleSpy.mockRestore();
    });
  });

  // ─── getAdminIds ───────────────────────────────────────────────────────────

  describe('getAdminIds', () => {
    it('returns array of admin user IDs', async () => {
      mockAll.mockResolvedValueOnce([
        { id: 'admin-1' },
        { id: 'admin-2' },
      ]);

      const result = await NotificationService.getAdminIds();

      expect(result).toEqual(['admin-1', 'admin-2']);
      expect(mockPrepare).toHaveBeenCalledWith(
        expect.stringContaining("role = 'Admin'")
      );
      expect(mockPrepare).toHaveBeenCalledWith(
        expect.stringContaining("status = 'active'")
      );
    });
  });

  // ─── getUserIdByName ───────────────────────────────────────────────────────

  describe('getUserIdByName', () => {
    it('returns user ID when found by name', async () => {
      mockGet.mockResolvedValueOnce({ id: 'user-123' });

      const result = await NotificationService.getUserIdByName('John Doe');

      expect(result).toBe('user-123');
      expect(mockGet).toHaveBeenCalledWith('John Doe', 'John Doe');
    });

    it('returns null when user not found', async () => {
      mockGet.mockResolvedValueOnce(null);

      const result = await NotificationService.getUserIdByName('NonExistent');

      expect(result).toBeNull();
    });
  });
});

// @vitest-environment node
import { describe, it, expect, vi, beforeEach } from 'vitest';
import fc from 'fast-check';

/**
 * Property Test: Hierarchical numbering derivation (Property 11)
 *
 * Feature: audit-modules-restructure
 * Property 11: كل رقم فرعي يحمل بادئة رقم العنصر الأب كاملةً (الترقيم متفرّع وليس مستقلاً).
 *
 * **Validates: Requirements 3.1, 3.2, 3.3, 3.4, 3.5, 3.7**
 *
 * When: توليد رقم لمهمة/ملاحظة/توصية/دليل
 * Then: taskNumber.startsWith(planCode) ∧ findingNumber.startsWith(planCode)
 *       ∧ recNumber.startsWith(findingNumber) ∧ evidenceNumber.startsWith(findingNumber)
 *
 * This test validates the NumberingService's hierarchical numbering logic
 * without database dependencies by extracting the pure formatting functions.
 */

// ─── Pure Formatting Logic (extracted from NumberingService) ──────────────────

const PADDING = { plan: 3, child: 2 } as const;
const MAX_PLAN_SEQ = 999;
const MAX_CHILD_SEQ = 99;

/**
 * Formats a plan code given a year and sequence number.
 * Mirrors NumberingService.nextPlanCode formatting logic.
 */
function formatPlanCode(year: number, seq: number): string {
  const yy = String(year).slice(-2).padStart(2, '0');
  return `IA-PL-${yy}-${String(seq).padStart(PADDING.plan, '0')}`;
}

/**
 * Formats a task number given a plan code and sequence.
 * Mirrors NumberingService.nextTaskNumber formatting logic.
 */
function formatTaskNumber(planCode: string, seq: number): string {
  return `${planCode}-T${String(seq).padStart(PADDING.child, '0')}`;
}

/**
 * Formats a finding number given a plan code and sequence.
 * Mirrors NumberingService.nextFindingNumber formatting logic.
 */
function formatFindingNumber(planCode: string, seq: number): string {
  return `${planCode}-F${String(seq).padStart(PADDING.child, '0')}`;
}

/**
 * Formats a recommendation number given a finding number and sequence.
 * Mirrors NumberingService.nextRecommendationNumber formatting logic.
 */
function formatRecommendationNumber(findingNumber: string, seq: number): string {
  return `${findingNumber}-R${String(seq).padStart(PADDING.child, '0')}`;
}

/**
 * Formats an evidence number given a finding number and sequence.
 * Mirrors NumberingService.nextEvidenceNumber formatting logic.
 */
function formatEvidenceNumber(findingNumber: string, seq: number): string {
  return `${findingNumber}-E${String(seq).padStart(PADDING.child, '0')}`;
}

// ─── Arbitraries ─────────────────────────────────────────────────────────────

/** Year in valid range (2000-2099), producing YY from 00 to 99 */
const yearArb = fc.integer({ min: 2000, max: 2099 });

/** Plan sequence in valid range (1-999) */
const planSeqArb = fc.integer({ min: 1, max: MAX_PLAN_SEQ });

/** Child sequence in valid range (1-99) */
const childSeqArb = fc.integer({ min: 1, max: MAX_CHILD_SEQ });

// ─── Tests ───────────────────────────────────────────────────────────────────

describe('Property 11: Hierarchical numbering derivation', () => {
  describe('Requirement 3.1: Plan codes follow format IA-PL-{YY}-{NNN}', () => {
    it('plan code matches IA-PL-{YY}-{NNN} format for any valid year and sequence', () => {
      fc.assert(
        fc.property(yearArb, planSeqArb, (year, seq) => {
          const planCode = formatPlanCode(year, seq);

          // Must match the exact format: IA-PL-{2 digits}-{3 digits}
          const planCodeRegex = /^IA-PL-\d{2}-\d{3}$/;
          expect(planCode).toMatch(planCodeRegex);

          // YY must be last 2 digits of year
          const yy = String(year).slice(-2).padStart(2, '0');
          expect(planCode).toContain(`IA-PL-${yy}-`);

          // NNN must be zero-padded sequence in range 001-999
          const nnn = planCode.split('-')[3];
          const seqValue = parseInt(nnn, 10);
          expect(seqValue).toBeGreaterThanOrEqual(1);
          expect(seqValue).toBeLessThanOrEqual(999);
          expect(seqValue).toBe(seq);
        }),
        { numRuns: 200 }
      );
    });
  });

  describe('Requirement 3.2: Task numbers derived from plan code as {planCode}-T{NN}', () => {
    it('task number starts with full plan code and appends -T{NN}', () => {
      fc.assert(
        fc.property(yearArb, planSeqArb, childSeqArb, (year, planSeq, taskSeq) => {
          const planCode = formatPlanCode(year, planSeq);
          const taskNumber = formatTaskNumber(planCode, taskSeq);

          // Task number must start with the full plan code
          expect(taskNumber.startsWith(planCode)).toBe(true);

          // Must match format {planCode}-T{NN}
          const suffix = taskNumber.slice(planCode.length);
          const taskSuffixRegex = /^-T\d{2}$/;
          expect(suffix).toMatch(taskSuffixRegex);

          // NN must be the sequence value (01-99)
          const nn = suffix.slice(2); // skip "-T"
          const nnValue = parseInt(nn, 10);
          expect(nnValue).toBeGreaterThanOrEqual(1);
          expect(nnValue).toBeLessThanOrEqual(99);
          expect(nnValue).toBe(taskSeq);
        }),
        { numRuns: 200 }
      );
    });
  });

  describe('Requirement 3.3: Finding numbers derived from plan code as {planCode}-F{NN}', () => {
    it('finding number starts with full plan code and appends -F{NN}', () => {
      fc.assert(
        fc.property(yearArb, planSeqArb, childSeqArb, (year, planSeq, findingSeq) => {
          const planCode = formatPlanCode(year, planSeq);
          const findingNumber = formatFindingNumber(planCode, findingSeq);

          // Finding number must start with the full plan code
          expect(findingNumber.startsWith(planCode)).toBe(true);

          // Must match format {planCode}-F{NN}
          const suffix = findingNumber.slice(planCode.length);
          const findingSuffixRegex = /^-F\d{2}$/;
          expect(suffix).toMatch(findingSuffixRegex);

          // NN must be the sequence value (01-99)
          const nn = suffix.slice(2); // skip "-F"
          const nnValue = parseInt(nn, 10);
          expect(nnValue).toBeGreaterThanOrEqual(1);
          expect(nnValue).toBeLessThanOrEqual(99);
          expect(nnValue).toBe(findingSeq);
        }),
        { numRuns: 200 }
      );
    });
  });

  describe('Requirement 3.4: Recommendation numbers derived from finding number as {findingNumber}-R{NN}', () => {
    it('recommendation number starts with full finding number and appends -R{NN}', () => {
      fc.assert(
        fc.property(
          yearArb,
          planSeqArb,
          childSeqArb,
          childSeqArb,
          (year, planSeq, findingSeq, recSeq) => {
            const planCode = formatPlanCode(year, planSeq);
            const findingNumber = formatFindingNumber(planCode, findingSeq);
            const recNumber = formatRecommendationNumber(findingNumber, recSeq);

            // Recommendation number must start with the full finding number
            expect(recNumber.startsWith(findingNumber)).toBe(true);

            // Must match format {findingNumber}-R{NN}
            const suffix = recNumber.slice(findingNumber.length);
            const recSuffixRegex = /^-R\d{2}$/;
            expect(suffix).toMatch(recSuffixRegex);

            // NN must be the sequence value (01-99)
            const nn = suffix.slice(2); // skip "-R"
            const nnValue = parseInt(nn, 10);
            expect(nnValue).toBeGreaterThanOrEqual(1);
            expect(nnValue).toBeLessThanOrEqual(99);
            expect(nnValue).toBe(recSeq);
          }
        ),
        { numRuns: 200 }
      );
    });
  });

  describe('Requirement 3.5: Evidence numbers derived from finding number as {findingNumber}-E{NN}', () => {
    it('evidence number starts with full finding number and appends -E{NN}', () => {
      fc.assert(
        fc.property(
          yearArb,
          planSeqArb,
          childSeqArb,
          childSeqArb,
          (year, planSeq, findingSeq, evidenceSeq) => {
            const planCode = formatPlanCode(year, planSeq);
            const findingNumber = formatFindingNumber(planCode, findingSeq);
            const evidenceNumber = formatEvidenceNumber(findingNumber, evidenceSeq);

            // Evidence number must start with the full finding number
            expect(evidenceNumber.startsWith(findingNumber)).toBe(true);

            // Must match format {findingNumber}-E{NN}
            const suffix = evidenceNumber.slice(findingNumber.length);
            const evidenceSuffixRegex = /^-E\d{2}$/;
            expect(suffix).toMatch(evidenceSuffixRegex);

            // NN must be the sequence value (01-99)
            const nn = suffix.slice(2); // skip "-E"
            const nnValue = parseInt(nn, 10);
            expect(nnValue).toBeGreaterThanOrEqual(1);
            expect(nnValue).toBeLessThanOrEqual(99);
            expect(nnValue).toBe(evidenceSeq);
          }
        ),
        { numRuns: 200 }
      );
    });
  });

  describe('Requirement 3.7: Child numbers always contain full parent prefix (hierarchical derivation)', () => {
    it('full hierarchy chain: plan → task contains plan prefix', () => {
      fc.assert(
        fc.property(yearArb, planSeqArb, childSeqArb, (year, planSeq, taskSeq) => {
          const planCode = formatPlanCode(year, planSeq);
          const taskNumber = formatTaskNumber(planCode, taskSeq);

          // Task number contains the full plan code as prefix
          expect(taskNumber.startsWith(planCode)).toBe(true);
        }),
        { numRuns: 200 }
      );
    });

    it('full hierarchy chain: plan → finding → recommendation contains all parent prefixes', () => {
      fc.assert(
        fc.property(
          yearArb,
          planSeqArb,
          childSeqArb,
          childSeqArb,
          (year, planSeq, findingSeq, recSeq) => {
            const planCode = formatPlanCode(year, planSeq);
            const findingNumber = formatFindingNumber(planCode, findingSeq);
            const recNumber = formatRecommendationNumber(findingNumber, recSeq);

            // Finding contains plan prefix
            expect(findingNumber.startsWith(planCode)).toBe(true);
            // Recommendation contains finding prefix (which includes plan prefix)
            expect(recNumber.startsWith(findingNumber)).toBe(true);
            // Recommendation also contains plan prefix (transitive)
            expect(recNumber.startsWith(planCode)).toBe(true);
          }
        ),
        { numRuns: 200 }
      );
    });

    it('full hierarchy chain: plan → finding → evidence contains all parent prefixes', () => {
      fc.assert(
        fc.property(
          yearArb,
          planSeqArb,
          childSeqArb,
          childSeqArb,
          (year, planSeq, findingSeq, evidenceSeq) => {
            const planCode = formatPlanCode(year, planSeq);
            const findingNumber = formatFindingNumber(planCode, findingSeq);
            const evidenceNumber = formatEvidenceNumber(findingNumber, evidenceSeq);

            // Finding contains plan prefix
            expect(findingNumber.startsWith(planCode)).toBe(true);
            // Evidence contains finding prefix (which includes plan prefix)
            expect(evidenceNumber.startsWith(findingNumber)).toBe(true);
            // Evidence also contains plan prefix (transitive)
            expect(evidenceNumber.startsWith(planCode)).toBe(true);
          }
        ),
        { numRuns: 200 }
      );
    });

    it('sibling entities (task and finding) under same plan share the plan prefix but differ in suffix', () => {
      fc.assert(
        fc.property(
          yearArb,
          planSeqArb,
          childSeqArb,
          childSeqArb,
          (year, planSeq, taskSeq, findingSeq) => {
            const planCode = formatPlanCode(year, planSeq);
            const taskNumber = formatTaskNumber(planCode, taskSeq);
            const findingNumber = formatFindingNumber(planCode, findingSeq);

            // Both share the same plan prefix
            expect(taskNumber.startsWith(planCode)).toBe(true);
            expect(findingNumber.startsWith(planCode)).toBe(true);

            // They differ in their type suffix (-T vs -F)
            const taskSuffix = taskNumber.slice(planCode.length + 1, planCode.length + 2);
            const findingSuffix = findingNumber.slice(planCode.length + 1, planCode.length + 2);
            expect(taskSuffix).toBe('T');
            expect(findingSuffix).toBe('F');
          }
        ),
        { numRuns: 200 }
      );
    });

    it('sibling entities (recommendation and evidence) under same finding share the finding prefix but differ in suffix', () => {
      fc.assert(
        fc.property(
          yearArb,
          planSeqArb,
          childSeqArb,
          childSeqArb,
          childSeqArb,
          (year, planSeq, findingSeq, recSeq, evidenceSeq) => {
            const planCode = formatPlanCode(year, planSeq);
            const findingNumber = formatFindingNumber(planCode, findingSeq);
            const recNumber = formatRecommendationNumber(findingNumber, recSeq);
            const evidenceNumber = formatEvidenceNumber(findingNumber, evidenceSeq);

            // Both share the same finding prefix
            expect(recNumber.startsWith(findingNumber)).toBe(true);
            expect(evidenceNumber.startsWith(findingNumber)).toBe(true);

            // They differ in their type suffix (-R vs -E)
            const recSuffix = recNumber.slice(findingNumber.length + 1, findingNumber.length + 2);
            const evidenceSuffix = evidenceNumber.slice(findingNumber.length + 1, findingNumber.length + 2);
            expect(recSuffix).toBe('R');
            expect(evidenceSuffix).toBe('E');
          }
        ),
        { numRuns: 200 }
      );
    });
  });
});

