      mockDb.prepare.mockReturnValue({ get: mockGet });

      await NumberingService.nextFindingNumber('my-plan-uuid', 'IA-PL-25-001');

      expect(mockGet).toHaveBeenCalledWith('finding', 'my-plan-uuid');
    });

    it('should throw NumberingOverflowError when sequence exceeds 99', async () => {
      setupCounterResponse(100);

      await expect(
        NumberingService.nextFindingNumber('plan-id', 'IA-PL-25-001')
      ).rejects.toThrow(NumberingOverflowError);
    });
  });

  describe('nextRecommendationNumber', () => {
    it('should generate {findingNumber}-R{NN} format', async () => {
      setupCounterResponse(1);

      const num = await NumberingService.nextRecommendationNumber(
        'finding-id',
        'IA-PL-25-001-F01'
      );

      expect(num).toBe('IA-PL-25-001-F01-R01');
    });

    it('should pad sequence to 2 digits', async () => {
      setupCounterResponse(3);

      const num = await NumberingService.nextRecommendationNumber(
        'finding-id',
        'IA-PL-25-001-F02'
      );

      expect(num).toBe('IA-PL-25-001-F02-R03');
    });

    it('should use findingId as scope_id for counter', async () => {
      const mockGet = vi.fn().mockResolvedValue({ last_value: 1 });
      mockDb.prepare.mockReturnValue({ get: mockGet });

      await NumberingService.nextRecommendationNumber('my-finding-uuid', 'IA-PL-25-001-F01');

      expect(mockGet).toHaveBeenCalledWith('rec', 'my-finding-uuid');
    });

    it('should throw NumberingOverflowError when sequence exceeds 99', async () => {
      setupCounterResponse(100);

      await expect(
        NumberingService.nextRecommendationNumber('finding-id', 'IA-PL-25-001-F01')
      ).rejects.toThrow(NumberingOverflowError);
    });
  });

  describe('nextEvidenceNumber', () => {
    it('should generate {findingNumber}-E{NN} format', async () => {
      setupCounterResponse(1);

      const num = await NumberingService.nextEvidenceNumber(
        'finding-id',
        'IA-PL-25-001-F01'
      );

      expect(num).toBe('IA-PL-25-001-F01-E01');
    });

    it('should pad sequence to 2 digits', async () => {
      setupCounterResponse(12);

      const num = await NumberingService.nextEvidenceNumber(
        'finding-id',
        'IA-PL-25-001-F03'
      );

      expect(num).toBe('IA-PL-25-001-F03-E12');
    });

    it('should use findingId as scope_id for counter', async () => {
      const mockGet = vi.fn().mockResolvedValue({ last_value: 1 });
      mockDb.prepare.mockReturnValue({ get: mockGet });

      await NumberingService.nextEvidenceNumber('my-finding-uuid', 'IA-PL-25-001-F01');

      expect(mockGet).toHaveBeenCalledWith('evidence', 'my-finding-uuid');
    });

    it('should throw NumberingOverflowError when sequence exceeds 99', async () => {
      setupCounterResponse(100);

      await expect(
        NumberingService.nextEvidenceNumber('finding-id', 'IA-PL-25-001-F01')
      ).rejects.toThrow(NumberingOverflowError);
    });
  });

  describe('hierarchical numbering derivation', () => {
    it('should produce full hierarchy: plan → task', async () => {
      setupCounterResponse(3);
      const planCode = await NumberingService.nextPlanCode(2025);

      setupCounterResponse(5);
      const taskNum = await NumberingService.nextTaskNumber('plan-id', planCode);

      expect(taskNum).toBe('IA-PL-25-003-T05');
      expect(taskNum.startsWith(planCode)).toBe(true);
    });

    it('should produce full hierarchy: plan → finding → recommendation', async () => {
      setupCounterResponse(1);
      const planCode = await NumberingService.nextPlanCode(2025);

      setupCounterResponse(2);
      const findingNum = await NumberingService.nextFindingNumber('plan-id', planCode);

      setupCounterResponse(1);
      const recNum = await NumberingService.nextRecommendationNumber('finding-id', findingNum);

      expect(recNum).toBe('IA-PL-25-001-F02-R01');
      expect(recNum.startsWith(findingNum)).toBe(true);
      expect(findingNum.startsWith(planCode)).toBe(true);
    });

    it('should produce full hierarchy: plan → finding → evidence', async () => {
      setupCounterResponse(1);
      const planCode = await NumberingService.nextPlanCode(2025);

      setupCounterResponse(1);
      const findingNum = await NumberingService.nextFindingNumber('plan-id', planCode);

      setupCounterResponse(3);
      const evidenceNum = await NumberingService.nextEvidenceNumber('finding-id', findingNum);

      expect(evidenceNum).toBe('IA-PL-25-001-F01-E03');
      expect(evidenceNum.startsWith(findingNum)).toBe(true);
      expect(findingNum.startsWith(planCode)).toBe(true);
    });
  });
});

import { describe, it, expect } from 'vitest';
import {
  getPartitionName,
  getPartitionDateRange,
  getPartitionsToDropByRetention,
  parsePartitionName,
  PartitionInfo,
} from '../PartitionManager';

describe('PartitionManager', () => {
  describe('getPartitionName', () => {
    it('should generate correct partition name for January 2024', () => {
      const date = new Date(Date.UTC(2024, 0, 1)); // January 2024
      expect(getPartitionName(date)).toBe('audit_trail_y2024m01');
    });

    it('should generate correct partition name for December 2025', () => {
      const date = new Date(Date.UTC(2025, 11, 15)); // December 2025
      expect(getPartitionName(date)).toBe('audit_trail_y2025m12');
    });

    it('should generate correct partition name for single-digit months with zero padding', () => {
      const date = new Date(Date.UTC(2024, 2, 10)); // March 2024
      expect(getPartitionName(date)).toBe('audit_trail_y2024m03');
    });

    it('should generate correct partition name for October (double-digit month)', () => {
      const date = new Date(Date.UTC(2024, 9, 1)); // October 2024
      expect(getPartitionName(date)).toBe('audit_trail_y2024m10');
    });

    it('should handle year boundaries correctly', () => {
      const dec = new Date(Date.UTC(2024, 11, 31)); // Dec 31, 2024
      const jan = new Date(Date.UTC(2025, 0, 1)); // Jan 1, 2025
      expect(getPartitionName(dec)).toBe('audit_trail_y2024m12');
      expect(getPartitionName(jan)).toBe('audit_trail_y2025m01');
    });
  });

  describe('getPartitionDateRange', () => {
    it('should return correct start and end for January 2024', () => {
      const date = new Date(Date.UTC(2024, 0, 15)); // mid-January
      const { startDate, endDate } = getPartitionDateRange(date);

      expect(startDate.toISOString()).toBe('2024-01-01T00:00:00.000Z');
      expect(endDate.toISOString()).toBe('2024-02-01T00:00:00.000Z');
    });

    it('should return correct start and end for December 2024', () => {
      const date = new Date(Date.UTC(2024, 11, 25)); // December
      const { startDate, endDate } = getPartitionDateRange(date);

      expect(startDate.toISOString()).toBe('2024-12-01T00:00:00.000Z');
      expect(endDate.toISOString()).toBe('2025-01-01T00:00:00.000Z');
    });

    it('should return correct range for February (leap year)', () => {
      const date = new Date(Date.UTC(2024, 1, 10)); // Feb 2024 (leap year)
      const { startDate, endDate } = getPartitionDateRange(date);

      expect(startDate.toISOString()).toBe('2024-02-01T00:00:00.000Z');
      expect(endDate.toISOString()).toBe('2024-03-01T00:00:00.000Z');
    });

    it('should return correct range for February (non-leap year)', () => {
      const date = new Date(Date.UTC(2023, 1, 10)); // Feb 2023 (non-leap)
      const { startDate, endDate } = getPartitionDateRange(date);

      expect(startDate.toISOString()).toBe('2023-02-01T00:00:00.000Z');
      expect(endDate.toISOString()).toBe('2023-03-01T00:00:00.000Z');
    });

    it('should always have start as 1st of month and end as 1st of next month', () => {
      for (let month = 0; month < 12; month++) {
        const date = new Date(Date.UTC(2024, month, 15));
        const { startDate, endDate } = getPartitionDateRange(date);

        expect(startDate.getUTCDate()).toBe(1);
        expect(startDate.getUTCMonth()).toBe(month);
        expect(endDate.getUTCDate()).toBe(1);
        expect(endDate.getUTCMonth()).toBe((month + 1) % 12);
      }
    });
  });

  describe('getPartitionsToDropByRetention', () => {
    it('should identify partitions older than retention period for dropping', () => {
      const referenceDate = new Date(Date.UTC(2024, 5, 15)); // June 2024
      const retentionMonths = 24; // Keep 2 years

      const partitions: PartitionInfo[] = [
        { name: 'audit_trail_y2022m01', startDate: new Date(Date.UTC(2022, 0, 1)), endDate: new Date(Date.UTC(2022, 1, 1)) },
        { name: 'audit_trail_y2022m05', startDate: new Date(Date.UTC(2022, 4, 1)), endDate: new Date(Date.UTC(2022, 5, 1)) },
        { name: 'audit_trail_y2022m06', startDate: new Date(Date.UTC(2022, 5, 1)), endDate: new Date(Date.UTC(2022, 6, 1)) },
        { name: 'audit_trail_y2023m01', startDate: new Date(Date.UTC(2023, 0, 1)), endDate: new Date(Date.UTC(2023, 1, 1)) },
        { name: 'audit_trail_y2024m05', startDate: new Date(Date.UTC(2024, 4, 1)), endDate: new Date(Date.UTC(2024, 5, 1)) },
      ];

      const toDrop = getPartitionsToDropByRetention(partitions, retentionMonths, referenceDate);

      // Cutoff: June 2024 - 24 months = June 2022
      // Partitions with endDate <= 2022-06-01 should be dropped
      expect(toDrop.map((p) => p.name)).toEqual([
        'audit_trail_y2022m01',
        'audit_trail_y2022m05',
      ]);
    });

    it('should return empty array when no partitions are older than retention', () => {
      const referenceDate = new Date(Date.UTC(2024, 5, 15)); // June 2024
      const retentionMonths = 24;

      const partitions: PartitionInfo[] = [
        { name: 'audit_trail_y2023m01', startDate: new Date(Date.UTC(2023, 0, 1)), endDate: new Date(Date.UTC(2023, 1, 1)) },
        { name: 'audit_trail_y2024m05', startDate: new Date(Date.UTC(2024, 4, 1)), endDate: new Date(Date.UTC(2024, 5, 1)) },
      ];

      const toDrop = getPartitionsToDropByRetention(partitions, retentionMonths, referenceDate);
      expect(toDrop).toEqual([]);
    });

    it('should drop all partitions when retention is 0', () => {
      const referenceDate = new Date(Date.UTC(2024, 5, 15)); // June 2024
      const retentionMonths = 0;

      const partitions: PartitionInfo[] = [
        { name: 'audit_trail_y2024m04', startDate: new Date(Date.UTC(2024, 3, 1)), endDate: new Date(Date.UTC(2024, 4, 1)) },
        { name: 'audit_trail_y2024m05', startDate: new Date(Date.UTC(2024, 4, 1)), endDate: new Date(Date.UTC(2024, 5, 1)) },
      ];

      const toDrop = getPartitionsToDropByRetention(partitions, retentionMonths, referenceDate);
      // Cutoff: June 2024 - 0 months = June 2024
      // Partitions with endDate <= 2024-06-01 should be dropped
      expect(toDrop.map((p) => p.name)).toEqual([
        'audit_trail_y2024m04',
        'audit_trail_y2024m05',
      ]);
    });

    it('should handle retention of 12 months correctly', () => {
      const referenceDate = new Date(Date.UTC(2024, 11, 1)); // December 2024
      const retentionMonths = 12;

      const partitions: PartitionInfo[] = [
        { name: 'audit_trail_y2023m10', startDate: new Date(Date.UTC(2023, 9, 1)), endDate: new Date(Date.UTC(2023, 10, 1)) },
        { name: 'audit_trail_y2023m11', startDate: new Date(Date.UTC(2023, 10, 1)), endDate: new Date(Date.UTC(2023, 11, 1)) },
        { name: 'audit_trail_y2023m12', startDate: new Date(Date.UTC(2023, 11, 1)), endDate: new Date(Date.UTC(2024, 0, 1)) },
        { name: 'audit_trail_y2024m01', startDate: new Date(Date.UTC(2024, 0, 1)), endDate: new Date(Date.UTC(2024, 1, 1)) },
      ];

      const toDrop = getPartitionsToDropByRetention(partitions, retentionMonths, referenceDate);
      // Cutoff: Dec 2024 - 12 months = Dec 2023
      // Partitions with endDate <= 2023-12-01 should be dropped
      expect(toDrop.map((p) => p.name)).toEqual([
        'audit_trail_y2023m10',
        'audit_trail_y2023m11',
      ]);
    });

    it('should not drop the partition at the exact cutoff boundary', () => {
      const referenceDate = new Date(Date.UTC(2024, 5, 1)); // June 2024
      const retentionMonths = 6;

      const partitions: PartitionInfo[] = [
        // Cutoff: June 2024 - 6 months = December 2023
        // This partition ends exactly at the cutoff (endDate = 2023-12-01)
        { name: 'audit_trail_y2023m11', startDate: new Date(Date.UTC(2023, 10, 1)), endDate: new Date(Date.UTC(2023, 11, 1)) },
        // This partition ends after the cutoff
        { name: 'audit_trail_y2023m12', startDate: new Date(Date.UTC(2023, 11, 1)), endDate: new Date(Date.UTC(2024, 0, 1)) },
      ];

      const toDrop = getPartitionsToDropByRetention(partitions, retentionMonths, referenceDate);
      // Only audit_trail_y2023m11 has endDate (2023-12-01) <= cutoff (2023-12-01)
      expect(toDrop.map((p) => p.name)).toEqual(['audit_trail_y2023m11']);
    });
  });

  describe('parsePartitionName', () => {
    it('should parse a valid partition name', () => {
      const date = parsePartitionName('audit_trail_y2024m03');
      expect(date).not.toBeNull();
      expect(date!.getUTCFullYear()).toBe(2024);
      expect(date!.getUTCMonth()).toBe(2); // March (0-indexed)
    });

    it('should return null for invalid partition names', () => {
      expect(parsePartitionName('invalid_name')).toBeNull();
      expect(parsePartitionName('audit_trail_2024m03')).toBeNull();
      expect(parsePartitionName('audit_trail_y2024')).toBeNull();
      expect(parsePartitionName('')).toBeNull();
    });

    it('should parse all months correctly', () => {
      for (let month = 1; month <= 12; month++) {
        const name = `audit_trail_y2024m${String(month).padStart(2, '0')}`;
        const date = parsePartitionName(name);
        expect(date).not.toBeNull();
        expect(date!.getUTCMonth()).toBe(month - 1);
      }
    });
  });
});

// @vitest-environment node
import { describe, it, expect, beforeEach, vi, afterEach } from 'vitest';
import { PermissionCache } from '../PermissionCache';

describe('PermissionCache', () => {
  let cache: PermissionCache;

  beforeEach(() => {
    cache = new PermissionCache(1000, 5);
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  describe('get/set', () => {
    it('should return undefined for a cache miss', () => {
      expect(cache.get('perm_user1_Analytics_View')).toBeUndefined();
    });

    it('should store and retrieve a true value', () => {
      cache.set('perm_user1_Analytics_View', true);
      expect(cache.get('perm_user1_Analytics_View')).toBe(true);
    });

    it('should store and retrieve a false value', () => {
      cache.set('perm_user1_Policies_Delete', false);
      expect(cache.get('perm_user1_Policies_Delete')).toBe(false);
    });

    it('should update an existing entry', () => {
      cache.set('perm_user1_Analytics_View', true);
      cache.set('perm_user1_Analytics_View', false);
      expect(cache.get('perm_user1_Analytics_View')).toBe(false);
    });

    it('should return undefined for expired entries', () => {
      cache.set('perm_user1_Analytics_View', true);

      // Advance time past TTL (5 minutes)
      vi.advanceTimersByTime(5 * 60 * 1000 + 1);

      expect(cache.get('perm_user1_Analytics_View')).toBeUndefined();
    });

    it('should return value for non-expired entries', () => {
      cache.set('perm_user1_Analytics_View', true);

      // Advance time but stay within TTL
      vi.advanceTimersByTime(4 * 60 * 1000);

      expect(cache.get('perm_user1_Analytics_View')).toBe(true);
    });
  });

  describe('LRU eviction', () => {
    it('should evict least recently used entry when at capacity', () => {
      const smallCache = new PermissionCache(3, 5);

      smallCache.set('perm_u1_M1_View', true);
      smallCache.set('perm_u1_M2_View', true);
      smallCache.set('perm_u1_M3_View', true);

      // Cache is full, adding a new entry should evict the LRU (M1)
      smallCache.set('perm_u1_M4_View', true);

      expect(smallCache.get('perm_u1_M1_View')).toBeUndefined();
      expect(smallCache.get('perm_u1_M2_View')).toBe(true);
      expect(smallCache.get('perm_u1_M3_View')).toBe(true);
      expect(smallCache.get('perm_u1_M4_View')).toBe(true);
    });

    it('should not evict recently accessed entries', () => {
      const smallCache = new PermissionCache(3, 5);

      smallCache.set('perm_u1_M1_View', true);
      smallCache.set('perm_u1_M2_View', true);
      smallCache.set('perm_u1_M3_View', true);

      // Access M1 to make it most recently used
      smallCache.get('perm_u1_M1_View');

      // Adding new entry should evict M2 (now the LRU)
      smallCache.set('perm_u1_M4_View', true);

      expect(smallCache.get('perm_u1_M1_View')).toBe(true);
      expect(smallCache.get('perm_u1_M2_View')).toBeUndefined();
      expect(smallCache.get('perm_u1_M3_View')).toBe(true);
      expect(smallCache.get('perm_u1_M4_View')).toBe(true);
    });

    it('should enforce max 1000 entries with default config', () => {
      const defaultCache = new PermissionCache();

      for (let i = 0; i < 1001; i++) {
        defaultCache.set(`perm_user_Module${i}_View`, true);
      }

      expect(defaultCache.size).toBe(1000);
      // First entry should have been evicted
      expect(defaultCache.get('perm_user_Module0_View')).toBeUndefined();
      // Last entry should exist
      expect(defaultCache.get('perm_user_Module1000_View')).toBe(true);
    });

    it('should update LRU order when set is called on existing key', () => {
      const smallCache = new PermissionCache(3, 5);

      smallCache.set('perm_u1_M1_View', true);
      smallCache.set('perm_u1_M2_View', true);
      smallCache.set('perm_u1_M3_View', true);

      // Update M1 to make it most recently used
      smallCache.set('perm_u1_M1_View', false);

      // Adding new entry should evict M2 (now the LRU)
      smallCache.set('perm_u1_M4_View', true);

      expect(smallCache.get('perm_u1_M1_View')).toBe(false);
      expect(smallCache.get('perm_u1_M2_View')).toBeUndefined();
    });
  });

  describe('invalidateUser', () => {
    it('should remove all entries for a specific user', () => {
      cache.set('perm_user1_Analytics_View', true);
      cache.set('perm_user1_Policies_Create', true);
      cache.set('perm_user1_Policies_Edit', false);
      cache.set('perm_user2_Analytics_View', true);

      cache.invalidateUser('user1');

      expect(cache.get('perm_user1_Analytics_View')).toBeUndefined();
      expect(cache.get('perm_user1_Policies_Create')).toBeUndefined();
      expect(cache.get('perm_user1_Policies_Edit')).toBeUndefined();
      expect(cache.get('perm_user2_Analytics_View')).toBe(true);
    });

    it('should not affect entries for other users', () => {
      cache.set('perm_user1_Analytics_View', true);
      cache.set('perm_user2_Analytics_View', true);
      cache.set('perm_user3_Analytics_View', true);

      cache.invalidateUser('user2');

      expect(cache.get('perm_user1_Analytics_View')).toBe(true);
      expect(cache.get('perm_user2_Analytics_View')).toBeUndefined();
      expect(cache.get('perm_user3_Analytics_View')).toBe(true);
    });

    it('should handle invalidating a user with no entries', () => {
      cache.set('perm_user1_Analytics_View', true);

      // Should not throw
      cache.invalidateUser('nonexistent');

      expect(cache.get('perm_user1_Analytics_View')).toBe(true);
    });
  });

  describe('invalidateAll', () => {
    it('should remove all permission entries', () => {
      cache.set('perm_user1_Analytics_View', true);
      cache.set('perm_user2_Policies_Create', false);
      cache.set('perm_user3_AuditPlans_Edit', true);

      cache.invalidateAll();

      expect(cache.get('perm_user1_Analytics_View')).toBeUndefined();
      expect(cache.get('perm_user2_Policies_Create')).toBeUndefined();
      expect(cache.get('perm_user3_AuditPlans_Edit')).toBeUndefined();
      expect(cache.size).toBe(0);
    });
  });

  describe('graceful error handling', () => {
    it('get should return undefined and not throw on internal error', () => {
      // Corrupt internal state to trigger error
      const brokenCache = new PermissionCache();
      (brokenCache as any).store = { get: () => { throw new Error('Simulated failure'); } };

      const consoleSpy = vi.spyOn(console, 'warn').mockImplementation(() => {});
      const result = brokenCache.get('perm_user1_Analytics_View');

      expect(result).toBeUndefined();
      expect(consoleSpy).toHaveBeenCalled();
      consoleSpy.mockRestore();
    });

    it('set should not throw on internal error', () => {
      const brokenCache = new PermissionCache();
      (brokenCache as any).store = { has: () => { throw new Error('Simulated failure'); } };

      const consoleSpy = vi.spyOn(console, 'warn').mockImplementation(() => {});

      expect(() => brokenCache.set('perm_user1_Analytics_View', true)).not.toThrow();
      expect(consoleSpy).toHaveBeenCalled();
      consoleSpy.mockRestore();
    });

    it('invalidateUser should not throw on internal error', () => {
      const brokenCache = new PermissionCache();
      (brokenCache as any).store = { keys: () => { throw new Error('Simulated failure'); } };

      const consoleSpy = vi.spyOn(console, 'warn').mockImplementation(() => {});

      expect(() => brokenCache.invalidateUser('user1')).not.toThrow();
      expect(consoleSpy).toHaveBeenCalled();
      consoleSpy.mockRestore();
    });

    it('invalidateAll should not throw on internal error', () => {
      const brokenCache = new PermissionCache();
      (brokenCache as any).store = { keys: () => { throw new Error('Simulated failure'); } };

      const consoleSpy = vi.spyOn(console, 'warn').mockImplementation(() => {});

      expect(() => brokenCache.invalidateAll()).not.toThrow();
      expect(consoleSpy).toHaveBeenCalled();
      consoleSpy.mockRestore();
    });
  });

  describe('size', () => {
    it('should report correct size', () => {
      expect(cache.size).toBe(0);

      cache.set('perm_user1_M1_View', true);
      expect(cache.size).toBe(1);

      cache.set('perm_user1_M2_View', false);
      expect(cache.size).toBe(2);

      cache.invalidateUser('user1');
      expect(cache.size).toBe(0);
    });
  });

  describe('TTL behavior', () => {
    it('should refresh TTL when entry is updated via set', () => {
      cache.set('perm_user1_Analytics_View', true);

      // Advance 4 minutes
      vi.advanceTimersByTime(4 * 60 * 1000);

      // Update the entry (refreshes TTL)
      cache.set('perm_user1_Analytics_View', true);

      // Advance another 4 minutes (total 8 from first set, 4 from update)
      vi.advanceTimersByTime(4 * 60 * 1000);

      // Should still be valid since TTL was refreshed
      expect(cache.get('perm_user1_Analytics_View')).toBe(true);
    });

    it('should expire exactly at TTL boundary', () => {
      cache.set('perm_user1_Analytics_View', true);

      // Advance exactly to TTL
      vi.advanceTimersByTime(5 * 60 * 1000);

      // At exactly TTL, entry should still be valid (expiresAt = now + ttl, check is > not >=)
      expect(cache.get('perm_user1_Analytics_View')).toBe(true);

      // One ms past TTL
      vi.advanceTimersByTime(1);
      expect(cache.get('perm_user1_Analytics_View')).toBeUndefined();
    });
  });
});

// @vitest-environment node
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import fc from 'fast-check';

/**
 * Property Tests for PermissionService
 *
 * Property 5: Admin Supremacy
 * Property 6: Permission Resolution with Override Precedence
 *
 * **Validates: Requirements 4.2, 4.3, 4.4, 4.5**
 */

// ─── Mocks ───────────────────────────────────────────────────────────────────

// Mock the database module
vi.mock('../../db/index', () => {
  const prepareMock = vi.fn();
  return {
    db: { prepare: prepareMock },
    default: { prepare: prepareMock },
  };
});

// Mock the PermissionCache module
vi.mock('../PermissionCache', () => {
  const getMock = vi.fn().mockReturnValue(undefined);
  const setMock = vi.fn();
  const invalidateUserMock = vi.fn();
  const invalidateAllMock = vi.fn();
  return {
    permissionCache: {
      get: getMock,
      set: setMock,
      invalidateUser: invalidateUserMock,
      invalidateAll: invalidateAllMock,
    },
  };
});

// Mock the ModuleRegistry
vi.mock('../../../permissions/registry', () => {
  const getModuleMock = vi.fn();
  const getAllModulesMock = vi.fn().mockReturnValue([]);
  const getModuleNamesMock = vi.fn().mockReturnValue([]);
  return {
    ModuleRegistry: {
      getModule: getModuleMock,
      getAllModules: getAllModulesMock,
      getModuleNames: getModuleNamesMock,
    },
  };
});

import { PermissionService } from '../PermissionService';
import { db } from '../../db/index';
import { permissionCache } from '../PermissionCache';
import { ModuleRegistry } from '../../../permissions/registry';
import { UserRole } from '../../../constants';

// ─── Custom Arbitraries ──────────────────────────────────────────────────────

/** Generates a valid UUID */
const userIdArb = fc.uuid();

/** Generates a valid module name (PascalCase) */
const moduleNameArb = fc.constantFrom(
  'Dashboard',
  'AuditCharter',
  'AuditPlans',
  'AuditFindings',
  'Policies',
  'RiskRegister',
  'Analytics',
  'Compliance',
  'Correspondence',
  'Fraud',
  'Integrity',
  'Recommendations',
  'Regulatory',
  'UserManagement',
  'Settings'
);

/** Generates a valid permission action */
const actionArb = fc.constantFrom('View', 'Create', 'Edit', 'Delete', 'Approve');

/** Generates a non-Admin role */
const nonAdminRoleArb = fc.constantFrom(
  UserRole.INTERNAL_AUDITOR,
  UserRole.COMPLIANCE_OFFICER,
  UserRole.RISK_OFFICER,
  UserRole.MANAGER,
  UserRole.VIEWER
);

/** Generates a role ID (UUID) */
const roleIdArb = fc.uuid();

// ─── Helper Functions ────────────────────────────────────────────────────────

/**
 * Sets up the DB mock to return a user with the given role and role_id.
 */
function setupUserMock(userId: string, role: string, roleId: string) {
  (db.prepare as ReturnType<typeof vi.fn>).mockImplementation((sql: string) => {
    if (sql.includes('SELECT id, role, role_id FROM users')) {
      return { get: vi.fn().mockResolvedValue({ id: userId, role, role_id: roleId }) };
    }
    // Default: return empty for other queries
    return { get: vi.fn().mockResolvedValue(undefined), all: vi.fn().mockResolvedValue([]) };
  });
}

/**
 * Sets up the DB mock for a full permission resolution scenario.
 */
function setupPermissionResolutionMock(config: {
  userId: string;
  role: string;
  roleId: string;
  userOverride?: { is_allowed: number } | undefined;
  rolePermissionExists: boolean;
}) {
  (db.prepare as ReturnType<typeof vi.fn>).mockImplementation((sql: string) => {
    // User lookup
    if (sql.includes('SELECT id, role, role_id FROM users')) {
      return {
        get: vi.fn().mockResolvedValue({
          id: config.userId,
          role: config.role,
          role_id: config.roleId,
        }),
      };
    }
    // User override check
    if (sql.includes('user_permissions') && sql.includes('is_allowed')) {
      return {
        get: vi.fn().mockResolvedValue(config.userOverride),
      };
    }
    // Role permission check
    if (sql.includes('role_permissions') && sql.includes('permissions')) {
      return {
        get: vi.fn().mockResolvedValue(config.rolePermissionExists ? { '1': 1 } : undefined),
      };
    }
    // Default fallback
    return { get: vi.fn().mockResolvedValue(undefined), all: vi.fn().mockResolvedValue([]) };
  });
}

// ─── Tests ───────────────────────────────────────────────────────────────────

describe('Property 5: Admin Supremacy', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    // Always return undefined from cache to force resolution logic
    (permissionCache.get as ReturnType<typeof vi.fn>).mockReturnValue(undefined);
  });

  it('for any module M registered in the registry and any action A, if user has Admin role, hasPermission returns true', async () => {
    await fc.assert(
      fc.asyncProperty(
        userIdArb,
        moduleNameArb,
        actionArb,
        roleIdArb,
        async (userId, module, action, roleId) => {
          vi.clearAllMocks();
          (permissionCache.get as ReturnType<typeof vi.fn>).mockReturnValue(undefined);

          // Setup: user has Admin role
          setupUserMock(userId, UserRole.ADMIN, roleId);

          // Setup: module is registered with the given action
          (ModuleRegistry.getModule as ReturnType<typeof vi.fn>).mockReturnValue({
            name: module,
            actions: ['View', 'Create', 'Edit', 'Delete', 'Approve'],
            label: { en: module, ar: module },
            defaults: {},
          });

          const result = await PermissionService.hasPermission(userId, module, action);

          // Admin always gets true
          expect(result).toBe(true);
        }
      ),
      { numRuns: 100 }
    );
  }, 30000);

  it('Admin supremacy holds regardless of whether role_permissions or user_permissions exist', async () => {
    await fc.assert(
      fc.asyncProperty(
        userIdArb,
        moduleNameArb,
        actionArb,
        roleIdArb,
        fc.boolean(), // whether role permission exists
        fc.option(fc.constantFrom(0, 1), { nil: undefined }), // user override
        async (userId, module, action, roleId, _rolePermExists, _userOverride) => {
          vi.clearAllMocks();
          (permissionCache.get as ReturnType<typeof vi.fn>).mockReturnValue(undefined);

          // Setup: user has Admin role - DB state shouldn't matter
          setupUserMock(userId, UserRole.ADMIN, roleId);

          // Setup: module is registered
          (ModuleRegistry.getModule as ReturnType<typeof vi.fn>).mockReturnValue({
            name: module,
            actions: ['View', 'Create', 'Edit', 'Delete', 'Approve'],
            label: { en: module, ar: module },
            defaults: {},
          });

          const result = await PermissionService.hasPermission(userId, module, action);

          // Admin always gets true regardless of DB state
          expect(result).toBe(true);
        }
      ),
      { numRuns: 100 }
    );
  }, 30000);
});

describe('Property 6: Permission Resolution with Override Precedence', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    // Always return undefined from cache to force resolution logic
    (permissionCache.get as ReturnType<typeof vi.fn>).mockReturnValue(undefined);
  });

  it('if user_permissions has (U, M, A, is_allowed=true), hasPermission returns true regardless of role_permissions', async () => {
    await fc.assert(
      fc.asyncProperty(
        userIdArb,
        moduleNameArb,
        actionArb,
        nonAdminRoleArb,
        roleIdArb,
        fc.boolean(), // whether role permission exists (should not matter)
        async (userId, module, action, role, roleId, rolePermExists) => {
          vi.clearAllMocks();
          (permissionCache.get as ReturnType<typeof vi.fn>).mockReturnValue(undefined);

          // Setup: module is registered with the given action
          (ModuleRegistry.getModule as ReturnType<typeof vi.fn>).mockReturnValue({
            name: module,
            actions: ['View', 'Create', 'Edit', 'Delete', 'Approve'],
            label: { en: module, ar: module },
            defaults: {},
          });

          // Setup: user has non-Admin role with user override granting permission
          setupPermissionResolutionMock({
            userId,
            role,
            roleId,
            userOverride: { is_allowed: 1 }, // User override grants
            rolePermissionExists: rolePermExists, // Doesn't matter
          });

          const result = await PermissionService.hasPermission(userId, module, action);

          // User override with is_allowed=true always grants
          expect(result).toBe(true);
        }
      ),
      { numRuns: 100 }
    );
  }, 30000);

  it('if user_permissions has (U, M, A, is_allowed=false), hasPermission returns false regardless of role_permissions', async () => {
    await fc.assert(
      fc.asyncProperty(
        userIdArb,
        moduleNameArb,
        actionArb,
        nonAdminRoleArb,
        roleIdArb,
        fc.boolean(), // whether role permission exists (should not matter)
        async (userId, module, action, role, roleId, rolePermExists) => {
          vi.clearAllMocks();
          (permissionCache.get as ReturnType<typeof vi.fn>).mockReturnValue(undefined);

          // Setup: module is registered with the given action
          (ModuleRegistry.getModule as ReturnType<typeof vi.fn>).mockReturnValue({
            name: module,
            actions: ['View', 'Create', 'Edit', 'Delete', 'Approve'],
            label: { en: module, ar: module },
            defaults: {},
          });

          // Setup: user has non-Admin role with user override denying permission
          setupPermissionResolutionMock({
            userId,
            role,
            roleId,
            userOverride: { is_allowed: 0 }, // User override denies
            rolePermissionExists: rolePermExists, // Doesn't matter
          });

          const result = await PermissionService.hasPermission(userId, module, action);

          // User override with is_allowed=false always denies
          expect(result).toBe(false);
        }
      ),
      { numRuns: 100 }
    );
  }, 30000);

  it('if no user override exists, hasPermission returns the role_permissions result', async () => {
    await fc.assert(
      fc.asyncProperty(
        userIdArb,
        moduleNameArb,
        actionArb,
        nonAdminRoleArb,
        roleIdArb,
        fc.boolean(), // whether role permission exists
        async (userId, module, action, role, roleId, rolePermExists) => {
          vi.clearAllMocks();
          (permissionCache.get as ReturnType<typeof vi.fn>).mockReturnValue(undefined);

          // Setup: module is registered with the given action
          (ModuleRegistry.getModule as ReturnType<typeof vi.fn>).mockReturnValue({
            name: module,
            actions: ['View', 'Create', 'Edit', 'Delete', 'Approve'],
            label: { en: module, ar: module },
            defaults: {},
          });

          // Setup: user has non-Admin role with NO user override
          setupPermissionResolutionMock({
            userId,
            role,
            roleId,
            userOverride: undefined, // No override
            rolePermissionExists: rolePermExists,
          });

          const result = await PermissionService.hasPermission(userId, module, action);

          // Without override, result matches role permission
          expect(result).toBe(rolePermExists);
        }
      ),
      { numRuns: 100 }
    );
  }, 30000);

  it('override precedence is consistent: grant override > role deny, deny override > role grant', async () => {
    await fc.assert(
      fc.asyncProperty(
        userIdArb,
        moduleNameArb,
        actionArb,
        nonAdminRoleArb,
        roleIdArb,
        async (userId, module, action, role, roleId) => {
          vi.clearAllMocks();
          (permissionCache.get as ReturnType<typeof vi.fn>).mockReturnValue(undefined);

          // Setup: module is registered
          (ModuleRegistry.getModule as ReturnType<typeof vi.fn>).mockReturnValue({
            name: module,
            actions: ['View', 'Create', 'Edit', 'Delete', 'Approve'],
            label: { en: module, ar: module },
            defaults: {},
          });

          // Case 1: Grant override overrides role denial
          setupPermissionResolutionMock({
            userId,
            role,
            roleId,
            userOverride: { is_allowed: 1 },
            rolePermissionExists: false, // Role denies
          });

          const grantOverrideDeny = await PermissionService.hasPermission(userId, module, action);
          expect(grantOverrideDeny).toBe(true);

          // Case 2: Deny override overrides role grant
          vi.clearAllMocks();
          (permissionCache.get as ReturnType<typeof vi.fn>).mockReturnValue(undefined);
          (ModuleRegistry.getModule as ReturnType<typeof vi.fn>).mockReturnValue({
            name: module,
            actions: ['View', 'Create', 'Edit', 'Delete', 'Approve'],
            label: { en: module, ar: module },
            defaults: {},
          });

          setupPermissionResolutionMock({
            userId,
            role,
            roleId,
            userOverride: { is_allowed: 0 },
            rolePermissionExists: true, // Role grants
          });

          const denyOverrideGrant = await PermissionService.hasPermission(userId, module, action);
          expect(denyOverrideGrant).toBe(false);
        }
      ),
      { numRuns: 50 }
    );
  }, 30000);
});

