    await new Promise((r) => setTimeout(r, 10));

    expect(mockWorkerManager.shutdown).not.toHaveBeenCalled();
    expect(mockQueueService.close).not.toHaveBeenCalled();
  });

  it('continues shutdown if certificate manager throws', async () => {
