};

const BUCKETS_WITH_LIMITS: Array<{ bucket: BucketName; maxSize: number }> = [
  { bucket: 'evidence', maxSize: BUCKET_MAX_SIZE.evidence },
  { bucket: 'reports', maxSize: BUCKET_MAX_SIZE.reports },
];

/**
 * Creates a Buffer with a faked `length` property to simulate large files
 * without actually allocating huge amounts of memory. The validation logic
 * only reads `buffer.length` for size checks, and passes the buffer to
 * magika's identifyBytes (which we mock).
 */
function createFakeBuffer(reportedSize: number): Buffer {
  const small = Buffer.alloc(16, 'x');
  Object.defineProperty(small, 'length', { value: reportedSize, writable: false });
  return small;
}

// ─── Arbitraries ─────────────────────────────────────────────────────────────

/** Arbitrary for buckets under test (evidence/reports have distinct size limits) */
const arbBucket = fc.constantFrom<BucketName>('evidence', 'reports');

/** Arbitrary for allowed MIME types */
const arbAllowedMime = fc.constantFrom(...(ALLOWED_MIME_TYPES as unknown as string[]));

/** Arbitrary for disallowed MIME types / magika labels */
const arbDisallowedLabel = fc.constantFrom(
  'elf',
  'html',
  'javascript',
  'python',
  'shell',
  'xml',
  'csv',
  'mp3',
  'mp4',
  'avi'
);

// ─── Property Tests ──────────────────────────────────────────────────────────

describe('Property 2: File Validation Correctness', () => {
  beforeEach(async () => {
    _resetMagikaForTesting();
    const mockFn = await getMockIdentifyBytes();
    mockFn.mockReset();
  });

  it('valid files (size ≤ max AND filename ≤ 255 chars AND allowed MIME) are accepted', async () => {
    const mockFn = await getMockIdentifyBytes();

    await fc.assert(
      fc.asyncProperty(
        arbBucket,
        arbAllowedMime,
        fc.integer({ min: 1, max: 1024 }), // valid sizes
        fc.integer({ min: 1, max: 200 }), // filename base length (well under 255)
        async (bucket, mime, size, nameLen) => {
          const label = MIME_TO_LABEL[mime];
          const extension = MIME_TO_EXTENSION[mime];

          // Configure magika to return the expected label
          mockFn.mockResolvedValue({
            prediction: { output: { label }, score: 0.99 },
          });

          // Generate a valid filename (short, no traversal)
          const filename = 'f'.repeat(nameLen) + extension;

          const input: FileValidationInput = {
            buffer: Buffer.alloc(size, 'x'),
            filename,
            declaredContentType: mime,
            bucket,
          };

          const result = await validateFile(input);

          expect(result.valid).toBe(true);
          expect(result.errors).toHaveLength(0);
          expect(result.detectedMimeType).not.toBeNull();
        }
      ),
      { numRuns: 100 }
    );
  });

  it('files with MIME type not in allowed list are rejected', async () => {
    const mockFn = await getMockIdentifyBytes();

    await fc.assert(
      fc.asyncProperty(
        arbBucket,
        arbDisallowedLabel,
        fc.integer({ min: 1, max: 512 }),
        async (bucket, label, size) => {
          // Configure magika to return a disallowed type
          mockFn.mockResolvedValue({
            prediction: { output: { label }, score: 0.99 },
          });

          const input: FileValidationInput = {
            buffer: Buffer.alloc(size, 'x'),
            filename: 'document.pdf', // valid filename
            declaredContentType: 'application/pdf',
            bucket,
          };

          const result = await validateFile(input);

          expect(result.valid).toBe(false);
          const errorCodes = result.errors.map((e) => e.code);
          expect(
            errorCodes.includes('MIME_NOT_ALLOWED') ||
              errorCodes.includes('MIME_EXTENSION_MISMATCH')
          ).toBe(true);
        }
      ),
      { numRuns: 100 }
    );
  });

  it('files exceeding per-bucket max size are rejected', async () => {
    const mockFn = await getMockIdentifyBytes();

    await fc.assert(
      fc.asyncProperty(
        fc.constantFrom(...BUCKETS_WITH_LIMITS),
        arbAllowedMime,
        fc.integer({ min: 1, max: 10 * 1024 * 1024 }), // offset above max (1B–10MB over)
        async ({ bucket, maxSize }, mime, offset) => {
          const label = MIME_TO_LABEL[mime];
          const extension = MIME_TO_EXTENSION[mime];

          mockFn.mockResolvedValue({
            prediction: { output: { label }, score: 0.99 },
          });

          const overSize = maxSize + offset;
          const filename = `oversize-file${extension}`;

          // Use fake buffer to avoid allocating 50–110MB per test run
          const input: FileValidationInput = {
            buffer: createFakeBuffer(overSize),
            filename,
            declaredContentType: mime,
            bucket,
          };

          const result = await validateFile(input);

          expect(result.valid).toBe(false);
          const errorCodes = result.errors.map((e) => e.code);
          expect(errorCodes).toContain('FILE_TOO_LARGE');
        }
      ),
      { numRuns: 100 }
    );
  });

  it('files with filename exceeding 255 characters are rejected', async () => {
    const mockFn = await getMockIdentifyBytes();

    await fc.assert(
      fc.asyncProperty(
        arbBucket,
        arbAllowedMime,
        fc.integer({ min: 256, max: 500 }), // total filename lengths > 255
        async (bucket, mime, filenameLen) => {
          const label = MIME_TO_LABEL[mime];
          const extension = MIME_TO_EXTENSION[mime];

          mockFn.mockResolvedValue({
            prediction: { output: { label }, score: 0.99 },
          });

          // Build a filename that exceeds 255 chars total
          // Ensure the total including extension exceeds 255
          const baseLen = filenameLen;
          const filename = 'a'.repeat(baseLen) + extension;

          // Double-check it actually exceeds 255
          if (filename.length <= MAX_FILENAME_LENGTH) return;

          const input: FileValidationInput = {
            buffer: Buffer.alloc(10, 'x'), // valid small file
            filename,
            declaredContentType: mime,
            bucket,
          };

          const result = await validateFile(input);

          expect(result.valid).toBe(false);
          const errorCodes = result.errors.map((e) => e.code);
          expect(errorCodes).toContain('FILENAME_TOO_LONG');
        }
      ),
      { numRuns: 100 }
    );
  });

  it('files violating multiple constraints are rejected with all relevant errors', async () => {
    const mockFn = await getMockIdentifyBytes();

    await fc.assert(
      fc.asyncProperty(
        fc.constantFrom(...BUCKETS_WITH_LIMITS),
        arbDisallowedLabel,
        fc.integer({ min: 1, max: 1024 }), // offset for oversized
        fc.integer({ min: 256, max: 400 }), // long filename base length
        async ({ bucket, maxSize }, label, offset, nameBaseLen) => {
          // MIME not allowed
          mockFn.mockResolvedValue({
            prediction: { output: { label }, score: 0.99 },
          });

          // Filename too long (> 255 chars)
          const longFilename = 'x'.repeat(nameBaseLen) + '.pdf';
          if (longFilename.length <= MAX_FILENAME_LENGTH) return;

          // File too large (use fake buffer)
          const overSize = maxSize + offset;

          const input: FileValidationInput = {
            buffer: createFakeBuffer(overSize),
            filename: longFilename,
            declaredContentType: 'application/pdf',
            bucket,
          };

          const result = await validateFile(input);

          expect(result.valid).toBe(false);
          const errorCodes = result.errors.map((e) => e.code);
          // Should have size and filename errors at minimum
          expect(errorCodes).toContain('FILE_TOO_LARGE');
          expect(errorCodes).toContain('FILENAME_TOO_LONG');
        }
      ),
      { numRuns: 100 }
    );
  });

  it('boundary: files at exactly the bucket max size are accepted', async () => {
    const mockFn = await getMockIdentifyBytes();

    await fc.assert(
      fc.asyncProperty(
        fc.constantFrom(...BUCKETS_WITH_LIMITS),
        arbAllowedMime,
        async ({ bucket, maxSize }, mime) => {
          const label = MIME_TO_LABEL[mime];
          const extension = MIME_TO_EXTENSION[mime];

          mockFn.mockResolvedValue({
            prediction: { output: { label }, score: 0.99 },
          });

          const filename = `exact-limit${extension}`;

          // Use fake buffer at exactly maxSize
          const input: FileValidationInput = {
            buffer: createFakeBuffer(maxSize),
            filename,
            declaredContentType: mime,
            bucket,
          };

          const result = await validateFile(input);

          // Should not have FILE_TOO_LARGE error
          const errorCodes = result.errors.map((e) => e.code);
          expect(errorCodes).not.toContain('FILE_TOO_LARGE');
        }
      ),
      { numRuns: 100 }
    );
  });

  it('boundary: filenames at exactly 255 characters are accepted', async () => {
    const mockFn = await getMockIdentifyBytes();

    await fc.assert(
      fc.asyncProperty(
        arbBucket,
        arbAllowedMime,
        async (bucket, mime) => {
          const label = MIME_TO_LABEL[mime];
          const extension = MIME_TO_EXTENSION[mime];

          mockFn.mockResolvedValue({
            prediction: { output: { label }, score: 0.99 },
          });

          // Build a filename that is exactly 255 characters
          const baseLen = MAX_FILENAME_LENGTH - extension.length;
          const filename = 'a'.repeat(baseLen) + extension;

          const input: FileValidationInput = {
            buffer: Buffer.alloc(10, 'x'),
            filename,
            declaredContentType: mime,
            bucket,
          };

          const result = await validateFile(input);

          // Should not have FILENAME_TOO_LONG error
          const errorCodes = result.errors.map((e) => e.code);
          expect(errorCodes).not.toContain('FILENAME_TOO_LONG');
        }
      ),
      { numRuns: 100 }
    );
  });
});

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import {
  validateFile,
  containsPathTraversal,
  ALLOWED_MIME_TYPES,
  BUCKET_MAX_SIZE,
  MAX_FILENAME_LENGTH,
  _resetMagikaForTesting,
  type BucketName,
  type FileValidationInput,
} from '../file-validation';

// Mock magika module
vi.mock('magika', () => {
  const mockIdentifyBytes = vi.fn();
  return {
    Magika: {
      create: vi.fn().mockResolvedValue({
        identifyBytes: mockIdentifyBytes,
      }),
    },
    __mockIdentifyBytes: mockIdentifyBytes,
  };
});

// Get reference to the mock function
async function getMockIdentifyBytes() {
  const mod = await import('magika') as any;
  return mod.__mockIdentifyBytes;
}

function createInput(overrides: Partial<FileValidationInput> = {}): FileValidationInput {
  return {
    buffer: Buffer.from('fake file content'),
    filename: 'document.pdf',
    declaredContentType: 'application/pdf',
    bucket: 'evidence' as BucketName,
    ...overrides,
  };
}

describe('file-validation', () => {
  beforeEach(async () => {
    _resetMagikaForTesting();
    const mockFn = await getMockIdentifyBytes();
    mockFn.mockReset();
    // Default: magika detects PDF
    mockFn.mockResolvedValue({
      prediction: { output: { label: 'pdf' }, score: 0.99 },
    });
  });

  describe('validateFile', () => {
    describe('file size validation', () => {
      it('rejects empty files (0 bytes)', async () => {
        const result = await validateFile(createInput({ buffer: Buffer.alloc(0) }));
        expect(result.valid).toBe(false);
        expect(result.errors).toContainEqual(
          expect.objectContaining({ code: 'FILE_EMPTY' })
        );
      });

      it('rejects files exceeding evidence bucket max (50MB)', async () => {
        const overSize = 50 * 1024 * 1024 + 1; // 50MB + 1 byte
        const result = await validateFile(
          createInput({ buffer: Buffer.alloc(overSize), bucket: 'evidence' })
        );
        expect(result.valid).toBe(false);
        expect(result.errors).toContainEqual(
          expect.objectContaining({ code: 'FILE_TOO_LARGE' })
        );
      });

      it('rejects files exceeding reports bucket max (100MB)', async () => {
        const overSize = 100 * 1024 * 1024 + 1; // 100MB + 1 byte
        const result = await validateFile(
          createInput({ buffer: Buffer.alloc(overSize), bucket: 'reports' })
        );
        expect(result.valid).toBe(false);
        expect(result.errors).toContainEqual(
          expect.objectContaining({ code: 'FILE_TOO_LARGE' })
        );
      });

      it('accepts files at exactly the bucket max', async () => {
        const exactSize = 50 * 1024 * 1024; // exactly 50MB
        const result = await validateFile(
          createInput({ buffer: Buffer.alloc(exactSize), bucket: 'evidence' })
        );
        // Should not have FILE_TOO_LARGE error
        expect(result.errors.find(e => e.code === 'FILE_TOO_LARGE')).toBeUndefined();
      });

      it('accepts files with valid size > 0', async () => {
        const result = await validateFile(createInput({ buffer: Buffer.from('valid') }));
        expect(result.errors.find(e => e.code === 'FILE_EMPTY')).toBeUndefined();
        expect(result.errors.find(e => e.code === 'FILE_TOO_LARGE')).toBeUndefined();
      });
    });

    describe('filename validation', () => {
      it('rejects filenames exceeding 255 characters', async () => {
        const longName = 'a'.repeat(252) + '.pdf'; // 256 chars total
        const result = await validateFile(createInput({ filename: longName }));
        expect(result.valid).toBe(false);
        expect(result.errors).toContainEqual(
          expect.objectContaining({ code: 'FILENAME_TOO_LONG' })
        );
      });

      it('accepts filenames at exactly 255 characters', async () => {
        const exactName = 'a'.repeat(251) + '.pdf'; // 255 chars
        const result = await validateFile(createInput({ filename: exactName }));
        expect(result.errors.find(e => e.code === 'FILENAME_TOO_LONG')).toBeUndefined();
      });

      it('rejects filenames with ../ path traversal', async () => {
        const result = await validateFile(createInput({ filename: '../etc/passwd.pdf' }));
        expect(result.valid).toBe(false);
        expect(result.errors).toContainEqual(
          expect.objectContaining({ code: 'FILENAME_PATH_TRAVERSAL' })
        );
      });

      it('rejects filenames with ..\\ path traversal', async () => {
        const result = await validateFile(createInput({ filename: '..\\windows\\system.pdf' }));
        expect(result.valid).toBe(false);
        expect(result.errors).toContainEqual(
          expect.objectContaining({ code: 'FILENAME_PATH_TRAVERSAL' })
        );
      });

      it('rejects filenames with // sequences', async () => {
        const result = await validateFile(createInput({ filename: 'path//to//file.pdf' }));
        expect(result.valid).toBe(false);
        expect(result.errors).toContainEqual(
          expect.objectContaining({ code: 'FILENAME_PATH_TRAVERSAL' })
        );
      });

      it('rejects filenames with null bytes', async () => {
        const result = await validateFile(createInput({ filename: 'file\0.pdf' }));
        expect(result.valid).toBe(false);
        expect(result.errors).toContainEqual(
          expect.objectContaining({ code: 'FILENAME_PATH_TRAVERSAL' })
        );
      });

      it('accepts normal filenames', async () => {
        const result = await validateFile(createInput({ filename: 'my-report_2024.pdf' }));
        expect(result.errors.find(e => e.code === 'FILENAME_TOO_LONG')).toBeUndefined();
        expect(result.errors.find(e => e.code === 'FILENAME_PATH_TRAVERSAL')).toBeUndefined();
      });
    });

    describe('MIME type detection and validation', () => {
      it('accepts a valid PDF file with matching extension', async () => {
        const result = await validateFile(createInput());
        expect(result.valid).toBe(true);
        expect(result.detectedMimeType).toBe('application/pdf');
        expect(result.errors).toHaveLength(0);
      });

      it('rejects when detected MIME is not in allowed list', async () => {
        const mockFn = await getMockIdentifyBytes();
        mockFn.mockResolvedValue({
          prediction: { output: { label: 'elf' }, score: 0.99 },
        });

        const result = await validateFile(createInput());
        expect(result.valid).toBe(false);
        expect(result.errors).toContainEqual(
          expect.objectContaining({ code: 'MIME_NOT_ALLOWED' })
        );
      });

      it('rejects when detected MIME does not match file extension', async () => {
        const mockFn = await getMockIdentifyBytes();
        // Detect as PNG, but filename says .pdf
        mockFn.mockResolvedValue({
          prediction: { output: { label: 'png' }, score: 0.99 },
        });

        const result = await validateFile(createInput({ filename: 'document.pdf' }));
        expect(result.valid).toBe(false);
        expect(result.errors).toContainEqual(
          expect.objectContaining({ code: 'MIME_EXTENSION_MISMATCH' })
        );
      });

      it('rejects when magika returns unknown label', async () => {
        const mockFn = await getMockIdentifyBytes();
        mockFn.mockResolvedValue({
          prediction: { output: { label: 'unknown' }, score: 0.1 },
        });

        const result = await validateFile(createInput());
        expect(result.valid).toBe(false);
        expect(result.errors).toContainEqual(
          expect.objectContaining({ code: 'MIME_DETECTION_FAILED' })
        );
      });

      it('rejects when magika returns empty label', async () => {
        const mockFn = await getMockIdentifyBytes();
        mockFn.mockResolvedValue({
          prediction: { output: { label: 'empty' }, score: 0.5 },
        });

        const result = await validateFile(createInput());
        expect(result.valid).toBe(false);
        expect(result.errors).toContainEqual(
          expect.objectContaining({ code: 'MIME_DETECTION_FAILED' })
        );
      });

      it('rejects when magika throws an error', async () => {
        const mockFn = await getMockIdentifyBytes();
        mockFn.mockRejectedValue(new Error('Magika internal error'));

        const result = await validateFile(createInput());
        expect(result.valid).toBe(false);
        expect(result.errors).toContainEqual(
          expect.objectContaining({ code: 'MIME_DETECTION_FAILED' })
        );
      });

      it('accepts docx files even when magika detects zip (zip-based format)', async () => {
        const mockFn = await getMockIdentifyBytes();
        mockFn.mockResolvedValue({
          prediction: { output: { label: 'zip' }, score: 0.95 },
        });

        const result = await validateFile(
          createInput({
            filename: 'report.docx',
            declaredContentType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
          })
        );
        expect(result.valid).toBe(true);
        expect(result.errors).toHaveLength(0);
      });

      it('accepts xlsx files even when magika detects zip (zip-based format)', async () => {
        const mockFn = await getMockIdentifyBytes();
        mockFn.mockResolvedValue({
          prediction: { output: { label: 'zip' }, score: 0.95 },
        });

        const result = await validateFile(
          createInput({
            filename: 'spreadsheet.xlsx',
            declaredContentType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
          })
        );
        expect(result.valid).toBe(true);
        expect(result.errors).toHaveLength(0);
      });

      it('accepts PNG image with matching extension', async () => {
        const mockFn = await getMockIdentifyBytes();
        mockFn.mockResolvedValue({
          prediction: { output: { label: 'png' }, score: 0.99 },
        });

        const result = await validateFile(
          createInput({
            filename: 'screenshot.png',
            declaredContentType: 'image/png',
          })
        );
        expect(result.valid).toBe(true);
      });

      it('accepts JPEG image with .jpg extension', async () => {
        const mockFn = await getMockIdentifyBytes();
        mockFn.mockResolvedValue({
          prediction: { output: { label: 'jpeg' }, score: 0.99 },
        });

        const result = await validateFile(
          createInput({
            filename: 'photo.jpg',
            declaredContentType: 'image/jpeg',
          })
        );
        expect(result.valid).toBe(true);
      });
    });

    describe('multiple errors', () => {
      it('reports multiple validation errors at once', async () => {
        const mockFn = await getMockIdentifyBytes();
        mockFn.mockResolvedValue({
          prediction: { output: { label: 'elf' }, score: 0.99 },
        });

        const longName = '../' + 'a'.repeat(255) + '.exe';
        const result = await validateFile(
          createInput({ filename: longName, buffer: Buffer.alloc(0) })
        );

        expect(result.valid).toBe(false);
        expect(result.errors.length).toBeGreaterThanOrEqual(2);
        // Should have both empty file and path traversal errors
        expect(result.errors).toContainEqual(
          expect.objectContaining({ code: 'FILE_EMPTY' })
        );
        expect(result.errors).toContainEqual(
          expect.objectContaining({ code: 'FILENAME_PATH_TRAVERSAL' })
        );
      });
    });
  });

  describe('containsPathTraversal', () => {
    it('detects ../ sequences', () => {
      expect(containsPathTraversal('../file.txt')).toBe(true);
      expect(containsPathTraversal('path/../file.txt')).toBe(true);
    });

    it('detects ..\\ sequences', () => {
      expect(containsPathTraversal('..\\file.txt')).toBe(true);
      expect(containsPathTraversal('path\\..\\file.txt')).toBe(true);
    });

    it('detects // sequences', () => {
      expect(containsPathTraversal('path//file.txt')).toBe(true);
    });

    it('detects null bytes', () => {
      expect(containsPathTraversal('file\0.txt')).toBe(true);
    });

    it('allows normal filenames', () => {
      expect(containsPathTraversal('normal-file.txt')).toBe(false);
      expect(containsPathTraversal('path.to.file.pdf')).toBe(false);
      expect(containsPathTraversal('file_name (1).docx')).toBe(false);
    });

    it('allows filenames with single dots', () => {
      expect(containsPathTraversal('file.name.ext')).toBe(false);
    });
  });
});

// @vitest-environment node
import { describe, it, expect } from 'vitest';
import {
  parsePaginationParams,
  computePaginationMeta,
  paginateQuery,
  DEFAULT_PAGE,
  DEFAULT_PAGE_SIZE,
  MAX_PAGE_SIZE,
} from '../paginationService';
import { ValidationError } from '../errors';

describe('paginationService', () => {
  // ─── parsePaginationParams ───────────────────────────────────────────────

  describe('parsePaginationParams', () => {
    describe('defaults', () => {
      it('returns default page=1, pageSize=20 when no params provided', () => {
        const result = parsePaginationParams({});
        expect(result.page).toBe(DEFAULT_PAGE);
        expect(result.pageSize).toBe(DEFAULT_PAGE_SIZE);
        expect(result.offset).toBe(0);
      });

      it('returns default page=1 when only pageSize is provided', () => {
        const result = parsePaginationParams({ pageSize: '10' });
        expect(result.page).toBe(1);
        expect(result.pageSize).toBe(10);
        expect(result.offset).toBe(0);
      });

      it('returns default pageSize=20 when only page is provided', () => {
        const result = parsePaginationParams({ page: '3' });
        expect(result.page).toBe(3);
        expect(result.pageSize).toBe(20);
        expect(result.offset).toBe(40);
      });

      it('treats empty string as not provided', () => {
        const result = parsePaginationParams({ page: '', pageSize: '' });
        expect(result.page).toBe(DEFAULT_PAGE);
        expect(result.pageSize).toBe(DEFAULT_PAGE_SIZE);
      });

      it('treats null as not provided', () => {
        const result = parsePaginationParams({ page: null, pageSize: null });
        expect(result.page).toBe(DEFAULT_PAGE);
        expect(result.pageSize).toBe(DEFAULT_PAGE_SIZE);
      });

      it('treats undefined as not provided', () => {
        const result = parsePaginationParams({ page: undefined, pageSize: undefined });
        expect(result.page).toBe(DEFAULT_PAGE);
        expect(result.pageSize).toBe(DEFAULT_PAGE_SIZE);
      });
    });

    describe('valid inputs', () => {
      it('parses valid page and pageSize as strings', () => {
        const result = parsePaginationParams({ page: '2', pageSize: '50' });
        expect(result.page).toBe(2);
        expect(result.pageSize).toBe(50);
        expect(result.offset).toBe(50);
      });

      it('parses valid page and pageSize as numbers', () => {
        const result = parsePaginationParams({ page: 5, pageSize: 25 });
        expect(result.page).toBe(5);
        expect(result.pageSize).toBe(25);
        expect(result.offset).toBe(100);
      });

      it('computes correct offset for page 1', () => {
        const result = parsePaginationParams({ page: '1', pageSize: '10' });
        expect(result.offset).toBe(0);
      });

      it('computes correct offset for page 3 with pageSize 15', () => {
        const result = parsePaginationParams({ page: '3', pageSize: '15' });
        expect(result.offset).toBe(30);
      });

      it('accepts pageSize of exactly 100', () => {
        const result = parsePaginationParams({ pageSize: '100' });
        expect(result.pageSize).toBe(100);
      });

      it('accepts page of 1 (minimum valid)', () => {
        const result = parsePaginationParams({ page: '1' });
        expect(result.page).toBe(1);
      });
    });

    describe('pageSize capping', () => {
      it('caps pageSize at 100 when value exceeds maximum', () => {
        const result = parsePaginationParams({ pageSize: '200' });
        expect(result.pageSize).toBe(MAX_PAGE_SIZE);
      });

      it('caps pageSize at 100 for very large values', () => {
        const result = parsePaginationParams({ pageSize: '999999' });
        expect(result.pageSize).toBe(MAX_PAGE_SIZE);
      });

      it('caps pageSize at 100 when provided as number', () => {
        const result = parsePaginationParams({ pageSize: 150 });
        expect(result.pageSize).toBe(MAX_PAGE_SIZE);
      });

      it('does not error when capping pageSize', () => {
        expect(() => parsePaginationParams({ pageSize: '500' })).not.toThrow();
      });
    });

    describe('invalid inputs - rejection with 400', () => {
      it('rejects non-numeric page', () => {
        expect(() => parsePaginationParams({ page: 'abc' })).toThrow(ValidationError);
        try {
          parsePaginationParams({ page: 'abc' });
        } catch (e: any) {
          expect(e.statusCode).toBe(400);
          expect(e.details.field).toBe('page');
        }
      });

      it('rejects non-numeric pageSize', () => {
        expect(() => parsePaginationParams({ pageSize: 'xyz' })).toThrow(ValidationError);
        try {
          parsePaginationParams({ pageSize: 'xyz' });
        } catch (e: any) {
          expect(e.statusCode).toBe(400);
          expect(e.details.field).toBe('pageSize');
        }
      });

      it('rejects page less than 1', () => {
        expect(() => parsePaginationParams({ page: '0' })).toThrow(ValidationError);
        expect(() => parsePaginationParams({ page: '-1' })).toThrow(ValidationError);
      });

      it('rejects pageSize less than 1', () => {
        expect(() => parsePaginationParams({ pageSize: '0' })).toThrow(ValidationError);
        expect(() => parsePaginationParams({ pageSize: '-5' })).toThrow(ValidationError);
      });

      it('rejects non-integer page (decimal)', () => {
        expect(() => parsePaginationParams({ page: '1.5' })).toThrow(ValidationError);
        expect(() => parsePaginationParams({ page: '2.7' })).toThrow(ValidationError);
      });

      it('rejects non-integer pageSize (decimal)', () => {
        expect(() => parsePaginationParams({ pageSize: '10.5' })).toThrow(ValidationError);
      });

      it('rejects special string values', () => {
        expect(() => parsePaginationParams({ page: 'NaN' })).toThrow(ValidationError);
        expect(() => parsePaginationParams({ page: 'Infinity' })).toThrow(ValidationError);
        expect(() => parsePaginationParams({ page: '-Infinity' })).toThrow(ValidationError);
      });

      it('rejects boolean-like strings', () => {
        expect(() => parsePaginationParams({ page: 'true' })).toThrow(ValidationError);
        expect(() => parsePaginationParams({ page: 'false' })).toThrow(ValidationError);
      });

      it('rejects strings with mixed content', () => {
        expect(() => parsePaginationParams({ page: '1abc' })).toThrow(ValidationError);
        expect(() => parsePaginationParams({ pageSize: '50px' })).toThrow(ValidationError);
      });
    });
  });

  // ─── computePaginationMeta ───────────────────────────────────────────────

  describe('computePaginationMeta', () => {
    it('computes correct metadata for standard case', () => {
      const meta = computePaginationMeta(1, 20, 100);
      expect(meta).toEqual({
        page: 1,
        pageSize: 20,
        total: 100,
        totalPages: 5,
        hasNext: true,
        hasPrev: false,
      });
    });

    it('computes correct metadata for last page', () => {
      const meta = computePaginationMeta(5, 20, 100);
      expect(meta).toEqual({
        page: 5,
        pageSize: 20,
        total: 100,
        totalPages: 5,
        hasNext: false,
        hasPrev: true,
      });
    });

    it('computes correct metadata for middle page', () => {
      const meta = computePaginationMeta(3, 10, 50);
      expect(meta).toEqual({
        page: 3,
        pageSize: 10,
        total: 50,
        totalPages: 5,
        hasNext: true,
        hasPrev: true,
      });
    });

    it('handles single page of results', () => {
      const meta = computePaginationMeta(1, 20, 5);
      expect(meta).toEqual({
        page: 1,
        pageSize: 20,
        total: 5,
        totalPages: 1,
        hasNext: false,
        hasPrev: false,
      });
    });

    it('handles zero total records', () => {
      const meta = computePaginationMeta(1, 20, 0);
      expect(meta).toEqual({
        page: 1,
        pageSize: 20,
        total: 0,
        totalPages: 0,
        hasNext: false,
        hasPrev: false,
      });
    });

    it('handles page beyond totalPages (empty data scenario)', () => {
      const meta = computePaginationMeta(10, 20, 50);
      // totalPages = ceil(50/20) = 3, page 10 > 3 so hasNext = false
      expect(meta).toEqual({
        page: 10,
        pageSize: 20,
        total: 50,
        totalPages: 3,
        hasNext: false,
        hasPrev: true,
      });
    });

    it('computes totalPages with ceiling division', () => {
      // 51 items / 20 per page = 2.55 → ceil = 3
      const meta = computePaginationMeta(1, 20, 51);
      expect(meta.totalPages).toBe(3);
    });

    it('computes totalPages correctly when total is exact multiple of pageSize', () => {
      const meta = computePaginationMeta(1, 25, 100);
      expect(meta.totalPages).toBe(4);
    });

    it('hasPrev is false for page 1', () => {
      const meta = computePaginationMeta(1, 10, 100);
      expect(meta.hasPrev).toBe(false);
    });

    it('hasPrev is true for page > 1', () => {
      const meta = computePaginationMeta(2, 10, 100);
      expect(meta.hasPrev).toBe(true);
    });

    it('hasNext is true when page < totalPages', () => {
      const meta = computePaginationMeta(1, 10, 100);
      expect(meta.hasNext).toBe(true);
    });

    it('hasNext is false when page >= totalPages', () => {
      const meta = computePaginationMeta(10, 10, 100);
      expect(meta.hasNext).toBe(false);
    });

    it('handles total of 1 with pageSize 1', () => {
      const meta = computePaginationMeta(1, 1, 1);
      expect(meta).toEqual({
        page: 1,
        pageSize: 1,
        total: 1,
        totalPages: 1,
        hasNext: false,
        hasPrev: false,
      });
    });
  });

  // ─── paginateQuery ───────────────────────────────────────────────────────

  describe('paginateQuery', () => {
    it('appends LIMIT and OFFSET to a basic query', () => {
      const result = paginateQuery('SELECT * FROM users', 1, 20);
      expect(result).toBe('SELECT * FROM users LIMIT 20 OFFSET 0');
    });

    it('computes correct offset for page 2', () => {
      const result = paginateQuery('SELECT * FROM items', 2, 10);
      expect(result).toBe('SELECT * FROM items LIMIT 10 OFFSET 10');
    });

    it('computes correct offset for page 5 with pageSize 25', () => {
      const result = paginateQuery('SELECT * FROM records WHERE active = true', 5, 25);
      expect(result).toBe('SELECT * FROM records WHERE active = true LIMIT 25 OFFSET 100');
    });

    it('handles page 1 with offset 0', () => {
      const result = paginateQuery('SELECT id, name FROM departments', 1, 50);
      expect(result).toBe('SELECT id, name FROM departments LIMIT 50 OFFSET 0');
    });

    it('preserves existing query with ORDER BY', () => {
      const result = paginateQuery('SELECT * FROM logs ORDER BY created_at DESC', 3, 15);
      expect(result).toBe('SELECT * FROM logs ORDER BY created_at DESC LIMIT 15 OFFSET 30');
    });
  });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import {
  detectDuplicates,
  logDuplicateRoutes,
  methodNotAllowed,
  registerRoute,
  registerRoutes,
  getRegisteredRoutes,
  clearRegistry,
  RouteRegistration,
} from '../routeRegistry';
import { createMockRequest, createMockResponse, createMockNext } from '../../__tests__/helpers/apiTestUtils';

describe('routeRegistry', () => {
  beforeEach(() => {
    clearRegistry();
  });

  describe('registerRoute', () => {
    it('adds a route to the registry', () => {
      registerRoute('GET', '/api/users', 'users.ts');
      const routes = getRegisteredRoutes();
      expect(routes).toHaveLength(1);
      expect(routes[0]).toEqual({ method: 'GET', path: '/api/users', source: 'users.ts' });
    });

    it('normalizes method to uppercase', () => {
      registerRoute('get', '/api/users', 'users.ts');
      const routes = getRegisteredRoutes();
      expect(routes[0].method).toBe('GET');
    });

    it('normalizes path with double slashes', () => {
      registerRoute('GET', '/api//users', 'users.ts');
      const routes = getRegisteredRoutes();
      expect(routes[0].path).toBe('/api/users');
    });
  });

  describe('registerRoutes', () => {
    it('registers multiple methods for the same path', () => {
      registerRoutes(['GET', 'POST', 'PUT', 'DELETE'], '/api/items', 'crudGenerator');
      const routes = getRegisteredRoutes();
      expect(routes).toHaveLength(4);
      expect(routes.map(r => r.method)).toEqual(['GET', 'POST', 'PUT', 'DELETE']);
    });
  });

  describe('detectDuplicates', () => {
    it('returns empty array when no duplicates exist', () => {
      const routes: RouteRegistration[] = [
        { method: 'GET', path: '/api/users', source: 'users.ts' },
        { method: 'POST', path: '/api/users', source: 'users.ts' },
        { method: 'GET', path: '/api/roles', source: 'roles.ts' },
      ];

      const duplicates = detectDuplicates(routes);
      expect(duplicates).toHaveLength(0);
    });

    it('detects duplicate route registrations with same method and path', () => {
      const routes: RouteRegistration[] = [
        { method: 'GET', path: '/api/audit-tasks', source: 'crudGenerator' },
        { method: 'GET', path: '/api/audit-tasks', source: 'auditTasks.ts' },
        { method: 'POST', path: '/api/audit-tasks', source: 'crudGenerator' },
      ];

      const duplicates = detectDuplicates(routes);
      expect(duplicates).toHaveLength(1);
      expect(duplicates[0]).toEqual({
        method: 'GET',
        path: '/api/audit-tasks',
        sources: ['crudGenerator', 'auditTasks.ts'],
      });
    });

    it('detects multiple duplicate groups', () => {
      const routes: RouteRegistration[] = [
        { method: 'GET', path: '/api/audit-tasks', source: 'crudGenerator' },
        { method: 'GET', path: '/api/audit-tasks', source: 'auditTasks.ts' },
        { method: 'GET', path: '/api/recommendations', source: 'crudGenerator' },
        { method: 'GET', path: '/api/recommendations', source: 'recommendations.ts' },
        { method: 'GET', path: '/api/users', source: 'users.ts' },
      ];

      const duplicates = detectDuplicates(routes);
      expect(duplicates).toHaveLength(2);
    });

    it('treats different methods on same path as distinct (no duplicate)', () => {
      const routes: RouteRegistration[] = [
        { method: 'GET', path: '/api/audit-tasks', source: 'auditTasks.ts' },
        { method: 'PATCH', path: '/api/audit-tasks', source: 'auditTasks.ts' },
        { method: 'DELETE', path: '/api/audit-tasks', source: 'crudGenerator' },
      ];

      const duplicates = detectDuplicates(routes);
      expect(duplicates).toHaveLength(0);
    });

    it('detects three-way duplicates', () => {
      const routes: RouteRegistration[] = [
        { method: 'GET', path: '/api/items', source: 'source1' },
        { method: 'GET', path: '/api/items', source: 'source2' },
        { method: 'GET', path: '/api/items', source: 'source3' },
      ];

      const duplicates = detectDuplicates(routes);
      expect(duplicates).toHaveLength(1);
      expect(duplicates[0].sources).toHaveLength(3);
    });

    it('uses the global registry when no routes argument is provided', () => {
      registerRoute('GET', '/api/items', 'source1');
      registerRoute('GET', '/api/items', 'source2');

      const duplicates = detectDuplicates();
      expect(duplicates).toHaveLength(1);
      expect(duplicates[0].sources).toEqual(['source1', 'source2']);
    });
  });

  describe('logDuplicateRoutes', () => {
    it('logs warnings for duplicate routes in the registry', () => {
      const warnSpy = vi.spyOn(console, 'warn').mockImplementation(() => {});

      registerRoute('GET', '/api/audit-tasks', 'crudGenerator');
      registerRoute('GET', '/api/audit-tasks', 'auditTasks.ts');

      const duplicates = logDuplicateRoutes();

      expect(duplicates).toHaveLength(1);
      expect(warnSpy).toHaveBeenCalledTimes(1);
      expect(warnSpy.mock.calls[0][0]).toContain('[RouteRegistry]');
      expect(warnSpy.mock.calls[0][0]).toContain('Duplicate route detected');
      expect(warnSpy.mock.calls[0][0]).toContain('GET');
      expect(warnSpy.mock.calls[0][0]).toContain('/api/audit-tasks');
      expect(warnSpy.mock.calls[0][0]).toContain('crudGenerator');
      expect(warnSpy.mock.calls[0][0]).toContain('auditTasks.ts');

      warnSpy.mockRestore();
    });

    it('returns empty array and does not log when no duplicates exist', () => {
      const warnSpy = vi.spyOn(console, 'warn').mockImplementation(() => {});

      registerRoute('GET', '/api/users', 'users.ts');
      registerRoute('POST', '/api/users', 'users.ts');
      registerRoute('GET', '/api/roles', 'roles.ts');

      const duplicates = logDuplicateRoutes();
      expect(duplicates).toHaveLength(0);
      expect(warnSpy).not.toHaveBeenCalled();

      warnSpy.mockRestore();
    });

    it('logs multiple warnings for multiple duplicate groups', () => {
      const warnSpy = vi.spyOn(console, 'warn').mockImplementation(() => {});

      registerRoute('GET', '/api/audit-tasks', 'crudGenerator');
      registerRoute('GET', '/api/audit-tasks', 'auditTasks.ts');
      registerRoute('GET', '/api/recommendations', 'crudGenerator');
      registerRoute('GET', '/api/recommendations', 'recommendations.ts');

      const duplicates = logDuplicateRoutes();
      expect(duplicates).toHaveLength(2);
      expect(warnSpy).toHaveBeenCalledTimes(2);

      warnSpy.mockRestore();
    });
  });

  describe('methodNotAllowed', () => {
    it('returns 405 status with Allow header', () => {
      const middleware = methodNotAllowed(['GET', 'PATCH']);
      const req = createMockRequest({ method: 'DELETE', url: '/api/audit-tasks/1' });
      const res = createMockResponse();
      const next = createMockNext();

      middleware(req, res as any, next);

      expect(res.statusCode).toBe(405);
      expect(res._headers['allow']).toBe('GET, PATCH');
      expect(res._json).toEqual({
        success: false,
        error: {
          code: 'METHOD_NOT_ALLOWED',
          message: 'Method DELETE is not allowed on this resource. Allowed methods: GET, PATCH',
        },
      });
    });

    it('includes all allowed methods in Allow header', () => {
      const middleware = methodNotAllowed(['GET', 'POST', 'PUT', 'DELETE']);
      const req = createMockRequest({ method: 'PATCH', url: '/api/items' });
      const res = createMockResponse();
      const next = createMockNext();

      middleware(req, res as any, next);

      expect(res._headers['allow']).toBe('GET, POST, PUT, DELETE');
      expect(res.statusCode).toBe(405);
    });

    it('normalizes method names to uppercase', () => {
      const middleware = methodNotAllowed(['get', 'post']);
      const req = createMockRequest({ method: 'PUT', url: '/api/items' });
      const res = createMockResponse();
      const next = createMockNext();

      middleware(req, res as any, next);

      expect(res._headers['allow']).toBe('GET, POST');
    });

    it('does not call next()', () => {
      const middleware = methodNotAllowed(['GET']);
      const req = createMockRequest({ method: 'DELETE', url: '/api/items' });
      const res = createMockResponse();
      const next = createMockNext();

      middleware(req, res as any, next);

      expect(next).not.toHaveBeenCalled();
    });

    it('includes error code METHOD_NOT_ALLOWED in response', () => {
      const middleware = methodNotAllowed(['POST']);
      const req = createMockRequest({ method: 'GET', url: '/api/items' });
      const res = createMockResponse();
      const next = createMockNext();

      middleware(req, res as any, next);

      expect(res._json.error.code).toBe('METHOD_NOT_ALLOWED');
    });
  });

  describe('clearRegistry', () => {
    it('removes all registered routes', () => {
      registerRoute('GET', '/api/users', 'users.ts');
      registerRoute('POST', '/api/users', 'users.ts');
      expect(getRegisteredRoutes()).toHaveLength(2);

      clearRegistry();
      expect(getRegisteredRoutes()).toHaveLength(0);
    });
  });
});

import { Request, Response, NextFunction } from 'express';

type AsyncHandler = (req: Request, res: Response, next: NextFunction) => Promise<any>;

export const asyncHandler = (fn: AsyncHandler) => {
  return (req: Request, res: Response, next: NextFunction) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
};

import fs from 'fs';
import path from 'path';
import crypto from 'crypto';
import { exec } from 'child_process';
import { promisify } from 'util';
import cron, { ScheduledTask } from 'node-cron';
import { db } from '../db/index';
import logger from './logger';

const execAsync = promisify(exec);

const BACKUP_DIR = process.env.BACKUP_DIR || path.join(process.cwd(), 'backups');
const MAX_BACKUPS = parseInt(process.env.MAX_BACKUPS || '7', 10);

// --- Interfaces ---

export interface BackupConfig {
  schedule: string;          // cron expression (default: '0 2 * * *' = daily at 2 AM)
  retentionDays: number;     // days to keep backups (default: 30)
  backupDir: string;         // backup storage directory
  encryptBackups: boolean;   // whether to encrypt backup files
  notifyOnFailure: boolean;  // send notification on failure
}

export interface BackupResult {
  id: string;
  timestamp: string;
  size: number;
  duration: number;
  status: 'success' | 'partial' | 'failed';
  errors?: string[];
}

export interface BackupRecord {
  id: string;
  started_at: string;
  completed_at: string | null;
  status: 'running' | 'success' | 'partial' | 'failed';
  type: 'scheduled' | 'manual';
  size_bytes: number;
  tables_count: number;
  file_path: string;
  error_message: string | null;
  verified: boolean;
  verified_at: string | null;
}

// --- Default config ---

const DEFAULT_CONFIG: BackupConfig = {
  schedule: '0 2 * * *',
  retentionDays: parseInt(process.env.BACKUP_RETENTION_DAYS || '30', 10),
  backupDir: BACKUP_DIR,
  encryptBackups: process.env.ENCRYPT_BACKUPS === 'true',
  notifyOnFailure: true,
};

// --- BackupScheduler Class ---

export class BackupScheduler {
  private config: BackupConfig;
  private task: ScheduledTask | null = null;
  private running = false;

  constructor(config?: Partial<BackupConfig>) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Starts the cron schedule for automated backups.
   */
  start(config?: Partial<BackupConfig>): void {
    if (config) {
      this.config = { ...this.config, ...config };
    }

    if (this.task) {
      logger.warn('[BACKUP] Scheduler already running. Stopping previous schedule.');
      this.stop();
    }

    if (!cron.validate(this.config.schedule)) {
      logger.error(`[BACKUP] Invalid cron expression: ${this.config.schedule}`);
      return;
    }

    this.task = cron.schedule(this.config.schedule, async () => {
      logger.info('[BACKUP] Scheduled backup triggered.');
      try {
        await this.executeBackup('scheduled');
      } catch (error) {
        logger.error('[BACKUP] Scheduled backup failed:', error);
      }
    });

    this.running = true;
    logger.info(`[BACKUP] Scheduler started with schedule: ${this.config.schedule}`);
  }

  /**
   * Stops the cron schedule.
   */
  stop(): void {
    if (this.task) {
      this.task.stop();
      this.task = null;
    }
    this.running = false;
    logger.info('[BACKUP] Scheduler stopped.');
  }

  /**
   * Triggers an immediate backup and returns the result.
   */
  async runNow(): Promise<BackupResult> {
    logger.info('[BACKUP] Manual backup triggered.');
    return this.executeBackup('manual');
  }

  /**
   * Queries the backup_history table and returns recent backup records.
   */
  async getHistory(limit: number = 20): Promise<BackupRecord[]> {
    try {
      const rows = await db.prepare(
        `SELECT id, started_at, completed_at, status, type, size_bytes, tables_count, file_path, error_message, verified, verified_at
         FROM backup_history
         ORDER BY started_at DESC
         LIMIT ?`
      ).all(limit);
      return rows as BackupRecord[];
    } catch (error) {
      logger.error('[BACKUP] Failed to fetch backup history:', error);
      return [];
    }
  }

  /**
   * Returns whether the scheduler is currently running.
   */
  isRunning(): boolean {
    return this.running;
  }

  /**
   * Core backup execution logic. Supports both PGlite (JSON) and external PostgreSQL (pg_dump).
   */
  private async executeBackup(type: 'scheduled' | 'manual'): Promise<BackupResult> {
    const startTime = Date.now();
    const backupId = crypto.randomUUID();
    const timestamp = new Date().toISOString();
    const errors: string[] = [];

    // Record start in backup_history
    await this.saveRecord({
      id: backupId,
      started_at: timestamp,
      completed_at: null,
      status: 'running',
      type,
      size_bytes: 0,
      tables_count: 0,
      file_path: '',
      error_message: null,
      verified: false,
      verified_at: null,
    });

    let filePath = '';
    let sizeBytes = 0;
    let tablesCount = 0;
    let status: 'success' | 'partial' | 'failed' = 'success';

    try {
      // Ensure backup directory exists
      if (!fs.existsSync(this.config.backupDir)) {
        fs.mkdirSync(this.config.backupDir, { recursive: true });
      }

      if (db.isExternal) {
        // External PostgreSQL: use pg_dump with gzip compression
        const dumpFile = `backup_${backupId}.sql.gz`;
        filePath = path.join(this.config.backupDir, dumpFile);

        const databaseUrl = process.env.DATABASE_URL;
        if (!databaseUrl) {
          throw new Error('DATABASE_URL is not set for external PostgreSQL backup');
        }

        await execAsync(
          `pg_dump "${databaseUrl}" | gzip > "${filePath}"`
        );

        const stat = fs.statSync(filePath);
        sizeBytes = stat.size;

        // Verify backup integrity (file size > 0)
        if (sizeBytes === 0) {
          throw new Error('pg_dump produced an empty backup file');
        }

        tablesCount = -1; // Unknown for pg_dump (full database)
      } else {
        // PGlite: use existing JSON backup logic
        const result = await createBackupInternal(this.config.backupDir, backupId);
        filePath = result.path;
        sizeBytes = result.size;
        tablesCount = result.tablesCount;

        if (result.errors.length > 0) {
          errors.push(...result.errors);
          status = result.tablesCount > 0 ? 'partial' : 'failed';
        }
      }
    } catch (error: any) {
      status = 'failed';
      errors.push(error.message || String(error));
      logger.error('[BACKUP] Backup execution failed:', error);
    }

    const duration = Date.now() - startTime;
    const completedAt = new Date().toISOString();

    // Update backup_history record
    await this.updateRecord(backupId, {
      completed_at: completedAt,
      status,
      size_bytes: sizeBytes,
      tables_count: tablesCount,
      file_path: filePath,
      error_message: errors.length > 0 ? errors.join('; ') : null,
      verified: sizeBytes > 0,
      verified_at: sizeBytes > 0 ? completedAt : null,
    });

    // Apply retention policy
    await this.applyRetentionPolicy();

    // Notify admins on failure
    if (status === 'failed' && this.config.notifyOnFailure) {
      await this.notifyAdminsOnFailure(backupId, errors);
    }

    const result: BackupResult = {
      id: backupId,
      timestamp,
      size: sizeBytes,
      duration,
      status,
      ...(errors.length > 0 && { errors }),
    };

    logger.info(`[BACKUP] Backup ${backupId} completed with status: ${status} (${duration}ms, ${sizeBytes} bytes)`);
    return result;
  }

  /**
   * Saves a new backup record to the backup_history table.
   */
  private async saveRecord(record: BackupRecord): Promise<void> {
    try {
      await db.prepare(
        `INSERT INTO backup_history (id, started_at, completed_at, status, type, size_bytes, tables_count, file_path, error_message, verified, verified_at)
         VALUES (?::uuid, ?::timestamptz, ${record.completed_at ? '?::timestamptz' : 'NULL'}, ?::text, ?::text, ?, ?, ?::text, ${record.error_message ? '?::text' : 'NULL'}, ?, ${record.verified_at ? '?::timestamptz' : 'NULL'})`
      ).run(
        ...[
          record.id,
          record.started_at,
          ...(record.completed_at ? [record.completed_at] : []),
          record.status,
          record.type,
          record.size_bytes,
          record.tables_count,
          record.file_path,
          ...(record.error_message ? [record.error_message] : []),
          record.verified,
          ...(record.verified_at ? [record.verified_at] : []),
        ]
      );
    } catch (error) {
      logger.error('[BACKUP] Failed to save backup record:', error);
    }
  }

  /**
   * Updates an existing backup record in the backup_history table.
   */
  private async updateRecord(id: string, updates: Partial<BackupRecord>): Promise<void> {
    try {
      await db.prepare(
        `UPDATE backup_history
         SET completed_at = ?::timestamptz,
             status = ?::text,
             size_bytes = ?,
             tables_count = ?,
             file_path = ?::text,
             error_message = ${updates.error_message ? '?::text' : 'NULL'},
             verified = ?,
             verified_at = ${updates.verified_at ? '?::timestamptz' : 'NULL'}
         WHERE id = ?::uuid`
      ).run(
        ...[
          updates.completed_at || null,
          updates.status || 'failed',
          updates.size_bytes || 0,
          updates.tables_count || 0,
          updates.file_path || '',
          ...(updates.error_message ? [updates.error_message] : []),
          updates.verified || false,
          ...(updates.verified_at ? [updates.verified_at] : []),
          id,
        ]
      );
    } catch (error) {
      logger.error('[BACKUP] Failed to update backup record:', error);
    }
  }

  /**
   * Applies retention policy: deletes backups older than retentionDays.
   */
  private async applyRetentionPolicy(): Promise<void> {
    try {
      const cutoffDate = new Date();
      cutoffDate.setDate(cutoffDate.getDate() - this.config.retentionDays);
      const cutoffStr = cutoffDate.toISOString();

      // Get old backup records
      const oldRecords = await db.prepare(
        `SELECT id, file_path FROM backup_history WHERE started_at < ? AND status != 'running'`
      ).all(cutoffStr) as BackupRecord[];

      for (const record of oldRecords) {
        // Delete backup file from disk
        if (record.file_path && fs.existsSync(record.file_path)) {
          try {
            const stat = fs.statSync(record.file_path);
            if (stat.isDirectory()) {
              fs.rmSync(record.file_path, { recursive: true, force: true });
            } else {
              fs.unlinkSync(record.file_path);
            }
          } catch (err) {
            logger.warn(`[BACKUP] Failed to delete old backup file: ${record.file_path}`, err);
          }
        }

        // Delete record from database
        await db.prepare(`DELETE FROM backup_history WHERE id = ?::uuid`).run(record.id);
      }

      if (oldRecords.length > 0) {
        logger.info(`[BACKUP] Retention policy applied: removed ${oldRecords.length} old backup(s)`);
      }
    } catch (error) {
      logger.warn('[BACKUP] Retention policy application failed:', error);
    }
  }

  /**
   * Notifies admin users when a backup fails.
   */
  private async notifyAdminsOnFailure(backupId: string, errors: string[]): Promise<void> {
    try {
      // Dynamically import to avoid circular dependencies
      const { NotificationService } = await import('../services/NotificationService');
      const { UserRole } = await import('../../constants');

      const admins = await db.prepare(
        `SELECT id FROM users WHERE role = '${UserRole.ADMIN}'`
      ).all() as Array<{ id: string }>;

      const adminIds = admins.map(a => a.id);
      if (adminIds.length === 0) return;

      await NotificationService.create(
        adminIds,
        'backup_failed',
        `Backup ${backupId} failed: ${errors.join('; ')}`,
        'system',
        '/admin/backups'
      );

      logger.info(`[BACKUP] Failure notification sent to ${adminIds.length} admin(s)`);
    } catch (error) {
      logger.error('[BACKUP] Failed to send failure notification:', error);
    }
  }
}

// --- Internal helper for PGlite JSON backup ---

interface InternalBackupResult {
  path: string;
  size: number;
  tablesCount: number;
  errors: string[];
}

async function createBackupInternal(
  backupDir: string,
  backupId: string
): Promise<InternalBackupResult> {
  const errors: string[] = [];
  const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
  const backupPath = path.join(backupDir, `backup_${backupId}_${timestamp}`);
  fs.mkdirSync(backupPath, { recursive: true });

  // Critical tables to backup
  const tables = [
    'users',
    'audit_programs',
    'audit_plans',
    'audit_tasks',
    'audit_findings',
    'recommendations',
    'risk_register',
    'incoming_correspondence',
    'outgoing_correspondence',
    'notifications',
  ];

  let backedUp = 0;
  let totalSize = 0;

  for (const table of tables) {
    try {
      const rows = await db.prepare(`SELECT * FROM ${db.validateIdentifier(table)}`).all();
      const filePath = path.join(backupPath, `${table}.json`);
      const content = JSON.stringify(rows, null, 2);
      fs.writeFileSync(filePath, content);
      totalSize += Buffer.byteLength(content, 'utf8');
      backedUp++;
    } catch (err: any) {
      // Table might not exist yet
      if (!err.message?.includes('does not exist')) {
        errors.push(`Failed to backup table ${table}: ${err.message}`);
        logger.warn(`[BACKUP] Failed to backup table ${table}:`, err.message);
      }
    }
  }

  return {
    path: backupPath,
    size: totalSize,
    tablesCount: backedUp,
    errors,
  };
}

// --- Legacy createBackup function (preserved for backward compatibility) ---

/**
 * Creates a logical backup of critical database tables.
 * For PostgreSQL production: use pg_dump externally.
 * For PGlite development: exports table data as JSON files.
 *
 * @deprecated Use BackupScheduler.runNow() instead for new code.
 */
export async function createBackup(): Promise<string | null> {
  if (db.isExternal) {
    // For external PostgreSQL, log a reminder to use pg_dump
    logger.info('[BACKUP] External PostgreSQL detected. Use pg_dump for production backups.');
    return null;
  }

  try {
    // Ensure backup directory exists
    if (!fs.existsSync(BACKUP_DIR)) {
      fs.mkdirSync(BACKUP_DIR, { recursive: true });
    }

    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const backupPath = path.join(BACKUP_DIR, `backup_${timestamp}`);
    fs.mkdirSync(backupPath, { recursive: true });

    // Critical tables to backup
    const tables = [
      'users',
      'audit_programs',
      'audit_plans',
      'audit_tasks',
      'audit_findings',
      'recommendations',
      'risk_register',
      'incoming_correspondence',
      'outgoing_correspondence',
      'notifications',
    ];

    let backedUp = 0;
    for (const table of tables) {
      try {
        const rows = await db.prepare(`SELECT * FROM ${db.validateIdentifier(table)}`).all();
        const filePath = path.join(backupPath, `${table}.json`);
        fs.writeFileSync(filePath, JSON.stringify(rows, null, 2));
        backedUp++;
      } catch (err: any) {
        // Table might not exist yet
        if (!err.message?.includes('does not exist')) {
          logger.warn(`[BACKUP] Failed to backup table ${table}:`, err.message);
        }
      }
    }

    logger.info(`[BACKUP] Created backup at ${backupPath} (${backedUp} tables)`);

    // Cleanup old backups
    await cleanupOldBackups();

    return backupPath;
  } catch (err) {
    logger.error('[BACKUP] Backup failed:', err);
    return null;
  }
}

async function cleanupOldBackups(): Promise<void> {
  try {
    if (!fs.existsSync(BACKUP_DIR)) return;

    const entries = fs.readdirSync(BACKUP_DIR)
      .filter(e => e.startsWith('backup_'))
      .sort()
      .reverse();

    // Keep only MAX_BACKUPS most recent
    for (let i = MAX_BACKUPS; i < entries.length; i++) {
      const dirPath = path.join(BACKUP_DIR, entries[i]);
      fs.rmSync(dirPath, { recursive: true, force: true });
      logger.info(`[BACKUP] Removed old backup: ${entries[i]}`);
    }
  } catch (err) {
    logger.warn('[BACKUP] Cleanup failed:', err);
  }
}

// Singleton instance for application-wide use
export const backupScheduler = new BackupScheduler();

export default { createBackup, BackupScheduler, backupScheduler };

import express from 'express';
import { AuthenticatedRequest, FileUploadRequest } from '../types';
import { asyncHandler } from './asyncHandler';
import { ValidationError, NotFoundError } from './errors';
import { BaseService } from '../services/BaseService';
import { AuthService } from '../services/AuthService';
import { AuditPlanService } from '../services/AuditPlanService';
import { RiskService } from '../services/RiskService';
import { registerRoutes } from './routeRegistry';
import { parsePaginationParams } from './paginationService';
import fs from 'fs';
import path from 'path';

/**
 * Route names excluded from CRUD generation because they have custom route files.
 * These resources are handled by dedicated route modules with specialized logic.
 */
export const CRUD_EXCLUDED_ROUTES: string[] = [
  'audit-tasks',
  'audit-programs',
  'recommendations',
  'audit-findings',
];

export const createCrudRoutes = (
  db: any,
  authenticate: any,
  checkPermission: any,
  logError: any,
  createNotification: any,
  saveFile: any
) => {
  const router = express.Router();

  const ALLOWED_TABLES = [
    "audit_plans", "audit_tasks", "audit_programs", "audit_procedures", 
    "audit_evidence", "risk_register", "fraud_log", "central_bank_instructions", 
    "law_bank", "audit_reports", "audit_findings", "recommendations", "compliance_items"
  ];

  const TABLE_ALLOWED_FIELDS: Record<string, string[]> = {
    "audit_plans": ["plan_code", "program_id", "title", "department", "type", "risk_rating", "planned_start_date", "planned_end_date", "status", "lead_auditor", "team_members", "objectives", "scope", "notes"],
    "audit_tasks": ["task_number", "title", "plan_id", "program_id", "audit_type", "status", "assigned_to", "audited_unit_id", "planned_hours", "actual_hours", "period_from", "period_to", "due_date", "approved_by", "approved_at", "created_by", "deleted_at"],
    "audit_programs": ["program_code", "program_title", "audit_area", "department", "audit_type", "audit_objective", "audit_scope", "key_risks", "control_objectives", "reference_standard", "status", "version_number", "created_by"],
    "audit_procedures": ["program_id", "procedure_number", "audit_step", "audit_test_description", "risk_addressed", "control_test_type", "expected_evidence", "sampling_method", "responsible_auditor", "remarks"],
    "audit_evidence": ["audit_id", "finding_id", "type", "description", "uploaded_by", "file_name", "file_data", "upload_date"],
    "risk_register": ["risk_id", "description", "owner", "source", "early_warning", "type", "likelihood", "impact", "likelihood_num", "impact_num", "risk_score_calc", "risk_level_calc", "score", "rating", "controls", "control_assessment", "mitigation", "treatment_option", "residual_likelihood", "residual_impact", "residual_score", "residual_rating", "status", "target_date", "review_date", "notes", "entry_date", "entered_by"],
    "fraud_log": ["incident_date", "description", "reported_by", "status"],
    "central_bank_instructions": ["title", "issue_date", "reference_number", "category", "description", "related_department", "attachment", "status", "related_instruction_id"],
    "law_bank": ["title", "type", "authority", "issue_date", "keywords", "bookmarked", "file_url"],
    "audit_reports": ["audit_id", "title", "report_type", "generated_by", "date_generated", "status", "content"],
    "audit_findings": ["audit_id", "title", "description", "criteria", "condition", "cause", "consequence", "recommendation", "risk_level", "status", "finding_number", "finding_type", "impact", "root_cause", "responsible_unit_id", "risk_id", "created_by", "deleted_at"],
    "recommendations": ["finding_id", "department", "responsible", "due_date", "status", "risk_level", "rec_number", "action_plan", "responsible_person_id", "priority", "follow_up_date", "closure_evidence_path", "closed_by", "closed_at", "created_by"],
    "compliance_items": ["ref_number", "title", "type", "issuing_authority", "issue_date", "effective_date", "compliance_status", "responsible_person_id", "attachment_path", "notes", "created_by"]
  };

  const generateRoutes = (tableName: string, routeName: string, moduleName: string) => {
    if (!ALLOWED_TABLES.includes(tableName)) {
      console.error(`Attempt to generate CRUD routes for unauthorized table: ${tableName}`);
      return;
    }

    // Skip routes that have custom route files to prevent duplicate registration
    if (CRUD_EXCLUDED_ROUTES.includes(routeName)) {
      return;
    }

    // Register routes in the route registry for duplicate detection
    registerRoutes(
      ['GET', 'POST', 'PUT', 'DELETE'],
      `/api/${routeName}`,
      'crudGenerator'
    );

    router.get(`/${routeName}`, authenticate, checkPermission(moduleName, 'View'), asyncHandler(async (req, res) => {
      const { page, pageSize } = parsePaginationParams(req.query as Record<string, any>);

      // Extract all query params except page and pageSize as filters
      const { page: _, pageSize: __, ...filters } = req.query;
      
      const allowedFields = TABLE_ALLOWED_FIELDS[tableName] || [];
      const excludeFromSelect = ['file_data', 'content', 'attachment_file', 'attachment', 'file_url'];
      const selectFields = ['id', 'created_at', 'updated_at', ...allowedFields.filter(f => !excludeFromSelect.includes(f))];

      const result = await BaseService.findAll(tableName, { 
        page, 
        pageSize,
        where: filters,
        select: selectFields
      });
      res.json(result);
    }));

    router.get(`/${routeName}/:id`, authenticate, checkPermission(moduleName, 'View'), asyncHandler(async (req, res) => {
      const id = req.params.id as string;
      const result = await BaseService.findById(tableName, id);
      if (!result) throw new NotFoundError(`${tableName} record not found`);
      res.json(result);
    }));

    router.post(`/${routeName}`, authenticate, checkPermission(moduleName, 'Create'), asyncHandler(async (req, res) => {
      const typedReq = req as unknown as FileUploadRequest;
      const rawBody = { ...typedReq.body };
      
      // Strict Whitelisting (Mass Assignment Prevention)
      const body: any = {};
      const allowedFields = TABLE_ALLOWED_FIELDS[tableName] || [];
      for (const key of Object.keys(rawBody)) {
        if (allowedFields.includes(key)) {
          body[key] = rawBody[key];
        }
      }
      
      // Handle file uploads if present
      const files = typedReq.files;
      if (files) {
        for (const key of Object.keys(files)) {
          if (!allowedFields.includes(key)) continue;
          const fileOrFiles = files[key];
          const file = Array.isArray(fileOrFiles) ? fileOrFiles[0] : fileOrFiles;
          body[key] = await saveFile(file);
        }
      }

      const service = tableName === 'audit_plans' ? AuditPlanService : (tableName === 'risk_register' ? RiskService : BaseService);
      let result;
      try {
        result = await service.create(tableName, body);
      } catch (err) {
        // Cleanup orphaned files if DB fails
        if (files) {
          for (const key of Object.keys(files)) {
            if (body[key] && typeof body[key] === 'string' && body[key].startsWith('/uploads/')) {
              const filePath = path.join(process.cwd(), body[key]);
              fs.unlink(filePath, (unlinkErr) => {
                if (unlinkErr && unlinkErr.code !== 'ENOENT') {
                  console.error(`[DB Failure Cleanup] Failed to delete orphaned file: ${filePath}`, unlinkErr);
                }
              });
            }
          }
        }
        throw err;
      }
      
      await AuthService.logAudit(typedReq.user.username, `Created ${tableName}`, routeName, JSON.stringify(body));
      
      // Targeted notification based on module type
      const actorId = typedReq.user?.id;
      const wss = (req.app as any).wss;
      const notifyOptions = { actorId, entityId: result?.id, entityType: tableName, wss };
      
      // Determine who to notify based on the table/module
      let targetUsers: string | string[] | 'all' = 'all';
      let notifType = 'record_created';
      let notifMessage = JSON.stringify({ key: 'notifications.newRecord', params: { module: tableName } });
      let notifTitle: string | undefined;
      
      if (tableName === 'risk_register' && body.owner) {
        // Notify risk owner + admins
        const { NotificationService: NS } = await import('../services/NotificationService');
        const ownerId = await NS.getUserIdByName(body.owner);
        const adminIds = await NS.getAdminIds();
        targetUsers = [...new Set([...(ownerId ? [ownerId] : []), ...adminIds])];
        notifType = 'risk_added';
        notifMessage = JSON.stringify({ key: 'notifications.riskAdded', params: { description: body.description || body.risk_id || '' } });
        notifTitle = JSON.stringify({ key: 'notifications.riskAdded' });
      } else if (tableName === 'recommendations' && body.responsible_person_id) {
        targetUsers = body.responsible_person_id;
        notifType = 'recommendation_added';
        notifMessage = JSON.stringify({ key: 'notifications.recommendationAdded' });
        notifTitle = JSON.stringify({ key: 'notifications.recommendationAdded' });
      } else if (tableName === 'audit_tasks' && body.assigned_to) {
        targetUsers = body.assigned_to;
        notifType = 'task_assigned';
        notifMessage = JSON.stringify({ key: 'notifications.taskAssigned', params: { title: body.title || '' } });
        notifTitle = JSON.stringify({ key: 'notifications.taskAssigned' });
      } else if (tableName === 'audit_findings') {
        // Notify admins for new findings
        const { NotificationService: NS } = await import('../services/NotificationService');
        targetUsers = await NS.getAdminIds();
        notifType = 'finding_added';
        notifMessage = JSON.stringify({ key: 'notifications.findingAdded', params: { title: body.title || '' } });
        notifTitle = JSON.stringify({ key: 'notifications.findingAdded' });
      } else if (tableName === 'audit_evidence') {
        notifType = 'evidence_uploaded';
        notifMessage = JSON.stringify({ key: 'notifications.evidenceUploaded', params: { description: body.description || body.file_name || '' } });
        notifTitle = JSON.stringify({ key: 'notifications.evidenceUploaded' });
      }
      
      await createNotification(targetUsers, notifType, notifMessage, routeName, `/${routeName}`, { ...notifyOptions, title: notifTitle });

      res.json(result);
    }));

    router.put(`/${routeName}/:id`, authenticate, checkPermission(moduleName, 'Edit'), asyncHandler(async (req, res) => {
      const typedReq = req as unknown as FileUploadRequest;
      const id = typedReq.params.id as string;
      const rawBody = { ...typedReq.body };
      
      // Strict Whitelisting (Mass Assignment Prevention)
      const body: any = {};
      const allowedFields = TABLE_ALLOWED_FIELDS[tableName] || [];
      for (const key of Object.keys(rawBody)) {
        if (allowedFields.includes(key)) {
          body[key] = rawBody[key];
        }
      }
      
      // Handle file uploads if present
      const files = typedReq.files;
      if (files) {
        for (const key of Object.keys(files)) {
          if (!allowedFields.includes(key)) continue;
          const fileOrFiles = files[key];
          const file = Array.isArray(fileOrFiles) ? fileOrFiles[0] : fileOrFiles;
          body[key] = await saveFile(file);
        }
      }

      const service = tableName === 'audit_plans' ? AuditPlanService : (tableName === 'risk_register' ? RiskService : BaseService);
      let result;
      try {
        result = await service.update(tableName, id, body);
      } catch (err) {
        // Cleanup orphaned files if DB fails
        if (files) {
          for (const key of Object.keys(files)) {
            if (body[key] && typeof body[key] === 'string' && body[key].startsWith('/uploads/')) {
              const filePath = path.join(process.cwd(), body[key]);
              fs.unlink(filePath, (unlinkErr) => {
                if (unlinkErr && unlinkErr.code !== 'ENOENT') {
                  console.error(`[DB Failure Cleanup] Failed to delete orphaned file: ${filePath}`, unlinkErr);
                }
              });
            }
          }
        }
        throw err;
      }

      await AuthService.logAudit(typedReq.user.username, `Updated ${tableName} ID: ${id}`, routeName, JSON.stringify(body));

      res.json(result);
    }));

    router.delete(`/${routeName}/:id`, authenticate, checkPermission(moduleName, 'Delete'), asyncHandler(async (req, res) => {
      const typedReq = req as unknown as AuthenticatedRequest;
      const id = typedReq.params.id as string;
      
      await BaseService.delete(tableName, id);
      
      await AuthService.logAudit(typedReq.user.username, `Deleted ${tableName} ID: ${id}`, routeName, JSON.stringify({ id }));
      res.json({ success: true });
    }));
  };

  generateRoutes("audit_plans", "audit-plans", "AuditPlans");
  generateRoutes("audit_tasks", "audit-tasks", "AuditTasks");
  generateRoutes("audit_programs", "audit-programs", "AuditProgramLibrary");
  generateRoutes("audit_procedures", "audit-procedures", "AuditProgramLibrary");
  generateRoutes("audit_evidence", "audit-evidence", "AuditEvidence");
  generateRoutes("risk_register", "risk-register", "RiskRegister");
  generateRoutes("fraud_log", "fraud-log", "IntegrityManagement");
  generateRoutes("central_bank_instructions", "central-bank-instructions", "Policies");
  generateRoutes("law_bank", "law-bank", "Policies");
  generateRoutes("audit_reports", "audit-reports", "Reports");
  generateRoutes("audit_findings", "audit-findings", "AuditFindings");
  generateRoutes("recommendations", "recommendations", "Recommendations");
  generateRoutes("compliance_items", "compliance-items", "ComplianceMatrix");

  return router;
};

export enum ErrorCode {
  BAD_REQUEST = 'BAD_REQUEST',
  UNAUTHORIZED = 'UNAUTHORIZED',
  FORBIDDEN = 'FORBIDDEN',
  NOT_FOUND = 'NOT_FOUND',
  CONFLICT = 'CONFLICT',
  VALIDATION_ERROR = 'VALIDATION_ERROR',
  INTERNAL_SERVER_ERROR = 'INTERNAL_SERVER_ERROR',
  DATABASE_ERROR = 'DATABASE_ERROR',
  SECURITY_ERROR = 'SECURITY_ERROR',
}

export class AppError extends Error {
  public readonly statusCode: number;
  public readonly errorCode: ErrorCode;
  public readonly isOperational: boolean;

  constructor(message: string, statusCode: number, errorCode: ErrorCode = ErrorCode.INTERNAL_SERVER_ERROR, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.errorCode = errorCode;
    this.isOperational = isOperational;
    Error.captureStackTrace(this, this.constructor);
  }
}

export class ValidationError extends AppError {
  public readonly details?: any;
  constructor(message: string, details?: any) {
    super(message, 400, ErrorCode.VALIDATION_ERROR);
    this.details = details;
  }
}

export class AuthError extends AppError {
  constructor(message: string = 'Unauthorized access') {
    super(message, 401, ErrorCode.UNAUTHORIZED);
  }
}

export class ForbiddenError extends AppError {
  constructor(message: string = 'Permission denied') {
    super(message, 403, ErrorCode.FORBIDDEN);
  }
}

export class NotFoundError extends AppError {
  constructor(message: string = 'Resource not found') {
    super(message, 404, ErrorCode.NOT_FOUND);
  }
}

export class ConflictError extends AppError {
  constructor(message: string) {
    super(message, 409, ErrorCode.CONFLICT);
  }
}

export class DatabaseError extends AppError {
  constructor(message: string = 'Database operation failed') {
    super(message, 500, ErrorCode.DATABASE_ERROR, false);
  }
}

export class SecurityError extends AppError {
  constructor(message: string) {
    super(message, 403, ErrorCode.SECURITY_ERROR);
  }
}

import path from 'path';
import logger from './logger';

// ─── Types ───────────────────────────────────────────────────────────────────

export type BucketName = 'evidence' | 'reports' | 'temp' | 'backups';

export interface FileValidationInput {
  /** File content as a Buffer */
  buffer: Buffer;
  /** Original filename as provided by the user */
  filename: string;
  /** MIME type declared by the client (e.g., from Content-Type header) */
  declaredContentType: string;
  /** Target storage bucket */
  bucket: BucketName;
}

export interface FileValidationResult {
  valid: boolean;
  /** Detected MIME type from content inspection (null if detection failed) */
  detectedMimeType: string | null;
  /** List of validation errors; empty when valid */
  errors: FileValidationError[];
}

export interface FileValidationError {
  code: FileValidationErrorCode;
  message: string;
}

export type FileValidationErrorCode =
  | 'MIME_NOT_ALLOWED'
  | 'MIME_EXTENSION_MISMATCH'
  | 'MIME_DETECTION_FAILED'
  | 'FILE_TOO_LARGE'
  | 'FILE_EMPTY'
  | 'FILENAME_TOO_LONG'
  | 'FILENAME_PATH_TRAVERSAL';

// ─── Constants ───────────────────────────────────────────────────────────────

/** Allowed MIME types for all buckets */
export const ALLOWED_MIME_TYPES: readonly string[] = [
  'application/pdf',
  'application/msword',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/vnd.ms-excel',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  'image/png',
  'image/jpeg',
  'image/gif',
] as const;

/** Per-bucket maximum file size in bytes */
export const BUCKET_MAX_SIZE: Record<BucketName, number> = {
  evidence: 50 * 1024 * 1024,   // 50 MB
  reports: 100 * 1024 * 1024,   // 100 MB
  temp: 100 * 1024 * 1024,      // 100 MB
  backups: 100 * 1024 * 1024,   // 100 MB
};

/** Maximum filename length in characters */
export const MAX_FILENAME_LENGTH = 255;

/**
 * Mapping from magika detection labels to MIME types.
 * Magika returns labels like 'pdf', 'png', 'docx', etc.
 */
const MAGIKA_LABEL_TO_MIME: Record<string, string> = {
  pdf: 'application/pdf',
  doc: 'application/msword',
  docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  xls: 'application/vnd.ms-excel',
  xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  png: 'image/png',
  jpeg: 'image/jpeg',
  jpg: 'image/jpeg',
  gif: 'image/gif',
  // zip-based formats (docx, xlsx are internally zip)
  zip: 'application/zip',
};

/**
 * Mapping from file extensions to expected MIME types.
 * Used to validate that detected MIME matches the file extension.
 */
const EXTENSION_TO_MIME: Record<string, string[]> = {
  '.pdf': ['application/pdf'],
  '.doc': ['application/msword'],
  '.docx': ['application/vnd.openxmlformats-officedocument.wordprocessingml.document'],
  '.xls': ['application/vnd.ms-excel'],
  '.xlsx': ['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'],
  '.png': ['image/png'],
  '.jpg': ['image/jpeg'],
  '.jpeg': ['image/jpeg'],
  '.gif': ['image/gif'],
};

/**
 * Some formats (docx, xlsx) are zip-based, so magika may report 'zip'.
 * We allow 'zip' detection for these extensions.
 */
const ZIP_BASED_EXTENSIONS = new Set(['.docx', '.xlsx']);

// ─── Magika Singleton ────────────────────────────────────────────────────────

let magikaInstance: any = null;
let magikaInitPromise: Promise<void> | null = null;

async function getMagikaInstance(): Promise<any> {
  if (magikaInstance) return magikaInstance;

  if (!magikaInitPromise) {
    magikaInitPromise = (async () => {
      try {
        const { Magika } = await import('magika');
        const m = await Magika.create();
        magikaInstance = m;
        logger.info('[FileValidation] Magika content inspector initialized.');
      } catch (e) {
        logger.error('[FileValidation] Failed to initialize Magika:', e);
        magikaInstance = null;
      }
    })();
  }

  await magikaInitPromise;
  return magikaInstance;
}

// ─── Core Validation Function ────────────────────────────────────────────────

/**
 * Validates a file for upload by checking:
 * 1. File size (> 0 and ≤ bucket max)
 * 2. Filename length (≤ 255 chars) and path traversal prevention
 * 3. Content-based MIME detection via magika
 * 4. Detected MIME against allowed list
 * 5. Detected MIME matches declared file extension
 *
 * @param input - File validation input parameters
 * @returns Structured validation result with pass/fail and specific errors
 */
export async function validateFile(input: FileValidationInput): Promise<FileValidationResult> {
  const { buffer, filename, declaredContentType, bucket } = input;
  const errors: FileValidationError[] = [];

  // ── 1. Validate file size ──────────────────────────────────────────────────
  if (buffer.length === 0) {
    errors.push({
      code: 'FILE_EMPTY',
      message: 'File is empty (0 bytes). Files must contain content.',
    });
  } else {
    const maxSize = BUCKET_MAX_SIZE[bucket];
    if (buffer.length > maxSize) {
      const maxMB = Math.round(maxSize / (1024 * 1024));
      const actualMB = (buffer.length / (1024 * 1024)).toFixed(2);
      errors.push({
        code: 'FILE_TOO_LARGE',
        message: `File size (${actualMB} MB) exceeds the maximum allowed size (${maxMB} MB) for bucket "${bucket}".`,
      });
    }
  }

  // ── 2. Validate filename ───────────────────────────────────────────────────
  if (filename.length > MAX_FILENAME_LENGTH) {
    errors.push({
      code: 'FILENAME_TOO_LONG',
      message: `Filename exceeds maximum length of ${MAX_FILENAME_LENGTH} characters (actual: ${filename.length}).`,
    });
  }

  if (containsPathTraversal(filename)) {
    errors.push({
      code: 'FILENAME_PATH_TRAVERSAL',
      message: 'Filename contains path traversal sequences (../, ..\\\, //, or null bytes) which are not allowed.',
    });
  }

  // ── 3. Content-based MIME detection via magika ─────────────────────────────
  let detectedMimeType: string | null = null;

  const magika = await getMagikaInstance();
  if (!magika) {
    errors.push({
      code: 'MIME_DETECTION_FAILED',
      message: 'Content inspection service (magika) is unavailable. File type could not be verified.',
    });

    return { valid: errors.length === 0, detectedMimeType, errors };
  }

  try {
    const bytes = new Uint8Array(buffer);
    const result = await magika.identifyBytes(bytes);
    const label = result?.prediction?.output?.label;

    if (!label || label === 'unknown' || label === 'empty') {
      errors.push({
        code: 'MIME_DETECTION_FAILED',
        message: `Content inspection could not determine the file type (detected: ${label || 'none'}). Upload rejected.`,
      });

      return { valid: errors.length === 0, detectedMimeType, errors };
    }

    // Resolve the detected label to a MIME type
    detectedMimeType = MAGIKA_LABEL_TO_MIME[label] || `application/x-${label}`;

    // ── 4. Check detected MIME against allowed list ────────────────────────
    const ext = path.extname(filename).toLowerCase();
    const isZipBased = ZIP_BASED_EXTENSIONS.has(ext);

    // For zip-based formats, if magika detects 'zip', we use the extension's MIME instead
    let effectiveMimeType = detectedMimeType;
    if (isZipBased && label === 'zip') {
      const expectedMimes = EXTENSION_TO_MIME[ext];
      if (expectedMimes && expectedMimes.length > 0) {
        effectiveMimeType = expectedMimes[0];
      }
    }

    if (!ALLOWED_MIME_TYPES.includes(effectiveMimeType)) {
      errors.push({
        code: 'MIME_NOT_ALLOWED',
        message: `Detected content type "${effectiveMimeType}" (label: ${label}) is not in the allowed list. Accepted types: ${ALLOWED_MIME_TYPES.join(', ')}.`,
      });
    }

    // ── 5. Validate detected MIME matches file extension ──────────────────
    if (ext) {
      const expectedMimesForExt = EXTENSION_TO_MIME[ext];
      if (expectedMimesForExt) {
        const mimeMatchesExtension =
          expectedMimesForExt.includes(effectiveMimeType) ||
          (isZipBased && label === 'zip');

        if (!mimeMatchesExtension) {
          errors.push({
            code: 'MIME_EXTENSION_MISMATCH',
            message: `Detected content type "${effectiveMimeType}" (label: ${label}) does not match file extension "${ext}". Expected: ${expectedMimesForExt.join(' or ')}.`,
          });
        }
      } else {
        // Extension not in our known mapping - might be a mismatch
        errors.push({
          code: 'MIME_EXTENSION_MISMATCH',
          message: `File extension "${ext}" is not recognized. Cannot verify it matches detected content type "${effectiveMimeType}".`,
        });
      }
    }
  } catch (e: any) {
    logger.error('[FileValidation] Magika identification failed:', e);
    errors.push({
      code: 'MIME_DETECTION_FAILED',
      message: 'Content inspection failed unexpectedly. File type could not be verified.',
    });
  }

  return {
    valid: errors.length === 0,
    detectedMimeType,
    errors,
  };
}

// ─── Helper Functions ────────────────────────────────────────────────────────

/**
 * Checks if a filename contains path traversal sequences.
 * Detects: ../, ..\, //, null bytes (\0)
 */
export function containsPathTraversal(filename: string): boolean {
  if (filename.includes('\0')) return true;
  if (filename.includes('../')) return true;
  if (filename.includes('..\\')) return true;
  if (filename.includes('//')) return true;
  // Also catch bare '..' which could be used in path manipulation
  if (filename === '..' || filename.startsWith('..') && (filename[2] === '/' || filename[2] === '\\')) return true;
  return false;
}

/**
 * Resets the magika instance (useful for testing).
 * @internal
 */
export function _resetMagikaForTesting(): void {
  magikaInstance = null;
  magikaInitPromise = null;
}

/**
 * Job Payload Security Validator
 *
 * Runtime defense-in-depth validation ensuring job payloads never contain
 * sensitive data such as credentials, tokens, or session information.
 *
 * The typed JobDataMap already enforces safe payloads at compile time,
 * but this validator catches any runtime violations (e.g., from casts,
 * dynamic data, or compromised upstream code).
 *
 * Requirements: 11.4
 */

import logger from './logger.js';

/**
 * Fields that must never appear in job payloads.
 * Case-insensitive matching is applied.
 */
const SENSITIVE_FIELD_PATTERNS: string[] = [
  'password',
  'token',
  'secret',
  'apikey',
  'api_key',
  'sessionid',
  'session_id',
  'cookie',
  'authorization',
  'jwt',
  'accesstoken',
  'access_token',
  'refreshtoken',
  'refresh_token',
  'credential',
  'private_key',
  'privatekey',
];

export interface PayloadValidationResult {
  isValid: boolean;
  sensitiveFields: string[];
}

/**
 * Recursively checks an object for keys matching sensitive field patterns.
 * Returns a list of offending field paths (e.g., "metadata.token").
 */
function findSensitiveFields(
  obj: unknown,
  path: string = '',
): string[] {
  const found: string[] = [];

  if (obj === null || obj === undefined || typeof obj !== 'object') {
    return found;
  }

  // Handle arrays
  if (Array.isArray(obj)) {
    for (let i = 0; i < obj.length; i++) {
      found.push(...findSensitiveFields(obj[i], `${path}[${i}]`));
    }
    return found;
  }

  // Handle plain objects
  for (const key of Object.keys(obj)) {
    const normalizedKey = key.toLowerCase().replace(/[-_]/g, '');
    const currentPath = path ? `${path}.${key}` : key;

    for (const pattern of SENSITIVE_FIELD_PATTERNS) {
      const normalizedPattern = pattern.toLowerCase().replace(/[-_]/g, '');
      if (normalizedKey === normalizedPattern || normalizedKey.includes(normalizedPattern)) {
        found.push(currentPath);
        break;
      }
    }

    // Recurse into nested objects
    const value = (obj as Record<string, unknown>)[key];
    if (value !== null && typeof value === 'object') {
      found.push(...findSensitiveFields(value, currentPath));
    }
  }

  return found;
}

/**
 * Validates that a job payload does not contain sensitive fields.
 *
 * @param payload - The job data object to validate
 * @returns Validation result with list of any detected sensitive fields
 */
export function validateJobPayload(payload: unknown): PayloadValidationResult {
  const sensitiveFields = findSensitiveFields(payload);

  return {
    isValid: sensitiveFields.length === 0,
    sensitiveFields,
  };
}

/**
 * Validates and sanitizes a job payload by stripping sensitive fields.
 * Logs a warning if sensitive fields are detected and removed.
 *
 * @param jobType - The job type being enqueued (for logging context)
 * @param payload - The job data object to validate and sanitize
 * @returns The sanitized payload with sensitive fields removed
 * @throws Error if the payload contains sensitive fields (strict mode)
 */
export function assertJobPayloadSecurity(
  jobType: string,
  payload: unknown,
): void {
  const result = validateJobPayload(payload);

  if (!result.isValid) {
    const message = `[JobPayloadValidator] SECURITY: Job payload for "${jobType}" contains sensitive fields: [${result.sensitiveFields.join(', ')}]. Rejecting job.`;
    logger.error(message);
    throw new Error(
      `Job payload contains sensitive data. Detected fields: ${result.sensitiveFields.join(', ')}`,
    );
  }
}

