  }
}

/**
 * Unified Pagination Service for the AL-SAQI API.
 *
 * Provides consistent pagination logic across all list endpoints:
 * - Validates and parses `page` and `pageSize` query parameters
 * - Computes pagination metadata (totalPages, hasNext, hasPrev)
 * - Generates SQL LIMIT/OFFSET clauses
 *
 * Requirements: 5.1, 5.2, 5.3, 5.4, 5.5, 5.6, 5.7
 */

import { ValidationError } from './errors';
import type { PaginationMeta } from '../types/api';

/** Default page number when not provided */
export const DEFAULT_PAGE = 1;

/** Default page size when not provided */
export const DEFAULT_PAGE_SIZE = 20;

/** Maximum allowed page size (values above this are capped silently) */
export const MAX_PAGE_SIZE = 100;

/**
 * Parsed and validated pagination parameters.
 */
export interface ParsedPaginationParams {
  page: number;
  pageSize: number;
  offset: number;
}

/**
 * Parses and validates pagination query parameters.
 *
 * - Defaults to page 1, pageSize 20 when not provided
 * - Caps pageSize at 100 without error
 * - Rejects invalid page/pageSize (< 1, non-integer, non-numeric) with 400 ValidationError
 *
 * @param query - The query parameters object (typically req.query)
 * @returns Validated pagination parameters with computed offset
 * @throws ValidationError if page or pageSize is invalid
 */
export function parsePaginationParams(
  query: Record<string, any>
): ParsedPaginationParams {
  let page = DEFAULT_PAGE;
  let pageSize = DEFAULT_PAGE_SIZE;

  // Parse page parameter
  if (query.page !== undefined && query.page !== null && query.page !== '') {
    page = validatePaginationParam(query.page, 'page');
  }

  // Parse pageSize parameter
  if (query.pageSize !== undefined && query.pageSize !== null && query.pageSize !== '') {
    pageSize = validatePaginationParam(query.pageSize, 'pageSize');
    // Cap pageSize at MAX_PAGE_SIZE without error (Requirement 5.4)
    if (pageSize > MAX_PAGE_SIZE) {
      pageSize = MAX_PAGE_SIZE;
    }
  }

  const offset = (page - 1) * pageSize;

  return { page, pageSize, offset };
}

/**
 * Validates a single pagination parameter value.
 *
 * @param value - The raw query parameter value
 * @param paramName - The parameter name for error messages
 * @returns The validated integer value
 * @throws ValidationError if the value is non-numeric, non-integer, or less than 1
 */
function validatePaginationParam(value: any, paramName: string): number {
  // Convert to string for consistent parsing
  const strValue = String(value).trim();

  // Check if it's a valid number
  if (strValue === '' || isNaN(Number(strValue))) {
    throw new ValidationError(
      `Invalid ${paramName}: must be a positive integer`,
      { field: paramName, value, rule: 'numeric' }
    );
  }

  const numValue = Number(strValue);

  // Check if it's an integer
  if (!Number.isInteger(numValue)) {
    throw new ValidationError(
      `Invalid ${paramName}: must be an integer`,
      { field: paramName, value, rule: 'integer' }
    );
  }

  // Check if it's at least 1
  if (numValue < 1) {
    throw new ValidationError(
      `Invalid ${paramName}: must be greater than or equal to 1`,
      { field: paramName, value, rule: 'min' }
    );
  }

  return numValue;
}

/**
 * Computes pagination metadata from page, pageSize, and total record count.
 *
 * - totalPages = ceil(total / pageSize)
 * - hasNext = page < totalPages
 * - hasPrev = page > 1
 * - When page > totalPages: hasNext is false (empty data scenario)
 *
 * @param page - Current page number (1-based)
 * @param pageSize - Number of items per page
 * @param total - Total number of records
 * @returns PaginationMeta object
 */
export function computePaginationMeta(
  page: number,
  pageSize: number,
  total: number
): PaginationMeta {
  const totalPages = total === 0 ? 0 : Math.ceil(total / pageSize);
  const hasNext = page < totalPages;
  const hasPrev = page > 1;

  return {
    page,
    pageSize,
    total,
    totalPages,
    hasNext,
    hasPrev,
  };
}

/**
 * Appends LIMIT and OFFSET clauses to a SQL query string for pagination.
 *
 * @param query - The base SQL query string
 * @param page - Current page number (1-based)
 * @param pageSize - Number of items per page
 * @returns The query string with LIMIT and OFFSET appended
 */
export function paginateQuery(
  query: string,
  page: number,
  pageSize: number
): string {
  const offset = (page - 1) * pageSize;
  return `${query} LIMIT ${pageSize} OFFSET ${offset}`;
}

/**
 * Route Registry Utility
 * 
 * Detects duplicate route registrations at startup and logs warnings.
 * Also provides a 405 Method Not Allowed handler for custom routes
 * that don't implement all HTTP methods.
 * 
 * Uses a manual registration approach rather than introspecting Express internals,
 * which ensures compatibility across Express versions (including Express 5).
 */
import type { Request, Response, NextFunction } from 'express';

export interface RouteRegistration {
  method: string;
  path: string;
  source: string;
}

export interface DuplicateWarning {
  method: string;
  path: string;
  sources: string[];
}

/**
 * Global route registry that tracks all registered routes.
 * Routes are registered via `registerRoute()` and checked via `detectDuplicates()`.
 */
const registry: RouteRegistration[] = [];

/**
 * Registers a route in the global registry for duplicate detection.
 * Call this when registering routes to track them.
 * 
 * @param method - HTTP method (GET, POST, PUT, DELETE, PATCH, etc.)
 * @param path - The full route path (e.g., '/api/audit-tasks')
 * @param source - Identifier for where this route is registered (e.g., 'crudGenerator' or 'auditTasks.ts')
 */
export function registerRoute(method: string, path: string, source: string): void {
  registry.push({
    method: method.toUpperCase(),
    path: normalizePath(path),
    source,
  });
}

/**
 * Registers multiple routes for a given path prefix and source.
 * Convenience method for CRUD-style route registration.
 * 
 * @param methods - Array of HTTP methods
 * @param pathPrefix - The route path prefix
 * @param source - Identifier for the source of registration
 */
export function registerRoutes(methods: string[], pathPrefix: string, source: string): void {
  for (const method of methods) {
    registerRoute(method, pathPrefix, source);
  }
}

/**
 * Returns all registered routes (for testing/inspection).
 */
export function getRegisteredRoutes(): RouteRegistration[] {
  return [...registry];
}

/**
 * Clears the route registry. Primarily used in tests.
 */
export function clearRegistry(): void {
  registry.length = 0;
}

/**
 * Detects duplicate route registrations and returns warnings.
 * A duplicate is defined as the same HTTP method + normalized path registered more than once.
 */
export function detectDuplicates(routes?: RouteRegistration[]): DuplicateWarning[] {
  const routesToCheck = routes || registry;
  const seen = new Map<string, string[]>();

  for (const route of routesToCheck) {
    const key = `${route.method} ${route.path}`;
    const sources = seen.get(key) || [];
    sources.push(route.source);
    seen.set(key, sources);
  }

  const duplicates: DuplicateWarning[] = [];
  for (const [key, sources] of seen.entries()) {
    if (sources.length > 1) {
      const [method, ...pathParts] = key.split(' ');
      duplicates.push({
        method,
        path: pathParts.join(' '),
        sources,
      });
    }
  }

  return duplicates;
}

/**
 * Logs duplicate route warnings at startup.
 * Call this after all routes have been registered.
 * 
 * @returns Array of detected duplicate warnings
 */
export function logDuplicateRoutes(): DuplicateWarning[] {
  const duplicates = detectDuplicates();

  for (const dup of duplicates) {
    console.warn(
      `[RouteRegistry] Duplicate route detected: ${dup.method} ${dup.path} ` +
      `(registered by: ${dup.sources.join(', ')})`
    );
  }

  return duplicates;
}

/**
 * Middleware that returns 405 Method Not Allowed for HTTP methods
 * not implemented on a custom route.
 * 
 * @param allowedMethods - Array of HTTP methods that are implemented (e.g., ['GET', 'PATCH'])
 * @returns Express middleware that responds with 405 for disallowed methods
 */
export function methodNotAllowed(allowedMethods: string[]) {
  const allowed = allowedMethods.map(m => m.toUpperCase());
  
  return (req: Request, res: Response, _next: NextFunction) => {
    res.setHeader('Allow', allowed.join(', '));
    res.status(405).json({
      success: false,
      error: {
        code: 'METHOD_NOT_ALLOWED',
        message: `Method ${req.method} is not allowed on this resource. Allowed methods: ${allowed.join(', ')}`,
      },
    });
  };
}

function normalizePath(p: string): string {
  return p.replace(/\/+/g, '/').replace(/\/$/, '') || '/';
}

