      // Pattern: {entityType}/{entityId}/{timestamp}-{uuid}
      const filePart = key.split('/')[2];
      expect(filePart).toMatch(/^\d{8}T\d{6}-[0-9a-f\-]{36}$/);
    });

    it('omits extension when filename ends with a dot', () => {
