      expect(key).toMatch(/^[a-zA-Z0-9\/\-_.]+$/);
      expect(key).not.toContain(' ');
      expect(key).not.toContain('!');
    });

    it('generates key within 1024 character limit', () => {
      const entityRef: EntityRef = { type: 'audit', id: 'a'.repeat(100) };
      const key = generateStorageKey(entityRef, 'file.pdf');

      expect(key.length).toBeLessThanOrEqual(MAX_KEY_LENGTH);
    });

    it('throws when key would exceed 1024 characters', () => {
      const entityRef: EntityRef = { type: 'audit', id: 'a'.repeat(1000) };
      expect(() => generateStorageKey(entityRef, 'file.pdf')).toThrow(
        /exceeds 1024 characters/,
      );
    });

    it('produces only valid S3 key characters', () => {
      const entityRef: EntityRef = { type: 'report', id: 'rpt-123_v2' };
      const key = generateStorageKey(entityRef, 'Annual Report (2024).pdf');

      // After sanitization, the key should only contain valid chars
      expect(key).toMatch(/^[a-zA-Z0-9\/\-_.]+$/);
    });

    it('works with all entity types', () => {
      const types: EntityType[] = ['audit', 'finding', 'recommendation', 'report'];
      for (const type of types) {
        const entityRef: EntityRef = { type, id: 'test-123' };
        const key = generateStorageKey(entityRef, 'file.pdf');
        expect(key).toContain(`${type}/`);
      }
    });

    it('handles filename with only null bytes', () => {
      const entityRef: EntityRef = { type: 'audit', id: 'a1' };
      // After sanitization, filename becomes empty, so no extension
      const key = generateStorageKey(entityRef, '\0\0\0');
      const filePart = key.split('/')[2];
      expect(filePart).toMatch(/^\d{8}T\d{6}-[0-9a-f\-]{36}$/);
    });

    it('handles filename with only path separators', () => {
      const entityRef: EntityRef = { type: 'audit', id: 'a1' };
      const key = generateStorageKey(entityRef, '///\\\\');
      const filePart = key.split('/')[2];
      // No extension since sanitized filename is empty
      expect(filePart).toMatch(/^\d{8}T\d{6}-[0-9a-f\-]{36}$/);
    });
  });
});

/**
 * Storage Key Generation
 *
 * Generates unique, collision-free storage keys for MinIO/S3 object storage.
 * Keys follow the pattern: {entityType}/{entityId}/{timestamp}-{uuid}.{ext}
 *
 * Requirements: 6.1, 6.2, 6.3, 6.4, 6.5, 6.6
 */

import { v4 as uuidv4 } from 'uuid';

// ─── Types ───────────────────────────────────────────────────────────────────

export type EntityType = 'audit' | 'finding' | 'recommendation' | 'report';

export interface EntityRef {
  type: EntityType;
  id: string;
}

// ─── Constants ───────────────────────────────────────────────────────────────

/** Maximum allowed length for an S3 object key */
export const MAX_KEY_LENGTH = 1024;

/**
 * Valid S3 key characters regex.
 * S3 keys can contain: alphanumeric, forward slash, dash, underscore, dot, and more.
 * We restrict to safe characters: a-z, A-Z, 0-9, /, -, _, .
 */
const VALID_S3_KEY_REGEX = /^[a-zA-Z0-9\/\-_.]+$/;

// ─── Sanitization ────────────────────────────────────────────────────────────

/**
 * Sanitizes a filename by removing path traversal and dangerous characters.
 * Removes: forward slash (/), backslash (\), dot-dot sequences (..), null bytes.
 *
 * Requirements: 6.5
 */
export function sanitizeFilename(filename: string): string {
  let sanitized = filename;

  // Remove null bytes
  sanitized = sanitized.replace(/\0/g, '');

  // Remove backslashes
  sanitized = sanitized.replace(/\\/g, '');

  // Remove forward slashes
  sanitized = sanitized.replace(/\//g, '');

  // Remove dot-dot sequences (repeatedly to handle nested cases like ....)
  while (sanitized.includes('..')) {
    sanitized = sanitized.replace(/\.\./g, '');
  }

  return sanitized;
}

// ─── Extension Extraction ────────────────────────────────────────────────────

/**
 * Extracts and lowercases the file extension from a sanitized filename.
 * Returns undefined if no extension is present.
 *
 * Requirements: 6.2, 6.3
 */
export function extractExtension(sanitizedFilename: string): string | undefined {
  const lastDot = sanitizedFilename.lastIndexOf('.');
  if (lastDot <= 0 || lastDot === sanitizedFilename.length - 1) {
    // No dot found, dot is at the start (hidden file), or dot is the last character
    return undefined;
  }

  const ext = sanitizedFilename.slice(lastDot + 1).toLowerCase();
  if (ext.length === 0) {
    return undefined;
  }

  return ext;
}

// ─── Timestamp Generation ────────────────────────────────────────────────────

/**
 * Generates an ISO-like timestamp string for lexicographic sorting.
 * Format: YYYYMMDDTHHmmss
 *
 * Requirements: 6.1
 */
export function generateTimestamp(date: Date = new Date()): string {
  const year = date.getUTCFullYear().toString().padStart(4, '0');
  const month = (date.getUTCMonth() + 1).toString().padStart(2, '0');
  const day = date.getUTCDate().toString().padStart(2, '0');
  const hours = date.getUTCHours().toString().padStart(2, '0');
  const minutes = date.getUTCMinutes().toString().padStart(2, '0');
  const seconds = date.getUTCSeconds().toString().padStart(2, '0');

  return `${year}${month}${day}T${hours}${minutes}${seconds}`;
}

// ─── Key Generation ──────────────────────────────────────────────────────────

/**
 * Generates a unique storage key for an entity's file.
 *
 * Pattern: {entityType}/{entityId}/{timestamp}-{uuid}.{ext}
 *
 * - Sanitizes the filename before extracting the extension
 * - Extension is lowercase; omitted entirely if missing (no trailing dot)
 * - UUID v4 ensures global uniqueness
 * - Key is ≤ 1024 characters with valid S3 characters only
 *
 * Requirements: 6.1, 6.2, 6.3, 6.4, 6.5, 6.6
 *
 * @param entityRef - Entity type and ID for organization
 * @param filename - Original filename (will be sanitized)
 * @returns Generated storage key
 * @throws Error if the generated key exceeds 1024 characters
 */
export function generateStorageKey(
  entityRef: EntityRef,
  filename: string,
): string {
  // Step 1: Sanitize the filename
  const sanitized = sanitizeFilename(filename);

  // Step 2: Extract and lowercase extension
  const ext = extractExtension(sanitized);

  // Step 3: Generate timestamp
  const timestamp = generateTimestamp();

  // Step 4: Generate UUID v4
  const uuid = uuidv4();

  // Step 5: Sanitize the entity ID (remove invalid S3 characters)
  const safeEntityId = entityRef.id.replace(/[^a-zA-Z0-9\-_\.]/g, '_');

  // Step 6: Compose the key
  const filenamePart = ext
    ? `${timestamp}-${uuid}.${ext}`
    : `${timestamp}-${uuid}`;

  const key = `${entityRef.type}/${safeEntityId}/${filenamePart}`;

  // Step 7: Validate key length
  if (key.length > MAX_KEY_LENGTH) {
    throw new Error(
      `Generated storage key exceeds ${MAX_KEY_LENGTH} characters (got ${key.length})`,
    );
  }

  // Step 8: Validate all characters are valid S3 key characters
  if (!VALID_S3_KEY_REGEX.test(key)) {
    throw new Error(
      'Generated storage key contains invalid S3 characters',
    );
  }

  return key;
}

/**
 * Property-based test for Temp Cleanup Age Filter.
 *
 * **Validates: Requirements 10.2**
 *
 * Property 8: Temp Cleanup Age Filter
 * For any set of objects in the temp bucket, the cleanup-temp worker SHALL delete
 * all and only those objects with a creation timestamp older than 24 hours.
 * Objects younger than 24 hours SHALL remain untouched.
 */

import { describe, it, expect, vi, afterEach } from 'vitest';
import fc from 'fast-check';
import type { Job } from 'bullmq';
import type { WorkerContext } from '../../services/worker-manager.js';
import type { JobDataMap } from '../../services/queue.service.js';
import type { StorageObject } from '../../services/storage.service.js';
import { cleanupTempWorker } from '../cleanup-temp.worker.js';

// ─── Generators ────────────────────────────────────────────────────────────────

/**
 * Generate an olderThanMs threshold (the configurable cutoff).
 * Default is 24 hours (86400000ms), but we test with various thresholds.
 */
const thresholdMsArb: fc.Arbitrary<number> = fc.constantFrom(
  86_400_000, // 24 hours (default)
  86_400_000, // Weighted towards default
  86_400_000, // Weighted towards default
  3_600_000, // 1 hour
  2 * 86_400_000, // 48 hours
);

/**
 * Generate a random storage object key.
 */
const objectKeyArb: fc.Arbitrary<string> = fc.oneof(
  fc.stringMatching(/^[a-z0-9_-]{1,32}\.[a-z]{2,4}$/),
  fc.tuple(
    fc.stringMatching(/^[a-z]{1,8}$/),
    fc.stringMatching(/^[a-z0-9]{1,12}$/),
    fc.constantFrom('.pdf', '.docx', '.png', '.jpg', '.xlsx'),
  ).map(([prefix, name, ext]) => `pending/${prefix}/${name}${ext}`),
);

/**
 * Generate a positive file size (1 byte to 50MB).
 */
const fileSizeArb: fc.Arbitrary<number> = fc.integer({ min: 1, max: 50 * 1024 * 1024 });

/**
 * Generate an etag string.
 */
const etagArb: fc.Arbitrary<string> = fc.stringMatching(/^[a-f0-9]{32}$/);

/**
 * Generate an age offset in milliseconds.
 * Ranges from 1 second to 7 days to cover objects both younger and older than threshold.
 */
const ageOffsetMsArb: fc.Arbitrary<number> = fc.integer({
  min: 1_000, // 1 second
  max: 7 * 24 * 60 * 60 * 1000, // 7 days
});

/**
 * Generate a StorageObject with a specific lastModified date based on a given reference time and offset.
 */
const storageObjectArb = (referenceTime: number): fc.Arbitrary<StorageObject> =>
  fc.tuple(objectKeyArb, fileSizeArb, etagArb, ageOffsetMsArb).map(
    ([key, size, etag, ageMs]) => ({
      key,
      size,
      etag,
      lastModified: new Date(referenceTime - ageMs),
    }),
  );

/**
 * Generate a list of 0–20 storage objects with various ages.
 */
const objectListArb = (referenceTime: number): fc.Arbitrary<StorageObject[]> =>
  fc.array(storageObjectArb(referenceTime), { minLength: 0, maxLength: 20 });

// ─── Helpers ───────────────────────────────────────────────────────────────────

function createJob(olderThanMs: number): Job<JobDataMap['cleanup-temp']> {
  return {
    data: { olderThanMs },
  } as Job<JobDataMap['cleanup-temp']>;
}

function createMockContext() {
  const deletedKeys: string[] = [];

  const mockStorage = {
    listObjects: vi.fn(),
    delete: vi.fn().mockImplementation(async (key: string) => {
      deletedKeys.push(key);
    }),
    upload: vi.fn(),
    download: vi.fn(),
    getPresignedUrl: vi.fn(),
    copy: vi.fn(),
    exists: vi.fn(),
  };

  const mockLogger = {
    info: vi.fn(),
    error: vi.fn(),
    warn: vi.fn(),
