const targetBucketArb = fc.constantFrom('evidence' as const, 'reports' as const);

// ─── Property Tests ────────────────────────────────────────────────────────────

describe('Property 7: Idempotent Job Processing', () => {
  /**
   * **Validates: Requirements 9.5**
   *
