              copy: vi.fn().mockImplementation(async () => {
                totalCopyCalls++;
                fileInPermanent = true;
                storedContent = Buffer.from(content);
                return { key: storageKey, bucket: 'evidence', etag: 'etag', size: content.length, url: '' };
              }),
