import i18next from 'i18next';

/**
 * Extracts a displayable error message string from an API error response.
 * Handles both old format ({ error: "string" }) and new format ({ error: { code, message, traceId } }).
 */
export const extractErrorMessage = (error: any, fallback?: string): string => {
  const data = error?.response?.data;
  if (!data) return fallback || i18next.t('errorOccurred');

  const errorField = data.error;
  if (typeof errorField === 'string') return errorField;
  if (typeof errorField === 'object' && errorField?.message) return errorField.message;
  if (typeof data.message === 'string') return data.message;

  return fallback || i18next.t('errorOccurred');
};

/**
 * Translates error messages from the backend to the current language
 */
export const translateError = (error: string | { message?: string; error?: string } | null | undefined, language: 'en' | 'ar'): string => {
  const t = (key: string, options?: Record<string, unknown>) => i18next.t(key, { lng: language, ...options });
  
  if (!error) return t('errorOccurred');
  
  const message = typeof error === 'string' ? error : (error.message || error.error || '');
  
  // Map common backend error strings to translation keys
  const errorMap: Record<string, string> = {
    'Unauthorized': t('unauthorized'),
    'Forbidden': t('forbidden'),
    'Not Found': t('notFound'),
    'Internal Server Error': t('serverError'),
    'Network Error': t('networkError'),
    'Invalid credentials': t('failedLogin'),
    'Account locked': t('accountLocked'),
    'Account suspended': t('auth.accountSuspended'),
    'Account suspended, disabled or archived': t('auth.accountSuspended'),
    'Session expired': t('sessionExpired'),
    'Session invalidated': t('sessionExpired'),
    'Invalid data': t('invalidData'),
    'Invalid option': t('validationErrors.invalidOption'),
    'expected string': t('validationErrors.expectedString'),
    'Required': t('validationErrors.required'),
    'too_small': t('validationErrors.tooShort'),
    'too_big': t('validationErrors.tooLong'),
    'TOO_MANY_ATTEMPTS': t('auth.tooManyAttempts'),
    'Too many requests': t('auth.tooManyAttempts'),
    'Invalid token': t('sessionExpired'),
    'User not found': t('failedLogin'),
    'Password change required': t('passwordChangeRequired'),
    'New password cannot be the same as the current password': t('auth.cannotUseSamePassword'),
    'Password has been used previously. Please choose a different one.': t('auth.passwordUsedBefore'),
    'Password must be at least': t('auth.ruleMinLength'),
    'Password must contain at least one uppercase letter': t('auth.ruleUppercaseRequired'),
    'Password must contain at least one lowercase letter': t('auth.ruleLowercaseRequired'),
    'Password must contain at least one number': t('auth.ruleNumberRequired'),
    'Password must contain at least one special character': t('auth.ruleSymbolRequired'),
    'Forbidden: Insufficient permissions': t('forbidden'),
    'An unexpected error occurred': t('errorOccurred'),
    'Missing required fields': t('validationErrors.required'),
    'Not implemented': t('featureUnderDevelopment'),
  };

  // Check if the message matches any known error
  for (const [key, value] of Object.entries(errorMap)) {
    if (message.includes(key)) return value;
  }

  // Handle Zod validation patterns
  if (message.includes('Invalid option: expected one of')) {
    return t('validationErrors.invalidOption');
  }
  if (message.includes('Invalid input: expected')) {
    return t('validationErrors.invalidInput');
  }

  // Fallback to the original message if it's already translated or just return generic error
  return message || t('errorOccurred');
};

import cron from 'node-cron';
import { db } from '../server/db/index';

export const createNotification = async (userId: number | 'all', eventType: string, description: string, relatedModule: string, link: string = '') => {
  try {
    if (userId === 'all') {
      const users = await db.prepare("SELECT id FROM users").all() as { id: number }[];
      const stmt = db.prepare(`INSERT INTO notifications (user_id, event_type, description, related_module, link) VALUES (?, ?, ?, ?, ?)`);
      const transaction = db.transaction(async (usersList: any[]) => {
        for (const user of usersList) {
          await stmt.run(user.id, eventType, description, relatedModule, link);
        }
      });
      await transaction(users);
    } else {
      await db.prepare(`INSERT INTO notifications (user_id, event_type, description, related_module, link) VALUES (?, ?, ?, ?, ?)`).run(userId, eventType, description, relatedModule, link);
    }
  } catch (error) {
    console.error("Error creating notification:", error);
  }
};

export const initNotificationScheduler = () => {
  // Run every day at 08:00
  cron.schedule('0 8 * * *', () => {
    checkOverdueItems();
  });
};

const checkOverdueItems = async () => {
  // Check overdue recommendations
  const overdueRecs = await db.prepare(`
    SELECT r.*, a.title as audit_title 
    FROM recommendations r
    JOIN audit_plans a ON r.audit_id = a.id
    WHERE r.due_date < CURRENT_DATE AND r.status != 'Closed'
  `).all() as any[];

  for (const rec of overdueRecs) {
    const description = `توصية متأخرة: ${rec.recommendation} في التدقيق ${rec.audit_title}. تاريخ الاستحقاق كان ${rec.due_date}`;
    createNotification(rec.responsible_id || 'all', 'Overdue', description, 'AuditTasks', '/tasks');
  }
};

import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { TAHOMA_FONT_BASE64 } from '../assets/fonts/tahoma-base64';
import i18n from '../i18n';

const t = i18n.t.bind(i18n);

/**
 * PDF Service - Generates audit reports with full Arabic/English support.
 * Uses embedded Tahoma font for Arabic text rendering (no internet required).
 */

// Register the Arabic font once
let fontRegistered = false;

function registerArabicFont(doc: jsPDF) {
  if (!fontRegistered) {
    doc.addFileToVFS('Tahoma.ttf', TAHOMA_FONT_BASE64);
    doc.addFont('Tahoma.ttf', 'Tahoma', 'normal');
    fontRegistered = true;
  } else {
    // Font already in VFS from a previous call, just re-add to this doc instance
    doc.addFileToVFS('Tahoma.ttf', TAHOMA_FONT_BASE64);
    doc.addFont('Tahoma.ttf', 'Tahoma', 'normal');
  }
}

export interface AuditReportData {
  title?: string;
  planCode?: string;
  department?: string;
  leadAuditor?: string;
  status?: string;
  startDate?: string;
  endDate?: string;
  tasks?: Array<{ title: string; status: string; assignee?: string }>;
  findings?: Array<{ title: string; riskLevel: string; description?: string }>;
  recommendations?: Array<{ action: string; status: string; deadline?: string }>;
}

export const generateAuditReport = async (data: AuditReportData, options: { language: 'ar' | 'en' }) => {
  const doc = new jsPDF({
    orientation: 'p',
    unit: 'mm',
    format: 'a4',
  });

  const isRtl = options.language === 'ar';
  
  // Register and set Arabic font
  registerArabicFont(doc);
  doc.setFont('Tahoma');

  const pageWidth = doc.internal.pageSize.getWidth();
  const margin = 15;
  const contentWidth = pageWidth - margin * 2;
  let y = 20;

  // === Header ===
  doc.setFontSize(18);
  const title = data.title || t('export.internalAuditReport');
  doc.text(title, pageWidth / 2, y, { align: 'center' });
  y += 12;

  // Divider line
  doc.setDrawColor(41, 128, 185);
  doc.setLineWidth(0.5);
  doc.line(margin, y, pageWidth - margin, y);
  y += 10;

  // === Report Info ===
  doc.setFontSize(10);
  const infoItems = [
    { label: t('export.planCode'), value: data.planCode || '-' },
    { label: t('export.department'), value: data.department || '-' },
    { label: t('export.leadAuditor'), value: data.leadAuditor || '-' },
    { label: t('export.status'), value: data.status || '-' },
    { label: t('export.startDate'), value: data.startDate || '-' },
    { label: t('export.endDate'), value: data.endDate || '-' },
  ];

  for (const item of infoItems) {
    const text = `${item.label}: ${item.value}`;
    doc.text(text, isRtl ? pageWidth - margin : margin, y, { align: isRtl ? 'right' : 'left' });
    y += 6;
  }
  y += 8;

  // === Tasks Table ===
  if (data.tasks && data.tasks.length > 0) {
    doc.setFontSize(13);
    const tasksTitle = t('export.tasks');
    doc.text(tasksTitle, isRtl ? pageWidth - margin : margin, y, { align: isRtl ? 'right' : 'left' });
    y += 8;

    const taskHeaders = isRtl 
      ? [t('export.taskStatus'), t('export.assignedTo'), t('export.task'), '#']
      : ['#', t('export.task'), t('export.assignedTo'), t('export.taskStatus')];

    const taskRows = data.tasks.map((t, i) => {
      const row = [String(i + 1), t.title, t.assignee || '-', t.status];
      return isRtl ? row.reverse() : row;
    });

    (doc as any).autoTable({
      startY: y,
      head: [taskHeaders],
      body: taskRows,
      styles: {
        font: 'Tahoma',
        fontSize: 9,
        halign: isRtl ? 'right' : 'left',
        cellPadding: 3,
      },
      headStyles: {
        fillColor: [41, 128, 185],
        textColor: [255, 255, 255],
        fontStyle: 'bold',
        halign: 'center',
      },
      margin: { left: margin, right: margin },
    });
    y = (doc as any).lastAutoTable.finalY + 12;
  }

  // === Findings Table ===
  if (data.findings && data.findings.length > 0) {
    // Check if we need a new page
    if (y > 240) { doc.addPage(); y = 20; }

    doc.setFontSize(13);
    const findingsTitle = t('export.findings');
    doc.text(findingsTitle, isRtl ? pageWidth - margin : margin, y, { align: isRtl ? 'right' : 'left' });
    y += 8;

    const findingHeaders = isRtl
      ? [t('export.riskLevel'), t('export.description'), t('export.finding'), '#']
      : ['#', t('export.finding'), t('export.description'), t('export.riskLevel')];

    const findingRows = data.findings.map((f, i) => {
      const row = [String(i + 1), f.title, f.description || '-', f.riskLevel];
      return isRtl ? row.reverse() : row;
    });

    (doc as any).autoTable({
      startY: y,
      head: [findingHeaders],
      body: findingRows,
      styles: {
        font: 'Tahoma',
        fontSize: 9,
        halign: isRtl ? 'right' : 'left',
        cellPadding: 3,
      },
      headStyles: {
        fillColor: [192, 57, 43],
        textColor: [255, 255, 255],
        fontStyle: 'bold',
        halign: 'center',
      },
      margin: { left: margin, right: margin },
    });
    y = (doc as any).lastAutoTable.finalY + 12;
  }

  // === Recommendations Table ===
  if (data.recommendations && data.recommendations.length > 0) {
    if (y > 240) { doc.addPage(); y = 20; }

    doc.setFontSize(13);
    const recTitle = t('export.recommendations');
    doc.text(recTitle, isRtl ? pageWidth - margin : margin, y, { align: isRtl ? 'right' : 'left' });
    y += 8;

    const recHeaders = isRtl
      ? [t('export.deadline'), t('export.recStatus'), t('export.action'), '#']
      : ['#', t('export.action'), t('export.recStatus'), t('export.deadline')];

    const recRows = data.recommendations.map((r, i) => {
      const row = [String(i + 1), r.action, r.status, r.deadline || '-'];
      return isRtl ? row.reverse() : row;
    });

    (doc as any).autoTable({
      startY: y,
      head: [recHeaders],
      body: recRows,
      styles: {
        font: 'Tahoma',
        fontSize: 9,
        halign: isRtl ? 'right' : 'left',
        cellPadding: 3,
      },
      headStyles: {
        fillColor: [39, 174, 96],
        textColor: [255, 255, 255],
        fontStyle: 'bold',
        halign: 'center',
      },
      margin: { left: margin, right: margin },
    });
  }

  // === Footer on all pages ===
  const pageCount = (doc as any).internal.getNumberOfPages();
  const pageHeight = doc.internal.pageSize.getHeight();
  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(128);
    const footerText = t('export.pageOf', { current: i, total: pageCount });
    doc.text(footerText, pageWidth / 2, pageHeight - 10, { align: 'center' });
    
    const dateText = new Date().toLocaleDateString(isRtl ? 'ar-SA' : 'en-US');
    doc.text(dateText, isRtl ? margin : pageWidth - margin, pageHeight - 10, { align: isRtl ? 'left' : 'right' });
    doc.setTextColor(0);
  }

  doc.save(`${title.replace(/\s+/g, '_')}_${Date.now()}.pdf`);
};

/**
 * Custom fast-check Arbitraries (Generators)
 *
 * Provides reusable generators for property-based testing across the AL-SAQI system.
 * Uses constants from src/constants.ts for enum values and matches existing Zod schemas.
 */
import fc from 'fast-check';
import {
  UserRole,
  AuditType,
  RiskLevel,
  CorrespondencePriority,
  CorrespondenceClassification,
  CorrespondenceStatus,
  SendingMethod,
  EntityType,
} from '../../constants';

// ─── 1. User-related Arbitraries ─────────────────────────────────────────────

/** Generates valid UserRole enum values */
export const userRoleArb = fc.constantFrom(
  UserRole.ADMIN,
  UserRole.INTERNAL_AUDITOR,
  UserRole.COMPLIANCE_OFFICER,
  UserRole.RISK_OFFICER,
  UserRole.MANAGER,
  UserRole.VIEWER
);

/** Generates valid usernames (3-50 chars, alphanumeric + underscore) */
export const validUsernameArb = fc.stringMatching(/^[a-zA-Z][a-zA-Z0-9_]{2,49}$/);

/** Generates valid email addresses */
export const validEmailArb = fc.tuple(
  fc.stringMatching(/^[a-z][a-z0-9]{2,10}$/),
  fc.constantFrom('test.com', 'example.org', 'company.io', 'mail.net')
).map(([local, domain]) => `${local}@${domain}`);

/** Generates valid passwords (6-100 chars) */
export const validPasswordArb = fc.string({ minLength: 6, maxLength: 100 }).filter(
  (s) => s.length >= 6 && s.length <= 100
);

/** Generates valid user objects */
export const userArb = fc.record({
  id: fc.uuid(),
  username: validUsernameArb,
  email: validEmailArb,
  role: userRoleArb,
  name: fc.string({ minLength: 2, maxLength: 50 }).filter((s) => s.trim().length >= 2),
  status: fc.constantFrom('Active' as const, 'Disabled' as const),
  failed_attempts: fc.integer({ min: 0, max: 10 }),
  session_version: fc.integer({ min: 1, max: 100 }),
});

// ─── 2. Database-related Arbitraries ─────────────────────────────────────────

/** List of allowed tables from crudGenerator.ts */
const ALLOWED_TABLES = [
  'audit_plans',
