// ==================== SecureNetwork.ts ====================
import { CryptoUtils } from './CryptoUtils';

export interface SecureNetworkConfig {
    allowedOrigins?: string[];
    blockedPatterns?: RegExp[];
}

export class SecureNetwork {
    private allowedOrigins: string[];
    private blockedPatterns: RegExp[];
    private hmacKey: CryptoKey | null = null;
    private ready: Promise<void>;

    constructor(config: SecureNetworkConfig = {}) {
        this.allowedOrigins = config.allowedOrigins || [window.location.origin];
        this.blockedPatterns = config.blockedPatterns || [
            /<script/i,
            /onerror=/i,
            /javascript:/i
        ];
        this.ready = this.initKeys();
        
        if (typeof window !== 'undefined' && !(window as any).__secureNetworkInitialized) {
            this.initInterceptors();
            (window as any).__secureNetworkInitialized = true;
        }
    }

    private async initKeys() {
        // Derive key from env variable; in production VITE_NETWORK_SECRET must be set
        const baseKey = import.meta.env.VITE_NETWORK_SECRET || 
            (typeof window !== 'undefined' ? `${window.location.origin}-${navigator.userAgent.slice(0, 32)}` : 'dev-only-key');
        this.hmacKey = await CryptoUtils.importHMACKey(baseKey);
    }

    private initInterceptors() {
        const self = this;
        const originalFetch = window.fetch;

        try {
            Object.defineProperty(window, 'fetch', {
                value: async function(input: RequestInfo | URL, init?: RequestInit) {
                    await self.ready;
                    const url = typeof input === 'string' ? input : (input instanceof URL ? input.href : input.url);
                    let options = init || {};

                    try {
                        // Ensure absolute URL for safety check
                        const targetUrl = new URL(url, window.location.origin);
                        
                        if (!self.isAllowedOrigin(targetUrl.origin)) {
                            console.error(`[Security] Blocked unauthorized origin: ${targetUrl.origin}`);
                            throw new Error('Unauthorized request origin');
                        }

                        // XSS Payload detection
                        if (options.body && typeof options.body === 'string') {
                            if (self.containsBlockedPattern(options.body)) {
                                throw new Error('Request payload blocked for security');
                            }
                        }

                        // Sign request
                        const secureOptions = await self.signRequest(options);
                        const response = await originalFetch.call(this, input, secureOptions);
                        
                        // Integrity check for text responses
                        const clonedResp = response.clone();
                        const contentType = response.headers.get('content-type');
                        if (contentType && (contentType.includes('json') || contentType.includes('text'))) {
                            const body = await clonedResp.text();
                            const signature = response.headers.get('x-response-signature');
                            
                            if (signature && !(await self.verifyResponse(body, signature))) {
                                throw new Error('Response integrity check failed');
                            }
                        }

                        return response;
                    } catch (error: any) {
                        console.warn('[Security] Network Guard:', error.message);
                        throw error;
                    }
                },
                configurable: true,
                enumerable: true,
                writable: true
            });
        } catch (e) {
            console.warn('[Security] Could not override window.fetch, skipping network interceptor.', e);
        }

        // Protected XHR
        try {
            const OriginalProt = window.XMLHttpRequest.prototype;
            const originalSend = OriginalProt.send;
            const originalOpen = OriginalProt.open;

            OriginalProt.open = function(method: string, url: string | URL, ...rest: any[]) {
                (this as any).__method = method;
                (this as any).__url = url;
                return originalOpen.apply(this, [method, url, ...rest] as any);
            };
            
            OriginalProt.send = function(body?: any) {
                if (body && typeof body === 'string' && self.containsBlockedPattern(body)) {
                    console.error('[Security] XHR Content blocked');
                    throw new Error('XHR Content blocked');
                }

                // We can't easily wait for self.ready here without making it async, 
                // but for blocking patterns we don't need the key.
                return originalSend.apply(this, arguments as any);
            };
        } catch (e) {
            console.warn('[Security] Could not override XMLHttpRequest, skipping XHR interceptor.', e);
        }
    }

    private isAllowedOrigin(origin: string) {
        return this.allowedOrigins.some(allowed => origin.startsWith(allowed));
    }

    private containsBlockedPattern(data: string) {
        return this.blockedPatterns.some(pattern => pattern.test(data));
    }

    private async signRequest(options: RequestInit): Promise<RequestInit> {
        if (!this.hmacKey) return options;
        const ts = Date.now().toString();
        const nonce = crypto.randomUUID();
        const signature = await CryptoUtils.sign(`${ts}:${nonce}`, this.hmacKey);
        
        return {
            ...options,
            headers: {
                ...(options.headers || {}),
                'x-sec-ts': ts,
                'x-sec-nonce': nonce,
                'x-sec-sig': signature
            }
        };
    }

    private async verifyResponse(body: string, signature: string) {
        if (!this.hmacKey) return true;
        return await CryptoUtils.verify(body, signature, this.hmacKey);
    }
}

export const initSecureNetwork = (config?: SecureNetworkConfig) => new SecureNetwork(config);

// ==================== SecureStorage.ts ====================

import { CryptoUtils } from './CryptoUtils';

export class SecureStorage {
  private prefix: string;
  private encryptionKey: CryptoKey | null = null;
  private hmacKey: CryptoKey | null = null;
  private tamperDetection: Map<string, number>;
  private ready: Promise<void>;

  constructor(prefix: string = 'myApp') {
      this.prefix = prefix;
      this.tamperDetection = new Map();
      this.ready = this.initKeys();
      this.initProtection();
  }

  private async initKeys() {
      // في الإنتاج: يفضل جلب المفتاح الملح من الخادم
      // fetch('/api/security/init').then(r => r.json())...
      const baseKey = import.meta.env.VITE_STORAGE_SECRET || (typeof navigator !== 'undefined' ? `${navigator.userAgent.slice(0, 32)}-${window.location.origin}` : 'dev-only-storage-key');
      
      this.encryptionKey = await CryptoUtils.importKey(baseKey);
      this.hmacKey = await CryptoUtils.importHMACKey(baseKey);
  }

  private async encrypt(data: string): Promise<string> {
      await this.ready;
      if (!this.encryptionKey) throw new Error('Security not initialized');
      return await CryptoUtils.encrypt(data, this.encryptionKey);
  }

  private async decrypt(data: string): Promise<string | null> {
      await this.ready;
      if (!this.encryptionKey) return null;
      return await CryptoUtils.decrypt(data, this.encryptionKey);
  }

  private async hash(data: string): Promise<string> {
      await this.ready;
      if (!this.hmacKey) return '0';
      return await CryptoUtils.sign(data, this.hmacKey);
  }

  private initProtection() {
      // حماية التخزين الأصلي (نفس المنطق لكن مع دعم الوعود)
      const original = {
          getItem: Storage.prototype.getItem,
          setItem: Storage.prototype.setItem,
          removeItem: Storage.prototype.removeItem
      };

      const self = this;
      
      // ملاحظة: لا يمكن تغيير getItem لتكون async فعلياً لأنها خاصية موروثة تعتمد عليها المتصفحات
      // لكن يمكننا كشف التلاعب عند الاستدعاء
      Storage.prototype.getItem = function(key: string) {
          const value = original.getItem.call(this, key);
          
          if (key && key.startsWith(self.prefix + '_')) {
              const storedHash = original.getItem.call(this, key + '_hash');
              if (storedHash && value) {
                  // نتحقق بشكل غير متزامن في الخلفية لعدم تعطيل الـ UI
                  self.hash(value).then(h => {
                      if (h !== storedHash) {
                          console.error(`[Security] Tampering detected on key: ${key}`);
                          self.onTamperDetected(key, 'hash_mismatch');
                      }
                  });
              }
          }
          
          return value;
      };

      Storage.prototype.removeItem = function(key: string) {
          if (key && key.startsWith(self.prefix + '_') && !key.endsWith('_hash')) {
              const protectedKeys = ['user_token', 'session_data', 'config'];
              const baseKey = key.replace(self.prefix + '_', '');
              
              if (protectedKeys.includes(baseKey)) {
                  console.warn(`[Security] Blocked unauthorized removal of: ${key}`);
                  self.onTamperDetected(key, 'removal_blocked');
                  return;
              }
          }
          return original.removeItem.call(this, key);
      };
  }

  private onTamperDetected(key: string, reason: string) {
      this.sendSecurityAlert({
          type: 'storage_tampering',
          key,
          reason,
          timestamp: new Date().toISOString()
      });
      this.clearSession();
  }

  private async sendSecurityAlert(alert: any) {
      try {
          await fetch('/api/security/alert', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify(alert)
          });
      } catch (e) {}
  }

  // ========== API عام ==========

  async set(key: string, value: any) {
      await this.ready;
      const fullKey = `${this.prefix}_${key}`;
      const serialized = JSON.stringify(value);
      const encrypted = await this.encrypt(serialized);
      const hash = await this.hash(encrypted);

      localStorage.setItem(fullKey, encrypted);
      localStorage.setItem(fullKey + '_hash', hash);
      
      this.tamperDetection.set(fullKey, Date.now());
  }

  async get(key: string) {
      await this.ready;
      const fullKey = `${this.prefix}_${key}`;
      const encrypted = localStorage.getItem(fullKey);
      
      if (!encrypted) return null;

      const lastAccess = this.tamperDetection.get(fullKey);
      if (lastAccess && Date.now() - lastAccess < 100) {
          console.warn(`[Security] Rapid access detected on: ${key}`);
      }

      const decrypted = await this.decrypt(encrypted);
      if (!decrypted) {
          this.onTamperDetected(fullKey, 'decryption_failed');
          return null;
      }

      try {
          return JSON.parse(decrypted);
      } catch {
          this.onTamperDetected(fullKey, 'parse_error');
          return null;
      }
  }

  clearSession() {
      Object.keys(localStorage)
          .filter(k => k.startsWith(this.prefix + '_'))
          .forEach(k => localStorage.removeItem(k));
      
      sessionStorage.clear();
  }
}

export const secureStore = new SecureStorage('myApp');

// ==================== SecurityLogger.ts ====================

export interface SecurityLoggerConfig {
    endpoint?: string;
    flushInterval?: number;
    maxBufferSize?: number;
    onAlert?: (eventType: string, details: any) => void;
}

export class SecurityLogger {
    private endpoint: string;
    private buffer: any[];
    private flushInterval: number;
    private maxBufferSize: number;
    public onAlert?: (eventType: string, details: any) => void;

    constructor(config: SecurityLoggerConfig = {}) {
        this.endpoint = config.endpoint || '/api/security/log';
        this.buffer = [];
        this.flushInterval = config.flushInterval || 5000;
        this.maxBufferSize = config.maxBufferSize || 100;
        this.onAlert = config.onAlert;
        
        // Ensure it runs once
        if (typeof window !== 'undefined' && !(window as any).__securityLoggerInitialized) {
            this.startAutoFlush();
            this.hookConsole();
            (window as any).__securityLoggerInitialized = true;
        }
    }

    private startAutoFlush() {
        setInterval(() => this.flush(), this.flushInterval);
        
        // إرسال قبل إغلاق الصفحة
        window.addEventListener('beforeunload', () => this.flush());
    }

    private hookConsole() {
        // تسجيل الأخطاء غير المعالجة
        window.addEventListener('error', (event) => {
            this.log('javascript_error', {
                message: event.message,
                filename: event.filename,
                lineno: event.lineno,
                colno: event.colno,
                stack: event.error?.stack
            });
        });

        // تسجيل الوعود المرفوضة غير المعالجة
        window.addEventListener('unhandledrejection', (event) => {
            this.log('unhandled_promise', {
                reason: event.reason?.message || event.reason
            });
        });
    }

    log(eventType: string, details: any, severity: 'info' | 'warn' | 'error' | 'alert' = 'info') {
        // التحقق مما إذا كان التفاصيل كائن خطأ وتحويله ليكون قابلاً للتسلسل
        const processedDetails = details instanceof Error ? {
            message: details.message,
            stack: details.stack,
            name: details.name,
            ...details
        } : details;

        const entry = {
            timestamp: new Date().toISOString(),
            type: eventType,
            severity,
            details: processedDetails,
            sessionId: this.getSessionId(),
            userAgent: navigator.userAgent,
            url: window.location.href,
            referrer: document.referrer
        };

        this.buffer.push(entry);

        if (this.buffer.length >= this.maxBufferSize) {
            this.flush();
        }

        // إظهار في console في وضع التصحيح
        if ((window as any).DEBUG_MODE || import.meta.env.DEV) {
            const consoleMethod = severity === 'alert' || severity === 'error' ? 'error' : severity === 'warn' ? 'warn' : 'log';
            console[consoleMethod](`[Security] ${severity.toUpperCase()}: ${eventType}`, details);
        }
    }

    info(eventType: string, details: any = {}) {
        this.log(eventType, details, 'info');
    }

    warn(eventType: string, details: any = {}) {
        this.log(eventType, details, 'warn');
    }

    error(eventType: string, details: any = {}) {
        this.log(eventType, details, 'error');
    }

    alert(eventType: string, details: any) {
        this.log(eventType, details, 'alert');
        
        // إرسال فوري للتنبيهات الخطيرة
        this.flush();
        
        // يمكنك هنا: إظهار تنبيه للمستخدم، تسجيل خروج، إلخ
        if (typeof this.onAlert === 'function') {
            this.onAlert(eventType, details);
        }
    }

    async flush() {
        if (this.buffer.length === 0) return;

        const batch = [...this.buffer];
        this.buffer = [];

        try {
            await fetch(this.endpoint, {
                method: 'POST',
                headers: { 
                    'Content-Type': 'application/json',
                    'x-log-batch-id': crypto.randomUUID()
                },
                body: JSON.stringify({ events: batch }),
                keepalive: true // للسماح بالإرسال عند إغلاق الصفحة
            });
        } catch (error) {
            // إعادة المحاولة لاحقاً
            this.buffer.unshift(...batch);
            console.error('Failed to send security logs:', error);
        }
    }

    private getSessionId() {
        try {
            let sessionId = sessionStorage.getItem('security_session_id');
            if (!sessionId) {
                sessionId = crypto.randomUUID();
                sessionStorage.setItem('security_session_id', sessionId);
            }
            return sessionId;
        } catch (e) {
            return crypto.randomUUID();
        }
    }
}

