          width: { size: 100, type: WidthType.PERCENTAGE },
          borders: {
            top: { style: BorderStyle.NONE },
            bottom: { style: BorderStyle.NONE },
            left: { style: BorderStyle.NONE },
            right: { style: BorderStyle.NONE },
            insideHorizontal: { style: BorderStyle.NONE },
            insideVertical: { style: BorderStyle.NONE },
          },
          rows: [
            new TableRow({
              children: [
                new TableCell({
                  width: { size: 33, type: WidthType.PERCENTAGE },
                  children: [
                    new Paragraph({
                      alignment: isRtl ? AlignmentType.RIGHT : AlignmentType.LEFT,
                      bidirectional: isRtl,
                      children: [
                        new TextRun({
                          text: t('export.internalUseOnly'),
                          size: 20,
                          rightToLeft: isRtl,
                        }),
                      ],
                    }),
                  ],
                }),
                new TableCell({
                  width: { size: 34, type: WidthType.PERCENTAGE },
                  children: [
                    new Paragraph({
                      alignment: AlignmentType.CENTER,
                      bidirectional: isRtl,
                      children: [
                        new TextRun({
                          text: t('export.auditDepartment'),
                          size: 20,
                          rightToLeft: isRtl,
                        }),
                      ],
                    }),
                  ],
                }),
                new TableCell({
                  width: { size: 33, type: WidthType.PERCENTAGE },
                  children: [
                    new Paragraph({
                      alignment: isRtl ? AlignmentType.LEFT : AlignmentType.RIGHT,
                      bidirectional: isRtl,
                      children: [
                        new TextRun({
                          text: t('export.page') + ' ',
                          size: 20,
                          rightToLeft: isRtl,
                        }),
                        // Page numbers are complex in docx.js, using simple text for now
                        // In a real scenario, we'd use PageNumber field
                      ],
                    }),
                  ],
                }),
              ],
            }),
          ],
        }),
      ],
    });
  };

  const createHeading = (text: string, level: number = 1) => {
    return new Paragraph({
      text: text,
      heading: level === 1 ? HeadingLevel.HEADING_1 : HeadingLevel.HEADING_2,
      alignment: isRtl ? AlignmentType.RIGHT : AlignmentType.LEFT,
      bidirectional: isRtl,
      spacing: { before: 240, after: 120 },
    });
  };

  const createParagraph = (text: string, color: string = "000000", bold: boolean = false) => {
    return new Paragraph({
      alignment: isRtl ? AlignmentType.RIGHT : AlignmentType.LEFT,
      bidirectional: isRtl,
      spacing: { after: 120 },
      children: [
        new TextRun({
          text: text,
          size: 24, // 12pt
          color: color,
          bold: bold,
          rightToLeft: isRtl,
        }),
      ],
    });
  };

  const createTocTable = () => {
    const rows = [
      [t('export.tocSection'), t('export.tocPageNote')],
      [t('export.tocDocControl'), t('export.tocAutoUpdate')],
      [t('export.executiveSummary'), t('export.tocAutoUpdate')],
      [t('export.reportIntroduction'), t('export.tocAutoUpdate')],
      [t('export.tocPlanVsAchieved'), t('export.tocAutoUpdate')],
      [t('export.tocCompletedWork'), t('export.tocAutoUpdate')],
      [t('export.tocFindings'), t('export.tocAutoUpdate')],
      [t('export.tocRecommendations'), t('export.tocAutoUpdate')],
      [t('export.tocIssues'), t('export.tocAutoUpdate')],
      [t('export.tocNeeds'), t('export.tocAutoUpdate')],
      [t('export.tocPriorities'), t('export.tocAutoUpdate')],
      [t('export.tocConclusion'), t('export.tocAutoUpdate')],
      [t('export.tocSignatures'), t('export.tocAutoUpdate')],
    ];

    return new Table({
      width: { size: 100, type: WidthType.PERCENTAGE },
      rows: rows.map((row, index) => {
        return new TableRow({
          children: row.map((cellText, cellIndex) => {
            return new TableCell({
              width: { size: cellIndex === 0 ? 60 : 40, type: WidthType.PERCENTAGE },
              shading: index === 0 ? { fill: LIGHT_FILL, type: ShadingType.CLEAR, color: "auto" } : undefined,
              children: [
                new Paragraph({
                  alignment: isRtl ? AlignmentType.RIGHT : AlignmentType.LEFT,
                  bidirectional: isRtl,
                  children: [
                    new TextRun({
                      text: cellText,
                      bold: index === 0,
                      rightToLeft: isRtl,
                    }),
                  ],
                }),
              ],
            });
          }),
        });
      }),
    });
  };

  const doc = new Document({
    sections: [
      // Cover Page
      {
        properties: {},
        children: [
          new Paragraph({
            alignment: AlignmentType.CENTER,
            spacing: { before: 2000, after: 400 },
            children: [
              new TextRun({
                text: t('export.companyName'),
                bold: true,
                size: 48,
                color: PRIMARY_COLOR,
              }),
            ],
          }),
          new Paragraph({
            alignment: AlignmentType.CENTER,
            spacing: { after: 2000 },
            children: [
              new TextRun({
                text: t('export.quarterlyReport'),
                bold: true,
                size: 36,
              }),
            ],
          }),
          new Paragraph({
            children: [new PageBreak()],
          }),
        ],
      },
      // Main Content
      {
        properties: {},
        headers: { default: createHeader() },
        footers: { default: createFooter() },
        children: [
          createHeading(t('export.tableOfContents'), 1),
          createParagraph(t('export.tocDescription'), MUTED_COLOR),
          createTocTable(),
          new Paragraph({ children: [new PageBreak()] }),
          
          createHeading(t('export.executiveSummary'), 1),
          createParagraph(t('export.executiveSummaryContent')),
          new Paragraph({ children: [new PageBreak()] }),
          
          createHeading(t('export.reportIntroduction'), 1),
          createParagraph(t('export.reportIntroductionContent')),
          new Paragraph({ children: [new PageBreak()] }),
          
          createHeading(t('export.quarterlyPlanVsAchieved'), 1),
          createParagraph(t('export.quarterlyPlanContent')),
          new Paragraph({ children: [new PageBreak()] }),
          
          createHeading(t('export.completedEngagements'), 1),
          createParagraph(t('export.completedEngagementsContent')),
          new Paragraph({ children: [new PageBreak()] }),
          
          createHeading(t('export.materialFindings'), 1),
          createParagraph(t('export.materialFindingsContent')),
          new Paragraph({ children: [new PageBreak()] }),
          
          createHeading(t('export.previousRecommendations'), 1),
          createParagraph(t('export.previousRecommendationsContent')),
          new Paragraph({ children: [new PageBreak()] }),
          
          createHeading(t('export.auditIssues'), 1),
          createParagraph(t('export.auditIssuesContent')),
          new Paragraph({ children: [new PageBreak()] }),
          
          createHeading(t('export.needsAndSupport'), 1),
          createParagraph(t('export.needsAndSupportContent')),
          new Paragraph({ children: [new PageBreak()] }),
          
          createHeading(t('export.nextQuarterPriorities'), 1),
          createParagraph(t('export.nextQuarterPrioritiesContent')),
          new Paragraph({ children: [new PageBreak()] }),
          
          createHeading(t('export.conclusion'), 1),
          createParagraph(t('export.conclusionContent')),
          new Paragraph({ children: [new PageBreak()] }),
          
          createHeading(t('export.signaturesAndApproval'), 1),
          createParagraph(t('export.signaturesContent')),
        ],
      },
    ],
  });

  const blob = await Packer.toBlob(doc);
  saveAs(blob, `Quarterly_Report_${new Date().getTime()}.docx`);
};

/**
 * Centralized frontend logger.
 * Wraps console methods to provide a single point of control for:
 * - Suppressing logs in production
 * - Future integration with error reporting services (Sentry, etc.)
 * - Consistent formatting
 */

const isDev = import.meta.env?.DEV ?? process.env.NODE_ENV !== 'production';

export const logger = {
  error(message: string, ...args: unknown[]) {
    if (isDev) {
      console.error(`[ERROR] ${message}`, ...args);
    }
    // In production, errors are already reported to /api/system-errors via the API interceptor.
    // This logger suppresses noisy console output in production builds.
  },

  warn(message: string, ...args: unknown[]) {
    if (isDev) {
      console.warn(`[WARN] ${message}`, ...args);
    }
  },

  info(message: string, ...args: unknown[]) {
    if (isDev) {
      console.info(`[INFO] ${message}`, ...args);
    }
  },
};

export default logger;

export const getTranslatedNotificationMessage = (desc: string, t: any, language: string) => {
  if (!desc) return '';
  
  // Try to parse as JSON translation key (new format from server)
  try {
    const parsed = JSON.parse(desc);
    if (parsed && parsed.key) {
      return t(parsed.key, parsed.params || {});
    }
  } catch {
    // Not JSON - continue with legacy pattern matching (backward compatibility)
  }
  
  // Check for "New record in X"
  const newRecordMatch = desc.match(/^New record in (.*)$/);
  if (newRecordMatch) {
    const table = newRecordMatch[1];
    let moduleKey = table;
    if (table === 'risk_register') moduleKey = 'RiskRegister';
    else if (table === 'audit_plans') moduleKey = 'AuditPlans';
    else if (table === 'audit_tasks') moduleKey = 'AuditTasks';
    else if (table === 'fraud_log') moduleKey = 'FraudLog';
    else if (table === 'audit_programs') moduleKey = 'AuditProgramLibrary';
    else if (table === 'audit_procedures') moduleKey = 'AuditProgramLibrary';
    else if (table === 'audit_evidence') moduleKey = 'AuditTasks';
    else if (table === 'compliance_items' || table === 'central_bank_instructions' || table === 'law_bank' || table === 'internal_policies') moduleKey = 'ComplianceMatrix';
    else if (table === 'audit_reports') moduleKey = 'AuditReports';
    
    const translatedModule = t(`modules.${moduleKey}`, moduleKey);
    return t('notifications.newRecord', { module: translatedModule });
  }
  
  // Other common backend strings
  if (desc === 'New audit finding created') {
    return t('notifications.newAuditFinding');
  }

  if (desc.includes('requested access to Fraud Log')) {
    const user = desc.split(' ')[0];
    return t('notifications.fraudAccessRequested', { user });
  }
  
  if (desc === 'Your access request to Fraud Log has been approved.') {
    return t('notifications.fraudAccessApproved');
  }
  
  if (desc.startsWith('Your access request to Fraud Log was rejected:')) {
    const reason = desc.split(': ')[1] || '';
    return t('notifications.fraudAccessRejected', { reason });
  }

  // Security and Password Reset Alerts
  if (desc.includes('Password reset attempt for non-existent or inactive user:')) {
    const reason = desc.split(': ')[1] || '';
    return t('notifications.passwordResetInvalidUser', { reason });
  }

  if (desc.includes('Password reset request submitted for')) {
    const args = desc.split('for ');
    const userPart = args.length > 1 ? args[1] : '';
    return t('notifications.passwordResetSubmitted', { user: userPart });
  }

  return desc;
};

export const getTranslatedNotificationModule = (module: string, t: any) => {
  if (!module) return module;
  const lower = module.toLowerCase();
  
  let moduleKey: string | null = null;
  if (lower === 'risk-register' || lower === 'risk_register') moduleKey = 'RiskRegister';
  else if (lower === 'audit-plans' || lower === 'audit_plans') moduleKey = 'AuditPlans';
  else if (lower === 'audit-tasks' || lower === 'audit_tasks') moduleKey = 'AuditTasks';
  else if (lower === 'fraud-log' || lower === 'fraud_log') moduleKey = 'FraudLog';
  else if (lower === 'audit-findings') moduleKey = 'AuditReports';
  else if (lower === 'audit-evidence') moduleKey = 'AuditTasks';
  else if (lower === 'compliance' || lower === 'compliance-matrix' || lower === 'central-bank-instructions' || lower === 'law-bank' || lower === 'policies') moduleKey = 'ComplianceMatrix';
  
  if (moduleKey) {
    return t(`modules.${moduleKey}`, moduleKey);
  }
  
  return module;
};

import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import api from '../services/api';
import handlebars from 'handlebars';
import html2canvas from 'html2canvas';
import { TAHOMA_FONT_BASE64 } from '../assets/fonts/tahoma-base64';
import i18n from '../i18n';

const t = i18n.t.bind(i18n);

export const generateDynamicPdf = async (
  templateContent: string,
  data: any,
  fileName: string
) => {
  try {
    // 1. Compile template
    const template = handlebars.compile(templateContent);
    const htmlString = template(data);

    // 2. Create a temporary container
    const container = document.createElement('div');
    container.innerHTML = htmlString;
    container.style.position = 'absolute';
    container.style.top = '-9999px';
    container.style.left = '-9999px';
    container.style.width = '800px'; // A4 width approx in pixels
    container.style.background = 'white';
    document.body.appendChild(container);

    // 3. Render to canvas
    const canvas = await html2canvas(container, {
      scale: 2,
      useCORS: true,
      logging: false,
    });

    // 4. Create PDF
    const doc = new jsPDF({
      orientation: 'portrait',
      unit: 'pt',
      format: 'a4'
    });

    const imgData = canvas.toDataURL('image/png');
    const pdfWidth = doc.internal.pageSize.getWidth();
    const pdfHeight = (canvas.height * pdfWidth) / canvas.width;

    // Handle pagination roughly
    let heightLeft = pdfHeight;
    let position = 0;
    const pageHeight = doc.internal.pageSize.getHeight();

    doc.addImage(imgData, 'PNG', 0, position, pdfWidth, pdfHeight);
    heightLeft -= pageHeight;

    while (heightLeft >= 0) {
      position = heightLeft - pdfHeight;
      doc.addPage();
      doc.addImage(imgData, 'PNG', 0, position, pdfWidth, pdfHeight);
      heightLeft -= pageHeight;
    }

    doc.save(`${fileName}.pdf`);

    // Clean up
    document.body.removeChild(container);
  } catch (err) {
    console.error('Error generating dynamic PDF', err);
    throw err;
  }
};

export const fetchPdfSettings = async (token: string) => {
  try {
    const res = await api.get('/pdf-settings', {
      headers: { Authorization: `Bearer ${token}` }
    });
    if (res.data) {
      return res.data;
    }
  } catch (err) {
    console.error('Error fetching PDF settings:', err);
  }
  return null;
};

export interface PdfSection {
  type: 'text' | 'table';
  title?: string;
  content?: string;
  columns?: any[];
  data?: any[];
}

// Use locally embedded font (no internet required)
let cachedArabicFont: string | null = TAHOMA_FONT_BASE64;

export const generatePdf = async (
  title: string, 
  sections: PdfSection[],
  token: string,
  language: 'ar' | 'en',
  templateType?: string,
  templateData?: any
) => {
  if (templateType && templateData) {
    try {
      const res = await api.get(`/pdf-templates/active?type=${encodeURIComponent(templateType)}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      if (res.data && res.data.content) {
        await generateDynamicPdf(res.data.content, templateData, title);
        return;
      }
    } catch (e) {
      console.warn(`No active template found for ${templateType}, falling back to legacy export.`);
    }
  }
  const settings = await fetchPdfSettings(token) || {
    arabic_font_name: 'Cairo',
    arabic_font_size: 12,
    heading_font_size: 16,
    subheading_font_size: 14,
    table_font_size: 10,
    rtl_enabled: language === 'ar' ? 1 : 0,
    margin_top: 40,
    margin_right: 40,
    margin_bottom: 40,
    margin_left: 40,
    header_template: '',
    footer_template: '',
    logo_position: 'right',
    show_page_number: 1
  };

  const doc = new jsPDF({
    orientation: 'portrait',
    unit: 'pt',
    format: 'a4'
  });

  const isRTL = settings.rtl_enabled === 1 || language === 'ar';
  
  if (isRTL) {
    try {
      doc.addFileToVFS('Tahoma.ttf', cachedArabicFont);
      doc.addFont('Tahoma.ttf', 'Tahoma', 'normal');
      doc.setFont('Tahoma');
      settings.arabic_font_name = 'Tahoma';
    } catch (e) {
      console.error('Failed to load Arabic font', e);
      doc.setFont('helvetica');
      settings.arabic_font_name = 'helvetica';
    }
  } else {
    doc.setFont('helvetica');
  }

  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  
  let currentY = settings.margin_top;

  // Header
  if (settings.header_template) {
    doc.setFontSize(settings.subheading_font_size);
    doc.text(settings.header_template, isRTL ? pageWidth - settings.margin_right : settings.margin_left, currentY, { align: isRTL ? 'right' : 'left' });
    currentY += 30;
  }

  // Title
  doc.setFontSize(settings.heading_font_size);
  doc.text(title, pageWidth / 2, currentY, { align: 'center' });
  currentY += 40;

  for (const section of sections) {
    if (section.title) {
      doc.setFontSize(settings.subheading_font_size);
      doc.text(section.title, isRTL ? pageWidth - settings.margin_right : settings.margin_left, currentY, { align: isRTL ? 'right' : 'left' });
      currentY += 20;
    }

    if (section.type === 'text' && section.content) {
      doc.setFontSize(settings.arabic_font_size);
      const splitText = doc.splitTextToSize(section.content, pageWidth - settings.margin_left - settings.margin_right);
      doc.text(splitText, isRTL ? pageWidth - settings.margin_right : settings.margin_left, currentY, { align: isRTL ? 'right' : 'left' });
      currentY += (splitText.length * (settings.arabic_font_size + 4)) + 20;
    } else if (section.type === 'table' && section.columns && section.columns.length > 0 && section.data) {
      const tableBody = section.data.length > 0 
        ? section.data.map(row => section.columns!.map(c => {
            const val = row[c.dataKey];
            return val !== undefined && val !== null ? String(val) : '';
          }))
        : [[{ content: t('export.noData'), colSpan: section.columns.length, styles: { halign: 'center' as const } }]];

      autoTable(doc, {
        startY: currentY,
        head: [section.columns.map(c => c.header)],
        body: tableBody,
        styles: {
          font: isRTL ? settings.arabic_font_name : 'helvetica',
          fontSize: settings.table_font_size,
          halign: isRTL ? 'right' : 'left',
        },
        headStyles: {
          fillColor: [41, 128, 185],
          textColor: 255,
          fontStyle: 'bold',
          halign: 'center'
        },
        margin: { 
          top: settings.margin_top, 
          right: settings.margin_right, 
          bottom: settings.margin_bottom, 
          left: settings.margin_left 
        },
        didDrawPage: (data: any) => {
          // Footer is drawn later for all pages
        }
      });
      currentY = (doc as any).lastAutoTable.finalY + 30;
    }
  }

  // Draw footer on all pages
  const pageCount = (doc as any).internal.getNumberOfPages();
  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    if (settings.footer_template || settings.show_page_number === 1) {
      doc.setFontSize(10);
      const footerText = `${settings.footer_template} ${settings.show_page_number === 1 ? t('export.pageOf', { current: i, total: pageCount }) : ''}`;
      doc.text(footerText, pageWidth / 2, pageHeight - settings.margin_bottom / 2, { align: 'center' });
    }
  }

  doc.save(`${title}.pdf`);
};
